import scala.io.StdIn
import scala.annotation.tailrec
import scala.collection.mutable.HashMap

object Main extends App {
  val Array(h, w) = StdIn.readLine.split(" ").map(_.toInt)
  val table = Iterator.continually(StdIn.readLine)
    .take(h)
    .map(_.map(_ == '#').toArray)
    .toArray

  @inline
  def flat(i:Int, j:Int):Int = i * w + j

  val ans = {
    val dx = Array(0, 1, 0, -1)
    val dy = Array(-1, 0, 1, 0)
    val uft = new UnionFindTree(flat(h, w))

    for{
      i <- 0 until h
      j <- 0 until w
    } {
        val ij = flat(i,j)
        (0 until 4).foreach(k => {
          val y = i + dy(k)
          val x = j + dx(k)
          if(0 <= y && y < h && 0 <= x && x < w &&
              table(i)(j) != table(y)(x) ) {
            uft.unite(ij, flat(y,x))
          }
        })
    }
    uft.map.values./:(0L)((acc,e) => {
      acc + e._1.toLong * e._2.toLong
    })
  }

  println(ans)

  class UnionFindTree(n:Int) {
    private val par  = Array.range(0, n)
    private val rank = Array.fill(n)(1)
    val map = HashMap.empty[Int,(Int,Int)]

    def root(x:Int):Int = {
      if(par(x) == x) x
      else { par(x) = root(par(x)); par(x) }
    }

    def isSame(x:Int, y:Int):Boolean = root(x) == root(y)

    def unite(x:Int, y:Int):Unit = {
      val rx = root(x)
      val ry = root(y)
      if(rx == ry) return

      if(!map.contains(ry)) map(ry) = if(table(ry/w)(ry%w)) (1,0) else (0,1)
      if(!map.contains(rx)) map(rx) = if(table(rx/w)(rx%w)) (1,0) else (0,1)
      val ryv = map(ry)
      val rxv = map(rx)

      if(rank(rx) < rank(ry)) {
        par(rx) = ry
        map(ry) = (ryv._1 + rxv._1, ryv._2 + rxv._2)
        map -= rx
      }
      else {
        par(ry) = rx
        if(rank(rx) == rank(ry)) rank(rx) += 1
        map(rx) = (rxv._1 + ryv._1, rxv._2 + ryv._2)
        map -= ry
      }
    }
  }
}

object Main extends App {

  val (h, w) = readLine.split(" ").map(_.toInt) match {
    case Array(h, w) => (h, w)
  }

  case class Position(i: Int, j: Int)

  case class Point(position: Position,
                   isBlack: Boolean,
                   nexts: Seq[Position] = Nil)

  case class Field(charArrArr: Array[Array[Char]]) {
    val points: Seq[Point] = charArrArr.zipWithIndex
      .filterNot(t => t._2 == 0 || t._2 == h + 1)
      .flatMap {
        case (charArr, i) =>
          charArr.zipWithIndex
            .filterNot(t => t._2 == 0 || t._2 == w + 1)
            .flatMap {
              case (c, j) =>
                def nexts(isBlack: Boolean): Seq[Position] =
                  Seq((i, j - 1), (i, j + 1), (i - 1, j), (i + 1, j))
                    .flatMap(p =>
                      charArrArr(p._1)(p._2) match {
                        case '#' if !isBlack => Some(Position(p._1, p._2))
                        case '.' if isBlack  => Some(Position(p._1, p._2))
                        case _               => None
                    })

                c match {
                  case '#' => Some(Point(Position(i, j), true, nexts(true)))
                  case '.' => Some(Point(Position(i, j), false, nexts(false)))
                  case _   => None
                }
            }
      }

    def find(p: Position): Point = points.find(_.position == p).get

    def nextWps(bp: Point,
                prevWps: Seq[Point] = Seq(),
                prevBps: Seq[Point] = Seq()): Seq[Point] =
      bp.nexts
        .filterNot(wpPositions => prevWps.exists(_.position == wpPositions))
        .map(find) match {
        case Nil => Seq()
        case wps =>
          wps ++ wps.flatMap(wp => nextBps(wp, prevWps, bp +: prevBps))
      }

    def nextBps(wp: Point,
                prevWps: Seq[Point] = Seq(),
                prevBps: Seq[Point] = Seq()): Seq[Point] =
      wp.nexts
        .filterNot(bpPositions => prevBps.exists(_.position == bpPositions))
        .map(find) match {
        case Nil => Seq()
        case bps => bps.flatMap(bp => nextWps(bp, wp +: prevWps, prevBps))
      }

  }

  val charArrList =
    List(Array.fill(w + 2)('x')) ++ (1 to h)
      .map(_ => ('x' + readLine + 'x').toCharArray)
      .toList ++ List(Array.fill(w + 2)('x'))

  val field = Field(charArrList.toArray)
  val count = field.points
    .filter(_.isBlack)
    .map(bp => field.nextWps(bp).map(_.position).distinct.length)
    .sum
  println(count)

}

import java.io._
import java.util.StringTokenizer
import scala.util.control.Breaks.{breakable,break}

object Main extends App {
  val in = new InputReader(System.in)
  val pw = new PrintWriter(System.out)

  val H, W = in.next().toInt
  val S = new Array[String](H+1)
  for (i <- 1 to H)
    S(i) = "N" + in.next()


  //
  type Coord = (Int, Int)

  val dp = Array.ofDim[Boolean](H+1, W+1)

  def inField(p: Coord): Boolean = {
    val (x, y) = p
    1 <= x && x <= W && 1 <= y && y <= H
  }

  def mk4dir(p: Coord): List[Coord] = {
    val (x, y) = p
    List((x-1, y), (x+1, y), (x, y-1), (x, y+1)).filter(inField)
  }

  def calc(p: Coord): (Int, Int) = {
    var B = 0
    var W = 0

    def dfs(p: Coord, pre: Char): Unit = {
      val (x, y) = p

      if (dp(y)(x))
        ()
      else {
        if (S(y)(x) != pre) {
          dp(y)(x) = true
          if (S(y)(x) == '#')
            B += 1
          else
            W += 1

          mk4dir(p).foreach(dfs(_, S(y)(x)))
        }
      }
    }

    dfs(p, 'N')
    (B, W)
  }

  var ans = 0L
  for (y <- 1 to H)
    for(x <- 1 to W) {
      if (!dp(y)(x) && S(y)(x) == '#') {
        val (b, w) = calc((x, y))

        ans += b * w
      }
    }

  println(ans)
}


class InputReader(stream: InputStream) {
  private val reader = new BufferedReader(new InputStreamReader(stream))
  private var tokenizer: StringTokenizer = new StringTokenizer(reader.readLine())
  def next(): String = {
    while (!tokenizer.hasMoreTokens()) {
      tokenizer = new StringTokenizer(reader.readLine())
    }
    tokenizer.nextToken()
  }
}

