  class UnionFindTree(isBlack: Boolean){
    private var mBlackCount: Int = if (isBlack) 1 else 0
    private var mParent: Option[UnionFindTree] = None
    private var mSize: Int = 1
    def blackCount: Int = parent.mBlackCount
    def whiteCount: Int = parent.mSize - parent.mBlackCount
    private def parent: UnionFindTree = {
      mParent.map{_.parent} match {
        case None ⇒ this
        case c@Some(p) ⇒
          mParent = c
          p
      }
    }
    def isSameUnion(that: UnionFindTree): Boolean = {
      parent == that.parent
    }
    def merge(that: UnionFindTree): Unit = {
      if (!isSameUnion(that)){
        val p = parent
        val tp = that.parent
        if (p.mSize > tp.mSize){
          tp.mParent = Some(p)
          p.mSize += tp.mSize
          p.mBlackCount += tp.mBlackCount
        }else {
          p.mParent = Some(tp)
          tp.mSize += p.mSize
          tp.mBlackCount += p.mBlackCount
        }
      }
    }
  }
  implicit class Extension[T](value :T){
    @inline
    def let[A](@inline func: T ⇒ A): A = func(value)
    @inline
    def also(@inline func: T ⇒ Unit): T = {func(value); value}
  }
}

