    private val rank = Array.fill(n)(1)
    val set = HashSet.empty[Int]

    def root(x:Int):Int = {
      if(par(x) == x) x
      else { par(x) = root(par(x)); par(x) }
    }

    def same(x:Int, y:Int):Boolean = root(x) == root(y)

    def unite(x:Int, y:Int):Unit = {
      val rx = root(x)
      val ry = root(y)
      if(rx == ry) return

      if(rank(rx) < rank(ry)) {
        par(rx) = ry
        set += ry
        if(set.contains(rx)) set -= rx
      }
      else {
        par(ry) = rx
        if(rank(rx) == rank(ry)) rank(rx) += 1
        set += rx
        if(set.contains(ry)) set -= ry
      }
    }
  }
