int memo[402][402];
char s[402][402];
int rec(int t, int y){
  int res;
  if(memo[t][y] != -1) return memo[t][y];
  if(t<1 || y<1) return memo[t][y] = 0;

  if(s[t-1][y-1] == '#'){

      if(s[t-1][y-2] == '.'){
         res = rec(t-1,y) + rec(t,y-1) + 1; 
          }else if(s[t-2][y-1] == '.'  ){
            res = rec(t-1,y) + rec(t,y-1);
            if(y==2) res++;
          }else{
            res = max(rec(t-1,y),rec(t,y-1));
          }

  }else if(s[t-1][y-1] == '.'){
      if(s[t-1][y-2] =='#' || s[t-2][y-1] == '#'){
        res = rec(t, y-1) + rec(t-1,y) + 1;

        }else if(s[t-2][y-1] == '#' ){
            res = rec(t-1,y) + rec(t,y-1);
            if(y==2) res++;
          }else{
            res = max(rec(t-1,y),rec(t,y-1));
          }

    }
    return memo[t][y] = res;
}

