int main(){
  int h,w;
  cin>>h>>w;

  vector<string> p(h);
  rep(i,h){
    cin>>p[i];
  }

  UF uf(h*w);

  rep(i,h){
    rep(j,w-1){
      if(p[i][j]!=p[i][j+1]) uf.unite(i*w+j,i*w+j+1);
    }
  }

  rep(j,w){
    rep(i,h-1){
      if(p[i][j]!=p[i+1][j]) uf.unite(i*w+j,(i+1)*w+j);
    }
  }

  map<ll,pair<ll,ll>> ans;
  rep(i,h){
    rep(j,w){
      ll x=uf.root(i*w+j);
      bool b=false;
      if(p[i][j]=='#') b=true;
      if(ans.count(x)){
        if(b) ans.at(x).fi++;
        else ans.at(x).se++;
      }
      else {
        if(b) ans[x]={1,0};
        else ans[x]={0,1};
      }
    }
  }

  ll answer=0;
  for(auto x : ans){
    answer+=x.se.fi*x.se.se;
  }


  cout << answer << endl;
}

