            dps(i+1,j);
        }
        if (s[i][j-1] == '.' && !t[i][j-1]) {
            dps(i,j-1);
        }
        if (s[i][j+1] == '.' && !t[i][j+1]) {
            dps(i,j+1);
        }
    }
    if (s[i][j] == '.') {
        if (s[i-1][j] == '#' && !t[i-1][j]) {
            dps(i-1,j);
        }
        if (s[i+1][j] == '#' && !t[i+1][j]) {
            dps(i+1,j);
        }
        if (s[i][j-1] == '#' && !t[i][j-1]) {
            dps(i,j-1);
        }
        if (s[i][j+1] == '#' && !t[i][j+1]) {
            dps(i,j+1);
        }
    }
}

