bool col(char t){
    if(t == '#'){return false;}
    else{return true;}
}

void dfs(ll &h, ll &i, ll H, ll W, int y, int x, vector<vector<char>> map, vector<vector<bool>> &ald){
    if((y<0||y>=H)||(x<0||x>=W)){return;}
    if(ald[y][x] == true){return;}
    ald[y][x] = true;
    bool p = col(map[y][x]);
    if(p == true){h++;}
    else{i++;}
    if(y != 0){
    if(col(map[y-1][x]) != p&&!(y-1<0||y-1>=H)){dfs(h,i, H, W, y-1, x, map, ald);}
    }
    if(x != 0){
    if(col(map[y][x-1]) != p&&!(x-1<0||x-1>=W)){dfs(h,i, H, W, y, x-1, map, ald);}
    }
    if(y != H-1){
    if(col(map[y+1][x]) != p&&!(y+1<0||y+1>=H)){dfs(h,i, H, W, y+1, x, map, ald);}
    }
    if(x != W-1){
    if(col(map[y][x+1]) != p&&!(x+1<0||x+1>=W)){dfs(h, i, H, W, y, x+1, map, ald);}
    }
}

int main(){
    ll H, W;
    cin >> H >> W;
    ll count = 0;
    ll x = 0;
    vector<vector<char>> map(H, vector<char>(W));
    for(int i=0; i<H; i++){
      for(int j=0; j<W; j++){
          cin >> map[i][j];
      }
    }
    vector<vector<bool>> ald(H, vector<bool>(W,false));
    for(int i=0; i<H; i++){
      for(int j=0; j<W; j++){

          if(ald[i][j] == false){

          ll h = 0;
          ll g = 0;
          dfs(h,g,H,W,i,j,map,ald);
          x++;
          count += h*g;
          }
      }     
    }

    cout << count;
}

