int dx[4] = {0, 1, 0, -1};
int dy[4] = {1, 0, -1, 0};

//the end of library zone

int H, W;

int ans;

vector<string> S;

bool walked[1000][1000];

bool notsolved(int h, int w, int x, int y){
	if(h == x){
		return w < y;
	}
	else{
		return h < x;
	}
}

void solve(int h, int w){
	REP(n, H){
		REP(m, W){
			walked[n][m] = false;
		}
	}

	queue<PII> q;
	q.push(make_pair(h, w));
	walked[h][w] = true;
	char f = S[h][w];

	while(!q.empty()){
		PII now = q.front();
		char n = S[now.first][now.second];
		q.pop();

		REP(i, 4){
			int x, y;
			x = now.first + dx[i];
			y = now.second + dy[i];
			if((0 <= h) && (h < H) && (0 <= w) && (w < W) && (!walked[h][w])){
				if(n != S[x][y]){
					q.push(make_pair(x, y));
					if(notsolved(h, w, x, y) && f != S[x][y]){
						ans++;
					}
					walked[x][y] = true;
				}
			}
		}
	}
}

signed main(){
