struct UnionFind {
    vector<i64> p_;

    explicit UnionFind(i64 n) : p_(n,-1) {}

    i64 root(i64 x) {
        if(p_[x] < 0) return x;
        return p_[x] = root(p_[x]);
    }

    void unite(i64 x, i64 y) {
        i64 rx = root(x);
        i64 ry = root(y);
        if(rx == ry) return;

        i64 kx = -p_[rx];
        i64 ky = -p_[ry];
        if(kx < ky) swap(rx,ry);
        p_[rx] = -(kx+ky);
        p_[ry] = rx;
    }
};

void solve() {
    i64 H = RD();
    i64 W = RD();
    auto M = RD_VEC<string>(H);

    auto vertex = [W](i64 y, i64 x) { return W*y + x; };

    UnionFind uf(H*W);
    REP(y, H) REP(x, W-1) {
        if(M[y][x] != M[y][x+1])
            uf.unite(vertex(y,x), vertex(y,x+1));
    }
    REP(y, H-1) REP(x, W) {
        if(M[y][x] != M[y+1][x])
            uf.unite(vertex(y,x), vertex(y+1,x));
    }

    vector<pair<i64,i64>> cnts(H*W);
    REP(y, H) REP(x, W) {
        char c = M[y][x];
        i64 r = uf.root(vertex(y,x));
        if(c == '.')
            ++cnts[r].first;
        else
            ++cnts[r].second;
    }
    DBG(cnts);

    i64 ans = 0;
    for(const auto& p : cnts) {
        i64 a,b; tie(a,b) = p;
        ans += a*b;
    }

    PRINTLN(ans);
}

signed main() {


    solve();

    return 0;
}

