// Union-Find木
// 初期化 UF(N); Nは要素数
// 結合 unite(x,y); 同じ集合か判定 same(x,y);
// 集合の数 count
struct UF{
  vector<int> par,sizes;
  vi black,white;
  int cnt;
  UF(int N) : par(N),sizes(N, 1),cnt(N),black(N,0),white(N,0)
  { for(int i=0; i<N; i++) par[i]=i; }

  int find(int x){ return par[x]==x ? x : par[x] = find(par[x]); }

  bool same(int x,int y){ return find(x) == find(y); }

  int size(int x){ return sizes[find(x)]; }


  void unite(int x, int y){
    x = find(x); y = find(y);
    if(x == y) return;
    if(sizes[x] < sizes[y]) swap(x,y);
    par[y] = x;
    sizes[x] += sizes[y];
    black[x] += black[y];
    white[x] += white[y];
    cnt--;
  }

  int count() const{return cnt;}
};

void solve(){
  ini(H , W);
  vs g(H); in(g);
  UF uf(H * W);
  auto idx=[&](int h,int w){return h * W + w;};
  rep(i , H) rep(j , W){
    if(g[i][j] == '.') uf.white[idx(i,j)]++;
    else uf.black[idx(i,j)]++;
  }
  rep(i , H) rep(j , W){
    if(i != H - 1){
      if(g[i][j] != g[i + 1][j])
        uf.unite(idx(i , j) , idx(i + 1 , j));
    }
    if(j != W - 1){
      if(g[i][j] != g[i][j + 1]){
        uf.unite(idx(i , j) , idx(i , j + 1));
      }
    }
  }
  ll ans = 0;
  vi used(H * W , 0);
  rep(i , H * W){
    if(used[uf.find(i)]) continue;
    int par = uf.find(i);
    ans += 1LL * uf.black[par] * uf.white[par];
    used[uf.find(i)] = 1;
  }
  out(ans);

}

