using namespace std;

int main() {
	int H, W;
	cin >> H >> W;
	vector<vector<char>> Map(H, vector<char>(W));
	for (int i = 0; i < H; i++) for (int j = 0; j < W; j++) cin >> Map[i][j];
	int now = 0, ans = 0;
	while (now < H * W) {
		int black = 0, white = 0;
		queue<pair<int, char>> Q;
		Q.push({ now,  (Map[now / W][now % W] == '#' ? '.' : '#') });
		while (!Q.empty()) {
			auto p = Q.front();
			int y = p.first / W, x = p.first % W;
			char before = p.second;
			Q.pop();
			if (Map[y][x] == 'x' || Map[y][x] == before) continue;
			(Map[y][x] == '.' ? white : black)++;
			before = Map[y][x];
			Map[y][x] = 'x';
			if (y > 0 && Map[y - 1][x] != 'x') Q.push({ y * W + x - W, before });
			if (y < H - 1 && Map[y + 1][x] != 'x') Q.push({ y * W + x + W, before });
			if (x > 0 && Map[y][x - 1] != 'x') Q.push({ y * W + x - 1, before });
			if (x < W - 1 && Map[y][x + 1] != 'x') Q.push({ y * W + x + 1, before });
		}
		ans += black * white;
		while (now < H * W && Map[now / W][now % W] == 'x') now++;
	}
	cout << ans << endl;
}

