		rep(j,W){
			if(i!=H){
				if(S[i][j]=='#'&&S[i+1][j]=='.'){
					uf.unite(i*W+j,(i+1)*H+j);
				}
				else if(S[i][j]=='.'&&S[i+1][j]=='#'){
					uf.unite(i*W+j,(i+1)*H+j);
				}
			}
			if(j!=W){
				if(S[i][j]=='#'&&S[i][j+1]=='.'){
					uf.unite(i*W+j,i*W+j+1);
				}
				else if(S[i][j]=='.'&&S[i][j+1]=='#'){
					uf.unite(i*W+j,i*W+j+1);
				}
			}
		}
	}
	rep(i,H){
		rep(j,W){
			if(S[i][j]=='#'){
				bnum[uf.root(i*W+j)]++;
			}
			else{
				wnum[uf.root(i*W+j)]++;
			}
		}
	}
	rep(i,H){
		rep(j,W){
			if(uf.root(i*W+j)==i*W+j){
