      while (q.size()) {
        pair<int, int> p = q.front(); q.pop();
        for (int d = 0; d < 4; d++) {
          pair<int, int> np = p;
          np.first += dy[d]; np.second += dx[d];
          if (!(0 <= np.first && np.first < H && 0 <= np.second && np.second < W)) {
            continue;
          }
          if (vis[np.first][np.second] || s[np.first][np.second] != s[i][j]) continue;
          vis[np.first][np.second] = true;
          tmp[(np.first + np.second) % 2]++;
          q.push(np);
        }
      }
      ans += tmp[0] * tmp[1];
    }
  }
  printf("%d\n", ans);

  return 0;
}

