using namespace std;

static int h;
static int w;

std::pair<int, int> paint(boost::multi_array<int, 2>& ss, int y, int x) {
  auto ret = std::pair<int, int>(0, 0);
  int const currentColor = ss[y][x];
  assert(currentColor == 0 || currentColor == 1);
  ss[y][x] = -1;
  if (currentColor == 0) {
    ret.first++;
  } else {
    ret.second++;
  }
  int const alternativeColor = 1 - currentColor;
  if (x < w - 1 && ss[y][x + 1] == alternativeColor) {
    auto painted = paint(ss, y, x + 1);
    ret.first += painted.first;
    ret.second += painted.second;
  }
  if (y < h - 1 && ss[y + 1][x] == alternativeColor) {
    auto painted = paint(ss, y + 1, x);
    ret.first += painted.first;
    ret.second += painted.second;
  }
  if (x > 0 && ss[y][x - 1] == alternativeColor) {
    auto painted = paint(ss, y, x - 1);
    ret.first += painted.first;
    ret.second += painted.second;
  }
  if (y > 0 && ss[y - 1][x] == alternativeColor) {
    auto painted = paint(ss, y - 1, x);
    ret.first += painted.first;
    ret.second += painted.second;
  }
  return ret;
}

int solve(boost::multi_array<int, 2>& ss) {
  int ret = 0;
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (ss[i][j] < 0) {
        continue;
      }
      auto painted = paint(ss, i, j);
      ret += painted.first * painted.second;
    }
  }
  return ret;
}

int main() {
  std::cin.tie(nullptr);
  std::ios::sync_with_stdio(false);
  std::cin >> h;
  std::cin >> w;
  boost::multi_array<int, 2> ss(boost::extents[h][w]);
  for (int i = 0; i < h; i++) {
    std::string s;
    std::cin >> s;
    for (int j = 0; j < w; j++) {
      ss[i][j] = static_cast<int>(s[j] == '#');
    }
  }
  auto const res = solve(ss);
  std::cout << res << std::endl;
  return 0;
}

