void dfs( int r , int c ){
    if( Visited[r][c] == true ) return;
    Visited[r][c] = true;
    int next;
    if( Array[r][c] == 0 ){ 
        ++black;
        next = 1;
    }
    else{ 
        ++white;
        next = 0;
    }

    if( r > 1 && Visited[r - 1][c] == false && Array[r - 1][c] == next ) dfs( r - 1 , c );
    if( r < h && Visited[r + 1][c] == false && Array[r + 1][c] == next ) dfs( r + 1 , c );
    if( c > 1 && Visited[r][c - 1] == false && Array[r][c - 1] == next ) dfs( r , c - 1 );
    if( c < w && Visited[r][c + 1] == false && Array[r][c + 1] == next ) dfs( r , c + 1 );
}

