        if(s[i][j] != s[i][j-1]) {
          int p = findp(parent,i*len+j);
          parent[i*len+j] = parent[p] = findp(parent,(i*len + j - 1));
        }
      }
    }
  }
  rep(i,0,n) {
    rep(j,0,len) {
      int p = findp(parent,i*len + j);
      if(s[i][j] == '#') blacks[p]++;
      else whites[p]++;
    }
  }
  long ways = 0;
  rep(i,0,n) {
    rep(j,0,len) {
      ways += (long)(whites[i*len + j] * blacks[parent[i*len+j]]);
    }
  }
  cout << ways << endl;
  return 0;
}

