#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {

	bool F[402][402] = {};
	bool S[402][402] = {};

	void Solve() {
		UL H, W; cin >> H >> W;
		rep(y, H) {
			rep(x, W) {
				char c; cin >> c;
				S[x + 1][y + 1] = (c == '#');
			}
		}
		rep(x, W + 2) F[x][0] = F[x][H + 1] = true;
		rep(y, H + 2) F[0][y] = F[W + 1][y] = true;
		ULL ans = 0;
		rep(sy, H) rep(sx, W) {
			if (F[sx + 1][sy + 1]) continue;
			ULL Black = 0, White = 0;
			queue<pair<UL, UL>> Q; Q.push({ sx + 1, sy + 1 });
			while (Q.size()) {
				UL x = Q.front().first, y = Q.front().second;
				Q.pop();
				if (F[x][y]) continue;
				F[x][y] = true;
				(S[x][y] ? Black : White)++;
				if (S[x][y] != S[x + 1][y]) Q.push({ x + 1, y });
				if (S[x][y] != S[x][y + 1]) Q.push({ x, y + 1 });
				if (S[x][y] != S[x - 1][y]) Q.push({ x - 1, y });
				if (S[x][y] != S[x][y - 1]) Q.push({ x, y - 1 });
			}
			ans += (Black * White);
		}
		cout << ans << endl;
	}

	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
