P num[MAX_H * MAX_W];
int dy[] = {0, -1, 0, 1};
int dx[] = {1, 0, -1, 0};

int par[MAX_H * MAX_W];
int rnk[MAX_H * MAX_W];

void init(int N){
	for(int i = 0; i < N; i++){
		par[i] = i;
		rnk[i] = 0;
	}
}
int find(int x){
	if(par[x] == x){
		return x;
	}else{
		return par[x] = find(par[x]);
	}
}
void unite(int x, int y){
	x = find(x);
	y = find(y);
	if(x == y) return;
	if(rnk[x] < rnk[y]){
		par[x] = y;
	}else{
		par[y] = x;
		if(rnk[x] == rnk[y]) rnk[x]++;
	}
}
bool same(int x, int y){
	return find(x) == find(y);
}

int main(){
	scanf("%d %d", &H, &W);
	for(int i = 0; i < H; i++) scanf("%s", S[i]);
