	for(int i = 0; i < H; i++){
		for(int j = 0; j < W; j++){
			if(S[i][j] == '#') continue;
			for(int k = 0; k < 4; k++){
				int ny = i + dy[k], nx = j + dx[k];
				if(ny < 0 || nx < 0 || ny >= H || nx >= W) continue;
				if(S[ny][nx] == '.') continue;
