	}
	for(int i = 0; i < H; i++){
		for(int j = 0; j < W; j++){
			if(S[i][j] == '.') num[par[i * W + j]].first++;
			else num[par[i * W + j]].second++;
		}
	}
	ll res = 0LL;
	for(int i = 0; i < H * W; i++) res += num[i].first * num[i].second;
	printf("%lld\n", res);
	return 0;
}

