    for (auto v : G[p.first][p.second]) {
        // 白の時
        if (!next and !ok[v.first*W+v.second]) {
            ok[v.first*W+v.second] = 1;
            ret += dfs(v, !next, ok) + 1;
        }
        else if (!ok[v.first*W+v.second]){
            ok[v.first*W+v.second] = 1;
            ret += dfs(v, !next, ok);

            mp[v.first*W+v.second] = true;
            onaji.push_back(v);
        }
    }
