const int dx[] = {-1, 0, 1, 0};
const int dy[] = {0, 1, 0, -1};

int main() {

    LL H, W;
    cin >> H >> W;

    vector<string> S(H);
    for (int i = 0; i < H; i++) cin >> S[i];

    vector<vector<bool>> used(H, vector<bool>(W, false));
    LL ans = 0;

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (!used[i][j]) {
                queue<pair<int, int>> Q;
                used[i][j] = true;
                Q.push(make_pair(i, j));
                LL white = 0;
                LL black = 0;
                while (!Q.empty()) {
                    auto p = Q.front();
                    Q.pop();
                    int y = p.first;
                    int x = p.second;
                    if (S[y][x] == '#') black++;
                    else white++;
                    for (int k = 0; k < 4; k++) {
                        int toY = y + dy[k];
                        int toX = x + dx[k];
                        if (toY < 0 || toY >= H || toX < 0 || toX >= W) continue;
                        if (S[y][x] == S[toY][toX]) continue;
                        if (used[toY][toX]) continue;
                        used[toY][toX] = true;
                        Q.push(make_pair(toY, toX));
                    }
                }
                ans += black * white;
            }
        }
    }

    cout << ans;

    return 0;
}

