int H,W;
char S[410][410];
bool Sc[410][410];

int func(int i,int j,bool isBlack){
    int ans=0;
    char ch;
    if(isBlack) ch='.';
    else ch='#';
    Sc[i][j] = true;
    //cout << "Sc" << Sc[i][j] << endl;
    // left
    if(i>0 && S[i-1][j]==ch && !Sc[i-1][j]){
            ans = ans + func(i-1,j,!isBlack);
            if (isBlack) ans++;
    }
    // right
    if(i<H-1 && S[i+1][j]==ch && !Sc[i+1][j]){
            ans = ans + func(i+1,j,!isBlack);
            if (isBlack) ans++;
    } 
    // up
    if(j>0 && S[i][j-1]==ch && !Sc[i][j-1]){
            ans = ans + func(i,j-1,!isBlack);
            if (isBlack) ans++;
    }
    // down
    if(j<W-1 && S[i][j+1]==ch && !Sc[i][j+1]){
            ans = ans + func(i,j+1,!isBlack);
            if (isBlack) ans++;
    }
    return ans;
}

