int n,m;
char p[405][405];
int bel[405][405];
bool vis[405][405];
int b,w;
long long ans;
void dfs(int x,int y,int cur)
{
	if (x<=0||x>n||y<=0||y>m||vis[x][y]||bel[x][y]!=cur)
		return;
	vis[x][y]=1;
	if (p[x][y]=='#')
		b++;
	else
		w++;
	dfs(x-1,y,cur);
	dfs(x,y-1,cur);
	dfs(x+1,y,cur);
	dfs(x,y+1,cur);
}
int main()
{
	scanf("%d%d",&n,&m);
	for (int i=1;i<=n;i++)
		scanf("%s",p[i]+1);
	for (int i=1;i<=n;i++)
		for (int j=1;j<=m;j++)
			bel[i][j]=(p[i][j]=='.')^((i^j)&1);
	for (int i=1;i<=n;i++)
		for (int j=1;j<=m;j++)
			if (!vis[i][j])
			{
				b=w=0;
				dfs(i,j,bel[i][j]);
				ans+=1ll*b*w;
			}
	printf("%lld\n",ans);
	return 0;
}

