#define BLACK 1
#define WHITE -1
using namespace std;
typedef pair<int, int> P;

short color[400][400];
bool visited[400][400] = {};
P direction[4] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

int H, W;
int black = 0, white = 0, ans = 0;

void dfs(int x, int y, int c)
{
    visited[x][y] = true;

    if (color[x][y] == -c)
    {
        color[x][y] == BLACK ? black++ : white++;
    }

    for (auto d : direction)
    {
        int dx = x + d.first;
        int dy = y + d.second;

        if (!visited[dx][dy])
        {
            dfs(dx, dy, -c);
        }
    }
}

void input()
{
    for (int i = 0; i < H; i++)
    {
        string s;
        cin >> s;
        for (int j = 0; j < W; j++)
        {
            color[i][j] = s[j] == '#' ? BLACK : WHITE;
        }
    }
}
int main()
{
    cin >> H >> W;

    input();
    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            if (color[i][j] == '#')
            {
                black = 0;
                white = 0;
                dfs(i, j, BLACK);
                ans += black * white;
            }
        }
    }

    cout << ans << endl;
}

