struct UnionFind{
	vector<int> par;
	UnionFind(int N){
		par.assign(N,0);
		rep(i,N) par[i]=i;
	}
	int find(int x){
		if(par[x]==x) return x;
		return par[x]=find(par[x]);
	}
	bool same(int x,int y){
		return find(x)==find(y);
	}
	void unite(int x,int y){
		x=find(x),y=find(y);
		if(x==y) return;
		par[y]=x;
	}
};
string s[500];
int dx[4]={1,0,-1,0};
int dy[4] = {0,1,0,-1};
int main(){
	int H,W;
	cin>>H>>W;
	rep(i,H) cin>>s[i];
	UnionFind UF(H*W);
	rep(i,H) rep(j,W) rep(d,4){
		int ni = i + dx[d], nj = j+dy[d];
		if(0<=ni&&ni<H&&0<=nj&&nj<W && s[i][j] != s[ni][nj]) UF.unite(i*W+j,ni*W+nj);
	}
	using P = pair<int,int>;
	map<int,V<P>> mp;
	rep(i,H) rep(j,W) mp[UF.find(i*W+j)].pb(P(i,j));
	ll ans = 0;
	for(auto it: mp){
		ll a[2] = {};
		for(P p:it.sc) a[(p.fs+p.sc)%2]++;
		ans += a[0]*a[1];
	}
	cout<<ans<<endl;
}

