#define MAX_H (400)
#define MAX_W (400)
#define SIZE_BUF (30)

using namespace std;

int main(int argc, char *argv[]) {
  // read inputs
  long H, W;
  char S[MAX_H][MAX_W], buf[SIZE_BUF];
  scanf("%ld %ld", &H, &W);
  fgets(buf, SIZE_BUF, stdin);
  for (long i = 0; i < H; i++) {
    for (long j = 0; j < W; j++) {
      S[i][j] = fgetc(stdin);
    }
    fgets(buf, SIZE_BUF, stdin);
  }
  // for (long i = 0; i < H; i++) {
  //   for (long j = 0; j < W; j++) {
  //     printf("%c", S[i][j]);
  //   }
  //   printf("\n");
  // }

  // dfs
  long gs[MAX_H][MAX_W];
  for (long i = 0; i < H; i++) {
    for (long j = 0; j < W; j++) {
      gs[i][j] = -1;
    }
  }
  long g = 0;
  vector<long> stack_i, stack_j, cntbs, cntws;
  const long dis[] = {1, 0, -1, 0}, djs[] = {0, 1, 0, -1};
  for (long i = 0; i < H; i++) {
    for (long j = 0; j < W; j++) {
      if (gs[i][j] < 0) {
        long cntb = 0, cntw = 0;
        stack_i.push_back(i);
        stack_j.push_back(j);
        gs[i][j] = g;
        if (S[i][j] == '#') {
          cntb++;
        } else {
          cntw++;
        }
        while (!stack_i.empty()) {
          const long i0 = stack_i.back(), j0 = stack_j.back();
          const char c0 = S[i0][j0];
          stack_i.pop_back();
          stack_j.pop_back();
          for (long k = 0; k < 4; k++) {
            const long i1 = i0 + dis[k], j1 = j0 + djs[k];
            if (i1 >= 0 && i1 < H && j1 >= 0 && j1 < W && gs[i1][j1] < 0) {
              const char c1 = S[i1][j1];
              if (c1 != c0) {
                stack_i.push_back(i1);
                stack_j.push_back(j1);
                gs[i1][j1] = g;
                if (S[i1][j1] == '#') {
                  cntb++;
                } else {
                  cntw++;
                }
              }
            }
          }
        }
        g++;
        cntbs.push_back(cntb);
        cntws.push_back(cntw);
      }
    }
  }
  // for (long i = 0; i < H; i++) {
  //   for (long j = 0; j < W; j++) {
  //     printf("%d ", gs[i][j]);
  //   }
  //   printf("\n");
  // }
  long ans = 0;
  for (long i = 0; i < g; i++) {
    ans += cntbs[i] * cntws[i];
    // printf("i = %d, cntb = %d, cntw = %d\n", i, cntbs[i], cntws[i]);
  }
  printf("%ld\n", ans);

  return 0;
}

