#define BL 1
#define WH 0
#define XX 2

int main()
{
    int H, W;
    cin >> H >> W;

    string S[H];
    REP(h, H) cin >> S[h];

    int board[H][W];
    REP(h, H) REP(w, W) board[h][w] = S[h][w] == '#';

    int ret = 0;
    REP(h, H) REP(w, W)
    {
        if (board[h][w] != BL) continue;

        stack<pair<int,int>> nexts;
        nexts.push(make_pair(h, w));
        int count[2] = {0};

        while (!nexts.empty())
        {
            pair<int,int> next = nexts.top();
            nexts.pop();

            int nh = next.first;
            int nw = next.second;
            if (board[nh][nw] == XX) continue;
            ++count[board[nh][nw]];

            if (nh-1 >= 0 && board[nh-1][nw] == !board[nh][nw]) nexts.push(make_pair(nh-1, nw));
            if (nh+1 <  H && board[nh+1][nw] == !board[nh][nw]) nexts.push(make_pair(nh+1, nw));
            if (nw-1 >= 0 && board[nh][nw-1] == !board[nh][nw]) nexts.push(make_pair(nh, nw-1));
            if (nw+1 <  W && board[nh][nw+1] == !board[nh][nw]) nexts.push(make_pair(nh, nw+1));

            board[nh][nw] = XX;
        }

        ret += count[WH]*count[BL];
    }

    cout << ret << endl;
    return 0;
}

