void search(int x,int y,int k){ //深さ優先探索
    if(x < 0 || x >= H || y < 0 || y >= W || reached[x][y] == 1)return;

    reached[x][y] = 1;
    if(S[x][y] == '#')b[k]++;
    if(S[x][y] == '.')w[k]++;

    if(x<399){
        if(S[x][y] != S[x+1][y])search(x+1,y,k);
    }
    if(x>0){
        if(S[x][y] != S[x-1][y])search(x-1,y,k);
    }
    if(y<399){
        if(S[x][y] != S[x][y+1])search(x,y+1,k);
    }
    if(y>0){
        if(S[x][y] != S[x][y-1])search(x,y-1,k);
    }
}



