using namespace std;

std::pair<int, int> paint(int h, int w, boost::multi_array<int, 2>& ss, int y,
                          int x) {
  auto ret = std::pair<int, int>(0, 0);
  int const currentColor = ss[y][x];
  assert(currentColor == 0 || currentColor == 1);
  ss[y][x] = -1;
  if (currentColor == 0) {
    ret.first++;
  } else {
    ret.second++;
  }
  int const alternativeColor = 1 - currentColor;
  if (y > 0 && ss[y - 1][x] == alternativeColor) {
    auto painted = paint(h, w, ss, y - 1, x);
    ret.first += painted.first;
    ret.second += painted.second;
  }
  if (y < h - 1 && ss[y + 1][x] == alternativeColor) {
    auto painted = paint(h, w, ss, y + 1, x);
    ret.first += painted.first;
    ret.second += painted.second;
  }
  if (x > 0 && ss[y][x - 1] == alternativeColor) {
    auto painted = paint(h, w, ss, y, x - 1);
    ret.first += painted.first;
    ret.second += painted.second;
  }
  if (x < w - 1 && ss[y][x + 1] == alternativeColor) {
    auto painted = paint(h, w, ss, y, x + 1);
    ret.first += painted.first;
    ret.second += painted.second;
  }
  return ret;
}

int solve(int h, int w, boost::multi_array<int, 2>& ss) {
  int ret = 0;
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (ss[i][j] < 0) {
        continue;
      }
      auto painted = paint(h, w, ss, i, j);
      ret += painted.first * painted.second;
    }
  }
  return ret;
}

