		if(maze[rt.x][rt.y]=='.'){
			ww++;
//			sst.insert(make_pair(make_pair(x,y),make_pair(rt.x,rt.y)));
		}
		for(int i=0;i<4;i++){
			int dx=rt.x+dir[i][0];
