#include<bits/stdc++.h>
#define rep(i,n,m) for(int i = (n); i <(m); i++)
#define rrep(i,n,m) for(int i = (n) - 1; i >=(m); i--)
using namespace std;
using ll = long long;
using tiii = tuple<int, int, int>;
const int MAX_HW = 500;

int colors[MAX_HW][MAX_HW];
vector<string> bw_grid;
int bw_cnt[2][MAX_HW * MAX_HW];
int h, w;

int bw(int i, int j)
{
    return int(bw_grid[i][j] == '#');
}

void bfs()
{
    int color = 1;
    rep(i, 0, h)
    rep(j, 0, w)
    if (colors[i][j] == 0)
    {
        queue<tiii> que;
        int reverse_bw = (1 + bw(i, j)) % 2;
        que.push(make_tuple(i, j, reverse_bw));
        while (que.size() > 0)
        {
            int x,y,prev_c;
            tie(x, y, prev_c) = que.front();
            que.pop();

            if (x < 0 or h <= x) continue;
            if (y < 0 or w <= y) continue;

            if (colors[x][y] != 0) continue;

            int now_c = bw(x, y);
            if (now_c == prev_c) continue;

            colors[x][y] = color;
            ++bw_cnt[now_c][color];

            que.push(make_tuple(x-1, y, now_c));
            que.push(make_tuple(x+1, y, now_c));
            que.push(make_tuple(x, y-1, now_c));
            que.push(make_tuple(x, y+1, now_c));
        }
        ++color;
    }
}

int main()
{
    cin >> h >> w;

    rep(i, 0, h)
    {
        string s;
        cin >> s;
        bw_grid.push_back(s);
    }
    bfs();

    ll ans = 0;
    rep(i, 1, MAX_HW * MAX_HW)
        ans += (ll)bw_cnt[0][i] * bw_cnt[1][i];

    cout << ans << endl;
    return 0;
}

