        if(s[y][x]!=s[ny][nx]){
            if(s[ny][nx]=='.'){
                D[make_pair(make_pair(sy,sx),make_pair(ny,nx))]++;
            }
            //cout<<y<<' '<<x<<' '<<ny<<' '<<nx<<endl;
            done[ny][nx]=true;
            dfs(ny,nx);
            done[ny][nx]=false;
        }
    }
}
signed main(){
    cin>>h>>w;
    for(int i=0;i<h;i++)cin>>s[i];
    for(int a=0;a<h;a++){
        for(int b=0;b<w;b++){
            if(s[a][b]=='#'){
                done[a][b]=true;
                sy=a;
                sx=b;
                dfs(a,b);
                done[a][b]=false;
            }
        }
    }
    int res=0;
    for(auto it:D)res++;
    cout<<res<<endl;
}

