int h, w;
char g[444][444];
bool used[444][444];
ll black, white;

bool border(int i, int j)
{
	if (i < 1 || i > h || j < 1 || j > w) return false;
	else return true;
}

void count(int i, int j)
{
	used[i][j] = true;
	if (g[i][j] == '#') {
		black++;
		if (border(i + 1, j) && g[i + 1][j] == '.' && used[i + 1][j] == 0) count(i + 1, j);
		if (border(i - 1, j) && g[i - 1][j] == '.' && used[i - 1][j] == 0) count(i - 1, j);
		if (border(i, j + 1) && g[i][j + 1] == '.' && used[i][j+1] == 0) count(i, j + 1);
		if (border(i, j - 1) && g[i][j - 1] == '.' && used[i][j-1] == 0) count(i, j - 1);
	}
	else {
		white++;
		if (border(i + 1, j) && g[i + 1][j] == '#' && used[i + 1][j] == 0) count(i + 1, j);
		if (border(i - 1, j) && g[i - 1][j] == '#' && used[i - 1][j] == 0) count(i - 1, j);
		if (border(i, j + 1) && g[i][j + 1] == '#' && used[i][j + 1] == 0) count(i, j + 1);
		if (border(i, j - 1) && g[i][j - 1] == '#' && used[i][j - 1] == 0) count(i, j - 1);
	}
}

int main()
{
	cin >> h >> w;
	for (int i = 1;i <= h;i++) {
		for (int j = 1;j <= w;j++) {
			cin >> g[i][j];
		}
	}

	ll ans = 0;

	for (int i = 1;i <= h;i++) {
		for (int j = 1;j <= w;j++) {
			if (used[i][j] == 0 && g[i][j] == '#') {
				black = 0;
				white = 0;
				count(i, j);
				ans += (black * white);
			}
		}
	}

	cout << ans << endl;

	return 0;
}

