// union find {{{
class union_find {

    using data_type = int_fast32_t;
    std::vector< data_type > data_;

    public:
    union_find(std::size_t size) : data_(size, -1) {}

    std::size_t size() const {
        return data_.size();
    }

    data_type get_root(data_type x) {
        return (data_[x] < 0 ? x : data_[x] = get_root(data_[x]));
    }

    bool is_root(data_type x) {
        return x == get_root(x);
    }

    bool is_same(data_type x, data_type y) {
        return get_root(x) == get_root(y);
    }

    void unite(data_type x, data_type y) {
        x = get_root(x); y = get_root(y);
        if (x == y) return;

        if (data_[x] > data_[y]) std::swap(x, y);
        data_[x] += data_[y];
        data_[y] = x;
    }

    data_type element_count(data_type x) {
        return -data_[get_root(x)];
    }
};
// }}}

void solver() {
    int h = input(), w = input();
    vector< string > ss(h);
    cin >> ss;

    union_find uf(h * w);
    range(i, 0, h) range(j, 0, w) {
        int v = i * w + j;
        if (i + 1 != h) {
            int u = (i + 1) * w + j;
            if (ss[i][j] != ss[i + 1][j]) {
                uf.unite(u, v);
            }
        }

        if (j + 1 != w) {
            int u = i * w + (j + 1);
            if (ss[i][j] != ss[i][j + 1]) {
                uf.unite(u, v);
            }
        }
    }

    auto cnt = make_vector(h * w, 2, 0ll);
    range(i, 0, h) range(j, 0, w) {
        int v = i * w + j;
        int u = uf.get_root(v);
        cnt[u][ss[i][j] == '.'] += 1;
    }

    i64 ans = 0;
    for (auto v: cnt) {
        ans += v[0] * v[1];
    }

    cout << ans << endl;
}

signed main(int argc, char *argv[]) {
    solver();
}

