class unionfind {
  vector<int> p;
public:
  void init(int n) {
    for (int i = 0; i < n; i++) {
      p.push_back(i);
    }
  }

  void merge(int m, int n) {
    if (find(m) == find(n)) return;
    p.at(find(m)) = find(n);
  }

  int find(int n) {
    if (p.at(n) == n) return n;
    return p.at(n) = find(p.at(n));
  }
};

