        t.merge(i * w + j, (i + 1) * w + j);
      }
    }
  }
  vector<pair<int, int>> c;
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      int root = t.find(i * w + j);
      if (s.at(i).at(j) == '#') {
        c.at(root).first++;
      } else {
        c.at(root).second++;
      }
    }
  }
  long total = 0;
  for (int i = 0; i < h * w; i++) {
    total += (long)c.at(i).first * c.at(i).second;
  }
  cout << total << endl;
}

