ll finalans = 0;

//UFからアクセスしたいのでグローバルにおく
int H, W;
//mapdata[1~H][1~W] でアクセス
vector<string> mapdata;

//idxをnode番号にする関数
//番兵を含めたidx(0~H+1, 0~W+1)を入れること
int to_n(int h, int w){
  return W * h + w;
};

//Union-Find
//0-indexed 注意！！
struct UnionFind {
  //data[idx]はノードの「根」もしくは「親」を格納している（必ずしも根ではない！）
  //  Q. 「根」じゃないの？
  //  初めは「根」を入れてるのだが、別のところでuniteが起きると情報が古くなる。
  //  だからfind_root()で再帰的に求めないと間違いが起こり得る。
  //  ちなみに「根」ノードのdata[idx]は直接アクセスしてok（最後にuniteされたものなので）
  vector< int > data;

  UnionFind(int sz) {
    data.assign(sz, -1); //ノードが属する根の番号を格納（根の場合はマイナス要素数を格納）
  }

  //併合　成功したらtrue, 既に同じ木ならfalse
  bool unite(int x, int y) {
    x = find_root(x), y = find_root(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  bool isSameGroup(int x, int y){
    x = find_root(x), y = find_root(y);
    if(x == y) return true;
    else return false;
  }

  //ノードが属する根の番号を返す（引数が根だった場合はその番号をそのまま帰す）
  int find_root(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find_root(data[k]));
  }

  //ノードが属する木に属するノードの数を返す
  int count(int k) {
    return (-data[find_root(k)]);
  }

  //木の数（接続していないグラフの数）を返す
  //根となっているノード（data[k]が負のもの）を数えるだけ
  int count_trees() {
    int ans = 0;
    rep(d_idx, data.size()){
      if (data[d_idx] < 0){
        ans += 1;
      }
    }
    return ans;
  }

  //今回だけの改造
  //「根」を見つけたら、その根が属する木に属するノード数を求める
  //ノード数が1なら、どこにも行けないマスなので無視
  //2以上なら、属する黒ノードの数、白ノードの数を確認する
  void solve() {
    vector<int> rootlist;
    rep(h, H){
      rep(w, W){
        ll num = -data[to_n(h,w)];
        if (num > 3){
          rootlist.PB(to_n(h, w));
        }
        else if (num >= 2){ //-3<=x<=-2 つまりx=-2 or -3
          //ノード数が2なら組合せは1
          //ノード数が3なら組合せは2にきまっている
          finalans += num - 1;
        }
      }
    }
    ll black = 0;
    ll white = 0;
    for (int eachroot : rootlist){ //to_n済み
      black = 0;
      white = 0;
      //根の分をカウント
      int root_h = eachroot / W;
      int root_w = eachroot - (root_h * W);
      if (mapdata[root_h][root_w] == '#'){
        black += 1;
      }
      else{
        white += 1;
      }
      //根以外を入れる
      rep(h, H){
        rep(w, W){
          if (h == root_h && w == root_w){
            continue;
          }
          if (find_root(to_n(h, w)) == eachroot){
            if (mapdata[h][w] == '#'){
              black += 1;
            }
            else{
              white += 1;
            }
          }
        }
      }
      finalans += black * white;
    }
  }

};

