void nhap()
{
    cin >> n >> m;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) cin >> c[i][j];
    }
}

void DFS(int u,int &SL,int &Value) {
    kt[u] = 1;
    Value += TS[u];
    SL++;
    for (int v : a[u]) {
        if (kt[v] == 0) DFS(v,SL,Value);
    }
}
void solve()
{
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            int u = (i - 1) * n + j;
            TS[u] = (c[i][j] == '#' ? 1 : -1);
            for (int h = 0; h < 2; h++) {
                int x = i + di[h];
                int y = j + dj[h];
                if (x > 0 && x <= n && y > 0 && y <= m && c[i][j] != c[x][y]) {
                    int u = (i - 1) * n + j;
                    int v = (x - 1) * n + y;
                    a[u].push_back(v);
                    a[v].push_back(u);
                }
            }
        }
    }
    long long Res = 0;
    for (int i = 1; i <= n * m; i++) {
        int SL = 0;
        int Value = 0;
        if (kt[i] == 0) {
            DFS(i,SL,Value);
            int SL1 = (SL + Value) >> 1;
            int SL2 = SL - SL1;
            Res += 1ll * SL1 * SL2;
        }
    }
    cout << Res;
}
