        Point buf;
        buf.x=x+1;buf.y=y;
        if(x+1<w&&y<h)if(s[buf.y][buf.x]!=s[y][x])next.push_back(buf);
        buf.x=x-1;buf.y=y;
        if(x-1>=0&&y<h)if(s[buf.y][buf.x]!=s[y][x])next.push_back(buf);
        buf.x=x;buf.y=y+1;
        if(x<w&&y+1<h)if(s[buf.y][buf.x]!=s[y][x])next.push_back(buf);
        buf.x=x;buf.y=y-1;
        if(x<w&&y-1>=0)if(s[buf.y][buf.x]!=s[y][x])next.push_back(buf);
    }
};
