int n , m;

int color[N][N] , ind[N][N];
int parent[N];
int sz[N * N];

char a[N][N];

int findher(int v){
    if(v == parent[v])return v;
    return parent[v] = findher(parent[v]);
}

void tmerge(int a,int b){
    if(sz[a] < sz[b]) swap(a , b);
    a = findher(a);
    b = findher(b);
    parent[b] = a;
    sz[a] += sz[b];
}

int dx[10] = {2 , -2 , 0 , 0};
int dy[10] = {0 , 0 , 2 , -2};

int ddx[10] = {1 , 1 , -1 , -1};
int ddy[10] = {-1 , 1 , -1 , 1};

int main(){
    cin>>n>>m;
    int it = 0;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            scanf(" %c",&a[i][j]);
        }
    }
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            if(a[i][j] == '#'){
                ind[i][j] = ++it;
                parent[it] = it;
                sz[it] = 1;
                for(int h=0;h<4;h++){
                    int nx = i + dx[h] , ny = j + dy[h];
                    int x = i + dx[h] / 2 , y = j + dy[h] / 2;
                    if(nx < 1 || ny < 1 || nx > n || ny > m)continue;
                    if(a[nx][ny] == '#' && a[x][y] == '.'){
                        int id = ind[nx][ny];
                        if(id == 0)continue;
                        if(findher(it) != findher(id)){
                            tmerge(it , id);
                        }
                    }
                }
                for(int h=0;h<4;h++){
                    int nx = i + ddx[h] , ny = j + ddy[h];
                    int x = i + ddx[h] , y = j;
                    int xx = i , yy = j + ddy[h];
                    if(nx < 1 || ny < 1 || nx > n || ny > m)continue;
                    if(a[nx][ny] == '#'){
                        if(a[x][y] != '.' && a[xx][yy] != '.')continue;
                        int id = ind[nx][ny];
                        if(id == 0)continue;
                        if(findher(it) != findher(id)){
                            tmerge(it , id);
                        }
                    }
                }
            }
        }
    }
    int answ = 0;
    for(int i=1;i<=n;i++){
        for(int j=1;j<=m;j++){
            if(a[i][j] == '.'){
                set <int> q;
                set <int>::iterator it;
                for(int h=0;h<4;h++){
                    int x = i + dx[h] / 2 , y = j + dy[h] / 2;
                    if(x < 1 || y < 1 || x > n || y > m)continue;
                    if(a[x][y] == '.')continue;
                    q.insert(findher(ind[x][y]));
                }
                for(it = q.begin(); it != q.end(); ++it){
                    answ += sz[(*it)];
                }
            }
        }
    }
    cout<<answ<<endl;
    return 0;
}

