using namespace std;

typedef long long ll;

ll h, w;

bool IsBorder(ll i, ll j) {
    return (i == -1 || j == -1 || i == h || j == w);
}

ll GetId(ll i, ll j) {
    return i * w + j;
}

pair<ll, ll> GetCoords(ll id) {
    return make_pair(id / w, id % w);
}

int main() {
    vector<pair<ll, ll>> sh = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
    cin >> h >> w;
    vector<string> v(h);
    rep(i,0,h) {
        cin >> v[i];
    }
    ll size = h * w;
    vector<vector<ll>> g(size);
    rep(i,0,h) {
        rep(j,0,w) {
            rep(k,0,4) {
                ll x = i + sh[k].first;
                ll y = j + sh[k].second;
                ll id = GetId(i, j);
                ll sid = GetId(x, y);
                if (!IsBorder(x, y)) {
                    if (v[i][j] != v[x][y]) {
                        g[id].push_back(sid);
                    }
                }
            }
        }
    }
    vector<bool> used(size);
    vector<pair<ll, ll>> res;
    rep(i,0,size) {
        if (!used[i]) {
            ll bl = 0, wh = 0;
            queue<pair<ll, ll>> q_;
            q_.push(make_pair(i, -1));
            used[i] = true;
            while(!q_.empty()) {
                ll id = q_.front().first;
                ll par = q_.front().second;
                pair<ll, ll> coord = GetCoords(id);
                if (v[coord.first][coord.second] == '#') {
                    ++bl;
                } else {
                    ++wh;
                }
                rep(j,0, g[id].size()) {
                    ll sid = g[id][j];
                    if (sid == par || used[sid]) {
                        continue;
                    }
                    used[sid] = true;
                    q_.push(make_pair(sid, id));
                }
                q_.pop();
            }
            res.push_back(make_pair(bl, wh));
        }
    }
    ll ans = 0;
    rep(i,0,res.size()) {
        ans += res[i].first * res[i].second;
    }
    cout << ans << endl;
    return 0;
}

