using namespace std;

int H, W;
char S[401][400];

bool used[400][400];
int dx[4] = { 1,0,-1,0 }, dy[4] = { 0,1,0,-1 };

P dfs(int h, int w) {
	P res;
	if (S[h][w] == '#') res.first++;
	else res.second++;
	used[h][w] = true;
	for (int i = 0; i < 4; i++) {
		int nx = h + dx[i], ny = w + dy[i];
		if (nx >= 0 && nx < H && ny >= 0 && ny < W && !used[nx][ny] && S[h][w] != S[nx][ny]) {
			P p = dfs(nx, ny);
			res.first += p.first;
			res.second += p.second;
		}
	}
	return res;
}

void solve() {
	memset(used, false, sizeof(used));
	ll ans = 0;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < H; j++) {
			if (!used[i][j]) {
				P res = dfs(i, j);
				ans += res.first * res.second;
			}
		}
	}
	printf("%lld\n", ans);
}

int main() {
	scanf("%d %d", &H, &W);
	for (int i = 0; i < H; i++)
		scanf("%s", S[i]);
	solve();
}

