				else if(S[i][j]=='.'&&S[i][j+1]=='#'){
					uf.unite(i*W+j,i*W+j+1);
				}
			}
		}
	}
	rep(i,H){
		rep(j,W){
			if(S[i][j]=='#'){
				bnum[uf.root(i*W+j)]++;
			}
			else{
				wnum[uf.root(i*W+j)]++;
			}
		}
	}
	rep(i,H){
		rep(j,W){
			if(uf.root(i*W+j)==i*W+j){
				ans+=bnum[i*W+j]*wnum[i*W+j];
			}
		}
	}
	prin(ans);
	return 0;
}

