long long dfs( int i, int j, int flag )
{
	if( visit[i][j / sizeof(int)] & (1 << (j % sizeof(int))) ) {
		return -1;
	}
	visit[i][j / sizeof(int)] |= 1 << (j % sizeof(int));

	char ptn = '.';
	int add = 1;
	if( flag % 2 ) {
		ptn = '#';
		add = 0;
	}

	long long res = 0;
	for( int k = 0; k < 4; k++ ) {
		int ni = i + diri[k];
