    //上下左右に進んで、
    for (int i = 0; i < 4; i++)
    {
        int hnow = hpre + mv[i][0];
        int wnow = wpre + mv[i][1];

        //別の色であること、エリア内であること、
        if (0 <= hnow && hnow < hmax && 0 <= wnow && wnow < wmax && path[hnow][wnow] != 1)
        {
            if (trout[hnow][wnow] + trout[hpre][wpre] == 1)
            {
                if (trout[hnow][wnow] == DOT) {
                    //printf("h,w %d,%d\n", hnow, wnow);
                    cnt++;
                }
                path[hnow][wnow] = 1;
