	REP(i,H){
		REP(j,W){
			if (S[i][j]=='.') white[dp[i][j]]++;
			else  black[dp[i][j]]++;
		}
	}
	REP(i,blocks+1){
		ans += white[i]*black[i];
	}

	//出力
