#define rep(i,n) for(int i=0, i##_len=(n); i<i##_len; ++i)

int h,w;
string s[400];
bool visited[400][400];

// <black, white>
pair<lint,lint> dfs(int y, int x) {
    pair<lint,lint> res;
    if (visited[y][x]) return res;
    visited[y][x] = true;
    if (s[y][x] == '#') res.first ++;
    else res.second ++;
    int yc[] = {0,0,-1,1};
    int xc[] = {-1,1,0,0};
    rep(i,4) {
        int ny = y + yc[i];
        int nx = x + xc[i];
        if (0 <= ny and ny < h and 0 <= nx and nx < w) {
            if (s[y][x] != s[ny][nx]) {
                auto t = dfs(ny,nx);
                res.first += t.first;
                res.second += t.second;
            }
        }
    }
    return res;
}

int main() {
    cin >> h >> w;
    rep(i,h) cin >> s[i];
    lint ans = 0;
    rep(y,h) {
        rep(x,w) {
            if (not visited[y][x]) {
                auto p = dfs(y,x);
                ans += p.first * p.second;
            }
        }
    }
    cout << ans << endl;
}

