ll ans = 0;
bool searched[400][400];
char grid[400][400];
int H;
int W;
int move_x[4] = {-1, 0, 1, 0};
int move_y[4] = {0, -1, 0, 1};
ll n_white;
ll n_black;

bool isRange(int x, int y){
    if(x <  0) return false;
    if(x >= H) return false;
    if(y <  0) return false;
    if(y >= W) return false;
    return true;
}

void dfs(int x, int y, char col){

    // 探索範囲外，探索済，色が同じであれば何もしない
    if(!isRange(x, y)) return ;
    if(searched[x][y]) return ;
    if(grid[x][y] == col) return;

    searched[x][y] = true;
    if(grid[x][y] == '#') n_black ++;
    else n_white ++;

    for(int i = 0; i < 4; i++){
        int nx = x + move_x[i];
        int ny = y + move_y[i];
        if( isRange(nx, ny) ){
            dfs(nx, ny, grid[x][y]);
        }
    }
}

int main(){

    cin >> H >> W;

    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            cin >> grid[i][j];
            searched[i][j] = false;
        }
    }

    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            if(grid[i][j] == '#'){
                n_black = 0;
                n_white = 0;
                dfs(i, j, '.');
                ans += (n_white * n_black);
            }
        }
    }

    cout << ans << endl;

}

