vector<string> str;

    int h,w;
    int bl,wh;
void rec(int i){//h,w
    if(str[i/w][i%w] == '#') bl++;
    else wh++;

    flag[i] = true;
    for(auto elem : graph[i]){
        if(!flag[elem]){
            rec(elem);
        }
    }
}

int main(){
    cin >> h >> w;
    flag.resize(h*w+100,false);
    str.resize(h+400);
    int ans = 0;
    rep(i,h) cin >> str[i];

    rep(i,h){
        rep(j,w){
            if(i+1<h){
                if(str[i+1][j] != str[i][j]){
                    //down
                    graph[(i)*w+j].push_back( (i+1)*w+j);
                    graph[(i+1)*w+j].push_back( (i)*w+j);
                }
            }
            if(j+1<w){
                if(str[i][j+1] != str[i][j]){
                    //right
                    graph[(i)*w+j].push_back((i)*w+j+1);
                    graph[(i)*w+j+1].push_back((i)*w+j);
                }
            }
        }
    }

    rep(i,h){
        rep(j,w){
            if(!flag[i*w+j]){
                rec(i*w+j);
                ans += bl*wh;
                bl = wh = 0;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

