void dfs(int y, int x, int& n_black, int &n_white)
{
  if(used[y][x])
    return;

  used[y][x] = true;
  if( S[y][x] == '#')
    {
      n_black++;
      if( y>0 && S[y-1][x] == '.')
	dfs(y-1,x,n_black,n_white);
      if( x>0 && S[y][x-1] == '.')
	dfs(y,x-1,n_black,n_white);
      if( y< S.size()-1 && S[y+1][x] == '.')
	dfs(y+1,x,n_black,n_white);
      if( x< S[0].size()-1 && S[y][x+1] == '.')
	dfs(y,x+1,n_black,n_white);
    }
  else
    {
      n_white++;
      if( y>0 && S[y-1][x] == '#')
	dfs(y-1,x,n_black,n_white);
      if( x>0 && S[y][x-1] == '#')
	dfs(y,x-1,n_black,n_white);
      if( y< S.size()-1 && S[y+1][x] == '#')
	dfs(y+1,x,n_black,n_white);
      if( x< S[0].size()-1 && S[y][x+1] == '#')
	dfs(y,x+1,n_black,n_white);
    }
  return;
}

