#define INF (1LL<<60)

typedef pair<int, int> P;
int dx[4] = { 0, 1, 0, -1 };
int dy[4] = { 1, 0, -1, 0 };

int H, W;
int sy, sx, gy, gx;
char a[402][402];
int d[402][402];

int bfs(int sx, int sy){
	queue<P> que;

	for (int h = 1; h <= H; h++)
		for (int w = 1; w <= W; w++) d[h][w] = INF;

	que.push(P(sy, sx));
	d[sy][sx] = 0;

	while (que.size()>0){
		P p = que.front();
		que.pop();

		for (int i = 0; i < 4; i++){
			int ny = p.first + dy[i], nx = p.second + dx[i];
			// 今黒なら次が白だけqueueに
			if (a[p.first][p.second]=='#'){
				if (a[ny][nx] == '.' && d[ny][nx] == INF){
					que.push(P(ny, nx));
					d[ny][nx] = d[p.first][p.second] + 1;
				}
			}
			// 今白なら次が黒だけqueueに
			else{
				if (a[ny][nx] == '#' && d[ny][nx] == INF){
					que.push(P(ny, nx));
					d[ny][nx] = d[p.first][p.second] + 1;
				}
			}
		}
	}
	int ans = 0;
	for (int h = 1; h <= H; h++)
		for (int w = 1; w <= W; w++)
			if (d[h][w] != INF && a[h][w] == '.') ans++;
	return ans;
}
signed main(){

	cin >> H >> W;

	for (int h = 1; h <= H; h++)
		for (int w = 1; w <= W; w++) cin >> a[h][w];

	int ans = 0;
	for (int h = 1; h <= H; h++)
		for (int w = 1; w <= W; w++)
			if (a[h][w] == '#') ans += bfs(w, h);

	cout << ans << endl;

	return 0;
}

#include <bits/stdc++.h>

using namespace std;

int h,w;

void solve(){
    int i,j;
    string str;
    cin >> h >> w;
    vector<string> s(h);
    for(i = 0;i < h;i++) cin >> s[i];
    vector<int> c(h*w+1,0),d(h*w+1,0);
    int f[400][400];
    memset(f,-1,sizeof(f));
    vector<pair<int,int> > st;
    int k = 0;
    for(i = 0;i < h;i++){
        for(j = 0;j < w;j++){
            if(f[i][j] == -1){
                f[i][j] = k;
                st.push_back(make_pair(i,j));
                for(c[k] = d[k] = 0;st.size()>0;){
                    int y = st.back().first;
                    int x = st.back().second;
                    if(s[y][x] == '#') c[k]++;
                    else d[k]++;
                    f[y][x] = k;
                    st.pop_back();
                    if(y > 0 && f[y-1][x] == -1 && s[y-1][x] != s[y][x]){
                        f[y-1][x] = k;
                        st.push_back(make_pair(y-1,x));
                    }
                    if(x > 0 && f[y][x-1] == -1 && s[y][x-1] != s[y][x]){
                        f[y][x-1] = k;
                        st.push_back(make_pair(y,x-1));
                    }
                    if(y+1 < h && f[y+1][x] == -1 && s[y+1][x] != s[y][x]){
                        f[y+1][x] = k;
                        st.push_back(make_pair(y+1,x));
                    }
                    if(x+1 < w && f[y][x+1] == -1 && s[y][x+1] != s[y][x]){
                        f[y][x+1] = k;
                        st.push_back(make_pair(y,x+1));
                    }
                }
                k++;
            }
        }
    }
    long long ans = 0;
    for(i = 0;i < h*w+1;i++){
        ans += c[i]*d[i];
    }
    cout << ans << endl;
}

int main(){
    solve();
}

