/*
      x: 1001 1010  1100 1011 1101  1111
x & ~ x: 0001 0010  0100 0001 0001  0001
    sum: 1010 1100 10000 1100 1100 10000

####### Attention #######
S | (1 << i) -> S union {i}
S & ~(1 << i) -> S - {i}

# inclusion-exclusion principle
|U[i = 1 to n] Ai| = sum[i = 1 to n] |Ai| - sum[i < j]|Ai ^ Aj| + ... + (-1)^(n - 1) |^[i = 1 to n]Ai|
*/

const ll MAX_N = 200005;
const size_t MAX_BIT = 160 * 160 + 10;
typedef bitset<MAX_BIT> bts;
typedef vector<bts> vbt;
typedef vector<vbt> vbt2;
typedef vector<vbt2> vbt3;
const bool multiple_queries = false;

void solve(){
    // generate_array(size, min, max);
    ll h, w, ans = 0; in2(h, w);
    vb2 black, visited(w, vb(h, false));
    queue<point> q;
    read_2DMap(w, h, black, '#');
    rep(x, w) rep(y, h) if (black[x][y]) q.push({x, y});

    auto ng = [&](point p, bool b) -> bool{
        if (p.x < 0 || p.x >= w) return true;
        if (p.y < 0 || p.y >= h) return true;
        if (visited[p.x][p.y]) return true;
        if (black[p.x][p.y] == b) return true;
        return false;
    };

    ll c1, c2; 
    auto dfs = [&](auto dfs, point src) -> void{
        visited[src.x][src.y] = true; c1++;
        rep(i, 4){
            point nx1 = src + dirs[i];
            if (ng(nx1, true)) continue;
            visited[nx1.x][nx1.y] = true;
            c2++;
            rep(j, 4){
                point nx2 = nx1 + dirs[j];
                if (ng(nx2, false)) continue;
                dfs(dfs, nx2);
            }
        }
    };

    while (!q.empty()){
        point p = q.front(); q.pop();
        if (visited[p.x][p.y]) continue;
        c1 = c2 = 0;
        dfs(dfs, p);
        ans += c1 * c2;
    }

    prl(ans);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

void test(ll num = 0, bool verbose = false){
    rep(i, max(1LL, num)){
        ll t = clock();
        if (verbose) prl4("\n#####", i + 1, "#####", "\n## Answer ##");
        solve();
        if (verbose) {prl(""); prl_time(t);}
    }
}

