    UnionFind UF(H * W);
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            for (int k = 0; k < 4; k++) {
                int toY = i + dy[k];
                int toX = j + dx[k];
                if (toY < 0 || toY >= H || toX < 0 || toX >= W) continue;
                if (S[i][j] != S[toY][toX]) {
                    UF.unite(f(i, j), f(toY, toX));
                }
            }
        }
    }

    vector<LL> black(H * W, 0);
    vector<LL> sizes(H * W, 0);

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (S[i][j] == '#') {
                black[UF.find(f(i, j))]++;
            }
        }
    }

    LL ans = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (f(i, j) == UF.find(f(i, j))) {
                LL all = UF.get_size(f(i, j));
                LL white = all - black[f(i, j)];
                ans += black[f(i, j)] * white;
            }
        }
    }

    cout << ans;

    return 0;
}

