using namespace std;

struct UnionFind
{
  vector<int> par; //par[i]がiの根を表す

  // コンストラクタ
  UnionFind(int n)
  {
    par = vector<int>(n);
    for (int i = 0; i < n; i++)
    {
      par[i] = i;
    }
  }

  // データxの根を求める
  int root(int x)
  {
    if (par[x] == x)
      return x;
    par[x] = root(par[x]); // 木構造の縮約を行っている
    return par[x];
  }

  // xとyの親が違うとき、マージする。そのときyの根がxの根の子になる
  void merge(int x, int y)
  {
    int rootx = root(x);
    int rooty = root(y);
    if (rootx == rooty)
      return;
    par[rooty] = rootx;
  }

  // 同じグループに属しているか
  bool isSame(int x, int y)
  {
    return root(x) == root(y);
  }
};

