          tree.merge(i * w + j, i * w + j + 1);
        }
      }

      if (i < h - 1)
      {
        if (map[i][j] != map[i + 1][j])
        {
          tree.merge(i * w + j, (i + 1) * w + j);
        }
      }
    }
  }

  //ここから

  int a[16000] = {};
  int b[16000] = {};

  REP(i, h)
  {
    REP(j, w)
    {
      int r = tree.root(i * w + j);
      if (map[i][j] == 0)
      {
        a[r]++;
      }
      else
      {
        b[r]++;
      }
    }
  }

  // ここまでにバグがある

  int result = 0;

  REP(i, h * w)
  {
    result += a[i] * b[i];
  }

  cout << result << endl;
}

