                trout[i][j] = DOT;
            }
            else
            {
                trout[i][j] = SHARP;
            }
        }
    }

    unsigned long long sum = 0;
    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            if(trout[i][j] != NONE){
            int targcolor;
            if (trout[i][j] == DOT){
                cntdot++;
                targcolor = SHARP;
            }else{
                cntsharp++;
                targcolor = DOT;
            }
            trout[i][j] = NONE;
            countroute(i, j, H, W, targcolor);
            sum += cntdot * cntsharp;
            cntdot = 0;
            cntsharp = 0;
            }
        }
    }

    cout << sum << endl;
}

