void rec(int h, int w) {
  if (vis[h][w] == true) return;
  if (h + 1 < H && s[h + 1][w] != s[h][w]) rec(h + 1, w);
  if (w + 1 < W && s[h][w + 1] != s[h][w]) rec(h, w + 1);

  if (s[h][w] == '.') {
    x++;
  } else {
    y++;
  }
  vis[h][w] = true;
  return;
}

