struct UnionFind {
    vector<int> par;

    UnionFind(int N) : par(N) {
        for(int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        par[rx] = ry;
    }

    bool same(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

int main() {
    //ll N; cin >> N;
    //ll N,M; cin >> N >> M;
    //string S; cin >> S;
    int H,W; cin >> H >> W;
    int hw=H*W;
    char c[hw];
    vector<int> ve;
    rep(i,hw){
        cin >> c[i];
        ve.push_back(i);
    }
    UnionFind tree(hw);
    rep(i,hw){
      	int h=i/W;
        int w=i%W;
      if((h+w)%2==0){
        if((i-W)>=0 && c[i]!=c[i-W])tree.unite(i,i-W);
        if((i+W)<hw && c[i]!=c[i+W])tree.unite(i,i+W);
        if((w-1)>=0 && c[i]!=c[i-1])tree.unite(i,i-1);
        if((w+1)<W && c[i]!=c[i+1])tree.unite(i,i+1);
      }
    }
    int sum=0;
    while(!ve.empty()){
        int a=ve.back();
        int e=1,o=0;
        ve.pop_back();
        for(auto x:ve){
            if(tree.same(a,x)){
                if(((x/W-a/W)%2+(x%W-a%W)%2)%2==0)e++;
                else o++;
                auto itr=find(all(ve),x);
                ve.erase(itr);
            }
        }
        sum+=e*o;
    }
    cout << sum;
}

