P dfs(int i, int j, bool black) {
    // DD(i, j)
    visited[i][j] = true;
    P ans = black ? make_pair(1, 0) : make_pair(0, 1);
    for (int k = 0; k < 4; ++k) {
        int ni = i + di[k];
        int nj = j + dj[k];
        if (ni < 0 || ni >= h) continue;
        if (nj < 0 || nj >= w) continue;
        if (visited[ni][nj]) continue;
        if (black && grid[ni][nj] == '#') continue;
        if (!black && grid[ni][nj] == '.') continue;
        P res = dfs(ni, nj, !black);
        ans.first += res.first;
        ans.second += res.second;
    }
    return ans;
}

