    ll ans = 0;
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            if (!visited[i][j] && grid[i][j] == '#') {
                P res = dfs(i, j, true);
                ans += (ll)res.first * res.second;
            }
        }
    }
    cout << ans << endl;
}

