bool bp[410][410];

bool isin_(int i, int j)
{
    return i >= 0 && i < h && j >= 0 && j < w;
}

bool check_(int i, int j, int d)
{
    int ni = i + dx[d];
    int nj = j + dy[d];
    if (!isin_(ni, nj))
        return false;
    if (bp[i][j] == bp[ni][nj])
        return false;
    return true;
}

ll bfs()
{
    ll ans = 0;
    ll b = 0;
    ll w = 0;
    for (int i = 0; i < h; ++i)
    {
        for (int j = 0; j < w; ++j)
        {
            if (visited[i][j])
                continue;
            b = 0;
            w = 0;
            queue<P> q;
            visited[i][j] = true;
            q.push(P(i, j));
            while (!q.empty())
            {
                P p = q.front();
                q.pop();
                int ci = p.first;
                int cj = p.second;
                if (bp[ci][cj])
                    b++;
                else
                    w++;
                for (int d = 0; d < 4; ++d)
                {
                    if (!check_(ci, cj, d))
                        continue;
                    int ni, nj;
                    ni = ci + dx[d];
                    nj = cj + dy[d];
                    if (visited[ni][nj])
                        continue;
                    visited[ni][nj] = true;
                    q.push(P(ni, nj));
                }
            }
            ans += b * w;
        }
    }
    return ans;
}

