void dfs(int i, int j, vector<vector<bool>>& chk, long& wcnt, long& bcnt) {
  chk[i][j] = true;
  if (grid[i][j] == '.') {
    wcnt++;
    for (int k = 0; k < 4; k++)
      if (grid[i + dx[k]][j + dy[k]] == '#')
        if (!chk[i + dx[k]][j + dy[k]])
          dfs(i + dx[k], j + dy[k], chk, wcnt, bcnt);
  } else if (grid[i][j] == '#') {
    grid[i][j] = '/';
    bcnt++;
    for (int k = 0; k < 4; k++)
      if (grid[i + dx[k]][j + dy[k]] == '.')
        if (!chk[i + dx[k]][j + dy[k]])
          dfs(i + dx[k], j + dy[k], chk, wcnt, bcnt);
  }
  return;
}

long count(int i, int j) {
  long wcnt = 0, bcnt = 0;
  vector<vector<bool>> chk(h + 2, vector<bool>(w + 2, false));
  dfs(i, j, chk, wcnt, bcnt);
  return wcnt * bcnt;
}

