const int Maxn = 405;
const int Maxd = 4;
const int dy[Maxd] = {-1, 0, 1, 0};
const int dx[Maxd] = {0, -1, 0, 1};

int H, W;
char B[Maxn][Maxn];
char upd[Maxn][Maxn];
ll res;

ii Get(int r, int c, char ex)
{
    if (r < 0 || r >= H || c < 0 || c >= W || upd[r][c] != ex) return ii(0, 0);
    upd[r][c] = '?';
    ii res = B[r][c] == '#'? ii(1, 0): ii(0, 1);
    for (int i = 0; i < Maxd; i++) {
        ii got = Get(r + dy[i], c + dx[i], ex);
        res.first += got.first;
        res.second += got.second;
    }
    return res;
}

int main()
{
    scanf("%d %d", &H, &W);
    for (int i = 0; i < H; i++) {
        scanf("%s", B[i]);
        for (int j = 0; j < W; j++)
            if ((i + j) % 2) upd[i][j] = B[i][j] == '#'? '.': '#';
            else upd[i][j] = B[i][j];
    }
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++) if (upd[i][j] != '?') {
            ii got = Get(i, j, upd[i][j]);
            res += ll(got.first) * got.second;
        }
    cout << res << endl;
    return 0;
}

