	{
		REP( j, W )
		{
			if ( i + 1 < H && board[i][j] != board[ i + 1 ][j] )
			{
				uf.unite( idx( i, j ), idx( i + 1, j ) );
			}
			if ( j + 1 < W && board[i][j] != board[i][ j + 1 ] )
			{
				uf.unite( idx( i, j ), idx( i, j + 1 ) );
			}
		}

	}

	map< int, int > blacks, whites;
	REP( i, H )
	{
		REP( j, W )
		{
			++( board[i][j] == '.' ? whites : blacks )[ uf.find( idx( i, j ) ) ];
		}
