            cnt0 = 0;
            cnt1 = 0;
            if(vis[i][j] != 0) continue;
            dfs(i, j);
            v.push_back(make_pair(cnt0, cnt1));
        }
    }
    int ans = 0;
    for(auto x : v){
        int a = x.first;
        int b = x.second;
        ans += a*b;
    }

    cout << ans << endl;
    return 0;
}

