int h,w;
bool inside(int i,int j)
{
    return i>=0&&i<h&&j>=0&&j<w;
}
vector<int> dx={1,-1,0,0},dy={0,0,1,-1};
int main()
{
	scanf("%i %i",&h,&w);
	vector<string> board(h);
	for(int i=0;i<h;i++)
        cin >> board[i];
    int cnt=0;
    vector<pair<int,int> > graf[h][w];
    for(int i=0;i<h;i++)
    {
        for(int j=0;j<w;j++)
        {
            for(int k=0;k<4;k++)
            {
                int xx=i+dx[k];
                int yy=j+dy[k];
                if(!inside(xx,yy))
                    continue;
                if(board[i][j]!=board[xx][yy])
                {
                    graf[i][j].pb({xx,yy});
                }
            }
        }
    }
    vector<vector<int> > visited(h,vector<int>(w));
    for(int i=0;i<h;i++)
    {
        for(int j=0;j<w;j++)
        {
            if(visited[i][j])
                continue;
            queue<pair<int,int> > q;
            q.push({i,j});
            visited[i][j]=1;
            int c1=0,c2=0;
            while(q.size())
            {
                int x=q.front().f;
                int y=q.front().s;
                if(board[x][y]=='#')
                    c1++;
                else
                    c2++;
                q.pop();
                for(auto p:graf[x][y])
                {
                    int xx=p.f;
                    int yy=p.s;
                    if(visited[xx][yy]==0)
                    {
                        visited[xx][yy]=1;
                        q.push({xx,yy});
                    }
                }
            }
            cnt+=c1*c2;
        }
    }
    printf("%i\n",cnt);
    return 0;
}

