P dir[4] = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

int main() {
    int H, W; cin >> H >> W;
    string S[H]; rep(i, H) cin >> S[i];
    ll ans = 0;
    for(int i = 0; i < H; ++i) {
        for(int j = 0; j < W; ++j) {
            if(S[i][j] == '.') continue;
            vector<vector<int>> dist(H, vector<int>(W, INF));
            dist[i][j] = 0;
            queue<P> Q;
            Q.push(mp(i, j));
            while(!Q.empty()) {
                P q = Q.front(); Q.pop();
                for(int k = 0; k < 4; ++k) {
                    int h = q.first + dir[k].first, w = q.second + dir[k].second;
                    if(h < 0 || h >= H || w < 0 || w >= W) continue;
                    if(dist[h][w] != INF) continue;
                    if(S[h][w] == ((dist[q.first][q.second] % 2 == 0) ? '#' : '.')) continue;
                    Q.push(mp(h, w));
                    dist[h][w] = dist[q.first][q.second] + 1;
                    if(dist[q.first][q.second] % 2 == 0) ++ans;
                }
            }
        }
    }
    cout << ans << endl;
}

