int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int H, W;
    cin >> H >> W;
    vector<string> s(H);
    for (int i = 0; i < H; i++)
        cin >> s[i];
    vector<vector<int>> dp(H, vector<int>(W, 0));
    int idx = 1;
    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            if (dp[i][j])
                continue;
            queue<P> q;
            dp[i][j] = idx;
            q.push(P(i, j));
            while (!q.empty())
            {
                P p = q.front();
                int x = p.first, y = p.second;
                q.pop();
                for (int k = 0; k < 4; k++)
                {
                    int nx = x + dx[k], ny = y + dy[k];
                    if (nx < 0 || H <= nx || ny < 0 || W <= ny)
                        continue;
                    if (dp[nx][ny])
                        continue;
                    if (s[nx][ny] == s[x][y])
                        continue;
                    dp[nx][ny] = idx;
                    q.push(P(nx, ny));
                }
            }
            idx++;
        }
    }
    map<ll, ll> bl, wh;
    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            int col = dp[i][j];
            if (s[i][j] == '.')
            {
                wh[col]++;
            }
            else
            {
                bl[col]++;
            }
        }
    }
    ll res = 0;
    for (auto p : bl)
    {
        ll col = p.first, num = p.second;
        res += num * wh[col];
    }
    cout << res << endl;
}

