        }
    }
    vector<pair<int,int>> dxy = {{-1,0}, {0,-1}, {1,0}, {0,1}};
    REP(i, h){
        REP(j, w){
            for(auto k : dxy){
                int x = i + k.first, y = j + k.second;
                if(x < 0 || x >= h || y < 0 || y >= w){
                    continue;
                }
                if(grid[i][j] != grid[x][y]){
                    tree.unite(i, j, x, y);
                }
            }
        }
    }
    vector<vector<pair<int,int>>> count(h, vector<pair<int,int>>(w));
    REP(i, h){
        REP(j, w){
            auto p = tree.root(i, j);
            if(grid[i][j] == '#'){
                count[p.first][p.second].first++;
            }else{
                count[p.first][p.second].second++;
            }
        }
    }
    int ans = 0;
    REP(i, h){
        REP(j, w){
            ans += count[i][j].first * count[i][j].second;
        }
    }
