        for (int j = 0; j < W; ++j) {
            if (SS[i][j] == UNCHECKED_BLACK) {
                writeCount = 0;
                blackCount = 0;
                checkAround(i, j);
                result += writeCount * blackCount;
            }

        }
    }

    cout << result << endl;

    return 0;
}

