                        if(field[a.first + 1][a.second] == '#')q.push(make_pair(a.first + 1, a.second));
                        if(field[a.first][a.second - 1] == '#')q.push(make_pair(a.first, a.second - 1));
                        if(field[a.first][a.second + 1] == '#')q.push(make_pair(a.first, a.second + 1));
                    }
                }
                ans += b * w;
            }
        }
    }
    cout << ans << endl;

    return 0;
}

