    };
    Vec dx = {1,0,-1,0,1,-1,1,-1};
    Vec dy = {0,1,0,-1,1,1,-1,-1};
    auto idx = [&](ll y, ll x) { return y*w+x; };
    UnionFind uf(h*w);
    rep(i,h){
        rep(j,w){
            char nc = g[i][j];
            rep(k,4){
                ll ni = i+dy[k];
                ll nj = j+dx[k];
