                if(g[i][j] != g[ni][nj]){
                    uf.unite(idx(i,j),idx(ni,nj));
                }
            }
        }
    }
    map<ll,ll>black;
    map<ll,ll>white;
    rep(i,h)rep(j,w){
        if(g[i][j]=='#'){
