vector<string> mapdata;


//Union-Find
//0-indexed 注意！！
struct UnionFind {
  vector< int > data;

  UnionFind(int sz) {
    data.assign(sz, -1); //ノードが属する根の番号を格納（根の場合はマイナス要素数を格納）
  }

  //併合　成功したらtrue, 既に同じ木ならfalse
  bool unite(int x, int y) {
    x = find_root(x), y = find_root(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  bool isSameGroup(int x, int y){
    x = find_root(x), y = find_root(y);
    if(x == y) return true;
    else return false;
  }

  //ノードが属する根の番号を返す（引数が根だった場合はその番号をそのまま帰す）
  int find_root(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find_root(data[k]));
  }

  //ノードが属する木に属するノードの数を返す
  int count(int k) {
    return (-data[find_root(k)]);
  }

  //木の数（接続していないグラフの数）を返す
  //根となっているノード（data[k]が負のもの）を数えるだけ
  int count_trees() {
    int ans = 0;
    rep(d_idx, data.size()){
      if (data[d_idx] < 0){
        ans += 1;
      }
    }
    return ans;
  }

  //今回だけの改造
  //「根」を見つけたら、その根が属する木に属するノード数を求める
  //ノード数が1なら、どこにも行けないマス、もしくは番兵なので無視
  //2以上なら、属する黒ノードの数、白ノードの数を確認する
  int solve() {
    vector<int> rootlist;
    rep(d_idx, data.size()){
      if (data[d_idx] < -1){
        rootlist.PB(d_idx);
      }
    }
    int ans = 0;
    int black = 0;
    int white = 0;
    int h = 0;
    int w = 0;
    for (int eachroot : rootlist){
      black = 0;
      white = 0;
      //根の分をカウント
      int root_h = eachroot / (W+2);
      int root_w = eachroot - (h * (W+2));
      if (mapdata[root_h][root_w] == '#'){
        black += 1;
      }
      else{
        white += 1;
      }
      //根以外を入れる
      rep(d_idx, data.size()){
        if (data[d_idx] == eachroot){
          h = d_idx / (W+2);
          w = d_idx - (h * (W+2));
          if (mapdata[h][w] == '#'){
            black += 1;
          }
          else if(mapdata[h][w] == '.'){
            white += 1;
          }
        }
      }
      ans += black * white;
    }
    return ans;
  }

};

