			s[i][j] = (s[i][j] == '#') ? '.' : '#';
		}
	}

	std::vector<std::vector<bool>> visited(h, std::vector<bool>(w, false));

	int ans = 0;

	REP(i, h) REP(j, w) {
		if (visited[i][j]) continue;
		visited[i][j] = true;
		char c = s[i][j];

		int cnt[2] = {1, 0};
		std::queue<PAIR> que({ PAIR(i, j) });
		while (!que.empty()) {
			PAIR now = que.front(); que.pop();
			REP(d, 4) {
				int dy = now.first + dy4[d];
				int dx = now.second + dx4[d];
				if (!IN(0, dy, h) || !IN(0, dx, w)) continue;
				if (s[dy][dx] != c) continue;
				if (visited[dy][dx]) continue;
				visited[dy][dx] = true;
				if ((dy + dx) % 2 == (i + j) % 2) ++cnt[0];
				else ++cnt[1];
				que.push(PAIR(dy, dx));
			}
		}

		ans += cnt[0] * cnt[1];
	}
	OUT(ans)BR;
	return 0;
}

