void Main()
{
	int H, W;
	std::cin >> H >> W;
	boost::multi_array<bool, 2> field(boost::extents[H][W]);
	boost::multi_array<bool, 2> flag(boost::extents[H][W]);
	boost::multi_array<int, 2> counts(boost::extents[H][W]);
	std::map<int, std::int64_t> group;
	lib::union_find uf(H*W);
	for (int i : boost::irange(0, H))
	{
		std::string str;
		std::cin >> str;
		for (int j : boost::irange(0, W))
		{
			if (str[j] == '#')
			{
				field[i][j] = true;
			}
		}
	}
	struct type
	{
		int fi, fj;
		int i, j;
		bool f;
	};
	std::stack<type> stack;
	for (int i : boost::irange(0, H))
	{
		for (int j : boost::irange(0, W))
		{
			stack.emplace(type{ i,j,i,j,field[i][j] });
		}
	}
	while (stack.size())
	{
		auto f = stack.top();
		stack.pop();
		if (f.i < 0 || f.i >= H || f.j < 0 || f.j >= W)
		{
			continue;
		}
		if (field[f.i][f.j] != f.f)
		{
			continue;
		}
		if (flag[f.i][f.j])
		{
			continue;
		}
		flag[f.i][f.j] = true;
		uf.merge(f.i*W + f.j, f.fi*W + f.fj);
		stack.emplace(type{ f.fi,f.fj,f.i + 1,f.j,!f.f });
		stack.emplace(type{ f.fi,f.fj,f.i - 1,f.j,!f.f });
		stack.emplace(type{ f.fi,f.fj,f.i,f.j + 1,!f.f });
		stack.emplace(type{ f.fi,f.fj,f.i,f.j - 1,!f.f });
	}
	for (int i : boost::irange(0, H))
	{
		for (int j : boost::irange(0, W))
		{
			if (!field[i][j])
			{
				++group[uf.group(i*W + j)];
			}
		}
	}
	auto set = uf.get();
	std::int64_t c = 0;
	for (auto const& p : set)
	{
		c += group[p.first] * (p.second.size() - group[p.first]);
	}
	out::write_line(c);
}

