int main() {
    // input(sunippets: inpv, inpn, inps)
    ll H,W;
    cin >> H >> W;
    UnionFind uf(H*W);

    char shapmap[H][W];

    FOR(i,0,H-1){
      string s; cin >> s;
      FOR(j,0,W-1){
        shapmap[i][j] = s[j];
      }
    }

    FOR(i,0,H-1){
      FOR(j,0,W-1){
        if(i==H-1){
          if(j!=W-1){
            if(shapmap[i][j]!=shapmap[i][j+1]) uf.merge(i*W+j, i*W+j+1);
          }
        } else if(j==W-1){
          if(shapmap[i][j]!=shapmap[i+1][j]) uf.merge(i*W+j, (i+1)*W+j);
        } else {
          if(shapmap[i][j]!=shapmap[i+1][j]) uf.merge(i*W+j, (i+1)*W+j);
          if(shapmap[i][j]!=shapmap[i][j+1]) uf.merge(i*W+j, i*W+j+1);
        }
      }
    }


    map<ll,ll> bombnum;

    FOR(i,0,H-1){
      FOR(j,0,W-1){
        if(shapmap[i][j]=='#') ++bombnum[uf.root(i*W+j)];
      }
    }
    ll ans = 0;
    FOR(i,0,H-1){
      FOR(j,0,W-1){
        if(!visited[uf.root(i*W+j)]){
          if(uf.size(i*W+j)>1){
            ans += bombnum[uf.root(i*W+j)] * (uf.size(i*W+j) - bombnum[uf.root(i*W+j)]);
          } 
          visited[uf.root(i*W+j)] = true;
        }
      }
    }

    cout << ans << endl;

    return 0;
}

