void rec(int y, int x, int &white, int &black, const int H, const int W) {
  int dx[4] = {1, 0, -1, 0};
  int dy[4] = {0, 1, 0, -1};
  for (int i = 0; i < 4; ++i) {
    int xx = x + dx[i];
    int yy = y + dy[i];
    if (0 <= xx && xx < W && 0 <= yy && yy < H) {
      if (c[y][x] + c[yy][xx] == 1) {
        if (c2[yy][xx] == 0) {
          c2[yy][xx] = 1;
          if (c[yy][xx] == 1) black++;
          else white++;
          rec(yy, xx, white, black, H, W);
        }
      }
    }
  }
}

int solve(int y, int x, const int H, const int W) {
  int white = 0, black = 0;
  c2[y][x] = 1;
  if (c[y][x] == 1) black++;
  else white++;
  rec(y, x, white, black, H, W);
  return white * black;
}

