  int ans = 0;
  for (int i = 0; i < H; ++i) {
    for (int j = 0; j < W; ++j) {
      if (c2[i][j] == 0) {
        ans += solve(i, j, H, W);
      }
    }
  }
  cout << ans << endl;
}

