class UnionFind {
public:
    vector<int> par;
    vector<ll> white;
    UnionFind(int n) {
        par.resize(n);
        white.resize(n, 0);
        REP(i, 0, n) {
            par[i] = i;
        }
    }
    int Find(int n) {
        return (n == par[n] ? n : par[n] = Find(par[n]));
    }
    bool Union(int a, int b, bool at, bool bt) {
        a = Find(a);
        b = Find(b);
        if (a == b) return false;
        par[a] = b;
        if (at && white[a] == 0) {
            white[a]++;
        }
        if (bt && white[b] == 0) {
            white[b]++;
        }
        white[a] += white[b];
        white[b] = white[a];
        return true;
    }
    ll getWhite(int n) {
        return white[Find(n)];
    }
};

int main() {
    cin.tie(nullptr);
