        }
    }
    UnionFind uf(H * W);
    int dx[4] = {0, 1, 0, -1}, dy[4] = {1, 0, -1, 0};
    REP(i, 0, H) {
        REP(j, 0, W) {
            REP(k, 0, 4) {
                int nx = j + dx[k], ny = i + dy[k];
                if (nx < 0 || nx >= W || ny < 0 || ny >= H || mp[ny][nx] == mp[i][j]) continue;
                uf.Union(i * W + j, ny * W + nx, mp[i][j] == '.', mp[ny][nx] == '.');
            }
        }
    }

    ll ans = 0;
    REP(i, 0, H) {
        REP(j, 0, W) {
            if (mp[i][j] == '#') {
                ans += uf.getWhite(i * W + j);
            }
        }
    }

    cout << ans << endl;

    return 0;
}

