ll bfs(int startX, int startY) {
    if (used[startY][startX]) return 0;
    ll black = 0, white = 0;
    queue<pair<int, int>> que;
    que.push(make_pair(startX, startY));
    used[startY][startX] = true;
    while (que.size() > 0) {
        int x = que.front().first;
        int y = que.front().second;
        que.pop();
        if (S[y][x] == '#') {
            black++;
        } else {
            white++;
        }
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (!withinArea(nx, ny)) continue;
            if (used[ny][nx]) continue;
            if (S[y][x] == S[ny][nx]) continue;
            que.push(make_pair(nx, ny));
            used[ny][nx] = true;
        }
    }
    return black * white;
}

bool withinArea(int x, int y) {
    return 0 <= x && x < W && 0 <= y && y < H;
}

