class UnionFind {
  vector<int> par, rank, potential;
public:
  UnionFind(int n) {
    par.resize(n, -1);
    rank.resize(n, 0);
    potential.resize(n, 0);
  }
  int root(int x) {
    if (par[x] < 0)
      return x;
    int r = root(par[x]);
    potential[x] += potential[par[x]];
    return par[x] = r;
  }
  int size(int x) {
    return -par[root(x)];
  }
  int weight(int x) {
    root(x);
    return potential[x];
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  bool unite(int x, int y, int w = 0) {
    w += weight(x);
    w -= weight(y);
    x = root(x);
    y = root(y);
    if (x == y) {
      return false;
    }
    if (rank[x] < rank[y]) {
      swap(x, y);
      w = -w;
    }
    if (rank[x] == rank[y])
      rank[x]++;
    par[x] += par[y];
    par[y] = x;
    potential[y] = w;
    return true;
  }
  int diff(int x, int y) {
    return weight(y) - weight(x);
  }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int h, w;
  cin >> h >> w;
  vector<string> grid(h);
  rep(i, h) cin >> grid[i];
  UnionFind uf(h*w);
  rep(i, h) rep(j, w) {
    if (i+1<h && grid[i+1][j] != grid[i][j])
      uf.unite(w*i+j, w*(i+1)+j);
    if (j+1<w && grid[i][j+1] != grid[i][j])
      uf.unite(w*i+j, w*i+(j+1));
  }
  map<int, pair<int, int>> mp;
  rep(i, h) rep(j, w) {
    if (grid[i][j] == '#')
      mp[uf.root(w*i+j)].first++;
    else
      mp[uf.root(w*i+j)].second++;
  }
  int ans = 0;
  for (auto e : mp) {
    int black, white;
    tie(black, white) = e.second;
    ans += black*white;
  }
  cout << ans << endl;
  return 0;
}

