        int ny = y + dy[i];

//        cout << ny << ' ' << nx << " " << s[ny][nx] << endl;

        if (used[ny][nx])continue; // already used
        if (nx < 0 || ny < 0 || nx >= w || ny >= h)continue; // invalid area
        if (s[ny][nx] == s[y][x])continue; // '#' => '.' -> '#' ... : not same char

        dfs(ny, nx, w, h);
    }

}


