    if (x+1<=h-1) {if (nm[x+1][y]==0 and bw[x+1][y]==tmp) area_make(x+1,y,gr);}
    if (y-1>=0)   {if (nm[x][y-1]==0 and bw[x][y-1]==tmp) area_make(x,y-1,gr);}
    if (y+1<=w-1) {if (nm[x][y+1]==0 and bw[x][y+1]==tmp) area_make(x,y+1,gr);}
}

