ll a[401][401];
ll H,W;
queue<pair<ll,ll> > q;
ll used[401][401];
ll dx[4]={1,-1,0,0};
ll dy[4]={0,0,1,-1};

bool inside(ll x, ll y, ll i) {
    return (x + dx[i] < H && x + dx[i] >= 0 && y + dy[i] >= 0 && y + dy[i] < W);
}

bool check(ll x,ll y, ll i) {
    if (!inside(x, y, i)) return false;
    return a[x + dx[i]][y + dy[i]] != a[x][y];
}

ll solve() {
    ll ans = 0;
    for (ll i = 0; i < H; i++) {
        for (ll j = 0; j < W; j++) {
            if (used[i][j]) continue;
            ll b = 0, w = 0;//b-black a-WHite
            used[i][j] = 1;
            q.push({i, j});
            while (!q.empty()) {
                pair<ll, ll> r = q.front();
                q.pop();
                ll x = r.first;
                ll y = r.second;
                if (a[x][y]) b++;
                else w++;
                for (ll d = 0; d < 4; d++) {
                    if (!check(x, y, d)) continue;//invalid move
                    if (used[x + dx[d]][y + dy[d]]) continue;
                    used[x + dx[d]][y + dy[d]] = 1;
                    q.push({x + dx[d], y + dy[d]});
                }
            }
            ans += b * w;
        }
    }
    return ans;
}

int run() {
    cin>>H>>W;
    for(ll i=0;i<H;i++){
        for(ll j=0;j<W;j++){
            char cH;
            cin>>cH;
            a[i][j]=(cH=='#');
        }
    }
    memset(used,0,sizeof(used));
    ll ans=solve();
    cout<<ans;
}

