//(x,y)から任意のマスにいけるかどうかを調べる関数
void search(ll x, ll y) {
	//マスが範囲外のときスルー
	if (x < 0 || y < 0 || x >= h || y >= w)return;
	//一度調べてあるときもスルー
	if (b[x][y])return;
	if (a[x][y] == '.') {
		b[x][y] = true; ans++;
	}
	//上下左右に隣り合うマスを続けて調べる
	if (a[x][y] != a[x][y - 1])search(x, y - 1);
	if (a[x][y] != a[x - 1][y])search(x - 1, y);
	if (a[x][y] != a[x + 1][y])search(x + 1, y);
	if (a[x][y] != a[x][y + 1])search(x, y + 1);
}
