typedef pair<ll, ll> pll;

int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, -1, 0, 1};
int Y, X;

pll dfs(int y, int x, vector<vector<char>> G, ll &w, ll &b,
        vector<vector<bool>> &seen) {
    seen[y][x] = true;
    if (G[y][x] == '#')
        b++;
    else
        w++;
    for (int i = 0; i < 4; i++) {
        int nx = x + dx[i];
        int ny = y + dy[i];
        if (nx < 0 || ny < 0 || nx >= X || ny >= Y)
            continue;
        if (seen[ny][nx])
            continue;
        if (G[ny][nx] == G[y][x])
            continue;
        dfs(ny, nx, G, w, b, seen);
    }

    return {w, b};
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> Y >> X;
    vector<vector<char>> G(Y, vector<char>(X));
    rep(i, Y) {
        rep(j, X) { cin >> G[i][j]; }
    }

    vector<vector<bool>> seen(Y, vector<bool>(X, false));
    ll ans = 0;
    rep(i, Y) {
        rep(j, X) {
            if (seen[i][j])
                continue;
            else {
                ll w = 0, b = 0;
                pll p = dfs(i, j, G, w, b, seen);
                ans += (p.first * p.second);
            }
        }
    }

    cout << ans << endl;
}

