/* constant */
const int INF = 1 << 30;
const ll LINF = 1LL << 50;
const int NIL = -1;
const int MAX = 405;
const int mod = 1000000007;
const double pi = 3.141592653589;
/* global variables */
int H, W;
vector<vector<int> > m(MAX, vector<int>(MAX, 0));
vector<vector<int>> visited(MAX, vector<int>(MAX, 0));
vector<int> dx{0, 0, 1, -1}, dy{1, -1, 0, 0};
/* function */
ll bfs(int sx, int sy) {
    visited[sx][sy] = 1;
    queue<pii> q;
    q.push(pii(sx, sy));
    vector<ll> cnt(2);
    while (!q.empty()) {
        pii p = q.front(); q.pop();
        int x = p.first, y = p.second;
        cnt[m[x][y]]++;
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx < 0 || H <= nx || ny < 0 || W <= ny) continue;
            if (visited[nx][ny]) continue;
            if (m[x][y] == m[nx][ny]) continue;
            visited[nx][ny] = 1;
            q.push(pii(nx, ny));
        }
    }
    return cnt[0] * cnt[1];
}
/* main */
int main(){
    cin >> H >> W;
    for (int i = 0; i < H; i++) {
        string S;
        cin >> S;
        for (int j = 0; j < W; j++) m[i][j] = (S[j] == '#' ? 1 : 0);
    }

    ll ans = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (!visited[i][j]) {
                ans += bfs(i, j);
            }
        }
    }
    cout << ans << '\n';
}

