int numB = 0, numC = 0;

void dfs(int x, int y){
   visited[x][y] = 1;
   if(clr[x][y] == '#') numB++;
   else numC++;
   if(x+1 < H && visited[x+1][y] == 0 && clr[x][y] != clr[x+1][y]){
      dfs(x+1, y);
   }
   if(x > 0 && visited[x-1][y] == 0 && clr[x][y] != clr[x-1][y]){
