   }
   if(y+1 < W && visited[x][y+1] == 0 && clr[x][y] != clr[x][y+1]){
      dfs(x, y+1);
   }
   if(y > 0 && visited[x][y-1] == 0 && clr[x][y] != clr[x][y-1]){
      dfs(x, y-1);
   }
}

