#include <bits/stdc++.h>
using namespace std;

const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};

string G[400];
bool seen[400][400];
bool seen2[400][400];
int H, W, cnt_w, cnt_b, ans = 0;

void dfs(int h, int w) {
    seen[h][w] = true;
    if (G[h][w] == '#') seen2[h][w] = true;

    for (int dir = 0; dir < 4; ++dir) {
        int nh = h + dx[dir];
        int nw = w + dy[dir];

        if (nh < 0 || nh >= H || nw < 0 || nw >= W) continue;
        if (G[nh][nw] == G[h][w]) continue;

        if (seen[nh][nw]) continue;

        if (G[nh][nw] == '.') cnt_w++;
        else cnt_b++;
        dfs(nh, nw);
    }

    return;
}

int main() {
    cin >> H >> W;
    for (int h = 0; h < H; h++) cin >> G[h];

    for (int h = 0; h < H; h++) {
        for (int w = 0; w < W; w++) {
            if (G[h][w] == '#' && !seen2[h][w]) {
                cnt_b = 1;
                cnt_w = 0;
                dfs(h, w);
                ans += cnt_b * cnt_w;
            }
        }
    }
    cout << ans << endl;
}

