            int nh = next.first;
            int nw = next.second;
            if (board[nh][nw] == XX) continue;
            ++count[board[nh][nw]];

            if (nh-1 >= 0 && board[nh-1][nw] == !board[nh][nw]) nexts.push(make_pair(nh-1, nw));
