            if (nw-1 >= 0 && board[nh][nw-1] == !board[nh][nw]) nexts.push(make_pair(nh, nw-1));
            if (nw+1 <  W && board[nh][nw+1] == !board[nh][nw]) nexts.push(make_pair(nh, nw+1));

            board[nh][nw] = XX;
        }

        ret += count[WH]*count[BL];
