int blackCount;

const int UNCHECKED_BLACK = 0;
const int CHECKED_BLACK = 1;
const int UNCHECKED_WRITE = -1;
const int CHECKED_WRITE = -2;
const int OUT_OF_AREA = -3;


void checkAroundByBlack(int x, int y);

int checkBlock(int x, int y) {

    if (x < 0 || x >= H) {
        return OUT_OF_AREA;
    }
    if (y < 0 || y >= W) {
        return OUT_OF_AREA;
    }

    return SS[x][y];
}


//白に隣接している黒をチェック
//調べ済みの黒は調べない
void checkAroundByWrite(int x, int y) {

    if(SS[x][y] != UNCHECKED_WRITE){
        return;
    }
    writeCount++;
    SS[x][y] = CHECKED_WRITE;

    if (checkBlock(x - 1, y) == UNCHECKED_BLACK) {
        checkAroundByBlack(x - 1, y);
    }
    if (checkBlock(x + 1, y) == UNCHECKED_BLACK) {
        checkAroundByBlack(x + 1, y);
    }
    if (checkBlock(x, y - 1) == UNCHECKED_BLACK) {
        checkAroundByBlack(x, y - 1);
    }
    if (checkBlock(x, y + 1) == UNCHECKED_BLACK) {
        checkAroundByBlack(x, y + 1);
    }
}

//黒に隣接している白をチェック。
//調べ済みの白は調べない
void checkAroundByBlack(int x, int y) {

    if(SS[x][y] != UNCHECKED_BLACK){
        return;
    }
    blackCount++;
    SS[x][y] = CHECKED_BLACK;

    if (checkBlock(x - 1, y) == UNCHECKED_WRITE) {
        checkAroundByWrite(x - 1, y);
    }
    if (checkBlock(x + 1, y) == UNCHECKED_WRITE) {
        checkAroundByWrite(x + 1, y);
    }
    if (checkBlock(x, y - 1) == UNCHECKED_WRITE) {
        checkAroundByWrite(x, y - 1);
    }
    if (checkBlock(x, y + 1) == UNCHECKED_WRITE) {
        checkAroundByWrite(x, y + 1);
    }
}

