    for (int i = 0; i < H; ++i) {
        string S;
        cin >> S;
        for (int j = 0; j < W; ++j) {
            int s;
            if (S[j] == '#') {
                s = UNCHECKED_BLACK;
            }
            if( S[j] == '.'){
                s = UNCHECKED_WRITE;
            }
            SS[i][j] = s;
        }
    }
    int result = 0;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (SS[i][j] == UNCHECKED_BLACK) {
                writeCount = 0;
                blackCount = 0;
                checkAroundByBlack(i, j);
                result += writeCount * blackCount;
            }
            if (SS[i][j] == UNCHECKED_WRITE) {
                writeCount = 0;
                blackCount = 0;
                checkAroundByWrite(i, j);
                result += writeCount * blackCount;
            }

        }
    }

    cout << result << endl;

