struct UnionFind {
  vector<ll> par, siz;
  UnionFind(ll n):par(n),siz(n,1) {
    for (ll i = 0; i < n; ++i) par[i] = i;
  }
  ll size() { return par.size(); };
  ll root(ll x) {
    assert(x < size());
    if (par[x] == x) return x;
    else return par[x] = root(par[x]);
  }
  void merge(ll x, ll y) {
    assert(x < size());
    assert(y < size());
    ll rx = root(x);
    ll ry = root(y);
    if (rx == ry) return;
    if (siz[rx] < siz[y]) std::swap(rx, ry);
    par[rx] = ry;
    siz[ry] += siz[rx];
  }
  bool same(ll x, ll y) { 
    assert(x < size());
    assert(y < size());
    return root(x) == root(y);
  }
  ll size(ll x) {
    assert(x < size());
    return siz[root(x)];
  }
};

int dx[8] = {-1, 0, 1, 0, -1, 1, -1, 1};
int dy[8] = {0, -1, 0, 1, -1, -1, 1, 1};

int main() {
  std::cin.tie(nullptr);
  std::ios_base::sync_with_stdio(false);
  std::cout << std::fixed << std::setprecision(15);
  int h,w;
  cin >> h >> w;
  vector<string> S(h);
  rep(i,h) cin >> S[i];

  UnionFind tree(h*w);
  rep(y,h) rep(x,w) {
    if (S[y][x] == '#') {
      int ind = w*y + x;
      for (int i = 4; i < 8; ++i) {
        int nx = x + dx[i];
        int ny = y + dy[i];
        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
        if (S[ny][nx] == '#' && (S[ny][x] == '.' || S[y][nx] == '.')) {
          int ind2 = w*ny + nx;
          if (!tree.same(ind, ind2)) tree.merge(ind, ind2);
        }
      }
    }
  }
  unordered_map<int,ll> union_cnt;
  vector<vector<int> > A(h*w);
  rep(y,h) rep(x,w) {
    if (S[y][x] == '#') {
      int ind = w*y + x;
      union_cnt[tree.root(ind)]++;
      rep(i,4) {
        int nx = x + dx[i];
        int ny = y + dy[i];
        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
        if (S[ny][nx] == '.') {
          int ind2 = w*ny + nx;
          A[tree.root(ind)].emplace_back(ind2);
        }
      }
    }
  }
  ll ans = 0;
  rep(i,h*w) {
    if (A[i].size() == 0) continue;
    vector<bool> checked(h*w,false);
    ll cnt = 0;
    for (auto x : A[i]) {
      if (!checked[x]) {
        cnt++;
        checked[x] = true;
      }
    }
    ans += union_cnt[i] * cnt;
  }
  cout << ans << endl;
  return 0;
}

