  int a = S[i-1][j-1]=='.';
  visited[i][j]=1;
  times(4, d) {
    int ii = i + dx[d], jj = j + dy[d];
    if(w[i][j] == w[ii][jj]) a += dfs(ii, jj);
  }
  return a;
}
int dfs2(int i, int j) {
  if(visited2[i][j])return 0;
  int a = S[i-1][j-1]=='#';
