vector<vector<set<pair<int,int>>>> memo;
LL calc(vector<string>& vec, int i,int j){
    queue<pair<int,int>> que;
    que.push(make_pair(i,j));
    LL ans=0;
    vector<vector<bool>> flag(vec.size(), vector<bool>(vec.front().size(),false));
    int dx[] = {1,0,-1,0};
    int dy[] = {0,1,0,-1};
    set<pair<int,int>> ins_ans;
    while(!que.empty()){
        P p = que.front();
        que.pop();
        if(flag.at(p.first).at(p.second))continue;
        if(!memo.at(p.first).at(p.second).empty()){
            for(auto w:memo.at(p.first).at(p.second))ins_ans.insert(w);
        }
        flag.at(p.first).at(p.second) = true;
      //  COUT(ans);
        if(vec.at(p.first).at(p.second) == '.'){
            ins_ans.insert(p);
        }
        for(int index = 0;index < 4;index++){
            int x = p.first+dx[index];
            int y = p.second+dy[index];
            if(0<=x && x <= vec.size()-1 &&0 <= y && y <= vec.front().size()-1){
                if(vec.at(p.first).at(p.second)!=vec.at(x).at(y)){
                    que.push(make_pair(x,y));
                }
            }
        }
    }
    memo.at(i).at(j) = ins_ans;
    return ins_ans.size();
}
