typedef long long ll;
int n,m;
char s[555][555];
int vis[555][555];
int c1,c2;
queue<pair<int,int>> q;
int main(){
    scanf("%d%d",&n,&m);
    for(int i=0;i<n;i++){
        scanf("%s",&s[i]);
    }
    long long ans = 0;
    for(int i=0;i<n;i++){
        for(int j=0;j<m;j++){
            if(s[i][j]=='#'&&!vis[i][j]){
                c1=0,c2=0;
                q.push(mk(i,j));
                vis[i][j]=1;
                while (!q.empty()){
                    int x = q.front().first;
                    int y = q.front().second;
                    q.pop();
                    int now = s[x][y];
                    if(now=='.') {
                        c1++;
                    } else{
                        c2++;
                    }
                    if(x-1>=0&&s[x-1][y]!=now&&!vis[x-1][y]){
                        vis[x-1][y]=1;
                        q.push(mk(x-1,y));
                    }
                    if(x+1<n&&s[x+1][y]!=now&&!vis[x+1][y]){
                        vis[x+1][y]=1;
                        q.push(mk(x+1,y));
                    }
                    if(y-1>=0&&s[x][y-1]!=now&&!vis[x][y-1]){
                        vis[x][y-1]=1;
                        q.push(mk(x,y-1));
                    }
                    if(y+1<m&&s[x][y+1]!=now&&!vis[x][y+1]){
                        vis[x][y+1]=1;
                        q.push(mk(x,y+1));
                    }
                }
                ans+=c1*c2;
            }
        }
    }
    printf("%d\n",ans);
}

