const int dh[] = {-1, 0, 1, 0};
const int dw[] = {0, -1, 0, 1};

int main() {
    cin.tie(0); ios::sync_with_stdio(false);
    int h, w; cin >> h >> w;
    vector<vector<char>> mat(h, vector<char>(w));
    rep(i, h) rep(j, w) cin >> mat[i][j];

    set<P> done;
    ll ans = 0;
    rep(i, h) rep(j, w) {
        if (mat[i][j]=='#') {
            if (done.count({i, j})) continue;
            vector<vector<int>> dist(h, vector<int>(w, -1));
            dist[i][j] = 0;
            queue<P> que;
            que.push({i, j});
            ll par = 1ll;
            ll cnt = 0;
            while (!que.empty()) {
                P p = que.front(); que.pop();
                char c = mat[p.fi][p.se];
                rep(i, 4) {
                    int nh = p.fi+dh[i], nw = p.se+dw[i];
                    if (nh<0||nh>h-1||nw<0||nw>w-1) continue;
                    if (dist[nh][nw]!=-1) continue;
                    if (mat[nh][nw]==c) continue;
                    dist[nh][nw] = dist[p.fi][p.se] + 1;
                    if (mat[nh][nw]=='#') {
                        par++;
                        done.insert({nh, nw});
                    }
                    que.push({nh, nw});
                    if (dist[nh][nw]%2==1) cnt++;
                }
            }
            ans += cnt*par;
            print(dist);
        }
    }
    cout << ans << endl;
}

