bool visited[405][405];
int main() {
  int h,w; cin >> h >> w;
  vector<string> maze(h);
  rep(i,h) cin >> maze[i];

  vii groups;
  auto bfs = [&](ii xy) {
    int black = 0, white = 0;
    queue<ii> q;
    q.push(xy);
    visited[xy.second][xy.first] = true;
    while (q.size()) {
      int x = q.front().first;
      int y = q.front().second;
      q.pop();
      if (maze[y][x] == '#') black++;
      else white++;
      int dx[] = {0,1,0,-1};
      int dy[] = {1,0,-1,0};
      rep(i, 4) {
        int nx = x+dx[i];
        int ny = y+dy[i];
        if ( ny<0 || ny >= h || nx < 0 || nx >= w || visited[ny][nx]) continue;
        if (maze[y][x] == maze[ny][nx]) continue;
        q.emplace(nx, ny);
        visited[ny][nx] = true;
      }
    }
    groups.emplace_back(black, white);
  };

  rep(i,h) rep(j,w) {
    if (!visited[j][i]) {
      bfs({j,i});
    }
  }

  ll ans = 0;
