void dfs(vector<string> &s, vector<vector<bool>> &visited, int i, int j, ll &tmpb, ll &tmpw, int h, int w) {
    if (s.at(i).at(j) == '.') tmpw++;
    else tmpb++;
    for (int k=0; k<4; k++) {
        int nx = i + dx[k], ny = j + dy[k];
        if (nx < 0 || nx >= h || ny < 0 || ny >= w) continue;
        if (!visited.at(nx).at(ny) && s.at(i).at(j) != s.at(nx).at(ny)) {
            visited.at(nx).at(ny) = true;
            dfs(s, visited, nx, ny, tmpb, tmpw, h, w);
        }
    }
