  rep(i,h) cin >> s[i];
  map<int,ll> cnt;
  UnionFind uf(h * w);
  auto calc = [&](int i, int j){
    for (int k = 0; k < 2; k++) {
      int x = i + dx[k], y = j + dy[k];
      if (x >= h || y >= w) continue;
      if (uf.same(i * w + j. x * w + y)) continue;
      if (s[x][y] == s[i][j]) continue;
      uf.unite(i * w + j, x * w + y);
    }
  };
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      calc(i, j);
      if (s[i][j] == '#') cnt[uf.find(i * w + j)]++;
    }
  }
  ll res = 0;
  rep(i,h) rep(j,w) if (s[i][j] == '#') res += (uf.size(i * w + j) - cnt[uf.find(i * w + j)]);
  cout << res << endl;
  return 0;
}

