    queue<pos> Q;
    Q.push(make_tuple(x,y,c));
    visited[x][y] = cnt;
    while(!Q.empty()){
        auto cur = Q.front();
        Q.pop();
        char pc = get<2>(cur);
        for(int k=0;k<4;k++){
            int nx = get<0>(cur) + dx[k];
            int ny = get<1>(cur) + dy[k];

