struct UnionFind{
    vector<int> par; // par[i]:iの親の番号
    vector<int> s; // s[i]:iの属する木のノード数
    int n_group; // 木の数

    UnionFind(int N) : par(N) {
        for(int i=0; i<N; i++) par[i] = i;
        s.assign(N, 1);
        n_group = N;
    }

    int root(int x){ // xが属する木の根
        if(par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y){ // xとyの木を併合
        int rx = root(x);
        int ry = root(y);
        if(rx == ry) return;
        par[rx] = ry;
        s[ry] += s[rx];
        s[rx] = 0;
        n_group--;
    }

    bool same(int x, int y){ // xとyが同じ木に属するかどうか
        return root(x) == root(y);
    }

    int size(int x){ // xが属する木のノード数
        return s[root(x)];
    }
};

int main(void){
    int H,W; cin >> H >> W;
    VS S(H); REP(i,H) cin >> S[i];
    int n[H][W];
    int t = 0;
    REP(i,H)REP(j,W) n[i][j] = t++;
    UnionFind uf(H*W);
    REP(i,H)REP(j,W){
        if(S[i][j] == '.') continue;
        if(i && S[i-1][j] == '.') uf.unite(n[i][j], n[i-1][j]);
        if(j && S[i][j-1] == '.') uf.unite(n[i][j], n[i][j-1]);
        if(i<H-1 && S[i+1][j] == '.') uf.unite(n[i][j], n[i+1][j]);
        if(j<W-1 && S[i][j+1] == '.') uf.unite(n[i][j], n[i][j+1]);
    }

    VI g(H*W,0);
    REP(i,H)REP(j,W){
        if(S[i][j] == '#') continue;
        int r = uf.root(n[i][j]);
        g[r]++;
    }
    ll ans = 0;
    REP(i,H)REP(j,W){
        if(S[i][j] == '.') continue;
        int r = uf.root(n[i][j]);
        ans += g[r];
    }

    cout << ans << endl;
    return 0;
}

