int par[SQR(MAX)];

int GetPar(int vr){
  return par[vr] == vr ? vr : par[vr] = GetPar(par[vr]);
}

void Merge(int a, int b){
  a = GetPar(a);
  b = GetPar(b);
  par[a] = b;
}

int h, w;
char in[MAX][MAX];
int id[MAX][MAX];

vector<pii> dlt = {mp(-1, 0), mp(+1, 0),
                   mp(0, -1), mp(0, +1)};

