      id[i][j] = t++;

  for(int i = 0;i < h;++i)
    for(int j = 0;j < w;++j)
      for(const auto& d : dlt){
        int ii = i + d.fi;
        int jj = j + d.se;
        if(ii >= 0 && jj >= 0 &&
           ii < h && jj < w &&
           in[i][j] != in[ii][jj]){
          Merge(id[i][j], id[ii][jj]);
        }
      }

  vector<pair<ll, ll>> ans(w * h);
  for(int i = 0;i < h;++i)
    for(int j = 0;j < w;++j)
      if(in[i][j] == '.') ++ans[GetPar(id[i][j])].fi;
      else ++ans[GetPar(id[i][j])].se;

  ll total = 0;
  for(int i = 0;i < w * h;++i)
    total += ans[i].fi * ans[i].se;

  cout << total << '\n';

  return 0;
}

