class UF
{
private:
	vector<int> root;
	vector<long long int> black;
	vector<long long int> white;

public:
	UF(int n)
	{
		root = vector<int>(n, -1);
		black = vector<long long int>(n, 0);
		white = vector<long long int>(n, 0);
	}

	int getRoot(int x)
	{
		if(root[x] == -1) return x;
		else return root[x] = getRoot(root[x]);
	}

	long long int getBlack(int x)
	{
		return black[getRoot(x)];
	}

	long long int getWhite(int x)
	{
		return white[getRoot(x)];
	}

	void update(int x, int y)
	{
		x = getRoot(x);
		y = getRoot(y);
		if(x == y) return;
		if(x > y) swap(x, y);
		root[y] = x;
		black[x] += black[y];
		white[x] += white[y];
	}

	void addBlack(int x)
	{
		black[getRoot(x)]++;
	}

	void addWhite(int x)
	{
		white[getRoot(x)]++;
	}

};

