int N, M;
string S[410];
bool used[410][410];

int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, 1, 0, -1};

void solve() {
	cin >> N >> M;
	rep(i, 0, N) cin >> S[i];
	queue<pi> que;
	ll res = 0;
	rep(i, 0, N) {
		rep(j, 0, N) {
			if(used[i][j]) continue;
			int b = 0;
			int w = 0;
			que.push(pi(i, j));
			used[i][j] = true;
			while(!que.empty()) {
				pi p = que.front(); que.pop();
				if(S[p.fst][p.sec] == '.') w++;
				else b++;
				rep(k, 0, 4) {
					int nx = dx[k] + p.fst, ny = dy[k] + p.sec;
					if(0 <= nx && nx < N && 0 <= ny && ny < M) {
						if(!used[nx][ny] && S[p.fst][p.sec] != S[nx][ny]) {
							used[nx][ny] = true;
							que.push(pi(nx, ny));
						}
					}
				}

			}
			res += 1ll * w * b;
		}
	}
	cout << res << "\n";
}

