const int N = 405;
const int dx[] = {0, 1, 0, -1};
const int dy[] = {1, 0, -1, 0};

char grd[N][N];
int h, w, dot, hsh, vst[N][N];

bool boundary(int i, int j) {
  return (i >= 0 && i < h) && (j >= 0 && j < w);
}

void dfs(int i, int j) {
  vst[i][j] = 1;
  if (grd[i][j] == '.') dot++;
  else hsh++;
  for (int k = 0; k < 4; k++) {
    int x = i + dx[k];
    int y = j + dy[k];
    if (boundary(x, y)) {
      if (vst[x][y] == 0 && grd[i][j] != grd[x][y]) dfs(x, y);
    }
  }
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cin >> h >> w;
  long long ans = 0;
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      cin >> grd[i][j];
    }
  }
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (!vst[i][j]) {
        dot = hsh = 0;
        dfs(i, j);
        ans += (dot * hsh);
      }
    }
  }
  cout << ans << '\n';
  return 0;
}

