using namespace std;

struct pa{
  int i, j;
  pa(int _i, int _j) : i(_i), j(_j) {}
};

long long search(vector<vector<int> >& v, int si, int sj){
  stack<pa> st = stack<pa>();
  st.push(pa(si, sj));
  v[si][sj] += 2;
  while(true){
    if (st.empty()){
      long long b=0, w=0;
      for(int i = 0; i < v.size(); ++i){
        for(int j = 0; j < v[i].size(); ++j){
          if (v[i][j] == 2){
            ++b;
            v[i][j] = 4;
          }else if (v[i][j] == 3){
            ++w;
            v[i][j] = 4;
          }
        }
      }
      return b*w;
    }
    stack<pa> st2 = stack<pa>();
    while(! st.empty()){
      pa pt = st.top();
      st.pop();
      int nextcolor;
      if (v[pt.i][pt.j] == 2)
        nextcolor = 1;
      else if (v[pt.i][pt.j] == 3)
        nextcolor = 0;
      else
        continue;
      if (pt.i != 0 && v[pt.i-1][pt.j] == nextcolor){
        st2.push(pa(pt.i-1, pt.j));
        v[pt.i-1][pt.j] += 2;
      }
      if (pt.j != 0 && v[pt.i][pt.j-1] == nextcolor){
        st2.push(pa(pt.i, pt.j-1));
        v[pt.i][pt.j-1] += 2;
      }
      if (pt.i != v.size()-1 && v[pt.i+1][pt.j] == nextcolor){
        st2.push(pa(pt.i+1, pt.j));
        v[pt.i+1][pt.j] += 2;
      }
      if (pt.j != v[0].size()-1 && v[pt.i][pt.j+1] == nextcolor){
        st2.push(pa(pt.i, pt.j+1));
        v[pt.i][pt.j+1] += 2;
      }
    }
    st = st2;
  }
}

int main(void){
  int h, w;
  cin >> h >> w;
  vector<vector<int> > v = vector<vector<int> >();
  v.reserve(h);
  for(int i = 0; i < h; ++i){
    string str;
    cin >> str;
    vector<int> vv = vector<int>();
    vv.reserve(w);
    for(int j = 0; j < w; ++j){
      vv.push_back(str[j] == '#' ? 0 : 1);
    }
    v.push_back(vv);
  }
  long long sum = 0;
  while(true){
    bool found = false;
    for(int i = 0; i < h; ++i){
      for(int j = 0; j < w; ++j){
        if (v[i][j] == 0){
          found = true;
          sum += search(v, i, j);
        }
      }
    }
    if (! found)
      break;
  }
  cout << sum << endl;
  return 0;
}

