typedef pair<long long,P>PP;
typedef pair<P,P>PPP;

const long long MOD=1e9+7;
const long long INF=5e18;
const int di[4]={1,0,-1,0};
const int dj[4]={0,1,0,-1};

#define fr first
#define sc second
#define pb push_back
#define eb emplace_back
#define ALL(x) (x).begin(),(x).end()
#define ALLR(x) (x).rbegin(),(x).rend()

int h,w;
ll d[410][410],ans;
string s[410];

bool c(int i,int j){
	if(i>=0&&i<h&&j>=0&&j<w)return true;
	return false;
}

void dfs(int ii,int jj){
	d[ii][jj]=1;
	queue<P>q;
	ll w=0,b=1;
	q.push(P(ii,jj));
	while(!q.empty()){
		P p=q.front();
		q.pop();
		for(int i=0;i<4;i++){
			int ni=p.fr+di[i],nj=p.sc+dj[i];
			if(!c(ni,nj))continue;
			if(d[ni][nj])continue;
			if(s[p.fr][p.sc]!=s[ni][nj]){
				if(s[ni][nj]=='.')w++;
				else b++;
				q.push(P(ni,nj));
				d[ni][nj]=1;
			}
		}
	}
	ans+=w*b;
	return;
}

void input(){
	cin>>h>>w;
	for(int i=0;i<h;i++)cin>>s[i];
	return;
}

void solve(){
	for(int i=0;i<h;i++){
		for(int j=0;j<w;j++){
			if(s[i][j]=='#'){
				if(!d[i][j])dfs(i,j);
			}
		}
	}
	cout<<ans<<endl;
	return;
}

int main(){
	input();
	solve();
	return 0;
}

