int x[4] = {-1, 0, 1, 0};
int y[4] = {0, 1, 0, -1};
int H, W;
bool S[400][400];
bool has_been_discovered[400][400];
int members[400][2];
void DepthFirstSearch(int row, int column, int group_number){
	has_been_discovered[row][column] = true;
	members[group_number][S[row][column]]++;
	for(int i = 0;i < 4;++i){
		if(0 <= row + x[i] && row + x[i] < H && 0 <= column + y[i] && column + y[i] < W && !has_been_discovered[row + x[i]][column + y[i]] && (S[row][column] ^ S[row + x[i]][column + y[i]])){
			DepthFirstSearch(row + x[i], column + y[i], group_number);
		}
	}
}


int main(){
	scanf("%d %d", &H, &W);
	for (int i = 0; i < H; ++i){
		for (int j = 0; j < W; ++j){
			if(!j) scanf("\n");
			char tmp;
			scanf("%c", &tmp);
			S[i][j] = tmp == '#';
		}
	}
	int group_number_ = 0;
	for (int i = 0; i < H; ++i){
		for (int j = 0; j < W; ++j) if(!has_been_discovered[i][j]) DepthFirstSearch(i, j, group_number_++);
	}
	ll answer = 0;
	for (int i = 0; i < group_number_; ++i) answer += members[i][0]*members[i][1];
	printf("%lld\n", answer);
	return 0;
}

