      }
  }

  memset(dp, -1, sizeof(dp));


  for (int i = 0; i < H; ++i) {
      for (int j = 0; j < W; ++j) {
          if (field[i][j] == 1 && dp[i][j] == -1) {
              memset(visited, false, sizeof(visited));
              int t = dfs(i, j);
              for (int k = 0; k < H; ++k) {
                  for (int l = 0; l < W; ++l) {
                      if (visited[k][l] && field[k][l] == 1) {
                          dp[k][l] = t;
                      }
                  }
              }
          }
      }
  }

  int ans = 0;
  for (int i = 0; i < H; ++i) {
      for (int j = 0; j < W; ++j) {
          if (dp[i][j] != -1) ans += dp[i][j];
      }
  }

  cout << ans << endl;

  return 0;
}

