const ll MAX_H = 400;
const ll MAX_W = 400;
ll blocks = 0;
ll H,W;
string S[MAX_H];
// ll v[MAX_N], w[MAX_N];
ll dp[MAX_H+1][MAX_W+1]; // メモ化テーブル

void rec(ll i, ll j){

	if (i==0 & j==0) dp[i][j] = 0;
	else if (dp[i][j]==-1){
		// printf("%lld %lld %lld \n", i,j,blocks);
		blocks++;
		dp[i][j] = blocks;
	}
	if (j<W-1 & S[i][j]!=S[i][j+1] & dp[i][j+1]==-1){
		dp[i][j+1] = dp[i][j];
		rec(i,j+1);
	}
	if (j>0 & S[i][j]!=S[i][j-1] & dp[i][j-1]==-1){
		dp[i][j-1] = dp[i][j];
		rec(i,j-1);
	}	
	if (i<H-1 & S[i][j]!=S[i+1][j] & dp[i+1][j]==-1){
			dp[i+1][j] = dp[i][j];
			rec(i+1,j);
	}

	if (i>0 & S[i][j]!=S[i-1][j] & dp[i-1][j]==-1){
			dp[i-1][j] = dp[i][j];
			rec(i-1,j);
	}
	return;
}

int main() {
	// 入力
	cin >> H>>W;
	for (ll i = 0; i < H; ++i) cin >> S[i];

	// 解法
	memset(dp, -1, sizeof(dp));
	REP(i,H){
		REP(j,W){
			rec(i,j);
		}
	}
	// cout << blocks << endl;

	// REP(i,H){
	// 	REP(j,W){
	// 		printf("%lld ", dp[i][j]);
	// 	}
	// 	printf("\n");
	// }
	ll ans = 0;
	// printf("%lld \n", blocks);
	ll num_block[blocks+1];
	ll white[blocks+1] = {0};
	ll black[blocks+1] = {0};
	REP(i,H){
		REP(j,W){
			if (S[i][j]=='.') white[dp[i][j]]++;
			else  black[dp[i][j]]++;
		}
	}
	REP(i,blocks+1){
		ans += white[i]*black[i];
	}

	//出力
	cout << ans << endl;
}

