    cin>>H>>W;
    REP(i,H)REP(j,W)cin>>S[i][j];
    LL ans = 0;
    REP(i,H)REP(j,W){
        black = 0;
        white = 0;
        f(i, j, 'X');
        ans += (LL)(black * white);
    }
    PUTS(ans);
}

