void dfs(int y, int x, int &bb, int &ww, char c) {
    if(!(0 <= x && x < w)) return;
    if(!(0 <= y && y < h)) return;
    if(m[y][x] != c) return;
    m[y][x] = '!';
    char ic = c == '#' ? '.' : '#';

    c == '#' ? bb++ : ww++;

    dfs(y+1, x, bb, ww, ic);
    dfs(y-1, x, bb, ww, ic);
    dfs(y, x+1, bb, ww, ic);
    dfs(y, x-1, bb, ww, ic);
    return;
}

