bool isin_(int i, int j){
    return i >= 0 && i < H && j >= 0 && j < W;
}

bool check_(int i, int j, int d){
    int ni = i + dx[d];
    int nj = j + dy[d];
    if(!isin_(ni, nj)) return false;
    if(a[i][j] == a[ni][nj]) return false;
    return true;
}

long long solve() {
    long long ans = 0;
    long long b = 0, w = 0;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (used[i][j]) continue;
            b = 0;
            w = 0;
            queue<P> que;
            used[i][j] = true;
            que.push(P(i, j));
            while (!que.empty()) {
                P p = que.front();
                que.pop();
                int ci = p.first, cj = p.second;
                if (a[ci][cj]) b++;
                else w++;
                for (int d = 0; d < 4; ++d) {
                    if (!check_(ci, cj, d)) continue;
                    int ni = ci + dx[d], nj = cj + dy[d];
                    if (used[ni][nj]) continue;
                    used[ni][nj] = true;
                    que.push(P(ni, nj));
                }
            }
            ans += b * w;
        }
    }
    return ans;
}

