    return(a.fi >= 0 && a.fi < h && a.se >= 0 && a.se < w);
}

int main(){
    cin >> h >> w;
    for(int i=0;i<h;++i){
        for(int j=0;j<w;++j){
            char c;
            cin >> c;
            board[i][j] = (c == '#');
        }
    }
    memset(color, -1, sizeof(color));
    int pen = 0;
    for(int i=0;i<h;++i){
        for(int j=0;j<w;++j){
            if(color[i][j] != -1){
                continue;
            }
            ++pen;
            queue<pair<int, int> > Q;
            Q.push(mp(i, j));
            while(!Q.empty()){
                pair<int, int> at = Q.front();
                Q.pop();
                color[at.fi][at.se] = pen;
                for(int k=0;k<4;++k){
                    pair<int, int> tmp = mp(at.fi + dx4[k], at.se + dy4[k]);
                    if(!valid(tmp)){
                        continue;
                    }
                    if(color[tmp.fi][tmp.se] != -1){
                        continue;
                    }
                    if(board[at.fi][at.se] != board[tmp.fi][tmp.se]){
                        Q.push(tmp);
                    }
                }
            }
        }
    }
    map<int, pair<ll, ll> > freq;
    for(int i=0;i<h;++i){
        for(int j=0;j<w;++j){
            if(board[i][j]){
                ++freq[color[i][j]].fi;
            }else{
                ++freq[color[i][j]].se;
            }
        }
    }
    ll ans = 0ll;
    for(auto it=freq.begin();it!=freq.end();++it){
        pair<ll, ll> tmp = it->second;
        ans += (tmp.fi * tmp.se);
    }
    cout << ans << endl;
}

