int dh[4] = {-1, 1, 0, 0};
int dw[4] = {0, 0, -1, 1};
int cntSame = 0;
int cntDiff = 0;
char st;

void search(int h, int w){
    if(S[h][w]==st) cntSame++;
    else cntDiff++;

    char now = S[h][w];
    S[h].replace(w,1,"X");
    for(int i=0; i<4; i++){
        int nh = h + dh[i];
        int nw = w + dw[i];
        if(0 <= nh && nh < H && 0 <= nw && nw < W && S[nh][nw] != now && S[nh][nw] != 'X'){
            search(nh,nw);
        }    
    }
}

