	cin >> H >> W;
	string S[400] = {};

	for (int i = 0; i < H; i++) {
			cin >> S[i];
    }

	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (S[i][j] == '#')matrix[i][j] = -1;
			else if (S[i][j] == '.')matrix[i][j] = -2;
          	else matrix[i][j] = 0;
		}
	}
	long a = 2;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (matrix[i][j] >= 0) continue;
			count(i, j, a);
			a+=2;
		}
    }

    int box[a]={};
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			int cell=matrix[i][j];
          	box[cell]++;
		}
	}

  	int ans=0;
  	for(int i=1;2*i<a;i++){
    	ans +=(box[2*i])*(box[2*i+1]);
    }

 	cout <<ans <<endl;
}

