										// 処理していなければ、スタックに積む
			if(ii > 0     && C[ii][jj] != C[ii-1][jj])	S.push( P(ii-1, jj) );
			if(ii < H - 1 && C[ii][jj] != C[ii+1][jj])	S.push( P(ii+1, jj) );
			if(jj > 0     && C[ii][jj] != C[ii][jj-1])	S.push( P(ii, jj-1) );
			if(jj < W - 1 && C[ii][jj] != C[ii][jj+1])	S.push( P(ii, jj+1) );
		}
		ans += b * w;
	}

	cout << ans << endl;

