vector<P> ds = {{1, 0}, {-1, 0}, {0, -1}, {0, 1}};

void bfs(int y, int x, int group_id) {
  queue<P> que; que.push({y, x});
  while (!que.empty()) {
    auto [y, x] = que.front(); que.pop();
    for (auto [dy, dx] : ds) {
      int ny = y + dy, nx = x + dx;
      if (nx < 0 || W <= nx || ny < 0 || H <= ny) continue;
      if (visited[ny][nx] > 0) continue;
      if (S[y][x] == S[ny][nx]) continue;

      visited[ny][nx] = group_id;
      que.push({ny, nx});
    }
  }
}

int main() {
  cin >> H >> W;
  S.resize(H), visited.resize(H, vector<int>(W, 0));
  for (int r = 0; r < H; ++r) {
    cin >> S[r];
  }

  int group_id = 0;
  for (int r = 0; r < H; ++r) {
    for (int c = 0; c < W; ++c) {
      if (S[r][c] == '.') continue;
      if (visited[r][c] > 0) continue;
      ++group_id;
      bfs(r, c, group_id);
    }
  }

  map<int, int> black, white;
  for (int r = 0; r < H; ++r) {
    for (int c = 0; c < W; ++c) {
      int group_id = visited[r][c];
      if (group_id == 0) continue;

      if (S[r][c] == '.') white[group_id]++;
      else                black[group_id]++;
    }
  }

  int cnt = 0;
  for (auto [id, c] : black) {
    cnt += c * white[id];
  }
  cout << cnt << endl;
}

