            if (state[new_h][new_w] == 0 && S[new_h][new_w] == '.')
            {
                dist[h][w] = dist[new_h][new_w] = c;
                dfs(S, dist, state, new_h, new_w, c, ++count);
            }
        }
        else
        {
            if (state[new_h][new_w] == 0 && S[new_h][new_w] == '#')
            {
                dist[h][w] = dist[new_h][new_w] = c;
                dfs(S, dist, state, new_h, new_w, c, ++count);
            }
        }
    }
    return count;
}

