const double EPS = 1e-10;

vector<int> par;

int root(int x){
  if (par[x] == x){// 根
    return x;
  }
  else {
    return par[x] = root(par[x]); // 経路圧縮
  }
}

void unite(int x, int y){
  x = root(x);
  y = root(y);
  if (x == y){}
  else{
    par[x] = y;     //xの親をyの親にする
  }
}

int same(int x, int y){
  return root(x) == root(y);
}

signed main(){
	int h,w;
	cin>>h>>w;
	int n=h*w;
	par.assign(n,0);
	for(int i=0;i<n;i++){
		par[i]=i;
	}
	string x;
	vector<int> a(n,0);
	for(int i=0;i<h;i++){
		cin>>x;
		for(int j=0;j<w;j++){
			if(x[j]=='#') a[i*w+j]=1;
		}
	}

	for(int i=0;i<h-1;i++){
		for(int j=0;j<w-1;j++){
			if(a[i*w+j]!=a[(i+1)*w+j]){
				unite(i*w+j,(i+1)*w+j);
			}
			if(a[i*w+j]!=a[i*w+j+1]){
				unite(i*w+j,i*w+j+1);
			}
		}
		int j=w-1;
		if(a[i*w+j]!=a[(i+1)*w+j]){
			unite(i*w+j,(i+1)*w+j);
		}
	}
	for(int j=0;j<w-1;j++){
		int i=h-1;
		if(a[i*w+j]!=a[i*w+j+1]){
			unite(i*w+j,i*w+j+1);
		}
	}
	ll ans=0;
	vector<int>bk(n,0);
	vector<int>wh(n,0);
	for(int i=0;i<n;i++){
		if(a[i]==1)bk[root(i)]++;
		else wh[root(i)]++;
	}
	for(int i=0;i<n;i++){
		ans+=(ll)bk[i]*wh[i];
	}
	cout<<ans<<endl;
}

