int main() {
  int h,w; cin >> h >> w;
  vector<string> s(h);
  rep(i,h) cin >> s[i];

  ll ans = 0;
  vector<pair<int,int>> MOVE = { make_pair(0,1), make_pair(1,0), make_pair(-1,0), make_pair(0,-1) };
  vector<vector<bool>> done(h, vector<bool>(w, false));
  rep(a,h) rep(b,w) {
    if(done[a][b]) continue;
    queue<pair<int,int>> q;
    done[a][b] = true;
    q.emplace(a,b);
    int black=0, white=0;
    while(q.size()) {
      auto [i,j] = q.front(); q.pop();
      if(s[i][j]=='#') black++;
      else white++;
      for(auto [di, dj] : MOVE) {
        int ii = i + di, jj = j + dj;
        if(ii < 0 || ii >= h || jj < 0 || jj >= w) continue;
        if(s[i][j] == s[ii][jj]) continue;
        if(done[ii][jj]) continue;
        q.emplace(ii,jj);
        done[ii][jj]=true;
      }
    }
    if(black+white>1) ans += black * white;
  }
  cout << ans << endl;
}

