using namespace std;


int gcd(int a, int b)
{
  while (1)
  {
    if (a < b)
      swap(a, b);
    if (!b)
      break;
    a %= b;
  }
  return a;
}

typedef unsigned long long int ulli;
typedef pair<int, int> P;

void eva(int *visited, int *input, stack<P> &st, int H, int W, int h, int w, int ch, int cw){
  if (ch >= 0 &&
      cw >= 0 &&
      ch < H &&
      cw < W &&
      input[INDEX(W, h, w)] != input[INDEX(W, ch, cw)] &&
      !visited[INDEX(W, ch, cw)])
  {
    visited[INDEX(W, ch, cw)] = 1;
    st.push(P(ch, cw));
  }
}

int main(int argc, char **argv)
{
  int H = inputValue<int>();
  int W = inputValue<int>();
  int *input = new int [H*W];
  int *visited = new int [H*W];

  vector<list<int>> graph(H * W, list<int>());
  int i = 0;
  char c;
  while ((c = getc(stdin)) != EOF) {
    if  (c == '#' || c == '.') {
      input[i++] = (c=='.'); // if black(#) is 0, otherwise 1  
    }
  }


  for(int i=0; i<H*W; i++){
    visited[i] = 0;
  }


  stack<P> st;
  ulli sum = 0;
  for (int i=0; i<H; i++){
    for(int j=0; j<W; j++){
      if (visited[INDEX(W, i, j)])
      {
        continue;
      }
      st.push(pair<int, int>(i, j));
      ulli ones = 0;
      ulli N = 0;
      while (st.size() != 0)
      {
        P p = st.top();
        st.pop();
        int y = p.first;
        int x = p.second;
        // cout <<i<<"#"<<j<<"|" << y << "," << x << "," << st.size() << endl;
        visited[INDEX(W, y, x)] = 1;
        N++;
        ones = ones + ulli(input[INDEX(W, y, x)]);

        eva(visited, input, st, H, W, y, x, y - 1, x);
        eva(visited, input, st, H, W, y, x, y + 1, x);
        eva(visited, input, st, H, W, y, x, y, x - 1);
        eva(visited, input, st, H, W, y, x, y, x + 1);
      }
      // cout << N << "#" << ones << endl;
      sum = sum + ones * (N-ones);
    }
  }

  // for (int i=0; i<H; i++){
  //   for(int j=0; j<W; j++){
  //     cout << input[INDEX(W, i, j)];
  //   }
  //   cout << endl;
  // }
    cout << sum << endl;
    free(input);
    free(visited);
    return 0;
}

