void dfs(vector <pll> v1,ll index,ll count)
{
    if(index>=v1.size())
    {
        return;
    }
    ll x1=v1[index].fi;
    ll y1=v1[index].se;
    if(x1>0 and arr1[x1][y1]!=arr1[x1-1][y1] and visit[x1-1][y1]==0)
    {
        if(arr1[x1-1][y1]==0)
            ++val2;
        else
            ++val1;
        visit[x1-1][y1]=count;
        v1.pb(mp(x1-1,y1));
    }
    if(y1>0 and arr1[x1][y1]!=arr1[x1][y1-1] and visit[x1][y1-1]==0)
    {
        if(arr1[x1][y1-1]==0)
            ++val2;
        else
            ++val1;
        visit[x1][y1-1]=count;
        v1.pb(mp(x1,y1-1));
    }
    if(x1+1<n and arr1[x1][y1]!=arr1[x1+1][y1] and visit[x1+1][y1]==0)
    {
        if(arr1[x1+1][y1]==0)
            ++val2;
        else
            ++val1;
        visit[x1+1][y1]=count;
        v1.pb(mp(x1+1,y1));
    }
    if(y1+1<m and arr1[x1][y1]!=arr1[x1][y1+1] and visit[x1][y1+1]==0)
    {
        if(arr1[x1][y1+1]==0)
            ++val2;
        else
            ++val1;
        visit[x1][y1+1]=count;
        v1.pb(mp(x1,y1+1));
    }
    dfs(v1,index+1,count);
    return;
}

