using namespace std;

struct pa{
  int i, j;
  pa(int _i, int _j) : i(_i), j(_j) {}
};

long long search(vector<vector<int> >& v, int si, int sj){
  stack<pa> st = stack<pa>();
  st.push(pa(si, sj));
  v[si][sj] += 2;
  long long b = 0, w = 0;
  while(! st.empty()){
    stack<pa> st2 = stack<pa>();
    while(! st.empty()){
      pa pt = st.top();
      int i = pt.i, j = pt.j;
      st.pop();
      int nextcolor;
      if (v[i][j] == 2){
        nextcolor = 1;
        ++b;
      }else{
        nextcolor = 0;
        ++w;
      }
      if (i != 0 && v[i-1][j] == nextcolor){
        st2.push(pa(i-1, j));
        v[i-1][j] += 2;
      }
      if (j != 0 && v[i][j-1] == nextcolor){
        st2.push(pa(i, j-1));
        v[i][j-1] += 2;
      }
      if (i != v.size()-1 && v[i+1][j] == nextcolor){
        st2.push(pa(i+1, j));
        v[i+1][j] += 2;
      }
      if (j != v[0].size()-1 && v[i][j+1] == nextcolor){
        st2.push(pa(i, j+1));
        v[i][j+1] += 2;
      }
    }
    st = st2;
  }
  return b*w;
}

int main(void){
  int h, w;
  cin >> h >> w;
  vector<vector<int> > v = vector<vector<int> >();
  v.reserve(h);
  for(int i = 0; i < h; ++i){
    string str;
    cin >> str;
    vector<int> vv = vector<int>();
    vv.reserve(w);
    for(int j = 0; j < w; ++j){
      vv.push_back(str[j] == '#' ? 0 : 1);
    }
    v.push_back(vv);
  }
  long long sum = 0;
  for(int i = 0; i < h; ++i){
    for(int j = 0; j < w; ++j){
      if (v[i][j] == 0){
        sum += search(v, i, j);
      }
    }
  }
  cout << sum << endl;
  return 0;
}

