using namespace std;
const int dh[4] = {0, 1, 0, -1};
const int dw[4] = {1, 0, -1, 0};
int H, W;
vector<string> S;
vector<vector<long long>> G;

inline bool is_ng (int h, int w) { return (h < 0 || H <= h || w < 0 || W <= w); }
inline void grid_search(int now_h, int now_w) {
    vector<vector<bool>> seen(H, vector<bool>(W, false));
    seen[now_h][now_w] = true;
    queue<pair<int, int>> que;
    que.emplace(now_h, now_w);
    while (!que.empty()) {
        int h, w; tie(h, w) = que.front(); que.pop();
        for (int i = 0; i < 4; i++) {
            int nh = h + dh[i], nw = w + dw[i];
            if (is_ng(nh, nw)) continue;
            if (seen[nh][nw])  continue;
            if (S[h][w] == S[nh][nw]) continue;
            seen[nh][nw] = true;
            if (S[nh][nw] == '.') G[nh][nw]++;
            que.emplace(nh, nw);
        }
    }
}

int main() {
    cin >> H >> W;
    S.resize(H); G.assign(H, vector<long long>(W, 0));
    for (int i = 0; i < H; i++) cin >> S[i];
    for (int h = 0; h < H; h++) {
        for (int w = 0; w < W; w++) {
            if (S[h][w] == '#') grid_search(h, w);
        }
    }

    long long ans = 0;
    for (int h = 0; h < H; h++) {
        for (int w = 0; w < W; w++) {
            if (S[h][w] == '.')ans += G[h][w];
            //cout << G[h][w] << ((w+1==W)?"\n":" ");
        }
    }

    cout << ans << endl;
    return 0;
}

