// dataは0以上のとき親のindex
// 負のときは根であり、集合のサイズを表す
struct UnionFind {
  vector<int> data;
  VII num;
  UnionFind(int n) : data(n, -1) {}
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  void unite(int x, int y) {
    x = root(x); y = root(y);
    if (x == y) return;
    if (data[y] < data[x]) swap(x, y);
    // yをxにマージ
    data[x] += data[y];
    num[x].fi += num[y].fi;
    num[x].se += num[y].se;
    data[y] = x;
  }
  bool is_same(int x, int y) {
    return root(x) == root(y);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

const VI x = {0, 1, 0, -1};
const VI y = {1, 0, -1, 0};
signed main() {
  int H, W; cin >> H >> W;
  vector<string> S(H);
  REP (i, H) cin >> S[i];

  UnionFind uf(H * W);
  uf.num = VII(H * W);
  REP (i, H) {
    REP (j, W) {
      (S[i][j] == '.' ? uf.num[W * i + j].fi : uf.num[W * i + j].se) = 1;
    }
  }
  auto valid = [&](int i, int j) {
    return 0 <= i && i < H && 0 <= j && j < W;
  };
  REP (i, H) {
    REP (j, W) {
      REP (k, 4) {
        int i2 = i + x[k];
        int j2 = j + y[k];
        if (!valid(i2, j2) || S[i][j] == S[i2][j2]) continue;
        uf.unite(W * i + j, W * i2 + j2);
      }
    }
  }
  int ans = 0;
  REP (i, H) {
    REP (j, W) {
      if (uf.root(W * i + j) == W * i + j) {
        II tmp = uf.num[W * i + j];
        ans += tmp.fi * tmp.se;
      }
    }
  }
  cout << ans << endl;
}

