using namespace std;
char arr[405][405];
bool vis[405][405];
int h, w;
int cb;

int cw;

bool f(int i, int j, int l, int m){
	if(l<0 || l>=h || m<0 || m>=w){
		return 0;
	}
	if(vis[l][m]==1){
		return 0;
	}
	if(arr[i][j]==arr[l][m]){
		return 0;
	}
	return 1;
}

void dfs(int i, int j){
	vis[i][j]=1;
	if(arr[i][j]=='#'){
		cb++;
	}
	else{
		cw++;
	}
	if(f(i, j, i+1, j)){
		dfs(i+1, j);
	}
	if(f(i, j, i, j+1)){
		dfs(i, j+1);
	}
	if(f(i, j, i-1, j)){
		dfs(i-1, j);
	}
	if(f(i, j, i, j-1)){
		dfs(i, j-1);
	}
}


int main() {
	cin>>h>>w;
	for(int i=0; i<h; i++){
		for(int j=0; j<w; j++){
			cin>>arr[i][j];
		}
	}
	int ans=0;
	for(int i=0; i<h; i++){
		for(int j=0; j<w; j++){
			if(vis[i][j]==0){
				dfs(i, j);
				ans+=(cb*cw);
				cb=0;
				cw=0;
			}
		}
	}
	cout<<ans;
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef pair<int,int> P;
const int MAX_N = 400;

bool color[MAX_N][MAX_N];
bool visited[MAX_N][MAX_N];
string s;

int dx[4] = {-1,0,0,1};
int dy[4] = {0,-1,1,0};

int main(void){
	cin.tie(0);
	ios::sync_with_stdio(false);
	long long ans = 0;
	int H,W;
	cin >> H >> W;
	for(int i=0;i<H;i++){
		cin >> s;
		for(int j=0;j<W;j++){
			color[i][j] = (s[j]=='#');
		}
	}

	for(int i=0;i<H;i++){
		for(int j=0;j<W;j++){
			long long b = 0,w = 0;
			if(visited[i][j])continue;
			queue<P> q;
			visited[i][j] = true;
			q.push(P(i,j));

			while(!q.empty()){
				P now = q.front();
				q.pop();
				if(color[now.first][now.second])b++;
				else w++;
				for(int k=0;k<4;k++){
					int nx = dx[k] + now.first;
					int ny = dy[k] + now.second;

					if(!(nx>=0 && ny>=0 && nx<H && ny<W))continue;
					if(visited[nx][ny] || color[nx][ny]==color[now.first][now.second])continue;
					else {
						visited[nx][ny] = true;
						q.push(P(nx,ny));
					}

				}
			}

			ans += b*w;
		}
	}
	cout << ans << endl;
}

