int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    for (auto &&i : S) {
        cin >> i;
    }
    vector<int> dx = {-1, 1, 0, 0};
    vector<int> dy = {0, 0, -1, 1};
    auto exist     = [](int H, int W, int nx, int ny) -> bool {
        if (nx < 0 || W <= nx || ny < 0 || H <= ny)
            return false;
        else
            return true;
    };
    vector<vector<bool>> visited(H, vector<bool>(W));
    ll black, white;

    auto dfs = [&](auto f, int x, int y) {
        if (visited[y][x])
