            if (exist(H, W, nx, ny) && next == S[ny][nx]) {
                f(f, nx, ny);
            }
        }
        return;
    };
    ll ans = 0;

    REP(y, H) {
        REP(x, W) {
            if (S[y][x] == '#') {
                black = white = 0;
                dfs(dfs, x, y);
                ans += black * white;
            }
        }
    }

