struct masu {
	char clr;
	bool have_been = false;
};

struct pir {
	int black;
	int white;
};

vector<struct masu> S[410];

struct pir explore(int i,int j, int H, int W) {
	S[i][j].have_been = true;
	struct pir out = { 0,0 };
	if (i > 0 && S[i - 1][j].have_been == false && S[i-1][j].clr != S[i][j].clr) {
		struct pir tmp = explore(i - 1, j, H, W);
		out.black += tmp.black;
		out.white += tmp.white;
	}
	if (H-1 >i && S[i + 1][j].have_been == false&& S[i+1][j].clr != S[i][j].clr) {
		struct pir tmp = explore(i + 1, j, H, W);
		out.black += tmp.black;
		out.white += tmp.white;
	}
	if (j > 0 && S[i][j - 1].have_been == false&& S[i][j-1].clr != S[i][j].clr) {
		struct pir tmp = explore(i, j-1, H, W);
		out.black += tmp.black;
		out.white += tmp.white;
	}
	if (W-1 > j  && S[i][j + 1].have_been == false&& S[i][j+1].clr != S[i][j].clr) {
		struct pir tmp = explore(i, j+1, H, W);
		out.black += tmp.black;
		out.white += tmp.white;
	}
	if (S[i][j].clr == '#')out.black += 1;
	else out.white += 1;
	return out;
}


int main() {
