			S[i].push_back(iptmasu);
		}
	}


	int score = 0;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (S[i][j].have_been == false) {
				struct pir tmp;
				tmp = explore(i, j, H, W);
				score += tmp.black*tmp.white;
			}
		}
	}
	print(score);







	return 0;
}

