namespace math
{
ll gcd(ll u, ll v)
{
    while (v != 0)
    {
        ll r = u % v;
        u = v;
        v = r;
    }
    return u;
}
ll lcm(ll m, ll n)
{
    if ((0 == m) || (0 == n))
        return 0;

    return ((m / math::gcd(m, n)) * n);
}

