int main(void)
{
    int H, W;
    cin >> H >> W;

    vector<vector<bool>> visited(H, vector<bool>(W, false));
    vector<string> S(H);
    for(int i = 0; i < H; i++)
        cin >> S[i];

    array<pair<int, int>, 4> const diff = {
        pair<int, int>{-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    ll ans = 0;
    for(int y = 0; y < H; y++){
        for(int x = 0; x < W; x++){
            if(visited[y][x]) continue;
            queue<pair<int, int>> q;
            q.push({y, x});
            ll nBlack = 0;
            ll nWhite = 0;
            while(!q.empty()){
                auto p = q.front();
                q.pop();
                if(visited[p.first][p.second])
                    continue;

                visited[p.first][p.second] = true;

                if(S[p.first][p.second] == '#') nBlack++;
                else nWhite++;

                for(auto d : diff){
                    if(p.first + d.first < 0 || p.first + d.first >= H || p.second + d.second < 0 || p.second + d.second >= W)
                        continue;
                    if(S[p.first][p.second] == S[p.first + d.first][p.second + d.second])
                        continue;

                    q.push({p.first + d.first, p.second + d.second});
                }
            }
            ans += nBlack * nWhite;
        }
    }

    cout << ans << endl;

    return 0;
}

