        for (auto &yx : p.second) {
            int y = yx.first;
            int x = yx.second;
            if (s[y][x] == '.')
                wh++;
            else
                bl++;
        }
        ret += bl * wh;
    }
    cout << ret << "\n";
    return 0;
}

