int main(){
	int h,w;
	cin>>h>>w;
	for (int i = 0; i < h; ++i){
		for (int j = 0; j < w; ++j){
			cin>>mp[i][j];
		}
	}

	int ans=0;
	int dx[4]={1,-1,0,0};
	int dy[4]={0,0,1,-1};
	for (int i = 0; i < h; ++i){
		for (int j = 0; j < w; ++j){
			if(mp[i][j]=='.')
				continue;
			else if(check[i][j]==false){
				int black=1,white=0;
				queue<PII> que;
				check[i][j]=true;
				que.push(make_pair(i,j));
				while(que.size()){
					PII p = que.front();
					que.pop();
					for (int k = 0; k < 4; ++k){
						int ny=p.first+dy[k];
						int nx=p.second+dx[k];
						if(mp[ny][nx]!=mp[p.first][p.second]&&check[ny][nx]==false&&nx>=0&&nx<w&&ny>=0&&ny<h){
							que.push(make_pair(ny,nx));
							if(mp[ny][nx]=='.'){
								white++;
							}else if(mp[ny][nx]=='#')
								black++;
							check[ny][nx]=true;
						}
					}
				}


				ans+=black*white;
			}

		}

	}
	cout<<ans<<endl;
}

