typedef short Pos[2];

int main(){
	int H, W;

	scanf("%d %d\n", &H, &W);

	std::vector<std::string> board(H);
	for(int i = 0; i < H; i++){
		std::cin >> board[i];
	}

	int ans = 0;
	Pos buf[400*400];
	int buf_i = 0;
	Pos new_buf[400*400];
	int new_buf_i = 0;

	//std::cout << H << " " << W << std::endl;

	for(short Y = 0; Y < H; Y++){
		for(short X = 0; X < W; X++){

			int n_White = 0, n_Black = 0;

			if(board[Y][X] != 'x'){
				//std::cout << "Found: (" << X << " " << Y << ")" << std::endl;

				buf_i = 0;

				buf[buf_i][0] = X;
				buf[buf_i][1] = Y;

				buf_i++;

				while(buf_i > 0 && buf_i < sizeof(buf)/sizeof(Pos)){
					new_buf_i = 0;
					for(int i = 0; i < buf_i; i++){
						//std::cout << i << std::endl;
						short x = buf[i][0];
						short y = buf[i][1];

						char color = board[y][x];
						char target;

						if(color == '#'){
							n_Black++;
							target = '.';
						}
						if(color == '.'){
							n_White++;
							target = '#';
						}

						// 上下左右のPosが自分の色と異なっている場合、new_bufに追加する
						if(y - 1 >= 0 && board[y - 1][x] == target){
							new_buf[new_buf_i][0] = x;
							new_buf[new_buf_i][1] = y - 1;
							new_buf_i++;
						}
						if(x + 1 < W && board[y][x + 1] == target){
							new_buf[new_buf_i][0] = x + 1;
							new_buf[new_buf_i][1] = y;
							new_buf_i++;
						}
						if(y + 1 < H && board[y + 1][x] == target){
							new_buf[new_buf_i][0] = x;
							new_buf[new_buf_i][1] = y + 1;
							new_buf_i++;
						}
						if(x - 1 >= 0 && board[y][x - 1] == target){
							new_buf[new_buf_i][0] = x - 1;
							new_buf[new_buf_i][1] = y;
							new_buf_i++;
						}

						board[y][x] = 'x';
					}
					memcpy(buf, new_buf, sizeof(Pos)*new_buf_i);
					buf_i = new_buf_i;
				}
			}
			ans += n_White*n_Black;
		}
	}

	std::cout << ans << std::endl;
}

