#include "bits/stdc++.h"
using namespace std;

static int par[160000];

int root(int x) {
	if (par[x] == x) return x;
	return par[x] = root(par[x]);
}

bool same(int x, int y) {
	return par[x] == par[y];
}

void unite(int x, int y) {
	x = root(x), y = root(y);
	if (x == y) return;
	par[x] = y;
}

int main() {
	int H, W, ans = 0;
	string S[400];
	map<int, pair<int, int> > mp;
	cin >> H >> W;
	for (int i = 0; i < H; i++) {
		cin >> S[i];
		for (int j = 0; j < W; j++) {
			par[i * W + j] = i * W + j;
		}
	}
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W - 1; j++) {
			if (S[i][j] != S[i][j + 1]) unite(i * W + j, i * W + j + 1);
		}
	}
	for (int i = 0; i < H - 1; i++) {
		for (int j = 0; j < W; j++) {
			if (S[i][j] != S[i + 1][j]) unite(i * W + j, (i + 1) * W + j);
		}
	}
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			root(i * W + j);
			if (S[i][j] == '#') {
				mp[par[i * W + j]].first++;
			}
			else {
				mp[par[i * W + j]].second++;
			}
		}
	}
	for (auto it = mp.begin(); it != mp.end(); it++) {
		ans += it->second.first * it->second.second;
	}
	cout << ans;
}

