    REP(j, W) {
      if (j != 0 && C[i][j] != C[i][j - 1]) {
        uf.unite(i * W + j, i * W + j - 1);
      }
      if (i != 0 && C[i][j] != C[i - 1][j]) {
        uf.unite((i - 1) * W + j, i * W + j);
      }
    }
  }
  set<int> s;
  map<int, int> wc;
  map<int, int> bc;
  REP(i, H) {
    REP(j, W) {
      int root = uf.root(i * W + j);
      s.insert(root);
      if (C[i][j] == 0) {
        wc[root]++;
      } else {
        bc[root]++;
      }
    }
  }
  int ans = 0;
  for (set<int>::iterator it = s.begin(), end = s.end(); it != end; ++it) {
    ans += wc[*it] * bc[*it];
  }
  print(ans);
}
signed main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  solve();
}

