int main()
{
  ll H, W;
  cin >> H >> W;
  vector<pair<ll, ll>> pB;
  REP(i, H) REP(j, W) {
    char c; cin >> c;
    if (c == '#') {
      mp[i][j] = 1;
      pB.PB(MP(i, j));
    } else mp[i][j] = -1;
  }

