  REP(i, pB.size()) {
    if (used[pB[i].FI][pB[i].SE]) {
      pair<ll, ll> pos = par[pB[i].FI][pB[i].SE];
      ans += kosu[pos.FI][pos.SE];
      continue;
    }
    queue<pair<ll, ll>> q;
    q.push(MP(pB[i].FI, pB[i].SE));
    used[pB[i].FI][pB[i].SE] = true;
    ll cnt = 0;
    while (! q.empty()) {
      pair<ll, ll> pos = q.front(); q.pop();
      ll y = pos.FI;
