          used[ny][nx] = true;
          q.push(MP(ny, nx));
          if (mp[ny][nx] == -1) cnt++;
        }
      }
    }
    ans += cnt;
    kosu[pB[i].FI][pB[i].SE] = cnt;
  }
  cout << ans << endl;
  return 0;
}

