int main()
{
    int H, W;
    cin >> H >> W;

    int board[H][W];
    int origin[H][W];
    string S;
    for (int i = 0; i < H; i++)
    {
        cin >> S;
        for (int j = 0; j < W; j++)
        {
            if (S[j] == '#')
            {
                board[i][j] = 0;
                origin[i][j] = 0;
            }
            else
            {
                board[i][j] = 1;
                origin[i][j] = 1;
            }
            if ((i + j) % 2 == 0)
            {
                board[i][j] = -1 * board[i][j] + 1;
            }
        }
    }

    int counted[H][W] = {};
    int dx[4] = {1, 0, -1, 0};
    int dy[4] = {0, 1, 0, -1};
    queue<int> xqueue;
    queue<int> yqueue;
    int ans;
    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            if (!counted[i][j])
            {
                xqueue.push(i);
                yqueue.push(j);
                int bsum = 0;
                int wsum = 0;
                while (xqueue.size() * yqueue.size() > 0)
                {
                    int x = xqueue.front();
                    xqueue.pop();
                    int y = yqueue.front();
                    yqueue.pop();
                    for (int k = 0; k < 4; k++)
                    {
                        int newx = x + dx[k];
                        int newy = y + dy[k];
                        if (
                            (0 <= newx && newx < H) &&
                            (0 <= newy && newy < W) &&
                            !counted[newx][newy] &&
                            board[x][y] == board[newx][newy])
                        {
                            xqueue.push(newx);
                            yqueue.push(newy);
                            if (origin[newx][newy] == 0)
                            {
                                bsum++;
                            }
                            else
                            {
                                wsum++;
                            }
                            counted[newx][newy] = 1;
                        }
                    }
                }
                ans += bsum * wsum;
            }
        }
    }
    cout << ans << endl;
}

