                    tree.unite((i*w+j), ((i)*w+j+1));
                }
            }
        }
    }
    REP(i,h-1){
        REP(j,w){
            if(s[i][j] == '#'){
                if(s[i+1][j] == '.' && !tree.same((i*w+j), ((i+1)*w+j))){
