  REP(i, H) {
    REP(j, W) {
      if(board[i][j] == '#') {
        if(i - 1 >= 0 && board[i - 1][j] == '.') {
          uf.merge(i * W + j, (i - 1) * W + j);
        }
        if(i + 1 <= H - 1 && board[i + 1][j] == '.') {
          uf.merge(i * W + j, (i + 1) * W + j);
        }
        if(j - 1 >= 0 && board[i][j - 1] == '.') {
          uf.merge(i * W + j, i * W + j - 1);
        }
        if(j + 1 <= W - 1 && board[i][j + 1] == '.') {
          uf.merge(i * W + j, i * W + j + 1);
        }
      }
    }
  }
  auto isBlack = [&](int n) {
    int i = n / W;
