	for(int i=1;i<=H;i++)
	{
		for(int j=1;j<=W;j++)
		{
			int w=0,b=0;
			int x,y;
			queue<pair<int,int>> q;
			q.push({i,j});
			while(!q.empty())
			{
				pair<int,int> p=q.front();
				q.pop();

				if(umap[p.first][p.second]==1)continue;
				if(p.first<=0 || H<p.first || p.second<=0 || W<p.second)continue;

				umap[p.first][p.second]=1;
				if(map[p.first][p.second]=='#')b++;
				else w++;
				for(int k=0;k<4;k++)
				{
					y=p.first+dy[k];
					x=p.second+dx[k];
					if(y<=0 || H<y || x<=0 || W<x)continue;
					if(map[y][x]!=map[p.first][p.second])q.push({y,x});
				}
			}

			ans+=w*b;
			//cout << w << " " << b << endl;
		}
	}

	cout << ans << endl;
	return 0;
}

