#define FOR(I,A,B) for(int I = int(A); I < int(B); ++I)

class UnionFind{
public:
	vector<int> par;
	vector<long long> g1,g2;
	//0-indexed
	void init(int n = 1) {
		par.resize(n);
		for (int i = 0; i < n; ++i) par[i] = i;
		g1.resize(n,0);
		g2.resize(n,0);
	}
	int root(int x = 1){
		if(par[x]==x)return x;
		else{
			return par[x] = root(par[x]);
		}
	}
	void unite(int x = 1,int y = 1){
		x = root(x);
		y = root(y);
		if(x==y)return;
		g1[y] += g1[x];
		g2[y] += g2[x];
		par[x] = y;
	}
};

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	int H,W;
	ll ans=0;
	cin >> H >> W;
	string s[H];
	FOR(i,0,H){
		cin >> s[i];
	}
	UnionFind uf;
	uf.init(H*W);
	// (x,y) -> W*x+y
	FOR(i,0,H){
		FOR(j,0,W){
			if(s[i][j]=='#'){
				uf.g1[W*i+j]=1;
			}else{
				uf.g2[W*i+j]=1;
			}
		}
	}
	FOR(i,0,H){
		FOR(j,0,W){
			int now = W*i+j;
			int to = W*(i-1)+j;
			if(i>0)if(s[i][j]!=s[i-1][j]){
				uf.unite(now,to);
				uf.root(to);
				uf.root(now);
			}
			to = W*i+j-1;
			if(j>0)if(s[i][j]!=s[i][j-1]){
				uf.unite(now,to);
				uf.root(to);
				uf.root(now);
			}
		}
	}
	set<int> se;
	FOR(i,0,H){
		FOR(j,0,W){
			int ro = uf.root(i*W+j);
			if(se.count( ro )==0){
				ans += uf.g1[ro]*uf.g2[ro];
				se.insert(ro);
			}
		}
	}
	cout << ans << endl;
}

