    {
        for (int j = 0; j < W; j++)
        {
            if (!counted[i][j])
            {
                xqueue.push(i);
                yqueue.push(j);
                bsum = 0;
                wsum = 0;
                while (xqueue.size() * yqueue.size() > 0)
                {
                    x = xqueue.front();
                    xqueue.pop();
                    y = yqueue.front();
                    yqueue.pop();
                    if (!counted[x][y])
                    {
                        if (origin[x][y] == 0)
                        {
                            bsum++;
                        }
                        else
                        {
