			if (!vis[x][y])
			{
				int black_cnt = 0 , white_cnt = 0;
				vis[que[1][0] = x][que[1][1] = y] = 1 , head = 0 , tail = 1;
				for (int x_ , y_ , x__ , y__;head < tail;)
				{
					++ head , x_ = que[head][0] , y_ = que[head][1];
					black_cnt += mp[x_][y_] == '#' , white_cnt += mp[x_][y_] == '.';
					for (int d = 0;d < D;++ d)
					{
						x__ = x_ + dir[d][0] , y__ = y_ + dir[d][1];
						if (1 <= x__ && x__ <= n && 1 <= y__ && y__ <= m && mp[x_][y_] != mp[x__][y__] && !vis[x__][y__])
							++ tail , vis[que[tail][0] = x__][que[tail][1] = y__] = 1;
					}
				}
				ans += 1ll * black_cnt * white_cnt;
			}
	printf("%lld\n" , ans);
	//fclose(stdin) , fclose(stdout);
	return 0;
}

