  rep(h, H-1){
    rep(w, W-1){
      if(mapdata[h][w] != mapdata[h][w+1]){
        UF.unite(to_n(h, w), to_n(h, w+1));
      }
      if(mapdata[h][w] != mapdata[h+1][w]){
        UF.unite(to_n(h, w), to_n(h+1, w));
      }
    }
  }

  //最終行・最終列を処理
  //最終行
  rep(w, W-1){
    if(mapdata[H-1][w] != mapdata[H-1][w+1]){
      UF.unite(to_n(H-1, w), to_n(H-1, w+1));
    }
  }
  rep(h, H-1){
    if(mapdata[h][W-1] != mapdata[h+1][W-1]){
      UF.unite(to_n(h, W-1), to_n(h+1, W-1));
    }
  }

  UF.solve();
  oi(finalans); br();


