struct UnionFind{
    vector<ll> par,s,b,w;
    UnionFind(ll N) : par(N),s(N),b(N),w(N){
        REP(i,N){
            par[i] = i;
            b[i] = 0;
            w[i] = 0;
            s[i] = 0;
        }
    }
    int root(int x){
        if(par[x]==x){ return x; }
        else{ 
          par[x]= root(par[x]);
          return par[x];
        }
    }
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if( rx!=ry ){
            par[rx] = ry;
            s[ry] += s[rx];
            w[ry] += w[rx];
            b[ry] += b[rx];
        }
    }

    void coloring(int x,char c){
        int rx = root(x);
        if(c=='.'){
            w[rx] += 1;
        }else{
            b[rx] += 1;
        }
    }
    ll solve(int rx){
        return w[rx]*b[rx];
    }
};

int main(){
    int H,W; cin>>H>>W;
    string board[H]; CINA(board,H);
    UnionFind uf(H*W);
    REP(i,H){
        REP(j,W){
            uf.coloring(i*W+j,board[i][j]);
        }
    }
    REP(i,H){
        REP(j,W){
            if(i+1<H){
                if(board[i][j]!=board[i+1][j]){
                    uf.unite(i*W+j,(i+1)*W+j);
                }
            }
            if(j+1<W){
                if(board[i][j]!=board[i][j+1]){
                    uf.unite(i*W+j,i*W+j+1);
                }

            }
        }
    }
    ll ans = 0;
    map<int,int> mp;
    REP(x,H*W){
        int rx = uf.root(x);
        if(mp[rx]==0){
            ++mp[rx];
            ans += uf.solve(rx);
        }

    }
    cout << ans << "\n";


}

#include <bits/stdc++.h>
using namespace std;
typedef pair<int, int> P;

const int MAX_N = 400;

const int di[] = {1, 0, -1, 0};
const int dj[] = {0, 1, 0, -1};

bool color[MAX_N][MAX_N];
int H, W;

char ch[MAX_N+1];
bool used[MAX_N][MAX_N];

void input(){
    cin >> H >> W;
    for(int i=0; i<H; ++i){
        cin >> ch;
        for(int j=0; j<W; ++j){
            color[i][j] = (ch[j] == '#');
        }
    }
}

bool isin_(int i, int j){
    return i>=0 && i < H && j>=0 && j <W;
}

bool check_(int i, int j, int d){
    int ni = i + di[d];
    int nj = j + dj[d];
    if(!isin_(ni, nj)) return false;
    if(color[i][j] == color[ni][nj]) return false;
    return true;
}


long long solve(){
    long long ans = 0;
    long long b = 0, w = 0;
    for(int i= 0; i<H; ++i){
        for(int j=0; j<W; ++j){
            if(used[i][j]) continue;
            b = 0;
            w = 0;
            queue<P> que;
            used[i][j] = true;
            que.push(P(i, j));
            while(!que.empty()){
                P p = que.front();
                que.pop();
                int ci = p.first, cj = p.second;
                if(color[ci][cj]) b++;
                else w++;
                for(int d=0; d<4; ++d){
                    if(!check_(ci, cj, d)) continue;
                    int ni = ci + di[d], nj = cj + dj[d];
                    if(used[ni][nj]) continue;
                    used[ni][nj] = true;
                    que.push(P(ni, nj));

                }
            }
            ans += b * w;
        }
    }
    return ans;
}


int main(){
    input();
    long long ans = solve();
    cout << ans << endl;
    return 0;
}

