struct UnionFind{
private:
  std::vector<int> data;

public:
  UnionFind(int n = 0) : data(n, -1){}

  int find(int x){
    return data[x] < 0 ? x : data[x] = find(data[x]);
  }

  bool unite(int x, int y){
    x = find(x); y = find(y);

    if(x == y) return false;
    else{
      if(data[x] > data[y]) std::swap(x, y);
      data[x] += data[y];
      data[y] = x;
      return true;
    }
  }

  bool is_same(int x, int y){
    return find(x) == find(y);
  }

  int size(int x){
    return -data[find(x)];
  }
};

int main(){
  int H, W;
  cin >> H >> W;

  vector<string> S(H);
  for(int i = 0; i < H; i++) cin >> S[i];

  UnionFind uf(H * W);

  for(int i = 0; i < H; i++){
    for(int j = 0; j < W; j++){
      if(i && S[i][j] != S[i - 1][j]){
        uf.unite(i * W + j, (i - 1) * W + j);
      }
      if(j && S[i][j] != S[i][j - 1]){
        uf.unite(i * W + j, i * W + j - 1);
      }
    }
  }

  vector<int> black(H * W, 0);
  vector<int> white(H * W, 0);
  for(int i = 0; i < H; i++){
    for(int j = 0; j < W; j++){
      if(S[i][j] == '#') ++black[uf.find(i * W + j)];
      else ++white[uf.find(i * W + j)];
    }
  }

  long long p = 0;
  vector<bool> used(H * W, false);
  for(int t = 0; t < H * W; t++){
    if(used[uf.find(t)]) continue;

    p += (long long)black[uf.find(t)] * white[uf.find(t)];
    used[uf.find(t)] = true;
  }

  cout << p << endl;

  return 0;
}

