int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};

int main() {
    int H, W;
    cin >> H >> W;
    vector<string> G(H);
    rep(i, H) cin >> G[i];

    vector<vector<int>> GG(H * W, vector<int>(0));
    for (int x = 0; x < H; x++) {
        for (int y = 0; y < W; y++) {
            int cid = x * W + y;
            char cc = G[x][y];
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i], ny = y + dy[i];
                if (nx < 0 or H <= nx or ny < 0 or W <= ny) continue;
                int nid = nx * W + ny;
                int nc  = G[nx][ny];
                if (nc != cc) GG[cid].push_back(nid);
            }
        }
    }

    lint ans = 0;
    vector<bool> check(W * H, false);
    for (int id = 0; id < H * W; id++) {
        if (check[id]) continue;
        check[id] = true;
        int cntW = 0, cntB = 0;

        queue<int> que;
        que.push(id);
        while (not que.empty()) {
            int cid = que.front();
            que.pop();
            int cx = cid / W, cy = cid % W;
            if (G[cx][cy] == '#')
                cntB++;
            else
                cntW++;

            for (auto nid : GG[cid]) {
                if (not check[nid]) {
                    que.push(nid);
                    check[nid] = true;
                }
            }
        }
        ans += cntB * cntW;
    }

    cout << ans << endl;
    return 0;
}

