int count( int i, int j, int H, int W, vector<vector<int>>& map, vector<vector<bool>>& searched ){
  if( searched[i][j] ) return 0;
  searched[i][j] = true;

  int sum = 0;
  if( map[i][j] == -1 ) sum++;
  if( i < H-1 ) if( map[i][j] == -1*map[i+1][j] ) sum += count( i+1, j, H, W, map, searched );
  if( i > 0 ) if( map[i][j] == -1*map[i-1][j]  ) sum += count( i-1, j, H, W, map, searched );
  if( j < W-1 ) if( map[i][j] == -1*map[i][j+1]  ) sum += count( i, j+1, H, W, map, searched );
  if( j > 0 ) if( map[i][j] == -1*map[i][j-1]  ) sum += count( i, j-1, H, W, map, searched );
  return sum;
}

int main( void ){
  int H, W;
  vector<vector<int>> map;
  cin >> H >> W;

  for( int i = 0; i < H; i++ ){
    string S;
    cin >> S;
    vector<int> _map;
    for( int j = 0; j < W; j++ ){
      if( S[j] == '#' ) _map.push_back(1);
      else               _map.push_back(-1);
    }
    map.push_back(_map);
  }

  int sum = 0;
  for( int i = 0; i < H; i++ ){
    for( int j = 0; j < W; j++ ){
      vector<vector<bool>> searched(H,vector<bool>(W,false));
      if( map[i][j] == 1 ) sum += count( i, j, H, W, map, searched);
    }
  }

  cout << sum << endl;
  return 0;
}

