void func(int x, int y) {
	queue<pair<int, int>> que;
	pair<int, int> pos = { x,y };
	que.push(pos);
	int w = 0, b = 0;
	if (maze[x][y] == '.')w++;
	else b++;
	while (!que.empty()) {
		pair<int, int> Pa = que.front();
		que.pop();
		int X = Pa.first;
		int Y = Pa.second;
		REP(i, 4) {
			int nx = X + dx[i];
			int ny = Y + dy[i];
			if (nx >= 0 && nx < H&&ny >= 0 && ny < W) {
				if (visited[nx][ny])continue;
				if (maze[X][Y] == '.') {
					if (maze[nx][ny] == '#') {
						b++;
						que.push({ nx,ny });
						visited[nx][ny] = true;
					}
				}
				else {
					if (maze[nx][ny] == '.') {
						w++;
						que.push({ nx,ny });
						visited[nx][ny] = true;
					}
				}
			}
		}
	}
	ans += b * w;
}
