using namespace std;

enum color_t { Black, White };

static color_t board[400][400];

using graph_t =
    boost::adjacency_list<boost::listS, boost::vecS, boost::undirectedS>;
using edge_t = std::pair<int, int>;

static int64_t solve(int h, int w) {
  std::unordered_set<int> candidates{};
  std::vector<edge_t> edges{};
  int const squares = h * w;
  for (int from = 0; from < squares - 1; ++from) {
    int const fromRow = from / w;
    int const fromColumn = from % w;
    color_t const fromColor = board[fromRow][fromColumn];

    {
      int const toRow = fromRow + 1;
      int const toColumn = fromColumn;
      if (toRow < h) {
        color_t const toColor = board[toRow][toColumn];
        if (fromColor != toColor) {
          int const to = toRow * w + toColumn;
          edges.emplace_back(std::make_pair(from, to));
          candidates.insert(from);
          candidates.insert(to);
        }
      }
    }

    {
      int const toRow = fromRow;
      int const toColumn = fromColumn + 1;
      if (toColumn < w) {
        color_t const toColor = board[toRow][toColumn];
        if (fromColor != toColor) {
          int const to = toRow * w + toColumn;
          edges.emplace_back(std::make_pair(from, to));
          candidates.insert(from);
          candidates.insert(to);
        }
      }
    }
  }

  const graph_t g(edges.begin(), edges.end(), 160000);

  int64_t ret = 0;
  for (int from = 0; from < squares - 1; ++from) {
    if (candidates.find(from) == candidates.end()) {
      continue;
    }
    int const fromRow = from / w;
    int const fromColumn = from % w;
    color_t const fromColor = board[fromRow][fromColumn];
    for (int to = from + 1; to < squares; ++to) {
      if (candidates.find(to) == candidates.end()) {
        continue;
      }
      int const toRow = to / w;
      int const toColumn = to % w;
      if ((abs(fromRow - toRow) + abs(fromColumn - toColumn)) % 2 == 0) {
        continue;
      }
      color_t const toColor = board[toRow][toColumn];
      if (fromColor == toColor) {
        continue;
      }
      std::vector<boost::default_color_type> color(160000, boost::white_color);
      if (boost::is_reachable(from, to, g, color.data())) {
        ++ret;
      }
    }
  }
  return ret;
}

