int h, w;
vector<vector<char>> field;
vector<vector<bool>> used;
int cnt;

void dfs(int x, int y, char c) {
    used[x][y] = true;
    cnt ++;
    rep(i, 4) {
        int nx = x + dx[i], ny = y + dy[i];
        char d = (c == '#'? '.': '#');
        if(0 <= nx && nx < h && 0 <= ny && ny < w && field[nx][ny] == d && !used[nx][ny]) {
            dfs(nx, ny, d);
        }
    }
}

void solve() {
	cin >> h >> w;
    field.assign(h, vector<char>(w));
    used.assign(h, vector<bool>(w));
    rep(i, h) {
        rep(j, w) {
            cin >> field[i][j];
            used[i][j] = false;
        }
