    int ans = 0;
    rep(i, h) {
        rep(j, w) {
            cnt = 0;
            if(!used[i][j]) {
                dfs(i, j, field[i][j]);
            }
            ans += cnt * (cnt - 1) / 2;
        }
    }
    cout << ans << endl;
}

