// LIBRARY

struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) {}
  void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y)
      return;
    if (data[y] < data[x])
      swap(x, y);
    data[x] += data[y];
    data[y] = x;
  }
  bool same(int x, int y) { return root(x) == root(y); }
  int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
  int size(int x) { return -data[root(x)]; }
};

// SOLVE
void solve() {
  int H, W;
  cin >> H >> W;
  vvi C(H, vector<int>(W));
  UnionFind uf(H * W);
  REP(i, H) {
    string str;
    cin >> str;
    REP(j, W) {
      if (str[j] == '.') {
        C[i][j] = 0;
      } else {
        C[i][j] = 1;
      }
    }
  }
  REP(i, H) {
    REP(j, W) {
      if (i != 0 && C[i][j] != C[i - 1][j]) {
        uf.unite((i - 1) * W + j, i * W + j);
      }
      if (j != 0 && C[i][j] != C[i][j - 1]) {
        uf.unite(i * W + j, i * W + j - 1);
      }
    }
  }
  set<int> s;
  map<int, int> wc;
  map<int, int> bc;
  REP(i, H) {
    REP(j, W) {
      int root = uf.root(i * W + j);
      s.insert(root);
      if (C[i][j] == 0) {
        wc[root]++;
      } else {
        bc[root]++;
      }
    }
  }
  int ans = 0;
  for (set<int>::iterator it = s.begin(), end = s.end(); it != end; ++it) {
    ans += wc[*it] * bc[*it];
  }
  print(ans);
}
