    vector<pair<int, int>> dirs = {{-1, 0}, {0, -1}, {0, 1}, {1, 0}};

    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (used[i][j]) continue;
            used[i][j] = true;

            i64 cnt_b = 0, cnt_w = 0;
            stack<pair<int, int>> st;
            st.emplace(i, j);
            while (!st.empty()) {
                auto p = st.top(); st.pop();
