                    if (used[c.first][c.second]) continue;
                    if (S[c.first][c.second] != pc) {
                        used[c.first][c.second] = true;
                        st.push(c);
                    }
                }
            }
            ans += cnt_w * cnt_b;
        }
    }

    cout << ans << endl;

