                    uf.unionSet(W * (i + 1) + j, th);
                if (j != 0 && S[i][j - 1] == '.')
                    uf.unionSet(W * (i) + j - 1, th);
                if (j != W - 1 && S[i][j + 1] == '.')
                    uf.unionSet(W * (i) + j + 1, th);
            }
        }
    }

    vector<pair<int, int> > g;


    for (int i = 0; i < uf.data.size(); i++) {

        if (uf.data[i] < 0) {
            g.push_back(pair<int, int>(i, -uf.data[i]));
        }
    }

