vector<ll> bfs(ll m, vector<vector<ll>> &nx, vector<bool> &seen, ll start) {
	queue<ll> task;
	task.push(start);
	seen[start] = true;
	vector<ll> ret = {1, 0};
	ll depth = 1;
	while (task.size()) {
		ll sz = task.size();
		while (sz--) {
			ll x = task.front();
			task.pop();
			for (ll i = 0; i < nx[x].size(); i++) {
				if (!seen[nx[x][i]]) {
					task.push(nx[x][i]);
					seen[nx[x][i]] = true;
					ret[depth % 2]++;
				}
			}
		}
		depth++;
	}
	return ret;
}

