struct UnionFind //size-based
{
  vector<int> parent, treesize, blacksize;

  UnionFind( int size, vector<int> black_size ) : parent( size ) , treesize( size , 1 ) //constructor
  {
    blacksize = black_size;
    for( int i = 0 ; i < size ; ++ i )
      {
	parent[i] = i;
      }
  }

  int root( int x )
  {
    if( parent[x] == x )
      {
	return x;
      }

    return parent[x] = root(parent[x]);
  }

  void unite( int x, int y )
  {
    x = root(x); 
    y = root(y);

    if( x == y )
      {
	return; 
      }

    if( treesize[x] < treesize[y] )
      {
	parent[x] = y;
	treesize[y] += treesize[x];
	blacksize[y] += blacksize[x];
      }
    else
      {
	parent[y] = x;
	treesize[x] += treesize[y];
	blacksize[x] += blacksize[y];	
      }

  }

  bool sametree( int x, int y )
  {
    return root(x) == root(y);
  }

  int gettreesize( int x )
  {
    return treesize[root(x)];
  }

  int getblacksize( int x )
  {
    return blacksize[root(x)];
  }

};


const int dy[4] = {0,1,0,-1};
const int dx[4] = {1,0,-1,0};



signed main()
{
  IOS; /* making cin faster */
  int H,W;
  CIN2(H,W);
  vector<string> S(H);
  REP(i,H)
    {
      CIN(S[i]);
    }

  vector<vector<int> > vm(H,vector<int>(W));
  vector<pair<int,int> > hm;
  vector<int> bk;

  int num = 0;
  REP(i,H)
    {
      REP(j,W)
	{
	  vm[i][j] = num;
	  hm.push_back(make_pair(i,j));
	  ++ num;

	  if( S[i][j] == '#' )
	    {
	      bk.push_back(1);
	    }
	  else
	    {
	      bk.push_back(0);
	    }
	}
    }


  UnionFind T(num,bk);

  REP(i,H)
    {
      REP(j,W)
	{
	  REP(k,4)
	    {
	      int y = dy[k] + i;
	      int x = dx[k] + j;

	      if( 0 <= y and y < H and 0 <= x and x < W and S[y][x] != S[i][j] )
		{
		  T.unite(vm[y][x],vm[i][j]);
		}
	    }
	}
    }


  vector<bool> used(num,false);
  lli cnt = 0LL;
  REP(i,num)
    {
      if( used[T.root(i)] )
	{
	  continue;
	}

      int n0 = T.gettreesize(i);
      lli nb = T.getblacksize(i);
      lli nw = n0 - nb;

      cnt += nb * nw;
      used[T.root(i)] = true;
    }

  PRINTLLD(cnt);

}

