typedef pair<int, int> ii;

const int N = 2e5 + 10;

int n, row, col;
int pr[N], dx[] = {0, 0, -1, 1}, dy[] = {-1, 1, 0, 0};
string s[405];
bool visit[N];
ii sz[N];

bool check(int x, int y) { return (x >= 1 && x <= row && y >= 1 && y <= col); }
int find(int x) { return x == pr[x] ? x : (pr[x] = find(pr[x])); }
void add(int x1, int y1, int x2, int y2)    {
    int pr1 = x1 * col + y1 - col, pr2 = x2 * col - col + y2;
    if(find(pr1) == find(pr2)) return;
//    cout << x1 << y1 << x2 << y2 << '\n';
    sz[find(pr1)].fi += sz[find(pr2)].fi;
    sz[find(pr1)].se += sz[find(pr2)].se;
    pr[find(pr2)] = find(pr1);
}
signed main()   {
//    freopen("test.inp", "r", stdin);
    ios_base::sync_with_stdio(false);
    cin.tie(0); cout.tie(0);

    cin >> row >> col;
    FOR(i, 1, row)  cin >> s[i];
    FOR(i, 1, row) FOR(j, 1, col) {
        int idx = i * col - col + j;
        pr[idx] = idx;
        sz[idx].fi += (s[i][j - 1] == '.');
        sz[idx].se += (s[i][j - 1] == '#');
    }
    FOR(i, 1, row) FOR(j, 1, col)   {
        FOR(t, 0, 3) {
            int ix = i + dx[t], iy = j + dy[t];
            if(check(ix, iy) && s[ix][iy - 1] != s[i][j - 1]) add(ix, iy, i, j);
        }
    }
    long long ans = 0LL;
    FOR(i, 1, row) FOR(j, 1, col) {
        int idx = find(i * col - col + j);
        if(!visit[idx]) {
            visit[idx] = 1;
            ans += 1ll * sz[idx].fi * sz[idx].se;
        }
    }
    cout << ans;
}

