int dx[4] = {1,0,-1,0};
int dy[4] = {0,1,0,-1};
#define inf 10000000

long long ans,c,nw,sx,sy;

void bfs(int sx,int sy){
    queue<pair<int, int>> q;
    d[sx][sy]=1;
    q.push({sx,sy});
    if(a[sx][sy]==0)nw++;
    while(!q.empty()){
        pair<int, int> p = q.front();
        int tx = p.first;
        int ty = p.second;
        q.pop();

        for(int i=0;i<4;i++){
            int x=tx+dx[i];
            int y=ty+dy[i];
            if(x<0 || x>=h)continue;
            if(y<0 || y>=w)continue;
            if((a[tx][ty]!=a[x][y])&&d[x][y]==0){
                c++;
                if(a[x][y]==0)nw++;
                d[x][y]=1;
                q.push({x,y});

            }
        }
    }
}

