	ll ans = 0;
	for (int si = 0; si < H; si++) {
		for (int sj = 0; sj < W; sj++) {
			if (visited[si][sj]) continue;
			// (si, sj) 始点で bfs
			// (i, j, col)
			ll numB = 0, numH = 0;
			if (S[si][sj] == '#') numB++;
			else numH++;

			queue<pic> qu;
			qu.push(pic(pii(si, sj), S[si][sj]));
			visited[si][sj] = true;
			while (!qu.empty()) {
				auto p = qu.front(); qu.pop();
				int ci = p.first.first, cj = p.first.second;
				char c = p.second;
				if (c == '.') {
					REP(d, 4) {
						int ni = ci + di[d], nj = cj + dj[d];
						if (ni < 0 || ni >= H || nj < 0 || nj >= W || visited[ni][nj] || S[ni][nj] == '.') continue;
						numB++;
						visited[ni][nj] = true;
						qu.push(pic(pii(ni, nj), '#'));
					}
				}
				else if(c == '#') {
					REP(d, 4) {
						int ni = ci + di[d], nj = cj + dj[d];
