LL dx[] = { 0,1 }, dy[] = { 1,0 };
void f(LL i, LL j)
{
	if (vis[i][j]) return;
	vis[i][j] = true;
	memo.push_back(std::make_pair(i, j));
	rep(k, 2)
	{
		LL x = i + dx[k], y = j + dy[k];
		if (x < 0 || H <= x || y < 0 || W <= y) continue;
