class Table {
public:
	vector<vector<int>> vec;
	vector<vector<int>> isVisited;
	vector<vector<int>> moves = { {1,0},{-1,0},{0,1},{0,-1} };
	vector<vector<int>> group;
	UnionFind uf;
	int h, w;
public:
	Table(int H, int W) {
		uf.Init(H * W);
		h = H;
		w = W;
		vec.resize(H,vi(W)); 
		isVisited.resize(H,vi(W,false));
		group.resize(H,vi(W));
		for (int i = 0; i < H; i++) {
			string s; cin >> s;
			for (int j = 0; j < W; j++) {
				if (s[j] == '.') vec[i][j] = 1;
				else vec[i][j] = -1;
				group[i][j] = W * i + j;
			}
		}

	}

	bool DoesExist(vi c1) {// DFS
		stack<vi> st;
		st.push(c1);
		isVisited[c1[0]][c1[1]] = true;
		while (!st.empty()) {
			vi u = st.top(); st.pop();
			for (int i = 0; i < 4; i++) {
				vi v = u + moves[i];
				//Coordinate Validation
				if (v[0] < 0 || v[1] < 0 || v[0] == h || v[1] == w) continue;
				//
				if (vec[v[0]][v[1]] * vec[u[0]][u[1]] == -1 && isVisited[v[0]][v[1]] == false && group[v[0]][v[1]] == w*v[0] + v[1]) {
					uf.unite(w * v[0] + v[1], w * u[0] + u[1]);

					st.push(v);
					isVisited[v[0]][v[1]] = true;
				}
			}
		}

		return false;
	}

	void AllUnite() {

	}
};

signed main() {
	int H, W; cin >> H >> W;
	Table tb(H, W);

	//All Search
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			tb.DoesExist({ i,j });
		}
	}
	vector<vector<int>> res(H *W,vi(2)); //{white,black} for each node
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			int rt = tb.uf.root(W * i + j);
			if (tb.vec[i][j] == 1) {// white
				res[rt][0]++;
			}
			else {
				res[rt][1]++;
			}
		}
	}

	ll ans = 0;
	for (int t = 0; t < H * W; t++) {
		ans += res[t][0] * res[t][1];
	}


	cout << ans << endl;
}

