void dfs(int h, int w, bool iswhite) {
	visited[h][w] = true; if (iswhite)ret++;
	if (h < H-1 && ban[h][w] != ban[h + 1][w] && !visited[h + 1][w])dfs(h + 1, w, !iswhite);
