        // DEBUG(j);
        // DEBUG(result);

        if (i - 1 >= 0) { // 上
            int nextColor = grid[i - 1][j];
            // DEBUG(nextColor);
            P nextCi = make_pair(i - 1, j);
            if (reachedC.count(nextCi) == 0 && (
                (isNextWhite && nextColor == '.') ||
                (!isNextWhite && nextColor == '#'))) {
                nextC.push(nextCi);
                reachedC.insert(nextCi);
                // DEBUG("上");
                if (isNextWhite) result++;
            }
        } 
        if (j - 1 >= 0) { // 左
            int nextColor = grid[i][j - 1];
            // DEBUG(nextColor);
            P nextCi = make_pair(i, j - 1);
            if (reachedC.count(nextCi) == 0 && (
                (isNextWhite && nextColor == '.') ||
                (!isNextWhite && nextColor == '#'))) {
                nextC.push(nextCi); 
                reachedC.insert(nextCi);
                // DEBUG("左");
                if (isNextWhite) result++;
            }
        } 
        if (i + 1 < H) { // 下
            int nextColor = grid[i + 1][j];
            // DEBUG(nextColor);
            P nextCi = make_pair(i + 1, j);
            if (reachedC.count(nextCi) == 0 && (
                (isNextWhite && nextColor == '.') ||
                (!isNextWhite && nextColor == '#'))) {
                nextC.push(nextCi); 
                reachedC.insert(nextCi);
                // DEBUG("下");
                if (isNextWhite) result++;
            }
        }
        if (j + 1 < W) { // 右
            int nextColor = grid[i][j + 1];
            // DEBUG(nextColor);
            P nextCi = make_pair(i, j + 1);
            if (reachedC.count(nextCi) == 0 && (
                (isNextWhite && nextColor == '.') ||
                (!isNextWhite && nextColor == '#'))) {
                nextC.push(nextCi); 
                reachedC.insert(nextCi);
                // DEBUG("右");
                if (isNextWhite) result++;
            }
        }

        if(currentC.empty()) {
            currentC = nextC; // 空になったら次の世代を代入
            queue<P> newNextC;
            nextC = newNextC;
            if (isNextWhite) { // 次の世代は白黒反転
                isNextWhite = false;
            } else {
                isNextWhite = true;
            }
        }
    }
}

