struct UnionFind {
	vector<int> parent;
	vector<int> black, white;

	UnionFind(int size) : parent(size, -1) {
		black.resize(size, 0);
		white.resize(size, 0);
		for (int u=0; u<size; u++) {
			int i = u/W;
			int j = u%W;
			if (board[i][j] == '#')
				black[u]++;
			else
				white[u]++;
		}
	}


	int find(int a) {
		if (parent[a] < 0) return a;
		return parent[a] = find(parent[a]);
	}

	// Returns false if a and b are already contained it the same set
	bool merge(int a, int b) {
		a = find(a); b = find(b);
		if (a==b) return false;

		// a should be the parent of b
		if (parent[a] > parent[b]) swap(a, b);
		parent[a] += parent[b];
		parent[b] = a;

		black[a] += black[b];
		white[a] += white[b];

		return true;
	}

	void clear() {
		for (int &p : parent) p = -1;
	}
};



int main() {
	//freopen("input.txt", "r", stdin);

	cin >> H >> W;
	for (int i=0; i<H; i++) cin >> board[i];

	UnionFind uf(H*W);
	for (int i=0; i<H; i++) for (int j=0; j<W-1; j++) 
		if (board[i][j] != board[i][j+1])
			uf.merge(idx(i, j), idx(i, j+1));

	for (int i=0; i<H-1; i++) for (int j=0; j<W; j++) 
		if (board[i][j] != board[i+1][j])
			uf.merge(idx(i, j), idx(i+1, j));

	ll ans = 0;
	for (int u=0; u<H*W; u++) if (uf.parent[u] < 0) {
		ans += uf.black[u] * uf.white[u];
	}

	cout << ans << endl;



	return 0;
}

