                uft.unite(idx(x,y),idx(x,y+1));
            }
        }
    }
    ll ans=0;
    ll b[n]={};
    ll w[n]={};
    FOR(y,0,H){
        FOR(x,0,W){
            auto p = uft.find(idx(x,y));
            if(getch(x,y)=='#'){
                ++b[p];
            }else{
                ++w[p];
            }
        }
    }
    REP(i,n){
        ans += b[i]*w[i];
    }
    cout<<ans<<endl;
    return 0;
}

