    ll ans = 0;
    rep(i, h) {
        rep(j, w) {
            int now = i*w+j;
            if(uft.size(now) != 1) continue;
            queue<int> que;
            que.push(now);
            int cou = 0;
            while(!que.empty()) {
                int nn = que.front();
