                    if(s[ni][nj] == s[ni-di[k]][nj-dj[k]]) continue;
                    if(uft.same(now, ni*w+nj)) continue;
                    que.push(ni*w+nj);
                    uft.unite(now, ni*w+nj);
                }
            }
            ll aa = uft.size(now);
            ans += (aa-cou) * cou;
