bool neighbor(int i1, int j1, int i2, int j2){
    if(abs(i1 - i2) == 0){
        if(abs(j1 - j2) == 1) return true;
        else return false;
    }else if(abs(i1 - i2) == 1){
        if(abs(j1 - j2) == 0) return true;
        else return false;
    }
    return false;
}

bool alter(int i1, int j1, int i2, int j2){
    return board.at(i1).at(j1) + board.at(i2).at(j2) == 1;
}

int router(int i1, int j1, int i2, int j2){
    if(memo.at(i1).at(j1).at(i2).at(j2) != -1) return memo.at(i1).at(j1).at(i2).at(j2);
    if(neighbor(i1, j1, i2, j2)){
        if(alter(i1, j1, i2, j2)){
            memo.at(i1).at(j1).at(i2).at(j2) = 1;
            memo.at(i2).at(j2).at(i1).at(j1) = 1;
            return 1;
        }else{
            memo.at(i1).at(j1).at(i2).at(j2) = 0;
            memo.at(i2).at(j2).at(i1).at(j1) = 0;
            return 0;
        }
    }else{
        int result = 0;
        if(i1 > 0){
            if(alter(i1 - 1, j1, i2, j2)) result = router(i1 - 1, j1, i2, j2);
        }
        if(result == 1){
            memo.at(i1).at(j1).at(i2).at(j2) = 1;
            memo.at(i2).at(j2).at(i1).at(j1) = 1;
            return 1;
