            memo.at(i2).at(j2).at(i1).at(j1) = 1;
            return 1;
        }
        if(j1 > 0){
            if(alter(i1, j1 - 1, i2, j2)) result = router(i1, j1 - 1, i2, j2);
        }
        if(result == 1){
            memo.at(i1).at(j1).at(i2).at(j2) = 1;
            memo.at(i2).at(j2).at(i1).at(j1) = 1;
