	      // cerr << j << " " << i << " " << xx << " " << yy << endl;
	      uf.unite(i*H+j, yy*H+xx);
	    }
	  }
	}
      }
    }
  }

  for(int i = 0; i < H; i++){
    for(int j = 0; j < W; j++){
