			checked[i][j] = true;

			while(!q.empty()){
				P nowp = q.front();
				q.pop();
				//cout << nowp.first << " " << nowp.second << endl;

				if(s[nowp.first][nowp.second] == '.'){
					cnt1++;
				}
				else{
					cnt2++;
				}

				rep(i,4){
					P nextp = P(nowp.first + dx[i], nowp.second + dy[i]);

					if(0 <= nextp.first && nextp.first < h && 
					   0 <= nextp.second && nextp.second < w && 
					   !checked[nextp.first][nextp.second] && 
					   s[nowp.first][nowp.second] != s[nextp.first][nextp.second]){
					   	q.push(nextp);
					   	checked[nextp.first][nextp.second] = true;
					}
				}
			}

			ll += cnt1 * cnt2;
		}
	}

	cout << res << endl;

	return 0;
}

