  for (int y = 0; y < h; y++) {
    for (int x = 0; x < w; x++) {
      if (!is_visited[y][x]) {
        ans += bfs(x, y, is_visited, grid);
      }
    }
  }
  cout << ans << "\n";

  return 0;
}

