            {
                int x = i+dirx[k];
                int y = j+diry[k];
                if(x>0&&x<=n&&y>0&&y<=m && s[i][j]!=s[x][y])
                    Join(f(x,y),f(i,j));
            }
        }
    }
    for(int i=1;i<=n;i++)
    {
        for(int j=1;j<=m;j++)
        {
            int t = Find(f(i,j));
