Pi solve(int h, int w, int p) {
	used[h][w] = true;
	int b = 0, s = 0;
	if (f[h][w] == '#')b++;
	else s++;

	rep(d, 4) {
		int nh = h + dir4[d][0];
		int nw = w + dir4[d][1];
		if (nh >= 0 && nh < H&&nw >= 0 && nw < W && !used[nh][nw]) {
			if (pattern[nh][nw] != p)continue;
			Pi rec = solve(nh, nw, p);
			b += rec.first;
			s += rec.second;
		}
	}
	return mp(b, s);
}

