inline void countWhite(int startI, int startJ) {
    // DEBUG(startI);
    // DEBUG(startJ);
    bool isNextWhite = true;
    bool reachedC[401][401] = {false};
    reachedC[startI][startJ] = true;
    queue<P> currentC;
    queue<P> nextC;
    currentC.push(make_pair(startI, startJ));

    while (!currentC.empty()) {
        P ci = currentC.front();
        currentC.pop();
        int i = ci._1;
        int j = ci._2;
        // DEBUG("---");
        // DEBUG(i);
        // DEBUG(j);
        // DEBUG(result);

        if (i - 1 >= 0) { // 上
            int nextColor = grid[i - 1][j];
            // DEBUG(nextColor);
            if (!reachedC[i - 1][j] && (
                (isNextWhite && nextColor == '.') ||
                (!isNextWhite && nextColor == '#'))) {
                P nextCi = make_pair(i - 1, j);
                nextC.push(nextCi);
                reachedC[i - 1][j] = true;
                // DEBUG("上");
                if (isNextWhite) result++;
            }
        } 
        if (j - 1 >= 0) { // 左
            int nextColor = grid[i][j - 1];
            // DEBUG(nextColor);
            if (!reachedC[i][j - 1] && (
                (isNextWhite && nextColor == '.') ||
                (!isNextWhite && nextColor == '#'))) {
                P nextCi = make_pair(i, j - 1);
                nextC.push(nextCi); 
                reachedC[i][j - 1] = true;
                // DEBUG("左");
                if (isNextWhite) result++;
            }
        } 
        if (i + 1 < H) { // 下
            int nextColor = grid[i + 1][j];
            // DEBUG(nextColor);
            if (!reachedC[i + 1][j] && (
                (isNextWhite && nextColor == '.') ||
                (!isNextWhite && nextColor == '#'))) {
                P nextCi = make_pair(i + 1, j);
                nextC.push(nextCi); 
                reachedC[i + 1][j] = true;
                // DEBUG("下");
                if (isNextWhite) result++;
            }
        }
        if (j + 1 < W) { // 右
            int nextColor = grid[i][j + 1];
            // DEBUG(nextColor);
            if (!reachedC[i][j + 1] && (
                (isNextWhite && nextColor == '.') ||
                (!isNextWhite && nextColor == '#'))) {
                P nextCi = make_pair(i, j + 1);
                nextC.push(nextCi); 
                reachedC[i][j + 1] = true;
                // DEBUG("右");
                if (isNextWhite) result++;
            }
        }

        if(currentC.empty()) {
            currentC = nextC; // 空になったら次の世代を代入
            queue<P> newNextC;
            nextC = newNextC;
            if (isNextWhite) { // 次の世代は白黒反転
                isNextWhite = false;
            } else {
                isNextWhite = true;
            }
        }
    }
}

