		}
		if (col - 1 >= 0) {
			if (matrix[row][col - 1] == -2) count(row, col-1,num);
		}
		if (col + 1 < W) {
			if (matrix[row][col + 1] == -2) count(row, col +1,num);
		}
	}

	if (temp == -2) {
      	matrix[row][col] = num;
		if (row - 1 >= 0) {
			if (matrix[row - 1][col] == -1) count(row - 1,col,  num);
		}
		if (row + 1 < H) {
			if (matrix[row + 1][col] == -1) count(row +1, col, num);
		}
		if (col - 1 >= 0) {
			if (matrix[row][col - 1] == -1) count(row, col -1, num);
		}
