string grid[555];
bool used[555][555];

int main(void) {
  ios::sync_with_stdio(false); cin.tie(0);


  ll h, w;
  cin >> h >> w;
  rep(i, h) cin >> grid[i];
  queue<pll> q;
  pll cur;
  rep(y, h) rep(x, w) {
    if (used[y][x]) continue;
    q.push(make_pair(y, x));
    used[y][x] = true;
    ll a = 0, b = 0;
    while (!q.empty()) {
      cur = q.front();
      q.pop();
      if (grid[cur.first][cur.second] == '.') a++;
      else b++;
      FOR(i, 1, 5) {
        pll to = pll(cur.first + dy[i], cur.second + dx[i]);
        if (to.first < 0 || to.first >= h || to.second < 0 || to.second >= w) continue;
        if (used[to.first][to.second]) continue;
        if (grid[cur.first][cur.second] == grid[to.first][to.second]) continue;
        used[to.first][to.second] = true;
        q.push(to);
      }
    }
    ans += a * b;
  }
  cout << ans << endl;


  return 0;
}

