int h, w;
std::vector<std::string> map;
std::vector<std::vector<long long>> label;
std::vector<long long> numBlack;
std::vector<long long> numWhite;
long long ans=0;

void dfs(int y, int x, int l){
	if(map[y][x]=='#')
		numBlack[l]++;
	if(map[y][x]=='.')
		numWhite[l]++;

	if(y+1< h){
		if(map[y][x]!= map[y+1][x] && label[y+1][x]==-1){
			label[y+1][x]=l;
			dfs(y+1, x,  l);
		}
	}
	if(y-1>= 0){
		if(map[y][x]!= map[y-1][x] && label[y-1][x]==-1){
			label[y-1][x]= l;
			dfs(y-1, x, l);
		}
	}
	if(x+1< w){
		if(map[y][x]!= map[y][x+1] && label[y][x+1]==-1){			
			label[y][x+1]= l;
			dfs(y, x+1, l);
		}
	}
	if(x-1>= 0){
		if(map[y][x]!= map[y][x-1] && label[y][x-1]==-1){
			label[y][x-1]= l;
			dfs(y, x-1, l);
		}
	}
}

int main(){

	std::cin>>h>>w;
	map.resize(h);
	label.resize(h);

	for(int i=0; i<h; i++)
		label[i].resize(w, -1);

	for(int i=0; i<h; i++)
		std::cin>>map[i];

	long long curL=0;
	for(int i=0; i<h; i++){
		for(int j=0; j<w; j++){
			if(label[i][j]==-1){
				numBlack.push_back(0);
				numWhite.push_back(0);

				label[i][j]=curL;
				dfs(i, j, curL);
				curL++;
			}

		}

	}

	for(int i=0; i<curL; i++)
		ans+= numWhite[i]* numBlack[i];

	std::cout<<ans<<std::endl;

	return 0;


}

