using namespace std;
using ll = long long;
using ld = long double;

int H, W;
vector<vector <int>> SS;
int writeCount;
int blackCount;

const int UNCHECKED_WRITE = -1;
const int UNCHECKED_BLACK = 0;
const int CHECKED_WRITE = -2;
const int CHECKED_BLACK = 1;
const int OUT_OF_AREA = -3;


void checkAroundByBlack(int x, int y);

int checkBlock(int x, int y) {

    if (x < 0 || x >= H) {
        return OUT_OF_AREA;
    }
    if (y < 0 || y >= W) {
        return OUT_OF_AREA;
    }

    return SS[x][y];
}


//白に隣接している黒をチェック
//調べ済みの黒は調べない
void checkAroundByWrite(int x, int y) {

    writeCount++;
    //調べた白には-2を入れる
    SS[x][y] = CHECKED_WRITE;

    if (checkBlock(x - 1, y) == UNCHECKED_BLACK) {
        checkAroundByBlack(x - 1, y);
    }
    if (checkBlock(x + 1, y) == UNCHECKED_BLACK) {
        checkAroundByBlack(x + 1, y);
    }
    if (checkBlock(x, y - 1) == UNCHECKED_BLACK) {
        checkAroundByBlack(x, y - 1);
    }
    if (checkBlock(x, y + 1) == UNCHECKED_BLACK) {
        checkAroundByBlack(x, y + 1);
    }
}

//黒に隣接している白をチェック。
//調べ済みの白は調べない
void checkAroundByBlack(int x, int y) {

    //cout << "Black: " << "x: " << x << " y: " << y << endl;
    blackCount++;
    //調べた黒には1を入れる
    SS[x][y] = CHECKED_BLACK;

    // 左が白かチェックして、そうなら、白の周辺が黒かチェック
    if (checkBlock(x - 1, y) == UNCHECKED_WRITE) {
        checkAroundByWrite(x - 1, y);
    }
    // 右が白かチェックして、そうなら、白の周辺が黒かチェック
    if (checkBlock(x + 1, y) == UNCHECKED_WRITE) {
        checkAroundByWrite(x + 1, y);
    }
    // 上が白かチェックして、そうなら、白の周辺が黒かチェック
    if (checkBlock(x, y - 1) == UNCHECKED_WRITE) {
        checkAroundByWrite(x, y - 1);
    }
    // 下が白かチェックして、そうなら、白の周辺が黒かチェック
    if (checkBlock(x, y + 1) == UNCHECKED_WRITE) {
        checkAroundByWrite(x, y + 1);
    }
}

int main() {


    cin >> H >> W;

    SS.resize(H);
    for (int i = 0; i < H; ++i) {
        SS[i].resize(W);
    }

    //白なら-1, 黒なら0を入れる
    for (int i = 0; i < H; ++i) {
        string S;
        cin >> S;
        for (int j = 0; j < W; ++j) {
            int s;
            if (S[j] == '#') {
                s = UNCHECKED_BLACK;
            }
            if( S[j] == '.'){
                s = UNCHECKED_WRITE;
            }
            SS[i][j] = s;
        }
    }
    int result = 0;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            // まだ調べていない黒を調べる
            if (SS[i][j] == UNCHECKED_BLACK) {
                writeCount = 0;
                blackCount = 0;
                checkAroundByBlack(i, j);
                result += writeCount * blackCount;
            }
        }
    }

    cout << result << endl;

    return 0;
}

