struct union_find{
	int N;
	vector<int> parent;
	vector<int> siz;

	union_find(int N) : parent(N), siz(N, 1){
		for (int i = 0; i < N; i++) parent[i] = i;
	}

	int root(int x){
		if(parent[x] == x) return x;
		else return parent[x] = root(parent[x]);
	}

	void merge(int x, int y){
		x = root(x), y = root(y);
		if(x == y) return;
		if(siz[x] < siz[y]) swap(x, y);
		parent[y] = x;
		siz[x] += siz[y];
		siz[y] = 0;
	}

	bool are_same(int x, int y){
		return root(x) == root(y);
	}

	int size(int x){
		return siz[root(x)];
	}
};

signed main(){
	int H, W, i, j;
	scanf("%lld%lld", &H, &W);
	vector<string> S(H);
	for(i = 0; i < H; i++){
		cin >> S[i];
	}
	union_find uf(H * W);
	for(i = 0; i < H; i++){
		for(j = 1; j < W; j++){
			if(S[i][j - 1] != S[i][j]){
				uf.merge(i * W + (j - 1), i * W + j);
			}
		}
	}
	for(i = 1; i < H; i++){
		for(j = 0; j < W; j++){
			if(S[i - 1][j] != S[i][j]){
				uf.merge((i - 1) * W + j, i * W + j);
			}
		}
	}
	vector<int> black(H * W, 0), white(H * W, 0);
	for(i = 0; i < H * W; i++){
		if(S[i / W][i % W] == '#'){
			black[uf.root(i)]++;
		}
		else{
			white[uf.root(i)]++;
		}
	}
	int ans = 0;
	for(i = 0; i < H * W; i++){
		ans += black[i] * white[i];
	}
	printf("%lld\n", ans);
	return 0;
}

