int dy[4]{-1,0,1,0};
int dx[4]{0,-1,0,1};

int H,W;
char field[410][410];
bool table[410][410];

ll cnt(int y,int x){
  int brack = 1,white = 0;
  memset(table,sizeof(table),true);
  queue<tuple<int,int,bool>> Q;
  Q.emplace(y,x,true);
  table[y][x] = false;
  while(Q.size()){
    int y,x;bool frag;
    tie(y,x,frag) = Q.front();
    Q.pop();
    rep(i,4){
      int ny = y + dy[i],nx = x + dx[i];
      if(0 <= ny && ny < H && 0 <= nx && nx < W){
        if(frag && field[ny][nx] == '.' && table[ny][nx]){
          white++;
          table[ny][nx] = false;
          Q.emplace(ny,nx,false);
        }
        if(! frag && field[ny][nx] == '#' && table[ny][nx]){
          brack++;
          table[ny][nx] = false;
          Q.emplace(ny,nx,true);
        }
      }
    }
  }
  return white*1000000+brack;
}

int main(){
  cin >> H >> W;
  rep(i,H) rep(j,W) cin >> field[i][j];
  rep(i,H) rep(j,W) table[i][j] = true;
  int ans = 0;
  rep(i,H) rep(j,W){
    if(table[i][j] && field[i][j] == '#'){
      ll a = cnt(i,j);
      ll w = a / 1000000,b = a % 1000000;
      ans += w * b;
    }
  }
  cout << ans << endl;
}

