using namespace std;
const int dh[4] = {0, 1, 0, -1};
const int dw[4] = {1, 0, -1, 0};
struct UnionFind {
    vector<int> data; int sz;
    UnionFind(int sz) : data(sz, -1), sz(sz) { }
    bool unionSet(int x, int y) {
        if ((x = root(x)) == (y = root(y))) { return false; }
        if (data[x] > data[y]) { swap(x, y); }
        data[x] += data[y]; data[y] = x; sz--; return true;
    }
    bool findSet(int x, int y) { return root(x) == root(y); }
    int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
    int size(int x) { return -data[root(x)]; }
    int size() { return sz; }
};

int main() {
    int H, W;
    cin >> H >> W;
    UnionFind uf(H*W);
    vector<string> S(H);
    vector<long long> white(H*W, 0);
    for (int i = 0; i < H; i++) cin >> S[i];

    auto idx = [=] (int h, int w) { return h * W + w; };
    for (int h = 0; h < H; h++) for (int w = 0; w < W; w++) {
        int u = idx(h, w);
        for (int i = 0; i < 4; i++) {
            int nh = h + dh[i], nw = w + dw[i];
            int v = idx(nh, nw);
            if ((nh < 0 || H <= nh || nw < 0 || W <= nw)) continue;
            if (S[h][w] != S[nh][nw]) uf.unionSet(u, v);
        }
    }

    for (int h = 0; h < H; h++) for (int w = 0; w < W; w++) {
        int u = idx(h, w), i = uf.root(u);
        if (S[h][w] == '.') white[i]++;
    }

    long long ans = 0;
    for (int h = 0; h < H; h++) for (int w = 0; w < W; w++) {
        int u = idx(h, w), i = uf.root(u);
        if (S[h][w] == '#') ans += white[i];
    }

    cout << ans << endl;
    return 0;
}

