            }
            if(i-1>=0 && !visited[i-1][j]){
                dfs(i-1, j, masu[i][j]);
            }
        }
    } else {
        if(j+1<W && !visited[i][j+1]){
            dfs(i, j+1, masu[i][j]);
        }
        if(j-1>=0 && !visited[i][j-1]){
