int bfs(int x, int y){
  int wh=0,bl=1;
  queue<P> q;
  q.push({x,y});
  used[x][y]=true;

  while(!q.empty()){
    P p = q.front(); q.pop();
    rep(i,4){
      int nx = p.F+dx[i], ny = p.S+dy[i];
      if(nx<0 || h<=nx || ny<0 || w<=ny) continue;
      if(used[nx][ny]) continue;
      if(d[p.F][p.S]==d[nx][ny]) continue;
      q.push({nx,ny});
      used[nx][ny] = true;
      if(d[nx][ny]=='.'){ wh++; } else { bl++; }
    }
  }
  return wh*bl;
}

