struct UnionFind {
    typedef pair<int, int> P;
    vector<vector<P> > par; 

    UnionFind(int X,int Y) : par(X+2) { //最初は全てが根であるとして初期化
        for(int i = 1; i <= X+1; i++){
            par[i].resize(Y+2);
            for(int j = 1; j <= Y+1; j++){
                par[i][j]=make_pair(i,j);
            }
        } 
    }

    P root(P p) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[p.first][p.second] == p) return p;
        return par[p.first][p.second] = root(par[p.first][p.second]);
    }

    void unite(P x, P y) { // xとyの木を併合
        P rx = root(x); //xの根をrx
        P ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx.first][rx.second] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(P x, P y) { // 2つのデータx, yが属する木が同じならtrueを返す
        P rx = root(x);
        P ry = root(y);
        return rx == ry;
    }
};

int main() {

    int  H,W;

    std::cin >> H;
    std::cin >> W;
    int a[402][402]; 

    for(int i = 1 ; i <= H;i++){
        string tmp;
        cin >> tmp;
        for(int j=0 ; j < W ;j++){
            if(tmp[j]=='#'){
                a[i][j+1]=-1;
            }else if(tmp[j]=='.'){
                a[i][j+1]=1;
            }
        } 
    }

    UnionFind tree(H,W);


    for(int i = 1 ; i <= H;i++){

        for(int j = 1 ; j <= W ;j++){
            if(a[i][j]*a[i-1][j]==-1) tree.unite(make_pair(i,j),make_pair(i-1,j));            
            if(a[i][j]*a[i][j-1]==-1) tree.unite(make_pair(i,j),make_pair(i,j-1));
            if(a[i][j]*a[i+1][j]==-1) tree.unite(make_pair(i,j),make_pair(i+1,j));
            if(a[i][j]*a[i][j+1]==-1) tree.unite(make_pair(i,j),make_pair(i,j+1));
        }
    }

    queue<pair<int,int> > list;
    map<pair<int,int>,int> black;
    map<pair<int,int>,int> white;
    for(int i = 1 ; i <= H;i++){
        for(int j = 1 ; j <= W ;j++){
            pair<int,int> point = make_pair(i,j);
            pair<int,int> parent=tree.root(point);
            if( black.find(parent) == black.end() && white.find(parent) == white.end()){
                list.push(parent);
            } 
            if(a[i][j]==-1) black[parent]++;
            if(a[i][j]==1) white[parent]++;

        }
    }
    ll answer=0;
    while(!list.empty()){

        answer += black[list.front()]*white[list.front()];
        list.pop();

    }

    cout << answer << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {

	int r, c; cin >> r >> c;

	vector<vector<char>> a(r + 2, vector<char>(c + 2, 'e'));
	for (int i = 1; i <= r; i++) for (int j = 1; j <= c; j++) cin >> a[i][j];

	vector<vector<bool>> used(r + 2, vector<bool>(c + 2, false));
	ll ans = 0;
	ll b, w;	
	for (int sy = 1; sy <= r; sy++) {
		for (int sx = 1; sx <= c; sx++) {

			if (used[sy][sx]) continue;
			b = 0;
			w = 0;

			// BFS のためのデータ構造
			queue<pair<int, int>> que;
			used[sy][sx] = true;

			// 初期条件
			que.push({ sy,sx });

			const int dy[4] = { 1, 0, -1, 0 };
			const int dx[4] = { 0, 1, 0, -1 };

			// BFS 開始 (キューが空になるまで探索を行う)
			while (!que.empty()) {

				pair<int, int> p = que.front(); // キューから先頭頂点を取り出す
				que.pop();

				int y_now = p.first;
				int x_now = p.second;
				if (a[y_now][x_now] == '.') w++;
				else b++;

				// p から辿れるマスをすべて調べる
				for (int i = 0; i < 4; i++) {

					int y_next = p.first + dy[i];
					int x_next = p.second + dx[i];

					if (a[y_next][x_next] == 'e') continue;
					if (a[y_next][x_next] == a[y_now][x_now]) continue;
					if (used[y_next][x_next]) continue;					

					used[y_next][x_next] = true;					
					que.push({ y_next, x_next });

				}

			}
			ans += b * w;
		}
	}
	cout << ans << endl;
    return 0;
}

