#define double long double 
#define fi first
#define se second
#define pii pair<int, int>

int h, w;

const int N = 410 * 410;
vector<vector<int>> g(N);
vector<bool> visited(N, false);
vector<vector<int>> comp;

int ind(int i, int j) {
  return i * w + j;
}

pii rind(int idx) {
  return {idx / w, idx % w};
}

bool valid(int i, int j) {
  return 0 <= i && i < h && 0 <= j && j < w;
}

void dfs(int v) {
  visited[v] = true;
  for (auto &u : g[v]) {
    if (!visited[u]) dfs(u);
  }
  comp.back().push_back(v);
}
signed main() {
  ios::sync_with_stdio(false); cin.tie(nullptr);
  cin >> h >> w;

  string s[h];
  for (int i = 0; i < h; i++) {
    cin >> s[i];
  }
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      vector<pii> dir = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};
      for (auto &d : dir) {
        int ii = i + d.fi, jj = j + d.se;
        if (!valid(ii, jj)) continue;
        if (s[i][j] != s[ii][jj]) {
          g[ind(i, j)].push_back(ind(ii, jj));
        }
      }
    }
  }
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (!visited[ind(i, j)]) {
        comp.push_back({});
        dfs(ind(i, j));
      }
    }
  }
  int ans = 0;
  for (auto &c : comp) {
    int cnt = 0;
    for (auto &idx : c) {
      auto r = rind(idx);
      if (s[r.fi][r.se] == '.') cnt++;
    }
    ans += cnt * (sz(c) - cnt);
  }
  cout << ans << "\n";
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
#define FOR(I,A,B) for(int I = int(A); I < int(B); ++I)

class UnionFind{
public:
	vector<int> par;
	vector<long long> g1,g2;
	//0-indexed
	void init(int n = 1) {
		par.resize(n);
		for (int i = 0; i < n; ++i) par[i] = i;
		g1.resize(n,0);
		g2.resize(n,0);
	}
	int root(int x = 1){
		if(par[x]==x)return x;
		else{
			return par[x] = root(par[x]);
		}
	}
	void unite(int x = 1,int y = 1){
		x = root(x);
		y = root(y);
		if(x==y)return;
		g1[y] += g1[x];
		g2[y] += g2[x];
		par[x] = y;
	}
};

int main(){
	ios::sync_with_stdio(false);
	cin.tie(0);
	int H,W;
	ll ans=0;
	cin >> H >> W;
	string s[H];
	FOR(i,0,H){
		cin >> s[i];
	}
	UnionFind uf;
	uf.init(H*W);
	// (x,y) -> W*x+y
	FOR(i,0,H){
		FOR(j,0,W){
