void count(int i, int j){
  if(S[i-1][j]=='.' && i>0){
    ans++;
    white(i-1, j);
  }
  if(S[i+1][j]=='.' && i<H-1){
    ans++;
    white(i-1, j);
  }
  if(S[i][j-1]=='.' && j>0){
    ans++;
    white(i, j-1);
  }
  if(S[i][j+1]=='.' && j<W-1){
    ans++;
    white(i, j+1);
  }
}

void white(int i, int j){
  if(S[i-1][j]=='.' && i>0){
    count(i-1, j);
  }
  if(S[i+1][j]=='.' && i<H-1){
    count(i-1, j);
  }
  if(S[i][j-1]=='.' && j>0){
    count(i, j-1);
  }
  if(S[i][j+1]=='.' && j<W-1){
    count(i, j+1);
  }
}

