int H, W;
int di[4] = {-1, 0, 1, 0}, dj[4] = {0, -1, 0, 1};
char C[405][405];
bool visited[405][405];
ll ans = 0;

int Solve(){
  int nowi = 0; ll cntw = 0, cntb = 0;
  queue <Pii> que; que.push({0, 0});
  visited[0][0] = true;
  while (!que.empty()){
    Pii Q = que.front(); que.pop();

    if (C[Q.fi][Q.se] == '#') cntb++;
    else cntw++;

    for (int k = 0; k < 4; k++){
      int I = Q.fi + di[k], J = Q.se + dj[k];
      if (I < 0 || H <= I || J < 0 || W <= J) continue;
      if (C[Q.fi][Q.se] == C[I][J]) continue;
      if (visited[I][J]) continue;
      que.push({I, J});
      visited[I][J] = true;
    }

    if (que.empty()){
      ans += cntb * cntw;
      cntb = 0; cntw = 0;
      for (int i = nowi; i < H; i++){
        for (int j = 0; j < W; j++){
          if (!visited[i][j]){
            que.push({i, j});
            nowi = i; visited[i][j] = true;
            break;
          }
        }
        if (!que.empty()) break;
      }
    }
  }
  printf("%lld\n", ans);

  return 0;
}

