int dy[8] = {0, -1, 0, 1, -1, -1, 1, 1};

int dx2[4] = {-2, 0, 2, 0};
int dy2[4] = {0, -2, 0, 2};


int main() {
  std::cin.tie(nullptr);
  std::ios_base::sync_with_stdio(false);
  std::cout << std::fixed << std::setprecision(15);
  ll h,w;
  cin >> h >> w;
  vector<string> S(h);
  rep(i,h) cin >> S[i];

  auto get_id = [&](int x, int y) {
    return w*y + x;
  };
  UnionFind tree(h*w);
  rep(y,h) rep(x,w) {
    if (S[y][x] == '#') {
      for (int i = 4; i < 8; ++i) { //斜め移動
        int nx = x + dx[i],  ny = y + dy[i];
        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
        if (S[ny][nx] == '#' && (S[ny][x] == '.' || S[y][nx] == '.')) {
          tree.merge(get_id(x,y), get_id(nx,ny));
        }
      }
      rep(i,4) { //1つ飛ばし
        int nx = x + dx2[i],  ny = y + dy2[i];
        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
        if (S[ny][nx] == '#' && S[y + dy[i]][x + dx[i]] == '.') {
          tree.merge(get_id(x,y), get_id(nx,ny));
        }
      }
    }
  }

  vector<vector<int> > A(h*w);
  rep(y,h) rep(x,w) {
    if (S[y][x] == '#') {
      rep(i,4) {
        int nx = x + dx[i], ny = y + dy[i];
        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
        if (S[ny][nx] == '.') {
          A[tree.root(get_id(x,y))].emplace_back(get_id(nx,ny));
        }
      }
    }
  }
  ll ans = 0;
  rep(i,h*w) {
    if (A[i].size() == 0) continue;
    vector<bool> checked(h*w,false);
    ll cnt = 0;
    for (auto x : A[i]) {
      if (!checked[x]) {
        cnt++;
        checked[x] = true;
      }
    }
    ans += tree.size(i) * cnt;
  }
  cout << ans << endl;
  return 0;
}

