                    if(d[i+act[a].x][j+act[a].y].color == 1 && i+act[a].x >= 0 && i+act[a].x < H && j+act[a].y >= 0 && j+act[a].y < W){
                        if(root(i,j) != root(i+act[a].x, j+act[a].y)){
                            unite(i,j, i+act[a].x,j+act[a].y);
                        }
                    }
                }
            }
            if(d[i][j].color == 1){
                for(int a = 0; a < 4; a++){
