                        if(root(i,j) != root(i+act[a].x, j+act[a].y)){
                            unite(i,j, i+act[a].x,j+act[a].y);
                        }
                    }
                }
            }

        }
    }

    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            if(d[i][j].color == 0){
                num[root(i,j)].black++;
            }
            if(d[i][j].color == 1){
                num[root(i,j)].white++;
            }
        }
    }

    for(int i = 0; i < H*W; i++){
        ans += num[i].black * num[i].white;
    }

    cout << ans << endl;


    return 0;
}

