class UnionFind {
  public:
    vi Parent;
    UnionFind(int N) {
      Parent = vi(N,-1);
    }

    int root(int A) {
      if(Parent[A] < 0) return A;
      return Parent[A] = root(Parent[A]);
    }

    int size(int A) {
      return -Parent[root(A)];
    }

    bool connect(int A,int B) {
      A = root(A);
      B = root(B);
      if(A == B) return false;
      if(size(A) < size(B)) swap(A,B);
      Parent[A] += Parent[B];
      Parent[B] = A;
      return true;
    }
};

int main() {
  int H,W;
  cin >> H >> W;
  v(string) G(H);
  rep(i,H) {
    cin >> G[i];
  }
  UnionFind t = UnionFind(H*W);
  rep(i,H) {
    rep(j,W) {
      if(i-1>=0 && G[i][j] != G[i-1][j]) {
        t.connect(i*W+j,(i-1)*W+j);
      }
      if(j-1>=0 && G[i][j] != G[i][j-1]) {
        t.connect(i*W+j,i*W+j-1);
      }
    }
  }
  vi b(H*W,0),w(H*W,0);

  rep(i,H) {
    rep(j,W) {
      if(G[i][j] == '#') {
        b[t.root(i*W+j)]++;
      } else {
        w[t.root(i*W+j)]++;
      }
    }
  }
  ll ans = 0;
  rep(i,H*W) {
    if(b[i] <= 0 || w[i] <= 0) continue;
    ans += 1ll * b[i] * w[i];
  }
  cout << ans << endl;
  return 0;
}

