pair<int,int> bfs(int Sx,int Sy){
    queue<node> Q;
    Q.push((node){Sx,Sy,0});
    vis[Sx][Sy]=1;
    int cnt1=0,cnt2=0;
    while(!Q.empty()){
        node u=Q.front();Q.pop();
        cnt1+=str[u.x][u.y]=='.',cnt2+=str[u.x][u.y]=='#';
        for(int i=0;i<4;i++){
            int x=u.x+dir[i][0],y=u.y+dir[i][1];
