                if(!vis[x][y]&&(str[x][y]=='.')==u.color){
                    vis[x][y]=1;
                    Q.push((node){x,y,str[x][y]=='#'});
                }
            }
        }
    }
    return make_pair(cnt1,cnt2);
}

