int main() {
  int table[kMax][kMax] = {};
  constexpr int dr[] = {1, -1, 0, 0};
  constexpr int dc[] = {0, 0, 1, -1};

  int H, W; std::cin >> H >> W;
  bool checked[kMax][kMax];
  for (int r = 0; r < H; ++r) {
    std::string s; std::cin >> s;
    for (int c = 0; c < W; ++c) {
      if (s[c] == '#') table[r][c] = 1;
      checked[r][c] = false;
    }
  }

#if DEBUG
  for (int r = 0; r < H; ++r) {
    for (int c = 0; c < W; ++c) {
      std::cout << table[r][c];
    }
    std::cout << std::endl;
  }
#endif

  LL cnt = 0;
  for (int r = 0; r < H; ++r) {
    for (int c = 0; c < W; ++c) {
      if (checked[r][c]) continue;

      LL cnt_b = 0;
      LL cnt_w = 0;
      std::queue<Point> que;
      que.push({r, c});
      checked[r][c] = true;

      while(!que.empty()) {
        Point p = que.front();
        que.pop();
#if DEBUG
        std::cout << "(" << p.r << "," << p.c << ")" << std::endl;
#endif

        if (table[p.r][p.c] == 0) ++cnt_w;
        else                      ++cnt_b;

