template <typename T1, typename T2>
void func(T1& grid, T2& s, int ni, int nj, ll& cnt_w, ll& cnt_b) {
	if (s[ni][nj] == '.') { ++cnt_w; }
	if (s[ni][nj] == '#') { ++cnt_b; }
	int H = s.size();
	int W = s[0].size();

	int dx[4] = { 0, 1, 0, -1 };
	int dy[4] = { 1, 0, -1, 0 };
	for (int i = 0; i < 4; ++i) {
		int di = ni + dy[i];
		int dj = nj + dx[i];
		if ((di < 0) || (di >= H) || (dj < 0) || (dj >= W)) {
			continue;
		}
		if (s[ni][nj] == '.') {
			if (!grid[di][dj] && (s[di][dj] == '#')) {
				grid[di][dj] = true;
				func(grid, s, di, dj, cnt_w, cnt_b);
			}
		}
		if (s[ni][nj] == '#') {
			if (!grid[di][dj] && (s[di][dj] == '.')) {
				grid[di][dj] = true;
				func(grid, s, di, dj, cnt_w, cnt_b);
			}
		}
	}
}

