bool visited[MAXH][MAXH];

ll solve(int i, int j){
    ll white = 0, black = 0;
    // bfs
    queue<tuple<int, int, bool> > Q;
    visited[i][j] = true;
    Q.push(make_tuple(i, j, true));
    // cout << i << " " << j << endl;
    while(!Q.empty()){
        auto v = Q.front();
        Q.pop();
        int ci = get<0>(v);
        int cj = get<1>(v);
        bool isblack = get<2>(v);
        if(isblack) black++;
        else white++;
        for(int k=0;k<4;k++){
            if(ci + di[k] < 0 || ci + di[k] >= h || cj + dj[k] < 0 || cj + dj[k] >= w) continue;
            if(visited[ci + di[k]][cj + dj[k]]) continue;
            if(isblack && s[ci + di[k]][cj + dj[k]] == '.'){
                visited[ci + di[k]][cj + dj[k]] = true;
                Q.push(make_tuple(ci + di[k], cj + dj[k], false));
            }else if(!isblack && s[ci + di[k]][cj + dj[k]] == '#'){
                visited[ci + di[k]][cj + dj[k]] = true;
                Q.push(make_tuple(ci + di[k], cj + dj[k], true));
            }
        }
    }
    return white * black;
}

