vector<string> s(401);
bool done[401][401];
ll h, w;
ll B, W;

int main(){

    ll ans = 0LL;
    cin >> h >> w;
    s.resize(h);
    rep(i, h) cin >> s[i];

    rep(i, h){
        rep(j, w){
            if(s[i][j] == '.' or done[i][j]) continue;
            B = W = 0;
            queue<ll> q;
            done[i][j] = true;
            q.push(i*w+j);
            while(!q.empty()){
                ll x = q.front()%w, y = q.front()/w; q.pop();
                if(s[y][x] == '#') ++B;
                else ++W;
                rep(i, 4){
                    ll xx = x+dx[i], yy = y+dy[i];
                    if(xx < 0 or w <= xx or yy < 0 or h <= yy) continue;
                    if(s[y][x] == s[yy][xx] or done[yy][xx]) continue;
                    done[yy][xx] = true;
                    q.push(yy*w+xx);
                }
            }
            ans += B*W;
        }
    }
    ppp(ans);
    return 0;
}

