void fill(vvi&f, int x, int y, int is_black, int&k, int &w)
{
	static const int vx[]={ 1, 0,-1, 0};
	static const int vy[]={ 0, 1, 0,-1};

	if(is_black) k++;
	else w++;

	f[y][x]='*';
	for(int i=0;i<4;i++)
	{
		int nx=x+vx[i];
		int ny=y+vy[i];
		if(is_black && f[ny][nx]=='.') fill(f, nx, ny, 0, k, w);
		if(!is_black && f[ny][nx]=='#') fill(f, nx, ny, 1, k, w);
	}
}


int main(void)
{
	int h, w;

	while(scanf("%d%d\n", &h, &w)==2)
	{
		vvi f(h+2);
		for(auto&mf:f) mf.assign(w+2, -1);

		for(int y=1;y<=h;y++)
		{
			char s[w+10];
			scanf("%[.#]\n", s+1);
			for(int x=1;x<=w;x++)
			{
				f[y][x]=s[x];
			}
		}

		ll ans=0;
		for(int y=1;y<=h;y++)
		{
			for(int x=1;x<=w;x++)
			{
				if(f[y][x]=='#')
				{
					int k=0, w=0;
					fill(f, x, y, 1, k, w);
					ans+=(ll)k*w;
				}
			}
		}
		printf("%lld\n", ans);
	}

	return 0;
}

