class UnionFind{
 public:
  int n;
  vector<int> parents;
  vector<int> ranks;
  vector<ll> group_pw, group_pb;

  explicit UnionFind(int n){
    this->n = n;
    parents = vector<int>(n, -1);
    for(int i = 0; i < n; i++)
    {
      parents[i] = i;
    }
    ranks = vector<int>(n, 0);
    group_pb = vector<ll>(n, 0);
    group_pw = vector<ll>(n, 0);
  }

  ///木の根を求める
  int findRoot(int target)
  { 
    if(parents[target] == target)
    {
      return target;
    }else{
      return parents[target] = findRoot(parents[target]);
    }
  }

  ///target1とtarget2の属する集合を併合
  void uniteGroup(int target1, int target2)
  { 
    int parent_target1 = findRoot(target1);
    int parent_target2 = findRoot(target2);
    if(parent_target1 == parent_target2)
    {
      ///すでに同じ集合に属している
      return;
    }
    if(ranks[parent_target1] < ranks[parent_target2])
    {
      parents[parent_target1] = parent_target2;
      group_pw[parent_target2] += group_pw[parent_target1];
      group_pb[parent_target2] += group_pb[parent_target1];
      group_pw[parent_target1] = group_pb[parent_target1] = 0;
    }else{
      group_pw[parent_target1] += group_pw[parent_target2];
      group_pb[parent_target1] += group_pb[parent_target2];
      group_pw[parent_target2] = group_pb[parent_target2] = 0;
      parents[parent_target2] = parent_target1; 
      if(ranks[parent_target1] == ranks[parent_target2]) ranks[parent_target1]++;
    }
  }

  ///target1とtarget2が同じ集合に属するか
  bool same(int target1, int target2)
  { 
    return findRoot(target1) == findRoot(target2);
  } 
 };

int main(){
  cin >> h >> w;
  vector<string> s(h);
  for(int i = 0; i < h; i++)
  {
    cin >> s[i];
  }
  //vector<vector<bool>> flag(h, vector<bool>(w, false));
  UnionFind uf(h * w);
  vector<vector<int>> index(h, vector<int>(w));
  int count = 0;
  for(int i = 0; i < h; i++)
  {
    for(int j = 0; j < w; j++)
    {
      index[i][j] = count;
      count++;
    }
  }
  ll result = 0;
  for(int i = 0; i < h; i++)
  {
    for(int j = 0; j < w; j++)
    {
      if(s[i][j] == '.')
      {
        uf.group_pw[index[i][j]] = 1;
      }else{
        uf.group_pb[index[i][j]] = 1;
      }
    }
  }
  for(int i = 0; i < h; i++)
  {
    for(int j = 0; j < w; j++)
    { 
      if(i < h - 1)
      {
        if(!uf.same(index[i][j], index[i + 1][j]) && s[i][j] != s[i + 1][j])
        {
          uf.uniteGroup(index[i][j], index[i + 1][j]);
        }
      } 
      if(j < w -1)
      {
        if(!uf.same(index[i][j], index[i][j + 1]) && s[i][j] != s[i][j + 1])
        {
          uf.uniteGroup(index[i][j], index[i][j + 1]);
        }
      }
    }
  }
  for(int i = 0; i < h * w; i++)
  {
    result += uf.group_pw[i] * uf.group_pb[i];
  }
  cout << result << endl;
}

