int H, W;
vector<string> S;
vector<vector<bool>> Used;
int writeCount;
int blackCount;

const int dx[4] = {0, 1, 0, -1};
const int dy[4] = {1, 0, -1, 0};

void checkAround(int x, int y) {
    if (Used[x][y]) {
        return;
    }
    Used[x][y] = true;

    if (S[x][y] == '.') {
        writeCount++;
    }
    if (S[x][y] == '#') {
        blackCount++;
    }

    for (int i = 0; i < 4; ++i) {
        int nx = x + dx[i];
        int ny = y + dy[i];

        if (nx < 0 || nx >= H || ny < 0 || ny >= W) {
            continue;
        }
        if (S[x][y] == S[nx][ny]) {
            continue;
        }
        checkAround(nx, ny);

    }
}

int main() {
    cin >> H >> W;

    Used.resize(H);
    for (int i = 0; i < H; ++i) {
        Used[i].resize(W);
        for (int j = 0; j < W; ++j) {
            Used[i][j] = false;
        }
    }

    for (int i = 0; i < H; ++i) {
        string S2;
        cin >> S2;
        S.push_back(S2);
    }


    int result = 0;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (Used[i][j]) {
                continue;
            }
            writeCount = 0;
            blackCount = 0;
            checkAround(i, j);
            result += writeCount * blackCount;


        }
    }
    cout << result << endl;

    return 0;
}

