int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int h, w;
    cin >> h >> w;
    vector<string> mat(h);
    for (int i = 0; i < h; ++i) {
        cin >> mat[i];
    }

    vector<vector<bool>> visited(h, vector<bool>(w, false));
    vector<int> X{-1, 1, 0, 0};
    vector<int> Y{0, 0, -1, 1};

    auto inside = [&](int x, int y) {
        return x >= 0 && x < h && y >= 0 && y < w;
    };

    auto bfs = [&](int sx, int sy) {
        vector<int> cnts(2, 0);
        queue<pair<int,int>> que;
        que.emplace(sx, sy);
        visited[sx][sy] = true;

        int clr = mat[sx][sy];

        while (!que.empty()) {
            int x = que.front().first;
            int y = que.front().second;
            cnts[clr == mat[x][y]] += 1;
            que.pop();

            for (int i = 0; i < X.size(); ++i) {
                int nx = x + X[i], ny = y + Y[i];
                if (inside(nx, ny) && !visited[nx][ny] && mat[nx][ny] != mat[x][y]) {
                    visited[nx][ny] = true;
                    que.emplace(nx, ny);
                }
            }
        }

        return cnts[0] * 1LL * cnts[1];
    };

    long long res = 0;
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            if (!visited[i][j]) {
                res += bfs(i, j);
            }
        }
    }
    cout << res << '\n';

    return 0;
}

#include <iostream>
#include <cmath>
