using namespace std;

int dx[4] ={1,0,-1,0};
int dy[4] = {0,1,0,-1};
int cntw,cntb;
int state[402][402];

int dfs(int x,int y){
  if(state[x][y]==0) {
    cntw+=1;
  }
  if(state[x][y]==1){
    cntb+=1;
  }
  int tmp=state[x][y];
  state[x][y]=-1;  
  for(int i=0;i<4;i++){
    int nx=x+dx[i], ny=y+dy[i];
    if(state[nx][ny]+tmp==1) {
      dfs(nx,ny);
    } 
  }
  return cntb*cntw;
}

int main()
{
  int H,W;
  cin>>H>>W;
  memset(state,-1,sizeof(state));

  for(int i=1;i<=H;i++){
    string s;
    cin>>s;
    for(int j=1;j<=W;j++){
      if(s[j-1]=='.'){
        state[i][j]=0;
      }else{
        state[i][j]=1;
      }
    }
  }

  int ans=0;
  for(int i=0;i<402;i++){
    for(int j=0;j<402;j++){
      cntw=0,cntb=0;
      if(state[i][j]>=0){
	ans += dfs(i,j);
      }
    }
  }
  cout<< ans <<endl;
}

