 int dj[4]={0,1,0,-1};

int main(){
	int h,w;
	int b[444][444]={},used[444][444]={};
	cin>>h>>w;
	FOR(i,0,404)FOR(j,0,404)b[i][j]=2;
	FORQ(i,1,h){
		string s;
		cin>>s;
		FOR(j,0,w){
			if(s[j]=='#')b[i][j+1]=1;
			else b[i][j+1]=0;
		}
	}
	LL ans=0;
	FORQ(i,1,h){
		FORQ(j,1,w){
			if(used[i][j])continue;
			if(b[i][j]!=1)continue;
			int cnt[2]={};
			queue<pii> q;
			q.push(MP(i,j));
			used[i][j]=1;
			cnt[1]++;
			while(q.size()){
				pii pr=q.front();
				q.pop();
				int ii=pr.ST,jj=pr.ND;
				int nc=b[ii][jj];
				FOR(d,0,4){
					int ni=ii+di[d];
					int nj=jj+dj[d];
					if(used[ni][nj])continue;
					if(b[ni][nj]!=(nc^1))continue;
					q.push(MP(ni,nj));
					used[ni][nj]=1;
					cnt[nc^1]++;
				}
			}
			ans+=1LL*cnt[0]*cnt[1];
		}
	}
	cout<<ans<<endl;
    return 0;
}

