struct UnionFind{
    vector<int> par;
    UnionFind(int N) : par(N){
        for(int i=0;i<N;i++)    par[i]=i;
    }
    int root(int x){
        if(par[x]==x)   return x;
        return par[x] = root(par[x]);
    }
    void unite(int x,int y){
        int rx = root(x);
        int ry = root(y);
        if(rx==ry)  return;
        par[rx] = ry;
    }
    bool same(int x,int y){
        int rx = root(x);
        int ry = root(y);
        return rx==ry;
    }
};

int main(){
    int h,w;
    cin >> h >> w;
    UnionFind tree(h*w);
    char s[400][401];
    for(int i=0;i<h;i++)    cin >> s[i];
    for(int y=0;y<h;y++){
        for(int x=0;x<w;x++){
            if(s[y][x]=='.'){
                if(y-1>=0&&s[y-1][x]=='#')  tree.unite(y*w+x,(y-1)*w+x);
                if(y+1<h&&s[y+1][x]=='#')   tree.unite(y*w+x,(y+1)*w+x);
                if(x-1>=0&&s[y][x-1]=='#')  tree.unite(y*w+x,y*w+x-1);
                if(x+1<w&&s[y][x+1]=='#')   tree.unite(y*w+x,y*w+x+1);
            }
            else{
                if(y-1>=0&&s[y-1][x]=='.')  tree.unite(y*w+x,(y-1)*w+x);
                if(y+1<h&&s[y+1][x]=='.')   tree.unite(y*w+x,(y+1)*w+x);
                if(x-1>=0&&s[y][x-1]=='.')  tree.unite(y*w+x,y*w+x-1);
                if(x+1<w&&s[y][x+1]=='.')   tree.unite(y*w+x,y*w+x+1);
            }
        }
    }
    map<int,int> black,white;
    for(int y=0;y<h;y++){
        for(int x=0;x<w;x++){
            if(s[y][x]=='.')    white[tree.root(y*w+x)]++;
            else    black[tree.root(y*w+x)]++;
        }
    }
    ll ans=0;
    for(auto e:white){
        ans+=e.second * black[e.first];
    }
    cout << ans << endl;
	return 0;
}

