void addbw(bw &a,bw b){
	a.b+=b.b;
	a.w+=b.w;
}
bw dfs(int x,int y,bool shouldB) {
	if(x<0 || y<0 || x>=W || y>=H) return {0,0};
	if(done[y][x]) return {0,0};
	if((shouldB==true) != (S[y][x]=='#')) return {0,0};
	done[y][x]=1;
	bw ans={0,1};
	if(shouldB) ans={1,0};
	addbw(ans,dfs(x-1,y  ,!shouldB));
	addbw(ans,dfs(x+1,y  ,!shouldB));
	addbw(ans,dfs(x  ,y-1,!shouldB));
	addbw(ans,dfs(x  ,y+1,!shouldB));
	return ans;
}

