using namespace std;
using P = pair<int, int>;
int total;
int black;
int white;
vector<vector<bool>> seen;
vector<string> g;
int H, W;
pair<int, int> nex;
void dfs(P p) {
  if(seen[p.first][p.second]) return;
  seen[p.first][p.second] = true;
  char c;
  if(g[p.first][p.second] == '.') {
    c = '#';
    white++;
  }
  else {
    c = '.';
    black++;
  }
  if(p.first != 0 && !seen[p.first-1][p.second]) {
    if(g[p.first-1][p.second] == c) dfs(make_pair(p.first-1, p.second));
    else if(nex.first == -1) nex = make_pair(p.first-1, p.second);
  }
  if(p.first != H-1 && !seen[p.first+1][p.second]) {
    if(g[p.first+1][p.second] == c) dfs(make_pair(p.first+1, p.second));
    else if(nex.first == -1) nex = make_pair(p.first+1, p.second);
  }
  if(p.second != 0 && !seen[p.first][p.second-1]) {
    if(g[p.first][p.second-1] == c) dfs(make_pair(p.first, p.second-1));
    else if(nex.first == -1) nex = make_pair(p.first, p.second-1);
  }
  if(p.second != W-1 && !seen[p.first][p.second+1]) {
    if(g[p.first][p.second+1] == c) dfs(make_pair(p.first, p.second+1));
    else if(nex.first == -1) nex = make_pair(p.first, p.second+1);
  }
}

int main() {
  int h, w;
  int ans = 0;
  cin >> h >> w;
  total = h * w;
  seen.resize(h);
  g.resize(h);
  for(int i=0;i<h;i++) seen[i].resize(w, false);
  H = h, W = w;
  for(int i=0;i<h;i++) cin >> g[i];
  nex = make_pair(0, 0);
  white = 0; black = 0;
  while(total != 0) {
    pair<int, int> start = nex;
    nex.first = -1;
    dfs(start);
    ans += black * white;
    total -= black + white;
    black = 0;
    white = 0;
  }
  cout << ans << endl;
}

