	rep(i,h) rep(j,w) {
		if(i<h-1 && B[i][j]!=B[i+1][j]) U.unite(i*w+j,(i+1)*w+j);
		if(j<w-1 && B[i][j]!=B[i][j+1]) U.unite(i*w+j,i*w+(j+1));
	}

	map<int,lint> fb,fw;
	rep(i,h) rep(j,w) {
		if(B[i][j]=='#') ++fb[U.find(i*w+j)];
		if(B[i][j]=='.') ++fw[U.find(i*w+j)];
	}

	lint ans=0;
	for(auto p:fb) ans+=fb[p.first]*fw[p.first];
	cout<<ans<<'\n';

	return 0;
}

