  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (b[i][j] == '#') {
        if (group[i][j] == 0) { // マスにグループ番号が割り振られていない場合
          int score = rec(i, j, cnt); // '#'からいける部分にグループ番号を割り当てる。
          ans += score;
          mp[cnt] = score; // グループ番号にスコアを登録する。これは、再計算を防ぐためにある
          cnt++; // グループ番号をインクリメント
        } else { // すでにグループ番号が割り振られている場合
          ans += mp[group[i][j]];
        }
      }
    }
  }

  cout << ans << endl;

  return 0;
}

