typedef long lint;
typedef pair<lint, lint> P;

lint H, W;

void step(vector<string> &S, vector<vector<bool>> &flag, lint x, lint y, P &p) {
  char current = S[x][y];
  char target = S[x][y] == '#' ? '.' : '#';
  //  cout << "x: " << x << " y: " << y << " " << current <<"\n";

  if(current == '#') {
    p.first++;
  } else {
    p.second++;
  }
  flag[x][y] = true;

  if(x+1 < H) {
    if(!flag[x+1][y] && target == S[x+1][y]) {
      step(S, flag, x+1, y, p);
    }
  }

  if(x-1 >= 0) {
    if(!flag[x-1][y] && target == S[x-1][y]) {
      step(S, flag, x-1, y, p);
    }
  }
  if(y+1 < W) {
    if(!flag[x][y+1] && target == S[x][y+1]) {
      step(S, flag, x, y+1, p);
    }
  }
  if(y-1 >= 0) {
    if(!flag[x][y-1] && target == S[x][y-1]) {
      step(S, flag, x, y-1, p);
    }
  }
}

