        P p(0,0);
      //      if(S[x][y] == '#') {
      //        p.first++;
      //      } else {
      //        p.second++;
      //      }

        step(S, flag, x, y, p);

        res += p.first*p.second;
        //        cout << "x: " << x << " y: " << y << "\n";
        //        cout << p.first << " " << p.second << "\n";
      }
    }

    PRINT(res);

    return 0;
}

