                int newx = x + dx[k];
                if (newy < 0 || h <= newy) {
                    continue;
                }
                if (newx < 0 || w <= newx) {
                    continue;
                }
                if (grid[y][x] + grid[newy][newx] == 1) {
                    graph[y * w + x][newy * w + newx] = 0;
                }
            }
        }
    }
    rep (k, h * w) {
        rep (i, h * w) {
            rep (j, h * w) {
                chmin(graph[i][j], graph[i][k] + graph[k][j]);
            }
