int H,W;
char S[400][400];
int reached[400][400];
int b[160000],w[160000];
void init(int x,int y){
    for(int i = 0;i < x;i++){
        for(int j = 0;j < y;j++){
            reached[i][j] = 0;
        }
    }
    for(int i = 0;i < x*y;i++){
        b[i] = 0;
        w[i] = 0;
    }
}
void search(int x,int y,int k){
    if(x < 0 || x >= H || y < 0 || y >= W || reached[x][y] == 1)return;

    reached[x][y] = 1;
    if(S[x][y] == '#')b[k]++;
    if(S[x][y] == '.')w[k]++;

    if(S[x][y] != S[x+1][y])search(x+1,y,k);
    if(S[x][y] != S[x-1][y])search(x-1,y,k);
    if(S[x][y] != S[x][y+1])search(x,y+1,k);
    if(S[x][y] != S[x][y-1])search(x,y-1,k);
}



int main(){
    scanf("%d%d",&H,&W);
    for(int i = 0;i < H;i++){
        for(int j = 0;j < W;j++){
            scanf("%c",&S[i][j]);
            if(S[i][j] == '\n')j = j - 1;
        }
    }


    int count = 0;
    for(int k = 0;k < H*W;k++){
        search(k/W,k%W,k);
        count += b[k]*w[k];
    }

    printf("%d\n",count);
    return 0;
}

