struct UnionFind {
  vector<int> par;

  UnionFind(int N) : par(N) { rep(i, N) par[i] = i; }

  int root(int x) { 
    if (par[x]==x) return x;
    else return par[x] = root(par[x]);
  }

  void unite(int x, int y) {
    int rx = root(x);
    int ry = root(y);
    if (rx==ry) return;
    par[rx] = ry;
  }

  bool same(int x, int y) {
    return root(x) == root(y);
  }

};

int main() {
  int H, W; cin >> H >> W;
  int m[H][W];
  rep(i, H) {
    string S; cin >> S;
    rep(j, W) m[i][j] = S[j]=='#' ? 1 : 0;
  }

  UnionFind tree(H*W);
  rep(i, H) rep(j, W) {
    if (i!=0 && m[i][j]!=m[i-1][j]) tree.unite((i-1)*W+j,i*W+j);
    if (j!=0 && m[i][j]!=m[i][j-1]) tree.unite(i*W+j-1,i*W+j);
  }

  map<int, map<int, int>> num; 
  rep(i, H) rep(j, W) { num[tree.root(i*W+j)][(i+j)%2]++; }

  ll result = 0;
  for (auto x: num) result += x.second[0]*x.second[1]; 

