using namespace std;
typedef pair<int,int> pii;

string grid[405];
int H,W;
int xi[] = {1,0};
int yi[] = {0,1};
bool visited[405][405];
long long dp[405][405];
pii solve(int x, int y){
	visited[x][y] = true;
	int d=0,h=0;
	if(grid[x][y]=='.'){
		d++;
		for(int i=0;i<2;i++){
			int nx = x+xi[i], ny = y+yi[i];
			if(nx<H and ny<W and !visited[nx][ny] and grid[nx][ny]=='#'){
				pii p = solve(nx,ny);
				d+=p.first;
				h+=p.second;
			}
		}
	}else{
		h++;
		for(int i=0;i<2;i++){
			int nx = x+xi[i], ny = y+yi[i];
			if(nx<H and ny<W and !visited[nx][ny] and grid[nx][ny]=='.'){
				pii p = solve(nx,ny);
				d+=p.first;
				h+=p.second;			
			}
		}

	}
	return pii(d,h);
}

int main(){
	long long ans=0;
	cin >> H >> W;
	for(int i=0;i<H;i++)
		cin >> grid[i];
	for(int i=0;i<H;i++){
		for(int j=0;j<W;j++){
			if(!visited[i][j]){
				pii p = solve(i,j);
				ans += (long long)p.first * p.second;
			}
		}
	}
	cout << ans;

}

