//t%2 ? # : .
pii dfs(int x, int y, int t)
{
  if(used[y][x]){
    if(t%2){
      return mp(0, 0); 
    }else{
      return mp(0, 0);
    }
  } 
//  cout << x << " , " << y << endl;

  used[y][x] = true;

  int dx[] = {-1, 1, 0, 0};
  int dy[] = {0, 0, 1, -1};

  pii ret = t%2 ? mp(1, 0) : mp(0, 1);
