    if(nx < 0 or w <= nx or ny < 0 or h <= ny) continue;
    if(s[ny][nx] == (t%2 ? '#' : '.')) continue;

    pii x = dfs(nx, ny, t+1);
    ret.first += x.first;
    ret.second += x.second;
  }

  return ret;
}

