using namespace std;

class UnionFind {
  vector<int> par;
  vector<int> sizes;
  public:
  UnionFind(int n) : par(n), sizes(n, 1) {
    for (int i = 0; i < n; i++) {
      par[i] = i;
    }
  }
  int find(int x) {
    if (x == par[x]) return x;
    return par[x] = find(par[x]);
  }
  void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (sizes[x] < sizes[y]) swap(x, y);
    par[y] = x;
    sizes[x] += sizes[y];
  }
  bool same(int x, int y) {
    return find(x) == find(y);
  }
  int size(int x) {
    return sizes[find(x)];
  }
};

void solve(long long H, long long W, vector<string> S){
  UnionFind uf(H*W);
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      if (i+1 < H && S[i][j] != S[i+1][j]) {
        uf.unite(i*W+j, (i+1)*W+j);
      }
      if (j+1 < W && S[i][j] != S[i][j+1]) {
        uf.unite(i*W+j, i*W+(j+1));
      }
    }
  }
  vector< vector<long long> > s(H*W, vector<long long>(2, 0));
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      s[uf.find(i*W+j)][S[i][j] == '.' ? 1 : 0]++;
    }
  }
  long long ret = 0;
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      ret += s[i*W+j][0] * s[i*W+j][1];
    }
  }
  std::cout << ret << std::endl;
}

int main(){
  long long H;
  long long W;
  scanf("%lld",&H);
  vector<string> S(H);
  scanf("%lld",&W);
  for(int i = 0 ; i < H ; i++){
    cin >> S[i];
  }
  solve(H, W, S);
  return 0;
}

#include <iostream>
