struct Pos{
	int x;
	int y;

	Pos(int _x, int _y): x(_x), y(_y)
	{}
};

int main(){
	int H, W;

	scanf("%d %d\n", &H, &W);

	std::vector<std::string> board(H);
	for(int i = 0; i < H; i++){
		std::cin >> board[i];
	}

	int ans = 0;

	for(int Y = 0; Y < H; Y++){
		for(int X = 0; X < W; X++){

			int n_White = 0, n_Black = 0;

			if(board[Y][X] != 'x'){

				std::vector<Pos> buf;
				buf.push_back(Pos(X, Y));

				while(buf.size() > 0){
					std::vector<Pos> new_buf;
					for(int i = 0; i < buf.size(); i++){
						int x = buf[i].x;
						int y = buf[i].y;

						char color = board[y][x];
						char target;

						if(color == '#'){
							n_Black++;
							target = '.';
						}
						if(color == '.'){
							n_White++;
							target = '#';
						}

						// 上下左右のPosが自分の色と異なっている場合、new_bufについかする
						if(y - 1 >= 0 && board[y - 1][x] == target){
							new_buf.push_back(Pos(x, y - 1));
						}
						if(x + 1 < W && board[y][x + 1] == target){
							new_buf.push_back(Pos(x + 1, y));
						}
						if(y + 1 < H && board[y + 1][x] == target){
							new_buf.push_back(Pos(x, y + 1));
						}
						if(x - 1 >= 0 && board[y][x - 1] == target){
							new_buf.push_back(Pos(x - 1, y));
						}

						board[y][x] = 'x';
					}
					buf = new_buf;
				}
			}
			ans += n_White*n_Black;
		}
	}

	std::cout << ans << std::endl;
}

