  std::ios_base::sync_with_stdio(false);
  std::cout << std::fixed << std::setprecision(15);
  ll h,w;
  cin >> h >> w;
  vector<string> S(h);
  rep(i,h) cin >> S[i];

  UnionFind tree(h*w);
  rep(y,h) rep(x,w) {
    if (S[y][x] == '#') {
      int ind = w*y + x;
      for (int i = 4; i < 8; ++i) {
        int nx = x + dx[i],  ny = y + dy[i];
        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
        if (S[ny][nx] == '#' && (S[ny][x] == '.' || S[y][nx] == '.')) {
          int ind2 = w*ny + nx;
          tree.merge(ind, ind2);
        }
      }
    }
  }

  vector<vector<int> > A(h*w);
  rep(y,h) rep(x,w) {
    if (S[y][x] == '#') {
      int ind = w*y + x;
      rep(i,4) {
        int nx = x + dx[i];
        int ny = y + dy[i];
        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
        if (S[ny][nx] == '.') {
          int ind2 = w*ny + nx;
          A[tree.root(ind)].emplace_back(ind2);
        }
      }
    }
  }
  ll ans = 0;
  rep(i,h*w) {
    if (A[i].size() == 0) continue;
    vector<bool> checked(h*w,false);
    ll cnt = 0;
    for (auto x : A[i]) {
      if (!checked[x]) {
        cnt++;
        checked[x] = true;
      }
    }
    ans += tree.size(i) * cnt;
  }
  cout << ans << endl;
  return 0;
}

