pair<int,int> mawari(vector<vector<int> >& s, int i,int j){
  pair<int,int> r(0,0);
  if(s[i][j]==0){
    r.first++;
  }else{
    r.second++;
  }
  int stmp=s[i][j];
  s[i][j]=2;

  pair<int,int> ptmp;
  if(0<i-1){
    if(stmp!=s[i-1][j] && s[i-1][j]!=2){
      ptmp=mawari(s,i-1,j);
      r.first+=ptmp.first;r.second+=ptmp.second;
    }
  }
  if(i+1<h){
    if(stmp!=s[i+1][j] && s[i+1][j]!=2){
      ptmp=mawari(s,i+1,j);
      r.first+=ptmp.first;r.second+=ptmp.second;
    }
  }
  if(0<j-1){
    if(stmp!=s[i][j-1] && s[i][j-1]!=2){
      ptmp=mawari(s,i,j-1);
      r.first+=ptmp.first;r.second+=ptmp.second;
    }
  }
  if(j+1<w){
    if(stmp!=s[i][j+1] && s[i][j+1]!=2){
      ptmp=mawari(s,i,j+1);
      r.first+=ptmp.first;r.second+=ptmp.second;
    }
  }

  return r;

}

