#define MAX_H 400
#define MAX_W 400
using namespace std;

int parent[MAX_H * MAX_W];
int depth[MAX_H * MAX_W];
long black[MAX_H * MAX_W];
long white[MAX_H * MAX_W];

void init(int h, int w) {
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            parent[w * i + j] = w * i + j;
            depth[w * i + j] = 1;
            black[w * i + j] = white[w * i + j] = 0;
        }
    }
}

int find(int p0) {
    if (parent[p0] == p0) {
        return p0;
    }
    return parent[p0] = find(parent[p0]);
}

void unite(int p0, int p1) {
    int parent0 = find(p0);
    int parent1 = find(p1);
    if (parent0 == parent1)
        return;

    if (depth[parent0] < depth[parent1]) {
        parent[parent1] = parent0;
    } else {
        parent[parent0] = parent1;
        if (depth[parent0] == depth[parent1])
            depth[parent1]++;
    }
}

int main() {
    int h, w;
    cin >> h >> w;
    string s[h];
    for (int i = 0; i < h; i++) {
        cin >> s[i];
    }

    init(h, w);

    for (int j = 1; j < w; j++) {
        if (s[0][j - 1] != s[0][j])
            unite(j, j - 1);
    }
    for (int i = 1; i < h; i++) {
        if (s[i - 1][0] != s[i][0])
            unite(w * i, w * i - w);
        for (int j = 1; j < w; j++) {
            if (s[i][j - 1] != s[i][j]) {
                unite(w * i + j, w * i + j - 1);
            }
            if (s[i - 1][j] != s[i][j]) {
                unite(w * i + j, w * i + j - w);
            }
        }
    }

    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            int pa = find(w * i + j);
            if (s[i][j] == '#')
                black[pa]++;
            else
                white[pa]++;
        }
    }

    long ans = 0;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            ans += black[w * i + j] * white[w * i + j];
        }
    }
    cout << ans << endl;
    return 0;
}

