struct UnionFind {
    vector<int> par;
    UnionFind(int n) : par(n, -1) {};
    int root(int v) {
        if (par[v] < 0) return v;
        return par[v] = root(par[v]);
    }
    int size(int v) {
        return -par[root(v)];
    }
    bool unionSet(int a, int b) {
        a = root(a);
        b = root(b);
        if (a == b) return false;
        if (size(a) > size(b)) swap(a, b);
        par[b] += par[a];
        par[a] = b;
        return true;
    }
    bool isSame(int a, int b) {
        return root(a) == root(b);
    }
};


void solve() {
    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    for (int i = 0; i < H; i++) {
        cin >> S[i];
    }
    int dx[] = {0, -1, 0, 1};
    int dy[] = {-1, 0, 1, 0};

    auto get = [&](int i, int j) {
        return W * i + j;
    };

    UnionFind uf(H * W);
    for(int i = 0; i < H; i++) {
        for(int j = 0; j < W; j++) {
            for(int k = 0; k < 4; k++) {
                int tx = j + dx[k];
                int ty = i + dy[k];
                if (tx < 0 || tx >= W || ty < 0 || ty >= H) continue;

                assert(get(ty, tx) < H * W);
                if (S[i][j] != S[ty][tx]) {
                    uf.unionSet(get(i, j), get(ty, tx));
                }
            }
        }
    }

    map<int, ll> black;
    map<int, ll> white;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (S[i][j] == '.') white[uf.root(get(i, j))]++;
            else black[uf.root(get(i, j))]++;
        }
    }

    ll ans = 0;
    for(auto e : white) {
        ans += e.second * black[e.first] / 2;
    }
    for(auto e : black) {
        ans += e.second * white[e.first] / 2;
    }
    cout << ans << endl;

}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout.setf(ios::fixed);
    cout.precision(16);
    solve();
    return 0;
}

