namespace lib
{
	template<class T>using pair = std::pair<T, T>;
	template<class T>constexpr T pow(T base, std::uint64_t p)
	{
		T ret = T(1);
		for (std::uint64_t i = 0; i <= 63; ++i)
		{
			if (((1ull << i) & p) != 0)
			{
				ret *= base;
			}
			base *= base;
		}
		return ret;
	}
	template<class T>using p_queue = std::priority_queue<T, std::vector<T>, std::greater<>>;

	struct union_find
	{
		std::vector<int> upper;
		union_find(std::size_t size):upper(size, -1) {}

		int group(int index)
		{
			if (upper[index] == -1)
			{
				return index;
			}
			else
			{
				return upper[index] = group(upper[index]);
			}
		}

		bool merge(int x, int y)
		{
			auto gx = group(x);
			auto gy = group(y);
			if (gx != gy)
			{
				upper[gx] = gy;
				return true;
			}
			return false;
		}

		auto get()
		{
			std::map<int, std::set<int>> ret;
			for (int i = 0; i < upper.size(); ++i)
			{
				ret[group(i)].emplace(i);
			}
			return ret;
		}

		auto tops()
		{
			std::set<int> ret;
			for (int i = 0; i < upper.size(); ++i)
			{
				ret.emplace(group(i));
			}
			return ret;
		}

		bool is_same_group(int x, int y)
		{
			return group(x) == group(y);
		}
	};
}

namespace out
{
	namespace detail
	{
		template<class>struct void_out
		{
			typedef void type;
		};
		template<class T>auto write(std::ostream& ost, T const& val)
			->typename void_out<decltype(ost << val)>::type
		{
			ost << val;
		}
		template<class T, class... Ts>void write(std::ostream& ost, T const& val, Ts const&... nexts)
		{
			write(ost, val);
			ost << " ";
			write(ost, nexts...);
		}
	}
	void write_line()
	{
		std::cout << std::endl;
	}
	template<class...Ts>void write_line(Ts const&... args)
	{
		detail::write(std::cout, args...);
		write_line();
	}
	template<class Range>void write_range(Range const& rng)
	{
		for (auto const& v : rng)
		{
			write_line(v);
		}
	}
}

namespace adaptor = boost::adaptors;



void Main()
{
	int H, W;
	std::cin >> H >> W;
	boost::multi_array<bool, 2> field(boost::extents[H][W]);
	boost::multi_array<bool, 2> flag(boost::extents[H][W]);
	boost::multi_array<int, 2> counts(boost::extents[H][W]);
	std::map<int, int> group;
	lib::union_find uf(H*W);
	for (int i : boost::irange(0, H))
	{
		std::string str;
		std::cin >> str;
		for (int j : boost::irange(0, W))
		{
			if (str[j] == '#')
			{
				field[i][j] = true;
			}
		}
	}
	struct type
	{
		int fi, fj;
		int i, j;
		bool f;
	};
	std::stack<type> stack;
	for (int i : boost::irange(0, H))
	{
		for (int j : boost::irange(0, W))
		{
			stack.emplace(type{ i,j,i,j,field[i][j] });
		}
	}
	while (stack.size())
	{
		auto f = stack.top();
		stack.pop();
		if (f.i < 0 || f.i >= H || f.j < 0 || f.j >= W)
		{
			continue;
		}
		if (field[f.i][f.j] != f.f)
		{
			continue;
		}
		if (flag[f.i][f.j])
		{
			continue;
		}
		flag[f.i][f.j] = true;
		uf.merge(f.i*W + f.j, f.fi*W + f.fj);
		stack.emplace(type{ f.fi,f.fj,f.i + 1,f.j,!f.f });
		stack.emplace(type{ f.fi,f.fj,f.i - 1,f.j,!f.f });
		stack.emplace(type{ f.fi,f.fj,f.i,f.j + 1,!f.f });
		stack.emplace(type{ f.fi,f.fj,f.i,f.j - 1,!f.f });
	}
	for (int i : boost::irange(0, H))
	{
		for (int j : boost::irange(0, W))
		{
			if (!field[i][j])
			{
				++group[uf.group(i*W + j)];
			}
		}
	}
	auto set = uf.get();
	int c = 0;
	for (auto const& p : set)
	{
		c += group[p.first] * (p.second.size() - group[p.first]);
	}
	out::write_line(c);
}

int main()
{
	std::cin.tie(nullptr);
	std::cin.sync_with_stdio(false);
	std::cout << std::fixed << std::setprecision(15);
	Main();
}

