long paint(char* field, int x, int y)
{
  int stack[160000];
  long odd = 0;
  long even = 0;
  int p = y * 402 + x;
  if((x + y) % 2)
  {
    odd = 1;
  }
  else
  {
    even = 1;
  }
  int color = field[p];
  int stn = 1;
  stack[0] = p;
  field[p] = 0;
  while(stn)
  {
    stn--;
    int pos = stack[stn];
    int way[4] = {-402, -1, 1, 402};
    int w;
    for(w = 0 ; w < 4 ; w++)
    {
    	int newpos = pos + way[w];
	    if(field[newpos] == color)
	    {
	      field[newpos] = 0;
	      if((newpos / 402 + newpos % 402) % 2)
	      {
	        odd++;
	      }
	      else
	      {
	        even++;
	      }
	      stack[stn] = newpos;
	      stn++;
	    }
    }
  }
  return odd * even;
}

int main()
{
  char field[402][402];
  int h, w;
  int x, y;
  scanf("%d%d", &h, &w);
  memset(field, 0, 402*402);
  for(y = 1 ; y <= h ; y++)
  {
    scanf("%s", field[y]+1);
    for(x = 1 ; x <= w ; x++)
    {
      if((x + y) % 2 == 0)
      {
        field[y][x] = field[y][x] ^ ('#' ^ '.');
      }
    }
  }
  long sum = 0;
  for(y = 1 ; y <= h ; y++)
  {
    for(x = 1 ; x <= w ; x++)
    {
    	if(field[y][x])
    	{
    		sum += paint((char*)field, x, y);
    	}
    }
  }
  printf("%ld\n", sum);
  return 0;
}

