void dfs(int i, int j, int n) {
    if (n != 0) {
        if (n % 2 && field[i][j] == '#') {
            return;
        } else if (n % 2 == 0 && field[i][j] == '.') {
            return;
        } else if (visited[i][j]) {
            return;
        }
    }

    ++n;
    visited[i][j] = true;

    if (n % 2) {
        rep(k, 4) {
            if (0 <= i + dx[k] && i + dx[k] <= h - 1 && 0 <= j + dy[k] && j + dy[k] <= w - 1 && field[i + dx[k]][j + dy[k]] == '.' && visited[i + dx[k]][j + dy[k]] == false) {
                ++cnt;
                dfs(i + dx[k], j + dy[k], n);
            }
        }
    } else {
        rep(k, 4) {
            if (0 <= i + dx[k] && i + dx[k] <= h - 1 && 0 <= j + dy[k] && j + dy[k] <= w - 1 && field[i + dx[k]][j + dy[k]] == '#' && visited[i + dx[k]][j + dy[k]] == false) {
                dfs(i + dx[k], j + dy[k], n);
            }
        }
    }
    return;
}

