int black = 0, white = 0;

void dfs(int i, int j){

    if(visited[i][j]) return;


    if(masu[i][j] == '#') black++;
    if(masu[i][j] == '.') white++;

    visited[i][j] = true;

    REP(k,4){
        if(i+dx[k]<0 || i+dx[k]>=H || j+dy[k]<0 || j+dy[k]>=W) continue;
