            visited[i][j] = false;
        }
    }
    ll ans = 0LL;

    REP(i,H){
        REP(j,W){

            if(visited[i][j]) continue;
            black = 0; white = 0;
            dfs(i, j);
            ans+=black*white;
        }
    }

    cout << ans << endl;

