                    g[num(i, j)].push_back(num(i + e.first, j + e.second));
                }   
            }   
        }   
    }   
    int ans = 0;
    int ptr = 0;
    for (int i = 0; i < n * m; ++i) {
        if (!used[i]) {
            dfs(i, ptr, 0);
            ans += cnt[ptr][0] * cnt[ptr][1];
            ++ptr;
        }
    }
    cout << ans << '\n';
    #ifdef HOME
        cerr << "TIME : " << (double)clock()/CLOCKS_PER_SEC<<'\n';
