const int N = 401;
int used[N][N];
vs maps;
int n, m;


pii steps[4] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};


bool may(int i, int j)
{
    return i >= 0 && i < n && j >= 0 && j < m && !used[i][j];
}


pii dfs(int i, int j)
{
    pii cur = {0, 0};
    used[i][j] = 1;

    if (maps[i][j] == '#')
        cur.first++;
    else
        cur.second++;

    for (auto p : steps)
    {
        if (may(i + p.first, j + p.second) && maps[i][j] != maps[i + p.first][j + p.second])
        {
            pii ncur = dfs(i + p.first, j + p.second);
            cur.first += ncur.first;
            cur.second += ncur.second;
        }
    }

    return cur;
}


void smain() {
    cin >> n >> m;
    maps.resize(n);

    for (int i = 0; i < n; ++i)
        cin >> maps[i];

    int ans = 0;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            if (!used[i][j] && maps[i][j] == '#')
            {
                pii p = dfs(i, j);
                ans += p.first * p.second;
            }

    cout << ans << '\n';
}

