/* function */
int bfs(int sx, int sy) {
    visited[sx][sy] = 1;
    queue<pii> q;
    q.push(pii(sx, sy));
    vector<int> cnt(2);
    while (!q.empty()) {
        pii p = q.front(); q.pop();
        int x = p.first, y = p.second;
        cnt[m[x][y]]++;
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx < 0 || H <= nx || ny < 0 || W <= ny) continue;
            if (!visited[nx][ny] && m[x][y] != m[nx][ny]) {
                visited[nx][ny] = 1;
                q.push(pii(nx, ny));
            }
        }
    }
    return cnt[0] * cnt[1];
}
