void init(int n){
    for(int i=0;i<n;i++){
        par[i]=i;
        r[i]=0;
    }
}//全部バラバラの状態

int find(int x){
    if(par[x]==x){
        return x;
    }else{
        return par[x]=find(par[x]);
    }
}//一番上の付け根を求める

void unite(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y) return;

    if(r[x]<r[y]){
        par[x]=y;
    }else{
        par[y]=x;
        if(r[x]==r[y]) r[x]++;
    }
}//xとyのグループを付け根でくっつける

bool same(int x,int y){
    return find(x)==find(y);
}//同じグループにいるかどうか

