vector<vector<char>> grid;

struct UnionFind
{
	// par[i]：データiが属する木の親の番号。i == par[i]のとき、データiは木の根ノードである
	vector<LL> par;
	// sizes[i]：根ノードiの木に含まれるデータの数。iが根ノードでない場合は無意味な値となる
	vector<LL> sizes;

	UnionFind(LL n) : par(n), sizes(n, 1) {
		// 最初は全てのデータiがグループiに存在するものとして初期化
		for(LL i = 0;i < n;i++) par[i] = i;
	}

	// データxが属する木の根を得る
	LL find(LL x) {
		if (x == par[x]) return x;
		return par[x] = find(par[x]);  // 根を張り替えながら再帰的に根ノードを探す
	}

	// 2つのデータx, yが属する木をマージする
	void unite(LL x, LL y) {
		// データの根ノードを得る
		x = find(x);
		y = find(y);

		// 既に同じ木に属しているならマージしない
		if (x == y) return;

		// xの木がyの木より大きくなるようにする
		if (sizes[x] < sizes[y]) swap(x, y);

		// xがyの親になるように連結する
		par[y] = x;
		sizes[x] += sizes[y];
		// sizes[y] = 0;  // sizes[y]は無意味な値となるので0を入れておいてもよい
	}

	// 2つのデータx, yが属する木が同じならtrueを返す
	bool same(LL x, LL y) {
		return find(x) == find(y);
	}

	// データxが含まれる木の大きさを返す
	LL size(LL x) {
		return sizes[find(x)];
	}
};

int main(int argc, char const* argv[])
{
	LL h,w;
	cin >> h >> w;
	grid = vector<vector<char>>(h,vector<char>(w));
	for (LL i = 0; i < h; i++) {
		for (LL j = 0; j < w; j++) {
			cin >> grid[i][j];
		}
	}
	LL ans = 0;
	UnionFind uf(h*w);
	for (LL i = 0; i < h; i++) {
		for (LL j = 0; j < w; j++) {
			if (j != w-1) {
				if (grid[i][j] != grid[i][j+1]) {
					uf.unite(i*w+j,i*w+j+1);
				}
			}
			if (i != h-1) {
				if (grid[i][j] != grid[i+1][j]) {
					uf.unite(i*w+j,(i+1)*w+j);
				}
			}
		}
	}
	map<LL,LL> num_b;
	for (LL i = 0; i < h; i++) {
		for (LL j = 0; j < w; j++) {
			if (grid[i][j] == '#') {
				num_b[uf.find(i*w+j)]++;
			}
		}
	}
	for (auto&& var : num_b) {
		ans += var.second * (uf.size(var.first) - var.second);
	}
	cout << ans << endl;
	return 0;
}

