			if (x == '#') {
				grid.at(i).at(j) = 1;
				black.push_back({ i,j });
			}
			else grid.at(i).at(j) = 0;
		}
	}
	vector<vector<int>>ed(h + 2, vector<int>(w + 2, 0));
	for (int i = 1; i < h + 1; i++) {
		for (int j = 1; j < w + 1; j++)ed.at(i).at(j) = -1;
	}
	ll ans = 0;
	for (auto bl : black) {
		vector<vector<int>>edc = ed;
		queue<pair<int, int>>qed;
		qed.push({ bl.at(0), bl.at(1) });
		while (qed.size() > 0) {
			int x = qed.front().first;
			int y = qed.front().second;
			if (edc.at(x).at(y) == -1) {
				edc.at(x).at(y) = 1;
				if (edc.at(x - 1).at(y) == -1&&grid.at(x-1).at(y)!=grid.at(x).at(y))qed.push({ x - 1,y });
				if (edc.at(x + 1).at(y) == -1 && grid.at(x + 1).at(y) != grid.at(x).at(y))qed.push({ x + 1,y });
				if (edc.at(x ).at(y - 1) == -1 && grid.at(x).at(y - 1) != grid.at(x).at(y))qed.push({ x ,y - 1 });
				if (edc.at(x ).at(y + 1) == -1 && grid.at(x).at(y + 1) != grid.at(x).at(y))qed.push({ x ,y + 1 });
				if (grid.at(x).at(y) == 0)ans++;
			}
			qed.pop();
		}
	}
	cout << ans << endl;
}

