pair<int,int> bfs(int sx,int sy){
	int black=0,white=0;
	queue<pair<int,int> >q;
	q.push({sx,sy});
	vis[sx][sy]=1;
	while(!q.empty()){
		pair<int,int>f=q.front();q.pop();
		int x=f.first;
		int y=f.second;
		int p=g[x][y];
		if(p==0)black++;
		else white++;
		for(int i=0;i<4;i++){
			int xx=x+dx[i],yy=y+dy[i];
			if(xx>=0 and xx<h and yy>=0 and yy<w){
				int pp=g[xx][yy];
				if(1-pp==p and !vis[xx][yy]){
					vis[xx][yy]=1;
					q.push({xx,yy});
				}
			}
		}
	}
	return make_pair(black,white);
}

