    }
    UnionFind tree(hw);
    rep(i,hw){
      int h=i/W;
      int w=i%W;
      if((h+w)%2==0){
        if((i-W)>=0 && c[i]!=c[i-W])if(!tree.same(i,i-W))tree.unite(i,i-W);
        if((i+W)<=(hw-1) && c[i]!=c[i+W])if(!tree.same(i,i+W))tree.unite(i,i+W);
        if((w-1)>=0 && (i-1)>=0 && c[i]!=c[i-1])if(!tree.same(i,i-1))tree.unite(i,i-1);
        if((w+1)<W && (i+1)<hw && c[i]!=c[i+1])if(!tree.same(i,i+1))tree.unite(i,i+1);
      }
    }
    int sum=0;
    while(!ve.empty()){
        int a=ve.back();
        int e=1,o=0;
        ve.pop_back();
        for(auto x:ve){
            if(tree.same(a,x)){
                if(((x/W-a/W)%2+(x%W-a%W)%2)%2==0)e++;
                else o++;
                auto itr=find(all(ve),x);
                ve.erase(itr);
            }
        }
        sum+=e*o;
    }
    cout << sum;
}

