                if (i + 1 < n && !arr[i + 1][j])                     adj[v].pb(value[i + 1][j]) , adj[value[i + 1][j]].pb(v);
                if (j - 1 >= 0 && !arr[i][j - 1])                    adj[v].pb(value[i][j - 1]) , adj[value[i][j - 1]].pb(v);
                if (j + 1 < m && !arr[i][j + 1])                     adj[v].pb(value[i][j + 1]) , adj[value[i][j + 1]].pb(v);
            }
        }
    }
    ll ans = 0;
    for (int i = 0; i < n * m; i++) {
        if (!vis[i]) {
            w = 0;
            b = 0;
            dfs(i);
            ans += (b * w);
        }
    }
    cout << ans << endl;

    return 0;
}

