class unionfind{ // 0-indexed
public:
	vector<int> parent;
	vector<int> size;
	int num_of_disjointsets;
	unionfind(int n){
		parent.resize(n, -1);
		size.resize(n, 1);
		num_of_disjointsets = n;
	}

	int find(int x){
		if(parent[x] == -1) return x;
		return parent[x] = find(parent[x]);
	}

	int unite(int x, int y){
		x = find(x);
		y = find(y);
		if(x == y) return -1;
		if(size[x] < size[y]){
			parent[x] = y;
			size[y] += size[x];
			size[x] = 0;
			--num_of_disjointsets;
			return y;
		}else{
			parent[y] = x;
			size[x] += size[y];
			size[y] = 0;
			return x;
			--num_of_disjointsets;
		}
	}

	bool united(int x, int y){
		return find(x) == find(y);
	}
};

