  }
  ll count_black[groups], count_white[groups];
  fill(all(count_black, groups), 0);
  fill(all(count_white, groups), 0);
  rep(i, H) rep(j, W) {
    if (s[i][j] == BLACK)
      ++count_black[group[i][j]-1];
    else
      ++count_white[group[i][j]-1];
  }
  ll ans = 0;
  rep(i, groups)
    ans += count_black[i] * count_white[i];
  out(ans);

  return 0;
}

