int n,m;
int rnk[N*N],par[N*N];
vector<pair<int,int>> edge;

void addEdge(int a,int b)
{
    edge.push_back({a,b});
}

int root(int u)
{
    while(u != par[u])
    {
        par[u] = par[par[u]];
        u = par[u];
    }
    return u;
}
void merge(int r1,int r2)
{
    if(rnk[r1] < rnk[r2])
        swap(r1,r2);
    par[r2] = r1;
    if(rnk[r2] == rnk[r1])
        rnk[r1]++;
}
int32_t main()
{
    IOS;

    cin >> n >> m;
    vector<string> v(n);
    for(int i = 0;i < n;i++)
    {
        cin >> v[i];
    }

    for(int i = 0;i < n;i++)
    {
        for(int j = 0;j < m;j++)
        {
            if(i+1 < n and v[i+1][j] != v[i][j])
                addEdge((i)*m+j,((i+1)*m)+j);
            if(j+1 < m and v[i][j+1]!=v[i][j])
                addEdge((i)*m+j,(i)*m + j+1);
            rnk[(i)*m+j] = 1;
            par[(i)*m + j] = (i)*m+j;
        }
    }
    for(auto it : edge)
    {
        int a = it.first;
        int b = it.second;
        int r1 = root(a);
        int r2 = root(b);
        if(r1!=r2)
        {
            merge(r1,r2);
        }
    }
    int black[n*m];
    int white[n*m];
    memset(black,0,sizeof(black));
    memset(white,0,sizeof(white));
    for(int i = 0;i < n;i++)
    {
        for(int j = 0;j < m;j++)
        {
           // cerr << i << " " << j << " " << root((i)*m+j) <<endl;
            if(v[i][j] == '#')
                black[root((i)*m+j)]++;
            else
                white[root((i)*m+j)]++;

        }
    }
    int ans = 0;
    for(int i = 0;i < n;i++)
    {
        for(int j = 0;j < m;j++)
        {
            ans += black[(i)*m+j]*white[(i)*m+j];
        }
    }
    cout << ans;
    return 0;
}

