  vector<string> G(h);
  UnionFind tree(h*w);
  rep(i,h)cin >> G[i];
  auto P = [](int i,int j){
    return(i*w+j);
  };
  rep(i,h){
    rep(j,w){
      //cout<<P(i,j)<<endl;
      if(i+1<h)if(G[i+1][j] != G[i][j]) tree.unite(P(i,j),P(i+1,j),G[i+1][j]);
      if(i-1>=0)if(G[i-1][j] != G[i][j]) tree.unite(P(i,j),P(i-1,j),G[i-1][j]);
      if(j-1>=0)if(G[i][j-1] != G[i][j]) tree.unite(P(i,j),P(i,j+-1),G[i][j-1]);
      if(j+1<w)if(G[i][j+1] != G[i][j]) tree.unite(P(i,j),P(i,j+1),G[i][j+1]);
    }
  }
  ll ans = 0;
  rep(i,h*w){
    if(tree.data[i]<0){
      ans -= (tree.data[i]+tree.color[i])*tree.color[i];
    }
  }
