int solve() {
  long long ans = 0;
  for(int i = 0; i < h; ++i)
    for(int j = 0; j < w; ++j)
      if(s[i][j] == '#' && !memo[i][j]) {
        int b = 1, wh = 0;
        queue<pair<int, int>> qu;
        qu.push(make_pair(i, j));
        memo[i][j] = 1;
        while(qu.size() > 0) {
          pair<int, int> now = qu.front();
          qu.pop();
          for(int k = 0; k < 4; ++k) {
            int nextx = now.fi + d[k],
                nexty = now.se + d[1 ^ k];
            if(nextx < 0 || nextx >= h || nexty < 0 ||
               nexty >= w)
              continue;
            if(!memo[nextx][nexty] &&
               s[now.fi][now.se] != s[nextx][nexty]) {
              if(s[nextx][nexty] == '#')
                ++b;
              else
                ++wh;
              memo[nextx][nexty] = 1;
              qu.push(make_pair(nextx, nexty));
            }
          }
        }
        ans += b * wh;
      }
  return ans;
}

