// https://qiita.com/ofutonfuton/items/c17dfd33fc542c222396
using ll = long long;

struct UnionFind {
    vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2

    UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
        for(int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) { // xとyの木を併合
        int rx = root(x); //xの根をrx
        int ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};


int main() {
	int H, W;
	cin >> H >> W;



	int w[H + 2][W + 2];

	ll count_dot[H * W];
	ll count_wall[H * W];

	for (int i = 0; i < H + 2; i++) {
		for (int j = 0; j < W + 2; j++) {
			 w[i][j] = -1;
		}
	}

	for (int i = 0; i < H * W; i++) {
		count_dot[i] = 0;
		count_wall[i] = 0;
	}



	for (int i = 0; i < H; i++) {
		string s;
		cin >> s;
		for (int j = 0; j < W; j++) {
			if (s.at(j) == '.') {
				w[i + 1][j + 1] = 0;
			} else {
				w[i + 1][j + 1] = 1;
			}
		}
	}

	UnionFind uf(H * W);

	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			int x[] = {-1, 0, 1, 0};
			int y[] = {0,  1 , 0, -1};
			for (int k = 0; k < 4; k++) {
				int cur_x = j + 1;
				int cur_y = i + 1;
				int next_x  = cur_x + x[k];
				int next_y  = cur_y + y[k];
				int cur = w[cur_y][cur_x];
				int next = w[next_y][next_x];
 				if (next == -1) {
 					continue;
 				}
 				if (cur == next) {
 					continue;
 				}
 				uf.unite((next_y - 1) * W + next_x - 1, (cur_y - 1) * W + (cur_x - 1));
			}
		}
	}


	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			int r = uf.root(i * W + j);
			if (w[i + 1][j + 1] == 0) {
				count_dot[r] ++;				
			} else {
				count_wall[r] ++;				
			}
		}
	}

	ll result = 0;


	for (int i = 0; i < H * W; i++) {
		result += count_dot[i] * count_wall[i];
	}
	cout << result << endl;


	return 0;
}

