class Graph{
public:
    vector<vector<char>> grid;
    vector<pair<int,int>> dx;
    deque<pair<int,int>> deq;
    vector<vector<bool>> check;
    ll ans;
    int H, W;

    Graph(int h, int w) :
    grid(h+2, vector<char>(w+2, '#')),
    ans(0), H(h), W(w),
    check(h+2, vector<bool>(w+2, false)){
        dx = {{-1,0}, {0,-1}, {1,0}, {0,1}};
    }

    void creset(){
        REP(i, H+2){
            REP(j, W+2){
                check[i][j] = false;
            }
        }
    }
    bool out(int x, int y){
        if(x < 0 || x > H+1 || y < 0 || y > W+1){
            return true;
        }
        return false;
    }

    void dfs(int x, int y){
        if(out(x, y)){
            return;
        }
        if(check[x][y]){
            return;
        }
        check[x][y] = true;
        if(grid[x][y] == '#'){
            return;
        }
        ans++;
        for(auto i : dx){
            int x2 = x + i.first, y2 = y + i.second;
            if(out(x2, y2)){
                continue;
            }
            if(!check[x2][y2] && grid[x2][y2] == '#'){
                for(auto j : dx){
                    dfs(x2 + j.first, y2 + j.second);
                }
            }
        }
    }

    void solve(){
        for(int i=1; i<=H; i++){
            for(int j=1; j<=W; j++){
                if(grid[i][j] == '.'){
                    continue;
                }
                creset();
                check[i][j] = true;
                for(auto k : dx){
                    dfs(i + k.first, j + k.second);
                }
            }
        }
        cout << ans << endl;
    }
};


