class UnionFind {
  private:
    vector<int> parent;
    vector<int> height;
    vector<int> m_size;

  public:
    UnionFind(int size_) : parent(size_), height(size_, 0), m_size(size_, 1) {
        for(int i = 0; i < size_; ++i)
            parent[i] = i;
    }
    void init(int size_) {
        parent.resize(size_);
        height.resize(size_, 0);
        m_size.resize(size_, 0);
        for(int i = 0; i < size_; ++i)
            parent[i] = i;
    }
    int find(int x) {
        if(parent[x] == x)
            return x;
        return parent[x] = find(parent[x]);
    }
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if(x == y)
            return;
        int t = size(x) + size(y);
        m_size[x] = m_size[y] = t;
        if(height[x] < height[y])
            parent[x] = y;
        else
            parent[y] = x;
        if(height[x] == height[y])
            ++height[x];
    }
    bool same(int x, int y) { return find(x) == find(y); }
    int size(int x) {
        if(parent[x] == x)
            return m_size[x];
        return size(parent[x] = find(parent[x]));
    }
};

int main() {
    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    REP(i, H) { cin >> S[i]; }
    UnionFind tree(H * W);
    //白黒の順番の連結成分を探す
    REP(i.H) {
        REP(j, W - 1) {
            if(S[i][j] != S[i][j + 1]) {
                tree.unite(W * i + j, W * i + j + 1);
            }
        }
    }
    REP(j.W) {
        REP(i, H - 1) {
            if(S[i][j] != S[i + 1][j]) {
                tree.unite(W * i + j, W * (i + 1) + j);
            }
        }
    }
    set<int> p;
    REP(i, H) {
        REP(j, W) { p.insert(tree.find(i * W + j)) }
    }
    ll ans = 0;
    for(auto now : p) {
        int hoge = tree.size(now);
        if(hoge % 2 == 0) {
            ans += hoge * hoge / 4;
        } else {
            ans += (hoge + 1) * (hoge - 1) / 4;
        }
    }
    cout << ans << endl;
    return 0;
}

