void dfs(int x,int y,bool flag,vector<vector<bool> >& used1){
  if(used1[x][y]) return ;
  //cout<<' '<<cnt<<' '<<x<<' '<<y<<endl;
  used1[x][y]=true;
  if(flag) used[x][y]=true;
  g[cnt].push_back(P(x,y));
