int dy[] = {0, 1, 0, -1};
int dx[] = {1, 0, -1, 0};

const static int MAX_N = 160001;

llong c1[MAX_N], c2[MAX_N];
int par[MAX_N], rank_t[MAX_N];

void init(int n) {
    for (int i = 0; i <= n; ++i) {
        par[i] = i;
        rank_t[i] = 0;
    }
}

int root(int x) {
    return par[x] == x ? x : par[x] = root(par[x]);
}

bool same(int x, int y) {
    return root(x) == root(y);
}

void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return;

    if (rank_t[x] < rank_t[y]) {
        par[x] = y;
    } else {
        par[y] = x;
        if (rank_t[x] == rank_t[y]) rank_t[x]++;
    }
}

