int bfs(int y,int x){
    int bl=0,wh=0;
    queue<P> q;
    q.push({y,x});
    visit[y][x]=1;
    int dy[4]={1,0,-1,0};
    int dx[4]={0,1,0,-1};
    while(!q.empty()){
        P d=q.front(); q.pop();
