		cin >> s[i];
	for (i = 0; i < h; i++) {
		for (j = 0; j < w; j++) {
			if (c[i][j] == 0) {
				count1 = 0;
				count2 = 0;
				dfs(i, j);
				ans += count1 * count2;
			}
		}
	}
	cout << ans << endl;
}

