            p now;
            now.x = i; now.y = j;
            if(f[i][j] == '#') black.push_back(now);
        }
    }
    int ans = 0;
    for(auto s : black){
        bool visited[h+2][w+2];
        for(int i = 1; i <= h; i++){
            for(int j = 1; j <= w; j++){
                visited[i][j] = false;
            }
        }

        queue<p> Q;
        Q.push(s);
        while(!Q.empty()){
            p now = Q.front();
            Q.pop(); visited[now.x][now.y] = true;
            char next;
            if(f[now.x][now.y] == '#') next = '.';
            else {next = '#'; ans++;}
            int nowx = now.x, nowy = now.y;
            p n;
            if(f[now.x+1][now.y] == next && !visited[now.x+1][now.y]){n.x= nowx+1; n.y=nowy; visited[n.x][n.y] = true; Q.push(n);}
            if(f[now.x][now.y-1] == next && !visited[now.x][now.y-1]){n.x= nowx; n.y=nowy-1; visited[n.x][n.y] = true; Q.push(n);}
            if(f[now.x-1][now.y] == next && !visited[now.x-1][now.y]){n.x= nowx-1; n.y=nowy; visited[n.x][n.y] = true; Q.push(n);}
