struct UnionFind{
  vector<int> par;

  UnionFind(int n) : par(n,-1) { }

  int root(int x){
    if(par[x] < 0) return x;
    return par[x] = root(par[x]);
  }

  bool merge(int x,int y){
    x = root(x);
    y = root(y);
    if(x == y) return false;
    if(par[x] > par[y]) swap(x,y);
    par[x] += par[y];
    par[y] = x;
    return true;
  }
};

