int dfs(const vector<string> &S, int H, int W, int i, int j, vector<vector<bool>> &visited)
{
	if (visited[i][j]) {
		return 0;
	}
	visited[i][j] = true;
	int ans = 0;

	if (S[i][j] == '.') {
		++ans;
	}

	for (int k = 0; k < 4; ++k) {
		int y = i + dy[k];
		int x = j + dx[k];
		if (y < 0 || H <= y || x < 0 || W <= x) {
			continue;
		}
		if ((S[i][j] == '#' && S[y][x] == '.') || (S[i][j] == '.' && S[y][x] == '#')) {
			ans += dfs(S, H, W, y, x, visited);
		}
	}
	return ans;
}

