// Union-Find
struct UnionFind {
    vector<int> par;
    vector<int> black;
    vector<int> white;

    //最初は全てが根であるとして初期化
    UnionFind(int N) : par(N), black(N, 0), white(N,0){
        for(int i = 0; i < N; i++) par[i] = i;
    }

    // データxが属する木の根を再帰で得る
    int root(int x){
        if (par[x] == x) return x;
        par[x] = root(par[x]); // 親を根にする付け替えによって次回以降の参照を高速化
        return par[x];
    }

    // xとyの木を併合
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        par[ry] = rx;
        white[rx] += white[ry];
        black[rx] += black[ry];
    }
};

int main() {
    int H, W;
    cin >> H >> W;
    vector<string>S(H);
    for (int i = 0; i < H; ++i) {
      cin >> S[i];
    }
    UnionFind tree(H*W);
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            int k = W * i + j;
            if(S[i][j] == '#') {
                tree.black[k]++;
            } else{
                tree.white[k]++;
            }
        }
    }
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            int k = W * i + j;
            if(i != H-1 && S[i][j] != S[i+1][j]){
                tree.unite(k, k+W);
            }
            if(j != W-1 && S[i][j] != S[i][j+1]){
                tree.unite(k, k+1);
            }
        }
    }

    ll ans = 0;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            int k = W * i + j;
            if(tree.par[k] == k){
                ans += tree.black[k] * tree.white[k];
            }
        }
    }
    cout << ans;
    return 0;
}

