void dfs(int x, int y, bool flag) {
    if (x < 0 || h <= x || y < 0 || w <= y) return;
    if (reached[x][y]) return;
    reached[x][y] = true;
    if (flag) {
        if (maze[x][y] == '.') ans++;
        else return;
    } else {
        if (maze[x][y] == '.') return;
    }
    if (maze[x][y] == '#') flag = true;
    if (maze[x][y] == '.') flag = false;
    dfs(x + 1, y, flag);
    if (maze[x][y] == '#') flag = true;
    if (maze[x][y] == '.') flag = false;
    dfs(x - 1, y, flag);
    if (maze[x][y] == '#') flag = true;
    if (maze[x][y] == '.') flag = false;
    dfs(x, y + 1, flag);
    if (maze[x][y] == '#') flag = true;
    if (maze[x][y] == '.') flag = false;
    dfs(x, y - 1, flag);
}

