  //4隣接（上下左右）
//  vector<vector<int> > adj_4 = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
  //今回は2隣接でいい
  vector<vector<int> > adj_4 = {{0, 1}, {1, 0}};

  REP(h, 1, H+1){
    REP(w, 1, W+1){
      for (auto each_vec : adj_4){
        int tg_h = h + each_vec[0];
        int tg_w = w + each_vec[1];
        if(mapdata[h][w] != mapdata[tg_h][tg_w] && mapdata[tg_h][tg_w] != 'w'){
          UF.unite(to_n(h, w), to_n(tg_h, tg_w));
        }
      }
    }
  }

  UF.solve();
  oi(finalans); br();


