		}
	}



	Int score = 0;
	for (Int i = 0; i < H; i++) {
		for (Int j = 0; j < W; j++) {
			if (S[i][j].have_been == false) {
				struct pir tmp;
				tmp = explore(i, j, H, W);
				score += tmp.black*tmp.white;
			}
		}
	}
	print(score);







	return 0;
}

