vector<int> dx = {1, 0, -1,  0};
vector<int> dy = {0, 1,  0, -1};

int h, w;
vector<string> s;
vector<vector<int>> memo;

void show_memo() {
	printf("\n");
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			printf("%2d ", memo[i][j]);
		}
		printf("\n");
	}
	printf("\n");
}

void walk(int sy, int sx, int num) {
	queue<PII> que;
	que.push(make_pair(sy, sx));
	memo[sy][sx] = num;

	while (!que.empty()) {
		auto p = que.front();
		que.pop();

		int y = p.first;
		int x = p.second;

		for (int i = 0; i < 4; i++) {
			int ny = y + dy[i];
			int nx = x + dx[i];


			if (nx < 0 || w <= nx || ny < 0 || h <= ny) {
				continue;
			}
// printf("(%d %d: %c %d) dir %d -> (%d %d: %c %d)\n",
// 	y, x, s[y][x], memo[y][x], i,
// 	ny, nx, s[ny][nx], memo[ny][nx]);

			if (memo[ny][nx] != 0 || s[ny][nx] == s[y][x]) {
// printf("continue\n");
				continue;
			}
// printf("push\n");

			que.push(make_pair(ny, nx));
			memo[ny][nx] = num;
		}
	}
}

int main() {
	cin >> h >> w;

	s.assign(h, "");
	for (int i = 0; i < h; i++) {
		cin >> s[i];
	}

	memo.assign(h, vector<int>(w, 0));

	int num = 0;
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			if (memo[i][j] != 0 || s[i][j] == '.') {
				continue;
			}

			num++;
			walk(i, j, num);
		}
	}

	vector<int> blacks(num+1, 0), whites(num+1, 0);
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			int n = memo[i][j];
			s[i][j] == '.' ? whites[n]++ : blacks[n]++;
		}
	}

	int ans = 0;
	for (int i = 0; i < blacks.size(); i++) {
		// printf("%d: %d %d\n", i, blacks[i], whites[i]);
		ans += blacks[i] * whites[i];
	}
	cout << ans << endl;
	// show_memo();
	return 0;
}

