using namespace std;

int h, w;


int board[410][410];	//0--黑色，1--白色 
int belongsTo[410][410];

struct Section	//每个区域为一个范围
{
	int id;	//编号
	int numOfBlack;	//黑色块
	int numOfWhite;	//白色块 
};
Section sections[160100];
int szSections;

struct Point
{
	int r, c;
};

int dr[4] = {-1, 1, 0, 0};
int dc[4] = { 0, 0,-1, 1};

void floodfill(int startR, int startC, int sectionFlag)
{
	sections[sectionFlag].id = sectionFlag;
	sections[sectionFlag].numOfBlack = 0;
	sections[sectionFlag].numOfWhite = 0;

	Point newPoint, curPoint;
	std::queue<Point> q;
	curPoint.r = startR;
	curPoint.c = startC;
	belongsTo[curPoint.r][curPoint.c] = sectionFlag;
	q.push(curPoint);

	while (!q.empty())
	{
		curPoint = q.front();
		q.pop();

		for (int d = 0 ; d < 4 ; d++)
		{
			newPoint.r = curPoint.r + dr[d];
			newPoint.c = curPoint.c + dc[d];

			if (0 <= newPoint.r && newPoint.r < h &&
			    0 <= newPoint.c && newPoint.c < w)	//范围内 
			{
				if (board[curPoint.r][curPoint.c] == board[newPoint.r][newPoint.c])	//颜色相等的剔除
					continue;

				if (belongsTo[newPoint.r][newPoint.c] != -1) 	//防止重复 
					continue;

				belongsTo[newPoint.r][newPoint.c] = sectionFlag;
				q.push(newPoint);
			}
		}

	}
}

int main()
{
	scanf("%d%d\n", &h, &w);
	char temp[410];

	for (int r = 0 ; r < h ; r++)
	{
		scanf("%s\n", temp);
		for (int c = 0 ; c < w ; c++)
		{
			if (temp[c] == '#')	//black
				board[r][c] = 0;
			if (temp[c] == '.')	//white
				board[r][c] = 1;

			belongsTo[r][c] = -1;
		}
	}

	szSections = 0;
	for (int r = 0 ; r < h ; r++)
	{
		for (int c = 0 ; c < w ; c++)
		{
			if (belongsTo[r][c] != -1)
				continue;
//			if (board[r][c] == 1)	//白色的不做
//				continue;

			floodfill(r, c, szSections);
			szSections++;
		}
	}

	for (int r = 0 ; r < h ; r++)
		for (int c = 0 ; c < w ; c++)
		{
			int p = belongsTo[r][c];
			if (board[r][c] == 0)	//黑色
				sections[p].numOfBlack++;
			if (board[r][c] == 1)	//白色
				sections[p].numOfWhite++;
		}

	int ans = 0;
	for (int i = 0 ; i < szSections ; i++)
	{
		ans = ans + sections[i].numOfBlack * sections[i].numOfWhite;
	}

	printf("%d\n", ans);
	return 0;
}

