void bfs(int y, int x, vvi &v, vs &s, int num){
    v[y][x]=num;
    queue<pair<int,int> > q;
    q.push(mp(y,x));
    while(!q.empty()){
        pair<int,int> now=q.front();q.pop();
        v[now.first][now.second]=num;
        for(int i=0;i<4;i++){
            int nexty=now.first+dy[i];
            int nextx=now.second+dx[i];
            if(nexty<0||nextx<0||nextx>=s[0].size()||nexty>=s.size())continue;
            if(v[nexty][nextx]!=-1)continue;
            if(s[nexty][nextx]==s[now.first][now.second])continue;
            q.push(mp(nexty,nextx));
        }
    }
}
int bfs2(int y, int x, vvi v, vs s, int num){
    int res=0;
    queue<pair<int,int> > q;
    q.push(mp(y,x));
    while(!q.empty()){
        pair<int,int> now=q.front();q.pop();
        // cout<<now.first<<" "<<now.second<<" "<<num<<endl;
        for(int i=0;i<4;i++){
            int nexty=now.first+dy[i];
            int nextx=now.second+dx[i];
            if(nexty<0||nextx<0||nextx>=s[0].size()||nexty>=s.size())continue;
            if(v[nexty][nextx]!=num)continue;
            v[nexty][nextx]=-1;
            if(s[nexty][nextx]=='.')res++;
            // cout<<res<<endl;
            q.push(mp(nexty,nextx));
        }
    }
    return res;
}

