void solve(long long H, long long W, vector<string> S){

    for(size_t i = 0; i < 400; i++)
    {
        fill(used[i],used[i]+400,false);
    }

    long long ans=0;

    for(size_t i = 0; i < S.size(); i++)
    {
        for(size_t j = 0; j < S[i].size(); j++)
        {
            if(used[i][j]==true){
                continue;
            }
            int b=0,w=0;
            queue<pair<int,int>> q;
            q.push(make_pair(i,j));
            used[i][j]=true;
            while(!q.empty()){
                auto a=q.back();q.pop();
                switch(S[a.first][a.second]){
                    case '.':
                        w++;
                        break;
                    case '#':
                        b++;
                        break;
                }

                for(size_t ii = 0; ii < 4; ii++)
                {
                    pair<int,int> b=a;
                    b.first+=tonari[ii][0];
                    b.second+=tonari[ii][1];
                    if(b.first<0||b.first>H-1||b.second<0||b.second>W-1){
                        continue;
                    }
                    if(used[b.first][b.second]){
                        continue;
                    }
                    if(S[b.first][b.second]!=S[a.first][a.second]){
                        used[b.first][b.second]=true;
                        q.push(b);
                    }

                }
            }
            cerr<<b<<','<<w<<endl;
            ans+=b*w;
        }
    }
    cout<<ans<<endl;
}

