class quick_find {
	vector<int> rt;
public:
	vector<vector<int>> vs;
	quick_find(int n) : rt(n), vs(n) {
		for (int i = 0; i < n; i++) rt[i] = i, vs[i].push_back(i);
	}
	int find(int a) {
		return rt[a];
	}
	bool same(int a, int b) {
		return rt[a] == rt[b];
	}
	void unite(int a, int b) {
		a = rt[a], b = rt[b];
		if (a == b) return;
		if (vs[a].size() < vs[b].size()) swap(a, b);
		for (auto& v : vs[b]) rt[v] = a;
		copy(vs[b].begin(), vs[b].end(), back_inserter(vs[a]));
	}
	int size(int a) {
		return vs[rt[a]].size();
	}
};

int main()
{
	int H, W;
	cin >> H >> W;
	vector<string> S(H);
	for (int i = 0; i < H; i++) {
		cin >> S[i];
	}
	quick_find uf(H * W);
	quick_find uf2(H * W * 2);
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (i + 1 < H && S[i + 1][j] != S[i][j]) {
				uf.unite(i * W + j, (i + 1) * W + j);
				uf2.unite(H * W + i * W + j, (i + 1) * W + j);
				uf2.unite(i * W + j, H * W + (i + 1) * W + j);
			}
			if (j + 1 < W && S[i][j + 1] != S[i][j]) {
				uf.unite(i * W + j, i * W + j + 1);
				uf2.unite(H * W + i * W + j, i * W + j + 1);
				uf2.unite(i * W + j, H * W + i * W + j + 1);
			}
		}
	}
	ll res = 0;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) if (uf.find(i * W + j) == i * W + j) {
			ll c1 = 0, c2 = 0;
			for (auto v : uf.vs[i * W + j]) {
				(uf2.same(i * W + j, v) ? c1 : c2) += 1;
			}
			res += c1 * c2;
		}
	}
	cout << res << endl;
	return 0;
}

