	{
		cin >> board[y];
	}

	const int N = H * W;

	// セットでつかっとけ
	vector <int> v;
	union_init(v, N);

	for (int y = 0; y < H; ++y)
	{
		for (int x = 0; x < W; ++x)
		{
			const static int dy[] = { -1, 0, 1, 0 }; // U,R,D,L
			const static int dx[] = { 0, 1, 0,-1 };
			for (int d = 0; d < 4; ++d)
			{
				const int ny = y + dy[d];
				const int nx = x + dx[d];
				if (INRANGE(ny, 0, H - 1) && INRANGE(nx, 0, W - 1))
				{
					if (board[y][x] != board[ny][nx])
					{
						union_connect(v, y*W + x, ny*W + nx);
					}
				}
			}
		}
	}

