            }
            else{
                black.at(index)++;
            }
        }
    }

    int ans = 0;
    for(int i = 0;i<H;i++){
        for(int j = 0;j<W;j++){
            ans += white.at(i*W+j+1)*black.at(i*W+j+1);
        }
    }

    cout << ans << endl;

}

