struct UnionFind {
    vector<int> par;
    vector<int> rank;
    UnionFind(int n) {
        par.resize(n);
        for (int i=0; i<n; ++i) par[i] = i;
        rank.resize(n, 1);
    }
    int find(int a) {
        if (par[a] == a) return a;
        return par[a] = find(par[a]);
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (rank[a] < rank[b]) {
            par[a] = b;
        } else {
            par[b] = a;
            if (rank[a] == rank[b]) rank[a]++;
        }
    }
};

