	UnionFind uf(h * w);
	rep (i, h) cin >> s[i];
	rep (i, h) {
		rep (j, w) {
			if (j + 1 < w && ((s[i][j] == '#') ^ (s[i][j + 1] == '#'))) {
				uf.unite(i * w + j, i * w + j + 1);
			}
			if (i + 1 < h && ((s[i][j] == '#') ^ (s[i + 1][j] == '#'))) {
				uf.unite(i * w + j, (i + 1) * w + j);
			}
		}
	}
	map<ll, P> m;
	rep (i, h * w) {
		if (s[i / w][i % w] == '#') m[uf.find(i)].first++;
		else m[uf.find(i)].second++;
		// eprintf("%d ", uf.find(i));
	}
	// eprintf("\n");
	ll ans = 0;
