/* constant */

const int MAX_H = 400;
const int MAX_W = 400;
const int MAX_N = MAX_H * MAX_W;

const int dxs[] = { 1, 0, -1, 0 }, dys[] = { 0, -1, 0, 1 };

/* typedef */

typedef long long ll;
typedef vector<int> vi;
typedef queue<int> qi;
typedef pair<int,int> pii;

/* global variables */

char flds[MAX_H][MAX_W + 4];
bool used[MAX_H][MAX_W];

/* subroutines */

/* main */

int main() {
  int h, w;
  scanf("%d%d", &h, &w);
  for (int y = 0; y < h; y++) scanf("%s", flds[y]);

  memset(used, false, sizeof(used));
  ll sum = 0;

  for (int y = 0; y < h; y++)
    for (int x = 0; x < w; x++)
      if (! used[y][x]) {
	used[y][x] = true;
	int bn = 0, wn = 0;
	(flds[y][x] == '#') ? bn++ : wn++;
	queue<pii> q;
	q.push(pii(x, y));

	while (! q.empty()) {
	  pii u = q.front(); q.pop();
	  int &ux = u.first, &uy = u.second;
	  char &uf = flds[uy][ux];

	  for (int di = 0; di < 4; di++) {
	    int vx = ux + dxs[di], vy = uy + dys[di];
	    if (vx >= 0 && vx < w && vy >= 0 && vy < h &&
		! used[vy][vx] && flds[vy][vx] != uf) {
	      used[vy][vx] = true;
	      (flds[vy][vx] == '#') ? bn++ : wn++;
	      q.push(pii(vx, vy));
	    }
	  }
	}

	sum += (ll)bn * wn;
      }

  printf("%lld\n", sum);
  return 0;
}

