bool inside(int a, int b){
    if(a < 0 || a >= h) return false;
    if(b < 0 || b >= w) return false;
    return true;
}

pair<int, int> dfs(int a, int b){
    if(visited[a][b]) return make_pair(0, 0);
    visited[a][b] = true;
    int c1 = 0, c2 = 0;
    if(s[a][b] == '.') c1++;
    else c2++;
    for(int i = 0; i < 4; i++){
        int to_a = a + dy[i], to_b = b + dx[i];
        if(!inside(to_a, to_b)) continue;
        if(s[to_a][to_b] == s[a][b]) continue;
        auto x = dfs(to_a, to_b);
        c1 += x.first;
        c2 += x.second;
    }
    return make_pair(c1, c2);
}

