        dfs(x+1,y,s[x+1][y]);
    }
    if(y-1>=0&&s[x][y-1]!=now&&!vis[x][y-1]){
        vis[x][y-1]=1;
        dfs(x,y-1,s[x][y-1]);
    }
    if(y+1<m&&s[x][y+1]!=now&&!vis[x][y+1]){
        vis[x][y+1]=1;
        dfs(x,y+1,s[x][y+1]);
    }
}
