class UnionFind {
public:
    vector <ll> par; // 各元の親を表す配列
    vector <ll> siz; // 素集合のサイズを表す配列(1 で初期化)

    // Constructor
    UnionFind(ll sz_): par(sz_), siz(sz_, 1LL) {
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }
    void init(ll sz_) {
        par.resize(sz_);
        siz.assign(sz_, 1LL);  // resize だとなぜか初期化されなかった
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }

    // Member Function
    // Find
    ll root(ll x) { // 根の検索
        while (par[x] != x) {
            x = par[x] = par[par[x]]; // x の親の親を x の親とする
        }
        return x;
    }

    // Union(Unite, Merge)
    bool merge(ll x, ll y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        // merge technique（データ構造をマージするテク．小を大にくっつける）
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        par[y] = x;
        return true;
    }

    bool issame(ll x, ll y) { // 連結判定
        return root(x) == root(y);
    }

    ll size(ll x) { // 素集合のサイズ
        return siz[root(x)];
    }
};

int main() {
    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    REP(i, H) cin >> S[i];
    UnionFind uf(H*W);

    REP(y, H-1) {
        REP(x, W-1) {
            if(S[y][x+1] != S[y][x]) uf.merge(y*W + x, y*W + (x+1));
            if(S[y+1][x] != S[y][x]) uf.merge(y*W + x, (y+1)*W + x);
        }
        if(S[y+1][W-1] != S[y][W-1]) uf.merge(y*W + W-1, (y+1)*W + W-1);
    }

    REP(x, W-1) if(S[H-1][x+1] != S[H-1][x]) uf.merge((H-1)*W + x, (H-1)*W + (x+1));

    set<int> parents;
    map<int, int> white, black;
    REP(y, H) REP(x, W) {
        parents.insert(uf.root(y*W+x));
        if(S[y][x] == '#') black[uf.root(y*W+x)]++;
        else white[uf.root(y*W+x)]++;
    }
    int ans = 0;

    // (H-1) * W + (W-1) = H*W - 1
    for(int p: parents) {
        ans += black[p]*white[p];
    }

    cout << ans << endl;

    return 0;
}

