using namespace std;
class UnionFind {
 public:
  vector<ll> par;
  vector<ll> siz;

  // Constructor
  UnionFind(ll sz_) : par(sz_), siz(sz_, 1LL) {
    for(ll i = 0; i < sz_; ++i) par[i] = i;
  }
  void init(ll sz_) {
    par.resize(sz_);
    siz.assign(sz_, 1LL);
    for(ll i = 0; i < sz_; ++i) par[i] = i;
  }

  // Member Function
  // Find
  ll root(ll x) {
    while(par[x] != x) {
      x = par[x] = par[par[x]];
    }
    return x;
  }

  // Union(Unite, Merge)
  bool merge(ll x, ll y) {
    x = root(x);
    y = root(y);
    if(x == y) return false;
    if(siz[x] < siz[y]) swap(x, y);
    siz[x] += siz[y];
    par[y] = x;
    return true;
  }

  bool issame(ll x, ll y) {  // 連結判定
    return root(x) == root(y);
  }

  ll size(ll x) {  // 素集合のサイズ
    return siz[root(x)];
  }
};

int main() {
  int H, W;
  cin >> H >> W;
  auto board = vector<vector<char>>(H, vector<char>(W));
  REP(i, H) {
    string S;
    cin >> S;
    board[i] = vector<char>(ALL(S));
  }

  UnionFind uf = UnionFind(H * W);

  REP(i, H) {
    REP(j, W) {
      if(i + 1 < H && board[i][j] != board[i + 1][j]) {
        uf.merge(W * i + j, W * (i + 1) + j);
      }
      if(j + 1 < W && board[i][j] != board[i][j + 1]) {
        uf.merge(W * i + j, W * i + j + 1);
      }
    }
  }
  auto isBlack = [&](int n) {
    int i = n / W;
    int j = n % W;
    return board[i][j] == '#';
  };

  auto black = vector<ll>(H * W);
  auto white = vector<ll>(H * W);
  REP(i, H * W) {
    // dump(isBlack(i));
    if(isBlack(i)) {
      black[uf.par[i]]++;
    } else {
      white[uf.par[i]]++;
    }
  }
  // dump(black, white);
  ll ans = 0;
  REP(i, H * W) { ans += black[i] * white[i]; }
  cout << ans << endl;
}

