  ll h,w,r=0;
  cin >> h >> w;
  vs s(h);
  REP(i,h){
    cin >> s[i];
  }
  c[0]=0;
  REP1(x,w-1){
    if (s[0][x]!=s[0][x-1]) {
      c[x] = c[x-1];
    } else {
      c[x] = x;
    }
  }
  REP1(y,h-1){
    if (s[y][0]!=s[y-1][0]) {
      c[y*w] = c[(y-1)*w];
    } else {
      c[y*w] = y*w;
    }
  }
  REP1(y,h-1){
    REP1(x,w-1){
      if (s[y-1][x]!=s[y][x]&&s[y][x-1]!=s[y][x]) {
        c[c[(y-1)*w+x]] = c[y*w+x-1];
        c[w*y+x] = c[(y-1)*w+x];
      } else if (s[y-1][x]!=s[y][x]) {
        c[w*y+x] = c[w*(y-1)+x];
      } else if (s[y][x-1]!=s[y][x]) {
        c[w*y+x] = c[w*y+x-1];
      } else {
        c[w*y+x] = y*w+x;
      }
    }
  }
  REP(y,h){
    REP(x,w){
      ll i=x+y*w;
      u[chk(i)][(x+y)%2]++;
    }
  }
  REP(i,h*w){
    r+=u[i][0]*u[i][1];
  }
  cout << r;
  return 0;
}

