            dfs(i-1, j, !color);
        }
    }
    if (i + 1 < w) {
        if (!visited[j][i+1] && matrix[j][i+1] != color) {
            visited[j][i+1] = true;
            dfs(i+1, j, !color);
        }
    }
    if (0 < j - 1) {
        if (!visited[j-1][i] && matrix[j-1][i] != color) {
            visited[j-1][i] = true;
            dfs(i, j-1, !color);
        }
    }
    if (j + 1 < h) {
        if (!visited[j+1][i] && matrix[j+1][i] != color) {
            visited[j+1][i] = true;
            dfs(i, j+1, !color);
