int par[160000];
int c1[160000];
int c2[160000];

int find(int x) {
    if (par[x] == x) return x;
    return par[x] = find(par[x]);
}

void unite(int x, int y) {
    x = find(x);
    y = find(y);

    if (x == y) return;

    par[x] = y;
}

int main() {
