Point operator+(const Point& a,const Point& b){return Point(a.h+b.h,a.w+b.w);}

struct Board{

	int H,W;
	vector<string>s ;
	vector<Point>near;
	queue<Point> que;
	vector<vector<int>> dist;
	vector<vector<bool>> visited;
	int ans;

	Board(){};
	Board(int h_,int w_){
		H=h_,W=w_;
		s.resize(H);
		near={{-1,0},{1,0},{0,-1},{0,1}};
		init_dist();
		init_visited();
	};
	bool in_board0(int x,int y){if(0<=x && x<H && 0<=y && y<W)return true;else return false;} 
	bool in_board(Point p){if(0<=p.h && p.h<H && 0<=p.w && p.w<W)return true;else return false;} 
	char get_char(Point p){return s[p.h][p.w];}
	vector<Point> get_near(Point p){vector<Point>ret;for(auto&& u:near)ret.emplace_back(p+u);return ret;}

	int  get_dist(Point p){return dist[p.h][p.w];}
	int  set_dist(Point p,int i){dist[p.h][p.w]=i;}
	void init_dist(){dist.assign(H,vector<int>(W,-1));}

	int  is_visited(Point p){return visited[p.h][p.w];}
	int  set_visited(Point p,bool i){visited[p.h][p.w]=i;}
	void init_visited(){visited.assign(H,vector<bool>(W,false));}


	void dfs(Point p){
		if(is_visited(p))return;
		set_visited(p,true);
		char c1,c2;
		c1=get_char(p);
		for(auto&& q:near){
			Point u=p+q;

		if(! in_bound(u))continue;
		c2=get_char(u);	
	    if(!is_visited(u) && c1!=c2){

				if(c2=='.'){ans++;}//cout<<"w "<<u.h<<" "<<u.w<<endl;}
				dfs(u);
		}
		}
	}

	void dfs0(int x,int y){
		if(visited[x][y])return;
		visited[x][y]=true;
		char c1=s[x][y];
		for(auto&& q:near){
			int x0=x+q.h,y0=y+q.w;
		if(!in_board0[x0][y0])continue;
		char c2=s[x0][y0];
		if( !is_visited[x0][y0] && c1!=c2){

				if(c2=='.'){ans++;}//cout<<"w "<<u.h<<" "<<u.w<<endl;}
				dfs(x0,y0);
		}
		}
	}

	int do_all_dfs(){
		ans=0;
		for (int i;i<H;i++)for(int j=0;j<W;j++){

		if(s[i][j]=='#'){
	//		cout<<"b "<<p.h<<" "<<p.w<<endl;
		init_visited();
		dfs(i,j);
		}}
		return ans;
	}

	void bfs(){
		while(! que.empty()){
		Point p=que.front();que.pop();	
		for(auto&& u:get_near(p)){
		if(in_board(u) && ! is_visited(u) && get_char(p)!=get_char(u)){
			set_visited(u,true);
			if(get_char(u)=='.')ans++;
			que.push(u);
		}}
		}}

	int do_all_bfs(){for (int i;i<H;i++)for(int j=0;j<W;j++){
		ans=0;
		for (int i;i<H;i++)for(int j=0;j<W;j++){
		Point p(i,j);
		if(get_char(p)=='#'){
	//		cout<<"b "<<p.h<<" "<<p.w<<endl;
		init_visited();
		que.push(p);
		set_visited(p,true);
		bfs();
		}}
		return ans;
	}
	}

};


