void naming(int g[402][402],int arr[402][402],int group,int i, int j){
    if(arr[i][j]==1){
        if(g[i][j]==0){
            g[i][j] = group;
        if (arr[i-1][j]==-1) naming(g,arr,group,i-1,j);
        if (arr[i][j-1]==-1) naming(g,arr,group,i,j-1);
        if (arr[i+1][j]==-1) naming(g,arr,group,i+1,j);
        if (arr[i][j+1]==-1) naming(g,arr,group,i,j+1); 
        }

    }else if(arr[i][j]==-1){
        if(g[i][j]==0){
            g[i][j] = group;
        if (arr[i-1][j]==1) naming(g,arr,group,i-1,j);
        if (arr[i][j-1]==1) naming(g,arr,group,i,j-1);
        if (arr[i+1][j]==1) naming(g,arr,group,i+1,j);
        if (arr[i][j+1]==1) naming(g,arr,group,i,j+1); 
        }
    }
}

