int H, W;
char s[405][405];
bool visited[405][405];
const int dx[] = {1, 0, -1, 0, 1, -1, -1, 1};
const int dy[] = {0, 1, 0, -1, 1, 1, -1, -1};

void dfs(int x, int y, lint &black, lint &white) {
    if (visited[x][y]) return;
    visited[x][y] = true;

    if (s[x][y] == '#') {
        black++;
    } else {
        white++;
    }
    for (int i = 0; i < 4; i++) {
        int nx = x + dx[i], ny = y + dy[i];
        if (0 <= nx && nx < H && 0 <= ny && ny < W &&
            s[nx][ny] != s[x][y]) {
            dfs(nx, ny, black, white);
        }
    }
}

int main() {
    cin >> H >> W;
    for (int i = 0; i < H; i++) {
        cin >> s[i];
