    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (!visited[i][j]) {
                lint b = 0, w = 0;
                dfs(i, j, b, w);
                ans += b * w;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

