    string s;
    cin>>s;
    for(int j=0;j<w;++j)if(s[j]=='#')a[i][j]=true;
  }
  union_find u;
  u.clear(h*w);
  for(int i=0;i<h;++i)for(int j=0;j<w;++j){
    if(0<i&&a[i-1][j]!=a[i][j])u.unite((i-1)*w+j,i*w+j);
    if(i<h-1&&a[i+1][j]!=a[i][j])u.unite((i+1)*w+j,i*w+j);
    if(0<j&&a[i][j-1]!=a[i][j])u.unite(i*w+j-1,i*w+j);
    if(j<w-1&&a[i][j+1]!=a[i][j])u.unite(i*w+j+1,i*w+j);
  }
