pair<int, int> f(const vector<string> &S, vector<vector<bool>> &check, int h, int w){
    pair<int, int> ret = make_pair(0, 0);
    (S[h][w] == '.' ? ret.second : ret.first)++;
    check[h][w] = true;
    int dh[4] = {1, -1, 0, 0};
    int dw[4] = {0, 0, 1, -1};
    for(int i = 0; i < 4; i++){
        int hh = h + dh[i];
        int ww = w + dw[i];
        if(0 <= hh && hh < S.size() && 0 <= ww && ww < S[0].length() && !check[hh][ww]){
            if(S[h][w] != S[hh][ww]){
                auto p = f(S, check, hh, ww);
                ret.first += p.first;
                ret.second += p.second;
            }
        }
    }
    return ret;
}

