int n, m;
char grid[405][405];
bool vis[405][405];
int black, white;
ll ans;

void dfs(int i, int j) {
	if (grid[i][j] == '#') black++;
	else white++;
	vis[i][j] = true;
	if (grid[i-1][j] != grid[i][j] && grid[i-1][j] != '$' && !vis[i-1][j]) dfs(i-1, j);
	if (grid[i+1][j] != grid[i][j] && grid[i+1][j] != '$' && !vis[i+1][j]) dfs(i+1, j);
	if (grid[i][j-1] != grid[i][j] && grid[i][j-1] != '$' && !vis[i][j-1]) dfs(i, j-1);
	if (grid[i][j+1] != grid[i][j] && grid[i][j+1] != '$' && !vis[i][j+1]) dfs(i, j+1);
}

int main() {
	reset(grid, '$');
	scanf("%d %d", &n, &m);
	for (int i = 1; i <= n; i++) {
		getchar();
		for (int j = 1; j <= m; j++) {
			scanf("%c", &grid[i][j]);
		}
	}
	for (int i = 1; i <= n; i++) {
		for (int j = 1; j <= m; j++) {
			if (vis[i][j]) continue;
			black = 0;
			white = 0;
			dfs(i, j);
			// printf("%d %d\n", black, white);
			ans += 1ll * black * white;
		}
	}
	printf("%lld\n", ans);
	return 0;
}

