struct union_find
{
    vector<long long> par;  //親の番号　
    vector<long long> rank; //木の深さ(根のランクは0)
    vector<long long> siz;  //要素xが根なら木の頂点数を格納する
    //初期化子リストを用いた初期化
    union_find(long long N) : par(N), rank(N), siz(N)
    {
        for (long long i = 0; i < N; i++)
        {
            par[i] = i;
            rank[i] = 0;
            siz[i] = 1;
        }
    }
    //要素xが所属する木の根を再帰的に発見する
    long long root(long long x)
    {
        if (par[x] == x)
            return x;
        return par[x] = root(par[x]); //経路圧縮
    }
    //要素xが属する木と要素yが属する木の併合
    void unite(long long x, long long y)
    {
        long long rx = root(x);
        long long ry = root(y);
        if (rx == ry)
            return; //同じ木に属してたらそのまま
        if (rank[rx] < rank[ry])
        {
            par[rx] = ry; //根がryの木に併合
            siz[ry] = siz[rx] + siz[ry];
        }
        else
        {
            par[ry] = rx; //根がrxの木に併合
            siz[rx] = siz[rx] + siz[ry];
            if (rank[rx] == rank[ry])
                rank[rx]++;
        }
    }
    //要素xが属する木と要素yが属する木が同じならtrueを返す
    bool same(long long x, long long y)
    {
        return root(x) == root(y);
    }
    //要素xが属する木の頂点数を返す
    long long size(long long x)
    {
        return siz[root(x)];
    }
};
//union-find木による森がいくつの木からなるかを返す
ll partial(union_find tree)
{
    ll n = tree.siz.size();
    vector<bool> seen(n, false);
    ll ans = 0;
    loop(i, n)
    {
        if (seen[tree.root(i)])
            continue;
        seen[tree.root(i)] = true;
        ans++;
    }
    return ans;
}
/*
このunion_find木で出来ること
例)union_find tree(N);などで宣言(N:頂点数)
tree.same(x,y):要素xと要素yが同じグループに属するか判定
tree.unite(x,y):要素xが属する木と要素yが属するグループの併合
tree.size(x,y):要素xが属する木の頂点数を返す
※グループの分割が出来ないことに注意！
計算量O(α(N))(ほぼO(1))
*/
int main()
{
    cout << fixed << setprecision(30);
    ll H, W;
    cin >> H >> W;
    vector<string> S(H);
    loop(i, H) cin >> S[i];
    union_find tree(H * W);
    loop(i, H)
    {
        loop(j, W)
        {
            char now = S[i][j];
            loop(d, 4)
            {
                ll nx = i + dx[d], ny = j + dy[d];
                if (nx < 0 || nx >= H || ny < 0 || ny >= W)
                    continue;
                char next = S[nx][ny];
                if (now != next)
                    tree.unite(W * i + j, W * nx + ny);
            }
        }
    }
    //tree.root(x)でmapを用いて管理
    map<ll, ll> white;
    map<ll, ll> black;
    loop(i, H)
    {
        loop(j, W)
        {
            ll parent = tree.root(i * W + j);
            if (S[i][j] == '.')
                white[parent]++;
            else
                black[parent]++;
        }
    }
    ll ans = 0;
    loop(i, H * W) ans += white[i] * black[i];
    putout(ans);
    return 0;
}

