        }

        if (y > 0 && s[x][y-1] == '#') {
            P p2 = dfs(x, y-1);
            p.first += p2.first;
            p.second += p2.second;
        }
    } else {
        p.second++;
        if (x < h-1 && s[x+1][y] == '.') {
            P p2 = dfs(x+1, y);
            p.first += p2.first;
            p.second += p2.second;
