struct UnionFind {
  vector<ll> par;

  UnionFind(ll N) : par(N) { rep(i, N) par[i] = i; }

  int root(ll x) { 
    if (par[x]==x) return x;
    else return par[x] = root(par[x]);
  }

  void unite(ll x, ll y) {
    ll rx = root(x);
    ll ry = root(y);
    if (rx==ry) return;
    par[rx] = ry;
  }

  bool same(ll x, ll y) {
    return root(x) == root(y);
  }

};

int main() {
