	      if(S[now.first][now.second]==S[y][x]) continue;
	      if(S[y][x]=='.') ans++;
	      v[y][x] = 1;
	      q.push(make_pair(y, x));
	    }
	  }
	}
      }
    }
  }
  std::cout << ans << std::endl;
}

