} Parameter;

int is_pass(Parameter * p)
{
std::list<int> list_dir;
std::list<Point> list_pos;

list_dir.push_back(-1);
list_pos.push_back(p->str);

for (;;)
{
if (list_pos.size() == 0) return 0;

Point cur = list_pos.back();
Point nex = cur;
int dir = list_dir.back(); dir++;
list_dir.back() = dir;

switch (dir)
{
case 0: nex.x += 1; nex.y += 0; break;
case 1: nex.x += 0; nex.y += 1; break;
case 2: nex.x -= 1; nex.y += 0; break;
case 3: nex.x += 0; nex.y -= 1; break;
default:
list_pos.pop_back();
list_dir.pop_back();
continue;
}

if ((nex.x < 0) || (nex.x >= p->w) || (nex.y < 0) || (nex.y >= p->h)) continue;

char twice = 0;
for (auto it = list_pos.begin(); it != list_pos.end(); it++)
{
    if ((nex.x == it->x) && (nex.y == it->y))
    {
        twice = 1;
        break;
    }
}
if (twice) continue;

char d0 = p->map[cur.y][cur.x];
char d1 = p->map[nex.y][nex.x];
if (d0 == d1) continue;

if ((nex.x == p->end.x) && (nex.y == p->end.y))
return 1;

list_pos.push_back(nex);
list_dir.push_back(-1);
}

return 0;
}

