using namespace std;

class unionfind {
  vector<int> p;
public:
  void init(int n) {
    for (int i = 0; i < n; i++) {
      p.push_back(i);
    }
  }

  void merge(int m, int n) {
    if (find(m) == find(n)) return;
    p.at(find(m)) = find(n);
  }

  int find(int n) {
    if (p.at(n) == n) return n;
    return p.at(n) = find(p.at(n));
  }
};

int main()
{
  int h, w;
  cin >> h >> w;
  vector<string> s(h);
  for (int i = 0; i < h; i++) cin >> s.at(i);
  unionfind t;
  t.init(h * w);
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (j < w - 1 && s.at(i).at(j) != s.at(i).at(j + 1)) {
        t.merge(i * w + j, i * w + j + 1);
      }
      if (i < h - 1 && s.at(i).at(j) != s.at(i + 1).at(j)) {
        t.merge(i * w + j, (i + 1) * w + j);
      }
    }
  }
  vector<pair<int, int>> c(h * w);
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      int root = t.find(i * w + j);
      if (s.at(i).at(j) == '#') {
        c.at(root).first++;
      } else {
        c.at(root).second++;
      }
    }
  }
  long total = 0;
  for (int i = 0; i < h * w; i++) {
    total += (long)c.at(i).first * c.at(i).second;
  }
  cout << total << endl;
}

