    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            char c; cin >> c;
            if(c=='#'){
                B[i][j] = ((i+j)%2==0);
            }
            if(c=='.'){
                B[i][j] = ((i+j)%2!=0);
            }
            checked[i][j]=false;
        }
    }

    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            if(checked[i][j]){ continue; }
            int a=0,b=0;
            func(i,j, &a, &b);
            count += a*b;
        }
    }
