const int dy[] = {1, 0, -1, 0};

char grd[N][N];
int h, w, dot, hsh, vst[N][N];

bool boundary(int i, int j) {
  return (i >= 0 && i < h) && (j >= 0 && j < w);
}

void dfs(int i, int j) {
  vst[i][j] = 1;
  if (grd[i][j] == '.') dot++;
  if (grd[i][j] == '#') hsh++;
  for (int k = 0; k < 4; k++) {
    int x = i + dx[k];
    int y = j + dy[k];
    if (boundary(x, y)) {
      if (vst[x][y] == 0 && grd[i][j] != grd[x][y]) {
        dfs(x, y);
      }
    }
  }
}

