// Union-Find
struct UnionFind {
    vector<int> par;
    vector<int> scale1;
    vector<int> black; // 黒の数
    vector<int> rank;
    int size;
    // par[i]はiの親の番号
    // scale[i]はiが親の時にのみ意味を持ち, その木の要素の数
    // rank[i]はiが親の時にのみ意味を持ち, その木のrank(union操作に使う)
    // 実はrankを導入してもほとんど速度変わらない
    // sizeは木の数
    // scaleとsizeはオプションなので必要なら消してもいい

    //最初は全てが根であるとして初期化
    UnionFind(int N) : par(N), black(N, 0), scale1(N,1), rank(N,0){
        for(int i = 0; i < N; i++) par[i] = i;
        size = N;
    }

    // データxが属する木の根を再帰で得る
    int root(int x){
        if (par[x] == x) return x;
        par[x] = root(par[x]); // 親を根にする付け替えによって次回以降の参照を高速化
        return par[x];
    }

    // xとyの木を併合(rankの大きい方の根を小さい方の根の親にする)
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        if(rank[rx] > rank[ry]){
            par[ry] = rx;
            scale1[rx] += scale1[ry];
            black[rx] += black[ry];
        }else if(rank[rx] < rank[ry]){
            par[rx] = ry;
            scale1[ry] += scale1[rx];
            black[ry] += black[rx];
        }else{
            // 同じならxを根に
            par[ry] = rx;
            scale1[rx] += scale1[ry];
            black[rx] += black[ry];
            rank[rx]++;
        }
        size--;
    }

    // 2つのデータx, yが属する木が同じならtrueを返す関数
    bool same(int x, int y){
        return root(x) == root(y);
    }
};

int main() {
    int H, W;
    cin >> H >> W;
    vector<string>S(H);
    for (int i = 0; i < H; ++i) {
      cin >> S[i];
    }
    UnionFind tree(H*W);
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            int k = W * i + j;
            if(S[i][j] == '#') tree.black[k]++;
        }
    }
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            int k = W * i + j;
            if(i != H-1 && S[i][j] != S[i+1][j]){
                tree.unite(k, k+W);
            }
            if(j != W-1 && S[i][j] != S[i][j+1]){
                tree.unite(k, k+1);
            }
        }
    }

    queue<int> que;
    ll ans = 0;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            int k = W * i + j;
            if(tree.par[k] == k) que.push(k);
        }
    }
    while (! que.empty()){
        int t = que.front();
        que.pop();
        ans += tree.black[t] * (tree.scale1[t] - tree.black[t]);
    }
    cout << ans;
    return 0;
}

