int find(int x) {
    return par[x] == x ? x : par[x] = find(par[x]);
}

void merge(int x, int y) {
     x = find(x);
     y = find(y);
     if (x == y) return;
     par[x] = y;
     wz[y] += wz[x];
     bz[y] += bz[x];
}

int main() {
    int H, W;
    scanf("%d %d", &H, &W);
    for (int i = 0; i < H; i++) {
        scanf("%s", s[i]);
