            if (s[i][j] == '#') bz[idx] = 1;
            else wz[idx] = 1;
            if (j && s[i][j - 1] != s[i][j]) merge(idx, idx - 1);
            if (i && s[i - 1][j] != s[i][j]) merge(idx, idx - W);
        }
    }
    LL ans = 0;
    for (int i = 0; i < H * W; i++) {
        int cur = find(i);
        if (visit[cur]) continue;
        visit[cur] = 1;
        ans += (LL)bz[cur] * wz[cur];
    }
    printf("%lld\n", ans);
    return 0;
}

