    vector<pair<int, int>> black;
    rep(i, H) cin >> S[i];
    rep(i, H){
        rep(j, W){
            if(S[i][j] == '#'){
                black.push_back(make_pair(i, j));
            }
        }
    }
    ll ans = 0;
    stack<pair<int, int>> work;
    while(!black.empty()){
        work.push(black[black.size()-1]);
        black.pop_back();
        visited[work.top().first][work.top().second] = 1;
        ll b = 1; //blackから取り出すのは#なので
        ll w = 0;
        //処理
        while(!work.empty()){
            pair<int, int> op = work.top();
            work.pop();
            int x = op.first, y = op.second;
            if(S[x][y] == '#'){
                if(x-1 >= 0 && S[x-1][y] == '.' && visited[x-1][y] == 0){
                    visited[x-1][y] = 1;
                    work.push(make_pair(x-1, y));
                    w++;
                }
                if(y-1 >= 0 && S[x][y-1] == '.' && visited[x][y-1] == 0){
                    visited[x][y-1] = 1;
                    work.push(make_pair(x, y-1));
                    w++;
                }
                if(y+1 <= W-1 && S[x][y+1] == '.' && visited[x][y+1] == 0){
                    visited[x][y+1] = 1;
                    work.push(make_pair(x, y+1));
                    w++;
                }
                if(x+1 <= H-1 && S[x+1][y] == '.' && visited[x+1][y] == 0){
                    visited[x+1][y] = 1;
                    work.push(make_pair(x+1, y));
                    w++;
                }
            }
            else{
                if(x-1 >= 0 && S[x-1][y] == '#' && visited[x-1][y] == 0){
                    visited[x-1][y] = 1;
                    work.push(make_pair(x-1, y));
                    b++;
                }
                if(y-1 >= 0 && S[x][y-1] == '#' && visited[x][y-1] == 0){
                    visited[x][y-1] = 1;
                    work.push(make_pair(x, y-1));
                    b++;
                }
                if(y+1 <= W-1 && S[x][y+1] == '#' && visited[x][y+1] == 0){
                    visited[x][y+1] = 1;
                    work.push(make_pair(x, y+1));
                    b++;
                }
                if(x+1 <= H-1 && S[x+1][y] == '#' && visited[x+1][y] == 0){
                    visited[x+1][y] = 1;
                    work.push(make_pair(x+1, y));
                    b++;
                }
            }
        }
        ans += b*w;
    }
    cout << ans << endl;

    return 0;
}

