          int tg_h = h + i;
          int tg_w = w + j;
          if(mapdata[h][w] != mapdata[tg_h][tg_w] && mapdata[tg_h][tg_w] != 'w'){
            UF.unite(to_n(h, w), to_n(tg_h, tg_w));
          }
        }
      }
    }
  }

