signed main(){
    int START_TIME = clock();
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
//    cout << fixed << setprecision(15);

    /**
     * 全点からBFSすれば良さそう。
     * それで白黒移動できるルートがいくつか得られるので、
     * それぞれのルートで白の個数 * 黒の個数を計算。
     * これの総和を求める。
     */

    i32 h,w; cin >> h >> w;
    vec<vec<char>> s(h, vec<char>(w));
    rep(i,h) rep(j,w) cin >> s[i][j];


    queue<PII> que;
    vii seen(h, vi(w, -1));
    i32 route_id = 0;
    rep(si, h) rep(sj, w) {
        if(seen[si][sj] != -1) continue;

        que.emplace(si, sj);
        seen[si][sj] = route_id;

        while(que.size()) {
            i32 i, j;
            tie(i,j) = que.front(); que.pop();
            rep(idx, 4) {
                i32 ni = i + mv_i[idx], nj = j + mv_j[idx];
                if(!(0 <= ni && ni < h && 0 <= nj && nj < w)) continue;
                if(s[ni][nj] == s[i][j]) continue;
                if(seen[ni][nj] != -1) continue;
                seen[ni][nj] = route_id;
                que.emplace(ni, nj);
            }
        }

        ++route_id;
    }

    vi white(route_id), black(route_id);
    rep(i,h) rep(j,w) {
        if(seen[i][j] == -1) continue;
        if(s[i][j] == '#') ++black[seen[i][j]];
        else ++white[seen[i][j]];
    }

    i64 ans = 0;
    for(i32 i = 0; i < route_id; ++i) {
        ans += black[i] * white[i];
    }

    cout << ans << '\n';

    // printf("ExecutionTime: %d /ms\n",1000*(int)((clock()-START_TIME)/CLOCKS_PER_SEC));
}

