                syori(j, i);
                int b = 0, w = 0;
                while(!q.empty()){
                    pair<int,int> a = q.front();
                    q.pop();
                    if(field[a.first][a.second] == '$'){
                        b++;
                        field[a.first][a.second] = '0';
                        if(field[a.first - 1][a.second] == '.')syori(a.first - 1, a.second);
                        if(field[a.first + 1][a.second] == '.')syori(a.first + 1, a.second);
                        if(field[a.first][a.second - 1] == '.')syori(a.first, a.second - 1);
                        if(field[a.first][a.second + 1] == '.')syori(a.first, a.second + 1);
