const int dx[9] = { 0, 1,  0, -1, 1,  1, -1, -1, 0};
const int dy[9] = { 1, 0, -1,  0, 1, -1, -1,  1, 0};
//--------------------------------------//
struct P{int x,y;};
int H, W;
bool S[400][400];
bool d[400][400];

bool check(int y, int x){
	return y>=0 and y<H and x>=0 and x<W;
}
ll bfs(int x, int y){
	ll bc = 1, wc = 0;
	queue<P> q;
	q.push(P{x,y});
	d[y][x] = true;
	while(!q.empty()){
		P p = q.front(); q.pop();
		rep(i, 4){
			int nx = p.x + dx[i], ny = p.y + dy[i];
			if(check(ny, nx) and S[ny][nx]!=S[p.y][p.x] and !d[ny][nx]){
				d[ny][nx]=true;
				if(S[ny][nx])
					bc++;
				else
					wc++;
				q.push(P{nx,ny});
			}
		}
	}
	return bc * wc;
}
void solve(){
	ll ans = 0;
	rep(i, H){
		rep(j, W){
			if(S[i][j] && !d[i][j]){
				ans += bfs(j, i);
			}
		}
	}
	cout<<ans<<endl;
}

