class UnionFind {
	vector<int>parent;
	vector<int>rank;
public:
	UnionFind(int num) {
		num++;
		parent.resize(num);
		rank.resize(num);
		for (int i = 0; i < num; i++) {
			parent[i] = i;
			rank[i] = 0;
		}
	}
	int Find(int node) {
		if (parent[node] == node)return node;
		else return parent[node] = Find(parent[node]);
	}
	void Unite(int u, int v) {
		u = Find(u);
		v = Find(v);
		if (u == v)return;
		if (rank[u] < rank[v])parent[u] = v;
		else {
			parent[v] = u;
			if (rank[u] == rank[v])rank[u]++;
		}
	}
	bool Check_Same(int u, int v) {
		return Find(u) == Find(v);
	}
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> H >> W;
	vector<string>s(H);
	for (auto &i : s)cin >> i;
	UnionFind uf(H*W);
	int dir[] = { 1,0,-1,0,1 };
	vector<set<long long int>>vs(H*W);
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (s[i][j] == '#')continue;
			for (int k = 0; k < 4; k++) {
				if (i + dir[k] < 0 || i + dir[k] >= H || j + dir[k + 1] < 0 || j + dir[k + 1] >= W)continue;
				for (int l = 0; l < 4; l++) {
					if (i + dir[l] < 0 || i + dir[l] >= H || j + dir[l + 1] < 0 || j + dir[l + 1] >= W)continue;
					if (s[i + dir[k]][j + dir[k + 1]] != '#' || s[i + dir[l]][j + dir[l + 1]] != '#')continue;
					uf.Unite((i + dir[k])*W + j + dir[k + 1], (i + dir[l])*W + j + dir[l + 1]);
				}
			}
		}
	}
	vector<long long int>num(H*W);
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (s[i][j] != '#')continue;
			num[uf.Find(i*W + j)]++;
			for (int k = 0; k < 4; k++) {
				if (i + dir[k] < 0 || i + dir[k] >= H || j + dir[k + 1] < 0 || j + dir[k + 1] >= W)continue;
				if (s[i + dir[k]][j + dir[k + 1]] == '#')continue;
				vs[uf.Find(i*W + j)].insert((i + dir[k])*W + j + dir[k + 1]);
			}
		}
	}
	long long int ans = 0;
	for (int i = 0; i < H*W; i++) {
		ans += num[i] * vs[i].size();
	}
	cout << ans << endl;
	return 0;
}

