  int black = (S[y][x] == '#') ? 1 : 0;
  int white = (S[y][x] == '.') ? 1 : 0;
  rep(i, 4) {
    int ny = y + dirs[i].first;
    int nx = x + dirs[i].second;
    if (ny < 0 || nx < 0 || H <= ny || W <= nx) continue;
    if (S[y][x] == S[ny][nx] || visit[ny][nx]) continue;
    visit[ny][nx] = true;
    int b, w;
    tie(b, w) = dfs(ny, nx, visit);
    black += b;
    white += w;
  }
  return make_pair(black, white);
}

int main(void) {
  ios::sync_with_stdio(false);
  cin >> H >> W;
  S.resize(H);
  rep(i, H) cin >> S[i];

  vector<vector<bool>> visit(H, vector<bool>(W, false));
  int64_t answer = 0;
  rep(i, H) {
    rep(j, W) {
      if (S[i][j] == '#' && !visit[i][j]) {
        visit[i][j] = true;
        int b, w;
        tie(b, w) = dfs(i, j, visit);
        answer += (int64_t)b * (int64_t)w;
      }
    }
  }
  cout << answer << endl;
  return 0;
}

