struct UF {
	vector<int> black, white, par;
	UF(int sz) : black(sz), white(sz), par(sz) {
		rep(i, sz) par[i] = i;
	}
	int parent(int i) {
		if (par[i] == i) return i;
		return par[i] = parent(par[i]);
	}
	void uni(int i, int j) {
		int pi = parent(i), pj = parent(j);
		if (pi == pj) return;
		black[pj] += black[pi];
		white[pj] += white[pi];
		par[pi] = pj;
	}
};

int main() {
	int H, W; cin >> H >> W;
	vector<vector<char>> S(H);
	UF uf = UF(H * W);
	auto idx = [W](int i, int j) {
		return i * W + j;
	};
	rep(i, H) {
		S[i].resize(W);
		rep(j, W) {
			cin >> S[i][j];
			if (S[i][j] == '#') uf.black[idx(i, j)] = 1;
			else uf.white[idx(i, j)] = 1;
		}
	}
	rep (i, H) {
		rep (j, W) {
			char c = S[i][j];
			int index = idx(i, j);
			if (0 <= i - 1 && c != S[i - 1][j]) uf.uni(index, idx(i - 1, j));
			if (0 <= j - 1 && c != S[i][j - 1]) uf.uni(index, idx(i, j - 1));
		}
	}
	uint64_t ans = 0;
	rep (i, H * W) if (uf.par[i] == i) ans += (uint64_t)uf.black[i] * uf.white[i];
	cout << ans << endl;
}

