	visit[cnt][i][j] = 1;

	char ptn = '.';
	int add = 1;
	if( flag % 2 ) {
		ptn = '#';
		add = 0;
	}

	long long res = 0;
	for( int k = 0; k < 4; k++ ) {
		int ni = i + diri[k];
		int nj = j + dirj[k];
		if( ni < 0 || H - 1 < ni || nj < 0 || W - 1 < nj ) {
			continue;
		}
		if( S[ni][nj] == ptn ) {
			long long ret = dfs( ni, nj, 1 - flag, cnt );
			if( ret >= 0 ) {
				res += ret + add;
			}
		}
	}

	return res;
}

int main() {
	cin >> H >> W;
	for( int i = 0; i < H; i++ ) {
		cin >> S[i];
	}

	long long ans = 0;
	int cnt = 0;
	for( int i = 0; i < H; i++ ) {
		for( int j = 0; j < W; j++ ) {
			if( S[i][j] == '#' ) {
				ans += dfs( i, j, 0, cnt );
				cnt++;
				if( cnt >= MAX ) {
					cnt = 0;
					memset( visit, 0, sizeof(visit) );
				}
			}
		}
	}

	cout << ans << endl;

	return 0;
}

