char s[401][401];
bool Arrive[401][401];

inline void BFS(int x, int y) {
	if(Arrive[x][y]) return ;
	queue<int>X, Y;
	long long B = 0, W = 0;
	X.push(x), Y.push(y);
	Arrive[x][y] = 1;
	while(!X.empty()) {
		int x = X.front(); X.pop();
		int y = Y.front(); Y.pop();
		if(s[x][y] == '.') B++;
		else W++;
		for(int i = -1; i <= 1; i++)
			for(int j = -1; j <= 1; j++)
				if(abs(i) + abs(j) == 1) {
					int tx = x + i;
					int ty = y + j;
					if(tx < 0 || ty < 0 || tx == n || ty == m) continue;
