int result = 0;

inline void countWhite(int startI, int startJ) {
    // DEBUG(startI);
    // DEBUG(startJ);
    bool isNextWhite = true;
    set<P> reachedC;
    reachedC.insert(make_pair(startI, startJ));
    queue<P> currentC;
    queue<P> nextC;
    currentC.push(make_pair(startI, startJ));

    while (!currentC.empty()) {
        P ci = currentC.front();
        currentC.pop();
        int i = ci._1;
        int j = ci._2;
        // DEBUG("---");
        // DEBUG(i);
        // DEBUG(j);
        // DEBUG(result);

        if (i - 1 >= 0) { // 上
            char nextColor = grid[i - 1][j];
            // DEBUG(nextColor);
            P nextCi = make_pair(i - 1, j);
            if (reachedC.count(nextCi) == 0 && (
                (isNextWhite && nextColor == '.') ||
                (!isNextWhite && nextColor == '#'))) {
                nextC.push(nextCi);
                reachedC.insert(nextCi);
                // DEBUG("上");
                if (isNextWhite) result++;
            }
        } 
        if (j - 1 >= 0) { // 左
            char nextColor = grid[i][j - 1];
            // DEBUG(nextColor);
            P nextCi = make_pair(i, j - 1);
            if (reachedC.count(nextCi) == 0 && (
                (isNextWhite && nextColor == '.') ||
                (!isNextWhite && nextColor == '#'))) {
                nextC.push(nextCi); 
                reachedC.insert(nextCi);
                // DEBUG("左");
                if (isNextWhite) result++;
            }
        } 
        if (i + 1 < H) { // 下
            char nextColor = grid[i + 1][j];
            // DEBUG(nextColor);
            P nextCi = make_pair(i + 1, j);
            if (reachedC.count(nextCi) == 0 && (
                (isNextWhite && nextColor == '.') ||
                (!isNextWhite && nextColor == '#'))) {
                nextC.push(nextCi); 
                reachedC.insert(nextCi);
                // DEBUG("下");
                if (isNextWhite) result++;
            }
        }
        if (j + 1 < W) { // 右
            char nextColor = grid[i][j + 1];
            // DEBUG(nextColor);
            P nextCi = make_pair(i, j + 1);
            if (reachedC.count(nextCi) == 0 && (
                (isNextWhite && nextColor == '.') ||
                (!isNextWhite && nextColor == '#'))) {
                nextC.push(nextCi); 
                reachedC.insert(nextCi);
                // DEBUG("右");
                if (isNextWhite) result++;
            }
        }

        if(currentC.empty()) {
            currentC = nextC; // 空になったら次の世代を代入
            queue<P> newNextC;
            nextC = newNextC;
            if (isNextWhite) { // 次の世代は白黒反転
                isNextWhite = false;
            } else {
                isNextWhite = true;
            }
        }
    }
}

int main() {
    cin >> H >> W;

    rep(i, H) {
        string si;
        cin >> si;
        grid.pb(si);
    }

    rep(i, H) {
        rep(j, W) {
            char ci = grid[i][j];
            if(ci == '#') { // 黒ならカウント
                countWhite(i ,j); // 幅優先で一つ一つチェック
            }
        }
    }

    cout << result << endl;
}

