struct Section	//每个区域为一个范围
{
	int id;	//编号
	long long numOfBlack;	//黑色块
	long long numOfWhite;	//白色块 
};
Section sections[160100];
int szSections;

struct Point
{
	int r, c;
};

int dr[4] = {-1, 1, 0, 0};
int dc[4] = { 0, 0,-1, 1};

void floodfill(int startR, int startC, int sectionFlag)
{
	sections[sectionFlag].id = sectionFlag;
	sections[sectionFlag].numOfBlack = 0;
	sections[sectionFlag].numOfWhite = 0;

	Point newPoint, curPoint;
	std::queue<Point> q;
	curPoint.r = startR;
	curPoint.c = startC;
	belongsTo[curPoint.r][curPoint.c] = sectionFlag;
	q.push(curPoint);

	while (!q.empty())
	{
		curPoint = q.front();
		q.pop();

		for (int d = 0 ; d < 4 ; d++)
		{
			newPoint.r = curPoint.r + dr[d];
			newPoint.c = curPoint.c + dc[d];

			if (0 <= newPoint.r && newPoint.r < h &&
			    0 <= newPoint.c && newPoint.c < w)	//范围内 
			{
