class UnionFind{
private:
    int n;
    vector<int> parent, r;

    int _find(int x){
        if(parent[x] == x) return x;
        else return parent[x] = _find(parent[x]);
    }

    void _unite(int x, int y){
        x = _find(x); y = _find(y);
        if(x == y) return;
        if(r[x]<r[y]) parent[x] = y;
        else{
            parent[y] = x;
            if(r[x] == r[y]) r[x]++;
        }
    }

public:
    int find(int x){
        return _find(x);
    }

    void unite(int x, int y){
        return _unite(x, y);
    }

    int operator[](int i){
        return find(i);
    }

    UnionFind(){}

    UnionFind(size_t _n) : n(_n){
        parent = vector<int>(n);
        r = vector<int>(n);
        for(int i=0;i<n;i++){
            parent[i] = i;
            r[i] = 0;
        }
    }
};


class CAlternatingPath {
public:
    int H, W;
    vcc grid;

    void input(std::istream& in, std::ostream& out){
        ios_base::sync_with_stdio(false);
        in>>H>>W;
        grid = vcc(H, vc(W));
        REP(i, H) REP(j, W) in>>grid[i][j];
    }

    void solve(std::istream& in, std::ostream& out){
        input(in, out);
        vi di = {1, 0, -1, 0}, dj = {0, 1, 0, -1};
        UnionFind uf(H*W);
        REP(i, H) REP(j, W){
            for(int k=0;k<4;k++){
                int ni = i + di[k], nj = j + dj[k];
                if(0<=ni and ni<H and 0<=nj and nj<W and grid[i][j]!=grid[ni][nj]){
                    uf.unite(i*W+j, ni*W+nj);
                }
            }
        }

        lint ans = 0;
        vl b(H*W, 0), w(H*W, 0);
        REP(i, H) REP(j, W){
            if(grid[i][j]=='.') w[uf.find(i*W+j)]++;
            else b[uf.find(i*W+j)]++;
        }

        REP(i, H*W) ans += w[i] * b[i];
        out<<ans<<'\n';
    }
};


int main() {
	CAlternatingPath solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

