#include<bits/stdc++.h>

using namespace std;

const int N = 405;
const int dx[] = {0, 1, 0, -1};
const int dy[] = {1, 0, -1, 0};

struct Data {
  int h, d;
  Data() {}
  Data(int x, int y) : d(x), h(y) {}
};

char grd[N][N]; int ans;
int row, col, visit[N][N], dot[N][N], hsh[N][N];

bool boundary(int i, int j) {
  return (i >= 0 && i < row) && (j >= 0 && j < col);
}

Data dfs(int i, int j) {
  visit[i][j] = 1;
  int d = 0, h = 0;
  for (int k = 0; k < 4; k++) {
    int x = dx[k] + i;
    int y = dy[k] + j;
    if (!boundary(x, y)) continue;
    if (visit[x][y] == 0 && grd[x][y] != grd[i][j]) {
      Data cur = dfs(x, y);
      if (grd[i][j] == '.') ans += cur.h;
      else ans += cur.d;
      h += cur.h;
      d += cur.d;
    } else if (visit[x][y] == 1 && grd[x][y] != grd[i][j]) {
      if (grd[i][x] == '.') ans += hsh[x][y];
      else ans += dot[x][y];
      h += hsh[x][y];
      d += dot[x][y];
    }
  }
  dot[i][j] = d;
  hsh[i][j] = h;
  return grd[i][j] == '.' ? Data(d + 1, h) : Data(d, h + 1);
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  cin >> row >> col;
  for (int i = 0; i < row; i++) {
    for (int j = 0; j < col; j++) {
      cin >> grd[i][j];
    }
  }
  for (int i = 0; i < row; i++) {
    for (int j = 0; j < col; j++) {
      if (visit[i][j] == 0) {
        Data cur = dfs(i, j);
      }
    }
  }
  cout << ans << endl;
  return 0;
}

