	pair<int, int> pos = { x,y };
	que.push(pos);
	int w = 0, b = 0;
	if (maze[x][y] == '.')w++;
	else b++;
	while (!que.empty()) {
		pair<int, int> Pa = que.front();
		que.pop();
		int X = Pa.first;
