using pa = pair<int, int>;
int H, W;
pa dfs(vector<pa>& n,vector<vector<int>>& f, vector<string>& s, int i, int j) {
	int sha = 0;
	int dot = 0;

	if (s[i][j] == '.') { dot++; }
	else { sha++; }

	if (i!=H-1 && f[i + 1][j] == 0) {
		if (s[i][j] != s[i + 1][j]) {
			f[i + 1][j] = 1;
			pa kari = dfs(n, f, s, i+1, j);
			sha += kari.first;
			dot += kari.second;
		}
	}
	if (j!=W-1 && f[i][j+1] == 0) {
		if (s[i][j] != s[i][j+1]) {
			f[i][j+1] = 1;
			pa kari = dfs(n, f, s, i, j+1);
			sha += kari.first;
			dot += kari.second;
		}
	}
	if (i!=0 && f[i-1][j] == 0) {
		if (s[i][j] != s[i-1][j]) {
			f[i-1][j] = 1;
			pa kari = dfs(n, f, s, i-1, j);
			sha += kari.first;
			dot += kari.second;
		}
	}
	if (j!=0 && f[i][j-1] == 0) {
		if (s[i][j] != s[i][j-1]) {
			f[i][j-1] = 1;
			pa kari = dfs(n, f, s, i, j-1);
			sha += kari.first;
			dot += kari.second;
		}
	}
	return pa(sha, dot);
}

