		for (int j = 0; j < W; j++) {

			if (flag[i][j] == 0) {
				flag[i][j] = 1;
				pa kari = dfs(ness, flag, S, i, j);
				ans += (ll)kari.first*kari.second;
			}
			else { continue; }
		}
	}

	cout << ans;
	return 0;
}

