	int dj[2] = {0, 1};
	for(int i = 0; i < h; i++){
		for(int j = 0; j < w; j++){
			for(int k = 0; k < 2; k++){
				int ni = i + di[k];
				int nj = j + dj[k];
				if(ni >= h || nj >= w) continue;
				if(s[i][j] != s[ni][nj]){
					uf.update(i * w + j, ni * w + nj);
				}
			}
		}
	}

	for(int i = 0; i < h; i++){
		for(int j = 0; j < w; j++){
			if(s[i][j] == '.') uf.addBlack(i * w + j);
			else uf.addWhite(i * w + j);
		}
	}

