struct UnionFind {
  vector<ll> parents;

  UnionFind(ll n) : parents(vector<ll>(n, -1)) {}

  ll root(ll a) {
    if (parents[a] < 0) {
      return a;
    }

    auto r = root(parents[a]);
    parents[a] = r;
    return r;
  }

  bool same(ll a, ll b) { return root(a) == root(b); }

  void merge(ll a, ll b) {
    ll ar = root(a);
    ll br = root(b);

    if (ar == br) {
      return;
    }

    // make less index one as a root
    if (ar > br) {
      swap(ar, br);
    }

    parents[ar] += parents[br];
    parents[br] = ar;
  }

  ll size(ll a) { return -parents[a]; }

  ll group_count() {
    ll res = 0;

    for (auto s : parents) {
      if (s < 0) {
        res++;
      }
    }

    return res;
  }
};

void solve() {
  ll H, W;
  cin >> H >> W;

  V<string> mat(H);
  rep(h, H) cin >> mat[h];

  ll N = H * W;
  VVL edge_list(N, VL(0));

  rep(h, H) rep(w, W) {
    ll u = h * W + w;

    rep(di, 4) {
      ll nh = h + dy[di];
      ll nw = w + dx[di];

      unless(0 <= nh && nh < H && 0 <= nw && nw < W) continue;
      unless(mat[h][w] != mat[nh][nw]) continue;

      ll v = nh * W + nw;

      edge_list[u].emplace_back(v);
      edge_list[v].emplace_back(u);
    }
  }

  UnionFind uf(N);

  rep(u, N) {
    for (auto v : edge_list[u]) {
      uf.merge(u, v);
    }
  }

  auto id_to_char = [&](ll id) {
    ll h = id / W;
    ll w = id % W;
    return mat[h][w];
  };

  map<ll, ll> b_ct_map;
  map<ll, ll> w_ct_map;

  rep(i, N) {
    ll r = uf.root(i);
    ll c = id_to_char(i);

    if (c == '#') {
      b_ct_map[r]++;
    } else {
      w_ct_map[r]++;
    }
  }

  ll res = 0;

  for (auto b_pair : b_ct_map) {
    ll r = b_pair.fi;
    ll b_ct = b_pair.se;
    ll w_ct = w_ct_map[r];

    res += b_ct * w_ct;
  }

  cout << res << endl;
}

