queue<pair<int, int>> q;
void go(int x1, int y1, int x2, int y2) {
	char a = grid[x1][y1], b = grid[x2][y2];
	if(!vis[x2][y2] && (a == '.' && b == '#' || a == '#' && b == '.')) {
		vis[x2][y2] = true;
		q.push(mp(x2, y2));
	}
}

int main() {
	int H, W;
