	for(int i = 0; i < H; i++) {
		for(int j = 0; j < W; j++) {
			if(grid[i][j]) {
				q.push(mp(i, j));
				vis[i][j] = true;
				int b = 0, w = 0;
				do {
					pair<int, int> xy = q.front();
					q.pop();
					int x = xy.first, y = xy.second;
					if(grid[x][y] == '.')
						b++;
					else
						w++;
					if(x + 1 < H)
						go(x, y, x + 1, y);
					if(x > 0)
						go(x, y, x - 1, y);
					if(y + 1 < W)
						go(x, y, x, y + 1);
					if(y > 0)
						go(x, y, x, y - 1);
				} while(!q.empty());
				ans += b * w;
			}
		}
