		if(s[i][j]=='.'){
			c1[uf.find(i*w+j)]++;
		}
		else{
			c2[uf.find(i*w+j)]++;
		}
	}
	ll ans=0;
	rep(i,h)rep(j,w){
		ans+=c1[i*w+j]*c2[i*w+j];
	}
	cout<<ans<<endl;
}

