vector<int> movew = {0, 1, 0, -1};
v3 bord(0, vector<char>(0));
v2 group(0, vector<int>(0));
void check(int h, int w, bool color, int gr){
	bord[h][w] = '+';
	group[h][w] = gr;
	rep(i, 4){
		int nh = h + moveh[i];
		int nw = w + movew[i];
		bool ncolor = !color;
		if(nh < 0 || nw <0 || nh >= H || nw >= W) continue;
		if(bord[nh][nw] == '+') continue;
		if(color){
			if(bord[nh][nw] == '#') continue;
		}else{
			if(bord[nh][nw] == '.') continue;
		}
		check(nh, nw,  ncolor, gr);
	}
}


