static void AIsing2019C()
{
	int H, W;
	getint(H, W);

	std::vector<std::string> grid(H);
	for (int i = 0; i < H; i++) {
		std::cin >> grid[i];
	}
	std::vector<std::vector<int>> flag(H, std::vector<int>(W, 0));
	std::vector<std::pair<int, int>> pairs;

	int dh[] = { 1, -1, 0, 0 };
	int dw[] = { 0, 0, -1, 1 };
	for (int h = 0; h < H; h++) {
		for (int w = 0; w < W; w++) {
			if ((grid[h][w] == '#') && (flag[h][w] == 0)) {
				std::pair<int, int> bwPair(0, 0);

				std::queue<std::pair<int, int>> que;
				que.push(std::pair<int, int>(h, w));

				flag[h][w] = 1;
				bwPair.first++;

				while (!que.empty()) {
					bool nowBlack = false;
					std::pair<int, int> pos = que.front(); que.pop();

					if (grid[pos.first][pos.second] == '#') {
						nowBlack = true;
					}

					for (int i = 0; i < 4; i++) {
						int nh = pos.first + dh[i];
						int nw = pos.second + dw[i];

						if ((nh >= 0) && (nw >= 0) && (nh < H) && (nw < W) && (flag[nh][nw] == 0)) {
							if ((nowBlack && (grid[nh][nw] != '#')) || (!nowBlack && (grid[nh][nw] == '#'))) {
								if (nowBlack) {
									bwPair.second++;
								}
								else {
									bwPair.first++;
								}
								flag[nh][nw] = 1;
								que.push(std::pair<int, int>(nh, nw));
							}
						}
					}
				}
				if (bwPair.second != 0) {
					pairs.push_back(bwPair);
				}
			}
		}
	}
	LLONG ans = 0;
	for (auto it = pairs.begin(); it != pairs.end(); it++) {
		ans += (LLONG)(it->first * it->second);
	}
	printf("%lld\n", ans);
}

