int H, W;
int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};
map<pair<int, int>, set<pair<int, int>>> Record;

void count(int h, int w, vector<string>& S, set<pair<int, int>>& SP) {
  auto op = make_pair(h, w);
  if (Record[op].size() != 0) {
    SP.insert(Record[op].begin(), Record[op].end());
    return;
  }
  char now = S[h][w];
  for (int i = 0; i < 4; i++) {
    int h2 = h + dy[i], w2 = w + dx[i];
    auto p = make_pair(h2, w2);
    if (h2 < 0 || h2 == H || w2 < 0 || w2 == W || S[h2][w2] == now || SP.count(p) != 0) continue;
    if (now == '#') {
      SP.insert(p);
    }
    count(h2, w2, S, SP);
  }
}

int main() {
  cin >> H >> W;
  vector<string> S(H);
  for (int i = 0; i < H; i++) {
    cin >> S[i];
  }
  long ans = 0;
  for (int h = 0; h < H; h++) {
    for (int w = 0; w < W; w++) {
      if (S[h][w] == '.') continue;
      set<pair<int, int>> SP;
      count(h, w, S, SP);
      ans += SP.size();
      Record[make_pair(h, w)] = SP;
    }
  }
  cout << ans << endl;
}

