bool vis[maxtot];

void addEdge(int a, int b) {
	g[a].push_back(b);
	g[b].push_back(a);
}

void bfs(int st, vector<long long> &count) {
	queue<int> qu;
	qu.push(st);
	vis[st] = true;
	++count[color[st]];

	while (!qu.empty()) {
		int cur = qu.front();
		qu.pop();

		for (int i = 0; i < g[cur].size(); ++i) {
			int v = g[cur][i];
			if (!vis[v]) {
				qu.push(v);
				vis[v] = true;
				++count[color[v]];
			}
		}
	}
}

