const int mod = (int)1e9 + 7, INF = (int)1e9;
const int di[4] = { 1,0,-1,0 }, dj[4] = { 0,1,0,-1 };


#define N 160005
class uf {
private:
    int par[N] = {}, r[N] = {}, size[N] = {};

public:
    uf(int n) {
        int i;
        for (i = 0; i < n; i++) {
            par[i] = i;
            size[i] = 1;
        }
    }

    int root(int a) {
        if (par[a] == a) return a;
        return par[a] = root(par[a]);
    }

    void unite(int a, int b) {
        a = root(a);
        b = root(b);
        if (a == b) return;
        if (r[a] > r[b]) {
            par[b] = a;
            r[a]++;
            size[a] += size[b];
        }
        else {
            par[a] = b;
            r[b]++;
            size[b] += size[a];
        }
    }

    int show_size(int a) {
        return size[root(a)];
    }

    int group(int n) {
        int i, t, res = 0;
        bool u[N] = { false };
        for (i = 0; i < n; i++) {
            t = root(i);
            if (!u[t]) {
                res++;
                u[t] = true;
            }
        }
        return res;
    }

    bool isroot(int a) {
        return par[a] == a;
    }

};

int main(void) {
    int h, w, i, j, bl[N] = {}, wh[N] = {}, dir, ni, nj, id, nid, rid, rnid;
    ll ans;
    string s[403];

    scanf("%d%d", &h, &w);
    for (i = 0; i < h; i++)
        cin >> s[i];

    for (i = 0; i < h; i++) for (j = 0; j < w; j++)
    {
        if (s[i][j] == '#')
            bl[i * w + j] = 1;
        else
            wh[i * w + j] = 1;
    }

    uf unfi(h * w + 3);
    for (i = 0; i < h; i++) for (j = 0; j < w; j++)
    {
        for (dir = 0; dir < 4; dir++)
        {
            ni = i + di[dir];
            nj = j + dj[dir];
            if (ni >= 0 && ni < h && nj >= 0 && nj < w && s[i][j] != s[ni][nj])
            {
                id = i * w + j;
                nid = ni * w + nj;
                if (unfi.root(id) != unfi.root(nid))
                {
                    rid = unfi.root(id);
                    rnid = unfi.root(nid);
                    unfi.unite(id, nid);
                    bl[rid] = bl[rnid] = bl[rid] + bl[rnid];
                    wh[rid] = wh[rnid] = wh[rid] + wh[rnid];
                }
            }
        }
    }

    ans = 0;
    for (id = 0; id < h * w; id++)
    {
        if (unfi.isroot(id))
            ans += (ll)bl[id] * wh[id];
    }

    printf("%lld\n", ans);

    return 0;
}

