int main() {
    ll h, w, ans = 0; cin >> h >> w;
    vector<string> s(h);
    rep(i, h) cin >> s[i];

    vector<vector<bool>> used(h, vector<bool>(w, false));

    rep(i, h) {
        rep(j, w) {
            // スタート地点
            if(s[i][j] == '.' && !used[i][j]) {
                ll wh = 0, bl = 0; // 白と黒
                wh++;
                queue<P> que;
                que.push(make_pair(i, j));
                used[i][j] = true;
                // 幅優先
                while(!que.empty()) {
                    P t = que.front();
                    que.pop();
                    ll x = t.first, y = t.second;
                    if(x > 0) if(!used[x-1][y] && s[x][y] != s[x-1][y]) {
                        used[x-1][y] = true;
                        que.push(make_pair(x-1, y));
                        if(s[x-1][y] == '.') wh++;
                        else bl++;
                    }
                    if(x < h-1) if(!used[x+1][y] && s[x][y] != s[x+1][y]) {
                        used[x+1][y] = true;
                        que.push(make_pair(x+1, y));
                        if(s[x+1][y] == '.') wh++;
                        else bl++;
                    }
                    if(y > 0) if(!used[x][y-1] && s[x][y] != s[x][y-1]) {
                        used[x][y-1] = true;
                        que.push(make_pair(x, y-1));
                        if(s[x][y-1] == '.') wh++;
                        else bl++;
                    }
                    if(y < w-1) if(!used[x][y+1] && s[x][y] != s[x][y+1]) {
                        used[x][y+1] = true;
                        que.push(make_pair(x, y+1));
                        if(s[x][y+1] == '.') wh++;
                        else bl++;
                    }
                }
                ans += bl*wh;
            }
        }
    }
    cout << ans << endl;

    return 0;
}

ll my_abs(ll a) {
    if(a >= 0) return a;
    else return -1 *a;
}

ll a_n(ll a, ll n) { 
    if(n == 0) return 1;

    ll ret = a, count = 1;
    while(count * 2 < n) {
        ret *= ret;
        count *= 2;
    }
    if(count == n) return ret;
    else return (ret * a_n(a, n-count));
}

ll my_gcd(ll a, ll b) {
    if(b == 0) return a;
    return my_gcd(b, a%b);
}

ll inv(ll a) {
    return a_n(a, MOD-2);
}

ll madd(ll a, ll b, ll c) {
    ll ret = (a+b) % MOD;
    return (ret+c) % MOD;
}

ll msub(ll a, ll b) {
    if(a < b) return (a-b+MOD) % MOD;
    else return (a-b) % MOD;
}

ll mtime(ll a, ll b, ll c) {
    ll ret = (a*b) % MOD;
    return (ret*c) % MOD;
}

#include <iostream>
#include <string>
#include <stack>
#include <utility>
#define MAX_H 400
#define MAX_W 400
using namespace std;

struct Point {
    int i, j;
    char prev_color;
};

bool used[MAX_H][MAX_W];

long calc(string s[], int h, int w, int i, int j) {
    long black = 0, white = 0;

    stack<Point> st;
    st.push(Point {i, j, ' '});
    while (!st.empty()) {
        Point p = st.top();
        st.pop();
        i = p.i;
        j = p.j;
        if (i < 0 || h <= i || j < 0 || w <= j || used[i][j] || p.prev_color == s[i][j])
            continue;
        used[i][j] = true;
        if (s[i][j] == '#')
            black++;
        else
            white++;
        st.push(Point {i - 1, j, s[i][j]});
        st.push(Point {i + 1, j, s[i][j]});
        st.push(Point {i, j - 1, s[i][j]});
        st.push(Point {i, j + 1, s[i][j]});
    }
    return black * white;
}

int main() {
    int h, w;
    cin >> h >> w;
    string s[h];
    for (int i = 0; i < h; i++) {
        cin >> s[i];
    }
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            used[i][j] = false;
        }
    }
    long ans = 0;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (used[i][j])
                continue;
            ans += calc(s, h, w, i, j);
        }
    }
    cout << ans << endl;
    return 0;
}

