ll ans;
char s[407][407];
int p[400007],cnt[400007],c_[400007];
int Hash(int x,int y){
    return x*400+y;
}
int Find(int x){
    return x == p[x]?x:p[x] = Find(p[x]);
}
void Merge(int x,int y){
    x = Find(x);
    y = Find(y);
    if(x!=y){
        p[x] = y;
        cnt[y] += cnt[x];
        c_[y] += c_[x];
    }
}
int main(){
    for(int i=0;i<400007;i++)
        p[i] = i,cnt[i] = 1;
    scanf("%d%d",&n,&m);
