            if(s[i][j] == '#')
                c_[Hash(i,j)] = 1;
    for(int i=1;i<=n;i++)
        for(int j=1;j<=m;j++)
            for(int k=0;k<4;k++){
                int x = i+direct[k][0];
                int y = j+direct[k][1];
                if(x>0&&x<=n&&y>0&&y<=m && s[i][j]!=s[x][y])
