                    if (field[i][j] != field[ni][nj]) {
                        int ij = conv(i, j);
                        int nij = conv(ni, nj);
                        if (!uf.same(ij, nij)) {
                            uf.unite(ij, nij);
                        }
                    }
                }

                if (j + 1 < W) {
                    int ni = i;
                    int nj = j + 1;

                    if (field[i][j] != field[ni][nj]) {
                        int ij = conv(i, j);
                        int nij = conv(ni, nj);
                        if (!uf.same(ij, nij)) {
                            uf.unite(ij, nij);
                        }
                    }
                }
            }
        }

        vector<int> G(H * W);
        vector<int> blackG(H * W);

        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j) {
                int gr = uf.find(conv(i, j));
                G[gr]++;
                if (field[i][j] == '#') {
                    blackG[gr]++;
                }
            }
        }

        ll ans = 0ll;

        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j) {
                if (field[i][j] == '#') {
//                    int add = G[uf.find(conv(i, j))] - 1;
                    int gr = uf.find(conv(i, j));
                    int add = G[gr] - blackG[gr];
                    ans += add;
                }
            }
        }

        cout << ans << endl;


    }
};


