const int UF_MAX = 401*401;

class UF{
	int x[UF_MAX];
	int co;

public:

	UF(){
		fill(x,x+UF_MAX,-1);
		co = 0;
	}

	int boss(int a){
		int s = a;
		while(x[s] > -1) s = x[s];
		if(s != a) x[a] = s;
		return s;
	}

	void uni(int a , int b){
		int s = boss(a);
		int t = boss(b);
		if(s != t){
			++co;
			if(x[s] < x[t]){
				x[s] += x[t];
				x[t] = s;
			} else {
				x[t] += x[s];
				x[s] = t;
			}
		}
	}

	bool find(int a , int b){
		return boss(a) == boss(b);
	}

	int count(){
		return co;
	}

	int member(int a){
		return -x[boss(a)];
	}
} uf;


int main(){
	int H,W; cin >> H >> W;
	vector<string> S(H);
	repp(i,0,H) cin >> S[i];
	repp(i,0,H) repp(j,1,W) if(S[i][j-1] != S[i][j]) uf.uni(i*W+j-1,i*W+j);
	repp(i,1,H) repp(j,0,W) if(S[i-1][j] != S[i][j]) uf.uni((i-1)*W+j,i*W+j);
	vector<int> c(H*W,0);
	repp(i,0,H) repp(j,0,W) if(S[i][j] == '#') ++c[uf.boss(i*W+j)];
	LL ans = 0;
	repp(i,0,H) repp(j,0,W) if(i*W+j == uf.boss(i*W+j)) ans += c[i*W+j]*(uf.member(i*W+j)-c[i*W+j]);
	cout << ans << endl;
	return 0;
}

