using ll = long long;
const ll INF = (ll)1e18;

ll dy[4] = {  0,  0, -1, +1};
ll dx[4] = { -1, +1,  0,  0};

ll H, W, V;
typedef struct {
  ll from;
  ll to;
  ll cost;
} S_Edge;

template<typename Head> void print(Head head){ std::cout << head << std::endl; }
template<typename Head, typename... Tail> void print(Head head, Tail... tail) {
  std::cout << head << " ";
  print(tail...);
}

ll pos2idx(ll y, ll x) { return y * W + x; }
ll idx2y(ll idx) { return idx / W; }
ll idx2x(ll idx) { return idx % W; }

void make_map(std::vector< std::string >& grid, std::vector< std::vector<S_Edge> >& vedge)
{
  for (ll y = 0; y < H; y++) {
    for (ll x = 0; x < W; x++) {
      for (ll d = 0; d < 4; d++) {
	ll ny = y + dy[d];
	ll nx = x + dx[d];
	if (ny >= 0 && nx >= 0 && ny < H && nx < W) {
	  S_Edge edge;
	  edge.from = pos2idx(y, x);
	  edge.to   = pos2idx(ny, nx);
	  edge.cost = grid[y][x] == grid[ny][nx] ? INF : 1;
	  vedge[pos2idx(y, x)].push_back(edge);
	}
      }
    }
  }
}

ll count_paths_and_upload_visit(ll s, std::vector< std::string >& grid,
				std::vector< std::vector<S_Edge> >& vedge,
				std::vector< bool >& is_visited)
{
  ll cnt[2] = {0, 0};
  std::vector<ll> dist(V, INF);
  std::queue<ll> que;

  dist[s] = 0LL;
  que.push(s);
  is_visited[s] = true;
  cnt[0] += grid[idx2y(s)][idx2x(s)] == '#' ? 1 : 0;
  cnt[1] += grid[idx2y(s)][idx2x(s)] == '.' ? 1 : 0;

  while (!que.empty()){
    ll v = que.front(); que.pop();
    for (auto it = vedge[v].begin(); it != vedge[v].end(); it++) {
      if (dist[it->to] > dist[it->from] + it->cost) {
	dist[it->to] = dist[it->from] + it->cost;
	que.push(it->to);
	if (!is_visited[it->to]) {
	  is_visited[it->to] = true;
	  cnt[0] += grid[idx2y(it->to)][idx2x(it->to)] == '#' ? 1 : 0;
	  cnt[1] += grid[idx2y(it->to)][idx2x(it->to)] == '.' ? 1 : 0;
	}
      }
    }
  }

  return cnt[0] * cnt[1];
}

int main()
{
  std::cin >> H >> W;
  V = H * W;

  std::vector< std::string > grid(H, std::string(W, 'X'));
  for (ll y = 0; y < H; y++) {
    std::cin >> grid[y];
  }

  std::vector< std::vector<S_Edge> > vedge(V);
  make_map(grid, vedge);

  std::vector< bool > is_visited(V);

  ll ans = 0;
  for (ll y = 0; y < H; y++) {
    for (ll x = 0; x < W; x++) {
      if (grid[y][x] == '.') continue;
      if (is_visited[pos2idx(y,x)]) continue;
      ans += count_paths_and_upload_visit(pos2idx(y,x), grid, vedge, is_visited);
    }
  }

  print(ans);
  return 0;
}

