int judge(int i, int j, int h, int w){
    int b = 0, W = 0;
    queue<int> qx, qy;
    int dy[4] = {0, 0, 1, -1};
    int dx[4] = {1, -1, 0, 0};
    qy.push(i);
    qx.push(j);
    finished[i][j] = true;
    while(!qx.empty()){
        int y = qy.front(), x = qx.front();
        if(s[y][x]) W++;
        else b++;
        rep(k, 4){
            int ny = y + dy[k], nx = x + dx[k];
            if(ny < 0 || h <= ny || nx < 0 || w <= nx) continue;
            if(finished[ny][nx]) continue;
            if(s[y][x] != s[ny][nx]){
                finished[ny][nx] = true;
                qy.push(ny);
                qx.push(nx);
            }
        }
        qy.pop();
        qx.pop();
    }
    return b * W;
}

