int main() {
	cin >> h >> w;
	ll s[h+2][w+2];
	ll p[h+2][w+2];//1 : 0
	for(ll i = 1; i <= h; i++){
		cin  >> str;
		for(ll j = 1; j <= w; j++){
			s[i][j] = (str[j-1] == '.')? 0 : 1;
			p[i][j] = 0;
		}
		s[i][0] = -1; s[i][w+1] = -1;
		p[i][0] = -1; p[i][w+1] = -1;
	}//init
	for(ll j = 1; j <= w; j++){
		s[0][j] = -1; s[h+1][j] = -1;
		p[0][j] = -1; p[h+1][j] = -1;
	}

	ll r = 0;
	queue<ll> quex;
	queue<ll> quey;
	bool flag = true;
	while(flag){
		bool nopush = true;
		for(ll i = 1; nopush && i <= h; i++){
			for(ll j = 1; nopush && j <= w; j++){
				if(nopush && s[i][j] != -1){
					quex.push(i);
					quey.push(j);
					p[i][j] = 1;
					nopush = false;
				}	
			}
		}
		flag = !nopush;
		ll countw = 0;
		ll countb = 0;
		while(!quex.empty()){
			ll x = quex.front(); quex.pop();
			ll y = quey.front(); quey.pop();
			if(s[x][y] != -1){
				if(p[x][y-1] == 0 && s[x][y] + s[x][y-1] == 1){quex.push(x); quey.push(y-1); p[x][y-1] = 1;}
				if(p[x][y+1] == 0 && s[x][y] + s[x][y+1] == 1){quex.push(x); quey.push(y+1); p[x][y+1] = 1;}
				if(p[x-1][y] == 0 && s[x][y] + s[x-1][y] == 1){quex.push(x-1); quey.push(y); p[x-1][y] = 1;}
				if(p[x+1][y] == 0 && s[x][y] + s[x+1][y] == 1){quex.push(x+1); quey.push(y); p[x+1][y] = 1;}
				if(s[x][y] == 0){countw++;}
				if(s[x][y] == 1){countb++;}
				s[x][y] = -1;
			}
		}
		r += countw*countb;
	}

	cout << r;	
	return 0;
}

