int main(){
    int H,W; cin>>H>>W;
    string board[H]; CINA(board,H);

    bool done[H][W][H][W];
    REP(i,H){
        REP(j,W){
            REP(k,H){
                REP(l,W){
                    done[i][j][k][l] = false;
                }
            }
        }
    }

    int ans = 0;

    REP(i,H){
        REP(j,W){
            // cout << i << j << "\n";
