                int cur_i = q.front().first;
                int cur_j = q.front().second;
                // cout << "-" << cur_i << cur_j << "\n";
                q.pop();

                for(pii p:{ MP(cur_i,cur_j-1),MP(cur_i,cur_j+1),MP(cur_i-1,cur_j),MP(cur_i+1,cur_j)  }){
