int a[401][401];
int H,W;
queue<pair<int,int> > q;
int used[401][401];
int dx[4]={1,-1,0,0};
int dy[4]={0,0,1,-1};

bool isin_(int i, int j){
    return i >= 0 && i < H && j >= 0 && j < W;
}

bool check_(int i, int j, int d){
    int ni = i + dx[d];
    int nj = j + dy[d];
    if(!isin_(ni, nj)) return false;
    if(a[i][j] == a[ni][nj]) return false;
    return true;
}

int solve() {
    ll ans = 0,b=0,w=0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (used[i][j]) continue;
            b = 0, w = 0;//b-black w-WHite
            used[i][j] = 1;
            q.push({i, j});
            while (!q.empty()) {
                pair<int, int> r = q.front();
                q.pop();
                int x = r.first;
                int y = r.second;
                if (a[x][y]) b++;
                else w++;
                for (int d = 0; d < 4; d++) {
                    if (!check_(x, y, d)) continue;//invalid move
                    if (used[x + dx[d]][y + dy[d]]) continue;
                    used[x + dx[d]][y + dy[d]] = 1;
                    q.push({x + dx[d], y + dy[d]});
                }
            }
            ans += b * w;
        }
    }
    return ans;
}

int run() {
    cin>>H>>W;
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            char cH;
            cin>>cH;
            a[i][j]=(cH=='#');
        }
    }
    memset(used,0,sizeof(used));
    ll ans=solve();
    cout<<ans;
}

#include <bits/stdc++.h>
using namespace std;

int vis[405][405];
char mat[405][405];

const int dx[] = {1, -1, 0, 0};
const int dy[] = {0, 0, 1, -1};

int main() {
  ios::sync_with_stdio(0), cin.tie(0);
  int n, m;
  cin >> n >> m;
  for (int i = 1; i <= n; ++i) {
    cin >> (mat[i] + 1);
  }
  long long sol = 0;
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= m; ++j) {
      if (vis[i][j]) continue;
      int c1 = 0;
      int c2 = 0;
      queue<array<int, 2>> q;
      for (q.push({i, j}); q.size(); q.pop()) {
        int x = q.front()[0];
        int y = q.front()[1];
        if (vis[x][y]) continue;
        vis[x][y] = 1;
        c1 += mat[x][y] == '#';
        c2 += mat[x][y] == '.';
        for (int i = 0; i < 4; ++i) {
          if (mat[x + dx[i]][y + dy[i]]) {
            if (mat[x][y] != mat[x + dx[i]][y + dy[i]]) {
              q.push({x + dx[i], y + dy[i]});
            }
          }
        }
      }
      sol += 1LL * c1 * c2;
    }
  }
  cout << sol << '\n';
}

