#include <iostream>
#include <vector>
#include <map>
#include <stack>
#include <algorithm>
using namespace std;

int H, W;

int main() {
    cin >> H >> W;
    vector<string> S(H);
    for (int i = 0; i < H; i++) {
        cin >> S[i];
    }
    vector<vector<int>> group(H, vector<int>(W));
    int g = 0;
    map<int, pair<int, int>> count;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (group[i][j] > 0) continue;

            //未訪問の頂点からDFS
            g++;
            stack<pair<int, int>> stack;
            stack.push(make_pair(i, j));
            if (S[i][j] == '.') {
                count[group[i][j]].first++;
            } else if (S[i][j] == '#') {
                count[group[i][j]].second++;
            }
            group[i][j] = g;
            if (S[i][j] == '.') {
                count[g].first++;
            } else if (S[i][j] == '#') {
                count[g].second++;
            }
            while (!stack.empty()) {
                pair<int, int> p = stack.top(); stack.pop();
                if (p.first > 0 && group[p.first - 1][p.second] == 0 && S[p.first - 1][p.second] != S[p.first][p.second]) {
                    group[p.first - 1][p.second] = g;
                    stack.push(make_pair(p.first - 1, p.second));
                    if (S[p.first - 1][p.second] == '.') {
                        count[g].first++;
                    } else if (S[p.first - 1][p.second] == '#') {
                        count[g].second++;
                    }
                }
                if (p.second > 0  && group[p.first][p.second - 1] == 0 && S[p.first][p.second - 1] != S[p.first][p.second]) {
                    group[p.first][p.second - 1] = g;
                    stack.push(make_pair(p.first, p.second - 1));
                    if (S[p.first][p.second - 1] == '.') {
                        count[g].first++;
                    } else if (S[p.first][p.second - 1] == '#') {
                        count[g].second++;
                    }
                }
                if (p.first < H - 1 && group[p.first + 1][p.second] == 0 && S[p.first + 1][p.second] != S[p.first][p.second]) {
                    group[p.first + 1][p.second] = g;
                    stack.push(make_pair(p.first + 1, p.second));
                    if (S[p.first + 1][p.second] == '.') {
                        count[g].first++;
                    } else if (S[p.first + 1][p.second] == '#') {
                        count[g].second++;
                    }
                }
                if (p.second < W - 1 && group[p.first][p.second + 1] == 0 && S[p.first][p.second + 1] != S[p.first][p.second]) {
                    group[p.first][p.second + 1] = g;
                    stack.push(make_pair(p.first, p.second + 1));
                    if (S[p.first][p.second + 1] == '.') {
                        count[g].first++;
                    } else if (S[p.first][p.second + 1] == '#') {
                        count[g].second++;
                    }
                }
            }
        }
    }
    long long ans = 0;
    for (int i = 1; i <= g; i++) {
        ans += 1ll * count[i].first * count[i].second;
    }
    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;

#define loop(i, a, b) for (int i = (a); i < (b); i++)
const int MAX = 405;
char grid[MAX][MAX];
int  visited[MAX][MAX];
int h, w;

bool inside(int x, int y)
{
    return 0 <= x && x < h && 0 <= y && y < w;
}

bool check(int x, int y, int a, int b){
    if (!inside(x + a, y + b))
        return false;
    return grid[x][y] != grid[x + a][y + b] && !visited[x + a][y + b];
}

int main()
{
    cin >> h >> w;
    loop(i, 0, h) loop(j, 0, w)
    {
        cin >> grid[i][j];
    }
    long long ans = 0;
    loop(i, 0, h) loop(j, 0, w) {
        if (visited[i][j]) continue;
        queue<pair<int, int>> queue;
        queue.emplace(make_pair(i, j));
        visited[i][j] = 1;
        long long black = 0;
        long long white = 0;
        while(queue.size()){
            pair<int, int> p = queue.front();
            queue.pop();
            if (grid[p.first][p.second] == '#')
                black += 1;
            else 
                white += 1;
            for (int a: {-1, 0, 1}){
                for (int b: {-1, 0, 1}){
                    if(abs(a) == abs(b)) continue;
                    if(check(p.first, p.second, a, b)){
                        queue.emplace(make_pair(p.first + a, p.second + b));
                        visited[p.first + a][p.second + b] = 1;
                    }
                }
            }
        }
        ans += white * black;
    }
    cout << ans << "\n";
    return 0;
}

