long long vis[444][444];
long long cnt0, cnt1;
long long dy[4] = {1, -1, 0, 0};
long long dx[4] = {0, 0, 1, -1};
long long H, W;
vector<string> S;

void dfs(long long y, long long x){
    if(vis[y][x] != 0) return;
    if(S[y][x] == '.'){
        vis[y][x] = 1;
        cnt0++;
    }else{
        vis[y][x] = -1;
        cnt1++;
    }

    for(long long i=0; i<4; i++){
        long long y2 = y+dy[i];
        long long x2 = x+dx[i];
        if(y2 < 0 || H <= y2 || x2 < 0 || W <= x2) continue;
        if(S[y][x] == S[y2][x2]) continue;
        dfs(y2, x2);
    }
}

int main(){
    cin >> H >> W;
    S.resize(H);

    for(long long i=0; i<H; i++)
        cin >> S[i];

    vector<pair<long long, long long>> v;
    for(long long i=0; i<H; i++){
        for(long long j=0; j<W; j++){
            cnt0 = 0;
            cnt1 = 0;
            if(vis[i][j] != 0) continue;
            dfs(i, j);
            v.push_back(make_pair(cnt0, cnt1));
        }
    }
    long long ans = 0;
    for(auto x : v){
        long long a = x.first;
        long long b = x.second;
        ans += a*b;
    }

    cout << ans << endl;
    return 0;
}

