        for(int j = 0; j < w; ++j){
            if(used[i][j])  continue;

            queue<P> que;
            que.push(P(i, j));
            int bcnt = 0, wcnt = 0;

            while(!que.empty()){
                P p = que.front();
                que.pop();
                int x = p.first, y = p.second;
                if(used[x][y])  continue;
                used[x][y] = true;
                bcnt += a[x][y] == 1;
                wcnt += a[x][y] == 0;

