                    int nx = x + dx[k], ny = y + dy[k];
                    if(nx < 0 || nx >= h || ny < 0 || ny >= w)  continue;
                    if(used[nx][ny])    continue;
                    if(a[x][y] == a[nx][ny])    continue;

                    que.push(P(nx, ny));
                }
            }

            ans += (ll)bcnt * wcnt;
        }
    }

    cout << ans << endl;
