#define MAX 410
int H,W;
string s[MAX];
int par[MAX*MAX];

int find(int x) {
  if( x == par[x] ) return x;
  return par[x] = find(par[x]);
}

void unite(int x,int y) {
  x = find(x), y = find(y);
  if( x != y ) par[x] = y;
}

bool used[MAX][MAX];
int d[] = {0,1,0,-1};

void dfs(int x,int y) {
  int col = ( s[y][x] == '.' );
  rep(i,4) {
    int nx = x + d[i], ny = y + d[(i+1)%4];
    if( !( 0 <= nx && nx < W && 0 <= ny && ny < H ) ) continue;
    int ncol = ( s[ny][nx] == '.' );
    if( col == ncol ) continue;
    unite(x+y*W,nx+ny*W);
    if( used[ny][nx] ) continue;
    used[ny][nx] = true;
    dfs(nx,ny);
  }
}

const bool debug = 0;

void compute() {
  rep(i,(H*W)) par[i] = i;
  rep(i,H) {
    rep(j,W) {
      if( !used[i][j] ) {
	used[i][j] = true;
	dfs(j,i);
      }
    }
  }
  if( debug ) {
    rep(i,H) {
      rep(j,W) {
	cout << find(j+i*W) << " ";
      } puts("");
    }puts("");
  }
  map<int,int> mp[2];
  rep(i,H) {
    rep(j,W) {
      int col = ( s[i][j] == '.' );
      ++mp[col][find(j+i*W)];
    }
  }
  ll ans = 0;
  for(auto v : mp[0]) {
    int id = v.first;
    ll cnt = v.second;
    ans += ( (ll)mp[1][id] * cnt );
  }
  cout << ans << endl;
}

int main() {
  cin >> H >> W;
  rep(i,H) cin >> s[i];
  compute();
  return 0;
}

