using namespace std;

char field[402][402];
queue<pair<int,int>> q;

void syori(int first, int second){
    q.push(make_pair(first, second));
    if(field[first][second]=='.')field[first][second]=',';
    else field[first][second]='$';

    return;
}

int main(void)
{
    int  H, W;

    for(int j = 0; j < 402; ++j){
        for(int i = 0; i < 402; ++i){
            field[j][i] = '0';
        }
    }
    cin >> H >> W;
    for(int j = 1; j <= H; ++j){
        for(int i = 1; i <= W; ++i){
            cin >> field[j][i];
        }
    }
    long int ans = 0;
    for(int j = 1; j <= H; ++j){
        for(int i = 1; i <= W; ++i){
            if(field[j][i]=='.' || field[j][i]=='#'){
                syori(j, i);
                long int b = 0, w = 0;
                while(!q.empty()){
                    pair<int,int> a = q.front();
                    q.pop();
                    if(field[a.first][a.second] == '$'){
                        b++;
                        field[a.first][a.second] = '0';
                        if(field[a.first - 1][a.second] == '.')syori(a.first - 1, a.second);
                        if(field[a.first + 1][a.second] == '.')syori(a.first + 1, a.second);
                        if(field[a.first][a.second - 1] == '.')syori(a.first, a.second - 1);
                        if(field[a.first][a.second + 1] == '.')syori(a.first, a.second + 1);
                    }else if(field[a.first][a.second] == ','){
                        w++;
                        field[a.first][a.second] = '0';
                        if(field[a.first - 1][a.second] == '#')syori(a.first - 1, a.second);
                        if(field[a.first + 1][a.second] == '#')syori(a.first + 1, a.second);
                        if(field[a.first][a.second - 1] == '#')syori(a.first, a.second - 1);
                        if(field[a.first][a.second + 1] == '#')syori(a.first, a.second + 1);
                    }
                }
                ans += b * w;
            }
        }
    }
    cout << ans << endl;

    return 0;
}

