void create_from_grid2(uf_tree& uf, int h, int w, vector<string>& mapData) {
	//グラフ構築 O(HW)
	rep(y, h) {
		rep(x, w) {
			int id = y * w + x;
			//右と下(変位が正)のみ見る(辺の重複を回避するため)
			rep(i, 2) {
				int nx = x + dxp[i];
				int ny = y + dyp[i];
				int nid = ny * w + nx;
				if (nx < 0 || nx >= w) {
					continue;
				}
				if (ny < 0 || ny >= h) {
					continue;
				}
				// 色が違うときだけ辺を張る
				if (mapData[ny][nx] != mapData[y][x]) {
					uf.unite(id, nid);
				}
			}
		}
	}
}

