struct Maze {
    int H, W;
    long long cost1=1, cost2=0, cost3=0, cost4=1;
    vector<string> maze;
    Maze(int H, int W, vector<string> maze) : H(H), W(W), maze(maze) {}
    vector<int> di={1,0,-1,0}, dj={0,1,0,-1};
    vector<vector<edge>> G;
    void Ginit() {
        G.resize(H*W);
        for(int i=0;i<H;++i) {
            for(int j=0;j<W;++j) {
                for (int k=0;k<4;k++) {
                    int ni = i + di[k];
                    int nj = j + dj[k];
                    if(0<=ni&&ni<H&&0<=nj&&nj<W) {
                        long long cost=0;
                        if(maze[i][j]=='.'&&maze[ni][nj]=='.') cost=cost1;
                        else if(maze[i][j]=='.'&&maze[ni][nj]=='#') cost=cost2;
                        else if(maze[i][j]=='#'&&maze[ni][nj]=='.') cost=cost3;
                        else if(maze[i][j]=='#'&&maze[ni][nj]=='#') cost=cost4;
                        if(cost!=INF) G[i*W+j].push_back((edge){ni*W+nj,cost});
                    }
                }
            }
        }
    }

};

struct UnionFind {
  vector<int> data;
  vector<int> white;
  UnionFind(int size) : data(size, -1), white(size, 0) {}
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
        if (data[y] < data[x]) swap(x, y);
        data[x] += data[y]; data[y] = x;
        white[x] += white[y];
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

int main() {
    int H, W; cin >> H >> W;
    vector<string> maze(H);
    REP(i,H) cin >> maze[i];
    Maze MZ(H,W,maze); MZ.Ginit();
    UnionFind UF(H*W);
    REP(i,H*W) if(maze[i/W][i%W]=='.') UF.white[i]++;
    for(int i=0; i<H*W; i++) for(auto e:MZ.G[i]) {
        if(e.cost==0) UF.unionSet(i,e.to);
    }
    ll ans = 0;
    REP(i,H*W) {
        if(i==UF.root(i)) ans += (ll) (UF.size(i) - UF.white[i]) * UF.white[i];
    }
    cout << ans << endl;
}

