int dfs_b(int i, int j, int n) {
    ++n;
    visited[i][j] = true;

    if (n % 2) {
        rep(k, 4) {
            if (0 <= i + dx[k] && i + dx[k] <= h - 1 && 0 <= j + dy[k] && j + dy[k] <= w - 1 && field[i + dx[k]][j + dy[k]] == '.' && visited[i + dx[k]][j + dy[k]] == false) {
                ++white;
                dfs_b(i + dx[k], j + dy[k], n);
            }
        }
    } else {
        rep(k, 4) {
            if (0 <= i + dx[k] && i + dx[k] <= h - 1 && 0 <= j + dy[k] && j + dy[k] <= w - 1 && field[i + dx[k]][j + dy[k]] == '#' && visited[i + dx[k]][j + dy[k]] == false) {
                ++black;
                dfs_b(i + dx[k], j + dy[k], n);
            }
        }
    }
    return (black + 1) * white;
}

int dfs_w(int i, int j, int n) {
    ++n;
    visited[i][j] = true;

    if (n % 2) {
        rep(k, 4) {
            if (0 <= i + dx[k] && i + dx[k] <= h - 1 && 0 <= j + dy[k] && j + dy[k] <= w - 1 && field[i + dx[k]][j + dy[k]] == '#' && visited[i + dx[k]][j + dy[k]] == false) {
                ++black;
                dfs_w(i + dx[k], j + dy[k], n);
