struct UnionFind // UnionFind Tree (0-indexed)
{
    vector<int> par, rank;
    UnionFind(int N) : par(N), rank(N) { REP(i, N) par[i] = i; }
    int find(int x) { return (par[x] == x) ? x : (par[x] = find(par[x])); }
    void unite(int x, int y) {
        x = find(x), y = find(y); if (x == y) return;
        if (rank[x] < rank[y]) par[x] = y; else par[y] = x;
        if (rank[x] == rank[y]) rank[x]++;
    }
    bool same(int x, int y) { return find(x) == find(y); }
};


int main()
{
    cin >> H >> W;
    S.resize(H);
    cin >> S;

    UnionFind uf(H * W);
    REP(h, H) REP(w, W) if (h + w)
    {
        if (h and (S[h][w] != S[h - 1][w])) uf.unite(h * W + w, (h - 1) * W + w);
        if (w and (S[h][w] != S[h][w - 1])) uf.unite(h * W + w, h * W + w - 1);
    }
    map<int, int> ma[2];
    REP(h, H) REP(w, W) ma[S[h][w] == '#'][uf.find(h * W + w)]++;

    lint ans = 0;
    REP(i, H * W) ans += ma[0][i] * ma[1][i];
    cout << ans << endl;
}

