pair<int, int> dfs(int y, int x, vector<vector<bool>>& visit) {
  const vector<pair<int, int>> dirs = {{+1, 0}, {-1, 0}, {0, +1}, {0, -1}};
  int black = (S[y][x] == '#') ? 1 : 0;
  int white = (S[y][x] == '.') ? 1 : 0;
  rep(i, 4) {
    int ny = y + dirs[i].first;
    int nx = x + dirs[i].second;
    if (ny < 0 || nx < 0 || H <= ny || W <= nx) continue;
    if (S[y][x] == S[ny][nx] || visit[ny][nx]) continue;
    visit[ny][nx] = true;
    int b, w;
    tie(b, w) = dfs(ny, nx, visit);
    black += b;
    white += w;
  }
  return make_pair(black, white);
}

