      if (S[i][j] == '#' && !visit[i][j]) {
        visit[i][j] = true;
        int b, w;
        tie(b, w) = dfs(i, j, visit);
        answer += b * w;
      }
    }
  }
  cout << answer << endl;
  return 0;
}

