  cin >> h >> w;
  for (int i = 0; i < h; ++i) cin >> s[i];
  Dsu tool(h * w);
  int dx[4] = {-1, 0, 1, 0};
  int dy[4] = {0, 1, 0, -1};
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      for (int d = 0; d < 4; ++d) {
        int ni = i + dx[d], nj = j + dy[d];
        if (ni < h and ni >= 0 and nj < w and nj >= 0 and s[i][j] != s[ni][nj]) {
          tool.unite(i * w + j, ni * w + nj);
        }
      }
    }
  }
  vector<bool> used(h * w);
  long long ans = 0;
  vector<vector<char>> compo;
  compo.resize(h * w);
  for (int i = 0; i < h * w; ++i) {
    compo[tool.anc(i)].emplace_back(s[i / w][i % w]);
  }
  for (int i = 0; i < h * w; ++i) {
    long long w = count(compo[i].begin(), compo[i].end(), '.'), b = count(compo[i].begin(), compo[i].end(), '#');
    ans += w * b;
  }
