    for (int j = 0; j < w; j++) {
      cin >> board[i][j];
    }
  }

  vector<vector<int>> visited(h, vector<int> (w, 0));
  int dx[4] = {1,-1,0,0};
  int dy[4] = {0,0,1,-1};

  ll ans = 0;
  queue<pair<int,int>> que;
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if(visited[i][j] || board[i][j] == '.') continue;
      que.emplace(i, j);
      visited[i][j] = 1;
      int cnt_blk = 1;
      int cnt_wht = 0;
      while(!que.empty()) {
        int curx = que.front().first;
        int cury = que.front().second;
        que.pop();

        for (int k = 0; k < 4; k++) {
          int nx = curx + dx[k];
          int ny = cury + dy[k];

          if(nx < h && nx >= 0 && ny < w && ny >= 0 &&
             board[curx][cury] != board[nx][ny] && !visited[nx][ny]) {
            que.emplace(nx, ny);
            visited[nx][ny] = 1;
            if(board[nx][ny] == '#') cnt_blk++;
            else cnt_wht++;
          }
        }
      }
      ans += cnt_blk * cnt_wht;
    }
