vector<vector<bool> > memo;

void dfs(int i, int j, bool color){

    memo[i][j] = true;
    if(i - 1 != -1 && memo[i - 1][j] == false && S[i - 1][j] == '.' && color == true) dfs(i - 1, j, false); // up
    if(i - 1 != -1 && memo[i - 1][j] == false && S[i - 1][j] == '#' && color == false) dfs(i - 1, j, true); // up
    if(i + 1 != H && memo[i + 1][j] == false && S[i + 1][j] == '.' && color == true) dfs(i + 1, j, false); // down
    if(i + 1 != H && memo[i + 1][j] == false && S[i + 1][j] == '#' && color == false) dfs(i + 1, j, true); // down
    if(j + 1 != W && memo[i][j + 1] == false && S[i][j + 1] == '.' && color == true) dfs(i, j + 1, false); // right
    if(j + 1 != W && memo[i][j + 1] == false && S[i][j + 1] == '#' && color == false) dfs(i, j + 1, true); // right
    if(j - 1 != -1 && memo[i][j - 1] == false && S[i][j - 1] == '.' && color == true) dfs(i, j - 1, false); // left
    if(j - 1 != -1 && memo[i][j - 1] == false && S[i][j - 1] == '#' && color == false) dfs(i, j - 1, true); // left

    if(S[i][j] == '.'){
        goal.first = i;
        goal.second = j;
        ans.insert(make_pair(start, goal));
    }
}

