#include<bits/stdc++.h>
using namespace std;

class Trees{
  vector<int> par;
  vector<int> rank;
  vector<int> cb,cw;

  public:
  int root(int i){
    int rt;
    if(par[i]==i){rt=i;rank[i]=1;}
    else{rt=root(par[i]);par[i]=rt;rank[i]=2;}
    return rt;
  }
  void unite(int i,int j){
    int rki=rank[i];int rkj=rank[j];
    if(rki<rkj){par[root(i)]=root(j);rank[i]++;}
    else{par[root(j)]=root(i);rank[j]++;}
  }
  bool same(int i,int j){
    return root(i)==root(j);
  }
  Trees(int n){
    for(int i=0;i<n;i++) {par.push_back(i);rank.push_back(1);cb.push_back(0);cw.push_back(0);};
  }
  void count(long i,char c){
    if(c=='#')cb[root(i)]++;
    if(c=='.')cw[root(i)]++;
  }
  long solve(){
    long ans=0;
    for(long i=0;i<cb.size();i++)ans+=cb[i]*cw[i];
    return ans;
  }
};

int main(){
  long H,W;cin>>H>>W;
  vector<string>S(H);for(long i=0;i<H;i++)cin>>S[i];
  Trees tree(H*W);
  for(long i=0;i<H;i++)for(long j=0;j<W-1;j++)if(S[i][j]!=S[i][j+1])tree.unite(i*W+j,i*W+j+1);
  for(long i=0;i<H-1;i++)for(long j=0;j<W;j++)if(S[i][j]!=S[i+1][j])tree.unite(i*W+j,i*W+j+W);
  for(long i=0;i<H;i++)for(long j=0;j<W;j++)tree.count(i*W+j,S[i][j]);
  cout<<tree.solve();
}

