const int maxn = 404 * 404;
int u[maxn], s0[maxn], s1[maxn];
void init(){
  iota(u, u + maxn, 0);
}
int find(int x){
  if(x == u[x]) return x;
  return u[x] = find(u[x]);
}
int join(int x, int y){
  x = find(x);
  y = find(y);
  if(x ^ y){
    u[x] = y;
    s0[y] += s0[x];
    s1[y] += s1[x];
  	return 1;
  }
  return 0;
}
int main(){
  int n, w; cin >> n >> w;
  vector<string> grid(n);
  for(auto & i : grid) cin >> i;
  for(int i = 0; i < n; i++) for(int j = 0; j < w; j++) {
    if(grid[i][j] == '#') s0[i*w+j] = 1;
    else s1[i*w+j] = 1;
  }
  init();
  for(int i = 0; i < n; i++) for(int j = 0; j < w; j++) {
    for(int di: {-1, 0, 1}){
      for(int dj: {-1, 0, 1}){
        if(abs(di) + abs(dj) == 1){
          int ni = di + i, nj = dj + j;
