struct UF {
	vi data, black, white;
	void init(int n)
	{
		data.resize(n);
		black.resize(n);
		white.resize(n);
		fill(all(data), -1);
		fill(all(black), 0);
		fill(all(white), 0);
	}
	int root(int x)
	{
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	void unite(int x, int y)
	{
		x = root(x);
		y = root(y);
		if (x == y) return;
		if (size(x) < size(y)) swap(x, y);
		data[x] += data[y];
		data[y] = x;
		black[x] += black[y];
		white[x] += white[y];
	}
	bool same(int x, int y)
	{
		return root(x) == root(y);
	}
	int size(int x)
	{
		x = root(x);
		return -data[x];
	}
	int calc(int x)
	{
		x = root(x);
		return black[x] * white[x];
	}
	bool is_root(int x)
	{
		return x == root(x);
	}
};

