		if (a[i][j]) uf.black[encode(i, j)]++;
		else uf.white[encode(i, j)]++;
	}

	rep(y, H) rep(x, W) {
		rep(k, 4) {
			int ny = y + dy[k], nx = x + dx[k];
			if (inside(ny, nx) and a[y][x] != a[ny][nx]) {
				uf.unite(encode(y, x), encode(ny, nx));
			}
		}
	}

