    ll ct1=0,ct2=0;
    while(!dq.empty()) {
        ll vx = dq.front().first;
        ll vy = dq.front().second;
        if((vx+vy)%2) ++ct1;
        else ++ct2;
        dq.pop_front();
        rep(i,4){
            ll x=vx+dx[i]; ll y=vy+dy[i];
            if(x<0 or x>=MAXX or y<0 or y>=MAXY) continue;
            if(map2d[x][y]==0) continue;
            if(depth[x][y]!=-1) continue;
            depth[x][y]=depth[vx][vy]+1;
            dq.emplace_back(x,y);
        }
    }
    return ct1*ct2;
}

