	}
	vector<T> operator()(int n, int h) {
		vector<T> ret(h);
		rep(i, h)ret[i] = InputC::operator()(i + n);
		return ret;
	}
	vector<vector<T>> operator()(int n, int h, int w) {
		vector<vector<T>> ret(h, vector<T>(w));
		rep(i, h)rep(j, w)ret[i][j] = InputC::operator()(n + i * w + j);
		return ret;
	}
};
