class UnionFind {
	vector<int> par, sz;
public:
	UnionFind(int n = 1) {
		init(n);
	}
	void init(int n) {
		par.resize(n); sz.resize(n);
		for (int i = 0; i < n; i++)par[i] = i, sz[i] = 1;
	}
	int root(int x) {
		if (par[x] == x)return x;
		else return par[x] = root(par[x]);
	}
	bool same(int x, int y) {
		return root(x) == root(y);
	}
	int size(int x) {
		return sz[root(x)];
	}
	void unite(int x, int y) {
		x = root(x); y = root(y);
		if (x == y)return;
		par[y] = x;
		sz[x] += sz[y];
	}
};

struct Point {
	int x, y;
	Point() :x(-1), y(-1) {}
	Point(int _x, int _y) :x(_x), y(_y) {}
	Point(int val, int H, int W) :x(val% W), y(val / W) {}
	Point operator+() { return *this; }
	Point operator-() { return { -x,-y }; }
	Point operator+(Point p) { return { x + p.x,y + p.y }; }
	Point operator-(Point p) { return { x - p.x,y - p.y }; }
	Point operator*(Point p) { return { x * p.x,y * p.y }; }
	Point operator/(Point p) { return { x / p.x,y / p.y }; }
	Point operator+(int d) { return { x + d,y + d }; }
	Point operator-(int d) { return { x - d,y - d }; }
	Point operator*(int d) { return { x * d,y * d }; }
	Point operator/(int d) { return { x / d,y / d }; }
	Point& operator+=(Point p) { x += p.x; y += p.y; return *this; }
	Point& operator-=(Point p) { x -= p.x; y -= p.y; return *this; }
	Point& operator*=(Point p) { x *= p.x; y *= p.y; return *this; }
	Point& operator/=(Point p) { x /= p.x; y /= p.y; return *this; }
	bool operator==(Point p) { return x == p.x && y == p.y; }
	bool operator!=(Point p) { return x != p.x || y != p.y; }
	int Dist(Point p) { return abs(x - p.x) + abs(y - p.y); }
	bool inBound(int H, int W) { return 0 <= x && x < W && 0 <= y && y < H; }
	int toInt(int H, int W) { return x + W * y; }
	array<Point, 4> Adjacent4() {
		return { Point(x,y + 1),Point(x,y + -1),Point(x + 1,y),Point(x + -1,y) };
	}
	array<Point, 8> Adjacent8() {
		return { Point(x,y + 1),Point(x,y - 1),Point(x + 1,y),Point(x - 1,y),
			Point(x + 1,y + 1),Point(x + 1,y + -1),Point(x - 1,y + 1),Point(x - 1,y - 1) };
	}
	vector<Point> Adjacent4_inRange(int H, int W) {
		vector<Point> ret;
		for (auto p : Adjacent4())
			if (p.inBound(H, W))ret.push_back(p);
		return ret;
	}
	vector<Point> Adjacent8_inRange(int H, int W) {
		vector<Point> ret;
		for (auto p : Adjacent8())
			if (p.inBound(H, W))ret.push_back(p);
		return ret;
	}
};

