using namespace std;

ll ecd(ll a, ll b) {
	if (a < b) swap(a, b);
	if (b == 0) return a;
	else {
		return ecd(b, a % b);
	}
}

ll pow(ll a, ll b) {
	vector<ll> d = vector<ll>((ll)(log(b)) + 2);
	d[0] = a;
	rep(i, 1, d.size()) d[i] = d[i - 1] * d[i - 1];
	ll ret = 1;
	rep(i, 0, log(b) + 1) {
		if (b & 1 << i) ret *= d[i];
	}
	return ret;
}

ll H, W,index;
vector<string> S;
vector<vector<ll>> group;
vector<vector<ll>> visit;

void rec(ll row, ll col) {
	visit[row][col] = 1;
	if (S[row][col] == '.') group[index][0]++;
	else group[index][1]++;
	rep(i, -1, 2) {
		rep(j, -1, 2) {
			if (i != 0 && j != 0)continue;

			if (0 <= row + i && row + i < H && 0 <= col + j && col + j < W) {
				if (S[row][col] != S[row + i][col + j] && visit[row + i][col + j] < 0) rec(row + i, col + j);
			}
		}
	}
}


