int main(void) {
	cin >> H >> W;
	group = vector<vector<ll>>(H * W, vector<ll>(2, 0));
	visit = vector<vector<ll>>(H, vector<ll>(W,-1));
	S = vector<string>(H);

	rep(i, 0, H) cin >> S[i];

	rep(i, 0, H) {
		rep(j, 0, W) {
			if (visit[i][j]) {
				rec(i, j);
				index++;
			}	
		}
	}

	ll ans = 0;
	rep(i, 0, H* W) {
		ans += group[i][0] * group[i][1];
	}

	cout << ans << endl;
}

