struct union_find{//rank,経路圧縮で高速化
  vector<int> par;//parは添字の親（または自分が根の時自身）を示す。
  vector<int> rank;//rankは木の高さ（根についてのみ実装,0-indexed）
  union_find(int n){//コンストラクタ,n個のノードを作成し、自分を親につける
    par.assign(n,0);
    rank.assign(n,0);
    for(int i = 0;i < n;++i) par[i]=i;
  }
  void init(int n){//初期化,n個のノードを作成し、自分を親につける
    par.assign(n,0);
    rank.assign(n,0);
    for(int i = 0;i < n;++i) par[i] = i;
  }
  int find(int a){//根を探す
    if(par[a]==a) return a; //親が自身を指す時、根である
    else return par[a] = find(par[a]);//根に直接つける
  }
  void unite(int a,int b){//小さい方の木の根に大きい方の根を上書きする
    int roota,rootb;
    roota = find(a),rootb = find(b);
    pii tmp1 = fromuf(roota);
    pii tmp2 = fromuf(a);
    dp[tmp1.first][tmp1.second] = dp[tmp2.first][tmp2.second];
    tmp2 = fromuf(rootb);
    dp[tmp1.first][tmp1.second] = dp[tmp2.first][tmp2.second];
    if(roota==rootb) return;
    if(rank[roota]>rank[rootb]){ //rankの高い方の根に低い方の根をつける
      par[rootb] = roota;
    }else if(rank[roota]<rank[rootb]){
      par[roota] = rootb;
    }else{ //rankが同じ時、適当な方につけ、つけられた方のrankを1増やす
      rank[roota]++;
      par[rootb] = roota;
    }
  }
};
