		}
	    }
	}
    }

    ll res = 0;


    map<int,vector<pair<int,int>>> mp;


    for (int i=0; i<n; i++) {
	for (int j=0; j<m; j++) {
	    int k = i*m+j;
	    mp[dsu.parent(k)].push_back({i,j});
