#define endl '\n'
#define D(x)  // cout << #x << " = " << (x) << endl;

bool is_valid(int x, int n) {
  return 0 <= x and x < n;
}

pair<long long, long long> count(int i, int j, const vector<string> &grid, vector<vector<int>> &mark) {
  const int h = grid.size();
  const int w = grid[0].size();

  int black = 1;
  int white = 0;

  mark[i][j] = 1;

  queue<pair<int, pair<int, int>>> Q;
  Q.push({0, {i, j}});

  vector<pair<int, int>> delta = {{ 1, 0},
                                  { 0, 1},
                                  {-1, 0},
                                  { 0,-1}};

  while (!Q.empty()) {
    int parity = Q.front().first;
    int i = Q.front().second.first;
    int j = Q.front().second.second;
    Q.pop();
    // cout << i << " " << j << endl;

    for (auto d : delta) {
      int next_i = i + d.first;
      int next_j = j + d.second;
      int next_parity = !parity;

      if (!is_valid(next_i, h) or !is_valid(next_j, w)) continue;
      if (mark[next_i][next_j]) continue;
      if (next_parity == 0 and grid[next_i][next_j] == '.') continue;
      if (next_parity == 1 and grid[next_i][next_j] == '#') continue;

      mark[next_i][next_j] = 1;
      Q.push({next_parity, {next_i, next_j}});

      if (next_parity == 0) {
        black++;
      } else {
        white++;
      }
      // cout << "  " << next_i << " " << next_j << endl;
    }
  }
  D(black); D(white);

  return {black, white};
}

int main() { IO;
  int h, w;
  cin >> h >> w;

  vector<string> grid(h);
  for (auto &line : grid) cin >> line;

  vector<vector<int>> mark(h);
  for (auto &v : mark) {
    v.resize(w);
  }

  long long ans = 0;
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      if (grid[i][j] == '#' and mark[i][j] == 0) {
        auto cnt = count(i, j, grid, mark);
        ans += cnt.first * cnt.second;
      }
    }
  }

  cout << ans << endl;

  return 0;
}

