using namespace std;

bool in_range(int a, int b, int x){
    return (a <= x) && (b >= x);
}

vector<vector<int>> bound(vector<int> &point, vector<string> &grid, int H, int W, char c){
    vector<vector<int>> ret;
    for (int a=-1; a<=1; a++){
        for (int b=-1; b<=1; b++){
            if (!(a == 0 || b == 0)) continue;
            if (in_range(0, W - 1, point[0] + a) && in_range(0, H - 1, point[1] + b) && grid[point[1] + b][point[0] + a] == c){
                ret.emplace_back(vector<int>({point[0] + a, point[1] + b}));
            }
        }
    }
    return ret;
}

bool visited(vector<int> point, vector<vector<int>> path){
    bool ret = false;
    for (int i=0; i<path.size(); i++){
        if (path[i] == point){
            ret = true;
            break;
        }
    }

    return ret;
}

void clean(vector<vector<vector<int>>> &boundary){
    vector<vector<int>> tmp, tmp2;
    int count = 0;
    int size = boundary.size();
    for (int i=0; i<size; i++){
        tmp.emplace_back(boundary[i - count].back());
        if (boundary[i - count].size() > 1) tmp2.emplace_back(boundary[i - count][boundary[i-count].size() - 2]);
        if (visited(boundary[i - count].back(), tmp) && visited(boundary[i - count].back(), tmp2)){
            boundary.erase(boundary.begin() + i - count);
            count++;
        }
    }
}


int main() {
    int H, W;
    string tmp;
    cin >> H >> W;
    int result = 0;
    vector<string> grid;
    vector<vector<int>> path, next_points, path_tmp, explored;
    vector<vector<vector<int>>> boundary;
    for (int i=0; i<H; i++){
        cin >> tmp;
        grid.push_back(tmp);
        for (int j=0; j<W; j++){
            if (tmp[j] == '#') boundary.emplace_back(vector<vector<int>>({vector<int>({j, i})}));
        }
    }
    int count = 1, size_tmp;

    while (!boundary.empty()){
        size_tmp = boundary.size();
        for (int i=0; i<size_tmp; i++){
            path = boundary.back();
            if (!explored.empty()) explored.erase(explored.begin(), explored.end());
            next_points = bound(path.back(), grid, H, W, (count % 2 == 0 ? '#' : '.'));
            for (int j=0; j<next_points.size(); j++){
                explored.emplace_back(next_points[j]);
                if (!visited(next_points[j], path)){
                    path_tmp = path;
                    path_tmp.push_back(next_points[j]);
                    boundary.insert(boundary.begin(), path_tmp);
                }
            }
            boundary.pop_back();
        }
        clean(boundary);
        count++;
        if (count % 2 == 0){
            result += boundary.size();
        }
    }

    cout << result << endl;



    return 0;

}

