#include <bits/stdc++.h>
using namespace std;

#define N 410
int n, m;
char G[N][N];
bool vis[N][N];
int res[N][N];
int Move[][2] = 
{
	1, 0,
   -1, 0,
    0,-1,
	0, 1,
};

bool ok(int x, int y)
{
	if (x < 1 || x > n || y < 1 || y > m) return false;
	return true; 
}

void DFS(int x, int y)
{
	vis[x][y] = 1;
	if (G[x][y] == '#') ++res[x][y];
	for (int i = 0; i < 4; ++i)
	{
		int nx = x + Move[i][0];
		int ny = y + Move[i][1];
		if (ok(nx, ny) && G[nx][ny] != G[x][y] && vis[nx][ny] == 0)
			DFS(nx, ny); 
	}
}

void clear(int x, int y)
{
	if (vis[x][y] == 0) return;
	vis[x][y] = 0;
	for (int i = 0; i < 4; ++i)
	{
		int nx = x + Move[i][0];
		int ny = y + Move[i][1];
		if (ok(nx, ny) && vis[nx][ny] == 1) clear(nx, ny);
	}
}

int main()
{
	while (scanf("%d%d", &n, &m) != EOF)
	{
		for (int i = 1; i <= n; ++i) scanf("%s", G[i] + 1);
		memset(vis, 0, sizeof vis);
		memset(res, 0, sizeof res);
		for (int i = 1; i <= n; ++i) for (int j = 1; j <= m; ++j) if (G[i][j] == '.')
		{
			DFS(i, j);
			clear(i, j);
		}
		int tot = 0;
		for (int i = 1; i <= n; ++i) for (int j = 1; j <= m; ++j) tot += res[i][j];
		printf("%d\n", tot);
	}
	return 0;
}

