using V=vector<int>;
using Vl=vector<ll>;
using VV=vector<vector<int>>;
using VVl=vector<vector<ll>>;

struct UnionFind{
    vector<int> d;
    UnionFind(int n=0):d(n,-1){}
    int root(int x){
        if(d[x]<0)return x;
        return d[x]=root(d[x]);
    }
    bool unite(int x,int y){
        x=root(x);y=root(y);
        if(x==y)return false;
        if(d[x]>d[y])swap(x,y);
        d[x]+=d[y];
        d[y]=x;
        return true;
    }
    bool same(int x,int y){return root(x)==root(y);}
    int usize(int x){return -d[root(x)];}
};

int main(){
    int h,w;cin >>h>>w;
    int n=h*w;
    UnionFind uni(n);
    vector<string>s(h);
    for (int i = 0; i < h; ++i) {
        cin >>s[i];
    }
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            if(i-1>=0 and s[i][j]!=s[i-1][j]){
                uni.unite(w*i+j,w*(i-1)+j);
            }
            if(j>=1 and s[i][j]!=s[i][j-1]){
                uni.unite(w*i+j,w*i+(j-1));
            }
        }
    }
    V black(n,0);
    for (int i = 0; i < n; ++i) {
        if(s[i/w][i%w]=='#')black[uni.root(i)]++;
    }
    ll ans=0;
    vector<bool>used(n,false);
    for (int i = 0; i < n; ++i) {
        if(used[uni.root(i)])continue;
        ll u=uni.usize(i);
        ll b=black[uni.root(i)];
        ans+=(b*(u-b));
        used[uni.root(i)]=true;
    }
    cout <<ans <<endl;
}

