const ll MAXn=4e2+5,MAXlg=__lg(MAXn)+2;
const ll MOD=1000000007;
const ll INF=0x3f3f3f3f;

ll h,w;
char d[MAXn][MAXn];
ll dsu[MAXn*MAXn],sz[MAXn*MAXn],bsz[MAXn*MAXn];
bitset<MAXn*MAXn> chk;
ll dx[] = {-1,0};
ll dy[] = {0,-1};
void init(){
  REP (i,h) REP (j,w) {
    if (d[i][j] == '#') bsz[i*h+j] = 1;
    sz[i*h+j] = 1, dsu[i*h+j] = i*h+j;
  }
}
ll fd(ll x){
  if (x == dsu[x]) return x;
  return dsu[x] = fd(dsu[x]);
}
void mrg(ll x,ll y){
  x = fd(x), y = fd(y);
  if (x == y) return;
  if (sz[x] > sz[y]) swap(x,y);
  dsu[x] = y;
  sz[y] += sz[x];
  bsz[y] += bsz[x];
}
ll ok(ll x,ll y){
  return x<0 || x>=h || y<0 || y>=w;
}
void gogo(ll x,ll y){
  REP (i,2) {
    ll tx = x + dx[i], ty = y + dy[i];
    if (ok(tx,ty)) continue;
    if (d[tx][ty] != d[x][y]) mrg(x*h+y,tx*h+ty);
  }
}
int main(){
  IOS();
  cin >> h >> w;
  REP (i,h) REP (j,w) cin >> d[i][j];
  init();
  REP (i,h) REP (j,w) gogo(i,j);
  ll ans = 0;
  REP (i,h) REP (j,w) {
    ll tmp = fd(i*h+j);
    if (chk[tmp]) continue;
    ans += max(0LL,(sz[tmp]-bsz[tmp]) * bsz[tmp]);
    chk[tmp] = true;
  }
  cout << ans << endl;
}

