        if (s[ny][nx] == '#') cnt++;
        else cnt2++;
        table[ny][nx] = 1;
        q.push(pii(ny, nx));
      }
    }
    // cout << cnt << " " << cnt2 << endl;
    ans += 1LL * cnt * cnt2;
  }
