void bfs(ii src){
	int white = 0;
	int black = 0;
	queue<ii> q; q.push(src);
	used[src.fst][src.snd] = 1;
	while(sz(q)){
		ii v = q.front(); q.pop();
		//~ printf("(%d, %d)\n", v.fst, v.snd);
