		else 						  white++;
		forn(i, 4){
			ii w = {v.fst + dr[i], v.snd + dc[i]};
			if(ok(w) && !used[w.fst][w.snd] && grid[v.fst][v.snd] != grid[w.fst][w.snd]){
				used[w.fst][w.snd] = true;
				q.push(w);
			}
		}
	}
	ans += white*black;
}

