typedef long long ll;
using namespace std;

bool is_in(int i, int j, int h, int w) {
    return 0 <= i && i < h && 0 <= j && j < w;
}

int main() {

    int h, w;
    cin >> h >> w;
    vector<string> sorg(h, "");
    vector<string> s   (h, "");
    REP(i, h) {
        cin >> s[i];
        sorg[i] = s[i];
    }

    REP(i, h) REP (j, w)
        if ((i + j) % 2)
            s[i][j] ^= '.' ^ '#';

    vector<vector<bool>> visited(h, vector<bool>(w, false));
    int ans = 0;
    REP(i, h) REP(j, w) {
        if (visited[i][j]) continue;
        deque<pair<int, int>> q;
        q.push_back(make_pair(i, j));
        visited[i][j] = true;
        int black = 0, white = 0;
        while (!q.empty()) {
            auto v = q.back();
            int k = v.first, l = v.second;
            q.pop_back();
            if (sorg[k][l] == '.') white++; else black++;
            if (is_in(k-1, l, h, w)) if (s[k][l] == s[k-1][l] && !visited[k-1][l]) {
                q.push_back(make_pair(k-1, l));
                visited[k-1][l] = true;
            }
            if (is_in(k+1, l, h, w)) if (s[k][l] == s[k+1][l] && !visited[k+1][l]) {
                q.push_back(make_pair(k+1, l));
                visited[k+1][l] = true;
            }
            if (is_in(k, l-1, h, w)) if (s[k][l] == s[k][l-1] && !visited[k][l-1]) {
                q.push_back(make_pair(k, l-1));
                visited[k][l-1] = true;
            }
            if (is_in(k, l+1, h, w)) if (s[k][l] == s[k][l+1] && !visited[k][l+1]) {
                q.push_back(make_pair(k, l+1));
                visited[k][l+1] = true;
            }
        }
        ans += black * white;
    }

    cout << ans << endl;

}

