const int N = 400 + 77 , L = 30;
int n , m , P[N * N] , X[N * N] , Y[N * N];
int dx[4] = {0 , 0 , - 1 , 1} , dy[4] = {1 , - 1 , 0 , 0};
long long A;
char S[N][N];
int Find(int x){
   return P[x] == 0 ? x : (P[x] = Find(P[x]));
}
inline void Merge(int x , int y){
   x = Find(x);
   y = Find(y);
   if(x == y)
      return ;
   X[x] += X[y] , X[y] = 0;
   Y[x] += Y[y] , Y[y] = 0;
   P[y] = x;
}
int main(){
   //ios::sync_with_stdio(0);cin.tie(0);
   scanf("%d %d" , & n , & m);
   for(int i = 1;i <= n;++ i)
      scanf("%s" , S[i] + 1);
   for(int i = 1;i <= n;++ i)
      for(int j = 1;j <= m;++ j){
         if(S[i][j] == '#')
            X[i * N + j] = 1;
         else
            Y[i * N + j] = 1;
      }
   for(int i = 1;i <= n;++ i)
      for(int j = 1;j <= m;++ j){
         for(int k = 0;k < 4;++ k){
            int ni = i + dx[k] , nj = j + dy[k];
            if(ni == 0 || nj == 0 || ni == n + 1 || nj == m + 1)
               continue ;
            if(S[i][j] != S[ni][nj])
               Merge(i * N + j , ni * N + nj);
         }
      }
   for(int i = 0;i < N * N;++ i)
      if(P[i] == 0)
         A += X[i] * 1ll * Y[i];
   cout << A;
   return 0;
}

