#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MX = 400;

int h, w;
string s;

int grid[MX][MX], black[MX][MX], white[MX][MX];
bool used[MX][MX];
int ans;

int dx[2] = {1, 0};
int dy[2] = {0, 1};
void bfs(int x, int y) {
	queue<pair<int, int>> q;
	q.push({x, y});
	used[x][y] = true;

	while (!q.empty()) {
		pair<int, int> v = q.front();
		q.pop();
		int nx = v.first, ny = v.second;
		// cout << nx << ", " << ny << " - " << white[nx][ny] << " " << black[nx][ny] << "\n";

		if (grid[nx][ny] && white[nx][ny]) {
			// cout << nx << ", " << ny << ": " << white[nx][ny] << "\n";
			ans += white[nx][ny];
		} else if (!grid[nx][ny] && black[nx][ny]) {
			// cout << nx << ", " << ny << ": " << black[nx][ny] << "\n";
			ans += black[nx][ny];
		}

		for (int i = 0; i < 2; i++) {
			int a = nx + dx[i], b = ny + dy[i];
			if (a < 0 || a >= h || b < 0 || b >= w) continue;
			if (grid[a][b] == grid[nx][ny]) continue;
			if (used[a][b]) {
				if (grid[nx][ny]) black[a][b]++;
				else white[a][b]++;
				continue;
			}

			if (grid[nx][ny]) {
				black[a][b] = black[nx][ny] + 1;
				white[a][b] = white[nx][ny];
			} else {
				black[a][b] = black[nx][ny];
				white[a][b] = white[nx][ny] + 1;
			}
			q.push({a, b});
			used[a][b] = true;
		}
	}
}

int main() {
	cin.sync_with_stdio(0); cin.tie(0);
    cin >> h >> w;
    for (int i = 0; i < h; i++) {
		cin >> s;
		for (int j = 0; j < w; j++) {
			if (s[j] == '#') grid[i][j] = 1;
			else grid[i][j] = 0;
		}
	}

	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			if (!used[i][j]) bfs(i, j);
		}
	}

	cout << ans;
    return 0;
}

