int H, W;
char C[400][400];
int di[4] = {0,1,0,-1}, dj[4] = {1,0,-1,0};
bool visited[400][400];
ll ans = 0, b = 0, w = 0;

int DFS(int i, int j){
  if (visited[i][j]) return 0;
  visited[i][j] = true;

  if (C[i][j] == '.') w++;
  else b++;

  for (int k = 0; k < 4; k++){
    int I = i + di[k], J = j + dj[k];
    if (0 <= I && I < H && 0 <= J && J < W){
      if (visited[I][J]) continue;
      if (C[i][j] != C[I][J]) DFS(I, J);
    }
  }
  return 0;
}


