  for (int i = 0; i < H; i++){
    for (int j = 0; j < W; j++){
      cin >> C[i][j];
    }
  }

  for (int i = 0; i < H; i++){
    for (int j = 0; j < W; j++){
      if (visited[i][j]) continue;
      b = 0; w = 0;
      DFS(i, j);
      ans += b * w;
    }
  }
  cout << ans << endl;

