int main()
{
    int H, W;
    cin >> H >> W;

    vector<vector<bool>> board(H, vector<bool>(W));
    string S;
    for (int i = 0; i < H; i++)
    {
        cin >> S;
        for (int j = 0; j < W; j++)
        {
            board[i][j] = (S[j] == '#');
        }
    }

    vector<vector<bool>> visited(H, vector<bool>(W, false));

    vector<pair<int, int>> diff{
        pair<int, int>(1, 0),
        pair<int, int>(0, 1),
        pair<int, int>(-1, 0),
        pair<int, int>(0, -1)};
    queue<pair<int, int>> q;
    int ans = 0;
    int bsum;
    int wsum;
    int x;
    int newx;
    int y;
    int newy;
    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            if (!visited[i][j])
            {
                q.push(make_pair(i, j));
                bsum = 0;
                wsum = 0;
                while (!q.empty())
                {
                    x = q.front().first;
                    y = q.front().second;
                    q.pop();
                    if (!visited[x][y])
                    {
                        if (board[x][y])
                        {
                            bsum++;
                        }
                        else
                        {
                            wsum++;
                        }
                        visited[x][y] = 1;
                    }
                    for (pair<int, int> d : diff)
                    {
                        newx = x + d.first;
                        newy = y + d.second;
                        if (newx < 0 || newy < 0)
                        {
                            continue;
                        }
                        if (newx >= H || newy >= W)
                        {
                            continue;
                        }
                        if (visited[newx][newy])
                        {
                            continue;
                        }
                        if (board[x][y] != board[newx][newy])
                        {
                            q.push(make_pair(newx, newy));
                        }
                    }
                }
                ans += bsum * wsum;
            }
        }
    }
    cout << ans << endl;
}

