    ald[y][x] = true;
    bool q = map[y][x];
    if(q == true){h++;}
    else{i++;}
    if(y != 0){
    if(map[y-1][x] != q){dfs(h,i, H, W, y-1, x, map, ald);}
    }
    if(x != 0){
    if(map[y][x-1] != q){dfs(h,i, H, W, y, x-1, map, ald);}
    }
    if(y != H-1){
    if(map[y+1][x] != q){dfs(h,i, H, W, y+1, x, map, ald);}
    }
    if(x != W-1){
    if(map[y][x+1] != q){dfs(h, i, H, W, y, x+1, map, ald);}
    }
}

