    queue<pair<int, int>> q;
    visited[x][y] = true;
    q.push({x, y});

    while(!q.empty()) {
        pair<int, int> cur = q.front(); q.pop();
        white += g[cur.first][cur.second] == '.';
        black += g[cur.first][cur.second] == '#';
        for(auto m : moves) {
            int nx = cur.first + m.first;
            int ny = cur.second + m.second;
            if(nx < 0 || nx > w || ny < 0 || ny > h) continue;
            if(g[nx][ny] != g[cur.first][cur.second] && !visited[nx][ny]) q.push({nx, ny}), visited[nx][ny] = true;
        }
    }
}

void dfs(int x, int y) {
    visited[x][y] = true;

    white += g[x][y] == '.';
    black += g[x][y] == '#';

    for(auto m : moves) {
        int nx = x + m.first;
        int ny = y + m.second;
        if(nx < 0 || nx > w || ny < 0 || ny > h) continue;
        if(g[nx][ny] != g[x][y] && !visited[nx][ny]) dfs(nx, ny);
    }
}

