		return x;
	}else{
		return par[x]=find(par[x]);
	}
}

void unite(int x,int y){
	x=find(x);
	y=find(y);
	if(x==y)return;

	if(ran[x]<ran[y]){
		par[x]=y;
	}else{
		par[y]=x;
		if(ran[x]==ran[y])ran[x]++;
	}
	sizeb[x]=sizeb[y]+sizeb[x];
	sizeb[y]=sizeb[x];
	sizew[x]=sizew[y]+sizew[x];
	sizew[y]=sizew[x];

}

