class Solver {
  public:
    bool solve() {
        int H, W; cin >> H >> W;
        vector<string> G(H); cin >> G;
        ll ans = 0;
        vector<vector<int>> visited(H, vector<int>(W));
        rep(h, H) rep(w, W) {
            if(not visited[h][w]) {
                visited[h][w] = true;
                // cerr << endl;
                int dots = 0;
                int sharp = 0;
                queue<pii> que;
                que.emplace(h, w);
                while(que.size()) {
                    pii p = que.front(); que.pop();
                    int y = p.first;
                    int x = p.second;
                    // cerr << y << "," << x << endl;
                    (G[y][x] == '.' ? dots : sharp)++;
                    rep(i, 4) {
                        int ny = y + dy[i];
                        int nx = x + dx[i];
                        if(0 <= ny and ny < H and 0 <= nx and nx < W) {
                            if(G[y][x] != G[ny][nx]) {
                                if(not visited[ny][nx]) {
                                    visited[ny][nx] = true;
                                    que.emplace(ny, nx);
                                }
                            }
                        }
                    }
                }
                // cerr << " > " << dots << "," << sharp << endl;
                ans += (ll)dots * sharp;
            }
        }
        cout << ans << endl;
        return 0;
    }
};

