class unionfind{
  private:
  int n;
  vector<int> nums;
  public:
  //constructor
  unionfind(int size){
    nums=vector<int>(size);
    for(int i=0;i<size;i++){
      nums[i]=i;
    }
    n=size;
  }
  void unite(int a,int b){
    int root1=getroot(a);
    int root2 = getroot(b);
    nums[root2]=root1;
    nums[a]=root1;
    nums[b]=root1;
    return;
  }
  int getroot(int index){
    if(nums[index]==index){
      return index;
    }else{
      int root=getroot(nums[index]);
      nums[index]=root;
      return root;
    }
  }
  int &operator[](int input){    // [] 演算子の多重定義
    nums[input]= getroot(input);
    return nums[input];
  } 
  int kindsize(){
    set<int>tmp;
    for(int i=0;i<n;i++){
      tmp.insert(nums[i]);
    }
    return tmp.size();
  }
  int size(){
    return n;
  }
  void Print(){
    for(int i=0;i<n;i++){
      cout<<getroot(i)<<" ";
    }
    cout<<endl;
  }
};
