const ll MAX_N = 160000;

ll par[MAX_N];
ll u_rank[MAX_N];

void init(ll n){
	for (ll i = 0; i < n; i++){
		par[i] = i;
		u_rank[i] = 0;
	}
}

ll find(ll x){
	if (par[x] == x){
		return x;
	}
	else{
		return par[x] = find(par[x]);
	}
}

void unite(ll x, ll y){
	x = find(x);
	y = find(y);
	if (x == y) return;
	if (u_rank[x] < u_rank[y]){
		par[x] = y;
	}
	else{
		par[y] = x;
		if (u_rank[x] == u_rank[y]) u_rank[x]++;
	}
}

bool same(ll x, ll y){
	return find(x) == find(y);
}



