const static long long int MOD = 1000000000 + 7;
int dy[] = {0, -1, 0, 1};
int dx[] = {1, 0, -1, 0};

const static int MAX_N = 160000;

int c1[MAX_N], c2[MAX_N];
int par[MAX_N], rank_t[MAX_N];

void init(int n) {
    for (int i = 0; i <= n; ++i) {
        par[i] = i;
        rank_t[i] = 0;
    }
}

int root(int x) {
    return par[x] == x ? x : par[x] = root(par[x]);
}

bool same(int x, int y) {
    return root(x) == root(y);
}

void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return;

    if (rank_t[x] < rank_t[y]) {
        par[x] = y;
    } else {
        par[y] = x;
        if (rank_t[x] == rank_t[y]) rank_t[x]++;
    }
}

int main() {
    int h, w;
    char field[401][401];
    cin >> h >> w;
    rep(i, h) {
        string s;
        cin >> s;
        rep(j, w) {
            field[i][j] = s[j];
        }
    }

    init(h * w);
    rep(i, h) {
        rep(j, w) {
            rep(k, 4) {
                if (0 <= i + dx[k] && i + dx[k] <= h - 1 && 0 <= j + dy[k] && j + dy[k] <= w - 1) {
                    if (field[i][j] != field[i + dx[k]][j + dy[k]]) unite(i * w + j, (i + dx[k]) * w + (j + dy[k]));
                } else {
                    continue;
                }
            }
        }
    }

    rep(i, h) {
        rep(j, w) {
            //cout << i << " " << j << " " << field[i][j] << " " << root(i * w + j) << endl;
            if (field[i][j] == '.') ++c1[root(i * w + j)];
            else ++c2[root(i * w + j)];
        }
    }

    llong ans = 0;
    rep(i, h * w) {
        ans += (llong)c1[i] * c2[i];
    }

    cout << ans << endl;
    return 0;
}

