        cin >> grid[i];
    }
    vector<vector<bool>> visited(h, vector<bool>(w));
    static const pair<int, int> d[] = {
        {1, 0},
        {-1, 0},
        {0, 1},
        {0, -1},
    };
    ll ans = 0;
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            if (grid[i][j] == '#' && !visited[i][j]) {
                int black = 0, white = 0;
                queue<pair<int, int>> que;
                que.push({i, j});
                while (!que.empty()) {
                    auto from = que.front();
                    que.pop();
                    if (visited[from.first][from.second])
                        continue;

                    visited[from.first][from.second] = true;
                    black += grid[from.first][from.second] == '#';
                    white += grid[from.first][from.second] == '.';

                    for (const auto &e : d) {
                        int toy = from.first + e.first;
                        int tox = from.second + e.second;

                        if (!(0 <= toy && toy < h && 0 <= tox && tox < w) || visited[toy][tox] || grid[toy][tox] == grid[from.first][from.second])
                            continue;

                        que.push({toy, tox});
                    }
                }

                ans += (ll)black * (ll)white;
            }
        }
    }
    cout << ans << endl;
