ll power(ll x, ll n, ll mod) {//x^nをmodで割った余り
    ll res = 1;
    if (n > 0) {
        res = power(x, n / 2, mod);
        if (n % 2 == 0) res = (res * res) % mod;
        else res = (((res * res) % mod) * x) % mod;
    }
    return res;
}

