typedef pair<int, int>p;
p f1(p a, p b) { return make_pair(a.first + b.first, a.second + b.second); }
p f(int i, int j) {
	p r = make_pair(0, 0);
	if (b[i][j])return r;
	b[i][j] = 1;
	char ch = (c[i][j] == '.' ? '#' : '.');
	if (c[i][j] == '.')r.first++; else r.second++;
	if (c[i - 1][j] == ch && !b[i - 1][j])r = f1(r, f(i - 1, j));
	if (c[i + 1][j] == ch && !b[i + 1][j])r = f1(r, f(i + 1, j));
	if (c[i][j - 1] == ch && !b[i][j - 1])r = f1(r, f(i, j - 1));
	if (c[i][j + 1] == ch && !b[i][j + 1])r = f1(r, f(i, j + 1));
	return r;
}
