ll H, W;
string s[444];
ll dx[]={-1, 0, 1, 0};
ll dy[]={0, -1, 0, 1};

P dfs(ll x, ll y, ll** used) {
    used[x][y]=1;

    P p=mkp(0, 0);
    if(s[x][y]=='#') p.fi++;
    else p.se++;

    for(ll i=0; i<4; i++) {
        ll tx=x+dx[i];
        ll ty=y+dy[i];

        if(tx<0 || ty<0 || tx>=H || ty>=W) continue;
        if((s[x][y]=='#' && s[tx][ty]=='#') || (s[x][y]=='.' && s[tx][ty]=='.')) continue;
        if(used[tx][ty]!=-1) continue;

        P t=dfs(tx, ty, used);
        p.fi+=t.fi;
        p.se+=t.se;
    }

    return p;
}

