int bfs(int y, int x) {
  int cnt_w = 0, cnt_b = 0;
  queue<P> que; que.push({y, x});
  visited[y][x] = true;

  while (!que.empty()) {
    auto [y, x] = que.front(); que.pop();
    if (S[y][x] == '.') ++cnt_w;
    else                ++cnt_b;

    for (auto [dy, dx] : ds) {
      int ny = y + dy, nx = x + dx;
      if (nx < 0 || W <= nx || ny < 0 || H <= ny) continue;
      if (visited[ny][nx]) continue;
      if (S[y][x] == S[ny][nx]) continue;

      visited[ny][nx] = true;
      que.push({ny, nx});
    }
  }
  return cnt_w * cnt_b;
}

