  if(my == map[y][x]){
    num +=  0;
  }
  else{
    num += 1;
  }
  if(x+1 < W && (map[y][x+1] != map[y][x])){
    num += gomap(x+1, y, my);
  }
  if(y+1 < H && (map[y+1][x] != map[y][x]))
    num += gomap(x, y+1, my);
  return num;
}

