typedef struct {
  ll from;
  ll to;
  ll cost;
} S_Edge;

ll pos2idx(ll y, ll x) { return y * W + x; }
ll idx2y(ll idx) { return idx / W; }
ll idx2x(ll idx) { return idx % W; }

void research_edges(std::vector< std::string >& grid, std::vector< std::vector<S_Edge> >& vedge)
{
  for (ll y = 0; y < H; y++) {
    for (ll x = 0; x < W; x++) {
      for (ll d = 0; d < 4; d++) {
	ll ny = y + dy[d];
	ll nx = x + dx[d];
	if (ny >= 0 && nx >= 0 && ny < H && nx < W) {
	  S_Edge edge;
	  edge.from = pos2idx(y, x);
	  edge.to   = pos2idx(ny, nx);
	  edge.cost = grid[y][x] == grid[ny][nx] ? INF : 1;
	  vedge[pos2idx(y, x)].push_back(edge);
	}
      }
    }
  }
}

ll count_path(ll y, ll x, std::vector< std::string >& grid, std::vector< std::vector<S_Edge> >& vedge)
{
  ll s = pos2idx(y, x);
  std::vector<ll> dist(V, INF);
  std::set<ll> visited;

  dist[s] = 0;

  typedef std::pair<ll, ll> P;
  std::priority_queue<P, std::vector<P>, std::greater<P> > que;

  que.push(P(dist[s], s));
  while (!que.empty()) {
    P p = que.top(); que.pop();
    ll v = p.second;
    for (auto it = vedge[v].begin(); it != vedge[v].end(); it++) {
      if (dist[it->to] > dist[it->from] + it->cost) {
	dist[it->to] = dist[it->from] + it->cost;
	que.push(P(dist[it->to], it->to));
	if (grid[idx2y(it->to)][idx2x(it->to)] == '.') {
	  visited.insert(it->to);
	  //print("visited", idx2y(it->to), idx2x(it->to));
	}
      }
    }
  }

  return (ll)visited.size();
}

int main(int argc, char* argv[])
{
  std::cin >> H >> W;
  V = H * W;

  std::vector< std::string > grid(H, std::string(W, 'x'));
  for (ll y = 0; y < H; y++) {
    std::cin >> grid[y];
  }

  std::vector< std::vector<S_Edge> > vedge(V);
  research_edges(grid, vedge);

  ll ans = 0LL;
  for (ll y = 0; y < H; y++) {
    for (ll x = 0; x < W; x++) {
      if (grid[y][x] == '.') continue;
      ll cnt = count_path(y, x, grid, vedge);
      //print(y, x, cnt);
      ans += cnt;
    }
  }

  print(ans);
  return 0;
}

