using namespace std;
char flag[400][400];
char table[400][400];
int H, W;

long white, black;
void dfs(int h, int w){
  	flag[h][w] = 1;
	if(table[h][w] == '.')
      white++;
  	else if(table[h][w] == '#')
      black++;
  	if(h > 0){
    	if((table[h][w] != table[h-1][w]) && (flag[h-1][w] != 1))
          dfs(h-1, w);
    }
  	if(h < H-1){
    	if((table[h][w] != table[h+1][w]) && (flag[h+1][w] != 1))
          dfs(h+1, w);
    }
  	if(w > 0){
    	if((table[h][w] != table[h][w-1]) && (flag[h][w-1] != 1))
          dfs(h, w-1);
    }
  	if(w < W-1){
    	if((table[h][w] != table[h][w+1]) && (flag[h][w+1] != 1))
          dfs(h, w+1);
    }
}
int main()
{
  long sum;
  cin >> H >> W;
  for(int i = 0; i < H; i++){
    for(int j = 0; j < W; j++){
      cin >> table[i][j];
    }
  }
  sum = 0;
  for(int i = 0; i < H; i++){
    for(int j = 0; j < W; j++){
      black = white = 0;
      if(flag[i][j] != 1){
      	dfs(i, j);
      	sum += black*white;
      }
    }
  }
  cout << sum << endl;

  return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n,m,vis[500*500],bcnt;
vector<int> edge[500*500];
char s[500][500];

int getnode(int x,int y)
{
	return (x-1)*m+y;
}

int dfs(int u)
{
	int res=1;
	if(s[(u-1)/m+1][(u-1)%m+1]=='.')++bcnt;
	vis[u]=true;
	for(auto v : edge[u])
	{
		if(!vis[v])res+=dfs(v);
	}
	return res;
}

int main()
{
	scanf("%d%d",&n,&m);
	for(int i=1;i<=n;++i)
	{
		scanf("%s",s[i]+1);
	}
	for(int i=1;i<=n;++i)
	{
		for(int j=1;j<=m;++j)
		{
			if(i<n && s[i][j]!=s[i+1][j])
			{
				edge[getnode(i,j)].push_back(getnode(i+1,j));
				edge[getnode(i+1,j)].push_back(getnode(i,j));
			}
			if(j<m && s[i][j]!=s[i][j+1])
			{
				edge[getnode(i,j)].push_back(getnode(i,j+1));
				edge[getnode(i,j+1)].push_back(getnode(i,j));
			}
		}
	}
	long long ans=0;
	for(int i=1;i<=n*m;++i)
	{
		if(!vis[i])
		{
			bcnt=0;
			int res=dfs(i);
			ans+=(long long)(res-bcnt)*bcnt;
		}
	}
	printf("%lld\n",ans);
}

