typedef pair<int,int> P;
typedef long long ll;

char m[405][405];
bool use[405][405];
int dx[] = {1,0,-1,0};
int dy[] = {0,1,0,-1};

void init(int h, int w) {
  for(int i = 0; i < h; i++) {
    for(int j = 0; j < w; j++) {
      use[i][j] = false;
    }
  }
}

int main() {
  int h,w;
  cin >> h >> w;

  for(int i = 0; i < h; i++) {
    string s;
    cin >> s;
    for(int j = 0; j < s.size(); j++) {
      m[i][j] = s[j];
    }
  }


  ll ans = 0;
  init(h,w);
  for(int i = 0; i < h; i++) {
    for(int j = 0; j < w; j++) {
      if(m[i][j] == '.' || use[i][j]) continue;
      int tmp = 0;
      int c = 0;
      queue<P> p;
      p.push(P(i,j));
      use[i][j] = true;
      while(!p.empty()) {
	int x = p.front().first;
	int y = p.front().second;
	if(m[x][y] == '#') tmp++;
	p.pop();
	for(int k = 0; k < 4; k++) {
	  int nx = x + dx[k];
	  int ny = y + dy[k];
	  if(nx < 0 || ny < 0 || nx >= h || ny >= w || use[nx][ny]) continue;
	  if(m[x][y] == '#' && m[nx][ny] == '.') {
	    use[nx][ny] = true;
	    p.push(P(nx,ny));
	    c++;
	    continue;
	  }
	   if(m[x][y] == '.' && m[nx][ny] == '#') {
	     use[nx][ny] = true;
	    p.push(P(nx,ny));
	    continue;
	   }
	}
      }

      ans += tmp * c;
    }
  }


  cout << ans << endl;
}

