}

template <typename T> inline void print(T x) {
	if(x < 0) putchar('-'), x = -x;
	if(x > 9) print(x / 10);
	putchar(x % 10 + '0');
}

inline void find_(int x,int y,int now){
	vis[x][y]=1;
	if(mp[x][y]==1) hei++;
	else bai++;
	for(rg int i=1;i<=4;i++){
		int tox=x+heng[i],toy=y+shu[i];
		if(tox>0&&tox<=H&&toy>0&&toy<=W&&!vis[tox][toy]&&mp[tox][toy]!=now)
			find_(tox,toy,mp[tox][toy]);
	}
	return ;
}

