      int idx = i * W + j;
      if (c[i][j] == '#') d[idx] = 0;
      else d[idx] = 1;
    }
  }
  DisjointSet ds(n);
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      if (i + 1 < H && c[i][j] != c[i + 1][j]) {
        ds.unite(W * i + j, W * (i + 1) + j);
      }
      if (j + 1 < W && c[i][j] != c[i][j + 1]) {
        ds.unite(W * i + j, W * i + j + 1);
      }
    }
  }
  int ans = 0;
  ll b[n]{};
