int main()
{
    int H, W;
    cin >> H >> W;

    vector<vector<bool>> board(H, vector<bool>(W));
    string S;
    for (int i = 0; i < H; i++)
    {
        cin >> S;
        for (int j = 0; j < W; j++)
        {
            board[i][j] = (S[j] == '#');
        }
    }

    vector<vector<bool>> visited(H, vector<bool>(W, false));

    vector<pair<int, int>> diff{
        pair<int, int>(1, 0),
        pair<int, int>(0, 1),
        pair<int, int>(-1, 0),
        pair<int, int>(0, -1)};
    queue<pair<int, int>> q;
    long long ans = 0;
    long long black, white;
    int x, new_x;
    int y, new_y;
    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            if (visited[i][j])
            {
                continue;
            }
            q.push(make_pair(i, j));
            black = 0;
            white = 0;
            while (!q.empty())
            {
                x = q.front().first;
                y = q.front().second;
                q.pop();
                if (visited[x][y])
                {
                    continue;
                }

                if (board[x][y])
                {
                    black++;
                }
                else
                {
                    white++;
                }
                visited[x][y] = true;

                for (pair<int, int> d : diff)
                {
                    new_x = x + d.first;
                    new_y = y + d.second;
                    if (new_x < 0 || new_y < 0)
                    {
                        continue;
                    }
                    if (new_x >= H || new_y >= W)
                    {
                        continue;
                    }
                    if (visited[new_x][new_y])
                    {
                        continue;
                    }

                    if (board[x][y] != board[new_x][new_y])
                    {
                        q.push(make_pair(new_x, new_y));
                    }
                }
            }
            ans += black * white;
        }
    }
    cout << ans << endl;
}

