class BIT
{
public:
  vll d;
  vll v;
  ll size;
  BIT(ll _size)
  {
    size = _size;
    d.assign(size + 1, 0);
    v.assign(size, 0);
  }
  BIT(vll vec) { copy(vec); }
  void add(ll idx, ll N)
  {
    v[idx] += N;
    idx++;
    while (idx <= size)
    {
      d[idx] += N;
      idx += LSB(idx);
    }
  }

  ll sum(ll idx = inf)
  {
    idx++;
    idx = min(idx, size);
    ll ans = 0;
    while (idx)
    {
      ans += d[idx];
      idx -= LSB(idx);
    }
    return ans;
  }

  void copy(vll vec)
  {
    size = vec.size();
    d.assign(size + 1, 0);
    v.assign(size, 0);
    REP(i, size) { add(i, vec[i]); }
  }
};

class UnionFind
{
public:
  vll arr;
  UnionFind(ll sz) : arr(sz, -1) {}
  ll root(ll node)
  {
    return arr[node] < 0 ? node : arr[node] = root(arr[node]);
  }
  ll size(ll x) { return -arr[root(x)]; }
  bool union_set(ll x, ll y)
  {
    x = root(x);
    y = root(y);
    if (x != y)
    {
      if (arr[x] < arr[y])
      {
        swap(x, y);
      }
      arr[x] += arr[y];
      arr[y] = x;
    }
    return x != y;
  }
  bool find_set(ll x, ll y) { return root(x) == root(y); }
};

class Vertex
{
