const LL INF = (1LL<<60);
const int INF_INT = 2147483647-1e6-1;
const LL mod = 1000000007ll;
const int mod_int = 1000000007;

LL H,W;
string S[400];

LL ans = 0;

void solve(){
	vector<vector<int>> used(H,vector<int>(W,0));
	auto dfs = [&](int h,int w){
		LL color[2] = {0,0};//color[0]を白のマスの数、color[1]を黒のマスの数とおく
		//pair<h,w>
		queue<pair<int,int>> q;
		q.push(pair<int,int>(h,w));
		used[h][w] = 1;
		color[(S[h][w]=='#')]++;
		while(!q.empty()){
			int y = q.front().first;
			int x = q.front().second;
			q.pop();

			auto make_next_point = [&](){
				vector<pair<int,int>> ret;
				if(y+1<H){
					if(S[y+1][x]!=S[y][x] && !used[y+1][x])ret.push_back(pair<int,int>(y+1,x));
				}
				if(y-1>=0){
					if(S[y-1][x]!=S[y][x] && !used[y-1][x])ret.push_back(pair<int,int>(y-1,x));
				}
				if(x+1<W){
					if(S[y][x+1]!=S[y][x] && !used[y][x+1])ret.push_back(pair<int,int>(y,x+1));
				}
				if(x-1>=0){
					if(S[y][x-1]!=S[y][x] && !used[y][x-1])ret.push_back(pair<int,int>(y,x-1));
				}
				return ret;
			};

			for(pair<int,int> next : make_next_point()){
				int next_y = next.first;
				int next_x = next.second;
				used[next_y][next_x] = 1;
				color[(S[next_y][next_x]=='#')]++;
				q.push(pair<int,int>(next_y,next_x));
			}
		}
		ans += color[0]*color[1];
	};

	for(int h=0;h<H;h++){
		for(int w=0;w<W;w++){
			if(!used[h][w]) dfs(h,w);
		}
	}
}

int main(){
    cin >> H >> W;
    for(int h=0;h<H;h++){
    	cin >> S[h];
    }

    solve();

	cout << ans << endl;
    return 0;
}

