PII dfs(int x, int y) {
	vis[x][y] = 1;
	PII res = MP(0, 0);
	if (g[x][y] == '#') {
		res.first += 1;
	} else {
		res.second += 1;
	}
	if (x && !vis[x - 1][y] && g[x - 1][y] != g[x][y]) {
		PII r = dfs(x - 1, y);
		res.first += r.first;
		res.second += r.second;
	}
	if (x < h - 1 && !vis[x + 1][y] && g[x + 1][y] != g[x][y]) {
		PII r = dfs(x + 1, y);
		res.first += r.first;
		res.second += r.second;
	}
	if (y && !vis[x][y - 1] && g[x][y - 1] != g[x][y]) {
		PII r = dfs(x, y - 1);
		res.first += r.first;
		res.second += r.second;
	}
	if (y < w - 1 && !vis[x][y + 1] && g[x][y + 1] != g[x][y]) {
		PII r = dfs(x, y + 1);
		res.first += r.first;
		res.second += r.second;
	}
	return res;
}

