struct UnionFind{
    vector<int> par;
    UnionFind(int N){
        par.resize(N);
        for(int i=0;i<N;i++){
            par[i] = i;
        }
    }
    void Union(int x,int y){
        par[Get(x)] = Get(y); 
    }
    bool Same(int x,int y){
        return Get(x) == Get(y);
    }
    int Get(int x){
        if(x != par[x]){
            par[x] = Get(par[x]);
        }
        return par[x];
    }
};
long DP[160000];
int Map[160000];
int Num1[160000];
int Num2[160000];
void Calc(){
	int H = rei();
	int W = rei();
	int c = 1;
	for(int i=0;i<H;i++){
		string S = res();
		for(int j=0;j<W;j++){
			if(S[j] == '#'){
				Map[i*400+j] = c++;
			}
		}
	}
	UnionFind U(160001);
	for(int i=0;i<H;i++){
		for(int j=0;j<W;j++){
			if(Map[i*400+j]){
				if(j < W-2 && Map[i*400+j+2] != 0 && Map[i*400+j+1] == 0){
					U.Union(Map[i*400+j],Map[i*400+j+2]);
				}
				if(i < H-2 && Map[(i+2)*400+j] != 0 && Map[(i+1)*400+j] == 0){
					U.Union(Map[i*400+j],Map[(i+2)*400+j]);
				}
				if(i != H-1 && j != W-1 && Map[(i+1)*400+j+1] != 0 && (Map[i*400+j+1] == 0 || Map[(i+1)*400+j] == 0)){
					U.Union(Map[i*400+j],Map[(i+1)*400+j+1]);	
				}
				if(i != H-1 && j != 0 && Map[(i+1)*400+j-1] != 0 && (Map[i*400+j-1] == 0 || Map[(i+1)*400+j] == 0)){
					U.Union(Map[i*400+j],Map[(i+1)*400+j-1]);	
				}
			}
		}
	}
	for(int i=1;i<c;i++){
		Num1[U.Get(i)]++;
	}
	for(int i=0;i<H;i++){
		for(int j=0;j<W;j++){
			if(Map[i*400+j] == 0){
				if(i != 0 && Map[(i-1)*400+j]){
					Num2[U.Get(Map[(i-1)*400+j])]++;
				}
				else if(i != H-1 && Map[(i+1)*400+j]){
					Num2[U.Get(Map[(i+1)*400+j])]++;
				}
				else if(j != 0 && Map[i*400+j-1]){
					Num2[U.Get(Map[i*400+j-1])]++;
				}
				else if(j != W-1 && Map[i*400+j+1]){
					Num2[U.Get(Map[i*400+j+1])]++;
				}
			}
		}
	}
	long ans = 0;
	for(int i=1;i<c;i++){
		ans += Num1[i]*Num2[i];
	}
	cout << ans << endl;
}
int main(int argc,char** argv){
	ios::sync_with_stdio(false), cin.tie(0);
	cout.tie(0); Calc(); return 0;
}

