struct UnionFind {
    vector<int> par;
    UnionFind(int n) :par(n, -1) { }
    void init(int n) { par.assign(n, -1); }
    int root(int x) {
        if (par[x] < 0) return x;
        else return par[x] = root(par[x]);
    }
    bool connect(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;
        return true;
    }
    int size(int x) {
        return -par[root(x)];
    }
};

int main() {
    cin.tie(0);
    cout.tie(0);
    ios::sync_with_stdio(false);
    int h, w;
    cin >> h >> w;
    int n = h * w;
    string s[h];
    UnionFind uf(n);
    for(int i=0;i<h;i++){
    	cin >> s[i];
    }
    for(int i=0;i<h;i++){
    	for(int j=1;j<w;j++){
    		if(s[i][j] != s[i][j-1]) uf.connect(i * w + j, i * w + j - 1);
     	}
    }
    for(int i=1;i<h;i++){
    	for(int j=0;j<w;j++){
    		if(s[i][j] != s[i-1][j]) uf.connect(i * w + j, (i-1) * w + j);
    	}
    }
    vector<vector<int> > cnt(n, vector<int> (2, 0));
    for(int i=0;i<h;i++){
    	for(int j=0;j<w;j++){
    		if(s[i][j] == '#'){
    			cnt[uf.root(i*w+j)][1]++;
    		}else{
    			cnt[uf.root(i*w+j)][0]++;
    		}
    	}
    }
    ll ans = 0;
    for(int i=0;i<n;i++){
    	if(uf.par[i] < 0){
    		ans += cnt[i][0] * cnt[i][1];
    	}
    }
    cout << ans << endl;
    return 0;
}

