void solve(long long H, long long W, vector<string> S){

    for(size_t i = 0; i < 400; i++)
    {
        fill(used[i],used[i]+400,false);
    }

    long long ans=0;

    for(size_t i = 0; i < S.size(); i++)
    {
        for(size_t j = 0; j < S[i].size(); j++)
        {
            if(used[i][j]==true){
                continue;
            }
            long long b=0,w=0;
            queue<pair<int,int>> q;
            q.push(make_pair(i,j));
            used[i][j]=true;
            while(!q.empty()){
                auto a=q.front();q.pop();
                switch(S[a.first][a.second]){
                    case '.':
                        w++;
                        break;
                    case '#':
                        b++;
                        break;
                }

                for(size_t ii = 0; ii < 4; ii++)
                {
                    pair<int,int> bb=a;
                    bb.first+=tonari[ii][0];
                    bb.second+=tonari[ii][1];
                    if(bb.first<0||bb.first>H-1||bb.second<0||bb.second>W-1){
                        continue;
                    }
                    if(used[bb.first][bb.second]){
                        continue;
                    }
                    if(S[bb.first][bb.second]!=S[a.first][a.second]){
                        used[bb.first][bb.second]=true;
                        q.push(bb);
                    }

                }
            }
            ans+=b*w;
        }
    }
    cout<<ans<<endl;
}

