				tree.unite(i * W + i2, i * W + W + i2);
			}
			if (i2 != W - 1 && S[i][i2] != S[i][i2 + 1]) {
				tree.unite(i * W + i2, i * W + 1 + i2);
			}
		}
	}
	map<int, pair<int, int>>mp;
	rep(i, 0, H * W) {
		if(S[i / W][i % W] == '#')mp[tree.root(i)].first++;
		else mp[tree.root(i)].second++;
	}
	for (auto m : mp) {
		ans += m.second.first * m.second.second;
	}
	printf("%lld\n", ans);
	return 0;
}

