struct UnionFind {
	vector<pii> data_black;
	UnionFind(int size, vector<string> s) : data_black(size, pii(-1,0)) {
		for (int l = 0; l < size; l++)
		{
			if (s[int_to_pair((ll)l).first][int_to_pair((ll)l).second] == '#') {
				data_black[l].second = 1;
			}
		}
	}
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data_black[y].first < data_black[x].first) swap(x, y);
			data_black[x].first += data_black[y].first;
			data_black[x].second += data_black[y].second;
			data_black[y].first = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data_black[x].first < 0 ? x : data_black[x].first = root(data_black[x].first);
	}
	int size(int x) {
		return -data_black[root(x)].first;
	}
	int size_black(int x) {
		return data_black[root(x)].second;
	}
};

int H, W;
vector<string> S;

int main() {
	cin >> H >> W;
	for (int i = 0; i < H; i++)
	{
		string tmpS;
		cin >> tmpS;
		S.push_back(tmpS);
	}
	const int nd = 2;
	pii d[nd] = { {-1,0}, {0,-1} };
	set_whole_size_pair(pii(H, W));
	UnionFind uf(H*W, S);
	for (int i = 0; i < H; i++)
	{
		for (int j = 0; j < W; j++)
		{
			char anotherc;
			if (S[i][j] == '#') {
				anotherc = '.';
			}
			else {
				anotherc = '#';
			}
			for (int k = 0; k < nd; k++)
			{
				const int ti = i + d[k].first, tj = j + d[k].second;
				if (0 <= ti and 0 <= tj and S[ti][tj] == anotherc) {
					uf.unionSet(pair_to_int(pii(i, j)), pair_to_int(pii(ti, tj)));
				}
			}
		}
	}
	unordered_set<int> us;
	for (int l = 0; l < H*W; l++)
	{
		us.insert(l);
	}
	ll ans = 0;
	for (int i = 0; i < H; i++)
	{
		for (int j = 0; j < W; j++)
		{
			const int ij = pair_to_int(pii(i, j));
			if (us.find(uf.root(ij)) == us.end())
				continue;
			int nb = uf.size_black(ij), nw = uf.size(ij) - nb;
			ans += nb * nw;
			us.erase(uf.root(ij));
		}
	}
	cout << ans << endl;
	return 0;
}

