int dx[4]={-1,1,0,0};
int dy[4]={0,0,-1,1};
char s[401][401];
bool used[401][401]={};

int bfs(int x,int y){
    int w=0;int b=0;
    queue<P> que;
    que.push({x,y});
    dist[x][y]=0;
    used[x][y]=true;
    while(!que.empty()){
        P q=que.front(); que.pop();
        if(s[q.first][q.second]=='.') w++;
        else b++;
        for(int i=0;i<4;i++){
            int nx=q.first+dx[i]; int ny=q.second+dy[i];
            if(nx>=0&ny>=0&&nx<H&&ny<W){
                if(used[nx][ny]==true) continue;
                int parity=dist[q.first][q.second]%2;
                if(parity==0&&s[nx][ny]=='#') continue;
                if(parity==1&&s[nx][ny]=='.') continue;
                dist[nx][ny]=dist[q.first][q.second]+1;
                used[nx][ny]=true;
                que.push({nx,ny});
            }
        }
    }
    return w*b;
}

