const char CHAR_STR = '#';
const char CHAR_END = '.';

const int DIR_X[] = { 1, 0, -1,  0 };
const int DIR_Y[] = { 0, 1,  0, -1};

typedef struct { int x; int y; } Point;

typedef struct
{
	int  h;
	int  w;
	char map [400][400];
	char flag[400][400];
} Parameter;

int count_to_goal(Parameter * p, int x, int y)
{
	std::list<Point> stack;
	int num_str = 0;
	int num_end = 0;

	if ( p->flag[y][x] ) return 0;

	stack.push_back((Point){x, y});
	p->flag[y][x] = 1;

	for (; stack.size(); )
	{
		auto cur = stack.front();
		stack.pop_front();

		if ( p->map[cur.y][cur.x] == CHAR_STR ) num_str++;
		else num_end++;

		for (auto i = 0; i < 4; i++)
		{
			auto nex = cur;
			nex.x += DIR_X[i];
			nex.y += DIR_Y[i];

			if ((nex.x < 0) || (nex.x >= p->w) || (nex.y < 0) || (nex.y >= p->h))
				continue;
			if (p->flag[nex.y][nex.x])
				continue;
			if (p->map [nex.y][nex.x] == p->map [cur.y][cur.x] )
				continue;

			stack.push_back(nex);
			p->flag[nex.y][nex.x] = 1;
		}
	}

	return num_str * num_end;
}

int main(int argc, char * argv[])
{
	Parameter p;
	int ret = 0;

	std::cin >> p.h;
	std::cin >> p.w;
	for (int y = 0; y < p.h; y++)
	{
		for (int x = 0; x < p.w; x++)
		{
			std::cin >> p.map[y][x];
			p.flag[y][x] = 0;
		}
	}

	for (int y = 0; y < p.h; y++)
	{
		for (int x = 0; x < p.w; x++)
		{
			if (p.flag[y][x] == 0)
				ret += count_to_goal(&p, x, y);
		}
	}

	std::cout << ret;

	return 0;
}

