  vector<string> S(h);
  rep(i,h) cin >> S[i];

  UnionFind tree(h*w);
  rep(y,h) rep(x,w) {
    if (S[y][x] == '#') {
      int ind = w*y + x;
      for (int i = 4; i < 8; ++i) {
        int nx = x + dx[i];
        int ny = y + dy[i];
        if (nx < 0 || ny < 0 || nx >= w || ny >= h) continue;
        if (S[ny][nx] == '#' && (S[ny][x] == '.' || S[y][nx] == '.')) {
          int ind2 = w*ny + nx;
          if (!tree.same(ind, ind2)) tree.merge(ind, ind2);
        }
      }
    }
  }

  vector<vector<int> > A(h*w);
  rep(y,h) rep(x,w) {
    if (S[y][x] == '#') {
      int ind = w*y + x;
      rep(i,4) {
        int nx = x + dx[i];
