            if(i!=h-1){
                if(s[i][j]!=s[i+1][j]){
                    unite(par,rank,i*w+j,(i+1)*w+j);
                }
            }
            if(j!=0){
                if(s[i][j]!=s[i][j-1]){
                    unite(par,rank,i*w+j,i*w+j-1);
                }
            }
            if(j!=w-1){
                if(s[i][j]!=s[i][j+1]){
                    unite(par,rank,i*w+j,i*w+j+1);
                }
            }
        }
