#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

#define WHITE 0
#define GRAY 1
#define BLACK 2
#define MAX 400

ll h, w;

ll d[MAX][MAX], color[MAX][MAX];

void dfs_visit(ll x, ll y, vector<string> s) {
  ll i, j;
  color[x][y] = GRAY;
  for (i = 0; i < h; ++i) {
    for (j = 0; j < w; ++j) {
      if (color[i][j] != WHITE) {
        continue;
      }
      if (!((i == x - 1 && j == y) || (i == x + 1 && j == y) ||
            (i == x && j == y - 1) || (i == x && j == y + 1))) {
        continue;
      }
      color[i][j] = GRAY;
      if (s[x][y] == '#' && s[i][j] == '.') {
        d[x][y] += 1;
      }
      dfs_visit(i, j, s);
    }
  }
  color[x][y] = BLACK;
}

void initialize_color() {
  ll i, j;
  for (i = 0; i < h; ++i) {
    for (j = 0; j < w; ++j) {
      color[i][j] = WHITE;
    }
  }
}

void dfs(vector<string> s) {
  ll i, j;
  for (i = 0; i < h; ++i) {
    for (j = 0; j < w; ++j) {
      d[i][j] = 0;
    }
  }
  for (i = 0; i < h; ++i) {
    for (j = 0; j < w; ++j) {
      initialize_color();
      dfs_visit(i, j, s);
    }
  }
}

