            m2[cnt] = m[i][j];
            cnt++;
        }
    }

    init(h * w);

    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            if(i != h - 1){
                if(m[i][j] != m[i+1][j]){
                    unite(i * w + j, (i+1) * w + j);
                }
            }
            if(j != w - 1){
                if(m[i][j] != m[i][j+1]){
                    unite(i * w + j, i * w + j + 1);
                }
            }
        }
    }

    rep(i, h * w){
        visited[i] = 0;
    }

    ll ans = 0;
    rep(i, h * w){
        int k = root(i);
        if(visited[k] == 0){
            ans += nb[k] * nw[k];
            visited[k] = 1;
        }
    }

    cout << ans << "\n";
    return 0;
}

