                        count[group[i][j]].first++;
                        count[group[i][k - 1]].first--;
                    } else if (S[i][k - 1] == '#') {
                        count[group[i][j]].second++;
                        count[group[i][k - 1]].second--;
                    }
                    group[i][k - 1] = group[i][j];
                    k--;
                }
            } else if (j > 0 && S[i][j] != S[i][j - 1]) {
                group[i][j] = group[i][j - 1];
