  rep(h, H-1){
    rep(w, W-1){
      if(mapdata[h][w] != mapdata[h][w+1]){
        UF.unite(to_n(h, w), to_n(h, w+1));
      }
      if(mapdata[h][w] != mapdata[h+1][w]){
        UF.unite(to_n(h, w), to_n(h+1, w));
      }
    }
  }

  //最終行・最終列を処理
  //最終行
  rep(w, W-1){
