      if (ny < 0 || ny >= h || nx < 0 || ny >= w) continue;
      if (b[y][x] == b[ny][nx]) continue;
      if (dist[ny][nx] != INF) continue;
      dist[ny][nx] = dist[y][x] + 1;
      kind[ny][nx] = 1;
      que.push({ny, nx});
    }
  }

  return ans;
}


int rec(int y, int x, char c, int t) {
  ok[y][x] = true;
  kind[y][x] = t;
  int ret = 0;

  rep (i, 4) {
    int ny = y + dy[i], nx = x + dx[i];
    if (ny < 0 || ny >= h || nx < 0 || nx >= w) continue;
    if (c == b[ny][nx]) continue;
    if (ok[ny][nx]) continue;
    int cost = (b[ny][nx] == '.' ? 1 : 0);
    ret += rec(ny, nx, b[ny][nx], t) + cost;
  }

  return ret;
}

