        REP(j, w) {
            cin >> s[i][j];
        }
    }

    bool memo[400][400];
    REP(i, h) {
        REP(j, w) {
            memo[i][j] = false;
        }
    }

    ll sum = 0;
    REP(i, h) {
        REP(j, w) {
            if (memo[i][j] == false) {
                P pair = mp(0, 0);
                search(s, memo, pair, i, j, h, w);
                sum += (pair.first * pair.second);
            }
        }
    }

    cout << sum << '\n';
}

