{
	vector<int> p;
	vector<int> s;
	UnionFind(int n) : p(n),s(n,1) {
		for (int i = 0; i < n; i++) {
			p[i] = i;
		}
	}

	int root(int x) {
		int px = p[x];
		if (px == x) {
			return x;
		}

		p[x] = root(px);
		return p[x];
	}


	void unite(int x, int y) {
		int rx = root(x);
		int ry = root(y);

		if (rx == ry) {
			return;
		}

		p[rx] = ry;
		s[ry] += s[rx];
		return;


	}
	bool isSame(int x, int y) {
		return root(x) == root(y);
	}

	int size(int x) {
		return s[root(x)];
	}
};

