using namespace std;
int64_t MAXH = 410;
int64_t H, W, ans = 0, black = 0, white = 0;
vector<vector<bool>> Black(MAXH, vector<bool>(MAXH, 0));
vector<vector<bool>> Checked(MAXH, vector<bool>(MAXH, 0));

void search(int64_t h, int64_t w, bool curBlack)
{
  if (h < 0 || h >= H || w < 0 || w >= W)
    return;
  if (Checked.at(h).at(w))
    return;
  if (curBlack && !Black.at(h).at(w) || !curBlack && Black.at(h).at(w))
    return;
  Checked.at(h).at(w) = true;
  curBlack ? black++ : white++;
  search(h + 1, w, !curBlack);
  search(h - 1, w, !curBlack);
  search(h, w + 1, !curBlack);
  search(h, w - 1, !curBlack);
}

int main()
{
  char c;
  cin >> H >> W;
  for (int h = 0; h < H; h++)
  {
    for (int w = 0; w < W; w++)
    {
      cin >> c;
      if (c == '#')
        Black.at(h).at(w) = 1;
    }
  }
  for (int h = 0; h < H; h++)
  {
    for (int w = 0; w < W; w++)
    {
      if (Black.at(h).at(w) && !Checked.at(h).at(w))
      {
        black = 0;
        white = 0;
        search(h, w, 1);
        ans += black * white;
      }
    }
  }
  cout << ans << endl;
}

