int main() {
  int H, W;
  cin >> H >> W;
  vector<vector<bool>> grid;
  for (int i = 0; i < H; ++i) {
    grid.emplace_back();
    for (int j = 0; j < W; ++j) {
      char c;
      cin >> c;
      grid.back().emplace_back(c == '#');
    }
  }

  vector<pair<int, int>> directions{
    {0, 1},
    {0, -1},
    {1, 0},
    {-1, 0},
  };

  int64_t count = 0;
  vector<vector<bool>> seen(H, vector<bool>(W));
  for (int i = 0; i < H; ++i) {
    for (int j = 0; j < W; ++j) {
      if (!seen[i][j] && grid[i][j]) {
        seen[i][j] = true;
        deque<pair<int, int>> bfs;
        bfs.emplace_back(i, j);
        bool next = false;
        int black = 1;
        int white = 0;
        for (; !bfs.empty(); next = !next) {
          auto&& cell = bfs.front();
          auto h = cell.first;
          auto w = cell.second;
          bfs.pop_front();
          for (auto&& dir : directions) {
            auto next_h = h + dir.first;
            auto next_w = w + dir.second;
            if (0 <= next_h && next_h < H && 0 <= next_w && next_w < W && !seen[next_h][next_w] && grid[next_h][next_w] == next) {
              bfs.emplace_back(next_h, next_w);
              seen[next_h][next_w] = true;
              if (next) ++black;
              else ++white;
            }
          }
        }
        count += black * white;
      }
    }
  }
  cout << count << endl;
}

