int finalans = 0;

//UFからアクセスしたいのでグローバルにおく
int H, W;
//mapdata[1~H][1~W] でアクセス
vector<string> mapdata;

//idxをnode番号にする関数
//番兵を含めたidx(0~H+1, 0~W+1)を入れること
int to_n(int h, int w){
  return (W+2) * h + w;
};

//Union-Find
//0-indexed 注意！！
struct UnionFind {
  vector< int > data;

  UnionFind(int sz) {
    data.assign(sz, -1); //ノードが属する根の番号を格納（根の場合はマイナス要素数を格納）
  }

  //併合　成功したらtrue, 既に同じ木ならfalse
  bool unite(int x, int y) {
    x = find_root(x), y = find_root(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  bool isSameGroup(int x, int y){
    x = find_root(x), y = find_root(y);
    if(x == y) return true;
    else return false;
  }

  //ノードが属する根の番号を返す（引数が根だった場合はその番号をそのまま帰す）
  int find_root(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find_root(data[k]));
  }

  //ノードが属する木に属するノードの数を返す
  int count(int k) {
    return (-data[find_root(k)]);
  }

  //木の数（接続していないグラフの数）を返す
  //根となっているノード（data[k]が負のもの）を数えるだけ
  int count_trees() {
    int ans = 0;
    rep(d_idx, data.size()){
      if (data[d_idx] < 0){
        ans += 1;
      }
    }
    return ans;
  }

  //今回だけの改造
  //「根」を見つけたら、その根が属する木に属するノード数を求める
  //ノード数が1なら、どこにも行けないマス、もしくは番兵なので無視
  //2以上なら、属する黒ノードの数、白ノードの数を確認する
  void solve() {
    vector<int> rootlist;
    REP(h, 1, H+1){
      REP(w, 1, W+1){
        int num = data[to_n(h,w)];
        if (num < -3){
          rootlist.PB(to_n(h, w));
        }
        else if (num <= -2){ //-3<=x<=-2 つまりx=-2 or -3
          //ノード数が2なら組合せは1
          //ノード数が3なら組合せは2にきまっている
          finalans += num*(-1) - 1;
        }
      }
    }
    int black = 0;
    int white = 0;
    for (int eachroot : rootlist){ //to_n済み
      black = 0;
      white = 0;
      //根の分をカウント
      int root_h = eachroot / (W+2);
      int root_w = eachroot - (root_h * (W+2));
      if (mapdata[root_h][root_w] == '#'){
        black += 1;
      }
      else{
        white += 1;
      }
      //根以外を入れる
      REP(h, 1, H+1){
        REP(w, 1, W+1){
          if (data[to_n(h, w)] == eachroot){
            if (mapdata[h][w] == '#'){
              black += 1;
            }
            else{
              white += 1;
            }
          }
        }
      }
      finalans += black * white;
    }
  }

};

// ----- library end ----- //



int main() {

  H = ii();
  W = ii();


  //両側に番兵をおく
  mapdata.PB(string(W+2, 'w'));
  rep(i, H){
    mapdata.PB("w" + is() + "w");
  }
  mapdata.PB(string(W+2, 'w'));

  //Union-Find
  UnionFind UF( (H+2) * (W+2) ); //引数はノード数


  //4隣接（上下左右）
  vector<vector<int> > adj_4 = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

  REP(h, 1, H+1){
    REP(w, 1, W+1){
      for (auto each_vec : adj_4){
        int tg_h = h + each_vec[0];
        int tg_w = w + each_vec[1];
        if(mapdata[h][w] != mapdata[tg_h][tg_w] && mapdata[tg_h][tg_w] != 'w'){
          UF.unite(to_n(h, w), to_n(tg_h, tg_w));
        }
      }
    }
  }

  UF.solve();
  oi(finalans); br();


//  UF.unite(x, y);





// -- main() end -- //
}

