using namespace std;
typedef long long ll;
ll par[160005],c[160005];
ll a[160005],b[160005];
void init(int x){
  for(int i=0;i<x;i++){
    par[i]=i;
    c[i]=1;
  }
}
ll root(int x){
  if(par[x]==x){
    return x;
  }
  return par[x]=root(par[x]);
}
void unite(int x,int y){
  x=root(x);
  y=root(y);
  if(x==y){
    return;
  }
  par[x]=y;
  c[y]+=c[x];
  b[y]+=b[x];
}

int main(){
  int h,w;cin >> h >> w;
  vector<string> s(h);
  init(h*w);
  for(int i=0;i<h;i++){
    cin >> s[i];
  }
  for(int i=0;i<h;i++){
    for(int j=0;j<w;j++){
      if(s[i][j]=='#'){
        b[i*w+j]=1;
      }
    }
  }
  for(int i=0;i<h;i++){
    for(int j=0;j<w;j++){
      if(i!=h-1){
        if(s[i][j]!=s[i+1][j]){
          unite(i*w+j,(i+1)*w+j);
        }
      }
      if(j!=w-1){
        if(s[i][j]!=s[i][j+1]){
          unite(i*w+j,i*w+j+1);
        }
      }
    }
  }
  ll ans=0;
  for(int i=0;i<h*w;i++){
    if(root(i)==i){
      ans+=b[i]*(c[i]-b[i]);
    }
  }
  cout << ans << endl;
}

