using namespace std;
typedef long long ll;
#define mod 1000000007

typedef pair<int,int> P;

const int MAX_N=400;

const int di[]={1,0,-1,0};
const int dj[]={0,1,0,-1};

bool color[MAX_N][MAX_N];
int H,W;

char ch[MAX_N+1];

void input(){
    cin>>H>>W;
    for(int i=0;i<H;i++){
        cin>>ch;
        for(int j=0;j<W;j++){
            color[i][j]=(ch[j]=='#');
        }
    }
}

bool isin_(int i, int j){
    return i>=0 && i<H && j>=0 && j<W;
}

bool check_(int i,int j, int d){
    int ni=i+di[d];
    int nj=j+dj[d];
    if(!isin_(ni,nj)) return false;
    if(color[i][j]==color[ni][nj]) return false;
    return true;
}

bool used[MAX_N][MAX_N];

ll solve(){
    ll ans=0;
    ll b=0,w=0;
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            if(used[i][j]) continue;
            b=0;
            w=0;
            queue<P> que;
            used[i][j]=true;
            que.push(P(i,j));
            while(!que.empty()){
                P p=que.front();
                que.pop();
                int ci=p.first,cj=p.second;
                if(color[ci][cj]) b++;
                else w++;
                for(int d=0;d<4;d++){
                    if(!check_(ci,cj,d)) continue;
                    int ni=ci+di[d],nj=cj+dj[d];
                    if(used[ni][nj]) continue;
                    used[ni][nj]=true;
                    que.push(P(ni,nj));
                }
            }
            ans+=b*w;
        }
    }
    return ans;
}

int main(){
    input();
    ll ans=solve();
    cout<<ans<<endl;
}

#include <bits/stdc++.h>
using namespace std;
using P = pair<int, int>;

int main() {
  int h, w;
  int ans = 0;
  cin >> h >> w;
  vector<string> g(h);
  vector<vector<bool>> seen(h, vector<bool>(w));
  for(int i=0;i<h;i++) cin >> g[i];
  int white = 0, black = 0;
  for(int i=0;i<h;i++) {
    for(int j=0;j<w;j++) {
      if(seen[i][j]) continue;
      queue<P> que;
      que.emplace(make_pair(i, j));
      while(!que.empty()) {
        P p = que.front();que.pop();
        if(seen[p.first][p.second]) continue;
        seen[p.first][p.second] = true;
        char c;
        if(g[p.first][p.second] == '.') {
          c = '#';
          white++;
        }
        else {
          c = '.';
          black++;
        }
        if(p.first != 0 && !seen[p.first-1][p.second]) {
          if(g[p.first-1][p.second] == c) que.emplace(make_pair(p.first-1, p.second));
        }
        if(p.first != h-1 && !seen[p.first+1][p.second]) {
          if(g[p.first+1][p.second] == c) que.emplace(make_pair(p.first+1, p.second));
        }
        if(p.second != 0 && !seen[p.first][p.second-1]) {
          if(g[p.first][p.second-1] == c) que.emplace(make_pair(p.first, p.second-1));
        }
        if(p.second != w-1 && !seen[p.first][p.second+1]) {
          if(g[p.first][p.second+1] == c) que.emplace(make_pair(p.first, p.second+1));
        }
      }
      ans += black * white;
      black = 0;
      white = 0;
    }
  }
  cout << ans << endl;
}

