      if (s[j] == '#')
      {
        map[i][j] = 0;
      }
      else
      {
        map[i][j] = 1;
      }
    }
  }

  UnionFind tree(h * w);

  REP(i, h)
  {
    REP(j, w)
    {
      if (j < w - 1)
      {
        if (map[i][j] != map[i][j + 1])
        {
          tree.merge(i * w + j, i * w + j + 1);
        }
      }

      if (i < h - 1)
      {
        if (map[i][j] != map[i + 1][j])
        {
          tree.merge(i * w + j, (i + 1) * w + j);
        }
      }
    }
  }

  return;

  int a[16000] = {};
  int b[16000] = {};

  REP(i, h)
  {
    REP(j, w)
    {
      int r = tree.root(i * w + j);
      if (map[i][j] == 0)
      {
        a[r]++;
      }
      else
      {
        b[r]++;
      }
    }
  }

  int result = 0;

  REP(i, h * w)
  {
    result += a[i] * b[i];
  }

  cout << result << endl;
}

