  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      char tmp;
      cin >> tmp;
      s[i][j] = tmp;
    }
  }
  int di[4] = {+1, 0, -1, 0};
  int dj[4] = {0, +1, 0, -1};
  long long ans = 0;
  vector<vector<bool>> ckd(h, vector<bool>(w, false));
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (ckd[i][j]) {
        continue;
      }
      stack<pair<int, int>> stk;
      int blk = 0;
      int wht = 0;
      stk.push({i, j});
      ckd[i][j] = true;
      while (!stk.empty()) {
        pair<int, int> crr = stk.top();
        char crrc = s[crr.first][crr.second];
        stk.pop();
        if (crrc == '#') {
