void dfs(int u, int color){
    marked[u] = true;

    int ii = u / w;
    int jj = u % w;
    qtd[comp_num][color]++;

    for(int i = 0 ; i < D ; i++){
        int xi = vi[i] + ii;
        int xj = vj[i] + jj;

        if(ok(xi, xj)){
            int v = xi * w + xj;

            if(tab[xi][xj] == colors[!color] && !marked[v]){
                dfs(v, !color);
            }
        } 
    }
}

