int a[401][401];
int H,W;

int used[401][401];
int dx[4]={1,-1,0,0};
int dy[4]={0,0,1,-1};

bool isin_(int i, int j){
    return i >= 0 && i < H && j >= 0 && j < W;
}

bool check_(int i, int j, int d){
    int ni = i + dx[d];
    int nj = j + dy[d];
    if(!isin_(ni, nj)) return false;
    if(a[i][j] == a[ni][nj]) return false;
    return true;
}

int solve() {
    ll ans = 0,b=0,w=0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (used[i][j]) continue;
            b = 0, w = 0;//b-black w-WHite
            used[i][j] = 1;
            queue<pair<int,int> > q;
            q.push({i, j});
            while (!q.empty()) {
                pair<int, int> r = q.front();
                q.pop();
                int x = r.first;
                int y = r.second;
                if (a[x][y]) b++;
                else w++;
                for (int d = 0; d < 4; d++) {
                    if (!check_(x, y, d)) continue;//invalid move
                    int ni = x + dx[d], nj = y+ dy[d];
                    if (used[ni][nj]) continue;
                    used[ni][nj] = 1;
                    q.push({ni,nj});
                }
            }
            ans += b * w;
        }
    }
    return ans;
}

int run() {
