    for(int i = 0; i < H; ++i){
        scanf("%s", ch);
        for(int j = 0; j < W; ++j){
            a[i][j] = (ch[j] == '#');
        }
    }
    memset(used,0,sizeof(used));
    ll ans=solve();
    cout<<ans;
}

