	int  get_dist(Point p){return dist[p.h][p.w];}
	int  set_dist(Point p,int i){dist[p.h][p.w]=i;}


	void bfs(){
		while(! que.empty()){
		Point p=que.front();p.pop();	
		for(auto&& u:near){
		Point q=p+u;
		if(in_board(q) && get_char(q)=='.' &&get_dist(q)==-1){
			set_dist(q,get_dist(p)+1);
			que.push(q);
