struct union_find_tree {
    std::vector<int> par, rank;
    union_find_tree(){}
    union_find_tree(int size)
    {
        par=std::vector<int>(size);
        rank=std::vector<int>(size);
        for(int i=0; i<size; ++i) par[i]=i;
    }
    int root(int x)
    {
        if (x==par[x]) return x;
        return par[x]=root(par[x]);
    }
    void unite(int x, int y)
    {
        x=root(x);
        y=root(y);
        if (x==y) return;
        if (rank[x]<rank[y]) {
            par[x]=y;
        }
        else {
            par[y]=x;
            if (rank[x]==rank[y]) ++rank[x];
        }
    }
    bool same(int x, int y)
    {
        return root(x)==root(y);
    }
};


int main()
{
    int n, m; cin>>n>>m;
    vector<string> s(n);
    for(auto& e: s) cin>>e;

    union_find_tree ut(n*m);

#define rep(i, n) for(int i=0; i<n; ++i)
    int dr[4]={-1, 0, 1, 0};
    int dc[4]={0, -1, 0, 1};
    rep(i, n) rep(j, m) if (s[i][j]=='#') rep(k, 4) {
        int r=i+dr[k], c=j+dc[k];
        if (r<0 || r>=n || c<0 || c>=m || s[r][c]!='.') continue;
        ut.unite(i*m+j, r*m+c);
    }

    map<int, int> b, w;
    rep(i, n) rep(j, m) (s[i][j]=='#' ? b : w)[ut.root(i*m+j)]++;

    long res=0;
    for(auto& e: b) res+=e.second*w[e.first];
    cout<<res<<endl;
}

