SINT64 cnt = 0;

SINT64 dfs(SINT64 x, SINT64 y) {
	SINT64 buf = 0;
	SINT64 a;
	SINT64 b;
	road[x][y] = 1;

	a = x;b = y;
	if (a != 0) {
		a--;
		if ((data[a][b] != data[x][y]) && (road[a][b] == 0)) {
			if (data[a][b] == 0)buf++;
			if (data[a][b] == 1) {
				gg[a][b] = 1; cnt++;
			}
			buf += dfs(a,b);
		}
	}

	a = x;b = y;
	if (b != 0) {
		b--;
		if ((data[a][b] != data[x][y]) && (road[a][b] == 0)) {
			if (data[a][b] == 0)buf++;
			if (data[a][b] == 1) {
				gg[a][b] = 1; cnt++;
			}
			buf += dfs(a,b);
		}
	}

	a = x;b = y;
	if (a != H-1) {
		a++;
		if ((data[a][b] != data[x][y]) && (road[a][b] == 0)) {
			if (data[a][b] == 0)buf++;
			if (data[a][b] == 1) {
				gg[a][b] = 1; cnt++;
			}
			buf += dfs(a,b);
		}
	}

	a = x;b = y;
	if (b != W-1) {
		b++;
		if ((data[a][b] != data[x][y]) && (road[a][b] == 0)) {
			if (data[a][b] == 0)buf++;
			if (data[a][b] == 1) {
				gg[a][b] = 1; cnt++;
			}
			buf += dfs(a,b);
		}
	}

	return buf;

}

int main() {

	cin >> H;
	cin >> W;

	vector<Pll> root;

	rep(i,0,H) {
		string s;
		cin >> s;
		rep(j,0,W) {
			if (s[j] == '#') {
				data[i][j] = 1;
