using namespace std;
typedef long long ll;
typedef pair<int,int> P;

int h,w;
char field[500][500];
vector<P> bl;

int dx[] = {0,1,0,-1};
int dy[] = {1,0,-1,0};

bool isSearched[500][500];

ll cntb, cntw;

void dfs(int nh, int nw, char pc){
	if(isSearched[nh][nw]) return;
	if(field[nh][nw] == pc) return;
	if(field[nh][nw] == '#') cntb++;
	else cntw++;
	isSearched[nh][nw] = true;
	for (int i = 0;i < 4;i++){
		int nexh = nh+dy[i], nexw = nw+dx[i];
		if(nexh >= 0 && nexw >= 0 && nexh < h && nexw < w) dfs(nh+dy[i], nw+dx[i], field[nh][nw]);
	}
	return;
}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> h >> w;

	for (int i = 0;i < h;i++){
		for (int j = 0;j < w;j++){
			cin >> field[i][j];
			if(field[i][j] == '#') bl.push_back(P(i,j));
		}
	}

	ll ans = 0;

	for (int bli = 0;bli < bl.size();bli++){
		if(isSearched[bl[bli].first][bl[bli].second]) continue;
		int nh = bl[bli].first, nw = bl[bli].second;
		cntb = cntw = 0;
		dfs(nh,nw,'.');
		ans += cntb*cntw;
	}

	cout << ans << endl;

	return 0;

}

