using namespace std;

int main(){
    int h, w;
    cin >> h >> w;
    vector<vector<char>> grid(h+2, vector<char>(w+2, '#'));
    vector<vector<int>> count(h+2, vector<int>(w+2, 0));
    for(int i=1; i<=h; i++){
        for(int j=1; j<=w; j++){
            cin >> grid[i][j];
        }
    }
    vector<pair<int,int>> dx = {{-1,0}, {0,-1}, {1,0}, {0,1}};
    for(int i=1; i<=h; i++){
        for(int j=1; j<=w; j++){
            if(grid[i][j] == '.'){
                continue;
            }
            for(auto k : dx){
                if(grid[i + k.first][j + k.second] == '.'){
                    count[i + k.first][j + k.second]++;
                }
            }
        }
    }
    ll ans = 0;
    for(int i=1; i<=h; i++){
        for(int j=1; j<=w; j++){
            if(grid[i][j] == '.'){
                continue;
            }
            int a = 0;
            for(auto k : dx){
                a = max(a, count[i + k.first][j + k.second]);
            }
            for(auto k : dx){
                if(count[i + k.first][j + k.second] > 0){
                    count[i + k.first][j + k.second] = a;
                }
            }
        }
    }
    for(auto i : count){
        for(auto j : i){
            ans += j;
        }
    }

    cout << ans << endl;

    return 0;
}

