_point lst[160505];
__attribute__((optimize("-O3"))) inline void BFS(_point s)
{
	register int front=0,rear=0;
	lst[rear++]=s;
	while(front<rear)
	{
		_point p=lst[front++];
		_point np;
		for(register int i=0;i<4;i++)
		{
			np.x=p.x+dir[i][0],np.y=p.y+dir[i][1];
			if(np.x<=0 || np.x>H || np.y<=0 || np.y>W || vis[(np.x-1)*H+np.y] || map[np.x][np.y]==map[p.x][p.y])
				continue;
			vis[(np.x-1)*H+np.y]=true;
			if(map[np.x][np.y]=='.')
				ans++;
			lst[rear++]=np;
		}
	}
}

