int findher(int v){
    if(v == parent[v])return v;
    return parent[v] = findher(parent[v]);
}

void tmerge(int a,int b){
    if(sz[a] < sz[b]) swap(a , b);
    a = findher(a);
    b = findher(b);
    parent[b] = a;
    sz[a] += sz[b];
}

