const int inf=1e9;
const int dy[4]={1,0,-1,0};
const int dx[4]={0,-1,0,1};
int H,W;
queue<pair<int,int>> que;
int GridBFS(pair<int,int> start,const vector<vector<char>> &info,vector<vector<int>> &dist,vector<vector<bool>> &seen){
    que.emplace(start);
    seen[start.fi][start.se]=1;
    dist[start.fi][start.se]=0;
    int cntb=1,cntw=0;
    while(que.size()){
        int y=que.front().fi,x=que.front().se;
        que.pop();
        for(int k=0;k<4;k++){
            int ny=y+dy[k],nx=x+dx[k];
            if(0<=ny and ny<H and 0<=nx and nx<W){
                if(seen[ny][nx])continue;
                if(info[ny][nx]=='#'){
                    if(dist[ny][nx]>dist[y][x]+1 and (dist[y][x]+1)%2==0){
                        dist[ny][nx]=dist[y][x]+1;
                        que.push({ny,nx});
                        seen[ny][nx]=1;
                        cntb++;
                    }
                }
                else{
                    if(dist[ny][nx]>dist[y][x]+1 and (dist[y][x]+1)%2==1){
                        dist[ny][nx]=dist[y][x]+1;
                        que.push({ny,nx});
                        seen[ny][nx]=1;
                        cntw++;
                    }
                }
            }
        }
    }
    return cntb*cntw;
}
int main(){
    cin>>H>>W;
    vector<vector<char>> info(H,vector<char>(W));
    vector<pair<int,int>> s;
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            cin>>info[i][j];
            if(info[i][j]=='#')s.push_back({i,j});
        }
    }
    vector<vector<bool>> seen(H,vector<bool>(W,0));
    int ans=0;
    vector<vector<int>> dist(H,vector<int>(W,inf));
    for(auto p:s){
        if(seen[p.fi][p.se])continue;
        pair<int,int> start=p;
        ans+=GridBFS(start,info,dist,seen);
    }
    printf("%lld\n",ans);
    return 0;
}

