int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  int n, m;
  cin >> n >> m;
  vector< vector<int> > g(n, vector<int>(m));
  for (int i = 0; i < n; i++) {
    string s;
    cin >> s;
    for (int j = 0; j < m; j++) {
      g[i][j] = (s[j] == '#');
      if ((i + j) & 1) {
        g[i][j] ^= 1;
      }
    }
  }

  int odd, even, ans = 0;
  function<void(int,int,int)> dfs = [&](int i, int j, int c) {
    if (i < 0 || i >= n || j < 0 || j >= m) {
      return;
    }
    if (g[i][j] != c) return;
    else {
      g[i][j] = -1;
      if ((i + j) & 1) odd++;
      else even++;
    }
    const int dx[] = {1, -1, 0, 0};
    const int dy[] = {0, 0, 1, -1};
    for (int k = 0; k < 4; k++) {
      dfs(i + dx[k], j + dy[k], c);
    }
  };

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (g[i][j] != -1) {
        odd = even = 0;
        dfs(i, j, g[i][j]);
        ans += odd * even;
        // cout << odd << ' ' << even << '\n';
      }
    }
  }
  cout << ans << '\n';
  return 0;
}

