#define ll long long
#define pb push_back
#define mp make_pair
#define P pair<int,int>
using namespace std;
const int maxn = 410;
char maze[maxn][maxn];
bool visited[maxn][maxn];
int h, w;

void input() {
    cin>>h>>w;
    for(int i=0;i<h;i++) {
        for(int j=0;j<w;j++) {
            cin>>maze[i][j];
        }
    }
}

const int dx[4] = {0, 0, 1, -1};
const int dy[4] = {1, -1, 0, 0};

bool check(int i, int j, int d) {
    int ni = i + dx[d];
    int nj = j + dy[d];
    if(ni >= 0 && ni < h && nj >= 0 && nj < w)
        if(!visited[ni][nj] && maze[i][j] != maze[ni][nj]) return true;
    return false;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    input();

    ll result = 0LL;
    for(int i=0;i<h;i++) {
        for(int j=0;j<w;j++) {
            if(visited[i][j] || maze[i][j] == '.') continue;
            ll B = 0, W = 0;
            queue<P>q;
            q.push(mp(i, j));
            visited[i][j] = true;

            while(!q.empty()) {
                P curr = q.front();
                q.pop();
                if(maze[curr.first][curr.second] == '#') B++;
                else W++;

                for(int d=0;d<4;d++) {
                    if(check(curr.first, curr.second, d)) {
                        int ni = curr.first + dx[d];
                        int nj = curr.second + dy[d];
                        visited[ni][nj] = true;
                        q.push(mp(ni, nj));
                    }
                }
            }
            result += 1LL * B * W;
        }
    }
    cout<<result<<"\n";
    return 0;
}

