struct UnionFind {
    VI sizes, par;

    UnionFind(int n) :
            sizes(n, 1), par(n) {
        REP(i, n) par[i] = i;
    }

    int find(int x) {
        return x == par[x] ? x : par[x] = find(par[x]);
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;
        if (sizes[x] < sizes[y]) swap(x, y);
        sizes[x] += sizes[y];
        par[y] = x;
    }

    int getSizes(int x) {
        return sizes[find(x)];
    }

};

LL H, W;

int to(int i, int j) {
    return i * W + j;
}

int main() {

    cin >> H >> W;

    VS S(H);
    cin >> S;

    UnionFind UF(H * W);
    REP(i, H) {
        REP(j, W) {
            REP(k, 4) {
                int toY = i + dy[k];
                int toX = j + dx[k];
                if (toY < 0 || toY >= H || toX < 0 || toX >= W) continue;
                if (S[i][j] == S[toY][toX])continue;
                UF.unite(to(i, j), to(toY, toX));
            }
        }
    }

    VLL black(H * W, 0);
    REP(i, H) {
        REP(j, W) {
            if (S[i][j] == '#') black[UF.find(to(i, j))]++;
        }
    }

    LL ans = 0;
    REP(i, H) {
        REP(j, W) {
            if (UF.find(to(i, j)) == to(i, j)) {
                LL b = black[to(i, j)];
                LL w = UF.getSizes(to(i, j)) - b;
                ans += b * w;
            }
        }
    }

    OUT(ans);

    return 0;
}

