using namespace std;

typedef pair<int,int> P;
typedef long long ll;

char m[405][405];
bool use[405][405];
int dist[405][405];
int dx[] = {1,0,-1,0};
int dy[] = {0,1,0,-1};

void init(int h, int w) {
  for(int i = 0; i < h; i++) {
    for(int j = 0; j < w; j++) {
      use[i][j] = false;
    }
  }
}

int main() {
  int h,w;
  cin >> h >> w;

  for(int i = 0; i < h; i++) {
    string s;
    cin >> s;
    for(int j = 0; j < s.size(); j++) {
      m[i][j] = s[j];
    }
  }

  for(int i = 0; i < h; i++) {
    for(int j = 0; j < w; j++) {
      dist[i][j] = -1;
    }
  }

  ll ans = 0;

  for(int i = 0; i < h; i++) {
    for(int j = 0; j < w; j++) {
      if(m[i][j] == '.' || dist[i][j] >= 0) continue;
      vector<P> tmp;
      int c = 0;
      init(h,w);
      queue<P> p;
      p.push(P(i,j));
      while(!p.empty()) {
	int x = p.front().first;
	int y = p.front().second;
	p.pop();
	for(int k = 0; k < 4; k++) {
	  int nx = x + dx[k];
	  int ny = y + dy[k];
	  if(nx < 0 || ny < 0 || nx >= h || ny >= w || use[nx][ny]) continue;
	  use[nx][ny] = true;
	  if(m[x][y] == '#' && m[nx][ny] == '.') {
	    p.push(P(nx,ny));
	    c++;
	    tmp.push_back(P(x,y));
	    continue;
	  }
	   if(m[x][y] == '.' && m[nx][ny] == '#') {
	    p.push(P(nx,ny));
	    continue;
	   }
	}
      }

      for(int k = 0; k < tmp.size(); k++) {
	dist[tmp[k].first][tmp[k].second] = c;
      }
    }
  }

  for(int i = 0; i < h; i++) {
    for(int j = 0; j <w; j++) {
      if(dist[i][j] == -1) continue;
      ans += dist[i][j];
    }
  }

  cout << ans << endl;
}

#include<iostream>
#include<map>
using namespace std;
typedef long long ll;

char grid[404][404];
bool is_checked[404][404];
int colored_grid[404][404];
int dh[4] = {0, -1, 0, 1}, dw[4] = {-1, 0, 1, 0};
int H, W;
map<int, ll> black_mp;
map<int, ll> count_mp;

void dfs(int color, char check_color, int h, int w) {
    colored_grid[h][w] = check_color;
    if (color == '#') black_mp[check_color]++;
    is_checked[h][w] = true;
    for (int i = 0; i < 4; i++) {
        int now_h = h + dh[i], now_w = w + dw[i];
        if (now_h >= 0 && now_h < H && now_w >= 0 && now_w < W && grid[now_h][now_w] != grid[h][w] && !is_checked[now_h][now_w]) {
            dfs(grid[now_h][now_w], check_color, now_h, now_w);
        }
    }
    return;
}

int main() {
    cin >> H >> W;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) cin >> grid[i][j];
    }
    int now_number = 1;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (!is_checked[i][j]) {
                dfs(grid[i][j], now_number, i, j);
            }
            now_number++;
        }
    }
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) count_mp[colored_grid[i][j]]++;
    }
    ll ans = 0;
    for (int i = 1; i < now_number; i++) {
        ans += black_mp[i] * (count_mp[i] - black_mp[i]);
    }
    cout << ans << endl;
    return 0;
}

