long paint(char* field, int x, int y)
{
  int stack[160000];
  long odd = 0;
  long even = 0;
  int p = y * 402 + x;
  if((x + y) % 2)
  {
    odd = 1;
  }
  else
  {
    even = 1;
  }
  int color = field[p];
  int stn = 1;
  stack[0] = p;
  field[p] = 0;
  while(stn)
  {
    stn--;
    int pos = stack[stn];
    int way[4] = {-402, -1, 1, 402};
    int w;
    for(w = 0 ; w < 4 ; w++)
    {
    	int newpos = pos + way[w];
	    if(field[newpos] == color)
	    {
	      field[newpos] = 0;
	      if((newpos / 402 + newpos % 402) % 2)
	      {
	        odd++;
	      }
	      else
	      {
	        even++;
	      }
	      stack[stn] = newpos;
	      stn++;
	    }
    }
  }
  return odd * even;
}

