class UnionFind {
public:
  vector<int> par, rank;
  UnionFind(int sz) : par(sz, -1), rank(sz, 0){}
  int find(int x){
    if(par[x]<0) return x;
    else return par[x] = find(par[x]);
  }
  void unite(int x, int y){
    x=find(x); y=find(y);
    if(x==y) return;
    if(rank[x] < rank[y]) swap(x,y);
    par[x] += par[y];
    par[y] = x;
    if(rank[x]==rank[y]) rank[x]++;
  }
  inline bool same(int x, int y){ return find(x) == find(y); }
  inline int size(int x){ return -par[find(x)]; }
  inline bool isroot(int x) const { return par[x] < 0; }
};

int main(){
  int h,w;
  cin>>h>>w;
  vector<string> vv(h);
  rep(i,h) cin>>vv[i];
  vector<vector<bool>> v(h,vector<bool>(w));
  rep(i,h) rep(j,w) v[i][j] = vv[i][j] == '#';
  vector<vector<int>> num(h,vector<int>(w));
  rep(i,h) rep(j,w) num[i][j] = i*w + j;

  UnionFind uf(h*w);
  rep(i,h) rep(j,w){
    if(i<h-1 && v[i][j] != v[i+1][j]) uf.unite(num[i][j], num[i+1][j]);
    if(j<w-1 && v[i][j] != v[i][j+1]) uf.unite(num[i][j], num[i][j+1]);
  }

  vector<int> a(h*w,0), b(h*w,0);
  rep(i,h) rep(j,w){
    if(v[i][j]) a[uf.find(num[i][j])]++;
    else b[uf.find(num[i][j])]++;
  }

  long ans = 0;
  rep(i,h*w) ans += a[i]*b[i];

  cout << ans << endl;

  return 0;
}

