using namespace std;

template <typename T1, typename T2>
void func(T1& grid, T2& s, int ni, int nj, int& cnt) {
	if (s[ni][nj] == '.') { ++cnt; }
	int H = s.size();
	int W = s[0].size();

	int dx[4] = { 0, 1, 0, -1 };
	int dy[4] = { 1, 0, -1, 0 };
	for (int i = 0; i < 4; ++i) {
		int di = ni + dy[i];
		int dj = nj + dx[i];
		if ((di < 0) || (di >= H) || (dj < 0) || (dj >= W)) {
			continue;
		}
		if (s[ni][nj] == '.') {
			if (!grid[di][dj] && (s[di][dj] == '#')) {
				grid[di][dj] = true;
				func(grid, s, di, dj, cnt);
			}
		}
		if (s[ni][nj] == '#') {
			if (!grid[di][dj] && (s[di][dj] == '.')) {
				grid[di][dj] = true;
				func(grid, s, di, dj, cnt);
			}
		}
	}
}

int main() {
	int H, W;
	cin >> H >> W;
	vector<string> s(H);
	for (int i = 0; i < H; ++i) { cin >> s[i]; }

	int res = 0;
	vector<vector<bool>> grid(H, vector<bool>(W, false));
	for (int i = 0; i < H; ++i) {
		for (int j = 0; j < W; ++j) {
			if (s[i][j] == '#') {
				for (int x = 0; x < W; ++x) {
					for (int y = 0; y < H; ++y) {
						grid[y][x] = false;
					}
				}
				grid[i][j] = true;
				int cnt = 0;
				func(grid, s, i, j, cnt);
				res += cnt;
			}
		}
	}

	cout << res << endl;

	return 0;
}

