pair<ll, ll> bw(ll w) {
	see[w] = 1;
	pair<ll, ll> ret = {0,0};

	for (ll u : g[w]) {
		if (see[u] == 1) { continue; }
		pair<ll, ll> x = bw(u);
		ret.first += x.first;
		ret.second += x.second;
	}

	if (col[w] == '#') { ret.first++; }
	else { ret.second++; }

	return ret;
