			g[v(i, j)].push_back(v(i, j + 1));
			g[v(i, j + 1)].push_back(v(i, j));
		}
	}


	ll ans = 0;

	repn(i, N) {
		if (see[i] == 1) { continue; }

		pair<ll, ll> x = bw(i);

		ans += x.first*x.second;
	}

	cout << ans;
	system("PAUSE");
