static const int MAX_H = 400;
static const int MAX_W = 400;

int H, W;
char S[MAX_H][MAX_W + 1];
P num[MAX_H * MAX_W];
int dy[] = {0, -1, 0, 1};
int dx[] = {1, 0, -1, 0};

int par[MAX_H * MAX_W];
int rnk[MAX_H * MAX_W];

void init(int N){
	for(int i = 0; i < N; i++){
		par[i] = i;
		rnk[i] = 0;
	}
}
int find(int x){
	if(par[x] == x){
		return x;
	}else{
		return par[x] = find(par[x]);
	}
}
void unite(int x, int y){
	x = find(x);
	y = find(y);
	if(x == y) return;
	if(rnk[x] < rnk[y]){
		par[x] = y;
	}else{
		par[y] = x;
		if(rnk[x] == rnk[y]) rnk[x]++;
	}
}
bool same(int x, int y){
	return find(x) == find(y);
}

int main(){
	scanf("%d %d", &H, &W);
	for(int i = 0; i < H; i++) scanf("%s", S[i]);
	init(H * W);
	for(int i = 0; i < H; i++){
		for(int j = 0; j < W; j++){
			for(int k = 0; k < 4; k++){
				int ny = i + dy[k], nx = j + dx[k];
				if(ny < 0 || nx < 0 || ny >= H || nx >= W) continue;
				if(S[ny][nx] == S[i][j]) continue;
				unite(i * W + j, ny * W + nx);
			}
		}
	}
	for(int i = 0; i < H; i++){
		for(int j = 0; j < W; j++){
			if(S[i][j] == '.') num[find(i * W + j)].first++;
			else num[find(i * W + j)].second++;
		}
	}
	ll res = 0LL;
	for(int i = 0; i < H * W; i++) res += num[i].first * num[i].second;
	printf("%lld\n", res);
	return 0;
}

