int main()
{
    const int H = read<int>(), W = read<int>();
    const auto S = readVec<std::string>(H);
    auto used = Vec(H, W, false);
    constexpr int D[] = {1, 0, -1, 0, 1};
    auto in = [&, H, W](const int y, const int x) { return 0 <= y and y < H and 0 <= x and x < W; };
    using P = std::pair<int, int>;
    auto dfs = [&](auto&& self, const int y, const int x) -> P {
        used[y][x] = true;
        P ans = S[y][x] == '.' ? P{1, 0} : P{0, 1};
        for (int d = 0; d < 4; d++) {
            const int ny = y + D[d], nx = x + D[d + 1];
            if (in(ny, nx) and S[ny][nx] != S[y][x] and not used[ny][nx]) {
                const auto sub = self(self, ny, nx);
                ans.first += sub.first, ans.second += sub.second;
            }
        }
        return ans;
    };
    ll ans = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (used[i][j]) { continue; }
            const auto p = dfs(dfs, i, j);
            ans += (ll)p.first * (ll)p.second;
        }
    }
    std::cout << ans << std::endl;
    return 0;
}

