                    unite(i * w + j, (i+1) * w + j);
                }
            }
            if(j != w - 1){
                if(m[i][j] != m[i][j+1]){
                    unite(i * w + j, i * w + j + 1);
                }
            }
        }
    }

    rep(i, h * w){
        visited[i] = 0;
    }

    ll ans = 0;
