char S[400][400];

typedef struct index {
        int i;
        int j;
}index;

index search(int H,int W){
        index a;
        a.i=H; a.j=W;
        for(int i=0; i<H; i++) {
                for(int j=0; j<W; j++) {
                        if(S[i][j]=='.') {
                                a.i=i; a.j=j;
                                return a;
                        }
                }
        }
        return a;
}

long long pairNum(index a,int H,int W){
        long long black=0,white=0;
        index next;
        std::queue<index> q;
        q.push(a);
        while(!q.empty()) {
                a = q.front();
                q.pop();
                if(S[a.i][a.j]==0) continue;
                if(0<=a.i-1&&S[a.i][a.j]!=S[a.i-1][a.j]&&S[a.i-1][a.j]!=0) {
                        next.i=a.i-1;
                        next.j=a.j;
                        q.push(next);
                }
                if(a.i+1<H&&S[a.i][a.j]!=S[a.i+1][a.j]&&S[a.i+1][a.j]!=0) {
                        next.i=a.i+1;
                        next.j=a.j;
                        q.push(next);
                }
                if(0<=a.j-1&&S[a.i][a.j]!=S[a.i][a.j-1]&&S[a.i][a.j-1]!=0) {
                        next.i=a.i;
                        next.j=a.j-1;
                        q.push(next);
                }
                if(a.j+1<W&&S[a.i][a.j]!=S[a.i][a.j+1]&&S[a.i][a.j+1]!=0) {
                        next.i=a.i;
                        next.j=a.j+1;
                        q.push(next);
                }
                if(S[a.i][a.j]=='.') black++;
                else if(S[a.i][a.j]=='#') white++;
                S[a.i][a.j]=0;
        }
        return black*white;
}

int main(){
