  int di[] = {1, 0, -1, 0}, dj[] = {0, 1, 0, -1};
  rep(i, h)rep(j, w){
    rep(k, 4){
      int ni = i + di[k], nj = j + dj[k];
      if(nj < 0 || w <= nj || ni < 0 || h <= ni) continue;
      if(s.at(i).at(j) != s.at(ni).at(nj)){
        // cerr << ni << " " << nj << " " << ni*h+nj << endl;
        uf.unite(i*w+j, ni*w+nj);
      }
    }
  }

  vector<int> cw(h*w, 0);
  rep(i, h)rep(j, w){
    if(s.at(i).at(j) == '.'){
