using namespace std;

int x_dir[] = {-1, 1, 0, 0};
int y_dir[] = {0, 0, -1, 1};

int H, W;

int dfs(string *S, vector<vector<int>> &dist, vector<vector<int>> &state, int h, int w, int c, int count)
{
    if (state[h][w] == 1)
        return count;
    state[h][w] = 1;
    int new_h, new_w;
    for (int i = 0; i < 4; ++i)
    {
        new_h = h + y_dir[i];
        new_w = w + x_dir[i];
        if (new_h < 0 || new_h >= H || new_w < 0 || new_w >= W)
            continue;
        if (S[h][w] == '#')
        {
            if (S[new_h][new_w] == '.')
            {
                dist[h][w] = dist[new_h][new_w] = c;
                dfs(S, dist, state, new_h, new_w, c, ++count);
            }
        }
        else
        {
            if (S[new_h][new_w] == '#')
            {
                dist[h][w] = dist[new_h][new_w] = c;
                dfs(S, dist, state, new_h, new_w, c, ++count);
            }
        }
    }
    return count;
}

int main()
{
    cin >> H >> W;
    vector<vector<int>> dist(H, vector<int>(W)), state(H, vector<int>(W));
    string S[H];
    for (int i = 0; i < H; ++i)
    {
        cin >> S[i];
    }

    int c = 1, count;
    for (int i = 0; i < H; ++i)
    {
        for (int j = 0; j < W; ++j)
        {
            count = dfs(S, dist, state, i, j, c, 1);
            if (count > 1)
                ++c;
        }
    }
    int brack, white, ans=0;
    for (int i = 1; i < c; ++i)
    {
        brack = white = 0;
        for (int h = 0; h < H; ++h)
        {
            for (int w = 0; w < W; ++w)
            {
                if(i == dist[h][w]){
                    if(S[h][w] == '#') ++brack;
                    else ++white;
                }
            }
        }
        ans += brack*white;
    }
    cout << ans << endl;
}

