class UnionFind{
	vector<ll> rank;
	vector<ll> diff_weight;
	vector<ll> num;
public:
	vector<ll> par;

	UnionFind(ll N):par(N),num(N),rank(N),diff_weight(N){
		for(ll i=0;i<N;i++){
			par[i]=i;
			num[i]=1;
			rank[i]=0;
			diff_weight[i]=0;
		}
	}

	ll root(ll x){
		if(par[x]==x){
			return x;
		}
		ll r = root(par[x]);
		diff_weight[x]+=diff_weight[par[x]];
		return par[x]=r;
	}

	void unite(ll x,ll y){
		ll rx = root(x);
		ll ry = root(y);
		if (rx == ry) return;
		if(rank[rx]<rank[ry]) swap(rx,ry);
		if(rank[rx]==rank[ry]) ++rank[rx];
		par[ry] = rx;
		num[rx] += num[ry];
	}

	void relate(ll x,ll y,ll w){
		w+=weight(x),w-=weight(y);
		ll rx = root(x);
		ll ry = root(y);
		if (rx == ry) return;
		if(rank[rx]<rank[ry]){
			swap(rx,ry);
			w = -w;
		}
		if(rank[rx]==rank[ry]) ++rank[rx];
		par[ry] = rx;
		diff_weight[ry] = w;
		num[rx] += num[ry];
	}

	bool same(ll x,ll y){
		ll rx = root(x);
		ll ry = root(y);
		return rx == ry;
	}

	ll getsize(ll x){
		return num[root(x)];
	}

	ll weight(ll x){
		root(x);
		return diff_weight[x];
	}

	ll diff(ll x,ll y){
		return weight(y)-weight(x);
	}
};

int main(){
	cin.tie(0);
	ios::sync_with_stdio(false);
	cout<<fixed<<setprecision(10);

	int H=in(),W=in();
	UnionFind uf(H*W);
	vector<string> M(H);
	REP(i,H){
		M[i]=in<string>();
	}

	REP(i,H){
		REP(j,W){
			int p=j+i*W;
			if(j>0 && M[i][j]!=M[i][j-1]){
				uf.unite(p,p-1);
			}
			if(j<W-1 && M[i][j]!=M[i][j+1]){
				uf.unite(p,p+1);
			}
			if(i>0 && M[i][j]!=M[i-1][j]){
				uf.unite(p,p-W);
			}
			if(i<H-1 && M[i][j]!=M[i+1][j]){
				uf.unite(p,p+W);
			}
		}
	}
	map<int,ll> black,white;
	REP(i,H){
		REP(j,W){
			int p=j+i*W;
			if(M[i][j]=='#'){
				black[uf.root(p)]++;
			}
			else{
				white[uf.root(p)]++;
			}
		}
	}

	unordered_set<int> S;
	ll sum = 0;
	REP(i,H*W){
		int r = uf.root(i);
		auto res = S.insert(r);
		if(!res.second) continue;
		sum += black[r]*white[r];
	}

	out(sum);
	return 0;
}

