using namespace std;

long H, W;
vector<string> S;
vector<long> uf;

long find(long i) {
  if (uf[i] == -1) return i;
  long root = find(uf[i]);
  uf[i] = root;
  return root;
}

void foo(long h, long w, long hh, long ww) {
  if (hh < 0 || ww < 0 || hh >= H || ww >= W) return;
  if (S[h][w] == S[hh][ww]) return;
  long root = find(h * W + w);
  long rootroot = find(hh * W + ww);
  if (root == rootroot) return;
  uf[root] = rootroot;
}

void solve() {
  cin >> H >> W;
  S = vector<string>(H);
  rep (i, H) cin >> S[i];
  uf = vector<long>(H * W);
  rep (i, H*W) uf[i] = -1;
  rep (h, H) rep (w, W) {
    foo(h, w, h-1, w);
    foo(h, w, h+1, w);
    foo(h, w, h, w-1);
    foo(h, w, h, w+1);
  }
  unordered_map<long, long> black;
  unordered_map<long, long> white;
  rep (h, H) {
    rep (w, W) {
      long i = h * W + w;
      long root = find(i);
      if (S[h][w] == '#') black[root]++;
      else white[root]++;
    }
  }

  long ans = 0;
  for (auto it: black) ans += it.second * white[it.first];

  cout << ans << endl;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout.precision(12);
  solve();
  return 0;
}

