    cin>>S[h][w];
  }
  UnionFind tree(H*W);
  REP(h,H-1){
    REP(w,W-1){
      if(S[h][w]!=S[h][w+1])tree.unite(W*h+w,W*h+w+1);
      if(S[h][w]!=S[h+1][w])tree.unite(W*h+w,W*(h+1)+w);
    }
  }
  REP(h,H-1)if(S[h][W-1]!=S[h+1][W-1])tree.unite(W*h+W-1,W*(h+1)+W-1);
  REP(w,W-1)if(S[H-1][w]!=S[H-1][w+1])tree.unite(W*(H-1)+w,W*(H-1)+w+1);
  map<int,pair<int,int> >m;
  REP(h,H)REP(w,W){
    if(S[h][w]=='.')m[tree.root(W*h+w)].first+=1;
    else m[tree.root(W*h+w)].second+=1;
  }
