int used[410][410];
const int dy[] = {1, 0, -1, 0};
const int dx[] = {0, 1, 0, -1};

int bfs(int sy, int sx, const vector<string>& s, int h, int w) {
	queue<pair<int, int>> que;
	que.push(make_pair(sy, sx));
	used[sy][sx] = true;
	set<pair<int, int>> st;
	st.insert(make_pair(sy, sx));

	while (not que.empty()) {
		int y = que.front().first, x = que.front().second;
		que.pop();
		rep(i, 4) {
			int ny = y + dy[i];
			int nx = x + dx[i];
			if (not (0 <= ny && ny < h && 0 <= nx && nx < w))
				continue;
			if (s[y][x] != s[ny][nx] && not used[ny][nx]) {
				used[ny][nx] = true;
				st.insert(make_pair(ny, nx));
				que.push(make_pair(ny, nx));
			}
		}
	}
	int black = 0, white = 0;
	for (auto u : st) {
		int y = u.first,  x = u.second;
		if (s[y][x] == '#') black++;
		else white++;
	}
	return black * white;
}

