int rnk[500][500];

int init(int h, int w) {
  REP(i, h) {
    REP(j, w) {
      par[i][j] = MP(i, j);
      white[i][j] = mp[i][j];
    }
  }
}

pair<int, int> find(pair<int, int> p)
{
  if (par[p.FI][p.SE] == p)
    return par[p.FI][p.SE];
  else
    return par[p.FI][p.SE] = find(par[p.FI][p.SE]);
}

void unite(pair<int, int> a, pair<int, int> b)
{
  a = find(a);
  b = find(b);
  if (a == b) return;
  if (rnk[a.FI][a.SE] > rnk[b.FI][b.SE]) {
    par[b.FI][b.SE] = a;
    white[a.FI][a.SE] += white[b.FI][b.SE];
  } else {
    par[a.FI][a.SE] = b;
    white[b.FI][b.SE] += white[a.FI][a.SE];
  }
  if (rnk[a.FI][a.SE] == rnk[b.FI][b.SE]) rnk[b.FI][b.SE]++;
}

