int count( int i, int j, int H, int W, int **map, bool **searched ){
  if( searched[i][j] ) return 0;
  searched[i][j] = true;

  int sum = 0;
  if( map[i][j] == -1 ) sum++;
  if( i < H-1 ) if( map[i][j] == -1*map[i+1][j] ) sum += count( i+1, j, H, W, map, searched );
  if( i > 0 ) if( map[i][j] == -1*map[i-1][j]  ) sum += count( i-1, j, H, W, map, searched );
  if( j < W-1 ) if( map[i][j] == -1*map[i][j+1]  ) sum += count( i, j+1, H, W, map, searched );
  if( j > 0 ) if( map[i][j] == -1*map[i][j-1]  ) sum += count( i, j-1, H, W, map, searched );
  return sum;
}


