pair<ll, ll> dfs(ll x, ll y){
    if(check[x][y]) return make_pair(0, 0);
    check[x][y] = true;

    pair<ll, ll> sum;
    if(s[x][y] == '#'){
        sum.first = 0;
        sum.second = 1;
    }else{
        sum.first = 1;
        sum.second = 0;
    }

    if(s[x][y] != s[x + 1][y] && s[x + 1][y] != 0){
        pair<ll, ll> tmp;
        tmp = dfs(x + 1, y);
        sum.first += tmp.first;
        sum.second += tmp.second;
    }
    if(s[x][y] != s[x - 1][y] && s[x - 1][y] != 0){
        pair<ll, ll> tmp;
        tmp = dfs(x - 1, y);
        sum.first += tmp.first;
        sum.second += tmp.second;
    }
    if(s[x][y] != s[x][y + 1] && s[x][y + 1] != 0){
        pair<ll, ll> tmp;
        tmp = dfs(x, y + 1);
        sum.first += tmp.first;
        sum.second += tmp.second;
    }
    if(s[x][y] != s[x][y - 1] && s[x][y - 1] != 0){
        pair<ll, ll> tmp;
        tmp = dfs(x, y - 1);
        sum.first += tmp.first;
        sum.second += tmp.second;
    }

    return sum;
}

