void f(vector<vector<bool>>& board, vector<vector<bool>>& visited,int& num_black, int& num_white, int hi, int wi){
    if(visited[hi][wi]) return;
    bool color=board[hi][wi];
    if(color) ++num_black;
    else ++num_white;
    visited[hi][wi]=true;
    if(hi>0 && board[hi-1][wi]!=color) f(board, visited, num_black, num_white, hi-1, wi);
    if(hi+1<h && board[hi+1][wi]!=color) f(board, visited, num_black, num_white, hi+1, wi);
    if(wi>0 && board[hi][wi-1]!=color) f(board, visited, num_black, num_white, hi, wi-1);
    if(wi+1<w && board[hi][wi+1]!=color) f(board, visited, num_black, num_white, hi, wi+1);
}

