char maze[444][444];
int visited[444][444];


bool is_in_field(int h, int w, pii now){
    if(now.first < 0 || now.first >= h){return false;}
    if(now.second < 0 || now.second >= w){return false;}
    return true;
}

int bfs(int h, int w, int sh,int sw){
    queue<pii> q;
    pii start = {sh,sw};
    pii d[4] = {{1,0},{-1,0},{0,1},{0,-1}};
    q.push(start);
    visited[start.first][start.second] = 1;
    int black = 0;
    int white = 0;
    while(!q.empty()){
        pii now = q.front();
        q.pop();
        if(maze[now.first][now.second]=='.'){white++;}
        else if(maze[now.first][now.second]=='#'){black++;}
        for(int i = 0; i < 4; i++){
            pii next = {now.first + d[i].first, now.second + d[i].second};
            if(maze[next.first][next.second] == maze[now.first][now.second]){continue;}

            if(is_in_field(h, w, next)){
                if(visited[next.first][next.second] == -1){
                    q.push(next);
                    visited[next.first][next.second] = 1;
                }
            }
        }
    }
    return white*black;
}

