    }
    int ans = 0;
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            if(visited[i][j] == -1){
                ans += bfs(h,w,i,j);
            }
        }
    }
    cout << ans << endl;

    return 0;
}

