      if(i-1>=0)if(G[i-1][j] != G[i][j]) tree.unite(P(i,j),P(i-1,j),G[i-1][j]);
      if(j-1>=0)if(G[i][j-1] != G[i][j]) tree.unite(P(i,j),P(i,j+-1),G[i][j-1]);
      if(j+1<w)if(G[i][j+1] != G[i][j]) tree.unite(P(i,j),P(i,j+1),G[i][j+1]);
    }
