ll black=0,white=0;

bool inside (pair<int,int> cor, int d)
{
    int x=cor.ff+dx[d],y=cor.ss+dy[d];
    return (x>=0 && x<h && y>=0 && y<w);
}

bool check (pair<int,int> g, int cx, int cy)
{
    return (color[g.ff][g.ss]!=color[cx][cy]);
}

void bfs (pair<int,int> s)
{
    queue<pair<int,int>> q;
    q.push(s);
    vis[s.ff][s.ss]=true;
    int i;
    while (!q.empty())
    {
        pair<int,int> v=q.front();
        q.pop();
        int x=v.ff,y=v.ss;
        if (color[x][y])
            black++;
        else
            white++;
        for (i=0;i<4;i++)
        {
            if (inside(v,i))
            {
                int cx=x+dx[i],cy=y+dy[i];
                if (check(v,cx,cy))
                {
                    if (vis[cx][cy]==false)
                    {
                        q.push(mp(cx,cy));
                        vis[cx][cy]=true;
                    }
                }
            }
        }
    }
}

main()
{
    fast;
    int i,j;
    cin>>h>>w;
    string s;
    for (i=0;i<h;i++)
    {
        cin>>s;
