            color[i][j]=(s[j]=='#');
    }
    ll ans=0;
    for (i=0;i<h;i++)
    {
        for (j=0;j<w;j++)
        {
            if (vis[i][j])
                continue;
            black=0;
            white=0;
            bfs(mp(i,j));
            ans+=black*white;
        }
    }
    cout<<ans<<endl;
}

