struct UnionFind {
    vector<int> v;
    UnionFind(int N) :v(N, -1) {}
    int root(int x) {
        if (v[x] < 0) return x;
        else return v[x] = root(v[x]);
    }
    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (v[x] > v[y]) swap(x, y);
        v[x] += v[y];
        v[y] = x;
    }
    int size(int x) {
        return -v[x];
    }
};

