        ll x = p.first, y = p.second;
        if (ok[x][y]) continue;
        if (color != s[x][y]) ans++;
        for (ll k = 0; k < 4; k++) {
          ll X = x + dx[k], Y = y + dy[k];
          if (X < 0 || X == h || Y < 0 || Y == w) continue;
          if (ok[X][Y]) continue;
          if (s[X][Y] == s[x][y]) continue;
          que.push(P(X, Y));
        }
        ok[x][y] = true;
      }
    }
  }
  printf("%lld\n", ans / 2);
}

