	REP(i, H) {
		string s;
		cin >> s;
		REP(j, W) {
			maps[i + 1][j + 1] = 1+(s[j]=='#');
			LL val = (i+1) * SIZE + (j+1);
			uf.sizes[maps[i + 1][j + 1]-1][val] = 1;
		}
	}
	int dx[] = { 0,1,0,-1 };
	int dy[] = { 1,0,-1,0 };
	EFOR(i, 1, H) {
		EFOR(j, 1, W) {
			REP(k, 4) {
				int ny = i + dy[k];
				int nx = j + dx[k];
				if (maps[i][j] + maps[ny][nx] == 3) {
					uf.unite(i*SIZE+ j,ny*SIZE+nx);
				}
			}
		}
	}
	LL ans = 0;
	EFOR(i,1,H)
		EFOR(j, 1, W) {
		LL val = i * SIZE + j;
		if (uf.find(val) == val) ans += uf.minisize(val, 0)*uf.minisize(val, 1);
	}
	cout << ans << endl;
	return 0;
}




