int nodeID(int h, int w) {
  assert(1<= h && h <= H);
  assert(1<= w && w <= W);

  return (h-1)*W + w - 1;
}

char getColor(int nodeID) {
  int h = nodeID/W + 1;
  int w = nodeID%W + 1;
  return board[h][w];
}

void dfs(vector<bool>& defined, int x, vi& nodes) {
  for (auto c : G[x]) {
    if (defined[c]) continue;
    defined[c] = true;
    nodes.emplace_back(c);
    dfs(defined, c, nodes);
  }
}

