int dy[4] = {0,0,-1,1};


pair<int,int> find_parent(pair<int,int> x){
    if(parent[x.first][x.second] != x) parent[x.first][x.second] = find_parent(parent[x.first][x.second]);
    return parent[x.first][x.second];
}

void merge_sets(pair<int,int> x, pair<int,int> y){
    x = find_parent(x),y = find_parent(y);
    if(x == y) return;
    cnt[x.first][x.second][0] = cnt[y.first][y.second][0] = cnt[x.first][x.second][0] + cnt[y.first][y.second][0];
    cnt[x.first][x.second][1] = cnt[y.first][y.second][1] = cnt[x.first][x.second][1] + cnt[y.first][y.second][1];
    if(set_rank[x.first][x.second] > set_rank[y.first][y.second] ) parent[y.first][y.second] = x;
    else parent[x.first][x.second] = y;
    if(set_rank[x.first][x.second] == set_rank[y.first][y.second]) set_rank[y.first][y.second] += 1;
}

int main(){
    int H,W; cin>>H>>W;
    for(int i=0;i<H;i++) cin>>grid[i];
    for(int i=0;i<H;i++) for(int j=0;j<W;j++) parent[i][j] = make_pair(i,j);
    for(int i=0;i<H;i++) for(int j=0;j<W;j++) cnt[i][j][grid[i][j] == '#'?0:1] += 1;
    for(int i=0;i<H;i++) for(int j=0;j<W;j++) for(int k=0;k<4;k++){
        int ni = i + dx[k],nj = j + dy[k];
        if(ni < 0 || ni >= H || nj < 0 || nj >= W || grid[ni][nj] == grid[i][j]) continue;
        merge_sets(make_pair(i,j),make_pair(ni,nj));
    }

    long long total = 0;
    for(int i=0;i<H;i++) for(int j=0;j<W;j++) if(parent[i][j] == make_pair(i,j)) total += cnt[i][j][0] * cnt[i][j][1];
    cout<<total<<endl;
}

