constexpr array<int, 8> di({0, 1, -1, 0, 1, -1, 1, -1});
constexpr array<int, 8> dj({1, 0, 0, -1, 1, -1, -1, 1});
constexpr lli mod = 1e9 + 7;

int main(int argc, char *argv[])
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);
  cout.setf(ios_base::fixed);
  cout.precision(15);

  int h, w;
  while (cin >> h >> w) {
    const int H = 400 + 5;
    const int W = 400 + 5;
    static char g[H][W];
    for (int i = 0; i < h; ++i) {
      for (int j = 0; j < w; ++j) {
        cin >> g[i][j];
      }
    }

    static bool vis[H][W];
    fill(&vis[0][0], &vis[H - 1][W - 1] + 1, false);

    lli x = 0;
    map<char, lli> m;
    function<void(int, int)> rec = [&] (int i, int j) {
      vis[i][j] = true;
      ++m[g[i][j]];
      for (int d = 0; d < 4; ++d) {
        int ni = i + di[d];
        int nj = j + dj[d];
        unless (0 <= ni && ni < h) continue;
        unless (0 <= nj && nj < w) continue;
        if (g[i][j] != g[ni][nj] && !vis[ni][nj]) {
          rec(ni, nj);
        }
      }
    };
    for (int i = 0; i < h; ++i) {
      for (int j = 0; j < w; ++j) {
        if (!vis[i][j]) {
          m.clear();
          rec(i, j);
          x += m['.'] * m['#'];
        }
      }
    }
    cout << x << endl;
  }

  return 0;
}

