#include <iostream>
#include <stack>
#include <vector>
using namespace std;

typedef pair<int, int> pxy;
const int dx[] = {1, 0, -1, 0}, dy[] = {0, 1, 0, -1};

using data = struct{
  pxy p;
  char prev;
};

int main()
{
  int H, W;
  cin >> H >> W;

  bool state[H][W];
  for(int i = 0; i < H; ++i){
    for(int j = 0; j < W; ++j){
      state[i][j] = false;
    }
  }

  vector<string> m(H);
  for(int i = 0; i < H; ++i) cin >> m[i];

  int b, w;
  int ans = 0;
  for(int i = 0; i < H; ++i){
    for(int j = 0; j < W; ++j){
      if(state[i][j]) continue;

      b = w = 0;
      char s = m[i][j];
      stack<data> st;
      st.push(data{pxy(i, j), s});
      state[i][j] = true;

      while(!st.empty()){
        int x, y;      
        x = st.top().p.first;
        y = st.top().p.second;
        s = st.top().prev;

        st.pop();

        if(s == '#') ++b;
        else ++w;

        for(int k = 0; k < 4; ++k){
          int next_x = x + dx[k], next_y = y + dy[k];
          if(next_x < 0 || next_x >= H || next_y < 0 || next_y >= W || m[next_x][next_y] == s || state[next_x][next_y]) continue;
          st.push(data{pxy(next_x, next_y), m[next_x][next_y]});
          state[next_x][next_y] = true;
        }
      }
      ans += b*w;
    }
  }

  cout << ans << endl;
}

