const int vx[]={0,1,0,-1};
const int vy[]={1,0,-1,0};

int main(){
    int h,w;
    cin>>h>>w;
    vector<vector<char>> mp(h+2,vector<char>(w+2));
    vector<vector<bool>> visited(h+2,vector<bool>(w+2,true));

    for (int i = 0; i < h; ++i) {
        string s;
        cin>>s;
        for (int j = 0; j < w; ++j) {
            mp[i+1][j+1]=s[j];
            visited[i+1][j+1]=false;
        }
    }

    queue<pair<int,int>> q;
    int nx=1,ny=1;
    int remg=h*w;
    int nextv=0;
    int ans=0;
    int li=0;
    while(true){
        if(remg==0)break;
        if(q.empty()){
            for (int i = li; i < h; ++i) {
                for (int j = 0; j < w; ++j) {
                    if(!visited[i+1][j+1]){
                        q.push(make_pair(i+1,j+1));
                        visited[i+1][j+1]=true;
                        li=i;
                        goto qpushed;
                    }
                }

            }
            break;
        }
        qpushed:;
        int bl=0,wh=0;

        while(!q.empty()){
            ny=q.front().first;
            nx=q.front().second;
            if(mp[ny][nx]=='#')++bl;
            else ++wh;
            --remg;
            q.pop();
            for (int i = 0; i < 4; ++i) {
                if(!visited[ny+vy[i]][nx+vx[i]]&&mp[ny][nx]!=mp[ny+vy[i]][nx+vx[i]]){
                    q.push(make_pair(ny+vy[i],nx+vx[i]));
                    visited[ny+vy[i]][nx+vx[i]]=true;
                }
            }
        }
        ans+=bl*wh;
    }
    cout<<ans<<endl;
    return 0;
}

