using namespace std;
long matrix[400][400] = {};
int H=0,W=0;

void count(int row, int col,int num) {
	int temp = matrix[row][col];
	if (temp == -1) {
      	matrix[row][col] = num+1;
		if (row - 1 >= 0) {
			if (matrix[row - 1][col] == -2) count(row - 1, col,num);
		}
		if (row + 1 < H) {
			if (matrix[row + 1][col] == -2) count(row +1, col,num);
		}
		if (col - 1 >= 0) {
			if (matrix[row][col - 1] == -2) count(row, col-1,num);
		}
		if (col + 1 < W) {
			if (matrix[row][col + 1] == -2) count(row, col +1,num);
		}
	}

	if (temp == -2) {
      	matrix[row][col] = num;
		if (row - 1 >= 0) {
			if (matrix[row - 1][col] == -1) count(row - 1,col,  num);
		}
		if (row + 1 < H) {
			if (matrix[row + 1][col] == -1) count(row +1, col, num);
		}
		if (col - 1 >= 0) {
			if (matrix[row][col - 1] == -1) count(row, col -1, num);
		}
		if (col + 1 < W) {
			if (matrix[row][col + 1] == -1) count(row, col +1,num);
		}
	}
}

int main() {
	cin >> H >> W;
	string S[400] = {};

	for (int i = 0; i < H; i++) {
			cin >> S[i];
    }

	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (S[i][j] == '#')matrix[i][j] = -1;
			else if (S[i][j] == '.')matrix[i][j] = -2;
          	else matrix[i][j] = 0;
		}
	}
	long a = 2;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (matrix[i][j] >= 0) continue;
			count(i, j, a);
			a+=2;
		}
    }

    long box[320000]={};
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			int cell=matrix[i][j];
          	box[cell]++;
		}
	}

  	int ans=0;
  	for(int i=1;2*i<a;i++){
    	ans +=(box[2*i])*(box[2*i+1]);
    }

 	cout <<ans <<endl;
}

