int h, w;
char maze[401][401] = {};
bool reached[401][401] = {};
ll black = 0, white = 0;

void dfs(int x, int y, char last_color) {
    if (x < 0 || h <= x || y < 0 || w <= y) return;
    if (reached[x][y]) return;
    if (maze[x][y] == last_color) return;

    reached[x][y] = true;
    if (maze[x][y] == '#') black++;
    else white++;
    last_color = maze[x][y];
    dfs(x + 1, y, last_color);
    dfs(x - 1, y, last_color);
    dfs(x, y + 1, last_color);
    dfs(x, y - 1, last_color);
}

int main() {
    cin >> h >> w;
    rep(i, 0, h) {
        rep(j, 0, w) {
            cin >> maze[i][j];
        }
    }

    ll ans = 0;
    rep(i, 0, h) {
        rep(j, 0, w) {
            if (maze[i][j] == '#') {
                char last_color = '.';
                dfs(i, j, last_color);
                ans += black * white;
                black = 0;
                white = 0;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

