class Disjoint_Sets{
public:
	ll* parent;
	ll* size;
	Disjoint_Sets(ll n){
		parent = new ll[n];
		size = new ll[n];
		For(i,0,n) parent[i]=i;
		For(i,0,n) size[i]=1;
	}
	void merge(ll a,ll b){
		ll parent_a = find(a);
		ll parent_b = find(b);
		if(parent_a==parent_b) return;
		if(size[parent_a]<size[parent_b]){
			parent[parent_a] = parent_b;
			size[parent_b] += size[parent_a];
			size[parent_a] = 0;
		}else{
			parent[parent_b] = parent_a;
			size[parent_a] += size[parent_b];
			size[parent_b] = 0;
		}
	}
	ll find(ll a){
		if(parent[a]==a){
			return a;
		}
		parent[a]=find(parent[a]);
		return parent[a];
	}
}; 
