struct Tmp
{
public:
  int H, W;
  vector<vector<int>> table, memo;
  Tmp(int H, int W)
  : H(H), W(W)
  , table(H, vector<int>(W, 0))
  , memo(H, vector<int>(W, 0))
  {}

  void operator() () {
    input();
    ll res{};
    for (int i = 0; i < H; ++i) {
      for (int j = 0; j < W; ++j) {
        if (table[i][j] && !memo[i][j]) {
          auto r = task(i, j);
          res += r;
        }
      }
    }
    cout << res << CRLF;
  }

  ll task(int h, int w) {
    ll cnt[2] = {};
    std::queue<pair<int, int>> que{};

    constexpr pair<int, int> delta[] = {
      {-1, 0},
      {0, -1},
      {1, 0},
      {0, 1},
    };
    memo[h][w] = 1;
    ++cnt[table[h][w]];
    que.push({h, w});
    while (!que.empty()) {
      auto p = que.front(); que.pop();
      auto ch = p.first;
      auto cw = p.second;
      auto isKuro = table[ch][cw];
      for (const auto& dxdy : delta) {
        auto nh = ch + dxdy.first;
        auto nw = cw + dxdy.second;
        if (nh < 0 || nh >= H) continue;
        if (nw < 0 || nw >= W) continue;

        auto nIsKuro = table[nh][nw];
        if (isKuro != nIsKuro && !memo[nh][nw]) {
          ++cnt[nIsKuro];
          memo[nh][nw] = 1;
          que.push({nh, nw});
        }
      }
    }
    return cnt[0] * cnt[1];
  }

  void input() {
    for (int i = 0; i < H; ++i) {
      for (int j = 0; j < W; ++j) {
        char c; cin >> c;
        if (c == '#') {
          table[i][j] = 1;
        }
      }
    }
  }
};

void solve(void)
{
  int H, W; cin >> H >> W;
  Tmp t(H, W);
  t();
  return;
}

int main(void)
{
  std::ios_base::sync_with_stdio(false);
  std::cin.tie(0);

  solve();

  return 0;
}

