inline int power(int a, long long b,int md) {
	int res = 1;
	while (b > 0) {
		if (b & 1) {
			res = mul(res, a, md);
		}
		a = mul(a, a, md);
		b >>= 1;
	}
	return res;
}

inline int inv(int a, int md) {
	a %= md;
	if (a < 0) a += md;
	int b = md, u = 0, v = 1;
	while (a) {
		int t = b / a;
		b -= t * a; swap(a, b);
		u -= t * v; swap(u, v);
	}
	//assert(b == 1);
	if (u < 0) u += md;
	return u;
}



ll mod_pow(ll x, ll n, ll mod) {
	ll res = 1;
	while (n > 0) {
		if (n & 1) {
			res = res * x;
			res %= mod;
		}
		x = (x*x) % mod;
		n >>= 1;
	}
	return res;
}

ll gcd(ll a, ll b) {
	while (b > 0) {
		int r = a % b;
		a = b;
		b = r;
	}
	return a;
}

ll stein_gcd(ll a, ll b) {
	unsigned c = 0;
	while (1)
	{
		if (a == 0)
			return b << c;
		else if (b == 0)
			return a << c;
		if (!(a & 1) && !(b & 1))
		{
			a >>= 1; b >>= 1; ++c;
		}
		else if (!(a & 1) && (b & 1))
		{
			a >>= 1;
		}
		else if ((a & 1) && !(b & 1))
		{
			b >>= 1;
		}
		else if ((a & 1) && (b & 1))
		{
			unsigned tmp = a > b ? b : a;
			a = a > b ? a - b : (b - a);
			b = tmp;
		}
	}
}

tuple<int, int, int> xgcd(int a, int b) {
	int x = 0, y = 1, px = 1, py = 0;
	while (b != 0) {
		int q = a / b;
		int tx = x;
		x = px - q * x;
		px = tx;
		int ty = y;
		y = py - q * y;
		py = ty;
		int r = a % b;
		a = b;
		b = r;
	}

	return make_tuple(a, px, py);
}

