int findRoot(int p)
{
	while (p != id[p])
	{
		id[p] = id[id[p]];
		p = id[p];
	}
	return p;
}

void comb(int p, int q) {
	int i = findRoot(p);
	int j = findRoot(q);
	if (i == j)
	{
		return;
	}
	if (sz[i] < sz[j])
	{
		id[i] = j;
		sz[j] += sz[i];
	}
	else
	{
		id[j] = i;
		sz[i] += sz[j];
	}
	groups--;
}









