	int sum = 0;
	Ap[x][y] = 0;
	for(int i = 0;i < 4; i++){
		int nx = x + dx[i];
		int ny = y + dy[i];
		if(Ap[nx][ny] != -c) continue; 
		if(Ap[nx][ny] == -sc) sum++;
		sum += dfs(nx, ny, -c);
	}
