// bfs 幅優先探索
int bfs(vector<string> field, pair<int, int> s_pos)
{
  int dirx[] = {1, -1, 0, 0};
  int diry[] = {0, 0, 1, -1};
  int R, C;
  int INF = INT32_MAX;
  R = field.size();
  C = field[0].size();

  vector<vector<int>> cost(R, vector<int>(C, INF));

  cost[s_pos.first][s_pos.second] = 0;
  queue<pair<int, int>> pos_queue;
  pos_queue.push(s_pos);

  int count = 0;
  while (pos_queue.size())
  {
    pair<int, int> pos = pos_queue.front();
    pos_queue.pop();
    int pos_x = pos.first;
    int pos_y = pos.second;
    rep(i, 4)
    {
      int next_x = pos_x + dirx[i];
      int next_y = pos_y + diry[i];

      if (0 <= next_x && next_x < R && 0 <= next_y && next_y < C && field[next_x][next_y] != field[pos_x][pos_y] && cost[next_x][next_y] == INF)
      {
        cost[next_x][next_y] = cost[pos_x][pos_y] + 1;
        pos_queue.push(make_pair(next_x, next_y));
        if (field[next_x][next_y] == '.')
          count++;
      }
    }
  }

  return count;
}

