//変数
ll H,W;
bool clr[400][400];
bool chk[400][400];


//解法
void solve() {

	ll ans = 0;

	rep(i, 400) rep(j, 400) chk[i][j] = false;

	rep(y, H) rep(x, W) {

		if (chk[x][y] == false) {

			ll white = 0;
			ll black = 0;

			queue<pair<int, int>> QU;
			QU.push(make_pair(x, y));
			chk[x][y] = true;
			if (clr[x][y] == false) white++;
			if (clr[x][y] == true) black++;

			while (QU.size() != 0) {

				pair<int, int> P = QU.front();
				QU.pop();
				int xx = P.first;
				int yy = P.second;

				if (chk[xx - 1][yy] == false && clr[xx - 1][yy] != clr[xx][yy] && xx - 1 >= 0) {
					QU.push(make_pair(xx - 1, yy));
					if (clr[xx - 1][yy] == false) white++;
					if (clr[xx - 1][yy] == true) black++;
					chk[xx - 1][yy] = true;
				}
				if (chk[xx + 1][yy] == false && clr[xx + 1][yy] != clr[xx][yy] && xx + 1 <=W-1) {
					QU.push(make_pair(xx + 1, yy));
					if (clr[xx + 1][yy] == false) white++;
					if (clr[xx + 1][yy] == true) black++;
					chk[xx + 1][yy] = true;
				}
				if (chk[xx][yy-1] == false && clr[xx][yy-1] != clr[xx][yy] && yy - 1 >= 0) {
					QU.push(make_pair(xx, yy-1));
					if (clr[xx ][yy-1] == false) white++;
					if (clr[xx ][yy-1] == true) black++;
					chk[xx][yy-1] = true;
				}
				if (chk[xx][yy + 1] == false && clr[xx][yy + 1] != clr[xx][yy] && yy + 1 <= H-1) {
					QU.push(make_pair(xx, yy + 1));
					if (clr[xx ][yy+1] == false) white++;
					if (clr[xx ][yy+1] == true) black++;
					chk[xx][yy + 1] = true;
				}

			}

			ans += white*black;
			//cout << "("<<x<<","<<y<<")"<< "white:" << white << " black:" << black << endl;
		}

	}

	cout << ans;

	return;
}

