	cin >> H>>W;
	string input;
	rep(i, H){
		cin >> input;
		rep(j, W) {
			if (input[j] == '#') {
				clr[j][i] = true;
			}
			else {
				clr[j][i] = false;
			}
		}
	}

	solve();
	cout << endl;
	return 0;
}

