void rec(int h, int w) {
  if (vis[h][w] == true) return;
  vis[h][w] = true;
  for (int i = 0; i < 4; i++) {
    int ny = h + dy[i], nx = w + dx[i];
    if (ny >= H || ny < 0 || nx >= W || nx < 0 || vis[ny][nx] || s[ny][nx] == s[h][w]) continue;
    rec(ny, nx);
  }

  if (s[h][w] == '.') {
    x++;
  } else {
    y++;
  }
  return;
}

