    rep(i, H - 1) {
        rep(j, W) {
            if (S[i][j] == '#' && S[i + 1][j] == '.') unite(i * W + j, i * W + W + j);
            if (S[i][j] == '.' && S[i + 1][j] == '#') unite(i * W + j, i * W + W + j);
        }
    }
    rep(i, H) {
        rep(j, W - 1) {
            if (S[i][j] == '#' && S[i][j + 1] == '.') unite(i * W + j, i * W + 1 + j);
            if (S[i][j] == '.' && S[i][j + 1] == '#') unite(i * W + j, i * W + 1 + j);
        }
