typedef long long ll;

const int N = 405, M = N * N, dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};

int n, m, fa[M], cb[M], cw[M];
char s[N][N];
ll ans;

int which(int x, int y)
{
	return (x - 1) * m + y;
}

int cx(int x)
{
	if (fa[x] != x) fa[x] = cx(fa[x]);
	return fa[x];
}

void zm(int x, int y)
{
	int ix = cx(x), iy = cx(y);
	if (ix != iy) fa[iy] = ix,
		cb[ix] += cb[iy], cw[ix] += cw[iy];
}

int main()
{
	std::cin >> n >> m;
	for (int i = 1; i <= n; i++)
		scanf("%s", s[i] + 1);
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++)
		{
			int x = which(i, j);
			fa[x] = x;
			(s[i][j] == '#' ? cb[x] : cw[x]) = 1;
		}
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++)
		{
			if (s[i][j] == '.') continue;
			for (int k = 0; k < 4; k++)
			{
				int x = i + dx[k], y = j + dy[k];
				if (x < 1 || x > n || y < 1 || y > m || s[x][y] == '#')
					continue;
				zm(which(i, j), which(x, y));
			}
		}
	for (int i = 1; i <= n * m; i++)
		if (fa[i] == i) ans += cb[i] * cw[i];
	std::cout << ans << std::endl;
	return 0;
}

