void solve() {
  int H, W; cin >> H >> W;
  vstr S(H); rep(i, H) cin >> S[i];
  vector<vi32> edges(H * W);
  rep(i, H) rep(j, W - 1) {
    if (S[i][j] != S[i][j + 1]) {
      int v = i * W + j, u = v + 1;
      edges[v].push_back(u);
      edges[u].push_back(v);
    }
  }
  rep(j, W) rep(i, H - 1) {
    if (S[i][j] != S[i + 1][j]) {
      int v = i * W + j, u = (i + 1) * W + j;
      edges[v].push_back(u);
      edges[u].push_back(v);
    }
  }
  vector<bool> seen(H * W);

  i64 c1, c2;
  function<void(int, int)> dfs = [&](int v, int c) {
    seen[v] = true;
    if (c % 2 == 0) c1++; else c2++;
    each(u, edges[v]) {
      if (seen[u]) continue;
      dfs(u, c + 1);
    }
  };

  i64 ans = 0;
  rep(i, H) rep(j, W) {
    int v = i * W + j;
    if (seen[v]) continue;
    c1 = 0, c2 = 0;
    dfs(v, 0);
    ans += c1 * c2;
  }
  cout << ans << '\n';
}

