					}
				}
				if (i < H - 1) {
					if (v[i + 1][j] == '.') {
						uni.unite(i*W + j, (i + 1)*W + j);
					}
				}
				if (j > 0) {
					if (v[i][j - 1] == '.') {
						uni.unite(i*W + j, i*W + j - 1);
					}
				}
				if (j < W - 1) {
					if (v[i][j + 1] == '.') {
						uni.unite(i*W + j, i*W + j + 1);
					}
				}
			}
		}
	}
	lli ans = 0;
	map<int, lli>b, w;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (v[i][j] == '#') {
				b[uni.root(i*W + j)]++;
			}
			else {
				w[uni.root(i*W + j)]++;
			}
		}
	}
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			ans += b[i * W + j] * w[i * W + j];
		}
	}
	cout << ans << endl;
	return 0;
}

