int dy[] = {-1, 1, 0, 0}, dx[] = {0, 0, -1, 1};

int H, W;
string s[410];
bool vis[410][410];

int x = 0, y = 0;

void rec(int h, int w) {
  if (vis[h][w] == true) return;
  vis[h][w] = true;
  for (int i = 0; i < 4; i++) {
    int ny = h + dy[i], nx = w + dx[i];
    if (ny >= H || ny < 0 || nx >= W || nx < 0 || vis[ny][nx] || s[ny][nx] == s[h][w]) continue;
    rec(ny, nx);
  }

  if (s[h][w] == '.') {
    x++;
  } else {
    y++;
  }
  return;
}

signed main() {
  cin >> H >> W;
  for (int i = 0; i < H; i++) {
    cin >> s[i];
  }

  int ans = 0;
  for (int h = 0; h < H; h++) {
    for (int j = 0; j < W; j++) {
      rec(h, j);
      ans += x * y;
      x = 0;
      y = 0;
    }
  }

  cout << ans << endl;
  return 0;
}

