#define PB push_back
#define MP make_pair
#define PUTS(x) cout << (x) << endl;
struct Node {
    bool black = false;
    bool visited = false;
    vector<int> adjacentNodeIndexes = vector<int>();
};

int main() {
    int h, w;
    cin >> h >> w;
    auto g = vector<Node>(h * w);
    auto pos = [&](int i, int j) {
        return i * w + j;
    };
    rep(i, h) {
        string s;
        cin >> s;
        rep(j, w) {
            g[pos(i, j)].black = (s[j] == '#');
        }
    }
    // 異色のノード同士を辺で結ぶ
    rep(i, h) {
        rep(j, w) {
            if (j < w - 1 && g[pos(i, j)].black != g[pos(i, j + 1)].black) {
                g[pos(i, j)].adjacentNodeIndexes.PB(pos(i, j + 1));
                g[pos(i, j + 1)].adjacentNodeIndexes.PB(pos(i, j));
            }
            if (i < h - 1 && g[pos(i, j)].black != g[pos(i + 1, j)].black) {
                g[pos(i, j)].adjacentNodeIndexes.PB(pos(i + 1, j));
                g[pos(i + 1, j)].adjacentNodeIndexes.PB(pos(i, j));
            }
        }
    }
    auto components = vector<pair<int, int>>();
    // 連結成分に含まれる (黒数,白数) をDFSで調べる関数
    function<pair<Int, Int>(int)> dfs = [&](int target) -> pair<Int, Int> {
        auto &node = g[target];
        node.visited = true;
        auto result = MP(0LL, 0LL); // 自分と子孫ノード全ての (黒数,白数) を返す
        if (node.black) {
            result.first++;
        } else {
            result.second++;
        }
        for (auto nextIndex : node.adjacentNodeIndexes) {
            if (!g[nextIndex].visited) { // 未調査の各子ノードについて
                auto result2 = dfs(nextIndex); // その子孫ノードの (黒数,白数)
                result.first += result2.first; // 累計に足す
                result.second += result2.second;
            }
        }
        return result; // 自分と子孫ノード全ての (黒数,白数) を返す
    };

    // 連結成分それぞれの (黒数,白数) を components に追加していく
    rep(i, h * w) {
        if (!g[i].visited) {
            components.PB(dfs(i));
        }
    }
    auto ans = 0LL;
    for (auto p : components) { // 各連結成分について積 黒数*白数 を累加していく
        ans += p.first * p.second;
    }
    PUTS(ans);
}

