int di[] = {0, 1, 0, -1};
int dj[] = {1, 0, -1, 0};
int sz[N];

bool ins(int i, int j) {
    return
            0 <= i && i < n &&
            0 <= j && j < m;
}

void dfs(int i, int j, int c) {
    used[i][j] = 1;
    which_comp[i][j] = c;
    if (orig[i][j] != '#') {
        sz[c]++;
    }


    loop(d, 4) {
        int ti = i + di[d];
        int tj = j + dj[d];
        if (ins(ti, tj) && !used[ti][tj] && x[i][j] == x[ti][tj]) {
            dfs(ti, tj, c);
        }
    }
}

