using namespace std;
typedef long long ll;
const ll mod = 1000000007;

const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};

int main() {
    int h, w;
	cin >> h >> w;

    vector<vector<int>> visited(h, vector<int>(w));
    vector<vector<int>> color(h, vector<int>(w));  // color[i][j] : (i,j)が白のとき0、黒のとき1

	rep(i, h) {
		string s;
        cin >> s;
        rep(j, w) {
            if(s[j] == '#') {
                color[i][j] = 1;
            }
        }
	}

	ll ans = 0;
	rep(i, h) {
		rep(j, w) {

            if(visited[i][j]) {
                continue;
            }

            ll black = 0, white = 0;

			queue<pair<int, int>> Q;

			Q.push(make_pair(i,j));
			while(!Q.empty()) {

				auto p = Q.front();
				Q.pop();

				int x = p.first;
                int y = p.second;

                visited[x][y] = 1;

				if(color[x][y]) {
                    black++;
                } 
				else {
                    white++;
                } 

				rep(k, 4) {

					int nx = x + dx[k];
                    int ny = y + dy[k];

					if(visited[nx][ny]) {
                        continue;
                    }

                    if(nx < 0 || h <= nx || ny < 0 || w <= ny) {
                        continue;
                    }

                    if(color[x][y] == color[nx][ny]) {
                        continue;
                    }

					Q.push(make_pair(nx,ny));
				}

			}

			ans += black*white;
		}
	}

	cout << ans << endl;
	return 0;
}

