int bz[404*404], wz[404*404];
int rep[404*404];
const int dr[4] = {1,0,-1,0}, dc[4] = {0,1,0,-1};

int f(int x){return x == rep[x] ? x : rep[x] = f(rep[x]);}
void c(int x, int y){
    x = f(x); y = f(y);
    if(x == y) return;
    bz[x] += bz[y];
    wz[x] += wz[y];
    rep[y] = x;
}

