        }
    }
    for(int i = 1; i <= h; i++){
        for(int j = 1; j <= w; j++){
            for(int d = 0; d < 4; d++){
                int ni = i + dr[d], nj = j + dc[d];
                if(buf[i][j] != buf[ni][nj] && buf[i][j] + buf[ni][nj] == '#' + '.'){
                    c(e(i,j), e(ni,nj));
