{
    memset(visited, 0, sizeof(visited));
}

void dfs(int x, int y, char c)
{
    if (x < 0 || x >= rows || y < 0 || y >= columns || visited[x][y] || grid[x][y] == c)
        return;

    visited[x][y] = 1;

    if (grid[x][y] == '#')
        black++;
    else
        yellow++;

    for (int i = 0; i < 4; i++)
    {
        dfs(x + dx[i], y + dy[i], grid[x][y]);
    }
}

int main()
{
