    for (int i = 0; i < rows; i++)
    {
        for (int j = 0; j < columns; j++)
        {
            if (grid[i][j] == '#' and visited[i][j] == 0)
            {
                black = yellow = 0;
                dfs(i, j, '.');
                answer += black * yellow;
            }
        }
    }

    cout << answer << endl;

    return 0;
}

