int dfs(int x, int y, int cnt) {
  if (arrived[y][x]) {
    return cnt;
  }
  arrived[y][x] = 1;
  if (!grid[y][x]) {
    ++cnt;
  }
  if (x > 0 && grid[y][x-1] ^ grid[y][x]) cnt = dfs(x-1, y, cnt);
  if (x < w-1 && grid[y][x+1] ^ grid[y][x]) cnt = dfs(x+1, y, cnt);
  if (y > 0 && grid[y-1][x] ^ grid[y][x]) cnt = dfs(x, y-1, cnt);
  if (y < h-1 && grid[y+1][x] ^ grid[y][x]) cnt = dfs(x, y+1, cnt);

  return cnt;
}
