    vector<string> field(h);
    for (string &s: field) cin >> s;
    UnionFind uf(h * w);
    auto idx = [&](int i, int j) { return i * w + j; };
    for (int i = 0; i < h; i++) for (int j = 0; j < w; j++) {
        for (int di: {-1, 0, 1}) for (int dj: {-1, 0, 1}) {
            if (di * di + dj * dj != 1) continue;
            int ni = i + di, nj = j + dj;
            if (ni < 0 || ni >= h || nj < 0 || nj >= w) continue;
            if (field[i][j] != field[ni][nj]) uf.unionSet(idx(i, j), idx(ni, nj));
        }
    }
    map<int, map<char, int>> cnt;
    for (int i = 0; i < h; i++) for (int j = 0; j < w; j++) {
        cnt[uf.root(idx(i, j))][field[i][j]]++;
    }
