int judge(int i, int j, int h, int w){
    int ret = 0;
    bool checked[401][401] = {false};
    queue<int> qx, qy;
    int dy[4] = {0, 0, 1, -1};
    int dx[4] = {1, -1, 0, 0};
    qy.push(i);
    qx.push(j);
    checked[i][j] = true;
    while(!qx.empty()){
        int y = qy.front(), x = qx.front();
        rep(k, 4){
            int ny = y + dy[k], nx = x + dx[k];
            if(ny < 0 || h <= ny || nx < 0 || w <= nx) continue;
            if(!checked[ny][nx] && s[y][x] != s[ny][nx]){
                if(!finished[ny][nx] && s[i][j] != s[ny][nx]){
                    ret++;
                    cout << i << ',' << j << ',' << ny << ',' << nx << endl;
                }
                checked[ny][nx] = true;
                qy.push(ny);
                qx.push(nx);
            }
        }
        qy.pop();
        qx.pop();
    }
    finished[i][j] = true;
    return ret;
}

