//union_find(親par,深さrnk)
int rnk[160801],par[160801];
void union_init(int n){
    for(int i=0;i<n;i++){
        par[i]=i;
        rnk[i]=0;
    }
}

int find(int x){
    if(par[x]==x){
        return x;
    }
    else{
        return par[x]=find(par[x]);
    }
}

void unite(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y){
        return;
    }
    if(rnk[x]<rnk[y]){
        par[x]=y;
    }
    else{
        par[y]=x;
        if(rnk[x]==rnk[y]){
            rnk[x]++;
        }
    }
}
//集合が同じか
bool same(int x,int y){
    return find(x)==find(y);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int H,W;
    cin >> H >> W;
    union_init(160801);
    vector<char> c(401*401,' ');
    rep(i,H){
        rep(j,W){
            cin >> c[i*401+j];
        }
    }
    rep(i,H){
        rep(j,W-1){
            if(c[i*401+j]!=c[i*401+j+1]){
                unite(i*401+j,i*401+j+1);
            }
        }
    }
    rep(i,H-1){
        rep(j,W){
            if(c[i*401+j]!=c[(i+1)*401+j]){
                unite(i*401+j,(i+1)*401+j);
            }
        }
    }
    map<ll,ll> mp;
    rep(i,160801){
        mp[par[i]*2+i%2]++;
    }
    ll ans=0;
    rep(i,160801){
        ans+=mp[2*i]*mp[2*i+1];
    }
    cout << ans << endl;
}
