int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, -1, 0, 1};
int Y, X;
vector<vector<char>> G;
vector<vector<bool>> seen;

pll dfs(int y, int x, ll &w, ll &b) {
    seen[y][x] = true;
    if (G[y][x] == '#')
        b++;
    else
        w++;
    for (int i = 0; i < 4; i++) {
        int nx = x + dx[i];
        int ny = y + dy[i];
