int movecheck(int x, int y, int h, int w, int check){
    int flag=0;
    int answer=0;
    if(x+1<h && move[x+1][y]==check){
        move[x+1][y]=2;
        answer+=movecheck(x+1,y,h,w,(check+1)%2)+check;
    }
    if(y+1<w && move[x][y+1]==check){
        move[x][y+1]=2;
        answer+=movecheck(x,y+1,h,w,(check+1)%2)+check;
    }
    if(x-1>=0 && move[x-1][y]==check){
        move[x-1][y]=2;
        answer+=movecheck(x-1,y,h,w,(check+1)%2)+check;
    }
    if(y-1>=0 && move[x][y-1]==check){
        move[x][y-1]=2;
        answer+=movecheck(x,y-1,h,w,(check+1)%2)+check;
    }
    return answer;
