class union_find {
  std::vector<intmax_t> tree;

public:
  union_find(size_t n): tree(n, -1) {}

  size_t find(size_t v) {
    if (tree[v] < 0)
      return v;

    return (tree[v] = find(tree[v]));
  }

  bool unite(size_t u, size_t v) {
    u = find(u);
    v = find(v);
    if (u == v)
      return false;

    if (-tree[u] >= -tree[v])
      std::swap(u, v);

    tree[v] += tree[u];
    tree[u] = v;
    return true;
  }

  bool connected(size_t u, size_t v) {
    return (find(u) == find(v));
  }

  size_t size(size_t v) {
    return -tree[find(v)];
  }
};

constexpr size_t di[] = {size_t(-1), 0, 1, 0};
constexpr size_t dj[] = {0, size_t(-1), 0, 1};

int main() {
  size_t H, W;
  scanf("%zu %zu", &H, &W);

  std::vector<std::string> S(H);
  for (size_t i = 0; i < H; ++i) {
    char buf[512];
    scanf("%s", buf);
    S[i] = buf;
  }

  auto encode = [=](size_t h, size_t w) {
    return W*h + w;
  };
  auto decode = [=](size_t e)->std::pair<size_t, size_t> {
    size_t w = e % W;
    size_t h = e / W;
    return {h, w};
  };

  union_find uf(H*W);
  for (size_t i = 0; i < H; ++i) {
    for (size_t j = 0; j < W; ++j) {
      for (int k = 0; k < 4; ++k) {
        size_t ni = i + di[k];
        size_t nj = j + dj[k];
        if (!(ni < H && nj < W)) continue;
        if (S[i][j] == S[ni][nj]) continue;

        uf.unite(encode(i, j), encode(ni, nj));
      }
    }
  }

  std::map<size_t, std::pair<intmax_t, intmax_t>> map;
  for (size_t i = 0; i < H; ++i)
    for (size_t j = 0; j < W; ++j) {
      size_t par = uf.find(encode(i, j));
      ++((S[i][j] == '.')? map[par].first:map[par].second);
    }

  intmax_t res = 0;
  for (const auto& p: map)
    res += p.second.first * p.second.second;

  printf("%jd\n", res);
}

