void dfs(int x, int y, char last_color, int area) {
    if (x < 0 || h <= x || y < 0 || w <= y) return;
    if (reached[x][y]) return;
    if (maze[x][y] == last_color) return;
    else {
        reached[x][y] = true;
        if (maze[x][y] == '#') num[area].first++;
        else num[area].second++;
        last_color = maze[x][y];
    }
    dfs (x + 1, y, last_color, area);
    dfs (x - 1, y, last_color, area);
    dfs (x, y + 1, last_color, area);
    dfs (x, y - 1, last_color, area);
}

