    int area = -1;
    rep(i, 0, h) {
        rep(j, 0, w) {
            if (maze[i][j] == '#') {
                area++;
                char last_color = '.';
                dfs(i, j, last_color, area);
                ans += num[area].first * num[area].second;
            }
        }
    }

    cout << ans << endl;
    return 0;
}

