long long H,W;
void f(int i,int j,bool last){
    if(i<0||i>=H||j<0||j>=W||!flags[i][j]) return;
    flags[i][j]=false;
    //last true means last is .
    if(last){
	if(v[i][j]=='.'){
	    flags[i][j]=true;
	    return;
	}
	blackNum++;
	last=false;
    }
    else{
	if(v[i][j]=='#'){
	    flags[i][j]=true;
	    return;
	}
	whiteNum++;
	last=true;
    }
    f(i-1,j,last);
    f(i+1,j,last);
    f(i,j-1,last);
    f(i,j+1,last);
}


