int check(int y, int x) {
  bool visited[SIZE][SIZE] = {};

  if (s[y][x] != '#') return 0;

  queue<pair<int,int> > que;
  que.push({y,x});

  int res = 0;

  while(que.size()){
    auto p = que.front();
    que.pop();

    int y = p.first;
    int x = p.second;

    if(visited[y][x]) continue;
    visited[y][x] = true;

    res += s[y][x] != '#';

    for(int i=0;i<4;i++){
      if(0 <= y+dy[i] && y+dy[i] < h && 0<= x+dx[i] && x+dx[i] < w &&
         s[y][x] != s[y+dy[i]][x+dx[i]]){
        que.push({y+dy[i], x+dx[i]});
      }
    }
  }

  return res;
}

int main(){

  scanf("%d%d", &h, &w);

  for(int i=0;i<h;i++){
    scanf("%s", s[i]);
  }

  ll ans = 0;

  for(int i=0;i<h;i++)
    for(int j=0;j<w;j++)
      ans += check(i, j);

  cout << ans << endl;

  return 0;
}

