map<int, pair<int, int>> m;

pair<ll, ll> dfs(int pos, vector<int>& used, vector<vector<int>>& g, vector<string>& S) {
	if (used[pos])return { 0,0 };
	used[pos] = 1;
	pair<ll, ll> tmp = { 0,0 };
	if (S[m[pos].first][m[pos].second] == '.')tmp.first += 1;
	else tmp.second += 1;
	for (int i = 0; i < g[pos].size(); i++) {
		if (used[g[pos][i]])continue;
		auto a = dfs(g[pos][i], used, g, S);
		tmp.first += a.first;
		tmp.second += a.second;
	}
	return tmp;
}
int main() {
	io_init;
	int H, W;
	cin >> H >> W;
	vector<string> S(H);
	for (int i = 0; i < H; i++) {
		cin >> S[i];
	}
	vector<vector<int>> g(H * W);
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			m[i * W + j] = { i,j };
			if (i != 0) {
				if (S[i][j] != S[i - 1][j]) {
					g[i * W + j].push_back((i - 1) * W + j);
					g[(i - 1) * W + j].push_back(i * W + j);
				}
			}
			if (i != H-1) {
				if (S[i][j] != S[i + 1][j]) {
					g[i * W + j].push_back((i + 1) * W + j);
					g[(i + 1) * W + j].push_back(i * W + j);
				}
			}
			if (j != 0) {
				if (S[i][j] != S[i][j - 1]) {
					g[i * W + j].push_back(i * W + j - 1);
					g[i * W + j - 1].push_back(i * W + j);
				}
			}
			if (j != W-1) {
				if (S[i][j] != S[i][j + 1]) {
					g[i * W + j].push_back(i * W + j + 1);
					g[i * W + j + 1].push_back(i * W + j);
				}
			}
		}
	}
	ll ans = 0;
	vector<int> used(H * W, 0);
	for (int i = 0; i < H * W; i++) {
		auto a = dfs(i, used, g, S);
		ans += a.first * a.second;
	}
	cout << ans << endl;
}

