		}

		for (int i = 0; i < 4; i++) {
			int a = nx + dx[i], b = ny + dy[i];
			if (a < 0 || a >= h || b < 0 || b >= w) continue;
			if (grid[a][b] == grid[nx][ny]) continue;
			if (used[a][b]) {
				if (grid[nx][ny]) black[a][b]++;
				else white[a][b]++;
				continue;
			}

			if (grid[nx][ny]) {
				black[a][b] = black[nx][ny] + 1;
				white[a][b] = white[nx][ny];
			} else {
				black[a][b] = black[nx][ny];
				white[a][b] = white[nx][ny] + 1;
			}
			q.push({a, b});
			used[a][b] = true;
		}
	}
}

