struct UnionFind{
  VI par;
  UnionFind(int N):par(N){
    rep(i,N) par[i]=i;
  }
  int root(int x){
    if(par[x]==x) return x;
    return par[x]=root(par[x]);
  }
  void unite(int x, int y){
    int rx=root(x);
    int ry=root(y);
    if(rx==ry) return;
    par[rx]=ry;
  }
  bool same(int x, int y){
    int rx=root(x);
    int ry=root(y);
    return rx==ry;
  }
};
int main(){
  int H,W;
  cin>>H>>W;
  vector<string> S(H);
  rep(i,H) cin>>S[i];
  UnionFind tree(H*W);
  rep(i,H) rep(j,W-1) if(S[i][j]!=S[i][j+1]) tree.unite(i*W+j,i*W+j+1);
  rep(i,H-1) rep(j,W) if(S[i][j]!=S[i+1][j]) tree.unite(i*W+j,(i+1)*W+j);
  VI N(H*W);
  VI B(H*W);
  rep(i,H) rep(j,W){
    N[tree.root(i*W+j)]++;
