struct UnionFind {
    int n; // id : 0...n-1
    vector<int> par;

    UnionFind(int n) : n(n), par(n,-1) { }
    int root(int x) {
        assert(0 <= x && x < n);
        return par[x] < 0 ? x : par[x] = root(par[x]);
    }
    bool unite(int x, int y) {
        x = root(x), y = root(y);
        if (x == y) return false;
        if (par[x] < par[y]) swap(x,y);
        par[y] += par[x];
        par[x] = y;
        return true;
    }
    bool same(int x, int y) { return root(x) == root(y); }
    int size(int x) { return -par[root(x)]; }
};

int32_t main() {
    int h,w; cin >> h >> w;
    vector<string> v(h); cin >> v;
    const auto id = [=](int i, int j) { return i*w+j; };
    UnionFind uf(h*w);
    rep (i,h-1) rep (j,w) {
        if (v[i][j] != v[i+1][j]) uf.unite(id(i,j),id(i+1,j));
    }
    rep (i,h) rep (j,w-1) {
        if (v[i][j] != v[i][j+1]) uf.unite(id(i,j),id(i,j+1));
    }
    vector<int> a(h*w),b(h*w);
    rep (i,h*w) {
        (v[i/w][i%w] == '.' ? a : b)[uf.root(i)]++;
    }
    int sum = 0;
    rep (i,h*w) sum += a[i]*b[i];
    cout << sum << "\n";
}

