using namespace std;
#define SIZE 200000
class unionfind
{
public:
	int par[SIZE];
	int ran[SIZE];
	int r1[SIZE], r2[SIZE];
	void init()
	{
		for (int i = 0; i<SIZE; i++)
		{
			par[i] = i;
			ran[i] = 0;
		}
	}
	int find(int a)
	{
		if (a == par[a])return a;
		else return par[a] = find(par[a]);
	}
	void unite(int a, int b)
	{
		a = find(a);
		b = find(b);
		if (a == b)return;
		if (ran[a]>ran[b])
		{
			par[b] = a;
			r1[a] += r1[b];
			r2[a] += r2[b];
		}
		else
		{
			par[a] = b;
			r1[b] += r1[a];
			r2[b] += r2[a];
		}
		if (ran[a] == ran[b])ran[b]++;
	}
};
