typedef pair<int,int> P;
int dx[4] = {-1,0,1,0};
int dy[4] = {0,-1,0,1};
bool mat[500][500];
bool used[500][500];
int h,w;
bool inLimit(int x,int y)
{
	if(x>=0 && x<h && y>=0 && y<w)
	{
		return true;
	}
	else
	{
		return false;
	}
}
bool valid(int ci,int cj,int d)
{
	int ni = ci + dx[d];
	int nj = cj + dy[d];
	if(!inLimit(ni,nj))
	{
		return false;
	}
	if(mat[ci][cj]==mat[ni][nj])
	{
		return false;
	}
	return true;

}
int main()
{
	//int h,w;
	cin>>h>>w;
	vector<string>ss;
	for(int i=0;i<h;i++)
	{
		string s;
		cin>>s;
		ss.push_back(s);
	}
	for(int i=0;i<h;i++)
	{
		for(int j=0;j<w;j++)
		{
			if(ss[i][j]=='#')
			{
				mat[i][j] = 1;
			}
			else if(ss[i][j]=='.')
			{
				mat[i][j] = 0;
			}
		}
	}
	lld ans = 0 ;
	lld b=0,wt=0;
	for(int i=0;i<h;i++)
	{
		for(int j=0;j<w;j++)
		{
			if(used[i][j])
			{
				continue;
			}
			b = 0;
			wt = 0;
			queue<P>Q;
			Q.push(P(i,j));
			used[i][j] = true;
			while(!Q.empty())
			{
				P p = Q.front();
				Q.pop();
				int ci = p.first;
				int cj = p.second;
				if(mat[ci][cj]==1)
				{
					b++;
				}
				else
				{
					wt++;
				}
				for(int d=0;d<4;d++)
				{
					if(!valid(ci,cj,d))
					{
						continue;
					}
					int ni = ci + dx[d];
					int nj = cj + dy[d];
					if(used[ni][nj])
					{
						continue;
					}
					used[ni][nj] = true;
					Q.push(P(ni,nj));
				}
			}
			ans += (b*wt);
		}
	}
	cout<<ans<<"\n";
}

