class union_find{
        vector<long> parent, tree_size, w_size;
    public:
        union_find(unsigned long _n) : parent(_n), tree_size(_n, 1), w_size(_n, 0){
            for(unsigned long i = 0; i < _n; ++i)parent[i] = i;
        }
        void init(vector<string> g, int h, int w){
            rep(i, h) rep(j,w) if(g[i][j] == '.') w_size[i*w + j] = 1;
        }
        ll find(ll x){
            while(parent[x] != x)x = parent[x] = parent[parent[x]];
            return x;
        }
        void merge(ll a, ll b){
            a = find(a);
            b = find(b);
	        if(a==b) return;
            if(tree_size[a] < tree_size[b])swap(a, b);
            tree_size[a] += tree_size[b];
            w_size[a] += w_size[b];
            parent[b] = a;
            return;
        }
	    bool same(ll a, ll b){
	        a = find(a);
	        b = find(b);
	        return a == b;
	    }
	    ll white(ll a){
            return w_size[find(a)];
        }
    };
//uf.mergeのように使う
//ufはMAX_N+1でとるか、代入時に0-indexedにする

