                    if(G[h][w] != G[nh][nw]) uf.merge(h*W + w, nh*W + nw);
                }
            }
        }
    }
    ll ans = 0;
    rep(h,H){
        rep(w, W){
            if(G[h][w] == '#') ans += uf.white(h*W + w);
        }
    }
    cout<<ans<<endl;
}

