		//		data[l].second = 1;
		//	}
		//}
	}
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y].first < data[x].first) swap(x, y);
			data[x].first += data[y].first;
			data[x].second += data[y].second;
			data[y].first = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x].first < 0 ? x : data[x].first = root(data[x].first);
	}
	int size(int x) {
		return -data[root(x)].first;
	}
	int size_black(int x) {
		return data[root(x)].second;
	}
};

