#define REP(i,n) for (int i = 0; i < n; i++)
template <class T> using reversed_priority_queue = priority_queue<T, vector<T>, greater<T> >;
typedef long long ll;

const int dx[4] = {0,1,0,-1};
const int dy[4] = {1,0,-1,0};

int H,W;
vector < string > S;

int cntW;
int cntB;
bool used[410][410];

void dfs (int x, int y)
{
    queue < pair < char, pair < int,int > > > sta;
    sta.push(make_pair(S[x][y], make_pair(x,y)));

    while (sta.size() > 0) {
        int cur = sta.front().first;
        int nx = sta.front().second.first;
        int ny = sta.front().second.second;
        sta.pop();
        if (used[nx][ny]) continue;
        used[nx][ny] = true;
        if (S[nx][ny] == '#') {
            cntB++;
        } else {
            cntW++;
        }
        REP(i,4) {
            int nnx = nx + dx[i];
            int nny = ny + dy[i];
            if (nnx < 0 || nny < 0 || nnx >= H || nny >= W) continue;
            if (S[nnx][nny] == cur) continue;
            sta.push(make_pair(S[nnx][nny], make_pair(nnx, nny)));
        }
    }
}

int main ()
{
    cin >> H >> W;
    S.resize(H);
    REP(i,H) cin >> S[i];

    REP(i,410) REP(j,410) used[i][j] = false;

    ll ans = 0;
    REP(x,H) REP(y,W) {
        cntW = 0;
        cntB = 0;
        dfs(x,y);
        ans += cntW * cntB;
    }

    cout << ans << endl;

    return 0;
}

