char s[500][500];
int ans = 0;
int h, w;
int use[400][400] = {};
void search(int i, int j, int k)
{
    if (s[i][j] != s[i][j - 1] && k != 1 && 0 < j && use[i][j] == 0)
    {
        ans++;
        use[i][j] = 1;
        search(i, j - 1, 4);
        use[i][j] = 0;
    }
    if (s[i][j] != s[i + 1][j] && k != 2 && i < h - 1 && use[i][j] == 0)
    {
        ans++;
        use[i][j] = 1;
        search(i + 1, j, 3);
        use[i][j] = 0;
    }
    if (s[i][j] != s[i - 1][j] && k != 3 && 0 < i && use[i][j] == 0)
    {
        ans++;
        use[i][j] = 1;
        search(i - 1, j, 2);
        use[i][j] = 0;
    }
    if (s[i][j] != s[i][j + 1] && k != 4 && w - 1 > j && use[i][j] == 0)
    {
        ans++;
        use[i][j] = 1;
        search(i, j + 1, 1);
        use[i][j] = 0;
    }
    if (s[i][j] == '#' && k != 0)
        ans--;
    return;
}
