void bfs(P idx) {
    char now = s[idx.first][idx.second], next = s[idx.first][idx.second];
    que.push(idx);
    seen[idx.first][idx.second] = true;
    mp[s[idx.first][idx.second]]++;

    while (!que.empty()) {
        P p = que.front();
        que.pop();
        rep(i, 4) {
            ll nx = p.first + dx[i], ny = p.second + dy[i];
            // 移動可能なマスの場合
            if (0 <= nx && nx < h && 0 <= ny && ny < w && !seen[nx][ny]) {
                if (now != s[nx][ny]) {
                    // queに入れて，最小値更新
                    que.push(P(nx, ny));
                    mp[s[nx][ny]]++;
                    seen[nx][ny] = true;
                    next = s[nx][ny];
                } else if (next_que.empty()) {
                    next_que.push(P(nx, ny));
                }
            }
        }
        now = next;
    }
    ans += mp['#'] * mp['.'];
    mp.clear();
    if (!next_que.empty()) {
        P tmp = next_que.front();
        next_que.pop();
        bfs(tmp);
    }
}

