#include <bits/stdc++.h>
using namespace std;
const int MAX_N = 160090;

int par[MAX_N], Rank[MAX_N], size[MAX_N];
const int dx[] = {0, 0, -1, 1};
const int dy[] = {-1, 1, 0, 0};
void init(int n)
{
    for (int i = 0; i < n; i++)
    {
        par[i] = i;
        Rank[i] = 0;
        size[i] = 1;
    }
}
int find(int x)
{
    if (par[x] == x)
    {
        return x;
    }
    else
    {
        return par[x] = find(par[x]);
    }
}
void unite(int x, int y)
{
    x = find(x);
    y = find(y);
    if (x == y)
        return;
    if (Rank[x] < Rank[y])
    {
        par[x] = y;
        size[y] += size[x];
    }
    else
    {
        par[y] = x;
        size[x] += size[y];
        if (Rank[x] == Rank[y])
            Rank[x]++;
    }
}

bool same(int x, int y)
{
    return find(x) == find(y);
}
int main()
{
    int H, W;
    cin >> H >> W;
    string S[H];
    init(MAX_N);
    for (int i = 0; i < H; i++)
    {
        cin >> S[i];
    }
    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            for (int k = 0; k < 4; k++)
            {
                int nx = i + dx[k];
                int ny = j + dy[k];
                if (0 <= nx && nx < H && 0 <= ny && ny < W)
                {
                    if (S[i][j] != S[nx][ny])
                    {
                        unite(i * W + j, nx * W + ny);
                    }
                }
            }
        }
    }
    map<long long, long long> white;
    map<long long, long long> black;
    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            if (S[i][j] == '#')
            {
                white[find(i * W + j)]++;
            }
            else
            {
                black[find(i * W + j)]++;
            }
        }
    }
    long long sum = 0;
    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            sum += white[i * W + j] * black[i * W + j];
        }
    }
    cout << sum << endl;
}

