using namespace std;

vector<string> s;

const int dx[] = {1, 0, -1, 0};
const int dy[] = {0, -1, 0, 1};
int h, w;

bool is_in(int x, int y){
  return x>=0 && x<w && y>=0 && y<h;
}

bool check(int x, int y, int d){
  int nx = x + dx[d];
  int ny = y+dy[d];
  if(!is_in(nx, ny))return false;
  return (s[y][x]!=s[ny][nx]);
}

int main(){
  cin>>h>>w;
  s.resize(h);
  rep(i,h)cin>>s[i];

  ll result=0;
  ll bl,wh;
  set<pair<int, int>> used;
  rep(i, h)rep(j,w){

    bl=0;
    wh=0;
    queue<pair<int, int>> q;
    auto fp = make_pair(i,j);
    q.push(fp);
    used.insert(fp);
    while(!q.empty()){
      auto p = q.front();q.pop();
      int cy = p.first;
      int cx = p.second;
      if(s[cy][cx]=='#')bl++;
      else wh++;
      rep(k, 4){
        if(!check(cx, cy, k))continue;
        int nx=cx+dx[k];
        int ny = cy+dy[k];
        auto np = make_pair(ny, nx);
        if(used.count(np)==1)continue;
        used.insert(np);
        q.push(np);
      }
    }
//cout<<i<<j<<'|'<<wh<<' '<<bl<<endl;
    result += wh*bl;
  }

  cout<<result;

  return 0;
}

