void init(int x,int y){
    for(int i = 0;i < x;i++){
        for(int j = 0;j < y;j++){
            reached[i][j] = 0;
        }
    }
    for(int i = 0;i < x*y;i++){
        b[i] = 0;
        w[i] = 0;
    }
}
void search(int x,int y,int k){ //深さ優先探索
    if(x < 0 || x >= H || y < 0 || y >= W || reached[x][y] == 1)return;

    reached[x][y] = 1;
    if(S[x][y] == '#')b[k]++;
    if(S[x][y] == '.')w[k]++;

    if(x<H){
        if(S[x][y] != S[x+1][y])search(x+1,y,k);
    }
    if(x>0){
        if(S[x][y] != S[x-1][y])search(x-1,y,k);
    }
    if(y<W){
        if(S[x][y] != S[x][y+1])search(x,y+1,k);
    }
    if(y>0){
        if(S[x][y] != S[x][y-1])search(x,y-1,k);
    }
}



