using namespace std;

struct edge_base {
  int from;
  int to;
};

template<class E>
struct graph_base {
  virtual void add_edge(E e) = 0;
  virtual const vector<E>& operator[](int i) const = 0;
  virtual int N() const = 0;
};

template<class E>
struct graph : graph_base<E> {
  vector<vector<E>> G;
  graph(int n) : G(n) {}
  void add_edge(E e) {
    G[e.from].push_back(e);
  }
  const vector<E>& operator[](int i) const { return G[i]; }
  int N() const { return G.size(); }
};

struct grid : public graph<edge_base> {
  using P = pair<int,int>;
  using Delta = function<vector<P>(P,int,int)>;
  Delta delta;
  int n;
  int m;
  grid(int n , int m ,Delta d) : graph<edge_base>(n * m), n(n) , m(m), delta(d) {
    for(int x = 0;x < n;x++) {
      for(int y = 0;y < m;y++) {
        vector<P> res = std::move(delta({x,y},n,m));
        for(auto& v : res) {
          this->add_edge({en({x,y}), en(v)});
        }
      }
    }
  }
  int N() const { return n * m; }
  int en(P p) const { return p.first * m + p.second; }
  P de(int i) const { return {i / m , i % m}; }
};

function<vector<pair<int,int>>(pair<int,int>,int,int)> cross_delta = [](pair<int,int> p,int n,int m) {
  vector<pair<int,int>> vec;
  int d[] = {1,0,-1,0};
  int x = p.first;
  int y = p.second;
  for(int i = 0;i < 4;i++) {
    if(x + d[i] < 0 || x + d[i] >= n) continue;
    if(y + d[i ^ 1] < 0 || y + d[i ^ 1] >= m) continue;
    vec.push_back({x + d[i] , y + d[i ^ 1]});
  }
  return move(vec);
} ;
function<vector<pair<int,int>>(pair<int,int>,int,int)> eight_delta = [](pair<int,int> p,int n,int m) {
  vector<pair<int,int>> vec;
  int x = p.first;
  int y = p.second;
  for(int i = -1;i <= 1;i++) {
    for(int j = -1;j <= 1;j++){
      if(i == 0 && j == 0) continue;
      if(x + i < 0 || x + i >= n) continue;
      if(y + j < 0 || y + j >= m) continue;
      vec.push_back({x + i , y + j});
    }
  }
  return move(vec);
} ;


