 class UnionFind {
  public:
   vector<ll> parent, size;
   vector<ll> n_white, n_black;

   UnionFind(ll n) {
     parent.resize(n);
     n_black.resize(n);
     n_white.resize(n);
     iota(parent.begin(), parent.end(), 0);
     size.resize(n, 1);
   }  

   ll Find(ll x) {
     return x == parent[x] ? x : parent[x] = Find(parent[x]);
   }
   bool Merge(ll x, ll y) {
     ll px = Find(x), py = Find(y);
     if (px == py) return false;
     if (size[px] < size[py]) swap(px, py);
     parent[py] = px;
     size[px] += size[py];
     n_black[px] += n_black[py];
     n_white[px] += n_white[py];
     return true;
   }
 };

int main () {
  ios::sync_with_stdio(0); cin.tie(0);

  // cin >> TT;
