  UnionFind uf(h*w);
  for (ll y = 0; y < h; ++y) {
    for (ll x = 0; x < w; ++x) {
      if (M[y][x] == '#') {
        ++uf.n_black[y*w+x];
      } else {
        ++uf.n_white[y*w+x];
      }
    }
  }

  for (ll y = 0; y < h; ++y) {
    for (ll x = 0; x < w; ++x) {
      for (ll dy = -1; dy <= 1; ++dy) {
        for (ll dx = -1; dx <= 1; ++dx) {
