            uf.Merge(y*w+x, (y+dy)*w + x+dx);
          }
        }
      }
    }
  }
  vector<bool> seen(h*w);
  ll ans = 0;
  for (ll y = 0; y < h; ++y) {
    for (ll x = 0; x < w; ++x) {
      ll p = uf.Find(y*w+x);
      if (!seen[p]) {
        ans += uf.n_black[p] * uf.n_white[p];
        seen[p] = true;
      }
    }
  }
  cout << ans << endl;

}

