	vector<string>s(h);
	rep(i, h)cin >> s[i];
	UnionFind UF(h * w);
	rep(i, h) {
		rep(j, w) {
			if (i != h - 1) {
				if (s[i][j] != s[i + 1][j]) {
					UF.connect(w * i + j, w * (i + 1) + j);
				}
			}
			if (j != w - 1) {
				if (s[i][j] != s[i][j + 1]) {
					UF.connect(w * i + j, w * i + j + 1);
				}
			}
		}
	}
	vllint wh(w* h, 0), br(w* h, 0);
	rep(i, h)rep(j, w) {
		if (s[i][j] == '.') {
			wh[UF.root(w * i + j)]++;
		}
