struct Dsu {
  vector<int> fa, szb, szw;
  Dsu(int n) : fa(n), szb(n, 0), szw(n, 0) {
    iota(fa.begin(), fa.end(), 0);
  }
  int find(int x) { return fa[x] == x ? x : fa[x] = find(fa[x]); }
  void unite(int x, int y) {
    int a = find(x);
    int b = find(y);
    if (a != b) {
      fa[a] = b;
      szb[b] += szb[a];
      szw[b] += szw[a];
    }
  }
};

signed main() {
  ios::sync_with_stdio(false);

  int H, W;
  cin >> H >> W;

  vector<string> S(H);
  for (int i = 0; i < H; ++i) cin >> S[i];

  Dsu dsu(H * W);
  for (int i = 0; i < H * W; ++i) {
    dsu.szw[i] = S[i / W][i % W] == '.';
    dsu.szb[i] = S[i / W][i % W] == '#';
  }
  vector<int> vis(H * W);
  for (int i = 0; i < H; ++i) {
    for (int j = 0; j < W; ++j) {
      if (vis[i * W + j]) continue;
      queue<int> que;
      que.push(i * W + j);
      vis[i * W + j] = 1;
      while (que.size()) {
        int x = que.front() / W;
        int y = que.front() % W;
        que.pop();
        static const int dx[] = {0, 1, 0, -1};
        static const int dy[] = {1, 0, -1, 0};
        for (int di = 0; di < 4; ++di) {
          int nx = x + dx[di];
          int ny = y + dy[di];
          if (nx < 0 || H <= nx || ny < 0 || W <= ny) continue;
          if (vis[nx * W + ny]) continue;
          if (S[nx][ny] == S[x][y]) continue;
          que.push(nx * W + ny);
          vis[nx * W + ny] = 1;
          dsu.unite(i * W + j, nx * W + ny);
        }
      }
    }
  }

  int64_t ans = 0;
  for (int i = 0; i < H * W; ++i) {
    if (dsu.find(i) == i) {
      int szw = dsu.szw[i];
      int szb = dsu.szb[i];
      ans += 1LL * szw * szb;
    }
  }

  cout << ans << endl;

  return 0;
}

