int snake_find(int limit, vector<int> a) {
	int n = a.size();
	int t = 0, s = 0, sum = 0;
	int res = n + 1;
	while (1) {
		while (t < n && sum < limit) {
			sum += a[t++];
		}
		// not satisfied
		if (sum < limit) {
			break;
		}
		res = min(res, t - s + 1);
		// remove first element;
		sum -= a[s++];
	}

	return res;
}

