const int dx[4] = { 1, 0, -1, 0 };
const int dy[4] = { 0, 1, 0, -1 };

int n, m;

bool ok(int x, int y) {
	return 0 <= x && x < n && 0 <= y && y < m;
}

vector<int> dsu;

int dsuFind(int x) {
	if (x == dsu[x]) return x;
	return dsu[x] = dsuFind(dsu[x]);
}

void dsuMerge(int x, int y) {
	x = dsuFind(x);
	y = dsuFind(y);
	dsu[x] = y;
}

void solve() {
	while (cin >> n >> m) {
		vector<string> a(n);
		for (int i = 0; i < n; i++) {
			cin >> a[i];
		}
		dsu.resize(n * m);
		for (int i = 0; i < sz(dsu); i++) {
			dsu[i] = i;
		}
		for (int x = 0; x < n; x++) {
			for (int y = 0; y < m; y++) {
				for (int s = 0; s < 4; s++) {
					int nx = x + dx[s];
					int ny = y + dy[s];
					if (ok(nx, ny)) {
						if (a[x][y] != a[nx][ny]) {
							dsuMerge(x * m + y, nx * m + ny);
						}
					}
				}
			}
		}
		map<int, int> w, b;
		for (int x = 0; x < n; x++) {
			for (int y = 0; y < m; y++) {
				int v = x * m + y;
				v = dsuFind(v);
				if (a[x][y] == '#') {
					b[v]++;
				}
				else {
					w[v]++;
				}
			}
		}
		ll ans = 0;
		for (int i = 0; i < n * m; i++) {
			ans += ll(w[i]) * b[i];
		}
		cout << ans << endl;
	}
}

