using namespace std;
using ll = long long;
using P = pair<ll, ll>;

const ll dx[4] = { 0, 1, 0, -1 };
const ll dy[4] = { -1, 0, 1, 0 };

ll bfs(P start, vector<string>& S, ll H, ll W)
{
    queue<P> que;
    que.push(move(start));

    ll black = 0;
    ll white = 0;
    while (!que.empty()) {
        auto q = que.front();
        que.pop();
        auto x = q.first;
        auto y = q.second;
        if (S[y][x] == '#') {
            black++;
        } else if (S[y][x] == '.') {
            white++;
        } else {
            continue;
        }

        for (ll i = 0; i < 4; i++) {
            auto nx = x + dx[i];
            auto ny = y + dy[i];
            if (nx >= 0 && nx < W && ny >= 0 && ny < H) {
                if (S[ny][nx] != '*' && S[y][x] != S[ny][nx]) {
                    que.emplace(nx, ny);
                }
            }
        }
        S[y][x] = '*';
    }

    return black * white;
}

void solve(long long H, long long W, std::vector<std::string> S)
{
    ll ans = 0;
    for (ll i = 0; i < H; i++) {
        for (ll j = 0; j < W; j++) {
            if (S[i][j] == '#') {
                ans += bfs({ j, i }, S, H, W);
            }
        }
    }
    cout << ans << endl;
}

