            visited[i][j] = true;

            array<int, 2> count = { 0, 0 };
            queue<pair<int, int>> q;
            q.push({ i, j });

            while (q.size()) {
                auto [y, x] = q.front(); q.pop();

                ++count[field[y][x] == '#'];
                for (int k = 0; k < 4; ++k) {
                    int ax = x + dx[k];
                    int ay = y + dy[k];

                    if (0 <= ax && ax < w && 0 <= ay && ay < h && !visited[ay][ax] && field[y][x] != field[ay][ax]) {
                        q.push({ ay, ax });
                        visited[ay][ax] = true;
                    }
                }
            }

            ans += count[0] * count[1];
        }
    }

    cout << ans << endl;
}

