int matrix[400][400] = {};
void count(int row, int Hrow, int col, int Wcol, int num) {
	int temp = matrix[row][col];
	if (temp == -1) {
      	matrix[row][col] = num+1;
		if (row - 1 >= 0) {
			if (matrix[row - 1][col] == -2) count(row - 1, Hrow, col, Wcol, num);
		}
		if (row + 1 < Hrow) {
			if (matrix[row + 1][col] == -2) count(row +1, Hrow, col, Wcol, num);
		}
		if (col - 1 >= 0) {
			if (matrix[row][col - 1] == -2) count(row, Hrow, col -1, Wcol, num);
		}
		if (col + 1 < Wcol) {
			if (matrix[row][col + 1] == -2) count(row, Hrow, col +1, Wcol, num);
		}
	}

	if (temp == -2) {
      	matrix[row][col] = num;
		if (row - 1 >= 0) {
			if (matrix[row - 1][col] == -1) count(row - 1, Hrow, col, Wcol, num);
		}
		if (row + 1 < Hrow) {
			if (matrix[row + 1][col] == -1) count(row +1, Hrow, col, Wcol, num);
		}
		if (col - 1 >= 0) {
			if (matrix[row][col - 1] == -1) count(row, Hrow, col -1, Wcol, num);
		}
		if (col + 1 < Wcol) {
			if (matrix[row][col + 1] == -1) count(row, Hrow, col +1, Wcol, num);
