ll bfs(int x,int y)
{
	ll a,b;
	a=b=0;
	PII t,nex;
	queue<PII> q;
	q.push(MP(x,y));
	flag[x][y]=1;
	while(!q.empty())
	{
		t=q.front();
		q.pop();
		add(t.fi,t.se,a,b);
		for(int i=0;i<4;i++)
		{
			nex=t;
			nex.fi+=dir[i][0];
			nex.se+=dir[i][1];
