			if(flag[nex.fi][nex.se]) continue;
			if(mp[nex.fi][nex.se]==mp[t.fi][t.se]) continue;
			q.push(nex);
			flag[nex.fi][nex.se]=1;
		}
	}
	return a*b;
}
