}
void operator += (pii &a, pii b) {
    a.first += b.first, a.second += b.second;
}
pii dfs(int i, int j) {
    if (used[i][j])
        return { 0, 0 };
    used[i][j] = 1;
    pii ans = { 0, 0 };
    if (ar[i][j])
        ans.first = 1;
    else
        ans.second = 1;
    int c = ar[i][j] ^ 1;
    if (check(i - 1, j, c))
        ans += dfs(i - 1, j);
    if (check(i + 1, j, c))
        ans += dfs(i + 1, j);
    if (check(i, j - 1, c))
        ans += dfs(i, j - 1);
    if (check(i, j + 1, c))
        ans += dfs(i, j + 1);
    return ans;
}

