int di[4] = {0, 1, 0, -1};
int dj[4] = {1, 0, -1, 0};

int main() {
  int H, W;
  cin >> H >> W;
  vector<vector<char>> S(H, vector<char>(W));
  rep(i, H) {
    rep(j, W) {
      cin >> S[i][j];
    }
  }

  vector<vector<bool>> visited(H, vector<bool>(W, false));

  typedef pair<int, int> P;

  int ans = 0;
  rep(h, H) {
    rep(w, W) {
      if (visited[h][w])
        continue;

      queue<P> q;
      map<char, int> m;
      q.push(P(h, w));
      visited[h][w] = true;
      m[S[h][w]]++;

      while (!q.empty()) {
        P now = q.front();
        q.pop();

        rep(d, 4) {
          int i = now.fi;
          int j = now.se;
          int ni = i + di[d];
          int nj = j + dj[d];
          if (ni < 0 || ni >= H || nj < 0 || nj >= W || visited[ni][nj])
            continue;
          if (S[i][j] == S[ni][nj])
            continue;

          m[S[ni][nj]]++;
          visited[ni][nj] = true;
          q.push(P(ni, nj));
        }
      }
      ans += m['#'] * m['.'];
    }
  }

  cout << ans << endl;
}

