const ll MAX_H = 400;
const ll MAX_W = 400;
ll blocks = 0;
ll H,W;
string S[MAX_H];
// ll v[MAX_N], w[MAX_N];
ll dp[MAX_H+1][MAX_W+1]; // メモ化テーブル

void rec(ll i, ll j){

	if (i==0 & j==0) dp[i][j] = 0;
	else if (dp[i][j]==-1){
		// printf("%lld %lld %lld \n", i,j,blocks);
		blocks++;
		dp[i][j] = blocks;
	}
	if (j<W & S[i][j]!=S[i][j+1] & dp[i][j+1]==-1){
		dp[i][j+1] = dp[i][j];
		rec(i,j+1);
	}
	if (j>0 & S[i][j]!=S[i][j-1] & dp[i][j-1]==-1){
		dp[i][j-1] = dp[i][j];
		rec(i,j-1);
	}	
	if (i<H & S[i][j]!=S[i+1][j] & dp[i+1][j]==-1){
			dp[i+1][j] = dp[i][j];
			rec(i+1,j);
	}

	if (i>0 & S[i][j]!=S[i-1][j] & dp[i-1][j]==-1){
			dp[i-1][j] = dp[i][j];
			rec(i-1,j);
	}
	return;
}

int main() {
