    visitFromBlack(x, y + 1, visited, accum);
  }
  return accum;
}
ll visitFromBlack(ll x, ll y, set<pair<ll, ll>> visited, ll accum){
  // cout << x << " " << y << endl;
  visited.insert(make_pair(x, y));
  if(x != 0 && !is_visited(x - 1, y, visited) && s[x - 1][y] == 0){
    // cout << x - 1 << " " << y << endl;
    accum++;
    visitFromWhite(x - 1, y, visited, accum);
  }
  if(y != 0 && !is_visited(x, y - 1, visited) && s[x][y - 1] == 0){
    // cout << x << " " << y - 1 << endl;
    accum++;
    visitFromWhite(x, y - 1, visited, accum);
  }
  if(x < H - 1 && !is_visited(x + 1, y, visited) && s[x + 1][y] == 0){
    // cout << x + 1 << " " << y << endl;
    accum++;
    visitFromWhite(x + 1, y, visited, accum);
