int main(void) {
    lint h, w; cin >> h >> w;
    vector<string> a(h);
    for (int i = 0; i < h; i++)
        cin >> a[i];
    UnionFind d(h * w);
    for (int i = 0; i < h; i++)
        for (int j = 0; j < w - 1; j++)
            if (a[i][j] != a[i][j + 1])
                d.unite(i * w + j, i * w + j + 1);
    for (int i = 0; i < w; i++)
        for (int j = 0; j < h - 1; j++)
            if (a[j][i] != a[j + 1][i])
                d.unite(j * w + i, j * w + i + w);
    lint ans = 0;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (a[i][j] == '.') {
                x[d.root(i * w + j)]++;
            }
            else {
                y[d.root(i * w + j)]++;
            }
        }
    }
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            ans += x[i * w + j] * y[i * w + j];
        }
    }
    printf("%lld\n", ans);

    return 0;
}

