int H,W;
bool B[400][400];
bool checked[400][400];

void func(int i, int j, int *a, int *b){
    if(checked[i][j]==true){ return; }
    checked[i][j]=true;
    if((i+j)%2==0){
        (*a)++;
    }
    else{
        (*b)++;
    }
    if(i-1>=0 && B[i][j] == B[i-1][j]){ func(i-1,j,a,b); }
    if(j-1>=0 && B[i][j] == B[i][j-1]){ func(i,j-1,a,b); }
    if(i+1<H && B[i][j] == B[i+1][j]){ func(i+1,j,a,b); }
    if(j+1<W && B[i][j] == B[i][j+1]){ func(i,j+1,a,b); }
}
int main(){
    long count = 0;
    cin >> H >> W;
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            char c; cin >> c;
            if(c=='#'){
                B[i][j] = ((i+j)%2==0);
            }
            if(c=='.'){
                B[i][j] = ((i+j)%2!=0);
            }
            checked[i][j]=false;
        }
    }

    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            if(checked[i][j]){ continue; }
            int a=0,b=0;
            func(i,j, &a, &b);
            count += (long)a*(long)b;
        }
    }
    cout << count;
    return 0;
}

