constexpr int INF = 2e9;
struct UnionFind{
  vector<int> data;
  int __size;
  UnionFind(int sz) {
  data.assign(sz, -1);
  __size = sz;
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);//親は負でサイズを保存
    __size--;
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  bool same(int x, int y){
    return find(x) == find(y);
  }

  int size(int k) {
    return (-data[find(k)]);
  }

  int union_count() {
    return (__size);
  }
};

int dx[] = {0,1,0,-1};
int dy[] = {1,0,-1,0};
int main() {
  int h, w;
  cin >> h >> w;
  vector<string> s(h);
  rep(i,h) cin >> s[i];
  vector<int> cnt(h * w, 0);
  UnionFind uf(h * w);
  auto calc = [&](int i, int j){
    for (int k = 0; k < 4; k++) {
      int x = i + dx[k], y = j + dy[k];
      if (x < 0 || y < 0 || x >= h || y >= w) continue;
      if (s[x][y] == s[i][j]) continue;
      uf.unite(i * w + j, x * w + y);
    }
  };
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      calc(i, j);
      if (s[i][j] == '#') cnt[uf.find(i * w + j)]++;
    }
  }
  ll res = 0;
  for (int i = 0; i < h * w; i++) {
    if (s[i / w][i % w] == '.') continue;
    res += uf.size(i);
    res -= cnt[uf.find(i)];
  }
  cout << res << endl;
  return 0;
}

