int gcd(int x, int y) {
	if (y == 0)return x;
	return gcd(y, x%y);
}
int lcm(int x, int y) {
	return x / gcd(x, y)*y;
}
int kai(int x, int y) {
	int res = 1;
	for (int i = x - y + 1; i <= x; i++) {
		res *= i; res %= mod;
	}
	return res;
}
int mod_pow(int x, int y, int m) {
	int res = 1;
	while (y > 0) {
		if (y & 1) {
			res = res * x % m;
		}
		x = x * x % m;
		y >>= 1;
	}
	return res;
}

int comb(int x, int y) {
	if (y > x)return 0;
	return kai(x, y) * mod_pow(kai(y, y), mod - 2, mod) % mod;
}

int h, w;
string s[410];
bool bl[410][410];
int dx[4] = { 0,0,1,-1 }, dy[4] = { 1,-1,0,0 };
int ans;

void bfs(int x, int y) {
	queue<P> que;
	que.push({ x,y });
	bl[x][y] = true;
	int cnt1 = 0, cnt2 = 0;
	if (s[x][y] == '#')cnt1++;
	else cnt2++;
	while (!que.empty()) {
		P p = que.front(); que.pop();
		for (int i = 0; i < 4; i++) {
			int tx = p.first + dx[i], ty = p.second + dy[i];
			if (tx < 0 || h <= tx || ty < 0 || w <= ty || s[p.first][p.second] == s[tx][ty] || bl[tx][ty])continue;
			if (s[tx][ty] == '#')cnt1++;
			else cnt2++;
			bl[tx][ty] = true;
			que.push({ tx,ty });
		}
	}
	ans += cnt1 * cnt2;
}

