	for(int i = 0; i < 4; i++)
	{
		int new_x = x + dx[i];
		int new_y = y + dy[i];

		if(isIn(new_x, new_y) && v[new_x][new_y] == (v[x][y] ^ 1) && vis[new_x][new_y] == 0)
			dfs(new_x, new_y);
	}
