int dx[] = {0, -1, 0, 1}, dy[] = {-1, 0, 1, 0};

void solve() {
  int h, w; scanf("%d%d", &h, &w);
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      scanf(" %c", s[i]+j);
    }
  }
  long long ans = 0;
  set<pair<int, int>> next;
  next.emplace(0, 0);
  while (!next.empty()) {
    queue<pair<int, int>> q;
    q.push(*next.begin());
    bio[next.begin()->second][next.begin()->first] = true;
    next.erase(next.begin());
    long long black = 0, white = 0;
    while (!q.empty()) {
      const auto &p = q.front();
      next.erase(p);
      if (s[p.second][p.first] == '#') ++black;
      else ++white;
      for (int i = 0; i < 4; ++i) {
	if (p.first+dx[i] < 0 || p.first+dx[i] >= w || p.second+dy[i] < 0 || p.second+dy[i] >= h) continue;
	if (bio[p.second+dy[i]][p.first+dx[i]]) continue;
	if (s[p.second][p.first] == s[p.second+dy[i]][p.first+dx[i]]) {
	  next.emplace(p.first+dx[i], p.second+dy[i]);
	  continue;
	}
	q.emplace(p.first+dx[i], p.second+dy[i]);
	bio[p.second+dy[i]][p.first+dx[i]] = true;
      }
      q.pop();
    }
    ans += black*white;
  }
  printf("%lld", ans);
}

