    used[x][y] = true;
    cnt ++;
    rep(i, 4) {
        int nx = x + dx[i], ny = y + dy[i];
        char d = (c == '#'? '.': '#');
        if(0 <= nx && nx < h && 0 <= ny && ny < w && field[nx][ny] == d) {
            dfs(nx, ny, d);
        }
    }
}

void solve() {
	cin >> h >> w;
