#include <bits/stdc++.h>
using namespace std;

int h, w;
long cnt;
int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};
bool matrix[401][401], visited[401][401];

void reset(){
    cnt = 0;
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            if(!matrix[i][j]) visited[i][j] = false;
        }
    }
}

long dfs(int y, int x){
    visited[y][x] = true;
    long res = 0;
    if(matrix[y][x]) cnt++;
    else res = 1;
    for(int i = 0; i < 4; i++){
        int ny = y + dy[i], nx = x + dx[i];
        if(ny < 0 || ny >= h || nx < 0 || nx >= w) continue;
        if(visited[ny][nx]) continue;
        if(matrix[y][x] == matrix[ny][nx]) continue;
        res += dfs(ny, nx);
    }
    return res;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> h >> w;
    vector<pair<int, int>> black;
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            char c; cin >> c;
            if(c == '#'){
                matrix[i][j] = true;
                black.emplace_back(i, j);
            }
        }
    }
    long long ans = 0;
    for(auto p : black){
        if(visited[p.first][p.second]) continue;
        reset();
        ans += cnt * dfs(p.first, p.second);
    }
    cout << ans << endl;
    return 0;
}

