using namespace std;
int main(){
  int H, W;
  cin >> H >> W;
  vector<vector<char>> vec(H,vector<char>(W));
  for(int i=0; i<H; i++){
    for(int j=0; j<W; j++){
      cin >> vec.at(i).at(j);
    }
  }

  vector<vector<bool>> seen(H,vector<bool>(W));
  for(int i=0; i<H; i++){
    for(int j=0; j<W; j++){
      seen.at(i).at(j) = false;
    }
  }

  int64_t ans = 0;
  pair<int,int> P;
  queue<pair<int,int>> Q;
  vector<int> dx = {0,1,0,-1};
  vector<int> dy = {1,0,-1,0};

  for(int i=0; i<H; i++){
    for(int j=0; j<W; j++){
      if(seen.at(i).at(j)){
        continue;
      }
      if(vec.at(i).at(j) == '#'){
        seen.at(i).at(j) = true;
        int64_t white = 0;
        int64_t black = 1;
        for(int x=0; x<4; x++){
          int xx = i + dx.at(x);
          int yy = j + dy.at(x);
          if(xx >= 0 && xx < H && yy >= 0 && yy < W){
            if(seen.at(xx).at(yy)){
              continue;
            }
            if(vec.at(xx).at(yy) == '.'){
              white++;
              seen.at(xx).at(yy) = true;
              P = make_pair(xx,yy);
              Q.push(P);
            }
          }
        }
        int q_size = white;
        int cnt = 0;
        bool kuro = false;
        while(Q.size()){
          P = Q.front();
          Q.pop();
          cnt++;
          int a = P.first;
          int b = P.second;
          for(int k=0; k<4; k++){
            int nx = a + dx.at(k);
            int ny = b + dy.at(k);
            if(nx >= 0 && nx < H && ny >= 0 && ny < W){
              if(seen.at(nx).at(ny)){
                continue;
              }
              if(kuro){
                if(vec.at(nx).at(ny) == '.'){
                  P = make_pair(nx,ny);
                  Q.push(P);
                  seen.at(nx).at(ny) = true;
                  white++;
                }
              }
              else{
                if(vec.at(nx).at(ny) == '#'){
                  P = make_pair(nx,ny);
                  Q.push(P);
                  seen.at(nx).at(ny) = true;
                  black++;
                }
              }
            }
          }
          if(cnt == q_size){
            q_size = Q.size();
            cnt = 0;
            if(kuro){
              kuro = false;
            }
            else{
              kuro = true;
            }
          }
        }
      ans += black * white;
      }
    }
  }
  cout << ans << endl;
}

