bool vis[500][500];

int main()
{
    int n,m;
    cin >> n >> m;

    string s[n];

    for(int i=0;i<n;i++)
        cin >> s[i];

    int ans = 0;

    for(int i=0;i<n;i++)
    {
        for(int j=0;j<m;j++)
        {
            if(s[i][j] == '#')
            {
                for(int k=0;k<n;k++)
                {
                    for(int l=0;l<m;l++)
                        vis[k][l] = false;
                }

                queue <pair<int,int> > q;
                q.push({i,j});

                while(!q.empty())
                {
                    auto temp = q.front();
                    q.pop();

                    int x,y;
                    x = temp.first;
                    y = temp.second;
                    vis[x][y] = true;

                    if(!vis[x + 1][y] && x + 1 < n && s[x][y] != s[x + 1][y])
                        q.push({x + 1,y});

                    if(!vis[x - 1][y] && x - 1 >= 0 && s[x][y] != s[x - 1][y])
                        q.push({x - 1,y});

                    if(!vis[x][y + 1] && y + 1 < m && s[x][y] != s[x][y + 1])
                        q.push({x,y + 1});

                    if(!vis[x][y - 1] && y - 1 >= 0 && s[x][y] != s[x][y - 1])
                        q.push({x,y - 1});
                }

                for(int k=0;k<n;k++)
                {
                    for(int l=0;l<m;l++)
                    {
                        if(vis[k][l] && s[k][l] == '.')
                            ans++;
                    }
                }
            }
        }
    }

    cout << ans << endl;
}

