template<class T>bool chmax(T &a, const T &b) { if (a<b) { a=b; return 1;} return 0;}
template<class T>bool chmin(T &a, const T &b) { if (b<a) { a=b; return 1;} return 0;}
int dx[] = {0, 1, 0, -1}, dy[] = {1, 0, -1, 0};
/*----------------------------------------------------------------------------------*/


int main() {
    int h, w; cin >> h >> w;
    vector<string> s(h);
    rep(i,h) cin >> s[i];

    vector<vector<bool>> ok(h, vector<bool>(w,false));

    // h->h, w->w, grid[][]->s[][]
    auto bfs = [&](int sy, int sx) -> ll {
        ll a = 1, b = 0;
        queue<pair<int, int>> que;
        que.push(make_pair(sy, sx));
        vector<vector<int>> dist(h, vector<int>(w));
        ok[sy][sx] = true;
        dist[sy][sx] = 1;
        while(!que.empty()) {
            pair<int, int> cur = que.front(); que.pop();
            int y = cur.first, x = cur.second;
            for(int i = 0; i < 4; ++i) {
                int ny = y + dy[i], nx = x + dx[i];
                if(ny < 0 || nx < 0 || ny >= h || nx >= w) continue;

                if(dist[ny][nx]) continue;

                if((s[ny][nx] == '.' && s[y][x] == '#') || (s[ny][nx] == '#' && s[y][x] == '.')) {
                    // cout << ny << ' ' << nx << endl;
                    que.push(make_pair(ny, nx));
                    dist[ny][nx] = dist[y][x] + 1;
                    ok[ny][nx] = true;
                    if (s[ny][nx] == '.') a++;
                    if (s[ny][nx] == '#') b++;
                }
            }
        }
        return a*b;
    };

    ll ans = 0;
    rep(i,h) rep(j,w) {
        if (s[i][j] == '.' && !ok[i][j]) ans += bfs(i,j);
        // cout << ans << endl;
    }
    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
#define int long long
using namespace std;
const int INF = 1000000000;
const int MOD = (int)1e9 + 7;
using P = pair<int, int>;
int H, W;
int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};
vector<string> maze;
map<P, int> visited;

bool isIn(int y, int x, int H, int W)
{
    return 0 <= x && x < W && 0 <= y && y < H;
}

P dfs(int h, int w)
{
    if (visited[P(h, w)]) return P(0, 0);
    visited[P(h, w)]++;
    int black = 0;
    int white = 0;
    char currentChar = maze[h][w];
    if (currentChar == '#') black++;
    if (currentChar == '.') white++;
    P res = P(black, white);
    for (int i = 0; i < 4; i++)
    {
        int next_h = h + dy[i];
        int next_w = w + dx[i];
        if (!isIn(next_h, next_w, H, W)) continue;
        if (maze[next_h][next_w] == currentChar) continue;
        P tmp = dfs(next_h, next_w);
        res.first += tmp.first;
        res.second += tmp.second;
    }
    return res;
}

signed main()
{
    cin >> H >> W;
    for (int i = 0; i < H; i++)
    {
        string x;
        cin >> x;
        maze.push_back(x);
    }

    int cnt = 0;
    for (int h = 0; h < H; h++)
    {
        for (int w = 0; w < W; w++)
        {
            P res = dfs(h, w);
            cnt += res.first * res.second;
        }
    }
    cout << cnt << "\n";
}

