using namespace std;

typedef vector<bool> vb;
typedef pair<int, int> pii;

const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, -1, 0, 1};
pii ff(string s[], int h, int w, int x, int y, vb f[]) {
    pii ret;

    f[x][y] = true;
    if (s[x][y] == '#') {
        ret.first = 1;
        ret.second = 0;
    } else {
        ret.first = 0;
        ret.second = 1;
    }

    for (int i = 0; i < 4; i++) {
        int tx = x + dx[i], ty = y + dy[i];
        if (tx >= 0 && tx < h && ty >= 0 && ty < w && !f[tx][ty] && s[tx][ty] != s[x][y]) {
            pii t = ff(s, h, w, tx, ty, f);
            ret.first += t.first;
            ret.second += t.second;
        }
    }

    return ret;
}

int main() {
    int h, w;
    cin >> h >> w;
    string s[h];
    for (int i = 0; i < h; i++) {
        cin >> s[i];
    }

    vb f[h];
    for (int i = 0; i < h; i++) {
        f[i].resize(w, false);
    }
    long long ans = 0;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (!f[i][j]) {
                pii t = ff(s, h, w, i, j, f);
                ans += 1ll * t.first * t.second;
            }
        }
    }

    cout << ans << endl;

    return 0;
}

