// Union Find {{{
class UnionFind {
 public:
     int n;
     std::vector<int> par;
     std::vector<int> num;

     explicit UnionFind(int n) {  // [0 n)のunion find
         this->n = n;
         this->par.resize(n);
         this->num.resize(n, 1);
         for (int i = 0; i < n; i++) {
             this->par[i] = i;
         }
     }

     int root(int i) {
         if (par[i] == i)
             return i;
         else
             return par[i] = root(par[i]);
     }

     bool same(int i, int j) {
         return root(i) == root(j);
     }

     bool unite(int i, int j) {
         int t = root(i);
         int k = root(j);

         if (t == k)
           return false;

         par[t] = k;
         num[k] += num[t];
         return true;
     }

     int size(int i) {
         return num[root(i)];
     }
};
// }}}

const int dy[] = {-1, 0, 1, 0};
const int dx[] = {0, 1, 0, -1};

