  if (x-2 >= 0 && s[y][x-1] == '.' && s[y][x-2] == '#') dfs(y,x-2,sy,sx);
  if (x+2 < W  && s[y][x+1] == '.' && s[y][x+2] == '#') dfs(y,x+2,sy,sx);

  if (y-1 >= 0 && x-1 >= 0 && (s[y][x-1] == '.' || s[y-1][x] == '.') && s[y-1][x-1] == '#') dfs(y-1,x-1,sy,sx);
