int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, -1, 0, 1};

int main(){
    int H, W; cin >> H >> W;
    vector<string> grid(H);
    rep(i, H) cin >> grid[i];

    ll res = 0;
    vector<vector<int>> d(H, vector<int>(W, INF)); 
    rep(i, H){
        rep(j, W){
            //BFS 始点が白の場合のみ探索する
            if(grid[i][j]=='#' or d[i][j] != INF)continue;
            queue<pii> que; que.push({i, j});
            d[i][j] = 0;
            ll white = 1, black = 0;
            while(!que.empty()){
                auto p = que.front(); que.pop();
                int vh = p.first, vw = p.second;
                rep(k, 4){
                    int ny = vh + dy[k], nx = vw + dx[k];
                    int cost = d[vh][vw] + 1;
                    if(ny<0 or nx<0 or ny>=H or nx>=W)continue;
                    if(d[ny][nx] != INF)continue;
                    if(grid[ny][nx]=='.' and cost%2==0 or grid[ny][nx]=='#' and cost%2==1){
                        d[ny][nx] = cost;
                        que.push({ny, nx});
                        grid[ny][nx] == '#' ? black++ : white++;                                     
                    }   
                }
            }
            res += white * black;   
        }
    }
    cout << res << ln;
}

