		if(ny<0 || ny>=H || nx<0 || nx>=W) continue;
		if(ch==field[ny][nx]) continue;
		uf.merge(y*W+x,ny*W+nx);
	}
}

int main() {
	cin>>H>>W;
	for(int i=0; i<H; i++)for(int j=0; j<W; j++) cin>>field[i][j];
	for(int i=0; i<H; i++)for(int j=0; j<W; j++) srch(i,j);
