ll h, w;
char s[400][401];
bool ok[400][400];
bool checked[400][400];
ll dx[4] = {1, 0, -1, 0};
ll dy[4] = {0, 1, 0, -1};

int main() {
  scanf("%lld%lld", &h, &w);
  for (ll i = 0; i < h; i++) scanf("%s", s[i]);
  ll ans = 0;
  queue<P> que;
  for (ll i = 0; i < h; i++) for (ll j = 0; j < w; j++) checked[i][j] = false;
  for (ll i = 0; i < h; i++) {
    for (ll j = 0; j < w; j++) {
      if (checked[i][j]) continue;
      for (ll i = 0; i < h; i++) for (ll j = 0; j < w; j++) ok[i][j] = false;
      char color = s[i][j];
      que.push(P(i, j));
      ll counter = 0, temp = 0;
      while (!que.empty()) {
        P p = que.front();
        que.pop();
        ll x = p.first, y = p.second;
        if (ok[x][y]) continue;
        if (color != s[x][y]) temp++;
        else checked[x][y] = true, counter++;
        for (ll k = 0; k < 4; k++) {
          ll X = x + dx[k], Y = y + dy[k];
          if (X < 0 || X == h || Y < 0 || Y == w) continue;
          if (ok[X][Y]) continue;
          if (s[X][Y] == s[x][y]) continue;
          que.push(P(X, Y));
        }
        ok[x][y] = true;
      }
      ans += temp * counter;
    }
  }
  printf("%lld\n", ans / 2);
}

