bool isRange(int x, int y)
{
	return (0 <= x && x < H && 0 <= y && y < W);

}

int solve(int i, int j, int chk)
{
	int &ret = dp[i][j][chk];
	if (ret != -1)return ret;
	if (i == Ex && j == Ey)return 1;
	if (i >= H || j >= W)return 0;
	ret = 0;
	for (int k = 0; k < 4; k++) {
		int nx = i + dx[k];
		int ny = j + dy[k];
		if (isRange(nx, ny)&&chk==0) {
			if (grid[nx][ny] == '.')ret += solve(nx, ny, 1);

		}
		if (isRange(nx, ny) && chk == 1) {
			if (grid[nx][ny] == '#')ret += solve(nx, ny, 0);
		}
	}
	return ret;

}

