bool merge(int x, int y) {
    int ra = find(x), rb = find(y);
    if (ra != rb) {
        if (ra < rb) {
            p[rb] = ra;
            w[ra] += w[rb];
            b[ra] += b[rb];
        } else {
            p[ra] = rb;
            w[rb] += w[ra];
            b[rb] += b[ra];
        }
        return true;
    }
    return false;
}

