ll solve() {
    ll H, W;
    cin >> H >> W;
    vector<string> S(H);
    for ( int i = 0; i < H; i++ ) {
        cin >> S[i];
        for ( int j = 0; j < W; j++ ) {
            if ( (i + j) & 1 ) {
                S[i][j] = S[i][j] == '#' ? '.' : '#';
            }
        }
    }
    vector<int> dh = {0, 1, 0, -1}, dw = {1, 0, -1, 0};

    vector<vector<int>> t(H, vector<int>(W, -1));
    function<void(int,int,int)> dfs = [&](int vh, int vw, int ty) {
        if ( t[vh][vw] >= 0 ) return;
        t[vh][vw] = ty;
        for ( int ii = 0; ii < 4; ii++ ) {
            int h = vh + dh[ii];
            int w = vw + dw[ii];
            if ( h < 0 || h >= H || w < 0 || w >= W ) continue;
            if ( S[vh][vw] == S[h][w] ) {
                dfs(h, w, ty);
            }
        }
    };

    int c = 0;
    for ( int h = 0; h < H; h++ ) {
        for ( int w = 0; w < W; w++ ) {
            if ( t[h][w] == -1 ) {
                dfs(h, w, c);
                c++;
            }
        }
    }

    for ( int i = 0; i < H; i++ ) {
        for ( int j = 0; j < W; j++ ) {
            if ( (i + j) & 1 ) {
                S[i][j] = S[i][j] == '#' ? '.' : '#';
            }
        }
    }
    vector<int> num_w(c), num_b(c);
    for ( int h = 0; h < H; h++ ) {
        for ( int w = 0; w < W; w++ ) {
            ll ct = t[h][w];
            if ( S[h][w] == '#' ) {
                num_b[ct]++;
            } else {
                num_w[ct]++;
            }
        }
    }

    ll ans = 0;
    for ( int i = 0; i < c; i++ ) {
        ans += (ll)num_b[i] * (ll)num_w[i];
    }
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

