        rep(i, N) {
            par[i] = i;
        }
    }

    int root(int x) {
        if (par[x] == x)return x;
        return par[x] = root(par[x]);
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y)return;
        par[x] = y;
        b[y] += b[x];
        w[y] += w[x];
    }

    bool isRoot(int x) {
        return par[x] == x;
    }
};

