            if (S[i][j] != S[i + 1][j]) {
                uf.unite(i * W + j, (i + 1) * W + j);
            }
        }
    }

    int ans = 0;
    rep(i, W * H) {
        if (uf.isRoot(i)) {
            ans += uf.b[i] * uf.w[i];
        }
    }
    cout << ans << endl;
    return 0;
}

