  // }

  int count_mat[400][400];

  for (size_t i = 0; i < 400; i++) {
    for (size_t j = 0; j < 400; j++) {
      count_mat[i][j] = 0;
    }
  }

  ll group_count = 0;
  ll group_nums[160000];

  for (int row = 0; row < HH; row++) {
    for (int col = 0; col < WW; col++) {
      if (count_mat[row][col] == 0) {
        int group_num1 = 0, group_num2 = 0;
        search(row, col, count_mat, group_num1,group_num2, S, HH, WW);

        group_nums[group_count] = group_num1 * group_num2;
