    rep(k, 4) {
        int ni = i + dx[k], nj = j + dy[k];
        if (ni < 0 || h <= ni || nj < 0 || w <= nj) continue;
        if (seen[ni][nj]) continue;
        if (c != grid[ni][nj]) dfs(ni, nj, cnt);
    }
}

