    cin.tie(nullptr);

    cin >> h >> w;
    grid.resize(h);
    rep(i, h) cin >> grid[i];
    seen.resize(h, vector<bool>(w, false));
    ll ans = 0;
    rep(i, h) {
        rep(j, w) {
            if (!seen[i][j]) {
                P res = P(0, 0);
                dfs(i, j, res);
                ans += res.fi * res.se;
            }
        }
    }
    cout << ans << endl;
}

