using namespace std;

int main() {
  int64_t H, W;
  cin >> H >> W;
  vector<vector<bool>> grid;
  for (int64_t i = 0; i < H; ++i) {
    grid.emplace_back();
    for (int64_t j = 0; j < W; ++j) {
      char c;
      cin >> c;
      grid.back().emplace_back(c == '#');
    }
  }

  vector<pair<int64_t, int64_t>> directions{
    {0, 1},
    {0, -1},
    {1, 0},
    {-1, 0},
  };

  int64_t count = 0;
  vector<vector<bool>> seen(H, vector<bool>(W));
  for (int64_t h = 0; h < H; ++h) {
    for (int64_t w = 0; w < W; ++w) {
      if (!seen[h][w] && grid[h][w]) {
        seen[h][w] = true;
        deque<pair<int64_t, int64_t>> bfs;
        bfs.emplace_back(h, w);
        int64_t black = 1;
        int64_t white = 0;
        for (; !bfs.empty();) {
          auto&& cell = bfs.front();
          auto h = cell.first;
          auto w = cell.second;
          bool next = !grid[h][w];
          bfs.pop_front();
          for (auto&& dir : directions) {
            auto next_h = h + dir.first;
            auto next_w = w + dir.second;
            if (0 <= next_h && next_h < H && 0 <= next_w && next_w < W && !seen[next_h][next_w] && grid[next_h][next_w] == next) {
              bfs.emplace_back(next_h, next_w);
              seen[next_h][next_w] = true;
              if (next) ++black;
              else ++white;
            }
          }
        }
        count += black * white;
      }
    }
  }
  cout << count << endl;
}

