using namespace std;

int h, w, dp[400][400], cnt;
string s[400];
bool visited[400][400], visited2[400][400];
int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};
long long ans;

void move(int sy, int sx, bool isWhite) {
    visited[sy][sx] = true;
    if (isWhite) cnt++;
    rep(i, 4) {
        int ny = sy + dy[i], nx = sx + dx[i];
        if (ny < 0 || ny >= h || nx < 0 || nx >= w || visited[ny][nx]) continue;
        if ( isWhite && s[ny][nx] == '#') move(ny, nx, false);
        if (!isWhite && s[ny][nx] == '.') move(ny, nx, true);
    }
}

void put(int sy, int sx) {
    dp[sy][sx] = cnt;
    visited2[sy][sx] = true;
    rep(i, 4) {
        int ny = sy + dy[i], nx = sx + dx[i];
        if (ny < 0 || ny >= h || nx < 0 || nx >= w || visited2[ny][nx]) continue;
        put(ny, nx);
    }
}

int main() {
    cin >> h >> w;
    rep(i, h) cin >> s[i];
    REP(i, 0, h) {
        REP(j, 0, w) {
            if (s[i][j] == '#') {
                move(i, j, false);
                put(i, j);
                fill((bool*)visited,(bool*)(visited2+h),false);
                ans += cnt; cnt = 0;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

