void dfs(int x, int y, int areaID){
  if (area[x][y]) return;
  area[x][y] = areaID;
  fld[x][y]=='#'? bCnt[areaID-1]++: wCnt[areaID-1]++;
  if (x>0 && fld[x-1][y] != fld[x][y]) dfs(x-1, y, areaID);
  if (x<w-1 && fld[x+1][y] != fld[x][y]) dfs(x+1, y, areaID);
  if (y>0 && fld[x][y-1] != fld[x][y]) dfs(x, y-1, areaID);
  if (y<h-1 && fld[x][y+1] != fld[x][y]) dfs(x, y+1, areaID);
}

