ll bfs(int c,int i,int j){
  ll w=0,b=0;
  qpipi q;
  q.push(mp(c,(mp(i,j))));
  f[i][j]=false;
  while(!q.empty()){
    pipi p=q.front();q.pop();
    int cc=p.first,xx=p.second.first,yy=p.second.second;
    if(cc==1) w++;
    else b++;
    if(xx!=0){
      if(ss[xx-1][yy]!=cc&&f[xx-1][yy]){
	q.push(mp(-cc,mp(xx-1,yy)));
	f[xx-1][yy]=false;
      }
    }
    if(xx!=H-1){
      if(ss[xx+1][yy]!=cc&&f[xx+1][yy]){
	q.push(mp(-cc,mp(xx+1,yy)));
	f[xx+1][yy]=false;	
      }
    }
    if(yy!=0){
      if(ss[xx][yy-1]!=cc&&f[xx][yy-1]){
	q.push(mp(-cc,mp(xx,yy-1)));
	f[xx][yy-1]=false;	
      }
    }
    if(yy!=W-1){
      if(ss[xx][yy+1]!=cc&&f[xx][yy+1]){
	q.push(mp(-cc,mp(xx,yy+1)));
	f[xx][yy+1]=false;	
      }
    }
  }
  return w*b;
}
