const int MAX = 405;

int H, W;
bool grid[MAX][MAX], vis[MAX][MAX];

int dfs(int i, int j, bool color) {
	if (i < 0 or j < 0 or i >= H or j >= W or vis[i][j] or grid[i][j] != color) return 0;
	int ret = !grid[i][j] ? 1 : 0;
	vis[i][j] = true;

	ret += dfs(i + 1, j, !color);
	ret += dfs(i - 1, j, !color);
	ret += dfs(i, j + 1, !color);
	ret += dfs(i, j - 1, !color);

	return ret;
}

main() {
	ios_base::sync_with_stdio(0); cin.tie(nullptr);
	int i, j, k, l;

	cin >> H >> W;
	for (i = 0; i < H; ++i) {
