			grid[i][j] = input[j] == '#';
		}
	}

	int ans = 0;
	for (i = 0; i < H; ++i) for (j = 0; j < W; ++j) {
		if (!grid[i][j]) continue;
		for (k = 0; k < H; ++k) for (l = 0; l < W; ++l) {
			vis[k][l] = false;
		}
		int temp = dfs(i, j, grid[i][j]);
		//cout << i << ", " << j << " = " << temp << "\n";
		ans += temp;
	}
	cout << ans << "\n";
}

