using namespace std;


struct UF
{
    vector<long> par;
    vector<long> rank;

    UF(long n)
    {
        par.resize(n);
        rank.resize(n);
        long i;
        for(i=0; i<n; i++) {
            par[i]=i;  rank[i]=1;
        }
    }

    long find(long x)
    {
        if(x==par[x]) return x;
        return par[x] = find(par[x]);
    }

    void unite(long x, long y)
    {
        x=find(x);
        y=find(y);
        if(x==y) return;
        if(rank[x]<rank[y]) {
            par[x]=y;
        }
        else {
            par[y]=x;
            if(rank[x]==rank[y]) rank[x]++;
        }
    }

    bool same(long x, long y)
    {
        return find(x)==find(y);
    }
};


int main(int argc, char* argv[])
{
    long h, w;
    scanf("%ld%ld", &h, &w);

    char s[405][405]={0};

    long i, j;
    for(i=0; i<h; i++) {
        scanf("%s", s[i]);
    }

    UF  uf(h*w);

#define ID(i,j) ((i)*w+(j))
    for(i=0; i<h; i++) {
        for(j=0; j<w; j++) {
            if( j<w-1 && s[i][j] != s[i][j+1] ) {
                uf.unite( ID(i,j), ID(i,j+1) );
            }
            if( i<h-1 && s[i][j] != s[i+1][j] ) {
                uf.unite( ID(i,j), ID(i+1,j) );
            }
        }
    }

    map<long, pair<long,long> > mm;

    for(i=0; i<h; i++) {
        for(j=0; j<w; j++) {
            if(s[i][j]=='#') {
                mm[uf.find(ID(i,j))].first ++;
            }
            else {
                mm[uf.find(ID(i,j))].second ++;
            }            
        }
    }

    ll sum=0;
    auto it=mm.begin();
    for(; it!=mm.end(); ++it) {
        sum += (it->second.first) * (it->second.second);
    }
    printf("%lld\n", sum);

    return 0;
}

