#include <bits/stdc++.h>
using namespace std;

using ll = int64_t;
constexpr ll mod = ll(1e9 + 7);

 class UnionFind {
  public:
   vector<int> parent, size;
   vector<int> n_white, n_black;

   UnionFind(int n) {
     parent.resize(n);
     n_black.resize(n);
     n_white.resize(n);
     iota(parent.begin(), parent.end(), 0);
     size.resize(n, 1);
   }  

   int Find(int x) {
     return x == parent[x] ? x : parent[x] = Find(parent[x]);
   }
   bool Merge(int x, int y) {
     int px = Find(x), py = Find(y);
     if (px == py) return false;
     if (size[px] < size[py]) swap(px, py);
     parent[py] = px;
     size[px] += size[py];
     n_black[px] += n_black[py];
     n_white[px] += n_white[py];
     return true;
   }
 };

int main () {
  ios::sync_with_stdio(0); cin.tie(0);

  ll h,w;
  cin >> h >> w;
  vector<string> M(h);
  for (auto& aa : M) cin >> aa;
  UnionFind uf(h*w);
  for (int y = 0; y < h; ++y) {
    for (int x = 0; x < w; ++x) {
      if (M[y][x] == '#') {
        ++uf.n_black[y*w+x];
      } else {
        ++uf.n_white[y*w+x];
      }
    }
  }

  for (int y = 0; y < h; ++y) {
    for (int x = 0; x < w; ++x) {
      for (int dy = -1; dy <= 1; ++dy) {
        for (int dx = -1; dx <= 1; ++dx) {
          if (abs(dy) + abs(dx) != 1) continue;
          if (y+dy < h && y+dy >= 0 && x+dx < w && x+dx >= 0 && M[y+dy][x+dx] != M[y][x]) {
            uf.Merge(y*w+x, (y+dy)*w + x+dx);
          }
        }
      }
    }
  }
  vector<bool> seen(h*w);
  ll ans = 0;
  for (int y = 0; y < h; ++y) {
    for (int x = 0; x < w; ++x) {
      int p = uf.Find(y*w+x);
      if (!seen[p]) {
        ans += uf.n_black[p] * uf.n_white[p];
        seen[p] = true;
      }
    }
  }
  cout << ans << endl;

}

