int main(){
    int h, w;
    cin >> h >> w;
    vector<string> s(h);
    rep(i,h) cin >> s[i];

    vector<vector<bool>> visited(h, vector<bool>(w));
    int ans = 0;
    rep(i,h) rep(j,w){
        if (visited[i][j]) continue;
        if (s[i][j] == '.') continue;
        queue<P> q;
        q.push(P(j, i));
        visited[i][j] = true;
        int cnt = 1, b = 1;
        while(!q.empty()){
            P p = q.front(); q.pop();
