                    if (s[y][x] == '#'){
                        q.push(P(x, y));
                        visited[y][x] = true;
                        cnt++;
                        b++;
                    }
                }else{
                    if (s[y][x] == '.'){
                        q.push(P(x, y));
                        visited[y][x] = true;
                        cnt++;
                    }
                }
            }
        }
        ans += b * (cnt - b);
    }
    cout << ans << endl;
    return 0;
}

