inline void init(vector<int>& uf) {
    iota(all(uf), 0);
}

int root(vector<int>& uf, int x) {
    if (uf[x] == x) {
        return x;
    } else {
        return uf[x] = root(uf, uf[x]);
    }
}
bool same(vector<int>& uf, int x, int y) {
    return root(uf, x) == root(uf, y);
}
void unite(vector<int>& uf, int x, int y)
{
    x = root(uf, x);
    y = root(uf, y);
    if (x == y) return;
    uf[x] = y;
}


int main()
{
    int H, W; cin >>H>>W;
    vs grid(H); cin >> grid;

    vector<int> uf(H*W);
    init(uf);

    rep(i, H) {
        rep(j, W) {
            if (j != W-1) {
                if (grid[i][j] != grid[i][j+1])
                    unite(uf, W*i+j, W*i+j+1);
            }
            if (i != H-1) {
                if (grid[i][j] != grid[i+1][j])
                    unite(uf, W*i+j, W*(i+1)+j);
            }
        }
    }

    unordered_map<int, pii> m;
    rep(i, H) {
        rep(j, W) {
            int r = root(uf, W*i+j);
            pii& p = m[r];
