#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const int N=4e2+10;
char a[N][N];
ll h,w,vis[N*N],Cnt[N*N],Dot[N*N],pre[N*N];
int dir[4][2]={
       {-1,0},
    {0,-1},{0,1},
        {1,0}
};
int Hash(int x,int y){
    return (x-1)*w+y;
}
int Find(int x){
    return x==pre[x]?x:Find(pre[x]);
}
void Merge(int x,int y){
    int fx=Find(x);
    int fy=Find(y);
    if(fx!=fy){
        pre[fy]=fx;
        Cnt[fx]+=Cnt[fy];
        Dot[fx]+=Dot[fy];
    }
}
bool check(int x,int y){
    return (x<1||y<1||x>h||y>w)?false:true;
}
int main()
{

    scanf("%lld%lld",&h,&w);
    for(int i=1;i<=h*w+10;i++){
        pre[i]=i;
    }
    for(int i=1;i<=h;i++){
        scanf("%s",a[i]+1);
    }
    for(int i=1;i<=h;i++){
        for(int j=1;j<=w;j++){
            Cnt[Hash(i,j)]++;
            if(a[i][j]=='.'){
                Dot[Hash(i,j)]++;
            }
        }
    }
    for(int i=1;i<=h;i++){
        for(int j=1;j<=w;j++){
            for(int k=0;k<4;k++){
                int tx=i+dir[k][0];
                int ty=j+dir[k][1];
                if(check(tx,ty)&&a[i][j]!=a[tx][ty]){
                    int Fx=Hash(i,j);
                    int Fy=Hash(tx,ty);
                    Merge(Fx,Fy);
                }
            }
        }
    }
    ll ans=0;
    for(int i=1;i<=h;i++){
        for(int j=1;j<=w;j++){
            int t=Hash(i,j);
            int Father=Find(t);
            if(!vis[Father]){
                ans=ans+(Cnt[Father]-Dot[Father])*Dot[Father];
                vis[Father]=1;
            }
        }
    }
    printf("%lld\n",ans);
    return 0;
}

