				if(a[cnt-m]!=ch)
				{
					v[cnt].push_back(cnt-m);
					v[cnt-m].push_back(cnt);
				}
			}
			cnt++;
		}
	}
	for(int i=1;i<=n*m;i++)
	{
		if(!vis[i])
		{
			x=y=0;
			dfs(i);
