class UnionFind {
    struct UFNode {
        int par;
        int rank;
        int blackSum;
        int whiteSum;
    };
    vector<UFNode> nodes;
public:
    UnionFind(int n): nodes(n) {
        for (int i = 0; i < n; i++) {
            nodes[i].par = i;
            nodes[i].rank = 0;
            nodes[i].blackSum = 0;
            nodes[i].whiteSum = 0;
        }
    };
    LL getSum(int x) const {
        return (LL)nodes[x].whiteSum * nodes[x].blackSum;
    }
    LL setSum(int x, bool isBlack) {
        if (isBlack) nodes[x].blackSum += 1;
        else nodes[x].whiteSum += 1;
    }
    int root(int x) {
        return nodes[x].par == x ? x : root(nodes[x].par);
    }
    bool same(int x, int y) {
        return root(x) == root(y);
    }
    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (nodes[x].rank < nodes[y].rank) {
            nodes[x].par = y;
            nodes[y].blackSum += nodes[x].blackSum;
            nodes[y].whiteSum += nodes[x].whiteSum;
        } else {
            nodes[y].par = x;
            nodes[x].blackSum += nodes[y].blackSum;
            nodes[x].whiteSum += nodes[y].whiteSum;
            if (nodes[x].rank == nodes[y].rank) nodes[x].rank++;
        }
    }
    //~UnionFind() {cout << nodes.size() << endl;}
};

void solve() {
    int h,w;
    cin >> h >> w;
    VS s(h);
    REP(i,0,h) cin >> s[i];
    UnionFind uf(h*w);
    REP(i,0,h) REP(j,0,w) {
        if (s[i][j] == '#') uf.setSum(i*h+j, true);
        else uf.setSum(i*h+j, false);
    }
    REP(i,0,h-1) REP(j,0,w) {
        if (s[i][j] != s[i+1][j]) uf.unite(i*h+j, (i+1)*h+j);
