/* #region UnionFind */

struct UnionFind {
    ll _groupcount; // グループ数
    vc<ll> parent;  // 各要素の直接の親リスト，親がいないときは自分自身を指す
    vc<ll> gsize; // 各要素が根である場合，その要素が属するグループの要素数 (root 要素のみ有効な値を持つ)

    // コンストラクタ
    UnionFind() {}
    // コンストラクタ，要素数 n の UnionFind 木を構築する
    UnionFind(ll n) : _groupcount(n), parent(n), gsize(n, 1) { iota(ALL(parent), 0LL); }

    // x の属する部分木の根要素を返す
    ll find(ll x) { return x == parent[x] ? x : parent[x] = find(parent[x]); }

    // x と y が同じグループかどうか判定する
    bool same(ll x, ll y) { return find(x) == find(y); }

    // x と y を同じグループにする
    void unite(ll x, ll y) {
        ll rx = find(x); // x の属するグループの根
        ll ry = find(y); // y の属するグループの根
        if (rx == ry)    // unite 済
            return;
        // assert(x != y)
        if (gsize[rx] < gsize[ry]) swap(rx, ry);
        // assert(gsize[x] > gsize[y]); // x 側の木の方が大きい

        gsize[rx] += gsize[ry]; // x を根とする1つのグループに統合
        parent[ry] = rx;        // ry 以下の木を rx 配下に接続する
        _groupcount--;
    }

    // x が属するグループの要素数を返す
    ll size(ll x) { return gsize[find(x)]; }

    // 全体のグループ数を返す
    ll count() const { return _groupcount; }
};

/* #endregion */

/* #region UnionFindWithGroupVal */

template <typename T> struct UnionFindWithGroupVal {
    using F = function<T(T, T)>; // 要素と要素をマージする関数．max とか．

    ll _groupcount; // グループ数
    vc<ll> parent;  // 各要素の直接の親リスト，親がいないときは自分自身を指す
    vc<ll> gsize; // 各要素が根である場合，その要素が属するグループの要素数 (root 要素のみ有効な値を持つ)
    vc<T> groupval;
    F f;

    // コンストラクタ
    UnionFindWithGroupVal() {}
    // コンストラクタ，要素数 n の UnionFind 木を構築する
    UnionFindWithGroupVal(ll n, F f, T ti) : _groupcount(n), parent(n), gsize(n, 1), groupval(n, ti), f(f) {
        iota(ALL(parent), 0LL);
    }

    // x の属する部分木の根要素を返す
    ll find(ll x) {
        if (x == parent[x]) return x;
        return parent[x] = find(parent[x]); // 経路圧縮
    }

    // x と y が同じグループかどうか判定する
    bool same(ll x, ll y) { return find(x) == find(y); }

    // x と y を同じグループにする
    void unite(ll x, ll y) {
        ll rx = find(x); // x の属するグループの根
        ll ry = find(y); // y の属するグループの根
        if (rx == ry)    // unite 済
            return;
        // assert(x != y)
        if (gsize[rx] < gsize[ry]) swap(rx, ry);
        // assert(gsize[x] > gsize[y]); // x 側の木の方が大きい

        gsize[rx] += gsize[ry]; // x を根とする1つのグループに統合
        parent[ry] = rx;        // ry 以下の木を rx 配下に接続する
        groupval[rx] = f(groupval[rx], groupval[ry]);
        _groupcount--;
    }

    // x が属するグループの要素数を返す
    ll size(ll x) { return gsize[find(x)]; }

    // 全体のグループ数を返す
    ll count() const { return _groupcount; }

    void update(ll idx, T val) {
        ll par = find(idx);
        groupval[par] = f(groupval[par], val);
    }

    T query(ll idx) { return groupval[find(idx)]; }
};

/* #endregion */

// Problem
void solve() {
    ll h, w;
    cin >> h >> w;
    vc<string> s(h);
    cin >> s;

    const auto idx = [&](ll row, ll col) -> ll { return w * row + col; };
    const auto canMove = [&](ll row_form, ll col_from, ll row_to, ll col_to) -> bool {
        return s[row_form][col_from] != s[row_to][col_to];
    };
    auto merge = [](ll a, ll b) -> ll { return a + b; };
    UnionFindWithGroupVal<ll> uf(h * w, merge, 0);
    REP(row, 0, h) REP(col, 0, w) {
        ll i = idx(row, col); //
        if (row != h - 1 && canMove(row, col, row + 1, col)) uf.unite(i, idx(row + 1, col));
        if (col != w - 1 && canMove(row, col, row, col + 1)) uf.unite(i, idx(row, col + 1));
        if (s[row][col] == '#') uf.update(i, 1);
    }

    set<ll> used;
    ll ret = 0;
    REP(i, 0, h * w) {
        ll par = uf.find(i);
        // dump(i, par, used, ret);
        if (used.find(par) != used.end()) continue; // このグループはもう数えた
        ll cnt = uf.size(par);
        ll cnt_black = uf.query(par);
        // if (cnt > 1) ret += cnt * (cnt - 1) / 2;
        if (cnt > 1) ret += cnt_black * (cnt - cnt_black);
        used.insert(par);
    }
    cout << ret << endl;
}

