const ll MOD = 1000000007; // 10^9 + 7
const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};

void solve() {
  ll h, w; cin >> h >> w;
  vector<string> grid(h); rep(i, h) cin >> grid[i];
  const ll MAX = 400;
  bool visited[MAX][MAX] = {{}};
  ll ans = 0;
  rep(i, h)rep(j, w) {
    if (visited[i][j]) continue;
    ll cntw = 0, cnth = 0;

    visited[i][j] = true;
    queue<ll> qx, qy;
    qx.push(j); qy.push(i);
    while (!qx.empty()) {
      ll x = qx.front(); qx.pop();
      ll y = qy.front(); qy.pop();

      if (grid[y][x] == '.') cntw++;
      else cnth++;

      rep(k, 4) {
        ll nx = x + dx[k];
        ll ny = y + dy[k];
        if (nx >= 0 && nx < w && ny >= 0 && ny < h && grid[y][x] != grid[ny][nx] && !visited[ny][nx]) {
          visited[ny][nx] = true;
          qx.push(nx);
          qy.push(ny);
        }
      }
    }

    ans += cntw * cnth;
  }
  outl(ans);
}

