void dfs(const int ch, const int cw, const bool ctf) {
  used[ch][cw]  = true;
  if(ctf) cnt1++; else cnt2++;
  bool ntf = (! ctf);
  const int dh[4] = {-1, 0, 1, 0};
  const int dw[4] = {0, -1, 0, 1};
