int bw[401][401][2];
int fin(int x){
    if(par[x/w][x%w]==x){
        return x;
    }else{
        return par[x/w][x%w] = fin(par[x/w][x%w]);
    }
}
void unite(int x, int y){
    x=fin(x);
    y=fin(y);
    if(x==y) return;

    if(ran[x/w][x%w]<ran[y/w][y%w]){
        par[x/w][x%w]=y;
    }else{
        par[y/w][y%w]=x;
        if(ran[x/w][x%w]==ran[y/w][y%w]) ran[x/w][x%w]++;
    }
}

