                if(j>0&&ma[i][j-1]==1-ma[i][j]){
                    unite(i*w+j-1,(i-1)*w+j);
                    unite(i*w+j-1,i*w+j);
                }else{
                     unite(i*w+j,(i-1)*w+j);
                }
            }else if(j>0&&ma[i][j-1]==1-ma[i][j]){
                unite(i*w+j,i*w+j-1);
            }
        }
