#define onBoardX(n) (0<=(n) && (n)<w)
#define onBoardY(n) (0<=(n) && (n)<h)
vector<vector<int>> v;
vector<vector<bool>> visited,done;
int h,w;
pair<int,int> col;

void dfs(int y,int x){
  bool isw=false;
  if(v[y][x])col.first++;
  else col.second++;
  for(int d=-1;d<=1;d+=2){
    if(onBoardX(x+d)&&!done[y][x+d]&&!visited[y][x+d]&&v[y][x+d]!=v[y][x]){
      done[y][x+d]=visited[y][x+d]=isw=true;
      dfs(y,x+d);
    }
    if(onBoardY(y+d)&&!done[y+d][x]&&!visited[y+d][x]&&v[y+d][x]!=v[y][x]){
      done[y+d][x]=visited[y+d][x]=isw=true;
      dfs(y+d,x);
    } 
  }
  if(!isw&&v[y][x])col.first--;
}

int main(){
  int res=0;
  cin>>h>>w;
  v.resize(h); visited.resize(h); done.resize(h);
  for(int i=0;i<h;++i){
    v[i].resize(w); visited[i].resize(w); done[i].resize(w);
    for(int j=0;j<w;++j)v[i][j]=visited[i][j]=done[i][j]=0;
  }
  for(int i=0;i<h;++i){
    string s;
    cin>>s;
    for(int j=0;j<w;++j)if(s[j]=='#')v[i][j]=1;
  }
  for(int i=0;i<h;++i)for(int j=0;j<w;++j){
    if(!done[i][j]&&v[i][j]==1){
      done[i][j]=true;
      col=make_pair(0,0);
      dfs(i,j);
      res+=col.first*col.second;
      cerr<<"col:("<<col.first<<","<<col.second<<")\n";
    }
  }
  cout<<res;
  return 0;
}

