int main() {
    ll h, w;
    cin >> h >> w;

    vvl board(h, vl(w));
    rep(i, h) {
        string s;
        cin >> s;
        rep(j, w) {
            if(s[j] == '#') {
                board[i][j] = 1;
            }
        }
    }

    queue<pair<ll, ll>> next;
    vvl visited(h, vl(w));

    ll ans = 0;
    rep(i, h) {
        rep(j, w) {
            if(visited[i][j]) {
                continue;
            }
            next.push(make_pair(i, j));  
            visited[i][j] = 1;
            ll cntBlack = 0, cntWhite = 0;
            while(!next.empty()) {
                ll x = next.front().first;
                ll y = next.front().second;
                if(board[x][y]) {
                    cntBlack++;
                }
                else {
                    cntWhite++;
                }
                rep(k, 4) {
                    ll nx = x + dx[k];
                    ll ny = y + dy[k];
                    if(nx < 0 || h <= nx || ny < 0 || w <= ny) {   
                        continue;
                    }
                    if(visited[nx][ny] || board[x][y] == board[nx][ny]) {
                        continue;
                    }
                    next.push(make_pair(nx, ny));
                    visited[nx][ny] = 1;
                }
                next.pop();
            }
            ans += cntBlack*cntWhite;
        }
    }

    out(ans);
    re0;
}

