using namespace std;

const int dx[] = { -1, 0, +1, 0 };
const int dy[] = { 0, -1, 0, +1 };

void dfs(const vector<string> &S, int H, int W, int i, int j, vector<vector<bool>> &visited, int &black, int &white)
{
	if (visited[i][j]) {
		return;
	}
	visited[i][j] = true;

	if (S[i][j] == '#') ++black;
	if (S[i][j] == '.') ++white;

	for (int k = 0; k < 4; ++k) {
		int y = i + dy[k];
		int x = j + dx[k];
		if (y < 0 || H <= y || x < 0 || W <= x) {
			continue;
		}
		if ((S[i][j] == '#' && S[y][x] == '.') || (S[i][j] == '.' && S[y][x] == '#')) {
			dfs(S, H, W, y, x, visited, black, white);
		}
	}
}

int main()
{
	int H, W;
	cin >> H >> W;

	vector<string> S(H);
	for (auto &x : S) {
		cin >> x;
	}
	vector<vector<bool>> visited(H, vector<bool>(W, false));
	int ans = 0;
	for (int i = 0; i < H; ++i) {
		for (int j = 0; j < W; ++j) {
			if (S[i][j] == '#') {
				int black = 0;
				int white = 0;
				dfs(S, H, W, i, j, visited, black, white);
				ans += black * white;
			}
		}
	}

	cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int H, W;
vector<int> dx = {1, 0, -1, 0};
vector<int> dy = {0, 1, 0, -1};

bool inside(int x, int y) {
  return (x >= 0 && y >= 0 && x < H && y < W);
}
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  cin >> H >> W;
  vector<vector<ll>> cells(H, vector<ll>(W, 0));
  for (int i = 0; i < H; i++) {
    string S; cin >> S;
    for (int j = 0; j < W; j++) {
      if (S[j] == '#') cells[i][j] = 1;
    }
  }

  ll ans = 0;
  vector<vector<bool>> used(H, vector<bool>(W, false));
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      if (used[i][j]) continue;
      used[i][j] = true;

      set<pair<int, int>> b, w;
      if (cells[i][j] == 1) b.insert(make_pair(i, j));
      else w.insert(make_pair(i, j));

      queue<pair<int, int>> q;
      q.push(make_pair(i, j));

      while (!q.empty()) {
        pair<int, int> p = q.front();
        q.pop();
        int px = p.first, py = p.second;
        if (cells[px][py] == 1) b.insert(p);
        else w.insert(p);

        for (int k = 0; k < 4; k++) {
          int nx = px + dx[k];
          int ny = py + dy[k];
          if (inside(nx, ny) && !used[nx][ny] && cells[px][py] != cells[nx][ny]) {
            used[nx][ny] = true;

            pair<int, int> n = make_pair(nx, ny);
            if (cells[nx][ny] == 1) b.insert(n);
            else w.insert(n);
            q.push(n);
          }
        }
      }
      ans += b.size() * w.size();
    }
  }

  cout << ans << '\n';
  return 0;
}

