const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};

vector<string> grid;
int H,W;

struct UnionFind {
    vector<int> par,rank,large,wsize;

    void init(int N){
        rank.assign(N,0);
        large.assign(N,1);
        par.resize(N);
        wsize.resize(N);
        for(int i= 0; i < N; i++){
            par[i]=i;
            if(grid[i/W][i%W]=='.') wsize[i]=1;
            else wsize[i]=0;
        }
    }

    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        if(rank[rx]<rank[ry]) {
            par[rx]=ry;
            large[ry]+=large[rx];
            large[rx]=0;
            wsize[ry]+=wsize[rx];
            wsize[rx]=0;
        }
        else {
            par[ry]=rx;
            large[rx]+=large[ry];
            large[ry]=0;
            wsize[rx]+=wsize[ry];
            wsize[ry]=0;
            if(rank[rx]==rank[ry])rank[x]++;
        }
    }

    bool same(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }

    int size(int x) {
        return large[root(x)];
    }
};

