class UnionFind{
  private:
    vector<int> Parent;
  public:
    vector<ll> White;
    vector<ll> Black;

    UnionFind(int N){
      Parent = vector<int>(N,-1);
      White = vector<ll>(N,0);
      Black = vector<ll>(N,0);
    }

    int find(int x){
      if(Parent[x] < 0) return x;
      return Parent[x] = find(Parent[x]);
    }

    int size(int x){
      return -Parent[find(x)];
    }

    bool unite(int x, int y){
      x = find(x);
      y = find(y);
      if(x==y) return false;

      if(size(x)<size(y))swap(x,y);
      Parent[x] += Parent[y];
      White[x] += White[y];
      Black[x] += Black[y];
      Parent[y] = x;
      White[y] = 0;
      Black[y] = 0;
      return true;
    }

    bool same(int x, int y){
      return find(x) == find(y);
    }
};

