pii steps[4] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};


bool may(int i, int j)
{
    return i >= 0 && i < n && j >= 0 && j < m && !used[i][j];
}


pii dfs(int i, int j)
{
    pii cur = {0, 0};
    used[i][j] = 1;

    if (maps[i][j] == '#')
        cur.first++;
    else
        cur.second++;

    for (auto p : steps)
    {
        if (may(i + p.first, j + p.second) && maps[i][j] != maps[i + p.first][j + p.second])
        {
            pii ncur = dfs(i + p.first, j + p.second);
            cur.first += ncur.first;
            cur.second += ncur.second;
        }
    }

    return cur;
}


