void dfs(int y, int x, int &H, int &W, vector<string> &S)
{
  seen[y][x] = true;
  if (S[y][x] == '#')
    numb++;
  else
    numw++;

  for (int i = 0; i < 4; i++)
  {
    int ny = y + dy[i];
