    if (s[y][x] == '#') res.first ++;
    else res.second ++;
    int yc[] = {0,0,-1,1};
    int xc[] = {-1,1,0,0};
    rep(i,4) {
        int ny = y + yc[i];
        int nx = x + xc[i];
        if (0 <= ny and ny < h and 0 <= nx and nx < w) {
            if (s[y][x] != s[ny][nx]) {
                auto t = dfs(ny,nx);
                res.first += t.first;
                res.second += t.second;
            }
        }
    }
    return res;
}

int main() {
    cin >> h >> w;
    rep(i,h) cin >> s[i];
    int ans = 0;
    rep(y,h) {
        rep(x,w) {
            if (not visited[y][x]) {
                auto p = dfs(y,x);
                ans += p.first * p.second;
            }
        }
    }
    cout << ans << endl;
}

