void solve(int sx, int sy)
{
	u[sx][sy] = 1;
	queue<pii> Q;
	Q.emplace(sx, sy);
	ll ans1 = 0;
	ll ans2 = 0;
	while (!Q.empty())
	{
		int x = Q.front().X;
