struct UnionFind {
    UnionFind() : m_parents(0), m_rank(0) {}
    UnionFind(size_t N) : m_parents(N), m_rank(N) {
        REP (i, N) {
            m_parents[i] = i;
            m_rank[i] = 0;
        }
    }

    size_t size() const {
        return this->m_rank.size();
    }

    void merge(size_t t1, size_t t2) {
        auto p1 = this->parent(t1);
        auto p2 = this->parent(t2);

        if (p1 == p2) {
            return ;
        }

        if (this->m_rank[p1] < this->m_rank[p2]) {
            this->m_parents[p1] = p2;
        } else {
            this->m_parents[p2] = p1;
            if (this->m_rank[p1] == this->m_rank[p2]) {
                this->m_rank[p1] += 1;
            }
        }
    }
    bool is_same(size_t t1, size_t t2) const {
        return this->parent(t1) == this->parent(t2);
    }

    size_t parent(size_t t) const {
        auto p = this->m_parents[t];
        if (p == t) {
            return t;
        } else {
            auto p2 = this->parent(p);
            this->m_parents[t] = p2;
            return p2;
        }
    }
private:
    mutable vector<size_t> m_parents;
    vector<u64> m_rank;

};

namespace internal {
    template <>
    struct oneline<UnionFind> {
        std::string operator()(const UnionFind &t) const {
            OrderedMap<size_t, OrderedSet<size_t>> xs;
            REP (i, t.size()) {
                xs[t.parent(i)].insert(i);
            }
            return oneline<decltype(xs)>()(xs);
        }
    };
}


void body() {
    auto H = read<i64>();
    auto W = read<i64>();
    auto Ss = read<string>(H);

    auto to_index = [W](pair<i64, i64> p) {
        return p.first * W + p.second;
    };
    auto to_point = [W](auto i) -> pair<i64, i64> {
        return make_pair(i / W, i % W);
    };

    UnionFind uf(H * W);
    REP (i, H) {
        REP (j, W) {
            if (i != 0) {
                if (Ss[i - 1][j] != Ss[i][j]) {
                    uf.merge(to_index({i - 1, j}), to_index({i, j}));
                }
            }
            if (i != H - 1) {
                if (Ss[i + 1][j] != Ss[i][j]) {
                    uf.merge(to_index({i + 1, j}), to_index({i, j}));
                }
            }
            if (j != 0) {
                if (Ss[i][j - 1] != Ss[i][j]) {
                    uf.merge(to_index({i, j - 1}), to_index({i, j}));
                }
            }
            if (j != W - 1) {
                if (Ss[i][j + 1] != Ss[i][j]) {
                    uf.merge(to_index({i, j + 1}), to_index({i, j}));
                }
            }
        }
    }

    OrderedMap<size_t, pair<i64, i64>> groups;
    REP (index, H * W) {
        auto parent = uf.parent(index);
        auto p = to_point(index);

        if (Ss[p.first][p.second] == '#') {
            groups[parent].first += 1;
        } else {
            groups[parent].second += 1;
        }
    }

    i64 ans = 0;
    EACH (group, groups) {
        ans += group.second.first * group.second.second;
    }

    cout << ans << endl;
}

