void dfs(ll &h, ll &i, ll H, ll W, int y, int x, vector<vector<char>> map, vector<vector<bool>> &ald){
    if(y<0||y>=H||x<0||x>=W){return;}
    if(ald[y][x] == true){return;}
    ald[y][x] = true;
    bool p = col(map[y][x]);
    if(p == true){h++;}
    else{i++;}
    if(y != 0){
    if(col(map[y-1][x]) != p){dfs(h,i, H, W, y-1, x, map, ald);}
    }
    if(x != 0){
    if(col(map[y][x-1]) != p){dfs(h,i, H, W, y, x-1, map, ald);}
    }
    if(y != H-1){
    if(col(map[y+1][x]) != p){dfs(h,i, H, W, y+1, x, map, ald);}
    }
    if(x != W-1){
    if(col(map[y][x+1]) != p){dfs(h, i, H, W, y, x+1, map, ald);}
    }
}

