void bfs(vector<string> &S,vector<vector<bool>> &visited,int y,int x){
  long long cnt_b=1;
  long long cnt_w=0;

  visited.at(y).at(x)=true;
  queue<pair<int,int>> que_yx;
  que_yx.push(make_pair(y,x));
  while(!que_yx.empty()){
    int y=que_yx.front().first;
    int x=que_yx.front().second;
    que_yx.pop();
    for(int i=0;i<4;i++){
      int ny=y+move_y.at(i);
      int nx=x+move_x.at(i);
      if(ny<0 || ny>=H || nx<0 || nx>=W)  continue;
      if(visited.at(ny).at(nx)) continue;
      if(S.at(ny).at(nx)==S.at(y).at(x))  continue;
      visited.at(ny).at(nx)=true;
      que_yx.push(make_pair(ny,nx));
      if(S.at(ny).at(nx)=='#')  cnt_b++;
      else  cnt_w++;
    }
  }
  ans+=cnt_b*cnt_w;
}

