struct Edge{pll from, to;};

void solve() {
    ll H,W;
    cin >> H >> W;
    vector<vll> mp, vis(H);
    mp.resize(H);
    REP(i, H) {
        str S;
        cin >> S;
        mp[i].resize(W);
        vis[i].resize(W);
        REP(j, W) {
            mp[i][j] = S[j] == '#' ? 1 : 0;
            vis[i][j] = -1;
        }
    }

    vector<vector<Edge> > path(H*W);
    vll dx = {-1, 0, 1, 0};
    vll dy = {0, -1, 0, 1};
    REP(y, H) {
        REP(x, W) {
            REP(i, 4) {
                if(x+dx[i]>=0&&x+dx[i]<W&&y+dy[i]>=0&&y+dy[i]<H) {
                    ll nx = x+dx[i];
                    ll ny = y+dy[i];
                    if(mp[y][x] != mp[ny][nx]){
                        path[x+y*W].push_back({{x, y}, {nx, ny}});
                        path[nx+ny*W].push_back({{nx, ny}, {x, y}});
                    }
                }
            }
        }
    }
    ll ans = 0;
    REP(y, H) {
        REP(x, W) {
            if(vis[y][x] != -1) continue;
            queue<ll> q;
            vll nwb(2);
            q.push(y*W+x);
            vis[y][x] = 0;
            nwb[mp[y][x]]++;
            while(!q.empty()) {
                ll f = q.front();
                ll px = f % W;
                ll py = f / W;
                q.pop();
                auto routes = path[py*W+px];
                for(auto &e:routes) {
                    ll nx = e.to.first;
                    ll ny = e.to.second;
                    if(vis[ny][nx] == -1) {
                        vis[ny][nx] = 0;
                        nwb[mp[ny][nx]]++;
                        q.push(ny*W+nx);
                    }
                }
            }
            ans += nwb[0] * nwb[1];
        }
    }
    out(ans);
}

int main() {
    fast_io;
    solve();
    return 0;
}

