vector<pair<int, int>> move_list = { make_pair(0, 1), make_pair(1, 0), make_pair(0, -1), make_pair(-1, 0) };

ll bfs(vector<vector<char>>& field, vector<vector<bool>>& already, int s_r, int s_c, int H, int W) {
    queue<pair<int, int>> q;
    q.push(make_pair(s_r, s_c));
    already[s_r][s_c] = true;
    int black_count = 0;
    int white_count = 0;

    while (1) {
        if (q.size() <= 0) {
            break;
        }
        auto nd = q.front();
        q.pop();
        if (field[nd.first][nd.second] == '.') white_count++;
        else black_count++;
        for (auto& m : move_list) {
            auto n_r = nd.first + m.first;
            auto n_c = nd.second + m.second;
            if (n_r >= 0 && n_c >= 0 && n_r < H && n_c < W) {
                if ((field[nd.first][nd.second] == '.' && field[n_r][n_c] == '#') ||
                    (field[nd.first][nd.second] == '#' && field[n_r][n_c] == '.')) {
                    if (already[n_r][n_c] == false) {
                        already[n_r][n_c] = true;
                        q.push(make_pair(n_r, n_c));
                    }
                }
            }
        }
    }
    return black_count * white_count;
}


