struct UnionFind {
    vector<int> data;
    int sz;
    UnionFind(int sz) : data(sz, -1), sz(sz) { }
    bool unionSet(int x, int y) {
        if ((x = root(x)) == (y = root(y))) return false;
        if (data[x] > data[y]) swap(x, y);
        data[x] += data[y]; data[y] = x; sz--;
        return true;
    }
    bool findSet(int x, int y) { return root(x) == root(y); }
    int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
    int size(int x) { return -data[root(x)]; }
    int size() { return sz; }
};

int main() {
    int h, w; cin >> h >> w;
    vector<string> field(h);
    for (string &s: field) cin >> s;
    UnionFind uf(h * w);
    auto idx = [&](int i, int j) { return i * w + j; };
    for (int i = 0; i < h; i++) for (int j = 0; j < w; j++) {
        for (int di: {-1, 0, 1}) for (int dj: {-1, 0, 1}) {
            if (di * di + dj * dj != 1) continue;
            int ni = i + di, nj = j + dj;
            if (ni < 0 || ni >= h || nj < 0 || nj >= w) continue;
            if (field[i][j] != field[ni][nj]) uf.unionSet(idx(i, j), idx(ni, nj));
        }
    }
    vector<vector<int>> cnt(h * w, vector<int>(2, 0));
    for (int i = 0; i < h; i++) for (int j = 0; j < w; j++) {
        cnt[uf.root(idx(i, j))][field[i][j] == '.']++;
    }
    long long ans = 0;
    for (auto &v: cnt) ans += 1LL * v[0] * v[1];
    cout << ans << endl;
    return 0;
}

