const int MAXHW = 405;

int H, W;
string S[MAXHW];

template <const int MAXV> struct ConnectedComponentsUF {
    int UF[MAXV], id[MAXV]; vector<vector<int>> components;
    void init(int N) { fill(UF, UF + N, -1); }
    int find(int v) { return UF[v] < 0 ? v : UF[v] = find(UF[v]); }
    bool addEdge(int v, int w) {
        if ((v = find(v)) == (w = find(w))) return false;
        if (UF[v] > UF[w]) swap(v, w);
        UF[v] += UF[w]; UF[w] = v;
        return true;
    }
    bool connected(int v, int w) { return find(v) == find(w); }
    int getSize(int v) { return -UF[find(v)]; }
    void assign(int V) { // assigns ids to each component
        fill(id, id + V, -1); int cnt = 0;
        for (int v = 0; v < V; v++) if (find(v) == v) { id[v] = cnt++; components.emplace_back(2, 0); }
        for (int v = 0; v < V; v++) components[id[v] = id[find(v)]][S[v / W][v % W] == '#']++;
    }
    void clear() { components.clear(); }
};

ConnectedComponentsUF<MAXHW * MAXHW> UF; 

int main() {
    // setInput("in.txt");
    // setOutput("out.txt");
    // setError("err.txt");
    setLength(MAXHW);
    read(H, W);
    UF.init(H * W);
    FOR(i, H) read(S[i]);
    FOR(i, H) FOR(j, W) {
        if (i + 1 < H && ((S[i][j] == '#') ^ (S[i + 1][j] == '#'))) UF.addEdge(i * W + j, (i + 1) * W + j);
        if (j + 1 < W && ((S[i][j] == '#') ^ (S[i][j + 1] == '#'))) UF.addEdge(i * W + j, i * W + j + 1);
    }
    UF.assign(H * W);
    ll ans = 0;
    FORE(comp, UF.components) ans += ll(comp[0]) * ll(comp[1]);
    writeln(ans);
    return 0;
}

