		s[0][j] = -1;
		s[h+1][j] = -1;
	}

	bool flag = true;
	queue<ll> quex;
	queue<ll> quey;
	ll x, y;
	ll r = 0;
	ll countw = 0;
	ll countb = 0;
	while(flag){
		if(quex.empty()){
			r += countw*countb;
			countw = 0;
			countb = 0;
			bool nopush = true;
			for(ll i = 1; i <= h; i++){
				for(ll j = 1; j <= w; j++){
					if(s[i][j] != -1 && nopush){
						quex.push(i);
						quey.push(j);
						nopush = false;
					}	
				}
			}	
		}
		else{
			x = quex.front();
			y = quey.front();
			quex.pop();
			quey.pop();
			if(s[x][y] != -1){
				//cout << x << y << endl;
