				if(s[x][y] + s[x-1][y] == 1){quex.push(x-1); quey.push(y);}
				if(s[x][y] + s[x+1][y] == 1){quex.push(x+1); quey.push(y);}
				if(s[x][y] == 0){countw++;}
				if(s[x][y] == 1){countb++;}
				s[x][y] = -1;
				flag = false;
				for(ll i = 1; i <= h; i++){
					for(ll j = 1; j <= w; j++){
						if(s[i][j] != -1){
							flag = true;
						}	
					}
				}
			}
		}
	}
	/*for(ll i = 1; i <= h; i++){
		for(ll j = 1; j <= w; j++){
			cout << s[i][j];	
		}
		cout << endl;
	}*/

	r += countw*countb;
	cout << r;	
	return 0;
}

