inline int CountAlternatelyWAndB(int wId, int hId, char preState, char firstState) 
{
  int count = 0;
  int currentState = s[wId][hId];

  if (wId < 1 || W < wId) return 0;
  if (hId < 1 || H < hId) return 0;
  if (visited[wId][hId]) return 0;

  if (currentState != preState)
  {
    visited[wId][hId] = true;

    if (currentState != firstState)
      count++;

    count += CountAlternatelyWAndB(wId + 1, hId, s[wId][hId], firstState);
    count += CountAlternatelyWAndB(wId, hId + 1, s[wId][hId], firstState);
    count += CountAlternatelyWAndB(wId - 1, hId, s[wId][hId], firstState);
    count += CountAlternatelyWAndB(wId, hId - 1, s[wId][hId], firstState);
  }
  else
    return 0;

  return count;
}

