struct UnionFind {
    vector<int> par;
    vector<int> sizes;

    UnionFind(int n) :
            par(n), sizes(n, 1) {
        for (int i = 0; i < n; i++) par[i] = i;
    }

    int find(int x) {
        return x == par[x] ? x : par[x] = find(par[x]);
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }

    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;
        if (sizes[x] < sizes[y]) swap(x, y);
        sizes[x] += sizes[y];
        par[y] = x;
    }

    int get_size(int x) {
        return sizes[find(x)];
    }

};

int f(int y, int x) {
    return y * W + x;
}

