void init(int h, int w) {
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            parent[w * i + j] = w * i + j;
            depth[w * i + j] = 1;
            black[w * i + j] = white[w * i + j] = 0;
        }
    }
}

int find(int p0) {
    if (parent[p0] == p0) {
        return p0;
    }
    return parent[p0] = find(parent[p0]);
}

void unite(int p0, int p1) {
    int parent0 = find(p0);
    int parent1 = find(p1);
    if (parent0 == parent1)
        return;

    if (depth[parent0] < depth[parent1]) {
        parent[parent1] = parent0;
    } else {
        parent[p0] = parent1;
        if (depth[parent0] == depth[parent1])
            depth[parent1]++;
    }
}

