#include <bits/stdc++.h>
using namespace std;

typedef long long llt;

const int MaxN = 400 + 5, MaxM = 400 + 5;
const int MaxV = 160000 + 5;

int N, M;
char str[MaxN][MaxM];
int par[MaxV]; bool vis[MaxV];
int dx[4] = {0, 1, -1, 0}, dy[4] = {1, 0, 0, -1};
map <int, bool> mp[MaxV];
llt Ans[MaxV], Cnt[MaxV];

void init() {
  scanf("%d %d", &N, &M);
  for (int i = 1; i <= N; ++i) scanf("%s", str[i] + 1);
}

inline int get_cor(int i, int j) {
  return (i - 1) * M + j;
}

int Find(int x) {
  return x == par[x] ? x : par[x] = Find(par[x]);
}

inline void Merge(int x, int y) {
  int p = Find(x), q = Find(y);
  par[p] = q;
}

void solve() {
  for (int i = 1; i <= N * M; ++i) par[i] = i;

  for (int i = 1; i <= N; ++i) for (int j = 1; j <= M; ++j) {
    if (str[i][j] == '#') {
      for (int k = 0; k < 4; ++k) {
        int x = i + dx[k], y = j + dy[k];
        if (x < 1 || x > N || y < 1 || y > M) continue;
        if (str[x][y] == '#') continue;

        for (int k2 = 0; k2 < 4; ++k2) {
          if (k + k2 == 3) continue;
          int u = x + dx[k2], v = y + dy[k2];
          if (u < 1 || u > N || v < 1 || v > M) continue;
          if (str[u][v] == '.') continue;

          Merge(get_cor(i, j), get_cor(u, v));
        }
      }
    }
  }

  for (int i = 1; i <= N; ++i) for (int j = 1; j <= M; ++j) {
    if (str[i][j] == '.') {
      for (int k = 0; k < 4; ++k) {
        int x = i + dx[k], y = j + dy[k];
        if (x < 1 || x > N || y < 1 || y > M) continue;
        if (str[x][y] == '.') continue;

        int p = Find(get_cor(x, y));
        if (mp[p][get_cor(i, j)] == true) continue;
        mp[p][get_cor(i, j)] = true;
        Ans[p]++;
      }
    } else {
      int p = Find(get_cor(i, j));
      Cnt[p]++;
    }
  }

  llt ans = 0;
  for (int i = 1; i <= N * M; ++i) {
    int p = Find(i);
    if (vis[p] == true) continue;
    vis[p] = true;
    ans += Ans[p] * Cnt[p];
  }
  cout << ans << endl;
}

int main() {
  init();
  solve();
  return 0;
}

