int count(int x, int y, vector<vector<int>>& P, vector<vector<bool>>& flag){
  long int ans=0;

  //printf("count : %d, %d\n", x, y);

  if(flag[x][y]==false) return ans;

  long int H, W;
  H = P.size();
  W = P[0].size();

  if(P[x][y]==1) ans+=1;

  flag[x][y]=false;

  //printf("P = %d\n", P[x][y]);

  if(x>0){
    if(P[x-1][y]==1-P[x][y] && flag[x-1][y]) ans+=count(x-1, y, P, flag);
  }
  if(x<H-1){
    if(P[x+1][y]==1-P[x][y] && flag[x+1][y]) ans+=count(x+1, y, P, flag);
  }
  if(y>0){
    if(P[x][y-1]==1-P[x][y] && flag[x][y-1]) ans+=count(x, y-1, P, flag);
  }
  if(y<W-1){
    if(P[x][y+1]==1-P[x][y] && flag[x][y+1]) ans+=count(x, y+1, P, flag);
  }

  return ans;
}

