template<class T> using V = vector<T>;
template<class T> using VV = V<V<T>>;
constexpr ll TEN(int n) { return (n == 0) ? 1 : 10 * TEN(n-1); }

struct QuickFind {
    V<int> id;
    VV<int> groups;
    int gc;  // group count
    QuickFind(int n = 0) {
        id = V<int>(n);
        groups = VV<int>(n);
        for (int i = 0; i < n; i++) {
            id[i] = i;
            groups[i] = {i};
        }
        gc = n;
    }
    void merge(int a, int b) {
        if (same(a, b)) return;
        gc--;
        int x = id[a], y = id[b];
        if (groups[x].size() < groups[y].size()) swap(x, y);
        for (int j : groups[y]) {
            id[j] = x;
            groups[x].push_back(j);
        }
        groups[y].clear();
    }
    bool same(int a, int b) { return id[a] == id[b]; }
};


int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << setprecision(20) << fixed;

    int h, w;
    cin >> h >> w;
    VV<bool> g(h, V<bool>(w));
    for (int i = 0; i < h; ++i) {
        string s;
        cin >> s;
        for (int j = 0; j < w; ++j) {
            g[i][j] = (s[j] == '#');
        }
    }
    QuickFind qf(h * w);
    auto id = [&](int i, int j) { return i * w + j; };
    for (int i = h-1; i >= 0; i--) {
        for (int j = w-1; j >= 0; j--) {
            if (i != h-1 && g[i+1][j] != g[i][j]) qf.merge(id(i, j), id(i + 1, j));
            if (j != w-1 && g[i][j+1] != g[i][j]) qf.merge(id(i, j), id(i, j + 1));
        }
    }
    ll ans = 0;
    for (auto v: qf.groups) {
        ll c0 = 0, c1 = 0;
        for (int d: v) {
            if (g[d / w][d % w] == true) c0++;
            else c1++;
        }
        ans += c0 * c1;
    }
    cout << ans << endl;
    return 0;
}

