#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

struct UnionFind{
    int num;
    vector<int> par,rank;
    UnionFind(int n):num(n),par(n),rank(n,1){
        iota(par.begin(),par.end(),0);
    }
    int root(int x){
        if (par[x]==x) return x;
        return par[x]=root(par[x]);
    }
    bool merge(int x, int y){
        x=root(x),y=root(y);
        if (x==y) return false;
        if (rank[x]<rank[y]) swap(x,y);
        par[y]=x;
        rank[x]+=rank[y];
        --num;
        return true;
    }
    bool same(int x, int y){
        return root(x)==root(y);
    }
    int size(int x){
        return rank[root(x)];
    }
    int count(){
        return num;
    }
};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int H,W; cin >> H >> W;
    vector<string> S(H);
    for (int i=0;i<H;++i) cin >> S[i];
    UnionFind uf(H*W);
    const int dx[2]={1,0};
    const int dy[2]={0,1};
    for (int i=0;i<H;++i){
        for (int j=0;j<W;++j){
            for (int k=0;k<2;++k){
                int nh=i+dx[k],nw=j+dy[k];
                if (H<=nh||W<=nw) continue;
                if (S[nh][nw]!=S[i][j]) uf.merge(i*W+j,nh*W+nw);
            }
        }
    }
    vector<vector<ll>> cnt(2,vector<ll>(H*W,0));
    for (int i=0;i<H;++i){
        for (int j=0;j<W;++j){
            if (S[i][j]=='#') ++cnt[0][uf.root(i*W+j)];
            else ++cnt[1][uf.root(i*W+j)];
        }
    }
    ll ans=0;
    for (int i=0;i<H*W;++i)
        ans+=cnt[0][i]*cnt[1][i];
    cout << ans << '\n';
}

