int find(vector < int > &lab, int x) {
  if(lab[x] == -1) return x;
  return lab[x] = find(lab, lab[x]);
}

void join(vector < int > &lab, int x, int y) {
  if(find(lab, x) == find(lab, y)) return;
  x = find(lab, x);
  y = find(lab, y);
  lab[x] = y;
}

int main(){
  ios_base::sync_with_stdio(false); 
  cin.tie(NULL); cout.tie(NULL);

  int n, m;
  cin >> n >> m;

  vector < string > a(n);
  for(int i = 0; i < n; ++i) cin >> a[i];

  vector < int > lab(n * m, -1);

  for(int i = 0; i < n; ++i){
    for(int j = 0; j < m; ++j) {
      if(i > 0 && a[i][j] != a[i - 1][j]) join(lab, i * n + j, i * n - n + j);
      if(j > 0 && a[i][j] != a[i][j - 1]) join(lab, i * n + j, i * n + j - 1);
    }
  }


  vector < int > cntblack(n * m, 0), cntwhite(n * m);

  for(int i = 0; i < n; ++i) for(int j = 0; j < m; ++j) {
    if(a[i][j] == '.') ++cntwhite[find(lab, i * n + j)];
    else ++cntblack[find(lab, i * n + j)];
  }

  long long ans = 0;

  for(int i = 0; i < n * m; ++i) {
    ans += 1LL * cntwhite[i] * (cntblack[i]);
  }

  cout << ans;

  return 0;
}

