int main(){

  ll H, W;
  cin >> H >> W;

  ll N = H * W; // 頂点数
  vector<ll> cells(N, 0); // 0:白, 1:黒
  // 頂点番号 : (h, w) -> h * W + w;

  rep(h, H){
    string s = is();
    rep(w, W) if(s[w]=='#') cells[h*W+w] = 1;
  }


  UnionFind UF(N); //Nはノード数
  rep(h, H) rep(w, W){
    // 右側と下側について、色が引っくり返っていたら繋げる
    if (w+1<=W-1 && cells[h*W+w]!=cells[h*W+w+1]) UF.unite(h*W+w, h*W+w+1);
    if (h+1<=H-1 && cells[h*W+w]!=cells[(h+1)*W+w]) UF.unite(h*W+w, (h+1)*W+w);
  }

  // 各頂点を舐めて、根の頂点番号が同じものはmapに入れていく
  map<ll, pll> cntmap; // pll : <根をkeyとする部分グラフが含む <白マス, 黒マス>
  rep(i, N){
    ll root = UF.find_root(i);
    if (cntmap.find(root) == cntmap.end()){
      // pllを初期化
      cntmap[root] = m_p(0, 0);
    }
    if (cells[i]==0) cntmap[root].first++;
    else cntmap[root].second++;
  }

  // 答え
  ll ans = 0;
  for (pair<ll, pll> eachvandk : cntmap){
    // その部分グラフに含まれる白の数×黒の数
    ans += eachvandk.second.first * eachvandk.second.second;
  }

  cout << ans << endl;


}

