    vector<vector<int>> used;
    int di[4] = {1, 0, -1, 0};
    int dj[4] = {0, 1, 0, -1};

    P dfs(int i, int j) {
        used[i][j] = 1;
        int res[2] = {0};
        res[S[i][j] == '.'] = 1;
        REP(k, 4) {
            int a = i + di[k];
