void place(int x, int y, vector<vector<int>>& P, vector<vector<int>>& flag, int tmp){

  //printf("place x:%d, y:%d\n", x, y);
  if(flag[x][y]==0) return;

  flag[x][y] = tmp;

  long int H, W;
  H = P.size();
  W = P[0].size();

  if(x>0){
    if(P[x-1][y]==1-P[x][y] && flag[x-1][y]!=tmp) place(x-1, y, P, flag, tmp);
  }
  if(x<H-1){
    if(P[x+1][y]==1-P[x][y] && flag[x+1][y]!=tmp) place(x+1, y, P, flag, tmp);
  }
  if(y>0){
    if(P[x][y-1]==1-P[x][y] && flag[x][y-1]!=tmp) place(x, y-1, P, flag, tmp);
  }
  if(y<W-1){
    if(P[x][y+1]==1-P[x][y] && flag[x][y+1]!=tmp) place(x, y+1, P, flag, tmp);
  }

  return;
}

int count(int x, int y, vector<vector<int>>& P, vector<vector<int>>& flag){
  long int ans=0;

  //printf("count : %d, %d\n", x, y);

  if(flag[x][y]!=0) return ans;

  long int H, W;
  H = P.size();
  W = P[0].size();

  if(P[x][y]==1) ans+=1;

  flag[x][y]=1;

  //printf("P = %d\n", P[x][y]);

  if(x>0){
    if(P[x-1][y]==1-P[x][y] && flag[x-1][y]==0) ans+=count(x-1, y, P, flag);
  }
  if(x<H-1){
    if(P[x+1][y]==1-P[x][y] && flag[x+1][y]==0) ans+=count(x+1, y, P, flag);
  }
  if(y>0){
    if(P[x][y-1]==1-P[x][y] && flag[x][y-1]==0) ans+=count(x, y-1, P, flag);
  }
  if(y<W-1){
    if(P[x][y+1]==1-P[x][y] && flag[x][y+1]==0) ans+=count(x, y+1, P, flag);
  }

  return ans;
}

