  vector<int> cnt(h * w, 0);
  UnionFind uf(h * w);
  auto calc = [&](int i, int j){
    for (int k = 0; k < 4; k++) {
      int x = i + dx[k], y = j + dy[k];
      if (x < 0 || y < 0 || x >= h || y >= w) continue;
      if (s[x][y] == '#') continue;
      uf.unite(i * w + j, x * w + y);
    }
  };
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (s[i][j] == '.') continue;
      calc(i, j);
      cnt[uf.find(i * w + j)]++;
    }
  }
  ll res = 0;
  for (int i = 0; i < h * w; i++) {
    if (s[i / w][i % w] == '.') continue;
    res += uf.size(i);
    res -= cnt[uf.find(i)];
  }
  cout << res << endl;
  return 0;
}

