int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};

int h, w;
typedef pair<int, int> P;


ll bfs(int sx, int sy) {
    used[sx][sy] = true;
    ll cnt_b = 1, cnt_w = 0;

    queue<P> que;
    que.push(P(sx, sy));
    while (!que.empty()) {
        P p = que.front();
        que.pop();
        for (int i = 0; i < 4; ++i) {
            int nx = p.first + dx[i], ny = p.second + dy[i];
            if (0 <= nx && nx < h && 0 <= ny && ny < w
                && field[p.first][p.second] != field[nx][ny] && !used[nx][ny]) {
                if (field[nx][ny] == '#')cnt_b++;
                else cnt_w++;
                que.push(P(nx, ny));
                used[nx][ny] = true;
            }
        }
    }

    return cnt_b * cnt_w;
}

int main() {
    scanf("%d %d", &h, &w);
    for (int i = 0; i < h; ++i) {
        char s[w];
