    ll ans = 0;
    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            if (field[i][j] == '#' && !used[i][j]) ans += bfs(i, j);
        }
    }

    printf("%lld\n", ans);
}

