typedef long long ll;
typedef pair<int,int> P;

struct UnionFind{
    vector<int> data;
    int __size;
    UnionFind(int sz) {
    data.assign(sz, -1);
    __size = sz;
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);//親は負でサイズを保存
    __size--;
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  bool same(int x, int y){
      return find(x) == find(y);
  }

  int size(int k) {
    return (-data[find(k)]);
  }

  int unum() {
    return (__size);
  }
};

int main(){ 
  int h, w;
  cin >> h >> w;
  vector<string> s(h);
  rep(i,h) cin >> s[i];
  UnionFind uf(h*w);
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (j + 1 < w && s[i][j] != s[i][j+1]) uf.unite(i*w+j, i*w+(j+1)); 
      if (i + 1 < w && s[i][j] != s[i+1][j]) uf.unite(i*w+j, (i+1)*w+j); 
    }
  }
  ll res = 0;
  vector<vector<int>> cnt(h*w,vector<int>(2,0));
  rep(i,h) rep(j,w) {
    if (s[i][j] == '#') cnt[uf.find(i*w+j)][0]++;
    else cnt[uf.find(i*w+j)][1]++;
  }

  rep(i,h*w) res += cnt[i][0]*cnt[i][1];
  cout << res << endl;
  return 0;
}

