                    unite(par,rank,i*w+j,(i+1)*w+j);
                }
            }
            if(j!=0){
                if(s[i][j]!=s[i][j-1]){
                    unite(par,rank,i*w+j,i*w+j-1);
                }
            }
            if(j!=w-1){
                if(s[i][j]!=s[i][j+1]){
                    unite(par,rank,i*w+j,i*w+j+1);
                }
            }
        }
    }

    ll count[h*w][2];
    rep(i,h*w){
        count[i][0] = 0;
        count[i][1] = 0;
    }
    rep(i,h){
        rep(j,w){
            if(s[i][j]=='#'){
                count[par[i*w+j]][0]++;
            }else{
                count[par[i*w+j]][1]++;
            }
        }
    }

    ll ans = 0;
    rep(i,h*w){
        ans += count[i][0]*count[i][1];
    }

    cout << ans << endl;

    return 0;
}

