            if(i>0&&field[i-1][j]!=field[i][j]) uf.unite(id(i-1,j),id(i,j));
            if(j>0&&field[i][j-1]!=field[i][j]) uf.unite(id(i,j),id(i,j-1));
        }
    } 
    ll ans = 0;
    for(auto v:uf.groups){
        ll black=0;
        ll white=0;
        for(int d:v){
            if(field[d/w][d%w]==true) black++;
            else white++;
        }
        ans += black*white;
    }
    cout << ans << endl;
    return 0;
}

