const int dy[] = {1, 0, -1, 0};
const int dx[] = {0, 1, 0, -1};
const int MAX_N = 500;
int h, w;
char table[MAX_N][MAX_N];
int flag[MAX_N][MAX_N];
int black;
int bfs(int y, int x, int t)
{
    queue<P> que;
    que.push(P(y, x));
    flag[y][x] = t;
    int res = 0;
    while(!que.empty())
    {
        P p = que.front();
        que.pop();
        for(int i = 0; i < 4; i++)
        {
            int ny = p.first + dy[i];
            int nx = p.second + dx[i];
            if(nx < 0 || ny < 0 || ny >= h || nx >= w) continue;
            if(table[ny][nx] == table[p.first][p.second]) continue; 
            if(flag[ny][nx] == t) continue;
            if(table[ny][nx] == '#') black++;
            else res++;
            flag[ny][nx] = t;
            que.push(P(ny, nx));
        }
    }
    return res;
}
