{
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> h >> w;
    int cnt = 0;
    for(int i = 0; i < h; i++)
        for(int j = 0; j < w; j++)
            cin >> table[i][j];
    int ans = 0;
    memset(flag, -1, sizeof(flag));
    int t = 0;
    for(int i = 0; i < h; i++)
    {
        for(int j = 0; j < w; j++)
        {
            if(table[i][j] == '#' && flag[i][j] == -1)
            {
                black = 1;
                int white = bfs(i, j, t);
                t++;
                ans += black * white;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

