template<class T>
T digitpower(T a,T b){//aのb乗を計算
  int mode=1;
  if(b==1){
    return a;
  }else if(b==0){
    return 1;
  }
  if(b%2==1){
    T tmp = digitpower(a,(b-1)/2);
    if(mode==0){
      tmp%=d9_7;
    }
    tmp*=tmp;
    if(mode==0){
      tmp%=d9_7;
    }
    tmp*=a;
    if(mode==0){
      return (tmp)%d9_7;
    }else{
      return tmp;
    }

  }else{
    T tmp = digitpower(a,(b)/2);
    if(mode==0){
      tmp%=d9_7;
    }
    tmp*=tmp;
    if(mode==0){
      tmp%=d9_7;
    }
    if(mode==0){
      return (tmp)%d9_7;
    }else{
      return tmp;
    }
  }
}

unordered_map<ll,ll> prime_factor(int64_t n) {
  unordered_map<ll,ll> ret;
  for(int64_t i = 2; i * i <= n; i++) {
    while(n % i == 0) {
      ret[i]++;
      n /= i;
    }
  }
  if(n != 1) ret[n] = 1;
  return ret;
}
