  if(v[i][j])return;
  if(c=='.'){
    ans_sub[cur].push_back((i*w+j));
  }
  if(c=='#'){
    ans[cur].push_back(i*w+j);
  }
  v[i][j]=true;
  if(i-1>=0 && !v[i-1][j] && s[i-1][j]!=c)dfs(i-1,j,s[i-1][j]);
