  if(j-1>=0 && !v[i][j-1] && s[i][j-1]!=c)dfs(i,j-1,s[i][j-1]);
  if(j+1<w && !v[i][j+1] && s[i][j+1]!=c)dfs(i,j+1,s[i][j+1]);
}

