                if(xi<0 || xi>=h || xj<0 || xj>=w)continue;
                if(s[ni][nj]==s[xi][xj])continue;
                if(check[xi][xj])continue;

                if((xi+xj)%2)
                    ans.back().first++;
                else
                    ans.back().second++;

                check[xi][xj] = 1;
                q.emplace(xi,xj);
            }
            q.pop();
        }
    }
    ll rtn = 0;
    rep(i,ans.size()){
        //cout << ans[i].first <<" "<< ans[i].second << endl;
        rtn += ans[i].first * ans[i].second;
    }

    cout << rtn << endl;

    return 0;
}

