using ll = long long;
const ll INF = (ll)1e18;

ll dy[4] = {  0,  0, -1, +1};
ll dx[4] = { -1, +1,  0,  0};

ll H, W, V;

typedef struct {
  ll to;
  ll cost;
} S_Edge;

template<typename Head> void print(Head head){ std::cout << head << std::endl; }

ll pos2idx(ll y, ll x) { return y * W + x; }

void make_map(std::vector< std::string >& grid, std::vector< std::vector<S_Edge> >& vedge)
{
  for (ll y = 0; y < H; y++) {
    for (ll x = 0; x < W; x++) {
      for (ll d = 0; d < 4; d++) {
	ll ny = y + dy[d];
	ll nx = x + dx[d];
	if (ny >= 0 && nx >= 0 && ny < H && nx < W) {
	  S_Edge edge;
	  edge.to   = pos2idx(ny, nx);
	  edge.cost = grid[y][x] == grid[ny][nx] ? INF : 1;
	  vedge[pos2idx(y, x)].push_back(edge);
	}
      }
    }
  }
}

//  #
// #.#.#.#.
//  #
//
// のような場合, 開始地点の候補数(=黒の数) * 終了地点の候補数(=白の数) を求めれば良いので,
// 6 * 4 = 24 通りになる.
// 複雑な経路であっても, 黒白が交互であれば, どの黒から始めても, どの白でも終わることができるため.
ll count_paths_and_upload_visit(ll s, std::string& idx_grid,
				std::vector< std::vector<S_Edge> >& vedge,
				std::vector< bool >& was_visited)
{
  ll black = 0;
  ll white = 0;
  std::queue<ll> que;

  que.push(s);
  was_visited[s] = true;
  black += idx_grid[s] == '#' ? 1 : 0;
  white += idx_grid[s] == '.' ? 1 : 0;

  while (!que.empty()){
    ll v = que.front(); que.pop();
    for (auto it = vedge[v].begin(); it != vedge[v].end(); it++) {
      if (!was_visited[it->to] && it->cost != INF) {
	que.push(it->to);
	was_visited[it->to] = true;
	black += idx_grid[it->to] == '#' ? 1 : 0;
	white += idx_grid[it->to] == '.' ? 1 : 0;
      }
    }
  }

  return black * white;
}

int main()
{
  std::cin >> H >> W;
  V = H * W;

  std::vector< std::string > grid(H, std::string(W, 'X'));
  std::string idx_grid;
  for (ll y = 0; y < H; y++) {
    std::cin >> grid[y];
    idx_grid += grid[y];
  }

  std::vector< std::vector<S_Edge> > vedge(V);
  make_map(grid, vedge);

  std::vector< bool > was_visited(V);

  ll ans = 0;
  for (ll v = 0; v < V; v++) {
    if (was_visited[v]) continue;
    ans += count_paths_and_upload_visit(v, idx_grid, vedge, was_visited);
  }

  print(ans);
  return 0;
}

