int bfs(vector<string> s, vector<vector<bool>> &flag, int i, int j)
{
  //bfs
  queue<pair<int, int>> q;
  q.push({i, j});
  flag[i][j] = true;
  int pw = 0;
  int pb = 0;
  if(s[i][j] == '.')
  {
    pw++;
  }else{
    pb++;
  }
  while(!q.empty())
  {
    pair<int, int> current = q.front();
    q.pop();
    if(current.first > 0){
      if(s[current.first][current.second] != s[current.first - 1][current.second] && !flag[current.first - 1][current.second])
      {
        q.push({current.first - 1, current.second});
        flag[current.first - 1][current.second] = true;
        if(s[current.first - 1][current.second] == '.')
        {
          pw++;
        }else{
          pb++;
        }
      }
    }
    if(current.first < h - 1){
      if(s[current.first][current.second] != s[current.first + 1][current.second] && !flag[current.first + 1][current.second])
      {
        q.push({current.first + 1, current.second});
        flag[current.first + 1][current.second] = true;
        if(s[current.first + 1][current.second] == '.')
        {
          pw++;
        }else{
          pb++;
        }
      }
    }
    if(current.second > 0){
      if(s[current.first][current.second] != s[current.first][current.second - 1] && !flag[current.first][current.second - 1])
      {
        q.push({current.first, current.second - 1});
        flag[current.first][current.second - 1] = true;
        if(s[current.first][current.second - 1] == '.')
        {
          pw++;
        }else{
          pb++;
        }
      }
    }
    if(current.second < w - 1)
    {
      if(s[current.first][current.second] != s[current.first][current.second + 1] && !flag[current.first][current.second + 1])
      {
        q.push({current.first, current.second + 1});
        flag[current.first][current.second + 1] = true;
        if(s[current.first][current.second + 1] == '.')
        {
          pw++;
        }else{
          pb++;
        }
      }
    }
  }
  return pw * pb;
}

