				if (i > 0) {
					if (v[i - 1][j] == '.') {
						uni.unite(i*W + j, (i - 1)*W + j);
					}
				}
				if (i < H - 1) {
					if (v[i + 1][j] == '.') {
						uni.unite(i*W + j, (i + 1)*W + j);
					}
				}
				if (j > 0) {
					if (v[i][j - 1] == '.') {
						uni.unite(i*W + j, i*W + j - 1);
					}
				}
				if (j < W - 1) {
					if (v[i][j + 1] == '.') {
						uni.unite(i*W + j, i*W + j + 1);
					}
