const char CHAR_STR = '#';
const char CHAR_END = '.';

typedef struct { int x; int y; } Point;

typedef struct
{
	int  h;
	int  w;
	char map [400][400];
	char flag[400][400];
} Parameter;

int count_to_goal(Parameter * p, int sx, int sy)
{
	std::list<Point> stack;
	int num_str = 0;
	int num_end = 0;

	if ( p->flag[sy][sx] ) return 0;

	stack.push_back((Point){sx, sy});
	p->flag[sy][sx] = 1;

	if ( p->map[sy][sx] == CHAR_STR ) num_str++;
	else num_end++;

	for (; stack.size(); )
	{
		auto cur = stack.front();
		stack.pop_front();

		for (auto i = 0; i < 4; i++)
		{
			auto nex = cur;
			switch (i)
			{
			case 0: nex.x += 1; break;
			case 1: nex.y += 1; break;
			case 2: nex.x -= 1; break;
			case 3: nex.y -= 1; break;
			}
			if ((nex.x < 0) || (nex.x >= p->w) || (nex.y < 0) || (nex.y >= p->h))
				continue;
			if (p->flag[nex.y][nex.x])
				continue;
			if (p->map[cur.y][cur.x] == p->map[nex.y][nex.x])
				continue;

			stack.push_back(nex);
			p->flag[nex.y][nex.x] = 1;
			if (p->map[nex.y][nex.x] == CHAR_STR) num_str++;
			else num_end++;
		}
	}

	return num_str * num_end;
}

