inline bool ok(int x2,int y2){return (x2>=0&&y2>=0&&x2<n&&y2<m);}
pii arrive(int x,int y,bool black)
{
	pii p;
	if(black)p.F++;
	else p.S++;
	for(int i=0;i<4;i++)
	{
		int x2=x+dx[i];
		int y2=y+dy[i];
		if(ok(x2,y2)&&!f[x2][y2]&&black!=a[x2][y2])
		{
			f[x2][y2]=true;
			pii j=arrive(x2,y2,!black);
			p.F+=j.F;
			p.S+=j.S;
		}
	}
	return p;
}
int main()
{
	scanf("%d %d",&n,&m);
	for(int i=0;i<n;i++)
	{
		for(int j=0;j<m;j++)
		{
			cin>>c;
