		}
	}
	for(int i=0;i<n;i++)
	{
		for(int j=0;j<m;j++)
		{
			if(f[i][j])continue;
			pii p=arrive(i,j,a[i][j]);
			if(a[i][j])p.F--;
			else p.S--;
			ans+=min(p.F*p.S,0);
		}
	}
	printf("%d",ans);
	return 0;
