int findp(int * parent, int n) {
  if(parent[n] == n) return n;
  parent[n] = findp(parent,parent[n]);
  return parent[n];
}

int main() {
  ios::sync_with_stdio(0);
  cin.tie(0);
  int n,len;
  cin >> n >> len;
  int parent[n*len];
  int blacks[n*len];
  int whites[n*len];
  rep(i,0,n*len) {
    parent[i] = i;
    blacks[i] = whites[i] = 0;
  }
  string s[n];
  rep(i,0,n) {
    cin >> s[i];
  }
  rep(i,0,n) {
    rep(j,0,len) {
      if(i != 0) {
        if(s[i-1][j] != s[i][j]) {
          parent[i*len + j] = findp(parent,(i-1)*len + j);
        }
      }
      if(j!= 0) {
        if(s[i][j] != s[i][j-1]) {
          parent[parent[i*len + j]] = findp(parent,(i*len + j - 1));
        }
      }
    }
  }
  rep(i,0,n) {
    rep(j,0,len) {
      int p = findp(parent,i*len + j);
      if(s[i][j] == '#') blacks[p]++;
      else whites[p]++;
    }
  }
  long ways = 0;
  rep(i,0,n) {
    rep(j,0,len) {
      ways += (long)(whites[i*len + j] * blacks[parent[i*len+j]]);
    }
  }
