	int x, y;
	pt() {}
	pt(int x, int y) {
		this->x = x;
		this->y = y;
	}
};

bool g[405][405], vis[405][405];
int n, m, dx[4] = {-1, 0, 0, 1}, dy[4] = {0, -1, 1, 0};
num ans;

num bfs(int sx, int sy) {
	num cnt0 = 0, cnt1 = 0;
	queue<pair<pt, int>> q;
	q.push(make_pair(pt(sx, sy), g[sx][sy]));
	vis[sx][sy] = 1;
	while (!q.empty()) {
		int x = q.front().first.x, y = q.front().first.y, c = q.front().second;
		q.pop();
		cnt0 += c == 0;
		cnt1 += c == 1;
		loop (i, 4) {
			int cx = x + dx[i], cy = y + dy[i];
			if (cx < 0 || cy < 0 || cx >= n || cy >= m || g[cx][cy] == c || vis[cx][cy])  continue;
			vis[cx][cy] = 1;
			q.push(make_pair(pt(cx, cy), c ^ 1));
		}
	}
	return cnt0 * cnt1;
}

int main() {
	ios_base::sync_with_stdio(0);
	cin >> n >> m;
	loop (i, n) {
		string s;
		cin >> s;
		loop (j, m) {
			g[i][j] = s[j] == '#';
		}
	}
	loop (i, n) {
		loop (j, m) {
			if (!vis[i][j]) {
				ans += bfs(i, j);
			}
		}
	}
	cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int INF = 1e9;
const int MOD = 1e9 + 7;

int h, w;
string s[500];

int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};
bool check[500][500];

void dfs(int y, int x, ll &b_num, ll &w_num)
{
  check[y][x] = true;
  for (int i = 0; i < 4; ++i)
  {
    int ny = y + dy[i], nx = x + dx[i];
    if (0 <= nx && nx < w && 0 <= ny && ny < h && !check[ny][nx] && s[ny][nx] != s[y][x])
    {
      if (s[ny][nx] == '#')
        b_num++;
      else
        w_num++;
      dfs(ny, nx, b_num, w_num);
    }
  }
  return;
}

int main()
{
  cin >> h >> w;
  for (int i = 0; i < h; ++i)
    cin >> s[i];

  ll ans = 0;
  for (int i = 0; i < h; ++i)
  {
    for (int j = 0; j < w; ++j)
    {
      if (!check[i][j])
      {
        ll b_num = 0, w_num = 0;
        if (s[i][j] == '#')
          b_num++;
        else
          w_num++;
        dfs(i, j, b_num, w_num);
        ans += b_num * w_num;
      }
    }
  }

  cout << ans << endl;

  return 0;
}

