using namespace std;
using ll = long long;
using vi = vector<int>;
using vv = vector<vi>;
using P  = pair<int,int>;

int main(){
    int h,w; cin >>h >>w;
    vector<string> s(h);
    rep(i,h){
        cin >>s[i];
        rep(j,w){
            if((i+j)%2)continue;
            if(s[i][j]=='.')s[i][j]='#';
            else s[i][j] = '.';
        }
        //cout << s[i] << endl;
    }

    vv check(h, vi (w,0));

    vector<P> ans;

    queue<P> q;
    vi di = {-1,1,0,0};
    vi dj = {0,0,-1,1};

    rep(i,h)rep(j,w){
        if(check[i][j])continue;
        check[i][j] = 1;
        ans.emplace_back(0,0);
        if((i+j)%2)
            ans.back().first++;
        else
            ans.back().second++;

        q.emplace(i,j);

        while(!q.empty()){
            int ni = q.front().first;
            int nj = q.front().second;

            rep(k,4){
                int xi = ni + di[k];
                int xj = nj + dj[k];
                if(xi<0 || xi>=h || xj<0 || xj>=w)continue;
                if(s[ni][nj]!=s[xi][xj])continue;
                if(check[xi][xj])continue;

                if((xi+xj)%2)
                    ans.back().first++;
                else
                    ans.back().second++;

                check[xi][xj] = 1;
                q.emplace(xi,xj);
            }
            q.pop();
        }
    }
    ll rtn = 0;
    rep(i,ans.size()){
        rtn += ans[i].first * ans[i].second;
    }

    cout << rtn << endl;

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int N=400+10;
typedef long long LL;
const int dx[]={-1,0,1,0};
const int dy[]={0,1,0,-1};
int n,m;
char mp[N][N];
bool vis[N][N];
LL black,white;

void dfs(int x,int y) {
	vis[x][y]=1;
	if (mp[x][y]=='#') black++; else white++;
	for (int i=0;i<4;i++) {
		int nx=x+dx[i],ny=y+dy[i];
		if (nx<1 || nx>n || ny<1 || ny>m || vis[nx][ny] || mp[x][y]==mp[nx][ny]) continue;
		dfs(nx,ny);
	}
}

int main()
{
	scanf("%d%d",&n,&m);
	for (int i=1;i<=n;i++) scanf("%s",mp[i]+1);

	LL ans=0;
	memset(vis,0,sizeof(vis));
	for (int i=1;i<=n;i++)
		for (int j=1;j<=m;j++)
			if (!vis[i][j] && mp[i][j]=='#') {
				black=0; white=0;
				dfs(i,j);
				ans+=black*white;
			}
	cout<<ans;		
	return 0;
}

