using namespace std;

int main()
{
    int H, W;
    cin >> H >> W;

    vector<string> S(H);
    vector<vector<bool>> isVisited(H, vector<bool>(W, false));

    for (int i = 0; i < H; i++)
    {
        cin >> S[i];
    }
    int sum = 0;

    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            if (isVisited[i][j])
                continue;
            queue<pair<int, int>> next;
            next.push(make_pair(i, j));

            int B = 0;
            int WH = 0;

            while (!next.empty())
            {
                pair<int, int> cur = next.front();
                next.pop();

                if (isVisited[cur.first][cur.second])
                    continue;

                isVisited[cur.first][cur.second] = true;
                //cout << cur.first << " " << cur.second << endl;

                if (S[cur.first][cur.second] == '#')
                {
                    B++;

                    if (0 <= cur.first - 1 && S[cur.first - 1][cur.second] == '.')
                    {
                        next.push(make_pair(cur.first - 1, cur.second));
                    }

                    if (cur.first + 1 < H && S[cur.first + 1][cur.second] == '.')
                    {
                        next.push(make_pair(cur.first + 1, cur.second));
                    }

                    if (0 <= cur.second - 1 && S[cur.first][cur.second - 1] == '.')
                    {
                        next.push(make_pair(cur.first, cur.second - 1));
                    }

                    if (cur.second + 1 < W && S[cur.first][cur.second + 1] == '.')
                    {
                        next.push(make_pair(cur.first, cur.second + 1));
                    }
                }
                if (S[cur.first][cur.second] == '.')
                {
                    WH++;

                    if (0 <= cur.first - 1 && S[cur.first - 1][cur.second] == '#')
                    {
                        next.push(make_pair(cur.first - 1, cur.second));
                    }

                    if (cur.first + 1 < H && S[cur.first + 1][cur.second] == '#')
                    {
                        next.push(make_pair(cur.first + 1, cur.second));
                    }

                    if (0 <= cur.second - 1 && S[cur.first][cur.second - 1] == '#')
                    {
                        next.push(make_pair(cur.first, cur.second - 1));
                    }

                    if (cur.second + 1 < W && S[cur.first][cur.second + 1] == '#')
                    {

                        next.push(make_pair(cur.first, cur.second + 1));
                    }
                }
            }

            sum += B * WH;
        }
    }

    cout << sum << endl;
}

