using namespace std;
#define rep(i, n) for(int i = 0; i < (int)(n); i++)
#define SZ(x) ((int)(x).size())
#define INF (1e16)
typedef long long ll;
int h, w;
char m[405][405];
char m2[10000];

int parent[10000];
int nb[100000];
int nw[100000];
int visited[10000];

void init(int n){// 初期化．全てのnodeで親を自分自身に，tree_rankを0にする．nもらわなくてもv.size()でいける
    rep(i, n){
        parent[i] = i;
        if(m2[i] == '#'){
            nb[i] = 1;
            nw[i] = 0;
        }else{
            nb[i] = 0;
            nw[i] = 1;
        }
    }
}

int root(int x){// node xのrootを返す．parent[x] = root(parent[x])で親をrootにつなぎ替える
    return x == parent[x] ? x : parent[x] = root(parent[x]);
}

bool same(int x, int y){// 同じ木に属するかどうか判定する
    return root(x) == root(y);
}

void unite(int x, int y){// xの属する木とyの属する木を連結する．rankができるだけ低くなるように処理を行う
    x = root(x);
    y = root(y);

    if(x != y){
        parent[y] = x;
        nb[x] += nb[y];
        nw[x] += nw[y];
    }
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);//おまじないでcin, cout早くする

    cin >> h >> w;
    int cnt = 0;
    rep(i, h){
        rep(j, w){
            cin >> m[i][j];
            m2[cnt] = m[i][j];
            cnt++;
        }
    }

    init(h * w);

    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            if(i != h - 1){
                if(m[i][j] != m[i+1][j]){
                    unite(i * w + j, (i+1) * w + j);
                }
            }
            if(j != w - 1){
                if(m[i][j] != m[i][j+1]){
                    unite(i * w + j, i * w + j + 1);
                }
            }
        }
    }

    rep(i, h * w){
        visited[i] = 0;
    }

    ll ans = 0;
    rep(i, h * w){
        int k = root(i);
        if(visited[k] == 0){
            ans += nb[k] * nw[k];
            visited[k] = 1;
        }
    }

    cout << ans << "\n";
    return 0;
}

