struct UF {
	vector<int> par;
	UF(int i) : par(i) {
		for (int j = 0; j < i; j++) {
			par[j] = j;
		}
	}
	int parent(int i) {
		if (par[i] == i) return i;
		return par[i] = parent(par[i]);
	}
	bool find(int i, int j) {
		return parent(i) == parent(j);
	}
	void uni(int i, int j) {
		par[parent(i)] = parent(j);
	}
};

int main() {
	int H, W; cin >> H >> W;
	vector<string> S(W);
	for (int i = 0; i < H; i++) cin >> S[i];
