	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (S[i][j] == '#') Sblack.push_back(i * W + j);
			else Swhite.push_back(i * W + j);
		}
	}
	UF uf(H * W);
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			char s = S[i][j];
			int idx = i * W + j;
			if (0 <= i - 1 && s != S[i - 1][j]) {
				uf.uni(idx, (i - 1) * W + j);
			}
			if (0 <= j - 1 && s != S[i][j - 1]) {
				uf.uni(idx, i * W + (j - 1));
			}
		}
	}
	int ans = 0;
	for (int i = 0, sz = Sblack.size(); i < sz; i++) {
		for (int j = 0, sz = Swhite.size(); j < sz; j++) {
			if (uf.find(Sblack[i], Swhite[j])) ans++;
		}
	}
	cout << ans << endl;
}

