    vector<pll> D{{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
    auto used = make_vector(m, n, false);
    auto dfs = [&](ll i, ll j){
        if(used[i][j]){
            return (ll)0;
        }
        used[i][j] = true;
        vector<pll> stack{{i, j}};
        ll white = 0, black = 0;
        while(!stack.empty()){
            ll i, j; tie(i, j) = stack.back(); stack.pop_back();
            (grid[i][j] == '.' ? white : black) ++;
