                    continue;
                }
                if(grid[i][j] != grid[ni][nj]){
                    used[ni][nj] = true;
                    stack.emplace_back(ni, nj);
                }
            }
        }
        return white * black;
    };

    ll res = 0;
    rep(i, m){
        rep(j, n){
            res += dfs(i, j);
        }
    }
