vector<vector<bool>> seen(405,vector<bool>(405));

int main() {
    ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int H,W;cin >> H >> W;
    vector<vector<char>> ban(H,vector<char>(W));
    for(int i = 0;i<H;i++)for(int j = 0;j<W;j++) cin >> ban.at(i).at(j);

    for(int i = 0;i<164514;i++){
        parent[i] = i;
        tall[i] = 0;
    }

    for(int i = 0;i<H;i++){
        for(int j = 0;j<W;j++){
            queue<pair<int,int>> Q;
            //BFSする
            Q.push(make_pair(i,j));
            while(!Q.empty()){
                P p = Q.front();Q.pop();
                int nowH = p.first,nowW = p.second;
                seen.at(nowH).at(nowW) = true;
                for(int k = 0;k<4;k++){
                    int nh = nowH+dh.at(k),nw = nowW+dw.at(k);
                    if(nh < 0 || nh >= H || nw < 0 || nw >= W || ban.at(nowH).at(nowW) == ban.at(nh).at(nw)) continue;
                    if(seen.at(nh).at(nw)) continue;
                    /*
                    グリッドの頂点番号を、
                    1 2 3
                    4 5 6
                    7 8 9
                    みたいにする（面倒なので）
                    */
                    unite(nowH*W+nowW+1,nh*W+nw+1);
                    Q.push(make_pair(nh,nw));
                    seen.at(nh).at(nw) = true;
                }
            }
        }
    }

    vector<long long> white(160005);
    vector<long long> black(160005);

    for(int i = 0;i<H;i++){
        for(int j = 0;j<W;j++){
            int index = searchRoot(i*W+j+1);
            if(ban.at(i).at(j) == '.'){
                white.at(index)++;
            }
            else{
                black.at(index)++;
            }
        }
    }

    long long ans = 0;
    for(int i = 0;i<H;i++){
        for(int j = 0;j<W;j++){
            ans += white.at(i*W+j+1)*black.at(i*W+j+1);
        }
    }

    cout << ans << endl;

}

