int main(void) {
    int h, w, i, j, k;
    ll ans = 0;
    string s[403];
    bool u[403][403] = { false };
    const int di[4] = { 1,0,-1,0 }, dj[4] = { 0,1,0,-1 };

    cin >> h >> w;
    for (i = 0; i < h; i++) {
        cin >> s[i];
    }

    for (i = 0; i < h; i++) for (j = 0; j < w; j++) {
        if (s[i][j] == '#' && !u[i][j]) {

            int pi, pj, ni, nj;
            ll ws = 0, bs = 0;
            P p;
            queue<P> q;
            q.push(P(i, j));
            u[i][j] = true;
            while (!q.empty()) {
                p = q.front();
                q.pop();
                pi = p.first;
                pj = p.second;
                if (s[pi][pj] == '.') ws++;
                if (s[pi][pj] == '#') bs++;
                for (k = 0; k < 4; k++) {
                    ni = pi + di[k];
