                    if (ni >= 0 && ni < h && nj >= 0 && nj < w && !u[ni][nj] && s[pi][pj] != s[ni][nj]) {
                        q.push(P(ni, nj));
                        u[ni][nj] = true;
                    }
                }
            }
            ans += ws * bs;

        }
    }

    cout << ans << endl;

    return 0;
}

