bool used[400][400];
int dx[4] = {0, 0, -1, 1};
int dy[4] = {-1, 1, 0, 0};
int W, H;
string S[400];

int main() {
    cin >> H >> W;
    for (int i = 0; i < H; i++) {
        cin >> S[i];
    }

    int count = 0;
    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            count += bfs(x, y);
        }
    }

    cout << count << endl;

    return 0;
}

int bfs(int startX, int startY) {
    if (used[startY][startX]) return 0;
    int black = 0, white = 0;
    queue<pair<int, int>> que;
    que.push(make_pair(startX, startY));
    used[startY][startX] = true;
    while (que.size() > 0) {
        int x = que.front().first;
        int y = que.front().second;
        que.pop();
        if (S[y][x] == '#') {
            black++;
        } else {
            white++;
        }
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (!withinArea(nx, ny)) continue;
            if (used[ny][nx]) continue;
            if (S[y][x] == S[ny][nx]) continue;
            que.push(make_pair(nx, ny));
            used[ny][nx] = true;
        }
    }
    return black * white;
}

bool withinArea(int x, int y) {
    return 0 <= x && x < W && 0 <= y && y < H;
}

