int count(boost::multi_array<bool, 2>const& field, int i, int j, int H, int W)
{
	bool flag[400][400] = {};
	struct t
	{
		int i, j;
		bool f;
	};
	std::queue<t> queue;
	queue.emplace(t{ i,j,true });
	int ret = 0;
	while (queue.size())
	{
		auto top = queue.front();
		queue.pop();
		if (top.i < 0 || top.i >= H || top.j < 0 || top.j >= W)
		{
			continue;
		}
		if (flag[top.i][top.j])
		{
			continue;
		}
		if (field[top.i][top.j] != top.f)
		{
			continue;
		}
		flag[top.i][top.j] = true;
		ret += !top.f;
		queue.emplace(t{ top.i + 1,top.j,!top.f });
		queue.emplace(t{ top.i - 1,top.j,!top.f });
		queue.emplace(t{ top.i ,top.j + 1,!top.f });
		queue.emplace(t{ top.i ,top.j - 1,!top.f });
	}
	return ret;
}

