int par[200010];
int unifind(int n) {
             for (int i = 0; i < n; i++) {
                           par[i] = i;
             }
             return 0;
}
             //木の根を求める
int unifind_root(int x) {
             if (par[x] == x) {
                           return x;
             }
             else {
                           return par[x] = unifind_root(par[x]);
             }
}
             //同じグループか判定
bool unifind_same(int x, int y) {
             return unifind_root(x) == unifind_root(y);
}
             //グループ併合
int unifind_unite(int x, int y) {
             x = unifind_root(x);
             y = unifind_root(y);
             if (x == y) {
                           return 0;
             }
             par[x] = y;
}


