void solve() {
  int n, m;
  cin >> n >> m;
  string s[n];
  rep(i, n) cin >> s[i];
  vector<vector<int> > table(n, vector<int>(m));

  int ans = 0;
  rep(i, n) rep(j, m) {
    if (table[i][j]) continue;

    queue<pii> q;
    q.push(pii(i, j));
    table[i][j] = 1;

    int cnt = 0, cnt2 = 0;
    if (s[i][j] == '#') cnt++;
    else cnt2++;

    int dy[] = {-1, 0, 1, 0};
    int dx[] = {0, 1, 0, -1};
    while (!q.empty()) {
      int y = q.front().F, x = q.front().S;
      q.pop();

      rep(i, 4) {
        int ny = y + dy[i], nx = x + dx[i];
        if (ny < 0 || ny >= n || nx < 0 || nx >= m) continue;
        if (table[ny][nx]) continue;
        if (s[ny][nx] == s[y][x]) continue;

        if (s[ny][nx] == '#') cnt++;
        else cnt2++;
        table[ny][nx] = 1;
        q.push(pii(ny, nx));
      }
    }
    // cout << cnt << " " << cnt2 << endl;
    ans += cnt * cnt2;
  }
  cout << ans << endl;
}

