void search(int row, int col, int (&count_mat)[400][400],
  int (&group_num1), int (&group_num2), string S[400], ll HH, ll WW) {
  // group_num++;
  if (S[row][col] == '#') {
    group_num1++;
  }else{
    group_num2++;
  }
  count_mat[row][col] = 1;

  if (col+1 < WW && S[row][col] != S[row][col+1] && count_mat[row][col+1]==0) {
    search(row, col+1, count_mat, group_num1, group_num2, S, HH, WW);
  }
  if (row+1 <HH && S[row][col] != S[row+1][col] && count_mat[row+1][col]==0) {
    search(row+1, col, count_mat, group_num1, group_num2, S, HH, WW);
  }
  if (col-1 >= 0 && S[row][col] != S[row][col-1] && count_mat[row][col-1]==0) {
    search(row, col-1, count_mat, group_num1, group_num2, S, HH, WW);
  }
  if (row-1>= 0 && S[row][col] != S[row-1][col] && count_mat[row-1][col]==0) {
    search(row-1, col, count_mat, group_num1, group_num2, S, HH, WW);
  }
}

int main(int argc, char const *argv[]) {
  ll HH, WW;

  std::cin >> HH>>WW;

  string S[400];
  for (size_t i = 0; i < HH; i++) {
    std::cin >> S[i];
  }

  // for (size_t i = 0; i < HH; i++) {
  //   std::cout << S[i] << '\n';
  // }

  int count_mat[400][400];

  for (size_t i = 0; i < HH; i++) {
    for (size_t j = 0; j < WW; j++) {
      count_mat[i][j] = 0;
    }
  }

  ll group_count = 0;
  ll group_nums[160000];

  for (int row = 0; row < HH; row++) {
    for (int col = 0; col < WW; col++) {
      if (count_mat[row][col] == 0) {
        int group_num1 = 0, group_num2 = 0;
        search(row, col, count_mat, group_num1,group_num2, S, HH, WW);

        group_nums[group_count] = group_num1 * group_num2;
        group_count++;
      }
    }
  }

  // for (size_t i = 0; i < group_count; i++) {
  //   std::cout << group_nums[i] << '\n';
  // }

  ll ans = 0;
  for (size_t i = 0; i < group_count; i++) {
    ans+= group_nums[i];
  }
  std::cout << ans << '\n';

  return 0;
}

