pair<int,int> dfs(int h,int w){
    pair<int,int> ret(0,0);
    if(str[h][w]=='#'){
        ret.first=1;
        ret.second=0;
    }else{
        ret.first=0;
        ret.second=1;
    }
    used[h][w]=true;
    for(int i = 0;i < 4;i++){
        int nh=h+d[i][0],nw=w+d[i][1];
        if(nh<0||nw<0||nh>=H||nw>=W||used[nh][nw])
            continue;
        if(str[h][w]!=str[nh][nw]){
            pair<int,int> temp=dfs(nh,nw);
            ret.first+=temp.first;
            ret.second+=temp.second;
        }
    }
    return ret;
}

