    cin>>H>>W;
    for(int i = 0;i < H;i++){
        cin>>str[i];
    }
    for(int h = 0;h < H;h++){
        for(int w = 0;w < W;w++){
            if(used[h][w])continue;
            pair<int,int> x = dfs(h,w);
            ans += x.first*x.second;
        }
    }
    cout<<ans<<endl;
    return 0;
}

