int main() {
  int H, W;
  cin >> H >> W;
  vector<string> S(H);
  REP(i, H) cin >> S[i];
  vector<vector<int>> A(H, vector<int>(W));
  vector<P> disjoint_list(0);
  REP(i, H) REP(j, W) {
    if (S[i][j] == '.') continue;
    if (A[i][j] != 0) continue;
    int number = disjoint_list.size() + 1;
    disjoint_list.push_back(P(i, j));
    queue<P> que;
    A[i][j] = number;
    que.push(P(i, j));
    while (!que.empty()) {
      P p = que.front();
      que.pop();
      int y = p.first, x = p.second;
      if (x > 0) {
        int ny = y, nx = x - 1;
        if (S[y][x] != S[ny][nx] && A[ny][nx] == 0) {
          A[ny][nx] = number;
          que.push(P(ny, nx));
        }
      }
      if (x < W - 1) {
        int ny = y, nx = x + 1;
        if (S[y][x] != S[ny][nx] && A[ny][nx] == 0) {
          A[ny][nx] = number;
          que.push(P(ny, nx));
        }
      }
      if (y > 0) {
        int ny = y - 1, nx = x;
        if (S[y][x] != S[ny][nx] && A[ny][nx] == 0) {
          A[ny][nx] = number;
          que.push(P(ny, nx));
        }
      }
      if (y < H - 1) {
        int ny = y + 1, nx = x;
        if (S[y][x] != S[ny][nx] && A[ny][nx] == 0) {
          A[ny][nx] = number;
          que.push(P(ny, nx));
        }
      }
    }
  }
  int ans = 0;
  REP(i, disjoint_list.size()) {
    queue<P> que;
    que.push(P(disjoint_list[i].first, disjoint_list[i].second));
    int tmp = 0, number = 1;
    A[disjoint_list[i].first][disjoint_list[i].second] = 0;
    while (!que.empty()) {
      P p = que.front();
      que.pop();
      int y = p.first, x = p.second;
      if (x > 0) {
        int ny = y, nx = x - 1;
        if (S[y][x] != S[ny][nx] && A[ny][nx] != 0) {
          if (S[ny][nx] == '#')
            number++;
          else
            tmp++;
          A[ny][nx] = 0;
          que.push(P(ny, nx));
        }
      }
      if (x < W - 1) {
        int ny = y, nx = x + 1;
        if (S[y][x] != S[ny][nx] && A[ny][nx] != 0) {
          if (S[ny][nx] == '#')
            number++;
          else
            tmp++;
          A[ny][nx] = 0;
          que.push(P(ny, nx));
        }
      }
      if (y > 0) {
        int ny = y - 1, nx = x;
        if (S[y][x] != S[ny][nx] && A[ny][nx] != 0) {
          if (S[ny][nx] == '#')
            number++;
          else
            tmp++;
          A[ny][nx] = 0;
          que.push(P(ny, nx));
        }
      }
      if (y < H - 1) {
        int ny = y + 1, nx = x;
        if (S[y][x] != S[ny][nx] && A[ny][nx] != 0) {
          if (S[ny][nx] == '#')
            number++;
          else
            tmp++;
          A[ny][nx] = 0;
          que.push(P(ny, nx));
        }
      }
    }
    ans += tmp * number;
  }
  cout << ans << endl;
}

