                for(int k = 0; k < 4; k++){
                    int di = p.first + dx[k], dj = p.second + dy[k];
                    if(inRange(di, 0, h) && inRange(dj, 0, w) && mat[di][dj]!=mat[p.first][p.second]){
                        s.push({di,dj});
                    }
                }
            }
            ans += black*white;
        }
    }

    cout << ans << endl;

    return 0;
}

