ll bfs(vector<string> &s, ll i, ll j){
    ll cnt = 0;
    ll h = s.size();
    ll w = s[0].size();
    vvi chk(h, vi(w, 0));
    queue<pair<pair<ll, ll>, ll>> que;
    que.push(make_pair(make_pair(i, j), 0));
    chk[i][j] = 1;
    while(que.size()){
        auto front = que.front();
        que.pop();
        ll x = front.first.second;
