struct UnionFind {
    vector<int> par;
    vector<int> rank;
    vector<int> Size;
    UnionFind(int n = 1) {
        init(n);
    }
    void init(int n = 1) {
        par.resize(n+1);
        rank.resize(n+1);
        Size.resize(n+1);
        for(int i=0;i<=n;++i) par[i] = i, rank[i] = 0, Size[i] = 1;
    }
    int root(int x) {
        if (par[x] == x) return x;
        else return par[x] = root(par[x]);
    }
    bool same(int x, int y) {
        return root(x) == root(y);
    }
    bool unite(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y);
        if (rank[x] == rank[y]) ++rank[x];
        par[y] = x;
        Size[x] += Size[y];
        return true;
    }
    int Sz(int x){
        return Size[root(x)];
    }
};
