using namespace std;

struct Pair{
    long a,b;
};

Pair search(int x,int y,int w,int h,vector<vector<char> > stage,vector<vector<bool> >& mark,vector<vector<bool> >& flags){
    Pair ret;
    ret.a = stage[x][y] == '.' ? 1 : 0;
    ret.b = 1;
    if(x > 0){
        if(mark[x][y] == mark[x - 1][y] && !flags[x - 1][y]){
            flags[x - 1][y] = true;
            Pair p = search(x - 1,y,w,h,stage,mark,flags);
            ret.a += p.a;
            ret.b += p.b;
        }
    }
    if(x < w - 1){
        if(mark[x][y] == mark[x + 1][y] && !flags[x + 1][y]){
            flags[x + 1][y] = true;
            Pair p = search(x + 1,y,w,h,stage,mark,flags);
            ret.a += p.a;
            ret.b += p.b;
        }
    }
    if(y > 0){
        if(mark[x][y] == mark[x][y - 1] && !flags[x][y - 1]){
            flags[x][y - 1] = true;
            Pair p = search(x,y - 1,w,h,stage,mark,flags);
            ret.a += p.a;
            ret.b += p.b;
        }
    }
    if(y < h - 1){
        if(mark[x][y] == mark[x][y + 1] && !flags[x][y + 1]){
            flags[x][y + 1] = true;
            Pair p = search(x,y + 1,w,h,stage,mark,flags);
            ret.a += p.a;
            ret.b += p.b;
        }
    }
    return ret;
}

int main() {
    int h,w;
    cin >> h >> w;
    vector<vector<char> > stage(w,vector<char>(h,'.'));
    vector<vector<bool> > mark(w,vector<bool>(h,false));
    vector<vector<bool> > flags(w,vector<bool>(h,false));
    for (int i = 0; i < h; ++i) {
        string s;
        cin >> s;
        const char* c = s.c_str();
        for(int j = 0;j < w;++j){
            stage[j][i] = c[j];
            mark[j][i] = ((i + j) % 2 == 0 && c[j] == '#') || ((i + j) % 2 == 1 && c[j] == '.');
        }
    }
    long total = 0;
    for (int i = 0; i < h; ++i) {
        for(int j = 0;j < w;++j){
            if(!flags[j][i] && stage[j][i] == '#') {
                Pair k = search(j, i, w, h,stage, mark, flags);
                total += k.a * (k.b - 1 - k.a);
            }
        }
    }
    cout << total << endl;
}

