int bfs(vector<string> &maze, vector<vector<bool> > &isVisited, int i, int j, int H, int W){
    if (isVisited[i][j]){
        return 0;
    }
    vector<int> dx(4);
    dx[0] = 1;
    dx[1] = 0;
    dx[2] = -1;
    dx[3] = 0;
    vector<int> dy(4);
    dy[0] = 0;
    dy[1] = 1;
    dy[2] = 0;
    dy[3] = -1;
    queue<pair<int,int> > que;
    que.push(pair<int,int> (i,j));
    int black = 0;
    int white = 0;
    if (maze[i][j] == '#') black++;
    if (maze[i][j] == '.') white++;
    isVisited[i][j] = true;
    while(que.size() != 0){
        pair<int,int> p = que.front();
        que.pop();
        rep(a,4){
            int nx = p.second + dx[a];
            int ny = p.first + dy[a];
            if (0 <= nx && nx < W && 0 <= ny && ny < H && maze[ny][nx] != maze[p.first][p.second] && !isVisited[ny][nx]){
                que.push(pair<int,int>(ny,nx));
                if (maze[ny][nx] == '#') black++;
                if (maze[ny][nx] == '.') white++;
                isVisited[ny][nx] = true;
            }
        }
    }
    int ans = black * white;
    return ans;
}
