#include <iostream>
#include <queue>
using namespace std;
#define MAX_N 400
#define P pair<int, int>
bool color[MAX_N][MAX_N];
bool used[MAX_N][MAX_N];
int H,W;
int dx[4] = {1,0,-1,0};
int dy[4] = {0,1,0,-1};

bool isin(int i, int j) {
    return i>=0 && i<H && j>=0 && j<W;
}

bool path(int i, int j, int d) {
    int nx = i + dx[d];
    int ny = j + dy[d];
    return (color[i][j] != color[nx][ny]);
}

long long solve() {
    long long ans = 0;
    for(int i=0; i<H; ++i) {
        for(int j=0; j<W; ++j) {
            used[i][j] = false;
        }
    }
    queue<P> q;
    for(int i=0; i<H; ++i) {
        for(int j=0; j<W; ++j) {
            if(used[i][j]) continue;
            long long b=0, w=0;
            used[i][j] = true;
            if(color[i][j]) ++b;
            else ++w;
            q.push(P(i,j));
            while(!q.empty()) {
                P cur = q.front(); q.pop();
                for(int d=0; d<4; ++d) {
                    int nx = cur.first + dx[d];
                    int ny = cur.second + dy[d];
                    if(isin(nx,ny) && path(cur.first,cur.second,d) && !used[nx][ny]) {
                        used[nx][ny] = true;
                        if(color[nx][ny]) ++b;
                        else ++w;
                        q.push(P(nx,ny));
                    }
                }
            }
            ans += b * w;
        }
    }
    return ans;
}

