            REP2(x,1,H+1){
                REP2(y,1,W+1){
                    if(dist[x][y]!=-1&&S[x][y]!=S[i][j]) cnt++;
                }
            }
            ans+=cnt;
        }
    }
    ans/=2;
    cout<<ans<<endl;


}

