                origin[i][j] = 0;
            }
            else
            {
                board[i][j] = 1;
                origin[i][j] = 1;
            }
            if ((i + j) % 2 == 0)
            {
                board[i][j] = -1 * board[i][j] + 1;
            }
        }
    }

    int counted[H][W] = {};
