    {
        for (int j = 0; j < W; j++)
        {
            if (!counted[i][j])
            {
                xqueue.push(i);
                yqueue.push(j);
                int bsum = 0;
                int wsum = 0;
                while (xqueue.size() * yqueue.size() > 0)
                {
                    int x = xqueue.front();
