int find(int si,int sj){
  int cnt=0;
  for(int i=0;i<h;i++)for(int j=0;j<w;j++)vis[i][j]=false;
  queue<pair<int,int>> que;
  vis[si][sj]=true;
  que.push({si,sj});
  while(!que.empty()){
    auto p=que.front();
    que.pop();
    int ti=p.first,tj=p.second;
    if(s[ti][tj]=='.'){cnt++;}
    int d[]={0,1,0,-1,0};
