template <typename X, typename T> auto vectors(X x, T a) { return vector<T>(x, a); }
template <typename X, typename Y, typename Z, typename... Zs> auto vectors(X x, Y y, Z z, Zs... zs) { auto cont = vectors(y, z, zs...); return vector<decltype(cont)>(x, cont); }

int solve(int h, int w, vector<string> const & s) {
    static const int dy[4] = { -1, 1, 0, 0 };
    static const int dx[4] = { 0, 0, 1, -1 };
    auto used = vectors(h, w, false);
    function<array<int, 2> (int, int)> go = [&](int y, int x) {
        used[y][x] = true;
        array<int, 2> k = {};
        k[s[y][x] == '#'] += 1;
        REP (i, 4) {
            int ny = y + dy[i];
            int nx = x + dx[i];
            if (0 <= ny and ny < h and 0 <= nx and nx < w) {
                if (s[ny][nx] != s[y][x] and not used[ny][nx]) {
                    auto k1 = go(ny, nx);
                    k[0] += k1[0];
                    k[1] += k1[1];
                }
            }
        }
        return k;
    };
    int answer = 0;
    REP (y, h) REP (x, w) if (not used[y][x]) {
        auto k = go(y, x);
        answer += k[0] * k[1];
    }
    return answer;
}

int main() {
    int h, w; cin >> h >> w;
    vector<string> s(h);
    REP (i, h) cin >> s[i];
    cout << solve(h, w, s) << endl;
    return 0;
}

