void solve(long long H, long long W, std::vector<std::string> S){
  ll d[4][2] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
  ll ans = 0;
  queue<pair<ll, ll>> q;
  for(ll i=0; i<H; i++) {
    for(ll j=0; j<W; j++) {
      if(S[i][j]=='#') {
	vector<vector<ll>> v(H, vector<ll>(W, 0));
	q.push(make_pair(i, j));
	while (!q.empty()) {
	  auto now = q.front();
	  q.pop();
	  for(ll k=0; k<4; k++) {
	    ll y = now.first+d[k][0];
	    ll x = now.second+d[k][1];
	    if(0<=x and x<W and 0<=y and y<H and v[y][x]==0 and
	       S[now.first][now.second]!=S[y][x]) {
	      if(S[y][x]=='.') ans++;
	      v[y][x] = 1;
	      q.push(make_pair(y, x));
	    }
	  }
	}
      }
    }
  }
  std::cout << ans << std::endl;
}

int main(){
  long long H;
  scanf("%lld",&H);
  long long W;
  scanf("%lld",&W);
  std::vector<std::string> S(H);
  for(int i = 0 ; i < H ; i++){
    std::cin >> S[i];
  }
  solve(H, W, std::move(S));
  return 0;
}

