using namespace atcoder;

int H, W;

struct UnionFind {
	vector<int> par; // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2
	map<int, lli> b;
	map<int, lli> w;
	UnionFind(int N) : par(N) { //最初は全てが根であるとして初期化
		for (int i = 0; i < N; i++) par[i] = i;
	}

	int root(int x) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
		if (par[x] == x) return x;
		return par[x] = root(par[x]);
	}

	void unite(int x, int y) { // xとyの木を併合
		int rx = root(x); //xの根をrx
		int ry = root(y); //yの根をry
		if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
		par[rx] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
	}

	bool same(int x, int y) { // 2つのデータx, yが属する木が同じならtrueを返す
		int rx = root(x);
		int ry = root(y);
		return rx == ry;
	}

	void construct(vector<string>& v, int y, int x, int parent) {
		if (par[y * W + x] != y * W + x && par[y * W + x] == parent)
			return;
		par[y * W + x] = parent;
		if (y < H - 1) {
			if (v[y + 1][x] != v[y][x]) {
				construct(v, y + 1, x, parent);
			}
		}
		if (x < W - 1) {
			if (v[y][x + 1] != v[y][x]) {
				construct(v, y, x + 1, parent);
			}
		}

	}

	void count(vector<string>& v) {
		for (int i = 0; i < H; i++) {
			for (int j = 0; j < W; j++) {
				if (v[i][j] == '#') {
					b[par[i * W + j]]++;
				}
				else {
					w[par[i * W + j]]++;
				}
			}
		}
	}
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin >> H >> W;
	vector<string> v(H);
	vector<int> black, white;
	for (int i = 0; i < H; i++) {
		cin >> v[i];
	}
	UnionFind uni(H*W);
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (uni.par[i * W + j] == i * W + j) {
				uni.construct(v, i, j, i * W + j);
			}
		}
	}
	uni.count(v);
	lli ans = 0;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			ans += uni.b[i * W + j] * uni.w[i * W + j];
		}
	}
	cout << ans << endl;
	return 0;
}

