int main() {
  int h, w;
  cin >> h >> w;
  VEC<string> s(h);
  REP(i, 0, h) cin >> s[i];
  queue<int> nh;
  queue<int> nw;
  LL answer = 0;
  auto visit = MATINIT(bool, h, w, 0);
  REP(i, 0, h) {
    REP(j, 0, w) {
      int blcnt=0;
      if (s[i][j] == '.') continue;
      nh.push(i);
      nw.push(j);
      LL ans = 0;
      while (!nh.empty() && !nw.empty()) {
        int ch = nh.front();
        int cw = nw.front();
        nh.pop();
        nw.pop();
        char cc = s[ch][cw];
        if (visit[ch][cw]) continue;
        visit[ch][cw] = 1;
        if (cc == '.') {
          ++ans;
          // DUMP(i,j,"to",ch,cw);
        }else{
          ++blcnt;
        }
        if (ch + 1 < h && cc != s[ch + 1][cw]) {
          nh.push(ch + 1);
          nw.push(cw);
        }
        if (ch - 1 >= 0 && cc != s[ch - 1][cw]) {
          nh.push(ch - 1);
          nw.push(cw);
        }
        if (cw + 1 < w && cc != s[ch][cw + 1]) {
          nh.push(ch);
          nw.push(cw + 1);
        }
        if (cw - 1 >= 0 && cc != s[ch][cw - 1]) {
          nh.push(ch);
          nw.push(cw - 1);
        }
      }
      answer += blcnt*ans;
    }
  }
  cout << answer;

  return 0;
}

