    REP(h, H) REP(w, W)
    {
        if (h > 0 and (S[h][w] != S[h - 1][w])) uf.unite(h * W + w, (h - 1) * W + w);
        if (w > 0 and (S[h][w] != S[h][w - 1])) uf.unite(h * W + w, h * W + w - 1);
    }
    map<int, int> ma[2];
    REP(h, H) REP(w, W) ma[S[h][w] == '#'][uf.find(h * W + w)]++;

    lint ans = 0;
    REP(i, H * W) ans += (lint)ma[0][i] * ma[1][i];
    cout << ans << endl;
}

