constexpr int kInvalid = 9;

struct Point {
  int x;
  int y;
};

typedef std::vector<std::pair<Point, std::vector<Point>>> Tree;

int main() {
  int table[402][402] = {};
  int H, W; std::cin >> H >> W;
  for (int r = 0; r < H; ++r) {
    std::string s; std::cin >> s;
    for (int c = 0; c < W; ++c) {
      if (s[c] == '#') table[r+1][c+1] = 1;
    }
  }

  for (int c = 0; c <= W + 1; ++c) {
    table[0][c] = kInvalid;
    table[H+1][c] = kInvalid;
  }
  for (int r = 0; r <= H + 1; ++r) {
    table[r][0] = kInvalid;
    table[r][W+1] = kInvalid;
  }

#if DEBUG
  for (int r = 1; r <= H; ++r) {
    for (int c = 1; c <= W; ++c) {
      std::cout << table[r][c];
    }
    std::cout << std::endl;
  }
#endif

  Tree tree;
  for (int r = 1; r <= H; ++r) {
    for (int c = 1; c <= W; ++c) {
      if (table[r][c] == 1) {
        std::vector<Point> ps;
        if (table[r-1][c] == 0) ps.push_back({r-1, c});
        if (table[r][c-1] == 0) ps.push_back({r, c-1});
        if (table[r][c+1] == 0) ps.push_back({r, c+1});
        if (table[r+1][c] == 0) ps.push_back({r+1, c});

        if (ps.size() > 0) {
          Point p = {r, c};
          tree.push_back(std::make_pair(p, ps));
        }
      }
    }
  }

#if DEBUG
  for (auto t : tree) {
    auto p = t.first;
    auto ps = t.second;
    std::cout << "(" << p.x << "," << p.y << ") -> {";
    for (auto a : ps) {
      std::cout << "(" << a.x << "," << a.y << "), ";
    }
    std::cout << "}" << std::endl;
  }
#endif

  int cnt = 0;
  bool checked[402][402];
  for (size_t i = 0; i < tree.size(); ++i) {
    const auto& t1b = tree[i].first;  // t1 black cell
    if (checked[t1b.x][t1b.y]) continue;

    std::queue<size_t> que;
    que.push(i);
    checked[t1b.x][t1b.y] = true;

    int cnt_b = 0, cnt_w = 0;
    while(!que.empty()) {
      int index = que.front();
      que.pop();

      const auto& t1 = tree[index];
      ++cnt_b;
      for (const auto& p : t1.second) {
        if (checked[p.x][p.y]) continue;
        ++cnt_w;
        checked[p.x][p.y] = true;
      }

      for (size_t j = i + 1; j < tree.size(); ++j) {
        const auto& t2 = tree[j];
        const auto& t2b = t2.first;  // t2 black cell
        if (checked[t2b.x][t2b.y]) continue;

        bool connectable = false;
        for (const auto& p1 : t1.second) {
          for (const auto& p2 : t2.second) {
            if (p1.x == p2.x && p1.y == p2.y) {
              connectable = true;
            }
          }
          if (connectable) break;
        }

        if (connectable) {
          que.push(j);
          checked[t2b.x][t2b.y] = true;
        }
      }
    }
    cnt += cnt_b * cnt_w;
#if DEBUG
    std::cout << cnt_b << ", " << cnt_w << std::endl;
#endif
  }
  std::cout << cnt << std::endl;
}

