void dfs(int i, int j, char prev){
    //cout << i << " " << j << " "<< prev <<endl;
    visited[i][j] = true;

    if(prev!='e'){
        if(prev != masu[i][j]){
            // good

            if(masu[i][j] == '.'){
                used.insert(make_pair(i,j));
                cnt++;
            }

            if(j+1<W && !visited[i][j+1]){
                dfs(i, j+1, masu[i][j]);
            }
            if(j-1>=0 && !visited[i][j-1]){
                dfs(i, j-1, masu[i][j]);
            }
            if(i+1<H && !visited[i+1][j]){
                dfs(i+1, j, masu[i][j]);
            }
            if(i-1>=0 && !visited[i-1][j]){
                dfs(i-1, j, masu[i][j]);
            }
        }
    } else {
        if(j+1<W && !visited[i][j+1]){
            dfs(i, j+1, masu[i][j]);
        }
        if(j-1>=0 && !visited[i][j-1]){
            dfs(i, j-1, masu[i][j]);
        }
        if(i+1<H && !visited[i+1][j]){
            dfs(i+1, j, masu[i][j]);
        }
        if(i-1>=0 && !visited[i-1][j]){
            dfs(i-1, j, masu[i][j]);
        }
    }
    visited[i][j] = false;

    return ;
}

