using pos = tuple<int,int,int>;
int visited[500][500] = {};
int dx[4] = {1,-1,0,0};
int dy[4] = {0,0,1,-1};
int H,W;

char G[500][500];

void dfs(int x, int y, char c, int cnt){
    queue<pos> Q;
    Q.push(make_tuple(x,y,c));
    visited[x][y] = cnt;
    while(!Q.empty()){
        auto cur = Q.front();
        Q.pop();
        char pc = get<2>(cur);
        for(int k=0;k<4;k++){
            int nx = get<0>(cur) + dx[k];
            int ny = get<1>(cur) + dy[k];

            if(nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
            if(visited[nx][ny] != 0) continue;
            if(G[nx][ny] == pc) continue;

            visited[nx][ny] = cnt;
            Q.push(make_tuple(nx,ny, G[nx][ny]));
        }
    }
}

