    int y;
};

action act[4] = {{1,0},{0,1},{-1,0},{0,-1}};

int root(int i, int j){
    if(d[i][j].up == i*W + j){
        return d[i][j].up;
    }else{
        int x = d[i][j].up;
        d[i][j].up = root(x/W, x%W);
        return root(x/W, x%W);
    }
}

void unite(int p, int q, int r, int s){
    d[p][q].up = r*W + s;
}

int main(void) {
    // insert code here...
