#define MAX 400

int H, W;
string S[MAX];

int visit[MAX][MAX];
map<int, long long> mp;

int diri[4] = { -1, 1, 0, 0 };
int dirj[4] = { 0, 0, -1, 1 };

long long dfs( int i, int j, int cnt )
{
	if( visit[i][j] == cnt ) {
		return -1;
	}
	visit[i][j] = cnt;
	long long res = 0;
	for( int k = 0; k < 4; k++ ) {
		int ni = i + diri[k];
		int nj = j + dirj[k];
		if( ni < 0 || H -1 < ni || nj < 0 || W - 1 < nj ) {
			continue;
		}
		if( S[ni][nj] == S[i][j] ) {
			continue;
		}
		long long ret = dfs( ni, nj, cnt );
		if( ret >= 0 ) {
			res += ret;
			if( S[ni][nj] == '.' ) {
				res++;
			}
		}
	}
	mp[cnt] = res;
	return res;
}

int main() {
	cin >> H >> W;
	for( int i = 0; i < H; i++ ) {
		cin >> S[i];
	}

	long long ans = 0;
	int cnt = 1;
	for( int i = 0; i < H; i++ ) {
		for( int j = 0; j < W; j++ ) {
			if( mp[ visit[i][j] ] == 0 ) {
				if( S[i][j] == '.' ) {
					continue;
				}
				long long ret = dfs( i, j, cnt );
				if( ret >= 0 ) {
					ans += ret;
				}
				cnt++;
			}
			else if( S[i][j] == '#' ) {
				ans += mp[ visit[i][j] ];
			}
		}
	}

	cout << ans << endl;

	return 0;
}

