class UF
{
private:
    int         num;
    vector<int> par;
    vector<int> siz;
public:
    vector<int> val0;
    vector<int> val1;
public:
    UF(int n): num(n) {
        par.resize(n);
        siz.resize(n);
        val0.resize(n);
        val1.resize(n);
        int i;
        for(i=0; i<n; i++) {
            par[i]=i; siz[i]=1;
            val0[i]=val1[i]=0;
        }
    }

    int find(int x) {
        if(x==par[x]) return x;
        return par[x] = find(par[x]);
    }

    void unite(int x, int y) {
        x=find(x);
        y=find(y);
        if(x==y) return;
        if(siz[x]<siz[y]) {
            par[x]=y;
            siz[y]=siz[x]+siz[y];
            val0[y]=val0[x]+val0[y];
            val1[y]=val1[x]+val1[y];
        }
        else {
            par[y]=x;
            siz[x]=siz[x]+siz[y];
            val0[x]=val0[x]+val0[y];
            val1[x]=val1[x]+val1[y];
        }
    }

    bool same(int x, int y) {
        return find(x)==find(y);
    }

    int size(int x) {
        return siz[find(x)];
    }

    int ngroup( ll& ans ) {
        int count=0;
        int i;
        for(i=0; i<num; i++) {
            if(par[i]==i) {
                count++;
                ans += ((ll)val0[i]*val1[i]);
            }
        }
        return count;
    }
};

