  // std::cout << "row:"<<row<< " col:"<<col <<
  // " group_num1:"<<group_num1<<
  // " group_num2:"<<group_num2<<
  // '\n';

  if(col != WW-1) {if (S[row][col] != S[row][col+1] && count_mat[row][col+1]==0) {
    search(row, col+1, count_mat, group_num1, group_num2, S, HH, WW);
  }}

  if(row != HH-1) {if ( S[row][col] != S[row+1][col] && count_mat[row+1][col]==0) {
    search(row+1, col, count_mat, group_num1, group_num2, S, HH, WW);
  }}
  if(col != 0){if ( S[row][col] != S[row][col-1] && count_mat[row][col-1]==0) {
    search(row, col-1, count_mat, group_num1, group_num2, S, HH, WW);
  }}
  if(row != 0){if (S[row][col] != S[row-1][col] && count_mat[row-1][col]==0) {
    search(row-1, col, count_mat, group_num1, group_num2, S, HH, WW);
  }}
}

