using namespace std;
const int MAXN=2e5+10;
const int MAX=410;
const int dx[4]={0,0,1,-1};
const int dy[4]={1,-1,0,0};
int fa[MAXN],sum[MAXN],s[MAXN];
bool w[MAXN];
char a[MAX][MAX];
int n,m;
ll ans;
int getfather(int x)
{
	if (fa[x]==x) return x;
	fa[x]=getfather(fa[x]);
	return fa[x];
}
void adit(int x,int y)
{
	x=getfather(x);
	y=getfather(y);
	if (x!=y) {
		fa[x]=y; sum[y]+=sum[x]; s[y]+=s[x];
	}
}
void solve(int x)
{
	x=getfather(x);
	if (!w[x]) {
		w[x]=1; ans+=(ll)(sum[x]-s[x])*(ll)s[x];
	}
}
int main()
{
	scanf("%d%d",&n,&m);
	for (int i=1;i<=n;i++) {
		scanf("%s",a[i]+1);
	}
