	for (int i=1;i<=n;i++) {
		for (int j=1;j<=m;j++)
		 if (a[i][j]=='#') s[(i-1)*m+j]=1;
	}
	for (int i=1;i<=n;i++)
	{
		for (int j=1;j<=m;j++) {
			for (int k=0;k<4;k++) {
				int x=i+dx[k];
