  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (vst[i][j] == 0) {
        dot = hsh = 0;
        dfs(i, j);
        ans += (dot * hsh);
      }
    }
  }
  cout << ans << '\n';
  return 0;
}

