vector<string> m;
int H, W;


ll dfs(int x, int y, char c, int d) {
	if (c == '#')d++;
	b[x][y] = true;
	ll tmp = d;

	if (x != 0) {
		if (b[x - 1][y] != true && m[x - 1][y] != c) {
			tmp = max(dfs(x - 1, y, m[x - 1][y], d), tmp);
		}
	}
	if (x != H - 1) {
		if (b[x + 1][y] != true && m[x + 1][y] != c) {
			tmp = max(dfs(x + 1, y, m[x + 1][y], d), tmp);
		}
	}
	if (y != 0) {
		if (b[x][y - 1] != true && m[x][y - 1] != c) {
			tmp = max(dfs(x, y - 1, m[x][y - 1], d), tmp);
		}
	}
	if(y != W-1){
		if (b[x][y + 1] != true && m[x][y + 1] != c) {
			tmp = max(dfs(x, y + 1, m[x][y + 1], d), tmp);
		}
	}
	if (c == '#')a[x][y] = max(tmp, a[x][y]);
	return tmp;
}
int main() {
	cin >> H >> W;
	m = vector<string>(H);
	for (int i = 0; i < H; i++) {
		cin >> m[i];
	}
	a = vector <vector<ll> >(H, vector<ll>(W, 0));
	b = vector <vector<bool> >(H, vector<bool>(W, false));
	for (int i = 0; i < H; i++)for (int j = 0; j < W; j++) {
		if (m[i][j] == '#')dfs(i, j, '#', 0);
	}
	ll ans = 0;
	for (int i = 0; i < H; i++)for (int j = 0; j < W; j++) {
		ll tmp = 0;
		if (m[i][j] == '.') {
			if (i != 0) {
				if (m[i - 1][j] == '#') tmp = max(tmp, a[i - 1][j]);
			}
			if (i != H - 1) {
				if (m[i + 1][j] == '#') tmp = max(tmp, a[i + 1][j]);
			}
			if (j != 0) {
				if (m[i][j - 1] == '#') tmp = max(tmp, a[i][j - 1]);
			}
			if (j != W - 1) {
				if (m[i][j + 1] == '#') tmp = max(tmp, a[i][j + 1]);
			}
			ans += tmp;
		}
	}
	cout << ans << endl;
	return 0;
}

