char ch[MAX_N];
int visited[MAX_N][MAX_N];

void input(){
   scanf("%d%d", &H, &W);
   for(int i = 0; i < H; i++){
      scanf("%s", ch);
      for(int j = 0; j < W; j++){
         clr[i][j] = ch[j];
      }
   }
}

void dfs(int x, int y){
   if(x < H-1 && visited[x+1][y] == 0 && clr[x][y] != clr[x+1][y]){
      visited[x+1][y] = 1;
      dfs(x+1, y);
   }
   if(x > 0 && visited[x-1][y] == 0 && clr[x][y] != clr[x-1][y]){
      visited[x-1][y] = 1;
      dfs(x-1, y);
   }
   if(y < W-1 && visited[x][y+1] == 0 && clr[x][y] != clr[x][y+1]){
      visited[x][y+1] = 1;
      dfs(x, y+1);
   }
   if(y > 0 && visited[x][y-1] == 0 && clr[x][y] != clr[x][y-1]){
      visited[x][y-1] = 1;
      dfs(x, y-1);
   }
}

int cntB(){
   int cnt = 0;
   for(int i = 0; i < H; i++){
      for(int j = 0; j < W; j++){
         if(visited[i][j] == 1 && clr[i][j] == '#'){
            cnt++;
         }
      }
   }
   return cnt;
}

int cntC(){
   int cnt = 0;
   for(int i = 0; i < H; i++){
      for(int j = 0; j < W; j++){
         if(visited[i][j] == 1 && clr[i][j] != '#'){
            cnt++;
         }
      }
   }
   return cnt;
}

void clean(){
   for(int i = 0; i < H; i++){
      for(int j = 0; j < W; j++){
         if(visited[i][j] == 1)
            visited[i][j] = -1;
      }
   }
}

int main(){
   input();
   for(int i = 0; i < H; i++){
      for(int j = 0; j < W; j++){
         if(visited[i][j] != -1){
            visited[i][j] = 1;
            dfs(i, j);
         }
         ans += cntB()*cntC();
         clean();
      }
   }
   cout << ans << endl;
}

