ll input[404][404];

const ll MAX_N = 404*404;

struct UnionFind{
    int N;
    int par[MAX_N];

    UnionFind(int N): N(N){
        for (int i=0;i<N;i++){
            par[i] = i;
        }
    }

    int root(int x){
        if(par[x] == x) return x;
        int rx = root(par[x]);
        par[x] = rx;
        return rx;
    }

    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if(rx==ry) return;
        par[rx] = ry;
    }

    bool find(int x, int y){
        return root(x) == root(y);
    }
};

int main(){
	ll H, W;
	cin >> H >> W;
	REP(i, H){
		string S;
		cin >> S;
		REP(j, W){
			input[i][j] = (S[j]=='#'?1:0);
		}
	}

	ll N = H*W;
	UnionFind uf(N);
	REP(i, H){
		REP(j, W-1){
			ll hidari = W*i+j;
			ll migi = W*i+j+1;
			if(input[i][j]!=input[i][j+1]){
				uf.unite(hidari, migi);
			}
		}
	}
	REP(i, H-1){
		REP(j, W){
			ll ue = W*i+j;
			ll shita = W*i+j+W;
			if(input[i][j]!=input[i+1][j]){
				uf.unite(ue, shita);
			}
		}
	}

	ll res = 0;
	//REP(i, N) uf.root(i);
	vector<ll> white(N, 0), black(N, 0);
	REP(i, N){
		if(input[i/W][i%W]==1){
			black[uf.root(i)]++;
		}else{
			white[uf.root(i)]++;
		}
	}
	//vprint(black);
	//vprint(white);
	REP(i, N) res += black[i]*white[i];
	cout << res << endl;
    return 0;
}

