    for(int i=0; i<H; i++){
      for(int j=0; j<W; j++){
          bool b = col(map[i][j]);
          if(ald[i][j] == false){

          ll h = 0;
          ll g = 0;
          dfs(h,g,H,W,i,j,map,ald);

          count += h*g;
          }
      }     
    }

    cout << count;
}

