int bfs(int sx, int sy)
{
  queue<int>qx;
  queue<int>qy;
  qx.push(sx);
  qy.push(sy);
  int cnt = 0;
  while (!qx.empty())
  {
    int ux = qx.front();
    qx.pop();
    int uy = qy.front();
    qy.pop();
    visited[ux][uy] = true;
    if (ar[ux][uy] == '#')
