struct UF
{
	UF *parent;
	long rank, b;
	UF() :parent(nullptr), rank(1), b(0) {}
	UF &Find() {
		if (parent == nullptr)
			return *this;
		return *(parent = &parent->Find());
	}
	int Union(UF &n) {
		auto &r = Find(), &nr = n.Find();
		if (&r == &nr) return 0;
		if (r.rank < nr.rank) r.parent = &nr, nr.rank += r.rank, nr.b += r.b;
		else nr.parent = &r, r.rank += nr.rank, r.b += nr.b;
		return -1;
	}
} u[444][444];
int main() {
	int h, w;
	cin >> h >> w;
	string s[444];
	for (int i = 0; i < h; i++) {
		cin >> s[i];
