			if (s[i][j] == '#')
				u[i][j].b = 1;
	}
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			if (i&&s[i][j] != s[i - 1][j])
				u[i][j].Union(u[i - 1][j]);
			if (j&&s[i][j] != s[i][j - 1])
				u[i][j].Union(u[i][j - 1]);
		}
	}
