  for(ll i=0;i<h;i++)cin>>s[i];
  bool used[h][w];
  for(ll i=0;i<h;i++)for(ll j=0;j<w;j++)used[i][j]=false;
  ll ans=0;
  ll dx[4]={-1,1,0,0};
  ll dy[4]={0,0,-1,1};
