long long nh=0,nd=0;

bool check(int i ,int j)
{
    if(i<1 || i>n || j<1 || j>m)
        return false;
    if(vis[i][j]==1)
        return false;
    return true;
}

int dfs(int i,int j)
{
    vis[i][j]=1;
    if(vec[i][j]=='#')
    {
        nh++;
        if(check(i+1,j))
        {
            if(vec[i+1][j]=='.')
                dfs(i+1,j);
        }
        if(check(i-1,j))
        {
            if(vec[i-1][j]=='.')
                dfs(i-1,j);
        }
        if(check(i,j+1))
        {
            if(vec[i][j+1]=='.')
                dfs(i,j+1);
        }
        if(check(i,j-1))
        {
            if(vec[i][j-1]=='.')
                dfs(i,j-1);
        }
    }
    else
    {
        nd++;
        if(check(i+1,j))
        {
            if(vec[i+1][j]=='#')
                dfs(i+1,j);
        }
        if(check(i-1,j))
        {
            if(vec[i-1][j]=='#')
                dfs(i-1,j);
        }
        if(check(i,j+1))
        {
            if(vec[i][j+1]=='#')
                dfs(i,j+1);
        }
        if(check(i,j-1))
        {
            if(vec[i][j-1]=='#')
                dfs(i,j-1);
        }
    }
}

