int id(int i, int j){
    return i * w + j;
}
P idinv(int id){
    return P(id / w, id % w);
}


vector<string> vs;
bool seen[MAX];
int bl, wh;

void dfs(int s){
    seen[s] = true;
    if(vs[idinv(s).fi][idinv(s).se] == '.') wh++; else bl++;
    for(int& t : G[s]){
        if(seen[t]) continue;
        dfs(t);
    }
}

int main(){
    cin >> h >> w;
    rep(i, h){
        string s; cin >> s; vs.push_back(s);
        rep(j, w){
            if(j != 0 && s[j] != s[j-1]){
                G[id(i, j)].push_back(id(i, j-1));
                G[id(i, j-1)].push_back(id(i, j));
            }
            if(i != 0 && s[j] != vs[i-1][j]){
                G[id(i, j)].push_back(id(i-1, j));
                G[id(i-1, j)].push_back(id(i, j));
            }
        }
    }
    lint ans = 0;
    rep(i, h*w){
        if(seen[i]) continue;
        bl = 0; wh = 0;
        dfs(i);
        ans += bl * wh;
    }
