struct UnionFind {
    vector< int > data;

    UnionFind(int sz) {
        data.assign(sz, -1);
    }

    bool unite(int x, int y) {
        x = find(x), y = find(y);
        if(x == y) return (false);
        if(data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return (true);
    }

    int find(int k) {
        if(data[k] < 0) return (k);
        return (data[k] = find(data[k]));
    }

    int size(int k) {
        return (-data[find(k)]);
    }
};




int main() {
    int h, w;
    cin >> h >> w;
    vector<vector<int>> grid(h, vector<int>(w, 0));
    UnionFind uf(h * w);
    rep (i, h) {
        string s;
        cin >> s;
        rep (j, w) {
            if (s[j] == '#') {
                grid[i][j] = 1;
            }
        }
    }
    vector<int> dx = {1, -1, 0, 0};
    vector<int> dy = {0, 0, -1, 1};
    rep (y, h) {
        rep (x, w) {
            rep (k, 4) {
                int newy = y + dy[k];
                int newx = x + dx[k];
                if (newy < 0 || h <= newy) {
                    continue;
                }
                if (newx < 0 || w <= newx) {
                    continue;
                }
                if (grid[y][x] + grid[newy][newx] == 1) {
                    uf.unite(y * w + x, newy * w + newx);
                }
            }
        }
    }
    int ans = 0;
    vector<int> children_b(h * w, 0);
    vector<int> children_w(h * w, 0);
    rep (i, h * w) {
        int y = i / w;
        int x = i % w;
        if (grid[y][x] == 1) {
            children_b[uf.find(i)]++;
        } else {
            children_w[uf.find(i)]++;
        }

    }
    rep (i, h * w) {
        cout << children_w[i] << " " << children_b[i] << endl;
        ans += children_w[i] * children_b[i];
    }
    cout << ans << endl;
}

