using namespace std;

int x_dir[] = {-1, 1, 0, 0};
int y_dir[] = {0, 0, -1, 1};

int H, W;
typedef long long ll;

int dfs(const string *S, vector<vector<int>> &dist, int h, int w, int c, int& count)
{
    int new_h, new_w;
    for (int i = 0; i < 4; ++i)
    {
        new_h = h + y_dir[i];
        new_w = w + x_dir[i];
        if (new_h < 0 || new_h >= H || new_w < 0 || new_w >= W)
            continue;
        if (S[h][w] == '#')
        {
            if (dist[new_h][new_w] == 0 && S[new_h][new_w] == '.')
            {
                dist[h][w] = dist[new_h][new_w] = c;
                dfs(S, dist, new_h, new_w, c, ++count);
            }
        }
        else
        {
            if (dist[new_h][new_w] == 0 && S[new_h][new_w] == '#')
            {
                dist[h][w] = dist[new_h][new_w] = c;
                dfs(S, dist, new_h, new_w, c, ++count);
            }
        }
    }
    return count;
}

int main()
{
    cin >> H >> W;
    vector<vector<int>> dist(H, vector<int>(W));
    string S[H];
    for (int i = 0; i < H; ++i)
    {
        cin >> S[i];
    }

    int c = 1, count;
    for (int i = 0; i < H; ++i)
    {
        for (int j = 0; j < W; ++j)
        {
            count = 1;
            dfs(S, dist, i, j, c, count);
            if (count > 1)
                ++c;
        }
    }

    ll brack, white, ans = 0;
    for (int t = 1; t < c; ++t)
    {
        brack = white = 0;
        for (int h = 0; h < H; ++h)
        {
            for (int w = 0; w < W; ++w)
            {
                if (t == dist[h][w])
                {
                    if (S[h][w] == '#')
                        ++brack;
                    else
                        ++white;
                }
            }
        }
        ans += brack * white;
    }
    cout << ans << endl;
}

