using namespace std;

long long bfs(int sx, int sy, std::vector<std::vector<char>> &grid,
              std::vector<std::vector<bool>> &is_visited) {
  int h = grid.size(), w = grid[0].size();

  int dx[] = {-1, 0, 0, 1};
  int dy[] = {0, -1, 1, 0};

  std::queue<std::pair<int, int>> que;
  que.push(std::make_pair(sx, sy));

  is_visited[sy][sx] = true;

  long long cnt_w = 0, cnt_b = 0;

  while (!que.empty()) {
    int cur_x = que.front().first;
    int cur_y = que.front().second;

    if (grid[cur_y][cur_x] == '#') {
      cnt_b++;
    } else {
      cnt_w++;
    }
    que.pop();

    for (int i = 0; i < 4; i++) {
      int nx = cur_x + dx[i];
      int ny = cur_y + dy[i];
      if (nx < 0 || ny < 0 || nx >= w || ny >= h) {
        continue;
      }
      if (is_visited[ny][nx]) {
        continue;
      }
      if (grid[cur_y][cur_x] == grid[ny][nx]) {
        continue;
      }
      is_visited[ny][nx] = true;
      que.push(std::make_pair(nx, ny));
    }
  }
  return cnt_w * cnt_b;
}

int main() {
  std::cin.tie(0);
  std::ios_base::sync_with_stdio(false);

  int h, w;
  cin >> h >> w;

  vector<vector<char>> g(h, vector<char>(w));

  for (int i = 0; i < h; i++) {
    string s;
    cin >> s;
    for (int j = 0; j < w; j++) {
      g[i][j] = s[j];
    }
  }

  vector<vector<bool>> is_visited(h, vector<bool>(w, false));

  long long ans = 0;
  for (int y = 0; y < h; y++) {
    for (int x = 0; x < w; x++) {
      if (is_visited[y][x]) {
        continue;
      }
      ans += bfs(x, y, g, is_visited);
    }
  }

  cout << ans << "\n";

  return 0;
}

