bool rangeCheck(int y, int x, int h, int w) {
  if (y < 0 || x < 0 || y >= h || x >= w) {
    return false;
  } else {
    return true;
  }
}

void outputDone(int h, int w, vector<vector<int>> a) {
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      printf("%3d", a[i][j]);
