int par[400 * 400];	    // 親を指す
int b[400 * 400];	    // 黒の数
int w[400 * 400];	    // 白の数

int root(int x) {
    if(par[x] == x)     return x;
    else                return par[x] = root(par[x]);
}

bool same(int x, int y) {
    return root(x) == root(y);
}

void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if(x == y)  return;
    par[x] = y;
}


signed main(){
