	   REP(j, 0, W) {
	       par[i*W + j] = i * W + j;
	   }
	}

	REP(i, 0, H) {
		REP(j, 0, W) {
			if(i < H - 1 && S[i][j] != S[i+1][j])    unite(i * W + j, (i+1) * W + j);
			if(j < W - 1 && S[i][j] != S[i][j+1])	unite(i * W + j, i * W + j + 1);
		}
	}
	REP(i, 0, H) {
