    cerr << uf.find(i) << " ";
  }
  cerr << endl;

  vector<int> black(h*w), white(h*w);
  rep(i, h) rep(j, w) {
    if (s[i][j] == '#') black[uf.find(i*w+j)]++;
    else white[uf.find(i*w+j)]++;
  }

  ll ans = 0;
  rep(i, h*w) {
    ans += black[i] * white[i];
  }
  cout << ans << endl;
}

