using namespace std;
int H, W;
vector<string> S;
vector<vector<bool>> B;
long long black = 0, white = 0;
bool posok(int i, int j) {
    return 0 <= i && i < H && 0 <= j && j < W;
}
void recur(int i, int j, int c)
{
    (c ? black : white) += 1;
    B[i][j] = true;
    if (posok(i-1, j) && S[i-1][j] == ".#"[c] && !B[i-1][j]) recur(i-1, j, !c);
    if (posok(i+1, j) && S[i+1][j] == ".#"[c] && !B[i+1][j]) recur(i+1, j, !c);
    if (posok(i, j-1) && S[i][j-1] == ".#"[c] && !B[i][j-1]) recur(i, j-1, !c);
    if (posok(i, j+1) && S[i][j+1] == ".#"[c] && !B[i][j+1]) recur(i, j+1, !c);
}
int main()
{
    cin >> H >> W;
    S = vector<string>(H); for (auto& s : S) cin >> s;
    B = vector<vector<bool>>(H, vector<bool>(W));
    long long ans = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (S[i][j] == '#' && !B[i][j]) {
                black = 0, white = 0;
                recur(i, j, 0);
                ans += black * white;
            }
        }
    }
    cout << ans << endl;
    return 0;
}

