class unionfind {
	vector<int> par;
	vector<P> sz;
public:
	unionfind(int n, vector<char> a) {
		par = vector<int>(n);
		sz = vector<P>(n);
		for (int i = 0; i < n; i++) {
			par[i] = i;
			if (a[i] == '#') sz[i] = { 1,0 };
			else sz[i] = { 0,1 };
		}
	}
	int find(int x) {
		if (par[x] == x) return x;
		else return par[x] = find(par[x]);
	}
	int si(int x) {
		return sz[find(x)].first * sz[find(x)].second;
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (sz[x] < sz[y]) {
			par[x] = y;
			sz[y].first += sz[x].first;
			sz[y].second += sz[x].second;
		}
		else {
			par[y] = x;
			sz[x].first += sz[y].first;
			sz[x].second += sz[y].second;
		}
	}
};

