inline bool in_bounds(int i, int j) {
    return i >= 0 && i < h && j < w && j >= 0;
}

inline bool in_bounds(pii v) {
    return in_bounds(v.first, v.second);
}

char used[N][N];

void dfs(pii v, int &cntb, int &cntw) {
    used[v.first][v.second] = 1;
    mat[v.first][v.second] == '#' ? ++cntb : ++cntw;

    fori (dir, di.size()) {
        pii to = {v.first + di[dir], v.second + dj[dir]};
        if (in_bounds(to) && !used[to.first][to.second] && mat[to.first][to.second] != mat[v.first][v.second])
            dfs(to, cntb, cntw);
    }
}

void smain() {

    cin >> h >> w;
    fori (i, h) cin >> mat[i];

    int ans = 0;
    fori (i, h) fori (j, w) if (!used[i][j]) {
        int cntb = 0, cntw = 0;
        dfs({i, j}, cntb, cntw);
        ans += cntb * cntw;
    }
    cout << ans;
}

