const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};

string G[405];
bool seen[405][405];
bool seen2[405][405];
int H, W, cnt_w, cnt_b;
ll ans = 0;

void dfs(int h, int w) {
    seen[h][w] = true;
    if (G[h][w] == '#') seen2[h][w] = true;

    for (int dir = 0; dir < 4; ++dir) {
        int nh = h + dx[dir];
        int nw = w + dy[dir];

        if (nh < 0 || nh >= H || nw < 0 || nw >= W) continue;
        if (G[nh][nw] == G[h][w]) continue;

        if (seen[nh][nw]) continue;

        if (G[nh][nw] == '.') cnt_w++;
        else cnt_b++;
        dfs(nh, nw);
    }

    return;
}

int main() {
