    for (int h = 0; h < H; h++) cin >> G[h];

    for (int h = 0; h < H; h++) {
        for (int w = 0; w < W; w++) {
            if (G[h][w] == '#' && !seen2[h][w]) {
                cnt_b = 1;
                cnt_w = 0;
                memset(seen, 0, sizeof(seen));
                dfs(h, w);
                ans += cnt_b * cnt_w;
            }
        }
    }
    cout << ans << endl;
}

