    ll index = W * i + j;
    if (i != 0 and S[i][j] != S[i - 1][j]) {
      uf.unite(index, W * (i - 1) + j);
    }
    if (j != 0 and S[i][j] != S[i][j - 1]) {
      uf.unite(index, W * i + (j - 1));
    }
    if (i != H - 1 and S[i][j] != S[i + 1][j]) {
      uf.unite(index, W * (i + 1) + j);
    }
    if (j != W - 1 and S[i][j] != S[i][j + 1]) {
