    REP(y, H) REP(x, W) {
        parents.insert(uf.root(y*W+x));
        if(S[y][x] == '#') black[uf.root(y*W+x)]++;
        else white[uf.root(y*W+x)]++;
    }
    int ans = 0;

    // (H-1) * W + (W-1) = H*W - 1
    for(ll p: parents) {
        ans += black[p]*white[p];
    }

    cout << ans << endl;

    return 0;
}

