        rep(k,4){
            int ny = i+dy[k];
            int nx = j+dx[k];
            if(0<=ny && ny<h && 0<=nx && nx<w && s[i][j]!=s[ny][nx]){
                uf.merge(i*w+j,ny*w+nx);
            }
        }
    }
    ll ans = 0;
    vector<vector<ll>> black(h,vector<ll>(w,0));
    vector<vector<ll>> white(h,vector<ll>(w,0));
    rep(i,h) rep(j,w){
        int r = uf.find(i*w+j);
        int x = r%w;
        int y = (r-x)/w;
        if(s[i][j]=='#'){
            black[y][x]++;
        }
        else{
            white[y][x]++;
        }
    }
    vector<int> d = uf.roots();
    rep(i,d.size()){
        if(uf.size(d[i])==1){
            continue;
        }
        int r = d[i]%w;
        int l = (d[i]-r)/w;
        ans += black[l][r]*white[l][r];
    }
    cout << ans << endl;
