        // printf("_i=%d _j=%d u=%d v=%d\n", _i, _j, u, v);
        f[u][v] = 1;
        // ff[v][v] = 1;
        (c ? *b : *w)++;
        myfind(!c, u, v, f, S,  b, w);
      }
    }
  }
}


