int dx[] = {1,-1,0,0};
int dy[] = {0,0,1,-1};

bool isInField(int x, int y) {
  return 0 <= x && x < W && 0 <= y && y < H;
}

int ans[MAX_N][MAX_N];

void bfs(int x, int y) 
{
  using II = pair<int, int>;
  using TT = pair<II, int>;

  queue<TT> que;
  que.push(TT(II(x, y), 1));
  used[y][x] = true;

  int ret = 0;
  vector<II> vec;
  vec.push_back(II(x, y));

  while(que.size()) {
    TT p = que.front(); que.pop();
    x = p.first.first; y = p.first.second;
    int turn = p.second;
    int nextTurn = (turn+1)%2;

    for(int d = 0; d < 4; d++) {
      int nx = x + dx[d];
      int ny = y + dy[d];
      if(isInField(nx, ny)) {
        if(nextTurn == 0) {
          if(!used[ny][nx] && field[ny][nx] == '.') {
            used[ny][nx] = true;
            que.push(TT(II(nx, ny), nextTurn));
            ret++;
          }
        }
        if(nextTurn == 1) {
          if(!used[ny][nx] && field[ny][nx] == '#') {
            used[ny][nx] = true;
            que.push(TT(II(nx, ny), nextTurn));
            vec.push_back(II(nx, ny));
          }
        }
      }
    }
  }

  for(II v : vec) {
    ans[v.second][v.first] = ret;
  }
}

