struct edge{int to, cost;};

class Graph
{
public:
    int V;
    vector<vector<edge>> G;

    Graph(int V): V(V){
        G = vector<vector<edge>>(V, vector<edge>(0));
    }

    void add_edge(int from, int to, int cost){
        G[from].push_back(edge({to, cost}));
    }

    void add_edge2(int v1, int v2, int cost){
        add_edge(v1, v2, cost);
        add_edge(v2, v1, cost);
    }

    void dfs(int v, int c[2], vector<bool> &used, vector<string> &S, int W){
        used[v] = true;
        if(S[v / W][v % W] == '.') c[0]++;
        else c[1]++;
        REP(k, G[v].size()) if(!used[G[v][k].to]) dfs(G[v][k].to, c, used, S, W);
    }

};

signed main(){

    int H, W; cin >> H >> W;
    vector<string> S(H); readv(S);
    Graph G(H * W);
    REP(i, H - 1) REP(j, W) if(S[i][j] != S[i + 1][j]) G.add_edge2(i * W + j, (i + 1) * W + j, 0);
    REP(i, H) REP(j, W - 1) if(S[i][j] != S[i][j + 1]) G.add_edge2(i * W + j, i * W + j + 1, 0);

    vector<bool> used(H * W, false);
    int c[2], ans = 0;
    REP(i, H * W){
        if(!used[i]){
            c[0] = 0;
            c[1] = 0;
            G.dfs(i, c, used, S, W);
            ans += c[0] * c[1];
        }
    }
    cout << ans;

    return 0;
}

