using namespace std;

struct UnionFind
{
  vector<int> par; //par[i]がiの根を表す

  // コンストラクタ
  UnionFind(int n)
  {
    par = vector<int>(n);
    for (int i = 0; i < n; i++)
    {
      par[i] = i;
    }
  }

  // データxの根を求める
  int root(int x)
  {
    if (par[x] == x)
      return x;
    return par[x] = root(par[x]); // 木構造の縮約を行っている
  }

  // xとyの親が違うとき、マージする。そのときyの根がxの根の子になる
  void merge(int x, int y)
  {
    int rootx = root(x);
    int rooty = root(y);
    if (rootx == rooty)
      return;
    par[rooty] = rootx;
  }

  // 同じグループに属しているか
  bool isSame(int x, int y)
  {
    return root(x) == root(y);
  }
};

int main()
{
  // 黒が#で0、白が.で1
  int map[400][400] = {};
  int h = 0, w = 0;
  cin >> h >> w;
  REP(i, h)
  {
    string s;
    cin >> s;
    REP(j, s.length())
    {
      if (s[j] == '#')
      {
        map[i][j] = 0;
      }
      else
      {
        map[i][j] = 1;
      }
    }
  }

  UnionFind tree(h * w);

  REP(i, h)
  {
    REP(j, w)
    {
      if (j < w - 1)
      {
        if (map[i][j] != map[i][j + 1])
        {
          tree.merge(i * w + j, i * w + j + 1);
        }
      }

      if (i < h - 1)
      {
        if (map[i][j] != map[i + 1][j])
        {
          tree.merge(i * w + j, (i + 1) * w + j);
        }
      }
    }
  }

  int a[16001] = {};
  int b[16001] = {};

  REP(i, h)
  {
    REP(j, w)
    {
      int r = tree.root(i * w + j);
      cout << r << endl;
      if (map[i][j] == 0)
      {
        a[r]++;
      }
      else
      {
        b[r]++;
      }
    }
  }

  int result = 0;

  REP(i, h * w)
  {
    result += a[i] * b[i];
  }

  cout << result << endl;
}

