const int lx[4] = {0, 0, -1, 1};
const int ly[4] = {-1, 1, 0, 0};

int main()
{
    int n, m;
    cin >> n >> m;
    vector<vector<int>> a(n, vector<int>(m, 0)), vis(n, vector<int> (m, 0));

    for(int i = 0; i < n; i++){
        string s;
        cin >> s;
        for(int j = 0; j < m; j++){
            char x = s[j];
            if(x == '#') a[i][j] = 1; // black
        }
    }

    int ans = 0;
    for(int i = 0; i < n; i++)
    {
        for(int j = 0; j < m; j++)
        {
            if(vis[i][j]) continue;
            queue< pair<int, int> > q;
            q.push({i, j});
            int w = 0, b = 0;
            while(!q.empty())
            {
                int x = q.front().first;
                int y = q.front().second;
                q.pop();
                if(vis[x][y]) continue;
                vis[x][y] = 1;
                if(a[x][y]) b++;
                else w++;
                for(int k = 0; k < 4; k++){
                    int nx = x + lx[k];
                    int ny = y + ly[k];
                    if(nx >= 0 && ny >= 0 && nx < n && ny < m && a[x][y] != a[nx][ny] && !vis[nx][ny])
                        q.push({nx, ny});
                }

            }
            ans += b*w;
        }
    }
    cout << ans;
}

