int a[401][401];
int H,W;
queue<pair<int,int> > q;
int used[401][401];
int dx[4]={1,-1,0,0};
int dy[4]={0,0,1,-1};

bool inside(int x, int y, int i) {
    return (x + dx[i] < H && x + dx[i] >= 0 && y + dy[i] >= 0 && y + dy[i] < W);
}

bool check(int x,int y, int i) {
    if (!inside(x, y, i)) return false;
    if(a[x][y] == a[x+dx[i]][y+dy[i]]) return false;
    return true;
}

int solve() {
    ll ans = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (used[i][j]) continue;
            long long  b = 0, w = 0;//b-black w-WHite
            used[i][j] = 1;
            q.push({i, j});
            while (!q.empty()) {
                pair<int, int> r = q.front();
                q.pop();
                int x = r.first;
                int y = r.second;
                if (a[x][y]) b++;
                else w++;
                for (int d = 0; d < 4; d++) {
                    if (!check(x, y, d)) continue;//invalid move
                    if (used[x + dx[d]][y + dy[d]]) continue;
                    used[x + dx[d]][y + dy[d]] = 1;
                    q.push({x + dx[d], y + dy[d]});
                }
            }
            ans += b * w;
        }
    }
    return ans;
}

int run() {
    cin>>H>>W;
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            char cH;
            cin>>cH;
            a[i][j]=(cH=='#');
        }
    }
    memset(used,0,sizeof(used));
    ll ans=solve();
    cout<<ans;
}

