int main()
{
	int h,w;
	cin >> h >> w;
	char field[h][w];
	FOR(i,0,h)cin >> field[i];
	bool checked[h][w];
	FOR(i,0,h)FOR(j,0,w)checked[i][j] = false;
	int rest = h * w;
	ll ans = 0;
	while(rest > 0){
		queue<pii> bfs;
		FOR(i,0,h){
			FOR(j,0,w){
				if(!checked[i][j]){
					bfs.push(mp(i,j));
					checked[i][j] = true;
					rest--;
					break;
				}
			}
			if(!bfs.empty())break;
		}
		int countB,countW;
		countB = countW = 0;
		while(!bfs.empty()){
			int y = bfs.front().first;
			int x = bfs.front().second;
			//cout << y << " " << x << endl;
			bfs.pop();
			if(field[y][x] == '#'){
				countB++;
			}else{
				countW++;
			}
			int dy[4] = {0,1,0,-1};
			int dx[4] = {1,0,-1,0};
			FOR(i,0,4){
				int ny = y + dy[i];
				int nx = x + dx[i];
				if(ny < 0 || h <= ny)continue;
				if(nx < 0 || w <= nx)continue;
				if(checked[ny][nx])continue;
				if(field[y][x] == field[ny][nx])continue;
				checked[ny][nx] = true;
				rest--;
				bfs.push(mp(ny,nx));
			}
		}
		ans += countB * countW;
		//cout << "----------------------\n";
	}
	ANS(ans);
	return 0;
}

