void count_area(int* n, int x, int y, char ch)
{
	S[y][x] = ' ';
	++n[(x+y)%2];
	if (x > 0 && S[y][x-1] == ch) {
		count_area(n, x-1, y, ch);
	}
	if (x < W-1 && S[y][x+1] == ch) {
		count_area(n, x+1, y, ch);
	}
	if (y > 0 && S[y-1][x] == ch) {
		count_area(n, x, y-1, ch);
	}
	if (y < H-1 && S[y+1][x] == ch) {
		count_area(n, x, y+1, ch);
	}
}

