pi dfs(int y, int x, vector<string> &f)
{
    pi ret = pi(0,0);
    if (f[y][x]=='#') ret.fi++; else ret.se++;
    use[y][x] = true;
    rep(i,4){
        int ty = y+dy[i];
        int tx = x+dx[i];
