        }
    }
    for (int i = 0; i < h; i++)
    {
        for (int j = 0; j < w; j++)
        {
            if (s[i][j] == '#')
                bp[i][j] = true;
        }
    }
    ll ans = bfs();
    printf("%lld\n", ans);
}

