using namespace std;
typedef long long ll;
typedef long double ld;
struct UnionFind
{
  vector<int> par; 

  UnionFind(int N) : par(N)
  {
    for (int i = 0; i < N; i++)
      par[i] = i;
  }

  int root(int x)
  {
    if (par[x] == x)
      return x;
    return par[x] = root(par[x]);
  }

  void unite(int x, int y)
  {                   
    int rx = root(x);
    int ry = root(y);
    if (rx == ry)
      return;     
    par[rx] = ry;
  }

  bool same(int x, int y)
  { 
    int rx = root(x);
    int ry = root(y);
    return rx == ry;
  }
};

int main()
{
  int h,w;
  cin >> h >> w;
  vector<string> s(h);
  UnionFind tree(h*w);
  REP(i,h) cin >> s[i];

  vector<int> black,white;
  auto it_b = black.begin();
  auto it_w = white.begin();
  REP(i,h){
    REP(j,w){
      if((s[i])[j] == '#'){
        it_b = black.insert(it_b, i*w+j);
        it_b++;
      }else{ 
        it_w = white.insert(it_w, i*w+j);
        it_w++;
      }
      if(i>0 && (s[i])[j] != (s[i-1])[j]){
        tree.unite(i*w+j,(i-1)*w+j);
      }
      if(i<h-1 && (s[i])[j] != (s[i+1])[j]){
        tree.unite(i*w+j,(i+1)*w+j);
      }
      if(j>0 && (s[i])[j] != (s[i])[j-1]){
        tree.unite(i*w+j,i*w+j-1);
      }
      if(j<w-1 && (s[i])[j] != (s[i])[j+1]){
        tree.unite(i*w+j,i*w+j+1);
      }
    }
  }

  int ans = 0;
  for(auto i: black){
    for(auto j: white){
      if(tree.same(i,j)){
//      cout << ans << " " << i << " " << j << endl;
        ans++;
      }
    }
  }
  cout << ans << endl;
  return 0;
}

