		{
			if (ff(i - 1, j, s[i][j]))
				t.un(f(i - 1, j), f(i, j));
			if (ff(i + 1, j, s[i][j]))
				t.un(f(i + 1, j), f(i, j));
			if (ff(i, j - 1, s[i][j]))
				t.un(f(i, j - 1), f(i, j));
			if (ff(i, j + 1, s[i][j]))
				t.un(f(i, j + 1), f(i, j));
