//白に隣接している黒をチェック
//cに入っている方向は調べない
void checkAroundByWrite(int x, int y, char c) {

    writeCount++;
    //調べた白には-2を入れる
    SS[x][y] = -2;

    if (checkBlock(x - 1, y) == 0 && c != 'l') {
        checkAroundByBlack(x - 1, y);
    }
    if (checkBlock(x + 1, y) == 0 && c != 'r') {

        checkAroundByBlack(x + 1, y);
    }
    if (checkBlock(x, y - 1) == 0 && c != 'u') {
        checkAroundByBlack(x, y - 1);

    }
    if (checkBlock(x, y + 1) == 0 && c != 'b') {
        checkAroundByBlack(x, y + 1);

    }
}

//黒に隣接している白をチェック。
//調べ済みの白は調べない
void checkAroundByBlack(int x, int y) {

    //cout << "Black: " << "x: " << x << " y: " << y << endl;
    blackCount++;
    //調べた黒には1を入れる
    SS[x][y] = 1;

    // 左が白かチェックして、そうなら、白の周辺が黒かチェック
    if (checkBlock(x - 1, y) == -1) {
        checkAroundByWrite(x - 1, y, 'r');
    }
    // 右が白かチェックして、そうなら、白の周辺が黒かチェック
    if (checkBlock(x + 1, y) == -1) {
        checkAroundByWrite(x + 1, y, 'l');
    }
    // 上が白かチェックして、そうなら、白の周辺が黒かチェック
    if (checkBlock(x, y - 1) == -1) {
        checkAroundByWrite(x, y - 1, 'b');
    }
    // 下が白かチェックして、そうなら、白の周辺が黒かチェック
    if (checkBlock(x, y + 1) == -1) {
        checkAroundByWrite(x, y + 1, 'u');
    }
}

int main() {


    cin >> H >> W;


    //白なら-1, 黒なら0を入れる
    for (int i = 0; i < H; ++i) {
        string S;
        cin >> S;
        for (int j = 0; j < S.size(); ++j) {
            int s;
            if (S[j] == '#') {
                s = 0;
            } else {
                s = -1;
            }
            SS[i][j] = s;
        }
    }
    int result = 0;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            // まだ調べていない黒を調べる
            if (SS[i][j] == 0) {
                writeCount = 0;
                blackCount = 0;
                checkAroundByBlack(i, j);
                result += writeCount * blackCount;
            }
        }
    }

    cout << result << endl;

    return 0;
}

