	for (int i = 0; i < N; i++)
		scanf("%s", mat[i]);
}

void dfs(int x, int y, int &b, int &w) {
	bio[x][y] = true;
	if (mat[x][y] == '#')
		b++;
	else
		w++; 
	for (int i = 0; i < 4; i++) {
		int nx = x + dx[i];
