map<pair<int, int>, int> mb, mw;
char grid[400][400];

int btow(int, int);
int wtob(int, int);

int main()
{
  cin >> h >> w;

  for (auto y = 0; y < h; y++) {
    for (auto x = 0; x < w; x++) {
      cin >> grid[y][x];
    }
  }

  int ans = 0;

  for (auto y = 0; y < h; y++) {
    for (auto x = 0; x < w; x++) {
      if (grid[y][x] == '#') {
        mb.clear();
        mw.clear();
        ans += btow(y, x);
      }
    }
  }
  cout << ans << endl;
}

int btow(int y, int x)
{
  int cnt = 0;

  if (mb.count(pair<int, int>(y, x)) != 0) {
    return cnt;
  }

  mb.emplace(pair<int, int>(y, x), 1);

  int dx[] = { 1, 0, -1, 0 };
  int dy[] = { 0, 1, 0, -1 };

  for (auto i = 0; i < 4; i++) {
    int xx = x + dx[i];
    int yy = y + dy[i];
    if (0 <= xx && xx < w && 0 <= yy && yy < h && grid[yy][xx] == '.') {
      cnt += wtob(yy, xx);
    }
  }
  return cnt;
}

int wtob(int y, int x)
{
  int cnt = 0;

  if (mw.count(pair<int, int>(y, x)) != 0) {
    return cnt;
  }

  cnt++;
  mw.emplace(pair<int, int>(y, x), 1);

  int dx[] = { 1, 0, -1, 0 };
  int dy[] = { 0, 1, 0, -1};

  for (auto i = 0; i < 4; i++) {
    int xx = x + dx[i];
    int yy = y + dy[i];
    if (0 <= xx && xx < w && 0 <= yy && yy < h && grid[yy][xx] == '#') {
      cnt += btow(yy, xx);
    }
  }
  return cnt;
}

