//入力
int h,w;
char s[410][410];
bool visited[410][410];
bool bp[410][410];

int dfs(int hh, int ww, int c){
    if (hh<0 && hh>=h && ww<0 && ww>=w && bp[hh][ww] == false) return c;
    if (visited[hh][ww] == false){
        if (bp[hh-1][ww] == false && 0<= hh-1 && hh-1<h && 0<=ww && ww<w) c++;
        if (bp[hh+1][ww] == false && 0<= hh+1 && hh+1<h && 0<=ww && ww<w) c++;
        if (bp[hh][ww-1] == false && 0<= hh && hh<h && 0<=ww-1 && ww-1<w) c++;
        if (bp[hh][ww+1] == false && 0<= hh && hh<h && 0<=ww+1 && ww+1<w) c++;
        visited[hh][ww]==true;
        c+=dfs(hh+1,ww+1,c);
        c+=dfs(hh-1,ww+1,c);
        c+=dfs(hh-1,ww-1,c);
        c+=dfs(hh+1,ww-1,c);
    }
    visited[hh][ww]==true;
    return c;
}
