int main() {
	int H, W; cin >> H >> W;
	vector<string> s(H);
	for (int i = 0; i < H; ++i) cin >> s[i];

	vector<pint> blacks;
	for (int i = 0; i < H; ++i) {
		for (int j = 0; j < W; ++j) {
			if (s[i][j] == '#')blacks.push_back({i, j});
		}
	}

	vector<vector<int>> used(H, vector<int>(W));
	int ans = 0;
	for (auto start : blacks) {
		if (used[start.first][start.second] != 0) continue;

