void dfs(int row, int column, bool black) {
    int n_row, n_column;
    if (black) {
        for (int i = 0; i < 4; i++) {
            n_row = row + dx[i];
            n_column = column + dy[i];
            if (0 <= n_row and n_row < H  and 0 <= n_column and n_column < W ) {
                if (visited[n_row][n_column] == false and S[n_row][n_column] == '.') {
                    visited[n_row][n_column] = true;
                    b += 1;
                    dfs(n_row, n_column, false);
                }
            }
        }
    }

    else {
        for (int i = 0; i < 4; i++) {
            n_row = row + dx[i];
            n_column = column + dy[i];
            if (0 <= n_row and n_row < H  and 0 <= n_column and n_column < W ) {
                if (visited[n_row][n_column] == false and S[n_row][n_column] == '#') {
                    visited[n_row][n_column] = true;
                    w += 1;
                    dfs(n_row, n_column, true);
                }
            }
        }
    }
}

