int dfsw(int y,int x){
  int cnt=0;
  for(int d=-1;d<=1;d+=2){
    if(onBoardX(x+d)&&!visited[y][x+d]&&v[y][x+d]==1){
      visited[y][x+d]=true;
      cnt+=dfsb(y,x+d);
    }
    if(onBoardY(y+d)&&!visited[y+d][x]&&v[y+d][x]==1){
      visited[y+d][x]=true;
      cnt+=dfsb(y+d,x);
    }
  }
  return cnt;
}
int dfsb(int y,int x){
  int cnt=0;
  for(int d=-1;d<=1;d+=2){
    if(onBoardX(x+d)&&!visited[y][x+d]&&v[y][x+d]==0){
      visited[y][x+d]=true;
      cnt+=1+dfsw(y,x+d);
    }
    if(onBoardY(y+d)&&!visited[y+d][x]&&v[y+d][x]==0){
      visited[y+d][x]=true;
      cnt+=1+dfsw(y+d,x);
    }
  }
  return cnt;
}

