#define MAX 400
#define WHITE 0
#define GRAY 1
#define BLACK 2

string s[MAX];
vector<pair<int, int>> m[MAX][MAX];
int c[MAX][MAX];
int dx[]={-1,0,0,1};
int dy[]={0,-1,1,0};

void bfs_init(){
	for(int i=0; i<MAX; i++){
		for(int j=0; j<MAX; j++){
			c[i][j]=WHITE;
		}
	}
	return;
}

ll bfs(int x, int y){
	ll b_cnt=0, w_cnt=0;
	queue<pair<int, int>> q;

	c[x][y]=GRAY;
	if(s[x][y]=='.') w_cnt++;
	else b_cnt++;

	q.push(make_pair(x,y));
	while(!q.empty()){
		pair<int,int> u=q.front();
		q.pop();
		int i=u.first, j=u.second;
		int l=m[i][j].size();
		for(int k=0; k<l; k++){
			int xx=m[i][j][k].first, yy=m[i][j][k].second;
			if(c[xx][yy]==WHITE){
				c[xx][yy]=GRAY;
				if(s[xx][yy]=='.') w_cnt++;
				else b_cnt++;
				q.push(make_pair(xx,yy));
			}
		}
		c[x][y]=BLACK;
	}
	return b_cnt*w_cnt;
}

int main(){
	int h, w;
	cin >> h >> w;
	for(int i=0; i<h; i++) cin >> s[i];

	vector<pair<int, int>> v;
