			for(int k=0; k<4; k++){
				int x=i+dx[k], y=j+dy[k];
				if(x<0 || x>=h || y<0 || y>=w) continue;
				if(s[i][j]!=s[x][y]){
					m[i][j].push_back(make_pair(x,y));
				}
			}
		}
	}

	ll ans=0;
	bfs_init();
	for(int i=0; i<h; i++){
		for(int j=0; j<w; j++){
			if(c[i][j]==WHITE){
				ans+=bfs(i, j);
			}
		}
	}
	cout << ans << endl;
	return 0;
}

#include<bits/stdc++.h>
#define pii pair<int,int>
#define F first
#define S second
using namespace std;
const int N=405;
int n,m;char c;
long long ans;
bool a[N][N],f[N][N],o;
int dx[4]={0,1,0,-1};
int dy[4]={1,0,-1,0};
inline bool ok(int x2,int y2){return (x2>=0&&y2>=0&&x2<n&&y2<m);}
pii arrive(int x,int y,bool black)
{
	pii p;
	if(black)p.F++;
	else p.S++;
	for(int i=0;i<4;i++)
	{
		int x2=x+dx[i];
		int y2=y+dy[i];
		if(ok(x2,y2)&&!f[x2][y2]&&black!=a[x2][y2])
		{
			f[x2][y2]=true;
			pii j=arrive(x2,y2,!black);
			p.F+=j.F;
			p.S+=j.S;
		}
	}
	return p;
}
int main()
{
	scanf("%d %d",&n,&m);
	for(int i=0;i<n;i++)
	{
		for(int j=0;j<m;j++)
		{
			cin>>c;
			a[i][j]=(c=='#'?true:false);
		}
	}
	for(int i=0;i<n;i++)
	{
		for(int j=0;j<m;j++)
		{
			if(f[i][j])continue;
			pii p=arrive(i,j,a[i][j]);
			if(a[i][j])p.F--;
			else p.S--;
			ans+=(long long)p.F*p.S;
		}
	}
	printf("%d",ans);
	return 0;
}

