struct UnionFind {
  vll d;
  UnionFind(ll n=0): d(n,-1) {}
  ll find(ll x) {
    if (d[x] < 0) return x;
    return d[x] = find(d[x]);
  }
  bool unite(ll x, ll y) {
    x = find(x); y = find(y);
    if (x == y) return false;
    if (d[x] > d[y]) swap(x,y);
    d[x] += d[y];
    d[y] = x;
    return true;
  }
  bool same(ll x, ll y) { return find(x) == find(y);}
  ll size(ll x) { return -d[find(x)];}
};


const ll MAX_H=400;
const ll MAX_W=400;
bool visited[MAX_H][MAX_W];
vector<string> s(MAX_H);
ll h,w;
void dfs(ll y, ll x, ll root, UnionFind& uf, char pre){
  if(visited[y][x])
    return;

  char now=s[y][x];
  if(pre==now)
    return;

  visited[y][x]=true;

  ll num=y*w+x;
  uf.unite(root,num);
  REP(i,4){
    if(x+dx[i]<0 || w<=x+dx[i] || y+dy[i]<0 || h<=y+dy[i])
      continue;
    if(s[y+dy[i]][x+dx[i]]!=now)
      dfs(y+dy[i],x+dx[i],root,uf,now);
  }
}


