  cin.tie(NULL);

  cin>>h>>w;
  REP(i,h)cin>>s[i];

  REP(i,h)REP(j,w)visited[i][j]=false;


  UnionFind uf(h*w);
  REP(i,h){
    REP(j,w){
      ll num=i*w+j;
      char pre='a';
      dfs(i,j,num,uf,pre);
    }
  }

  ll ans=0;
  vpl p(h*w);
  REP(i,h){
    REP(j,w){
      ll num=w*i+j;
      ll par=uf.find(num);
      if(s[i][j]=='#')
        p[par].FI++;
      else
        p[par].SE++;
    }
  }

  REP(i,h*w)ans+=p[i].FI*p[i].SE;

  cout<<ans<<endl;

}

