#include <bits/stdc++.h>
using namespace std;

const int MAX_V = 160000;
int par[MAX_V];
int depth[MAX_V];
int black_num[MAX_V];
int white_num[MAX_V];

void init(int n) {
    for(int i = 0; i < n; i++)
    {
        par[i] = i;
        depth[i] = 0;
    }
}

int root(int x) {
    if (par[x] == x) return x;
    else return par[x] = root(par[x]);
}

void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y) return;

    black_num[x] += black_num[y];
    black_num[y] = black_num[x];
    white_num[y] += white_num[x];
    white_num[x] = white_num[y];

    if (depth[x] < depth[y]) par[x] = y;
    else {
        par[y] = x;
        if (depth[x] == depth[y]) depth[x]++;
    }
}

bool same(int x, int y) {
    return root(x) == root(y);
}

int get_black(int x) {
    return black_num[root(x)];
}

int get_white(int x) {
    return white_num[root(x)];
}

int main() {
    int h, w;
    cin >> h >> w;
    vector<vector<char>> s(h, vector<char>(w));
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            cin >> s.at(i).at(j);
        }
    }

    init(h * w);
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (s.at(i).at(j) == '#') black_num[i * w + j] = 1;
            else white_num[i * w + j] = 1;
        }
    }

    int dx[] = {0, 0, 1, -1};
    int dy[] = {1, -1, 0, 0};
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            for (int k = 0; k < 4; k++) {
                int ny = i + dy[k], nx = j + dx[k];
                if (0 <= ny && ny < h && 0 <= nx && nx < w && s.at(i).at(j) != s.at(ny).at(nx)) {
                    unite(i * w + j, ny * w + nx);
                }
            }
        }
    }

    vector<bool> done(h * w);
    long long cnt = 0;
    for (int i = 0; i < h * w; i++) {
        if (done.at(root(i))) continue;

        cnt += (long long)get_black(i) * get_white(i);
        done.at(root(i)) = true; 
    }

    cout << cnt << endl;
}

