  auto f = [&](int64_t y, int64_t x) {
    int b = 0, w = 0;
    queue<pair<int, int>> que;
    que.push(make_pair(y, x));

    while (!que.empty()) {
      auto q = que.front();
      que.pop();

      int y = q.first, x = q.second;
      for (int k = 0; k < 4; k++) {
        int ny = y + dy[k], nx = x + dx[k];
        if (ny < 0 || ny >= H || nx < 0 || nx >= W) continue;
        if (used[ny][nx] || S[y][x] == S[ny][nx]) continue;
        if (S[ny][nx] == '.') w++;
