        que.push(make_pair(ny, nx));
        used[ny][nx] = true;
      }
    }
    return make_pair(b, w);
  };
  int64_t res = 0;
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      if (used[i][j] || S[i][j] == '.') continue;
      used[i][j] = true;
      pair<int64_t, int64_t> cnt = f(i, j);
      res += (cnt.first + 1) * cnt.second;
    }
  }
  cout << res << '\n';
