int main(){
    int H,W;
    cin>>H>>W;
    vector<vector<char>> S(410,vector<char>(410,'x'));    
    REP(i,H){
        string s;
        cin>>s;
        REP(j,s.size()){
            S[i+1][j+1]=s[j];
        }
    }
    ll ans=0;
    // BFS のためのデータ構造
    vector<vector<int>> dist(410,vector<int>(410,-1)); // 全頂点を「未訪問」に初期化
    REP2(i,1,H+1){
        REP2(j,1,W+1){
            if(dist[i][j]!=-1) continue;

            queue<pair<int,int>> que;

            // 初期条件 (頂点 0 を初期ノードとする)
            dist[i][j] = 0;
            que.push(make_pair(i,j)); // 0 を橙色頂点にする
            ll cnt1=0;
            ll cnt2=0;
            // BFS 開始 (キューが空になるまで探索を行う)
            while (!que.empty()) {
                pair<int,int> t = que.front(); // キューから先頭頂点を取り出す
                que.pop();
                int x=t.first;
                int y=t.second;

                if(S[x][y]=='#') cnt1++;
                if(S[x][y]=='.') cnt2++;
                char bv=S[x][y];
                S[x][y]='x';

                // v から辿れる頂点をすべて調べる
                for (auto n : np) {
                    int nx=x+n.first;
                    int ny=y+n.second;
                    if (S[nx][ny]=='x') continue;
                    if (S[nx][ny]==bv) continue;
                    if (dist[nx][ny]!=-1) continue;
                    // 新たな白色頂点 nv について距離情報を更新してキューに追加する
                    dist[nx][ny] = dist[x][y] + 1;
                    que.push(make_pair(nx,ny));
                }
            }
            ans+=cnt1*cnt2;
        }
    }
    cout<<ans<<endl;


}

