vector<vector<char>> field;
const ll dx[] = {1,0,0,-1};
const ll dy[] = {0,1,-1,0};
ll bfs(ll x,ll y){
    queue<P> que;
    que.push(P(x,y));
    ll B = 0,W = 0;
    while(!que.empty()){
        P p = que.front();
        que.pop();
        if(field[p.first][p.second] == '$')continue;
        else if(field[p.first][p.second] == '#')B++;
        else W++;
        rep(i,4){
            ll hx = p.first + dx[i],hy = p.second + dy[i];
            if(hx < 0 || hy < 0 || hx >= N || hy >= M)continue;
            if(field[hx][hy] == '$' || field[hx][hy] == field[p.first][p.second])continue;
            que.push(P(hx,hy));
        }
        field[p.first][p.second] = '$';
    }
    return B * W;
}

