class UnionFind {
 public:
  vector<int> data;
  int count;
 public:
  UnionFind(int size) : data(size, -1), count(size) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
      --count;
    }
    return x != y;
  }
  bool findSet(int x, int y) { return root(x) == root(y); }
  int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }
  int size(int x) { return -data[root(x)]; }
};

#define HW(r,c) ((r)*W+(c))

ll solve(int H,int W, vs& s) {
    UnionFind uf(H*W);
    rep(r,H)rep(c,W) {
        if (0 < r) {
            if (s[r-1][c] != s[r][c]) uf.unionSet(HW(r-1,c), HW(r,c));
        }
        if (r+1 < H) {
            if (s[r+1][c] != s[r][c]) uf.unionSet(HW(r+1,c), HW(r,c));
        }
        if (0 < c) {
            if (s[r][c-1] != s[r][c]) uf.unionSet(HW(r,c-1), HW(r,c));
        }
        if (c+1 < W) {
            if (s[r][c+1] != s[r][c]) uf.unionSet(HW(r,c+1), HW(r,c));
        }
    }

    unordered_map<int,ll> bl, wh;
    unordered_set<int> roots;
    rep(r,H) rep(c,W) {
        int rt = uf.root(HW(r,c));
        roots.insert(rt);
        if (s[r][c] == '#') {
            bl[rt]++;
        } else {
            wh[rt]++;
        }
    }
    ll cnt = 0;
    for (int rt: roots){
        cnt += bl[rt] * wh[rt];
    }
    return cnt;
}

int main() {
    int H, W; cin >> H >> W;
    vs s(H);
    rep(i,H) cin >> s[i];
    cout << solve(H,W,s) << endl;
    return 0;
}

