        for(int y = prev_start_y; y <= H; ++y){
            for(int x = prev_start_x + 1; x <= W; ++x){
                if(!passed[y][x]){
                    start_x = x;
                    start_y = y;
                    break;
                }
            }
            if(start_x != -1){
                break;
            }
            prev_start_x = 0;
        }

        if(start_x == -1){
            break;
        }

        prev_start_x = start_x;
        prev_start_y = start_y;

        queue<pair<int, int>> pos_q;
        pos_q.push({start_x, start_y});
        passed[start_y][start_x] = true;

        int black_num = 0;
        int white_num = 0;

        while(pos_q.size()){
            auto p = pos_q.front();
            pos_q.pop();
            int val = S[p.second][p.first];

            if(val == 0){
                ++black_num;
            }
            else{
                ++white_num;
            }

            for(int dy = -1; dy <= 1; dy += 2){
                if(!passed[p.second + dy][p.first] && S[p.second + dy][p.first] != val){
                    passed[p.second + dy][p.first] = true;
                    pos_q.push({p.first, p.second + dy});
                }
            }
            for(int dx = -1; dx <= 1; dx += 2){
                if(!passed[p.second][p.first + dx] && S[p.second][p.first + dx] != val){
                    passed[p.second][p.first + dx] = true;
                    pos_q.push({p.first + dx, p.second});
                }
            }
        }

        sum += white_num * black_num;
    }

    cout << sum;
}

