inline bool is_valid_coordinate(int i,int j){
    return (0<=i&&i<h&&0<=j&&j<w);
}
inline bool is_alternated(int i,int j,int di,int dj){
    return (is_valid_coordinate(i,j)
            &&is_valid_coordinate(i+di,j+dj)
            &&((s[i][j]=='b'&&s[i+di][j+dj]=='.')
            ||(s[i][j]=='w'&&s[i+di][j+dj]=='#')));
}
void check_recursively(int i,int j){
    if(is_valid_coordinate(i,j)&&(s[i][j]=='#'||s[i][j]=='.')){
        if(s[i][j]=='#'){
            s[i][j]='b';
            cntb++;
        }else if(s[i][j]=='.'){
            s[i][j]='w';
            cntw++;
        }
        int di[]={1,0,-1,0},dj[]={0,1,0,-1};
        for(int itr=0;itr<4;itr++){
            if(is_alternated(i,j,di[itr],dj[itr]))
                check_recursively(i+di[itr],j+dj[itr]);
        }
    }
}
void reset_recursively(int i,int j){
    if(is_valid_coordinate(i,j)&&(s[i][j]=='b'||s[i][j]=='w')){
        s[i][j]='x';
        int di[]={1,0,-1,0},dj[]={0,1,0,-1};
        for(int itr=0;itr<4;itr++){
            reset_recursively(i+di[itr],j+dj[itr]);
        }
    }
}
long long count_in_connected_component(int i,int j){
    cntb=0;
    cntw=0;
    check_recursively(i,j);
    reset_recursively(i,j);
    return cntb*cntw;
}
