        for(int i=0; i<H; i++)
                std::cin >> S[i];

        index position=search(H,W);
        do {
                result+=pairNum(position,H,W);
                position=search(H,W);
        } while(position.i<H&&position.j<W);

        std::cout <<result;

        return 0;
}

