int main() {
    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    for (auto &e: S) cin >> e;

    int ans = 0;
    vector<pair<int, int>> dirs = {{0, 1}, {1, 0}};

    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (used[i][j]) continue;
            used[i][j] = true;

            int cnt_b = 0, cnt_w = 0;
            stack<pair<int, int>> st;
            st.emplace(i, j);
            while (!st.empty()) {
                auto p = st.top(); st.pop();
                char pc = S[p.first][p.second];
                if (pc == '.') cnt_b++;
                else cnt_w++;
                for (auto &&d: dirs) {
                    pair<int, int> c = {p.first + d.first, p.second + d.second}; 
                    if (c.first >= H || c.second >= W) continue;
                    if (used[c.first][c.second]) continue;
                    if (S[c.first][c.second] != pc) {
                        used[c.first][c.second] = true;
                        st.push(c);
                    }
                }
            }
            ans += cnt_w * cnt_b;
        }
    }

    cout << ans << endl;

    return 0;
}

