	ll num_block[blocks+1];
	ll white[blocks+1] = {0};
	ll black[blocks+1] = {0};
	REP(i,H){
		REP(j,W){
			if (S[i][j]=='.') white[dp[i][j]]++;
			else  black[dp[i][j]]++;
		}
	}
	REP(i,blocks+1){
		ans += white[i]*black[i];
	}

	//出力
	cout << ans << endl;
}

