int dfs(int y,int x,char c,vector<string>& s){
  if(ending) return ending;
  if(dp[y][x]){
    return ending = dp[y][x];
  }
  used[y][x]=true;
  int res = 0;
  REP(i,4){
    int nx=x+dx[i];
    int ny=y+dy[i];
    if(in_range(ny,nx)&&s[ny][nx]!=c&&!used[ny][nx]) res += dfs(ny,nx,s[ny][nx],s);
  }
  if(ending) return ending;
  if(c=='.') return res+1;
  else {
