const std::vector<std::pair<int,int>> Directions{{-1, 0}, {0, -1}, {1, 0}, {0, 1}};

int main(int argc, char* argv[])
{
  std::ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int H, W;
  cin >> H >> W;

  std::vector<std::string> S(H);
  std::vector<std::vector<int>> seen(H, std::vector<int>(W, 0));

  for (auto& si : S)
  {
    cin >> si;
  }

  long long res = 0;
  std::queue<int> q;

  for (int i = 0; i < H; ++i)
  {
    for (int j = 0; j < W; ++j)
    {
      if (seen[i][j]) continue;

      q.push((i << 9) | j);
      seen[i][j] = 1;

      int wc = 0;
      int bc = 0;

      while (!q.empty())
      {
        int w = q.front() & 511;
        int h = q.front() >> 9; q.pop();

        if (S[h][w] == '.') ++wc;
        else ++bc;

        for (auto& dir : Directions)
        {
          int hh = h + dir.first;
          int ww = w + dir.second;
          if (hh < 0 || ww < 0 || hh >= H || ww >= W) continue;
          if (S[hh][ww] == S[h][w]) continue;
          if (seen[hh][ww]) continue;
          seen[hh][ww] = 1;
          q.push((hh << 9) | ww);
        }
      }

      res += 1LL * wc * bc;
    }
  }

  cout << res << "\n";

  return 0;
}

