int Find(int x){
    return x == p[x]?x:p[x] = Find(p[x]);
}
void Merge(int x,int y){
    x = Find(x),y = Find(y);
    if(x!=y){
        p[x] = y;
        cnt[y] += cnt[x];
        c_[y] += c_[x];
    }
}
int main(){
