#include <bits/stdc++.h>
using namespace std;

int h, w;
int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};
bool matrix[401][401], visited[401][401];

bool dfs(int y, int x, int gy, int gx){
    if(y == gy && x == gx) return true;
    visited[y][x] = true;
    for(int i = 0; i < 4; i++){
        int ny = y + dy[i], nx = x + dx[i];
        if(ny < 0 || ny >= h || nx < 0 || nx >= w) continue;
        if(visited[ny][nx]) continue;
        if(matrix[y][x] == matrix[ny][nx]) continue;
        if(dfs(ny, nx, gy, gx)){
            visited[y][x] = false;
            return true;
        }
    }
    visited[y][x] = false;
    return false;
}

void solve(){
    int ans = 0;
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            if(!matrix[i][j]) continue;
            for(int k = 0; k < h; k++){
                for(int l = 0; l < w; l++){
                    if(matrix[k][l]) continue;
                    ans += dfs(i, j, k, l);
                }
            }
        }
    }
    cout << ans << endl;
}

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> h >> w;
    for(int i = 0; i < h; i++){
        for(int j = 0; j < w; j++){
            char c; cin >> c;
            if(c == '#') matrix[i][j] = true;
        }
    }
    solve();
    return 0;
}

