ll GridBFS(pl start,const vector<vector<char>> &info,vvl &dist,vector<vector<bool>> &seen){
    que.emplace(start);
    dist[start.fi][start.se]=0;
    int cntb=1,cntw=0;
    while(que.size()){
        ll y=que.front().fi,x=que.front().se;
        que.pop();
        rep(k,4){
            ll ny=y+dy[k],nx=x+dx[k];
            if(0<=ny and ny<H and 0<=nx and nx<W){
                if(info[ny][nx]=='#'){
                    if(dist[ny][nx]>dist[y][x]+1 and (dist[y][x]+1)%2==0){
                        dist[ny][nx]=dist[y][x]+1;
                        que.push({ny,nx});
                        seen[ny][nx]=1;
                        cntb++;
                    }
                }
                else{
                    if(dist[ny][nx]>dist[y][x]+1 and (dist[y][x]+1)%2==1){
                        dist[ny][nx]=dist[y][x]+1;
                        que.push({ny,nx});
                        seen[ny][nx]=1;
                        cntw++;
                    }
                }
            }
        }
    }
    return cntb*cntw;
}
