complex<int> f(int i, int j, char c) {
	if (!(0 <= i && i < H && 0 <= j && j < W)) return 0;
	if (S[i][j] != c) return 0;
	S[i][j] = '*';
	complex<int> r;
	if (c == '.') r.real(1); else r.imag(1);
	char cc = c == '.' ? '#' : '.';
	r += f(i+1,j,cc);
	r += f(i-1,j,cc);
	r += f(i,j+1,cc);
	r += f(i,j-1,cc);
	return r;
}
