//木の根を求める
int find(int x)
{
    if (par[x] == x)
    {
        return x;
    }
    else
    {
        return par[x] = find(par[x]);
    }
}
//併合
void unite(int x, int y)
{
    x = find(x);
    y = find(y);
    if (x == y)
        return;
    if (rank1[x] < rank1[y])
    {
        par[x] = y;
    }
    else
    {
        par[y] = x;
        if (rank1[x] == rank1[y])
            rank1[x]++;
    }
}
bool same(int x, int y)
{
    return find(x) == find(y);
}
int size(int x)
{
    return -par[find(x)];
}
