struct Pair{
    long a,b;
};

Pair search(int x,int y,int w,int h,vector<vector<char> > stage,vector<vector<bool> >& mark,vector<vector<bool> >& flags){
    Pair ret;
    ret.a = stage[x][y] == '.' ? 1 : 0;
    ret.b = 1;
    if(x > 0){
        if(mark[x][y] == mark[x - 1][y] && !flags[x - 1][y]){
            flags[x - 1][y] = true;
            Pair p = search(x - 1,y,w,h,stage,mark,flags);
            ret.a += p.a;
            ret.b += p.b;
        }
    }
    if(x < w - 1){
        if(mark[x][y] == mark[x + 1][y] && !flags[x + 1][y]){
            flags[x + 1][y] = true;
            Pair p = search(x + 1,y,w,h,stage,mark,flags);
            ret.a += p.a;
            ret.b += p.b;
        }
    }
    if(y > 0){
        if(mark[x][y] == mark[x][y - 1] && !flags[x][y - 1]){
            flags[x][y - 1] = true;
            Pair p = search(x,y - 1,w,h,stage,mark,flags);
            ret.a += p.a;
            ret.b += p.b;
        }
    }
    if(y < h - 1){
        if(mark[x][y] == mark[x][y + 1] && !flags[x][y + 1]){
            flags[x][y + 1] = true;
            Pair p = search(x,y + 1,w,h,stage,mark,flags);
            ret.a += p.a;
            ret.b += p.b;
        }
    }
    return ret;
}

