struct union_find {
	long long N;					// the number of nodes
	long long M;					// the number of trees
	std::vector<long long> parent;	// parent[i] := the direct parent of i
	std::vector<long long> size;	// size[i] := the number of nodes in the tree rooted to i
	vector<ll> white_cnt;
	vector<ll> black_cnt;

	union_find(long long n) : N(n), M(n) {
		parent.resize(n, -1);
		size.resize(n, 1);
		white_cnt.resize(n, 0);
		black_cnt.resize(n, 0);
	}

	long long root(long long i) {
		if (parent[i] == -1) return i;
		else return parent[i] = root(parent[i]);
	}

	bool is_united(long long i, long long j) {
		return (root(i) == root(j));
	}

	// true : unite succeeded
	bool unite(long long i, long long j) {
		i = root(i); j = root(j);
		if (i == j) return false;
		if (size[i] < size[j]) std::swap(i, j);
		parent[j] = i;
		size[i] += size[j];
		white_cnt[i] += white_cnt[j];
		black_cnt[i] += black_cnt[j];
		M--;
		return true;
	}
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	//constexpr ll P = 1e9 + 7;
	//constexpr ll P = 998244353;

	ll h, w;
	cin >> h >> w;
	vector<string> s(h);
	for (ll i = 0; i < h; i++) cin >> s[i];

	ll m = h * w;
	union_find uf(m);
	auto idx = [&] (ll i, ll j) {return i * w + j;};
	for (ll i = 0; i < h; i++) {
		for (ll j = 0; j < w; j++) {
			if (s[i][j] == '.') uf.white_cnt[idx(i, j)]++;
			else uf.black_cnt[idx(i, j)]++;
		}
	}

	for (ll i = 0; i < h; i++) {
		for (ll j = 0; j < w; j++) {
			if (i < h - 1 && (s[i][j] ^ s[i + 1][j])) uf.unite(idx(i, j), idx(i + 1, j));
			if (j < w - 1 && (s[i][j] ^ s[i][j + 1])) uf.unite(idx(i, j), idx(i, j + 1));
		}
	}

	ll ans = 0;
	for (ll i = 0; i < m; i++) {
		if (uf.parent[i] == -1) {
			ans += uf.white_cnt[i] * uf.black_cnt[i];
		}
	}
	cout << ans << endl;
}

