const long long MAXN = 405;

lli dx[]={0,0,-1,1,-1,-1,1,1};
lli dy[]={1,-1,0,0,1,-1,-1,1};

lli g[MAXN][MAXN], vis[MAXN][MAXN];
lli h, w;

void dfs(lli x, lli y, lli color, plli &val) {
    if (x < 0 or x > h - 1 or y < 0 or y > w - 1) return;
    if (vis[x][y]) return;

    vis[x][y] = 1;
    int next;
    if (color == 1)
        next = 0;
    else
        next = 1;

    if (color == 1) val.second++;
    else val.first++;

    for (int i = 0; i < 4; ++i) {
        lli p = x + dx[i], q = y + dy[i];
        if (p < 0 or p > h - 1 or q < 0 or q > w - 1) continue;
        if (g[p][q] != next) continue;
        dfs(p, q, next, val);
    }
}

void solve() {
    cin >> h >> w;
    lli ans = 0;
    for (int i = 0; i < h; ++i) {
        string s;
        cin >> s;
        for (int j = 0; j < w; ++j) {
            if (s[j] == '.') g[i][j] = 0;
            else g[i][j] = 1;
        }
    }

    memset(vis, 0, sizeof(vis));

    for (int i = 0; i < h; ++i) {
        for (int j = 0; j < w; ++j) {
            if (vis[i][j]) continue;
            plli p;
            p.first = 0, p.second = 0;
            dfs(i, j, g[i][j], p);
            ans += p.first * p.second;
        }
    }

    cout << ans << endl;
}

