ll ecd(ll a, ll b) {
	if (a < b) swap(a, b);
	if (b == 0) return a;
	else {
		return ecd(b, a % b);
	}
}

ll pow(ll a, ll b) {
	vector<ll> d = vector<ll>((ll)(log(b)) + 2);
	d[0] = a;
	rep(i, 1, d.size()) d[i] = d[i - 1] * d[i - 1];
	ll ret = 1;
	rep(i, 0, log(b) + 1) {
		if (b & 1 << i) ret *= d[i];
	}
	return ret;
}

//C
class UnionFind
{

private:
	std::vector<long long> par;
	std::vector<long long> rank;
	std::vector<long long> color; //0なら白1なら黒

public:
	UnionFind(long long n) {
		par = std::vector<long long>(n);
		rank = std::vector<long long>(n);
		color = std::vector<long long>(n);
		for (long long i = 0; i < n; i++) {
			par[i] = i;
			rank[i] = 0;
			color[i] = 2;
		}
	};

	long long find(long long x) {
		if (par[x] == x) {
			return x;
		}
		else {
			return par[x] = find(par[x]);
		}
	}

	void unite(long long x, long long y) {
		color[x] = 0;
		color[y] = 1;
		x = find(x);
		y = find(y);
		if (x == y)return;

		if (rank[x] < rank[y]) {
			par[x] = y;
		}
		else {
			par[y] = x;
			if (rank[x] == rank[y])rank[x]++;
		}
	}

	bool same(long long x, long long y) {
		return find(x) == find(y);
	}

	long long count() {
		long long ret = 0;
		vector<vector<long long>> group = vector<vector<long long>>(par.size(), vector<long long>(color.size()));
		for (long long i = 0; i < par.size(); i++) {
			group[par[i]][color[i]]++;
		}

		for (long long i = 0; i < par.size(); i++) {
			ret += group[i][0] * group[i][1];
		}

		return ret;
	}
};


int main(void) {
