	UnionFind uf = UnionFind(H*W);
	rep(i, 0, H) {
		rep(j, 0, W) {
			if (S[i][j] == '#') {
				if (i > 0 && S[i - 1][j] == '.' )
					uf.unite((i - 1) * W + j, i * W + j);
				if (i < H - 1 && S[i + 1][j] == '.') 
					uf.unite((i + 1) * W + j, i * W + j);
				if (j > 0 && S[i][j - 1] == '.' && !(i > 0 && j > 0 && S[i - 1][j - 1] == '#'))
					uf.unite(i * W + j - 1, i * W + j);
				if (j < W - 1 && S[i][j + 1] == '.' && !(i > 0 && j < W - 1 && S[i - 1][j + 1] == '#'))
					uf.unite(i * W + j + 1, i * W + j);
			}
		}
	}
	cout << uf.count() << endl;
}

