    UnionFind tree(H * W);
    //白黒の順番の連結成分を探す
    REP(i, H) {
        REP(j, W - 1) {
            if(S[i][j] != S[i][j + 1]) {
                tree.unite(W * i + j, W * i + j + 1);
            }
        }
    }
    REP(j, W) {
        REP(i, H - 1) {
            if(S[i][j] != S[i + 1][j]) {
                tree.unite(W * i + j, W * (i + 1) + j);
            }
        }
    }
    set<int> p;
    REP(i, H) {
        REP(j, W) { p.insert(tree.find(i * W + j)); }
    }
    ll ans = 0;
    for(auto now : p) {
        int hoge = tree.size(now);
        if(hoge % 2 == 0) {
            ans += hoge * hoge / 4;
        } else {
