bool is_in(int i, int j, int h, int w) {
    return 0 <= i && i < h && 0 <= j && j < w;
}

int main() {

    int h, w;
    cin >> h >> w;
    vector<string> sorg(h, "");
    vector<string> s   (h, "");
    REP(i, h) {
        cin >> s[i];
        sorg[i] = s[i];
    }

    REP(i, h) REP (j, w) {
        if ((i + j) % 2) {
            s[i][j] = s[i][j] == '.' ? '#' : '.';
        }
    }

    vector<vector<bool>> visited(h, vector<bool>(w, false));
    ll ans = 0;

    REP(i, h) REP(j, w) {

        if (visited[i][j]) continue;

        deque<ll> q;
        ll black = 0, white = 0;

        q.push_back(j + i * w);
        visited[i][j] = true;
        char rootc = s[i][j];

        while (!q.empty()) {

            ll v = q.back();
            int k = v / w, l = v % w;
            q.pop_back();

            if (sorg[k][l] == '.') white++; else black++;

            if (is_in(k-1, l, h, w)) if (rootc == s[k-1][l] && !visited[k-1][l]) {
                q.push_back((k - 1) * w + l);
                visited[k-1][l] = true;
            }
            if (is_in(k+1, l, h, w)) if (rootc == s[k+1][l] && !visited[k+1][l]) {
                q.push_back((k + 1) * w + l);
                visited[k+1][l] = true;
            }
            if (is_in(k, l-1, h, w)) if (rootc == s[k][l-1] && !visited[k][l-1]) {
                q.push_back(k * w + l - 1);
                visited[k][l-1] = true;
            }
            if (is_in(k, l+1, h, w)) if (rootc == s[k][l+1] && !visited[k][l+1]) {
                q.push_back(k * w + l + 1);
                visited[k][l+1] = true;
            }

        }

        ans += black * white;

    }

    cout << ans << endl;

}

