typedef struct UnionFindTree{
    int n;
    vector<int> par;

    UnionFindTree(int n_){
        n = n_;
        par.resize(n, -1);
    }

    int find(int x){
        if(par[x] < 0) return x;
        return par[x] = find(par[x]);
    }

    bool unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return false;
        if(par[x] < par[y]){
            par[x] += par[y];
            par[y] = x;
        }
        else{
            par[y] += par[x];
            par[x] = y;
        }
        return true;
    }
}UF;

