class UF
{
private:
	vector<int> parent;
	vector<int> black;
	vector<int> white;

public:
	UF(int n)
	{
		parent = vector<int>(n, -1);
		black = vector<int>(n, 0);
		white = vector<int>(n, 0);
	}

	int getParent(int x)
	{
		if(parent[x] == -1) return x;
		else return parent[x] = getParent(parent[x]);
	}

	int getBlack(int x)
	{
		return black[getParent(x)];
	}

	int getWhite(int x)
	{
		return white[getParent(x)];
	}

	void update(int x, int y)
	{
		x = getParent(x);
		y = getParent(y);
		if(x == y) return;
		if(x > y) swap(x, y);
		parent[y] = x;
		black[x] += black[y];
		white[x] += white[y];
	}

	void addBlack(int x)
	{
		black[x]++;
	}

	void addWhite(int x)
	{
		white[x]++;
	}

};

int main()
{
	int h, w;
	cin >> h >> w;
