				int ny = j + dy[k];
				if(nx >= h || ny >= w) continue;
				if(s[i][j] != s[nx][ny]){
					uf.update(i * w + j, nx * w + ny);
				}
			}
		}
	}
	int ans = 0;
	for(int i = 0; i < h * w; i++){
		// cout << uf.getParent(i) << " " << uf.getBlack(i) << " " << uf.getWhite(i) << endl;
