std::pair<int, int> paint(boost::multi_array<int8_t, 2>& ss, int y, int x) {
  auto ret = std::pair<int, int>(0, 0);
  auto const currentColor = ss[y][x];
  assert(currentColor == 0 || currentColor == 1);
  ss[y][x] = -1;
  if (currentColor == 0) {
    ret.first++;
  } else {
    ret.second++;
  }
  auto const alternativeColor = 1 - currentColor;
  if (x < w - 1 && ss[y][x + 1] == alternativeColor) {
    auto painted = paint(ss, y, x + 1);
    ret.first += painted.first;
    ret.second += painted.second;
  }
  if (y < h - 1 && ss[y + 1][x] == alternativeColor) {
    auto painted = paint(ss, y + 1, x);
    ret.first += painted.first;
    ret.second += painted.second;
  }
  if (x > 0 && ss[y][x - 1] == alternativeColor) {
    auto painted = paint(ss, y, x - 1);
    ret.first += painted.first;
    ret.second += painted.second;
  }
  if (y > 0 && ss[y - 1][x] == alternativeColor) {
    auto painted = paint(ss, y - 1, x);
    ret.first += painted.first;
    ret.second += painted.second;
  }
  return ret;
}

int64_t solve(boost::multi_array<int8_t, 2>& ss) {
  int64_t ret = 0;
  for (int i = 0; i < h; i++) {
    for (int j = 0; j < w; j++) {
      if (ss[i][j] < 0) {
        continue;
      }
      auto painted = paint(ss, i, j);
      ret += static_cast<int64_t>(painted.first) *
             static_cast<int64_t>(painted.second);
    }
  }
  return ret;
}

