struct unionfind {
	vector<int> rank, par;
	unionfind() {}
	unionfind(int n):rank(n, 1), par(n, 0) {
		iota(par.begin(), par.end(), 0);
	}
	int root(int x) {
		return (x == par[x] ? x : par[x] = root(par[x]));
	}
	void unite(int x, int y) {
		x = root(x);
		y = root(y);
		if(x == y) return;
		if(rank[x] < rank[y]) swap(x, y);
		rank[x] += rank[y];
		par[y] = x;
	}
};
