using namespace std;

int Init(bool (*visited)[401], int w, int h)
{
	int i, j;

	for (i = 0; i < h; i++)
	{
		for (j = 0; j < w; j++)
		{
			visited[i][j] = false;
		}
	}
	return 1;
}

int Input(char (*s)[401], int& w, int& h, int (*score)[401])
{
	cin >> h >> w;

	for (int i = 0; i < h; i++)
	{
		for (int j = 0; j < w; j++)
		{
			cin >> s[i][j];
			score[i][j] = (s[i][j] == '#') ? 1 : 0;
		}
	}

	return 1;
}


int Process(int (*score)[401], bool (*visited)[401], int w, int h, int &result)
{
	int i, j ,k;
	int curr_x, curr_y;
	int next_x, next_y;
	int move[4][2] = { { 1, 0 },{ 0, 1 },{ -1,0 },{ 0,-1 } };
	vector<int> logging;
	queue<pair<int, int>> q;

	for (i = 0; i < h; i++)
	{
		for (j = 0; j < w; j++)
		{
			if (!visited[i][j])
			{
				q.push(pair<int, int>(i, j));
				visited[i][j] = true;

				while (!q.empty())
				{
					curr_y = q.front().first;
					curr_x = q.front().second;
					q.pop();
					logging.push_back(score[curr_y][curr_x]);


					for (k = 0; k < 4; k++)
					{
						next_y = curr_y + move[k][0];
						next_x = curr_x + move[k][1];

						if (0 <= next_x && next_x < w && 0 <= next_y && next_y < h && !visited[next_y][next_x]
							&& (score[curr_y][curr_x] + score[next_y][next_x] == 1))
						{
							q.push(pair<int, int>(next_y, next_x));
							visited[next_y][next_x] = true;
						}
					}
				}

				result += (count(logging.begin(), logging.end(), 1) * count(logging.begin(), logging.end(), 0));

				cout << endl;
				logging.clear();
			}
		}
	}

	return 1;
}

int main()
{
	int h, w, result = 0;

	char s[401][401];
	int score[401][401];
	bool visited[401][401] = { false, };

	Input(s, w, h, score);
	Init(visited, w, h);

	Process(score, visited, w, h, result);

	cout << result << endl;

	return 0;
}

