#include<bits/stdc++.h>
using namespace std;

class UnionFind{
    public:
    //親の番号を格納する。親だった場合は-(その集合のサイズ)
    vector<int> parent;

    //-1で初期化
    //最初はすべてバラバラ
    UnionFind(int N){
        parent = vector<int>(N,-1);
    }

    //Aがどのグループに属しているか(Aの根)を調べる
    int root(int A){
        if(parent[A] < 0) return A;
        return parent[A]=root(parent[A]);
    }

    //自分のいるグループの頂点数を調べる
    int size(int A){
        return -parent[root(A)];
    }

    //AとBをくっつける
    bool connect(int A, int B) {
    //AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
        A = root(A);
        B = root(B);
        //既にくっついているからくっつけない
        if(A == B) return false; 

        //大きいほう(A)に小さいほう(B)をくっつける
        //大証が逆ならひっくり返す
        if(size(A) < size(B)) swap(A,B);

        //Aのサイズを更新する
        parent[A] += parent[B];
        //Bの親をAに変更する
        parent[B] = A;

        return true;
    }

    //AとBが同じグループならtrueを返す
    bool same(int A, int B){
        return root(A)==root(B);
    } 
};

int main(){
    int h,w;
    cin>>h>>w;
    string s[h];
    for(int i=0;i<h;i++){
        cin>>s[i];
    }
    int ans=0,cnt=0;

    UnionFind uni(h*w);
    vector<int> b,wh;

    for(int i=0;i<h;i++)for(int j=0;j<w;j++){
        if(s[i][j]=='.'){
            if(i!=0 && s[i-1][j]=='#') uni.connect(i*w+j,(i-1)*w+j);
            if(i!=h-1 && s[i+1][j]=='#') uni.connect(i*w+j,(i+1)*w+j);
            if(j!=0 && s[i][j-1]=='#') uni.connect(i*w+j,i*w+j-1);
            if(j!=w-1 && s[i][j+1]=='#') uni.connect(i*w+j,i*w+j+1);
        }

        if(s[i][j]=='.') wh.push_back(i*w+j);
        else b.push_back(i*w+j);
    }

    for(auto i:wh){
        for(auto j:b){
            if(uni.same(i,j)) ans++;
        }
    }
    cout<<ans<<endl;


}

