class UnionFind {
    vector<int> data;
    int num;

  public:
    UnionFind(int size) : data(size, -1), num(size) {}
    bool unionSet(int x, int y) {
        x = root(x);
        y = root(y);
        if(x != y) {
            if(data[y] < data[x])
                swap(x, y);
            data[x] += data[y];
            data[y] = x;
            num--;
        }
        return x != y;
    }
    bool findSet(int x, int y) {
        return root(x) == root(y);
    }
    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }
    int size(int x) {
        return -data[root(x)];
    }
    int numSet() {
        return num;
    }
};

void solve() {

    ll h, w;
    cin >> h >> w;
    vec<string> s(h);
    REP(i, h) {
        cin >> s[i];
    }

    UnionFind uni(h * w);

    int dx[4] = {-1, 1, 0, 0};
    int dy[4] = {0, 0, 1, -1};

    REP(y, h) {
        REP(x, w) {
            REP(v, 4) {
                ll ny = y + dy[v];
                ll nx = x + dx[v];
                if(ny < 0 or ny >= h or nx < 0 or nx >= w)
                    continue;
                if(s[y][x] == s[ny][nx])
                    continue;
                uni.unionSet(y * w + x, ny * w + nx);
            }
        }
    }

    vec<ll> conw(h * w, 0), conb(h * w, 0);

    REP(y, h) {
        REP(x, w) {
            if(s[y][x] == '#') {
                conb[uni.root(y * w + x)]++;
            } else {
                conw[uni.root(y * w + x)]++;
            }
        }
    }
    ll ans = 0;

    REP(i, h * w) {
        ans += conw[i] * conb[i];
    }
    cout << ans << en;
}

