typedef long long ll;

class DisjointSet {
public:
  vector<int> p, rank, size;
  DisjointSet(int n) {
    p.assign(n, 0);
    rank.assign(n, 0);
    size.assign(n, 0);
    for (int i = 0; i < n; i++) {
      make_set(i);
    }
  }

  void make_set(int x) {
    p[x] = x;
    rank[x] = 0;
    size[x] = 1;
  }

  int find_set(int x) {
    if (x != p[x]) {
      p[x] = find_set(p[x]);
    }
    return p[x];
  }

  bool same(int x, int y) {
    return find_set(x) == find_set(y);;
  }

  int union_size(int x) {
    if (x != p[x]) {
      size[x] = union_size(find_set(x));
    }
    return size[x];
  }

  void link(int x, int y) {
    if(rank[x]  > rank[y]) {
        p[y] = x;
        size[x] = size[x] + size[y];
    }else if(rank[x] < rank[y]){
        p[x] = y;
        size[y] = size[x] + size[y];
    }else if(x != y) {
      p[y] = x;
      rank[x]++;
      size[x] = size[x] + size[y];
    }
  }

  void unite(int x, int y) {
      link(find_set(x), find_set(y));
  }
};

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int H, W;
  cin >> H >> W;
  char c[H][W];
  int n = H * W;
  int d[n];
  for (int i = 0; i < H; i++) {
    string s;
    cin >> s;
    for (int j = 0; j < W; j++) {
      c[i][j] = s[j];
      int idx = i * W + j;
      if (c[i][j] == '#') d[idx] = 0;
      else d[idx] = 1;
    }
  }
  DisjointSet ds(n);
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      if (i + 1 < H && c[i][j] != c[i + 1][j]) {
        ds.unite(W * i + j, W * (i + 1) + j);
      }
      if (j + 1 < W && c[i][j] != c[i][j + 1]) {
        ds.unite(W * i + j, W * i + j + 1);
      }
    }
  }
  ll ans = 0;
  ll b[n]{};
  ll w[n]{};
  for (int i = 0; i < n; i++) {
    if (d[i] == 0) b[ds.find_set(i)]++;
    else  w[ds.find_set(i)]++;
  }
  for (int i = 0; i < n; i++) {
    ans += b[i] * w[i];
  }
  cout << ans << "\n";
  return 0;
}

