int n, m, tot, color[maxtot];
string data[maxn];
vector<int> g[maxtot];
bool vis[maxtot];

void addEdge(int a, int b) {
	g[a].push_back(b);
	g[b].push_back(a);
}

void bfs(int st, vector<int> &count) {
	queue<int> qu;
	qu.push(st);
	vis[st] = true;

	while (!qu.empty()) {
		int cur = qu.front();
		qu.pop();

		++count[color[cur]];

		for (int i = 0; i < g[cur].size(); ++i) {
			int v = g[cur][i];
			if (!vis[v]) {
				qu.push(v);
				vis[v] = true;
			}
		}
	}
}

int main() {

	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	cin >> n >> m;
	for (int i = 0; i < n; ++i)
		cin >> data[i];

	tot = n * m;
	for (int i = 0; i < n; ++i)
		for (int j = 0; j < m; ++j) {
			int cur = i*n + j;
			if (i < n-1 && data[i][j] != data[i+1][j])
				addEdge(cur, cur+n);
			if (j < m-1 && data[i][j] != data[i][j+1])
				addEdge(cur, cur+1);

			color[cur] = data[i][j] == '.' ? 0 : 1;
		}

	long long ans = 0;
	for (int i = 0; i < tot; ++i) {
		vector<int> count(2);
		bfs(i, count);

		ans += count[0] * count[1];
	}

	cout << ans << endl;

	return 0;
}

