#define ll long long

struct UnionFind{
    vector<int> data;
    /* constructor */
    UnionFind(int sz){ data.assign(sz,-1); }
    /* merge the set to which x belongs and the set to which y belongs */
    bool unite(int x,int y){
        x = find(x); y = find(y);
        if (x == y) return false;
        if (data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return true;
    }
    /* find the root of k */
    int find(int k){
        if (data[k] < 0) return k;
        return data[k] = find(data[k]);
    }
    /* calculate the size of the set to which k belongs */
    int size(int k){ return -data[find(k)]; }
};

int main(void){
	int H, W; cin >> H >> W;
	vector<string> S(H);
	for (auto& si : S) cin >> si;

	UnionFind uf(H * W);
	for (int i = 0; i < H; ++i){
		for (int j = 0; j < W; ++j){
			int id = W * i + j;
			if (j != W - 1){ // 右
				int r = id + 1;
				if (S[i][j] != S[i][j + 1])
					uf.unite(id, r);
			}
			if (i != H - 1){ // 下
				int d = id + W;
				if (S[i][j] != S[i + 1][j])
					uf.unite(id, d);
			}
		}
	}

	map<int, int> b, w;
	for (int i = 0; i < H; ++i){
		for (int j = 0; j < W; ++j){
			int id = i * W + j;
			if (S[i][j] == '.') w[uf.find(id)]++;
			else b[uf.find(id)]++;
		}
	}

	ll res = 0;
