      unvisited_nodes.insert(tools::vector2<std::int_fast64_t>(j, i));
    }
  }

  std::int_fast64_t answer = 0;
  while (!unvisited_nodes.empty()) {
    std::int_fast64_t white = 0;
    std::int_fast64_t black = 0;
    bfs_queue bfs;
    bfs.insert(*unvisited_nodes.begin());
    for (std::int_fast64_t i = 0; i < bfs.size(); ++i) {
      const tools::vector2<std::int_fast64_t>& vec = bfs[i];
      switch (S[vec.y][vec.x]) {
      case '.':
        if (0 < vec.y && S[vec.y - 1][vec.x] == '#') bfs.insert(tools::vector2<std::int_fast64_t>(vec.x, vec.y - 1));
        if (vec.y < H - 1 && S[vec.y + 1][vec.x] == '#') bfs.insert(tools::vector2<std::int_fast64_t>(vec.x, vec.y + 1));
        if (0 < vec.x && S[vec.y][vec.x - 1] == '#') bfs.insert(tools::vector2<std::int_fast64_t>(vec.x - 1, vec.y));
        if (vec.x < W - 1 && S[vec.y][vec.x + 1] == '#') bfs.insert(tools::vector2<std::int_fast64_t>(vec.x + 1, vec.y));
        ++white;
        break;
      case '#':
        if (0 < vec.y && S[vec.y - 1][vec.x] == '.') bfs.insert(tools::vector2<std::int_fast64_t>(vec.x, vec.y - 1));
        if (vec.y < H - 1 && S[vec.y + 1][vec.x] == '.') bfs.insert(tools::vector2<std::int_fast64_t>(vec.x, vec.y + 1));
        if (0 < vec.x && S[vec.y][vec.x - 1] == '.') bfs.insert(tools::vector2<std::int_fast64_t>(vec.x - 1, vec.y));
        if (vec.x < W - 1 && S[vec.y][vec.x + 1] == '.') bfs.insert(tools::vector2<std::int_fast64_t>(vec.x + 1, vec.y));
        ++black;
        break;
      }
      unvisited_nodes.erase(vec);
    }
    answer += white * black;
  }

  std::cout << answer << std::endl;
  return 0;
}

