            if (memo[i][j] != memo[I][J] && UF.find(i*W+j) != UF.find(I*W+J)) {
                int ij = UF.find(i*W+j), IJ = UF.find(I*W+J);
                int ii = ij/W, jj = ij%W, II = IJ/W, JJ = IJ%W;
