  else return (color1 != color2);
}

int main() {
  int table[402][402] = {};
  int H, W; std::cin >> H >> W;
  for (int r = 0; r < H; ++r) {
    std::string s; std::cin >> s;
    for (int c = 0; c < W; ++c) {
      if (s[c] == '#') table[r+1][c+1] = 1;
    }
  }

  for (int c = 0; c <= W + 1; ++c) {
    table[0][c] = kInvalid;
    table[H+1][c] = kInvalid;
  }
  for (int r = 0; r <= H + 1; ++r) {
    table[r][0] = kInvalid;
    table[r][W+1] = kInvalid;
  }

#if DEBUG
  for (int r = 1; r <= H; ++r) {
    for (int c = 1; c <= W; ++c) {
      std::cout << table[r][c];
    }
    std::cout << std::endl;
  }
#endif

  int cnt = 0;
  bool checked[402][402];
  for (int x = 1; x <= W; ++x) {
    for (int y = 1; y <= H; ++y) {
      if (checked[x][y]) continue;

      int cnt_b = 0;
      int cnt_w = 0;
      std::queue<Point> que;
      que.push({x, y});
      checked[x][y] = true;

      while(!que.empty()) {
        const auto& p = que.front();
        que.pop();

        if (table[p.x][p.y] == 0) ++cnt_w;
        else if (table[p.x][p.y] == 1) ++cnt_b;

        if (!checked[p.x][p.y-1] && connectable(table[p.x][p.y], table[p.x][p.y-1])){// up
          que.push({p.x, p.y-1});
          checked[p.x][p.y-1] = true;
        }
        if (!checked[p.x][p.y+1] && connectable(table[p.x][p.y], table[p.x][p.y+1])){// down
          que.push({p.x, p.y+1});
          checked[p.x][p.y+1] = true;
        }
        if (!checked[p.x-1][p.y] && connectable(table[p.x][p.y], table[p.x-1][p.y])){// left
          que.push({p.x-1, p.y});
          checked[p.x-1][p.y] = true;
        }
        if (!checked[p.x+1][p.y] && connectable(table[p.x][p.y], table[p.x+1][p.y])){// right
          que.push({p.x+1, p.y});
          checked[p.x+1][p.y] = true;
        }
      }
      cnt += cnt_b * cnt_w;
    }
  }
  std::cout << cnt << std::endl;
}

