void dfs(int x, int y)
{
	map<pair<pair<int, int>, pair<int, int>>, bool> m;
	queue<pair<int, int>> que;
	que.push(pair<int, int>(x, y));

	while (que.size()){
		int res = 0;
		pair<int, int> p = que.front();
		que.pop();
		if (d[p.first][p.second] != INF){
			res = d[p.first][p.second];
			continue;
		}
		for (int i = 0; i < 4; i++){
			int nx = p.first + dx[i], ny = p.second + dy[i];
			if (0 <= nx and nx < h and 0 <= ny and ny < w and m[pair<pair<int, int>, pair<int, int>>(pair<int,int>(x, y), pair<int, int>(nx, ny))] == 0 and s[nx][ny] != s[p.first][p.second]){
				if (s[nx][ny] != s[x][y]) res++;
				que.push(pair<int, int>(nx, ny));
			m[pair<pair<int, int>, pair<int, int>>(pair<int,int>(x, y), pair<int, int>(nx, ny))] = 1;
			}
		}
		ans += res;
	}

	return ;
}

