int H, W;
vector<vector<int>> field;
vector<vector<int>> checked;
long long ans = 0;
long long black_cnt;
long long white_cnt;

int dfs(int h, int w) {
    checked[h][w] = 1;
    if (field[h][w] == 0) white_cnt++;
    else black_cnt++;

    int dx[] = {0, 1, 0, -1};
    int dy[] = {1, 0, -1, 0};
    for (int i = 0; i < 4; i++) {
        int next_h = h + dy[i];
        int next_w = w + dx[i];
        if (checked[next_h][next_w] == 0 && field[next_h][next_w] == (field[h][w] ^ 1)) {
            dfs(next_h, next_w);
        }
    }
    return 0;
}

int main(void){
    cin >> H >> W;
    field.resize(H+2, vector<int>(W+2, -1));
    checked.resize(H+2, vector<int>(W+2));
