        }
    }

    for (int i = 1; i <= H; i++) {
        for (int j = 1; j <= W; j++) {
            if (checked[i][j] == 0) {
                black_cnt = 0;
                white_cnt = 0;
                dfs(i, j);
                ans += black_cnt * white_cnt;
            }
        }
    }

    cout << ans << endl;
}

#include <iostream>
#include <string>
#include <stack>
#include <utility>
#define MAX_H 400
#define MAX_W 400
using namespace std;

struct Point {
    int i, j;
    char prev_color;
};

bool used[MAX_H][MAX_W];

int calc(string s[], int h, int w, int i, int j) {
    int black = 0, white = 0;

    stack<Point> st;
    st.push(Point {i, j, ' '});
    while (!st.empty()) {
        Point p = st.top();
        st.pop();
        i = p.i;
        j = p.j;
        if (i < 0 || h <= i || j < 0 || w <= j || used[i][j] || p.prev_color == s[i][j])
            continue;
        used[i][j] = true;
        if (s[i][j] == '#')
            black++;
        else
            white++;
        st.push(Point {i - 1, j, s[i][j]});
        st.push(Point {i + 1, j, s[i][j]});
        st.push(Point {i, j - 1, s[i][j]});
        st.push(Point {i, j + 1, s[i][j]});
    }
    return black * white;
}

int main() {
    int h, w;
    cin >> h >> w;
    string s[h];
    for (int i = 0; i < h; i++) {
        cin >> s[i];
    }
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            used[i][j] = false;
        }
    }
    int ans = 0;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (used[i][j])
                continue;
            ans += calc(s, h, w, i, j);
        }
    }
    cout << ans << endl;
    return 0;
}

