int main() {
	int h, w;
	cin >> h >> w;
	vector<vector<int>> field(h, vector<int>(w, 0));
	vector<vector<int>> id(h, vector<int>(w, -1));
	for (int y = 0; y < h; ++y) {
		string s;
		cin >> s;
		for (int x = 0; x < w; ++x) {
			if (s[x] == '#') {
				field[y][x] = 1;
			}
		}
	}

	int maxid = 0;
	vector<pair<int, int>> res;
	for (int y = 0; y < h; ++y) {
		for (int x = 0; x < w; ++x) {
			if (id[y][x] == -1) {
				queue<pair<int, int>> q;
				q.push(make_pair(x, y));
				id[y][x] = maxid;
				int white, black;
				white = black = 0;
				if (field[y][x] == 1) black++;
				else white++;

				while (!q.empty()) {
					auto p = q.front();
					int cx = p.first;
					int cy = p.second;
					q.pop();
					int dx[] = { 1,0,-1,0 };
					int dy[] = { 0,1,0,-1 };
					for (int d = 0; d < 4; ++d) {
						int nx = cx + dx[d];
						int ny = cy + dy[d];
						if (0 <= nx && nx < w) {
							if (0 <= ny && ny < h) {
								if (id[ny][nx] == -1) {
									if (field[cy][cx] != field[ny][nx]) {
										id[ny][nx] = maxid;
										if (field[ny][nx] == 1) black++;
										else white++;
										q.push(make_pair(nx, ny));
									}
								}
							}
						}
					}
				}
				res.push_back(make_pair(white, black));
				maxid++;
			}
		}
	}
	int64_t sum = 0;
	for (auto item : res) {
		sum += item.first * item.second;
	}
	cout << sum << endl;
	return 0;
}

