		ans=0;
		for (int i;i<H;i++)for(int j=0;j<W;j++){
		Point p(i,j);
		if(get_char(p)=='#'){
	//		cout<<"b "<<p.h<<" "<<p.w<<endl;
		init_visited();
		dfs(p);
		}}
		return ans;
	}

