        //cout << xx << " " << yy << endl;
        if (xx < 0 || xx >= H) continue;
        else if (yy < 0 || yy >= W) continue;
        else if (used[xx][yy]) continue;
        else if (S[xx][yy] != C[(color + 1) % 2]) continue;
        if (S[xx][yy] == 'x') continue;
        //cout << "ok" << xx << " " << yy << " " << S[xx][yy] << endl;
        dfs(xx, yy, (color + 1) % 2);
        check++;
    }
    if (color == 0 && check == 0) {
        black--;
        return;
    }
    if (color == 0) S[x][y] = 'x';
}


int main(void)
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> H >> W;
    rep(i, H) rep(j, W) cin >> S[i][j];
    int ans = 0;
    rep(i, H) {
        rep(j, W) {
            //cout << S[i][j] << endl;
