                used = vector<vector<bool>>(410, vector<bool>(410, 0));
                ans += white * black;
                //cout << "*" << white << " " << black << endl;
                white = 0;
                black = 0;
            }
        }
    }
    //rep(i, H) rep(j, W) cout << i << " " << j <<" " << S[i][j]  << endl;
    cout << ans << endl;

    return 0;
}

