using namespace std;

int H, W;
string S[405];

int C[405][405];

int B[405][405];

set<pair<int, int> > SS, tmp_SS;

int main(void) {

	cin >> H >> W;
	string tmp = "";
	for (int i = 0; i <= W + 1; i++) { tmp += "?"; }
	S[0] = tmp; S[H + 1] = tmp;

	for (int i = 1; i <= H; i++) {
		cin >> tmp;
		S[i] = "?" + tmp + "?";
	}

	for (int i = 1; i <= H; i++) {
		for (int j = 1; j <= W; j++) {
			if (S[i][j] == '#') { B[i][j] = 1; }
			else { B[i][j] = -1; }
		}
	}

	int ans = 0;

	for (int i = 1; i <= H; i++) {
		for (int j = 1; j <= W; j++) {
			if (B[i][j] == +1) {
				for (int u = 1; u <= H; u++) {
					for (int v = 1; v <= W; v++) {
						C[u][v] = 0;
					}
				}
			//=============
				SS.insert(pair<int, int>(i, j)); int parity = 0;
				while (SS.size()) {

					tmp_SS.clear();

					for (auto it = SS.begin(); it != SS.end(); it++) {
						int I = (*it).first;
						int J = (*it).second;
						/*string str;
						if (parity == 0) { str = "."; }
						else { str = "#"; }*/

						int val;
						if (parity == 0) { val = -1; }
						else { val = 1; }

						if ((B[I-1][J]==val) && (C[I - 1][J] == 0)) { tmp_SS.insert(pair<int, int>(I - 1, J)); C[I - 1][J] = 1; }
						if ((B[I+1][J]==val) && (C[I + 1][J] == 0)) { tmp_SS.insert(pair<int, int>(I + 1, J)); C[I + 1][J] = 1; }
						if ((B[I][J-1]==val) && (C[I][J-1] == 0)) { tmp_SS.insert(pair<int, int>(I , J-1)); C[I][J-1] = 1; }
						if ((B[I][J+1]==val) && (C[I][J + 1] == 0)) { tmp_SS.insert(pair<int, int>(I, J + 1)); C[I][J + 1] = 1; }
					}
					SS = tmp_SS;
					parity++;
					parity %= 2;
				}

				for (int u = 1; u <= H; u++) {
					for (int v = 1; v <= W; v++) {
						if ((B[u][v] == -1) && (C[u][v] != 0)) { ans++; }
					}
				}

			//================
			}
		}
	}

	cout << ans << endl;
	//system("pause");
	return 0;
}

