// 4方向（左、右、上、下）（左上を0, 0とした場合）
vector<long long> dx = {-1, 1, 0, 0};
vector<long long> dy = { 0, 0,-1, 1};

vector<string> s;
vvi globalchk;

ll bfs(ll i, ll j){
    ll cnt = 0;
    ll h = s.size();
    ll w = s[0].size();
    //vvi chk(h, vi(w, 0));
    ll gcnt = 1;
    globalchk[i][j] = 1;
    queue<pair<pair<ll, ll>, ll>> que;
    que.push(make_pair(make_pair(i, j), 0));
    // chk[i][j] = 1;
    while(que.size()){
        auto front = que.front();
        que.pop();
        ll x = front.first.second;
        ll y = front.first.first;
        char c = (front.second == 0 ? '#' : '.');
        for(ll d=0; d<4; d++){
            ll tx = x + dx[d];
            ll ty = y + dy[d];
            if(tx<0 || ty<0 || tx>w-1 || ty > h-1) continue;
            if(globalchk[ty][tx] == 1 || s[ty][tx] == c) continue;
            globalchk[ty][tx] = 1;
            que.push(make_pair(make_pair(ty, tx), front.second^1));
            if(s[ty][tx] == '.') cnt++;
            else{
                globalchk[ty][tx] = 1;
                gcnt++;
            }
        }
    }
    return cnt*gcnt;
}

