#include <bits/stdc++.h>
using namespace std;
#define ll long long


struct unionfind{
    vector<int> parent;
    vector<int> rank;
    vector<int> sizeb;
    vector<int> sizew;

    unionfind (int N) {
        parent = vector<int>(N);
        iota(parent.begin(), parent.end(), 0);
        rank = vector<int>(N, 0);
        sizeb = vector<int>(N, 0);
        sizew = vector<int>(N, 0);

    }
    int root(int x) {
        if (parent[x] == x) return x;
        parent[x] = root(parent[x]);
        return parent[x];
    }

    bool same(int x, int y){
        return root(x) == root(y);
    }

    void unite(int x, int y){
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (rank[x] > rank[y]) {
            parent[y] = x;
            sizeb[x] += sizeb[y];
            sizew[x] += sizew[y];
        }
        else {
            parent[x] = y;
            sizeb[y] += sizeb[x];
            sizew[y] += sizew[x];
            if (rank[x] == rank[y]) rank[y] += 1;
        }
    }
};


int main(){
    int H, W;
    cin >> H >> W;
    vector<string> grid(H);
    unionfind uf(H*W);
    for (int i = 0; i < H; i++) cin >> grid[i];
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++){
            if (grid[i][j] == '.') uf.sizew[W*i+j] = 1;
            else uf.sizeb[W*i+j] = 1;
        }
    }

    for (int i = 0; i < H-1; i++) {
        for (int j = 0; j < W; j++){
            if (grid[i][j] != grid[i+1][j]) {
                uf.unite(W*i+j, W*(i+1)+j);
            }
        }
    }
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W-1; j++){
            if (grid[i][j] != grid[i][j+1]) {
                uf.unite(W*i+j, W*i+j+1);
            }
        }
    }

    int ans = 0;
    for (int i = 0; i < H*W; i++) {
        if (uf.root(i) != i) continue;
        ans += uf.sizeb[i] * uf.sizew[i];
    }
    cout << ans << endl;

    return 0;
}

