	{
		for (int j = 0; j < W; j++)
		{
			char anotherc;
			if (S[i][j] == '#') {
				anotherc = '.';
			}
			else {
				anotherc = '#';
			}
			for (int k = 0; k < nd; k++)
			{
				const int ti = i + d[k].first, tj = j + d[k].second;
				if (0 <= ti and 0 <= tj and S[ti][tj] == anotherc) {
					uf.unionSet(pair_to_int(pii(i, j)), pair_to_int(pii(ti, tj)));
				}
			}
		}
	}
	unordered_set<int> us;
