    }
  }

  UnionFind U(H*W);



  FOR(i,0,H-1){
    FOR(j,0,W-1){
      if(i!=H-1){
        if(m[i][j]!=m[i+1][j]){
          U.connect(i*W+j,(i+1)*W+j);
        }
      }
      if(j!=W-1){
        if(m[i][j]!=m[i][j+1]){
          U.connect(i*W+j,i*W+j+1);
        }
      }
    }
  }
  ll ans=0;

  ll b[H*W]={0};
  ll w[H*W]={0};


  FOR(i,0,H-1){
