      }else{
        w[U.root(i*W+j)]++;
      }


    }
  }

  FOR(i,0,H-1){
    FOR(j,0,W-1){

      ans=ans+b[i*W+j]*w[i*W+j];

    }
  }


  cout<<(ans)<<endl;
