#include <bits/stdc++.h>
using namespace std;
using ll = int64_t;

ll H, W;
vector<string> S;

bool isOK(ll x, ll y) {
    return 0 <= x && x < W && 0 <= y && y < H;
}

ll dx[] = {0, 1, 0, -1};
ll dy[] = {1, 0, -1, 0};

ll ans;

vector<vector<bool>> isvisit;

array<ll, 2> solve(ll x, ll y) {
    array<ll, 2> result{};
    result[S[y][x] == '.']++;
    isvisit[y][x] = true;
    for (ll i = 0; i < 4; i++) {
        ll nx = x + dx[i];
        ll ny = y + dy[i];
        if (isOK(nx, ny) && S[ny][nx] != S[y][x] && !isvisit[ny][nx]) {
            auto r = solve(nx, ny);
            result[0] += r[0];
            result[1] += r[1];
        }
    }
    return result;
}

int main() {
    cin >> H >> W;
    S.resize(H);
    for (ll i = 0; i < H; i++) {
        cin >> S[i];
    }

    isvisit.resize(H, vector<bool>(W, false));

    for (ll i = 0; i < H; i++) {
        for (ll j = 0; j < W; j++) {
            if (isvisit[i][j]) {
                continue;
            }
            auto r = solve(j, i);
            ans += r[0] * r[1];
        }
    }

    cout << ans << endl;
}

