struct UnionFind {
  UnionFind(size_t size) : v(size, -1) {}
  vector<int> v;

  int root(int x) {
    return (v[x] < 0 ? x : v[x] = root(v[x]));
  }

  bool is_root(int x) {
    return x == root(x);
  }

  bool same(int x, int y) {
    return root(x) == root(y);
  }

  void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x != y) {
      if (v[x] > v[y]) swap(x, y);
      v[x] += v[y];
      v[y] = x;
    }
  }

  int size(int x) {
    return -v[root(x)];
  }
};

int main(){
  int H, W;
  char s[405][405];
  int g[405][405];
  UnionFind uf(170000);

  cin >> H >> W;
  for(int i = 0; i < H; i++){
    for(int j = 0; j < W; j++){
      cin >> s[i][j];
    }
  }

  for(int i = 0; i < H; i++){
    for(int j = 0; j < W; j++){
      if(s[i][j] == '.') continue;
      for(int k = 0; k < 4; k++){
	int x = j + dx[k], y =i + dy[k];
	if(0 <= x && x <= W && 0 <= y && y < H && s[y][x] == '.'){
	  for(int l = 0; l < 4; l++){
	    int xx = x + dx[l], yy = y + dy[l];
	    if((xx == j && yy == i) || uf.same(i*H+j, yy*H+xx)) continue;
	    if(0 <= xx && xx < W && 0 <= yy && yy < H && s[yy][xx] == '#'){
	      // cerr << j << " " << i << " " << xx << " " << yy << endl;
	      uf.unite(i*H+j, yy*H+xx);
	    }
	  }
	}
      }
    }
  }

  for(int i = 0; i < H; i++){
    for(int j = 0; j < W; j++){
      if(s[i][j] == '.') continue;
      for(int k = 0; k < 4; k++){
	int x = j + dx[k], y =i + dy[k];
	if(0 <= x && x < W && 0 <= y && y < H && s[y][x] == '.'){
	  int cnt = uf.size(i * H + j);
	  // cerr << cnt << endl;
	  g[y][x] = max(g[y][x], cnt);	  
	}
      }
    }
  }

  ll ans = 0;
  for(int i = 0; i < H; i++){
    for(int j = 0; j < W; j++){
      ans += g[i][j];
      // cerr << g[i][j];
    }// cerr <<endl;
  }
  cout << ans << endl;
  return 0;
}

