  ll dx[4]={-1,1,0,0};
  ll dy[4]={0,0,-1,1};
  for(ll i=0;i<h;i++){
    for(ll j=0;j<w;j++){
      if(s[i][j]=='.'||used[i][j]==true)continue;
      ll c=0;
      ll d=0;
      queue<pair<ll,ll>> q;
      q.push(make_pair(i,j));
      used[i][j]=true;
      while(q.size()>0){
        pair<ll,ll> p=q.front();q.pop();
        ll pf=p.first,ps=p.second;
        //cout<<pf<<" "<<ps<<endl;
        if(s[pf][ps]=='#')c++;
        else d++;
        for(ll k=0;k<4;k++){
          ll in=pf+dy[k],jn=ps+dx[k];
          if(in<0||in>=h||jn<0||jn>=w||used[in][jn]==true)continue;
          if(s[pf][ps]==s[in][jn])continue;
          q.push(make_pair(in,jn));
          used[in][jn]=true;
        }
      }
      ans+=c*d;
      //cout<<c<<" "<<d<<endl;
    }
  }
  cout<<ans<<endl;
}

