int H, W;
vector<vector<int>> SS;
int writeCount;
int blackCount;

const int UNCHECKED_BLACK = 0;
const int CHECKED_BLACK = 1;
const int UNCHECKED_WRITE = -1;
const int CHECKED_WRITE = -2;

const int dx[4] = {0, 1, 0, -1};
const int dy[4] = {1, 0, -1, 0};

void checkAround(int x, int y) {
    if (SS[x][y] == UNCHECKED_WRITE) {
        writeCount++;
        SS[x][y] = CHECKED_WRITE;
    }
    if (SS[x][y] == UNCHECKED_BLACK) {
        blackCount++;
        SS[x][y] = CHECKED_BLACK;
    }

    for (int i = 0; i < 4; ++i) {
        int nx = x + dx[i];
        int ny = y + dy[i];

        if (nx < 0 || nx >= H || ny < 0 || ny >= W) {
            continue;
        }
        if ((SS[x][y] == CHECKED_WRITE && SS[nx][ny] == UNCHECKED_BLACK)
            || (SS[x][y] == CHECKED_BLACK && SS[nx][ny] == UNCHECKED_WRITE)) {
            checkAround(nx, ny);
        }
    }
}

int main() {
    cin >> H >> W;
    SS.resize(H);
    for (int i = 0; i < H; ++i) {
        SS[i].resize(W);
    }
    for (int i = 0; i < H; ++i) {
        string S;
        cin >> S;
        for (int j = 0; j < W; ++j) {
            int s;
            if (S[j] == '#') {
                s = UNCHECKED_BLACK;
            }
            if (S[j] == '.') {
                s = UNCHECKED_WRITE;
            }
            SS[i][j] = s;
        }
    }

    int result = 0;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (SS[i][j] == UNCHECKED_BLACK || SS[i][j] == UNCHECKED_WRITE) {
                writeCount = 0;
                blackCount = 0;
                checkAround(i, j);
                result += writeCount * blackCount;
            }

        }
    }
    cout << result << endl;

    return 0;
}

