int rec(const vvec<char> &board, vvec<bool> &reached, int y, int x, int h, int w)
{
    if (y > h || y <= 0 || x > w || x <= 0 || reached[y][x] || board[y][x] == ' ')
        return 0;

    reached[y][x] = true;
    //std::cout << y << " " << x << std::endl;

