    {
        ++ret;

        for (int i = -1; i <= 1; ++i)
            for (int j = -1; j <= 1; ++j)
            {
                if (abs(i) + abs(j) <= 1 && board[y + i][x + j] == black)
                    ret += rec(board, reached, y + i, x + j, h, w);
            }
    }
    else if (board[y][x] == black)
    {
        for (int i = -1; i <= 1; ++i)
            for (int j = -1; j <= 1; ++j)
            {
                if (abs(i) + abs(j) <= 1 && board[y + i][x + j] == white)
                    ret += rec(board, reached, y + i, x + j, h, w);
            }
    }

    //std::cout << std::endl;

    return ret;
}

