    UnionFind tree(hw);
    rep(i,hw){
      	int h=i/H;
        int w=i%H;
      if((h+w)%2==0){
        if((i-H)>=0 && c[i]!=c[i-H])tree.unite(i,i-H);
        if((i+H)<hw)if(c[i]!=c[i+H])tree.unite(i,i+H);
        if((w-1)>=0 && c[i]!=c[i-1])tree.unite(i,i-1);
        if((w+1)<W && c[i]!=c[i+1])tree.unite(i,i+1);
      }
    }
