        int a=ve[ve.size()];
        int e=1,o=0;
        ve.pop_back();
        for(auto x:ve){
            if(tree.same(a,x)){
                if(((x/H-a/H)%2+(x/H-a%H)%2)%2==0)e++;
                else o++;
                auto itr=find(all(ve),x);
                ve.erase(itr);
            }
        }
        sum+=e*o;
    }
    cout << sum;
}

