struct LLPoint {
	ll x = 0;
	ll y = 0;
	ll dist = 0;
	LLPoint() {}
	LLPoint(ll x, ll y, ll dist) {
		this->x = x;
		this->y = y;
		this->dist = dist;
	}
};

int main() {
	ll H;
	scanf("%lld", &H);
	ll W;
	scanf("%lld", &W);
	char arr[410][410] = { 0 };
	for (ll j = 0; j < H; j++) {
		scanf("%s", arr[j]);
	}

	ll result = 0;
	bool visited[410][410] = { 0 };

	for (ll j = 0; j < H; j++) {
		for (ll i = 0; i < W; i++) {
			if (visited[j][i] == false && arr[j][i] == '#') {
				//BFS
				queue<LLPoint> q;
				q.push(LLPoint(i, j, 0)); //dist0:# dist1:.
				visited[j][i] = true;
				ll black = 1;
				ll white = 0;

				while (q.empty() == false) {
					LLPoint p = q.front();
					q.pop();

					for (ll y = -1; y <= 1; y++) {
						for (ll x = -1; x <= 1; x++) {
							if (abs(x) + abs(y) > 1) {
								continue;
							}

							if (p.x + x < 0 || p.x + x >= W || p.y + y < 0 || p.y + y >= H) {
								continue;
							}

							if (visited[p.y + y][p.x + x] == true) {
								continue;
							}

							if ((p.dist + 1) % 2 == 0) {
								if (arr[p.y + y][p.x + x] == '.') {
									continue;
								}

								black++;
							}
							else {
								if (arr[p.y + y][p.x + x] == '#') {
									continue;
								}

								white++;
							}

							q.push(LLPoint(p.x + x, p.y + y, p.dist + 1));
							visited[p.y + y][p.x + x] = true;
						}
					}
				}

				result += black * white;
			}
		}
	}

	printf("%lld\n", result);
}

