typedef long long ll;

ll bfs(vector<string> &maze, vector<vector<bool> > &isVisited, ll i, ll j, ll H, ll W){
    if (isVisited[i][j]){
        return 0;
    }
    vector<ll> dx(4);
    dx[0] = 1;
    dx[1] = 0;
    dx[2] = -1;
    dx[3] = 0;
    vector<ll> dy(4);
    dy[0] = 0;
    dy[1] = 1;
    dy[2] = 0;
    dy[3] = -1;
    queue<pair<ll,ll> > que;
    que.push(pair<ll,ll> (i,j));
    ll black = 0;
    ll white = 0;
    if (maze[i][j] == '#') black++;
    if (maze[i][j] == '.') white++;
    isVisited[i][j] = true;
    while(que.size() != 0){
        pair<ll,ll> p = que.front();
        que.pop();
        rep(a,4){
            ll nx = p.second + dx[a];
            ll ny = p.first + dy[a];
            if (0 <= nx && nx < W && 0 <= ny && ny < H && maze[ny][nx] != maze[p.first][p.second] && !isVisited[ny][nx]){
                que.push(pair<ll,ll>(ny,nx));
                if (maze[ny][nx] == '#') black++;
                if (maze[ny][nx] == '.') white++;
                isVisited[ny][nx] = true;
            }
        }
    }
    ll ans = black * white;
    return ans;
}
int main(){
    ll H,W;
    cin >> H >> W;
    vector<string> maze(H);
    rep(i,H){
        cin >> maze[i];
    }
    vector<vector<bool> > isVisited(H,vector<bool> (W));
    rep(i,H){
        rep(j,W){
            isVisited[i][j] = false;
        }
    }
    ll ans = 0;
    rep(i,H){
        rep(j,W){
            ans += bfs(maze, isVisited, i, j, H, W);
        }
    }
    cout << ans << endl;
}

