using namespace std;
typedef long long ll;

pair<int, int> DFS(int x, int y, vector<string> &map, vector<vector<int>> &ok) {
	pair<int, int> ans = make_pair(0, 0), p;
	ok[y][x] = false;
	if (y > 0 && ok[y - 1][x] && map[y - 1][x] != map[y][x]) {
		p = DFS(x, y - 1, map, ok);
		ans.first += p.first;
		ans.second += p.second;
	}
	if (x > 0 && ok[y][x - 1] && map[y][x - 1] != map[y][x]) {
		p = DFS(x - 1, y, map, ok);
		ans.first += p.first;
		ans.second += p.second;
	}
	if (y < map.size() - 1 && ok[y + 1][x] && map[y + 1][x] != map[y][x]) {
		p = DFS(x, y + 1, map, ok);
		ans.first += p.first;
		ans.second += p.second;
	}
	if (x < map[0].size() - 1 && ok[y][x + 1] && map[y][x + 1] != map[y][x]) {
		p = DFS(x + 1, y, map, ok);
		ans.first += p.first;
		ans.second += p.second;
	}
	if (map[y][x] == '.')
		ans.first++;
	else
		ans.second++;
	return ans;
}

int main(void) {
	int h, w, num, i, j, ans = 0;
