    }

    FOR(i,0,H-1){
      FOR(j,0,W-1){
        if(i==H-1){
          if(j!=W-1){
            if(shapmap[i][j]!=shapmap[i][j+1]) uf.merge(i*W+j, i*W+j+1);
          }
        } else if(j==W-1){
          if(shapmap[i][j]!=shapmap[i+1][j]) uf.merge(i*W+j, (i+1)*W+j);
        } else {
          if(shapmap[i][j]!=shapmap[i+1][j]) uf.merge(i*W+j, (i+1)*W+j);
          if(shapmap[i][j]!=shapmap[i][j+1]) uf.merge(i*W+j, i*W+j+1);
        }
      }
    }


    map<ll,ll> bombnum;

