class UF
{
private:
	vector<int> parent;
	vector<int> black;
	vector<int> white;

public:
	UF(int n)
	{
		parent = vector<int>(n, -1);
		black = vector<int>(n, 0);
		white = vector<int>(n, 0);
	}

	int getParent(int x)
	{
		if(parent[x] == -1) return x;
		else return parent[x] = getParent(parent[x]);
	}

	int getBlack(int x)
	{
		return black[getParent(x)];
	}

	int getWhite(int x)
	{
		return white[getParent(x)];
	}

	void update(int x, int y)
	{
		x = getParent(x);
		y = getParent(y);
		if(x == y) return;
		if(x > y) swap(x, y);
		parent[y] = x;
		black[x] += black[y];
		white[x] += white[y];
	}

	void addBlack(int x)
	{
		black[x]++;
	}

	void addWhite(int x)
	{
		white[x]++;
	}

};

int main()
{
	int h, w;
	cin >> h >> w;
	UF uf(h * w);
	char s[401][401];
	for(int i = 0; i < h; i++){
		for(int j = 0; j < w; j++){
			cin >> s[i][j];
			if(s[i][j] == '.') uf.addWhite(w * i + j);
			else uf.addBlack(w * i + j);
		}
	}

	int dx[4] = {1, 0, -1, 0};
	int dy[4] = {0, 1, 0, -1};
	for(int i = 0; i < h; i++){
		for(int j = 0; j < w; j++){
			for(int k = 0; k < 4; k++){
				int nx = i + dx[k];
				int ny = j + dy[k];
				if(nx < 0 || ny < 0 || nx >= h || ny >= w) continue;
				if(s[i][j] != s[nx][ny]){
					uf.update(i * w + j, nx * w + ny);
				}
			}
		}
	}
	long long int ans = 0;
	for(int i = 0; i < h * w; i++){
		// cout << uf.getParent(i) << " " << uf.getBlack(i) << " " << uf.getWhite(i) << endl;
		if(uf.getParent(i) == i) ans += uf.getBlack(i) * uf.getWhite(i);
	}
	cout << ans << endl;
}

