  auto uf = UnionFind(H * W);
  REP(i, H) REP(j, W) {
    if (i > 0 && A[i][j] + A[i - 1][j] == 1)
      uf.unite((i - 1) * W + j, i * W + j);
    if (j > 0 && A[i][j] + A[i][j - 1] == 1)
      uf.unite(i * W + j, i * W + j - 1);
  }

  REP(i, H * W) B[uf.root(i)][A[i / W][i % W]]++;
  REP(i, H * W) count += B[i][0] * B[i][1];

  cout << count << endl;
  return 0;
}

