ll rot(string s[],ll h,ll w,ll n,ll m){
    ll cnt=0;
    if(s[h][w]=='#'){
        if(h>0&&s[h-1][w]=='.'&&memo[h-1][w]==0){
            cnt++;
          	memo[h][w]=1;
            cnt+=rot(s,h-1,w,n,m);
        }
        if(h<n-1&&s[h+1][w]=='.'&&memo[h+1][w]==0){
            cnt++;
          	memo[h][w]=1;
            cnt+=rot(s,h+1,w,n,m);
        }
        if(w>0&&s[h][w-1]=='.'&&memo[h][w-1]==0){
            cnt++;
          memo[h][w]=1;
            cnt+=rot(s,h,w-1,n,m);
        }
        if(w<m-1&&s[h][w+1]=='.'&&memo[h][w+1]==0){
            cnt++;
          memo[h][w]=1;
            cnt+=rot(s,h,w+1,n,m);
        }
    }else if(s[h][w]=='.'){
        if(h>0&&s[h-1][w]=='#'&&memo[h-1][w]==0){
          	memo[h][w]=1;
            cnt+=rot(s,h-1,w,n,m);
        }
        if(h<n-1&&s[h+1][w]=='#'&&memo[h+1][w]==0){
          	memo[h][w]=1;
            cnt+=rot(s,h+1,w,n,m);
        }
        if(w>0&&s[h][w-1]=='#'&&memo[h][w-1]==0){
          memo[h][w]=1;
            cnt+=rot(s,h,w-1,n,m);
        }
        if(w<m-1&&s[h][w+1]=='#'&&memo[h][w+1]==0){
          memo[h][w]=1;
            cnt+=rot(s,h,w+1,n,m);
        }
    }
  //cout<<s[n-2][m-1]<<endl;
  memo[h][w]=0;
  return cnt;
}
