ll RS(ll N,ll P){
    if(P==0){
        return 1;
    }else{
        if(P%2==0){
            ll t=RS(N,P/2);
            return t*t;
        }else{
            return N*RS(N,P-1);
        }
    }
}
 struct UnionFind{
     vi d;
     vi cntWhite;
     UnionFind(int n):d(n,-1),cntWhite(n,0){};
     int deb(int x){
         return d[x];
     }
     int root(int x){
         if(d[x]<0)return x;
         return d[x]=root(d[x]);
     }
     int unite(int x,int y){
         x=root(x);y=root(y);
         if(d[x]>d[y])swap(x,y);
         d[x]+=d[y];
         cntWhite[x]+=cntWhite[y];
         d[y]=x;
         return true;
     }
     bool same(int x,int y){return root(x)==root(y);}
     int size(int x){return -d[root(x)];}
 };
int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
    int H,W;
    cin>>H>>W;
    vector<string> S(H);
    REP(i,H)cin>>S[i];

    //マスをノードと考え移動できるマス同士をパスで繋いでいく
    //木のサイズから答えを求める
    UnionFind uf(H*W);
    //各マスに対して自分から下に行けるかチェック

    REP(ih,H){
        REP(iw,W){
            if(S[ih][iw]=='#')uf.cntWhite[ih*W+iw]++;
        }
    }
    REP(i,(H-1)*W){
        int x,y;x=i%W;y=i/W;
        if(S[y][x]!=S[y+1][x]){
            uf.unite(i,i+W);
        }
    }
    //各マスに対して自分から右に行けるかチェック
    REP(i,H*W){
        if(i%W==W-1)continue;
        int x,y;x=i%W;y=i/W;
        if(S[y][x]!=S[y][x+1]){
            if(!uf.same(i,i+1))uf.unite(i,i+1);
        }
    }
    ll ans=0;
    REP(i,H*W){
        if(uf.root(i)!=i)continue;
        ll s=uf.cntWhite[i];
        ans+=(uf.size(i)-s)*s;
    }
    cout<<ans<<endl;
  return 0;
}

