int main() {
    int h, w;
    cin >> h >> w;
    vvi b(h, vi(w));
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            char c;
            cin >> c;
            if (c == '#') b[i][j] = 1;
        }
    }

    vvi visited(h, vi(w));
    using ii = pair<int, int>;

    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};
    function<bool(int, int)> valid = [&](int x, int y) {
        return 0 <= x && x < h && 0 <= y && y < w;
    };

    int black, white;

    function<void(ii)> dfs = [&](ii v) {
        int x = v.first, y = v.second;
        visited[x][y] = 1;
        if (b[x][y]) black++;
        else white++;
        for (int i = 0; i < 4; i++) {
            int xx = x + dx[i];
            int yy = y + dy[i];
            if (valid(xx, yy) && !visited[xx][yy] && b[x][y] != b[xx][yy]) {
                dfs(ii(xx, yy));
            }
        }
    };

    i64 cnt = 0;

    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (!visited[i][j]) {
                black = 0, white = 0;
                dfs(ii(i, j));
                cnt += black * white;
            }
        }
    }

    cout << cnt << endl;
}

