int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    clock_t tStart = clock();
    int test;
    test = 1;
    // cin >> test;
    while (test--) {
        ll a, b;
        cin >> a >> b;
        vector<string> arr(a);
        for (ll i = 0; i < a; i++)
            cin >> arr[i];

        ll ans = 0;

        bool visitedsharp[a][b];
        for (ll i = 0; i < a; i++) {
            for (ll j = 0; j < b; j++)
                visitedsharp[i][j] = 0;
        }

        for (ll ix = 0; ix < a; ix++) {
            for (ll jx = 0; jx < b; jx++) {

                if (arr[ix][jx] == '#' && !visitedsharp[ix][jx]) {

                    visitedsharp[ix][jx] = 1;
                    map<pll, bool> m;
                    m[{ ix, jx }] = 1;
                    ll cnt = 0;
                    queue<pll> q;
                    bool visited[a][b];
                    for (ll i = 0; i < a; i++) {
                        for (ll j = 0; j < b; j++) {
                            visited[i][j] = 0;
                        }
                    }

                    q.push({ ix, jx });
                    visited[ix][jx] = 1;
                    /* trace("mainx,mainy", ix, jx); */

                    while (!q.empty()) {

                        auto node = q.front();
                        q.pop();
                        ll x = node.ff, y = node.ss;

                        for (ll i = -1; i <= 1; i++) {
                            for (ll j = -1; j <= 1; j++) {
                                if (abs(i) == abs(j))
                                    continue;
                                if (validxy(x + i, y + j, a, b) && !visited[x + i][y + j]) {
                                    if (arr[x][y] == '#' && arr[x + i][y + j] == '.') {
                                        visited[x + i][y + j] = 1;
                                        cnt++;
                                        /* trace("foundx,foundy", x + i, y + j); */
                                        q.push({ x + i, y + j });
                                    } else if (arr[x][y] == '.' && arr[x + i][y + j] == '#') {
                                        q.push({ x + i, y + j });
                                        visited[x + i][y + j] = 1;
                                        m[{ x + i, y + j }] = 1;
                                        visitedsharp[x + i][y + j] = 1;
                                    }
                                }
                            }
                        }
                    }

                    ans += m.size() * cnt;
                }
            }
        }
        cout << ans << endl;
    }
#ifdef LOCAL_DEFINE
    printf("Time taken: %.2fs\n", (double)(clock() - tStart) / CLOCKS_PER_SEC);
#endif
    return 0;
}

