#include<bits/stdc++.h>
using namespace std;

static const int INF=1e9;
static const int MOD=1000000007;
typedef long long ll;
typedef pair<int,int> P;

int H,W;
int dist[410][410];
int dx[4]={-1,1,0,0};
int dy[4]={0,0,-1,1};
char s[410][410];
bool used[410][410]={};

long long bfs(int x,int y){
    long long w=0;long long b=0;
    queue<P> que;
    que.push({x,y});
    used[x][y]=true;
    while(!que.empty()){
        P q=que.front(); que.pop();
        if(s[q.first][q.second]=='.') w++;
        else b++;
        for(int i=0;i<4;i++){
            int nx=q.first+dx[i]; int ny=q.second+dy[i];
            if(nx>=0&ny>=0&&nx<H&&ny<W){
                if(used[nx][ny]==true) continue;
                if(s[q.first][q.second]==s[nx][ny]) continue;
                used[nx][ny]=true;
                que.push({nx,ny});
            }
        }
    }
    return w*b;
}

int main(){
    cin >> H >> W;
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            cin >> s[i][j];
        }
    }
    long long ans=0;
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            if(s[i][j]=='.') continue;
            if(used[i][j]) continue;
            ans+=bfs(i,j);
        }
    }
    cout << ans << endl;
}

