int bfs(int sy, int sx, const vector<string>& s, int h, int w) {
	queue<pair<int, int>> que;
	que.push(make_pair(sy, sx));
	used[sy][sx] = true;
	set<pair<int, int>> st;

	int black = 0, white = 0;

	while (not que.empty()) {
		int y = que.front().first, x = que.front().second;
		que.pop();
		if (s[y][x] == '#') black++;
		else white++;

		rep(i, 4) {
			int ny = y + dy[i];
			int nx = x + dx[i];
			if (not (0 <= ny && ny < h && 0 <= nx && nx < w))
				continue;
			if (s[y][x] != s[ny][nx] && not used[ny][nx]) {
				used[ny][nx] = true;
				st.insert(make_pair(ny, nx));
				que.push(make_pair(ny, nx));
			}
		}
	}
	return black * white;
}

