char maze[410][410];
bool isReached[410][410];
int H, W;
int dh [] = {1, -1, 0, 0};
int dw [] = {0, 0, 1, -1};
int B_cnt = 0;
int W_cnt = 0;
int ans = 0;

vector<pair<int, int>> start;
vector<pair<int, int>> nums;

void dfs(int h, int w, string color) {
    isReached[h][w] = true;

    if (color == "B") {
        B_cnt += 1;
    } else {
        W_cnt += 1;
    }

    rep(i, 4) {
        int nh = h + dh[i];
        int nw = w + dw[i];
        if (0 <= nh and nh < H and 0 <= nw and nw < W) {
            if (isReached[nh][nw] == false) {
                if (color == "B" and maze[nh][nw] == '.') {
                    dfs(nh, nw, "W");
                }

                if (color == "W" and maze[nh][nw] == '#') {
                    dfs(nh, nw, "B");
                }
            }
        }
    }
}

int main() {
    cin >> H >> W;
    rep(i, H) rep(j, W) {
        cin >> maze[i][j];
        if (maze[i][j] == '.') {
            start.emplace_back(i, j);
        }
    }

    for(auto p: start) {
        B_cnt = 0;
        W_cnt = 0;
        if (isReached[p.first][p.second] == false) {
            dfs(p.first, p.second, "W");
            nums.emplace_back(B_cnt, W_cnt);
        }
    }

    for(auto p: nums) {
        ans += p.first * p.second;
    }

    cout << ans << endl;
}

