void dfs(int i, int j, int &g, int pi=-1, int pj=-1){
  if(seen[i][j]==1) return;
  if(i<0 || i>=h || j<0 || j>=w) return;
  if(pi!=-1 && grid[pi][pj]==grid[i][j]) return;
  seen[i][j]=1;
  gr[g].push_back(make_pair(i,j));
  dfs(i+1,j,g,i,j);
  dfs(i-1,j,g,i,j);
  dfs(i,j+1,g,i,j);
  dfs(i,j-1,g,i,j);
}

