pair<long, long> move(int y, int x){
    if(space[y][x] == 'x'){
        return {0, 0};
    }
    pair<long, long> ans = {0, 0};
    if(space[y][x] == '#'){
        ans.first++;
    }else{
        ans.second++;
    }
    char tmp = space[y][x];
    space[y][x] = 'x';
    for(int i = 0; i < 4; i++){
        if(tmp != space[y + mv[i].y][x + mv[i].x] && space[y + mv[i].y][x + mv[i].x] != 'x'){
            pair<long, long> next = move(y + mv[i].y, x + mv[i].x);
            ans.first += next.first;
            ans.second += next.second;
        }
    }
    return ans;
}

