    if(!grid[i][j])
    {
        cntw++;
        if(j+1<w && grid[i][j+1] && !vis[i][j+1])
            traverse(i,j+1);
        if(j-1>=0 && grid[i][j-1] && !vis[i][j-1])
            traverse(i,j-1);
        if(i+1<h && grid[i+1][j] && !vis[i+1][j])
            traverse(i+1,j);
        if(i-1>=0 && grid[i-1][j] && !vis[i-1][j])
            traverse(i-1,j);
    }
    else
    {
        cntb++;
        if(j+1<w && !grid[i][j+1] && !vis[i][j+1])
            traverse(i,j+1);
        if(j-1>=0 && !grid[i][j-1] && !vis[i][j-1])
            traverse(i,j-1);
        if(i+1<h && !grid[i+1][j] && !vis[i+1][j])
            traverse(i+1,j);
        if(i-1>=0 && !grid[i-1][j] && !vis[i-1][j])
            traverse(i-1,j);
    }

}

