	for (int i = 0; i < H; i++)
	{
		for (int j = 0; j < W; j++)
		{
			char anotherc;
			if (S[i][j] == '#') {
				anotherc = '.';
			}
			else {
				anotherc = '#';
			}
			for (int k = 0; k < nd; k++)
			{
				const int ti = i + d[k].first, tj = j + d[k].second;
				if (0 <= ti and 0 <= tj and S[ti][tj] == anotherc) {
					uf.unionSet(pair_to_int(i, j), pair_to_int(ti, tj));
				}
			}
		}
	}
	unordered_set<int> us;
	for (int l = 0; l < H*W; l++)
	{
		us.insert(l);
	}
	ll ans = 0;
	for (int i = 0; i < H; i++)
	{
		for (int j = 0; j < W; j++)
		{
			const int ij = pair_to_int(pii(i, j));
			if (us.find(uf.root(ij)) == us.end())
				continue;
			int nb = uf.size_black(ij), nw = uf.size(ij) - nb;
			ans += nb * nw;
			us.erase(uf.root(ij));
		}
	}
	cout << ans << endl;
	return 0;
}

