//-----CODE------//
void DFS(int V,vector<vector<int> > &GRAPH,vector<int> & visited,vector<vector<char> > & mat,int & nB,int &nW,int WIDTH)
{
  if(mat[V/WIDTH][V%WIDTH] == '.')nW++;
  else nB++;
  visited[V] = 1;
  for (auto &&nV : GRAPH[V])
  {
    if(visited[nV] == 1)continue;
    DFS(nV,GRAPH,visited,mat,nB,nW,WIDTH);
  }
  return;
}
//-----CODE------//
void solve(void)
{ 
  int H,W; cin>>H; cin>>W; 
  vector<vector<char> >  mat (H,vector<char>(W,0));
  for (int i = 0; i < H; i++)
  {
    for (int j = 0; j < W; j++)
    {
       cin>>mat[i][j];
    }
  }
  int N = H*W;
  vector<vector<int> > GRAPH (H*W);
  for (int i = 0; i < H; i++)
  {
    for (int j = 0; j < W; j++)
    {
      if(i != 0)
      {
        if(mat[i][j] != mat[i-1][j])
        {
          int V = i*W + j;
          int nV = (i-1)*W+j;
          GRAPH[V].emplace_back(nV);
          GRAPH[nV].emplace_back(V);
        }
      }
      if(i != H - 1)
      {
        if(mat[i][j] != mat[i+1][j])
        {
          int V = i*W + j;
          int nV = (i+1)*W+j;
          GRAPH[V].emplace_back(nV);
          GRAPH[nV].emplace_back(V);
        }
      }
      if(j != 0)
      {
        if(mat[i][j] != mat[i][j-1])
        {
          int V = i*W + j;
          int nV = (i)*W+j-1;
          GRAPH[V].emplace_back(nV);
          GRAPH[nV].emplace_back(V);
        }
      }
      if(j != W -1)
      {
        if(mat[i][j] != mat[i][j+1])
        {
          int V = i*W + j;
          int nV = (i)*W+j+1;
          GRAPH[V].emplace_back(nV);
          GRAPH[nV].emplace_back(V);
        }
      }

    }

  }
  vector<int> visited (H*W,-1);
  int ANS = 0;
  for (int i = 0; i < H*W; i++)
  {
    int V = i;
    int nB = 0;
    int nW = 0;
    DFS(V,GRAPH,visited,mat,nB,nW,W);
    ANS += nB * nW;
  }
  cout<<ANS<<endl;


  return;
}
