int numB = 0, numC = 0;

void dfs(int x, int y){
   if(x < H-1 && visited[x+1][y] == 0 && clr[x][y] != clr[x+1][y]){
      if(clr[x+1][y] == '#') numB++;
      else numC++;

      visited[x+1][y] = 1;
      dfs(x+1, y);
   }
   if(x > 0 && visited[x-1][y] == 0 && clr[x][y] != clr[x-1][y]){
      if(clr[x-1][y] == '#') numB++;
      else numC++;
      visited[x-1][y] = 1;
      dfs(x-1, y);
   }
   if(y < W-1 && visited[x][y+1] == 0 && clr[x][y] != clr[x][y+1]){
      if(clr[x][y+1] == '#') numB++;
      else numC++;
      visited[x][y+1] = 1;
      dfs(x, y+1);
   }
   if(y > 0 && visited[x][y-1] == 0 && clr[x][y] != clr[x][y-1]){
      if(clr[x][y-1] == '#') numB++;
      else numC++;
      visited[x][y-1] = 1;
      dfs(x, y-1);
   }
}

void clean(){
   for(int i = 0; i < H; i++){
      for(int j = 0; j < W; j++){
         if(visited[i][j] == 1)
            visited[i][j] = -1;
      }
   }
}

