      for(int j = 0; j < W; j++){
         if(visited[i][j] != -1 && clr[i][j] == '#'){
            numB++;
            visited[i][j] = 1;
            dfs(i, j);
         }
         ans += numB*numC;
         numB = 0; numC = 0;
         clean();
      }
   }
   cout << ans << endl;
}

