struct P {
    ll x;
    ll y;
    ll encode() {
        return x + y * W;
    }
    static P decode(ll code) {
        return {code % W, code / W};
    }
};

pair<ll, ll> collect(P now) {
    visited[now.encode()] = true;
    pair<ll, ll> ans;
    if (grid[now.x][now.y] == '#') {
        ans.first++;
    } else {
        ans.second++;
    }
    rep(d,0,4) {
        P vec;
        if (d == 0) {
            vec = {-1, 0};
        } else if (d == 1) {
            vec = {1, 0};
        } else if (d == 2) {
            vec = {0, 1};
        } else {
            vec = {0, -1};
        }
        P next = {now.x + vec.x, now.y + vec.y};
        if (!(0 <= next.x && next.x < W && 0 <= next.y && next.y < H)) {
            continue;
        }
        if (visited[next.encode()]) {
            continue;
        }
        if (grid[now.x][now.y] == grid[next.x][next.y]) {
            continue;
        }
        pair<ll,ll> ans_sub = collect(next);
        ans.first += ans_sub.first;
        ans.second += ans_sub.second;
    }
    return ans;
}

