struct Grid {
    int h, w;
    vector<vector<char>> grid;
    vector<vector<bool>> seen;

    void init(int H, int W) {
        h = H;
        w = W;
        grid.assign(H, vector<char>(W));
        seen.assign(H, vector<bool>(W, false));
    }

    void input(){
        for(int i = 0; i < (int)grid.size(); i++) {
            for(int j = 0; j < (int)grid[i].size(); j++) {
                cin >> grid[i][j];
            }
        }
    }

    bool isin(int i, int j) {
        return i >= 0 && i < h && j >= 0 && j < w;
    }

    bool isseen(int i, int j) {
        return i >= 0 && i < h && j >= 0 && j < w && !seen[i][j];
    }
};

int h, w;
Grid g;
int cnt[2];
ll ans = 0;

void dfs(int i, int j, int dis) {
    g.seen[i][j] = true;
    if(g.grid[i][j] == '#') {
        cnt[0]++;
    }else{
        cnt[1]++;
    }

    for(int k = 0; k < 4; k++) {
        int ni = i + dx[k];
        int nj = j + dy[k];
        if(g.isseen(ni, nj)) {
            if(dis&1 && g.grid[ni][nj]=='#') dfs(ni, nj, dis+1);
            if(dis&1^1 && g.grid[ni][nj]=='.') dfs(ni, nj, dis+1);
        }
    }
}

int main() {
    cin >> h >> w;
    g.init(h, w);
    g.input();
    for(int i = 0; i < h; i++) for(int j = 0; j < w; j++) {
        if(g.grid[i][j] == '.' && !g.seen[i][j]) {
            memset(cnt, 0, sizeof(cnt));
            dfs(i, j, 1);
            ans += 1LL * cnt[0] * cnt[1];
        }
    }
    cout << ans << endl;
}

