int move_h[4] = {-1, 1, 0, 0};
int move_w[4] = {0, 0, -1, 1};

int main(){
    int H;
    int W;
    cin >> H >> W;
    for(int i=0; i < H; i++){
        cin >> grid[i];
    }

    long long ans = 0;
    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            if(used[i][j]){
                continue;
            }
            queue <pair <int, int> > q;
            q.push(make_pair(i, j));
            used[i][j] = true;
            long long black_num = 0;
            long long white_num = 0;
            while(!q.empty()){
                auto cur = q.front();
                q.pop();
                int cur_h = cur.first;
                int cur_w = cur.second;
                if(grid[cur_h][cur_w] == '.'){
                    white_num ++;
                } else {
                    black_num ++;
                }
                for(int i = 0; i < 4; i++){
                    int next_h = cur_h + move_h[i];
                    int next_w = cur_w + move_w[i];
                    if(0 <= next_h && next_h < H && 0 <= next_w && next_w < W
                        && !used[next_h][next_w] && grid[next_h][next_w] != grid[cur_h][cur_w]){
                        q.push(make_pair(next_h, next_w));
                        used[next_h][next_w] = true;

                    }
                }

            }
            ans += black_num * white_num;
        }
    }    

    cout << ans << endl;
    return 0;
}

