void Search(vector<pair<int, int>> &wAndB, int row, int column, char *str, int *tansakuzumi, int H, int W) {
  //printf("row%d, column%d\n", row, column);
  int nextRow, nextColumn;
  if (*(str + W * row + column) == '.') {
    wAndB.back().first++;
  } else {
    wAndB.back().second++;
  }
  nextRow = row - 1;
  nextColumn = column;
  if (nextRow >= 0 && *(tansakuzumi + W * nextRow + nextColumn) != 1 && *(str + W * row + column) != *(str + W * nextRow + nextColumn)) {
    *(tansakuzumi + W * nextRow + nextColumn) = 1;
    Search(wAndB, nextRow, nextColumn, str, tansakuzumi, H, W);
  }
  nextRow = row;
  nextColumn = column + 1;
  if (nextColumn < W && *(tansakuzumi + W * nextRow + nextColumn) != 1 && *(str + W * row + column) != *(str + W * nextRow + nextColumn)) {
    *(tansakuzumi + W * nextRow + nextColumn) = 1;
    Search(wAndB, nextRow, nextColumn, str, tansakuzumi, H, W);
  }
  nextRow = row + 1;
