        if (p->tmp[sy][sx] != -1)
            return p->tmp[sy][sx];

        char flag[400][400] = { 0 };

        flag[sy][sx] = 1;

std::vector<Point> vec1, vec2;
std::vector<Point> * src, * dst;

src = &vec1;
dst = &vec2;

src->push_back((Point){sx, sy});

        for (char nex = CHAR_STR; ;)
        {
            if (nex == CHAR_STR)
                nex = CHAR_END;
            else
                nex = CHAR_STR;

            for (auto it = src->begin(); it != src->end(); it++)
            {
                for (int i = 0; i < 4; i++)
                {
                    int x = it->x, y = it->y;
                    switch (i)
                    {
                    case 0: x += 1; break;
                    case 1: y += 1; break;
                    case 2: x -= 1; break;
                    case 3: y -= 1; break;
                    }
                    if ((x < 0) || (x >= p->w) || (y < 0) || (y >= p->h)) continue;
                    if (flag[y][x] != 0) continue;

                    if (p->map[y][x] == nex)
                    {
                        flag[y][x] = 1;
                        dst->push_back((Point){x, y});
                    }
                    else
                        flag[y][x] = -1;
                } // i
            } // vector

            if (dst->size() == 0)
                break;
            src->clear();
            if (src == &vec1)
            {
                src = &vec2;
                dst = &vec1;
            }
            else
            {
                src = &vec1;
                dst = &vec2;
            }
        } // do-while abort

        int ret = 0;
        for (int y = 0; y < p->h; y++)
            for (int x = 0; x < p->w; x++)
                if ((p->map[y][x] == CHAR_END) && (flag[y][x] == 1))
                    ret++;

        for (int y = 0; y < p->h; y++)
            for (int x = 0; x < p->w; x++)
                if ((p->map[y][x] == CHAR_STR) && (flag[y][x] == 1))
                    p->tmp[y][x] = ret;

        return ret;
    }

    int main(int argc, char * argv[])
    {
        Parameter p;
        int ret = 0;

        std::cin >> p.h;
        std::cin >> p.w;
        for (int y=0; y<p.h; y++)
            for (int x=0; x<p.w; x++)
                std::cin >> p.map[y][x];

        for (int y=0; y<p.h; y++)
            for (int x=0; x<p.w; x++)
                p.tmp[y][x] = -1;

        for (int y=0; y<p.h; y++)
        {
            for (int x=0; x<p.w; x++)
            {
                if (p.map[y][x] == CHAR_STR)
                    ret += count_to_goal(&p, x, y);
            }
        }

        std::cout << ret;

        return 0;
    }

