void dfs(int h, int w) {
    seen[h][w] = true;
    if (G[h][w] == '.') cnt_w++;
    else cnt_b++;

    for (int dir = 0; dir < 4; ++dir) {
        int nh = h + dx[dir];
        int nw = w + dy[dir];

        if (nh < 0 || nh >= H || nw < 0 || nw >= W) continue;
        if (G[nh][nw] == G[h][w]) continue;

        if (seen[nh][nw]) continue;

        dfs(nh, nw);
    }

    return;
}

