	// 定数時間初期化配列
	template<typename _Vt, size_t _Sz>
	class ValArray : public array<_Vt, _Sz> {
	public:
		ValArray() = default;
		ValArray(const _Vt& initVal) : mCurrentNum(1), mInitVal(initVal) { std::fill(mNums.begin(), mNums.end(), 0); }
		inline void setInitVal(const _Vt& initVal) { mInitVal = initVal; }
		inline void init() { ++mCurrentNum; }
		inline _Vt& read(size_t index) { return (mNums[index] == mCurrentNum) ? array<_Vt, _Sz>::operator[](index) : mInitVal; }
		inline void write(size_t index, const _Vt& val) { mNums[index] = mCurrentNum; array<_Vt, _Sz>::operator[](index) = val; }
	private:
		inline _Vt& operator[](size_t _Pos) { return array<_Vt, _Sz>::operator[](_Pos); } // 封印
		_Vt mInitVal;
		array<int, _Sz> mNums;
		int mCurrentNum;
	};

	// 定数時間初期化配列２次元
	template<typename _Vt, size_t _Sz1, size_t _Sz2>
	class ValArray2D : public array<array<_Vt, _Sz2>, _Sz1> {
	public:
		ValArray2D() = default;
		ValArray2D(const _Vt& initVal) : mCurrentNum(1), mInitVal(initVal) { for (array<int, _Sz2>& t1 : mNums) std::fill(t1.begin(), t1.end(), 0); }
		inline void setInitVal(const _Vt& initVal) { mInitVal = initVal; }
		inline void init() { ++mCurrentNum; }
		inline _Vt& read(size_t index1, size_t index2) { return (mNums[index1][index2] == mCurrentNum) ? array<array<_Vt, _Sz2>, _Sz1>::operator[](index1)[index2] : mInitVal; }
		inline void write(size_t index1, size_t index2, const _Vt& val) { mNums[index1][index2] = mCurrentNum; array<array<_Vt, _Sz2>, _Sz1>::operator[](index1)[index2] = val; }
	private:
		inline _Vt& operator[](size_t _Pos) { return array<array<_Vt, _Sz2>, _Sz1>::operator[](_Pos); } // 封印
		_Vt mInitVal;
		array<array<int, _Sz2>, _Sz1> mNums;
		int mCurrentNum;
	};

	// 定数時間初期化配列３次元
	template<typename _Vt, size_t _Sz1, size_t _Sz2, size_t _Sz3>
	class ValArray3D : public array<array<array<_Vt, _Sz3>, _Sz2>, _Sz1> {
	public:
		ValArray3D() = default;
		ValArray3D(const _Vt& initVal) : mCurrentNum(1), mInitVal(initVal) { for (array<array<int, _Sz3>, _Sz2>& t1 : mNums) for (array<int, _Sz3>& t2 : t1) std::fill(t2.begin(), t2.end(), 0); }
		inline void setInitVal(const _Vt& initVal) { mInitVal = initVal; }
		inline void init() { ++mCurrentNum; }
		inline _Vt& read(size_t index1, size_t index2, size_t index3) { return (mNums[index1][index2][index3] == mCurrentNum) ? array<array<array<_Vt, _Sz3>, _Sz2>, _Sz1>::operator[](index1)[index2][index3] : mInitVal; }
		inline void write(size_t index1, size_t index2, size_t index3, const _Vt& val) { mNums[index1][index2][index3] = mCurrentNum; array<array<array<_Vt, _Sz3>, _Sz2>, _Sz1>::operator[](index1)[index2][index3] = val; }
	private:
		inline _Vt& operator[](size_t _Pos) { return array<array<array<_Vt, _Sz3>, _Sz2>, _Sz1>::operator[](_Pos); } // 封印
		_Vt mInitVal;
		array<array<array<int, _Sz3>, _Sz2>, _Sz1> mNums;
		int mCurrentNum;
	};

