int h, w;
vector<vector<char>> s;
vector<vector<ll>> memo;
vector<vector<int>> memoid;
int memoIndex = 0;
ValArray2D<bool, 400, 400> check;

bool isOver(int x, int y) {
	return x < 0 || x >= w || y < 0 || y >= h;
}
bool isOver(Point p) {
	return p.x < 0 || p.x >= w || p.y < 0 || p.y >= h;
}
bool canMove(Point a, Point b) {
	return s[a.y][a.x] != s[b.y][b.x];
}

vector<Point> posList;
uset<int> usedMemoId;

ll calc(int y, int x) {
	posList.push_back(Point(x, y));
	if (memo[y][x] >= 0) {
		if (usedMemoId.find(memoid[y][x]) == usedMemoId.end()) {
			usedMemoId.insert(memoid[y][x]);
			return memo[y][x];
		} else {
			return 0ll;
		}
	}

	ll result = 1;

	for (int i = 0; i < 4; ++i) {
		Point next1 = Point(x, y) + DP4[i];
		if (isOver(next1)) {
			continue;
		}
		if (check.read(next1.y, next1.x)) {
			continue;
		}
		if (!canMove(Point(x, y), next1)) {
			continue;
		}
		check.write(next1.y, next1.x, true);
		for (int j = 0; j < 4; ++j) {
			Point next2 = next1 + DP4[j];
			if (isOver(next2)) {
				continue;
			}
			if (check.read(next2.y, next2.x)) {
				continue;
			}
			if (!canMove(next1, next2)) {
				continue;
			}
			check.write(next2.y, next2.x, true);
			result += calc(next2.y, next2.x);
		}
	}

	//memo[y][x] = after;
	return result;
}

int main() {
	std::ios::sync_with_stdio(false);

	in(h, w);
	inr(s, h, w);
	check.setInitVal(false);
	resize(memo, h, w, -1ll);
	resize(memoid, h, w, -1);
	posList.reserve(h * w);

	ll ans = 0ll;
	for (int y = 0; y < h; ++y) {
		for (int x = 0; x < w; ++x) {
			posList.clear();
			usedMemoId.clear();
			check.init();
			//check.write(y, x, true);
			ll sum = 0ll;
			for (int k = 0; k < 4; ++k) {
				Point p = Point(x, y) + DP4[k];
				if (isOver(p)) {
					continue;
				}
				if (check.read(p.y, p.x)) {
					continue;
				}
				if (s[y][x] == s[p.y][p.x]) {
					continue;
				}
				check.write(p.y, p.x, true);
				sum += calc(p.y, p.x);
			}
			for (int k = 0; k < posList.size(); ++k) {
				memo[posList[k].y][posList[k].x] = sum;
				memoid[posList[k].y][posList[k].x] = memoIndex;
			}
			++memoIndex;
			ans += sum;
		}
	}

	out(ans / 2);

	getchar();
}

