class UnionFind {
private:
    vector<int> par, sizes;

public:

    UnionFind(int n = 100010) : par(n), sizes(n, 1) {
        rep(i, n) par[i] = i;
    }

    int root(int x) {
        if (x == par[x]) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (sizes[x] < sizes[y]) swap(x, y);
        par[y] = x;
        sizes[x] += sizes[y];
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    int size(int x) {
        return sizes[root(x)];
    }
};

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int h,w; cin >> h >> w;
  char c[400][400];
  rep(i,h) rep(j,w) cin >> c[i][j];
  UnionFind uf(h*w);
  rep(i,h-1) rep(j,w){
    if(c[i][j] != c[i+1][j]){
      uf.unite(i*w+j,(i+1)*w+j);
    }
  }
  rep(i,h) rep(j,w-1){
    if(c[i][j] != c[i][j+1]){
      uf.unite(i*w+j,i*w+j+1);
    }
  }

  int black[400*400]={},white[400*400]={};
  rep(i,h) rep(j,w){
    if(c[i][j] == '#') black[uf.root(i*w+j)]++;
    else white[uf.root(i*w+j)]++;
  }

  ll ans = 0;
  rep(i,h*w) ans+= black[i] * white[i];
  cout << ans << endl;
  return 0;
}

