pair<int, int> connected(int x, int y, int px, int py, vector<vector<int>>& s, vector<vector<int>>& t, int H, int W){
    if(x < 0 || y < 0 || x >= H || y >= W || s[x][y] != s[px][py] || t[x][y])return {0, 0};
    t[x][y] = 1;
    pair<int, int> ret({0, 0});
    vector<int> mv({0, 1, 0, -1, 0});
    for(int i = 0; i < 4; ++i){
        auto tmp = connected(x + mv[i], y + mv[i + 1], x, y, s, t, H, W);
        ret.first += tmp.first;
        ret.second += tmp.second;
    }
    ++((x ^ y) & 1 ? ret.first : ret.second);
    return ret;
}

int main(){
    int H, W;
    scanf("%d%d", &H, &W);
    vector<vector<int>> s(H, vector<int>(W)), t(H, vector<int>(W));
    {
        string S;
        for(int i = 0; i < H; ++i){
            cin >> S;
            for(int j = 0; j < W; ++j){
                s[i][j] = (S[j] ^ i ^ j) & 1;
            }
        }
    }
    int ans(0);
    for(int i = 0; i < H; ++i){
        for(int j = 0; j < W; ++j){
            auto tmp = connected(i, j, i, j, s, t, H, W);
            ans += tmp.first * tmp.second;
        }
    }
    printf("%lld\n", ans);
    return 0;
}

