ll ans;
int n, m;
char s[666][666];
bool vis[666][666];

int head, tail;
int q[666666][2];
int w, b;

void work(int x, int y, char a){
	if(!vis[x][y] && s[x][y] != a)
		q[++tail][0] = x, q[tail][1] = y, vis[x][y] = 1;
}

void bfs(int a, int c){
	w = b = head = tail = 0;
	q[++tail][0] = a; q[tail][1] = c;
	vis[a][c] = true;
	while(head < tail){
		int x = q[++head][0], y;
		y = q[head][1];
		if(s[x][y] == '#') b++; else w++;
		work(x + 1, y, s[x][y]), work(x - 1, y, s[x][y]), work(x, y + 1, s[x][y]), work(x, y - 1, s[x][y]);
	}
	ans += 1ll * w * b;
}

int main(){
	scanf("%d %d", &n, &m);
	for(int i = 1; i <= n; i++) vis[i][0] = vis[i][m + 1] = 1;
	for(int i = 1; i <= m; i++) vis[0][i] = vis[n + 1][i] = 1;
	for(int i = 1; i <= n; i++)
		scanf("%s", s[i] + 1);
	for(int i = 1; i <= n; i++)
		for(int j = 1; j <= m; j++)
			if(!vis[i][j]) bfs(i, j);
	printf("%lld\n", ans);
	return 0;
}

