using namespace std;
const int dx[] = {0, 1, 0, -1};
const int dy[] = {-1, 0, 1, 0};


vector<string> s;

bool used[401][401];
int black_count;
int white_count;

void dfs(int y, int x, int w, int h) {
    used[y][x] = true;

    if (s[y][x] == '#') black_count++;
    else if (s[y][x] == '.')white_count++;

    for (int i = 0; i < 4; i++) {
        int nx = x + dx[i];
        int ny = y + dy[i];

//        cout << ny << ' ' << nx << endl;

        if (used[ny][nx])continue;
        if (nx < 0 || ny < 0 || nx >= w || ny >= h)continue;
        if (s[ny][nx] == s[y][x])continue;

        dfs(ny, nx, w, h);
    }

}


signed main() {
    int h, w;
    int ans = 0;
    cin >> h >> w;

    s.resize(h);

    for (int i = 0; i < h; i++) {
        cin >> s[i];
    }

    for (int y = 0; y < w; y++) {
        for (int x = 0; x < h; x++) {

//            cout << y << " " << x << " " << s[y][x] << endl;

            if (s[y][x] == '.') continue;
            if (used[y][x])continue;

            black_count = 0;
            white_count = 0;

            dfs(y, x, w, h);
            ans += black_count * white_count;
        }
    }

    cout << ans << endl;

    return 0;
}

