using namespace std;

const int dx[] = { -1, 0, +1, 0 };
const int dy[] = { 0, -1, 0, +1 };

void dfs(const vector<string> &S, int H, int W, int i, int j, vector<vector<bool>> &visited, long long &black, long long &white)
{
	if (visited[i][j]) {
		return;
	}
	visited[i][j] = true;

	if (S[i][j] == '#') ++black;
	if (S[i][j] == '.') ++white;

	for (int k = 0; k < 4; ++k) {
		int y = i + dy[k];
		int x = j + dx[k];
		if (y < 0 || H <= y || x < 0 || W <= x) {
			continue;
		}
		if ((S[i][j] == '#' && S[y][x] == '.') || (S[i][j] == '.' && S[y][x] == '#')) {
			dfs(S, H, W, y, x, visited, black, white);
		}
	}
}

int main()
{
	int H, W;
	cin >> H >> W;

	vector<string> S(H);
	for (auto &x : S) {
		cin >> x;
	}
	vector<vector<bool>> visited(H, vector<bool>(W, false));
	long long ans = 0;
	for (int i = 0; i < H; ++i) {
		for (int j = 0; j < W; ++j) {
			if (S[i][j] == '#') {
				long long black = 0;
				long long white = 0;
				dfs(S, H, W, i, j, visited, black, white);
				ans += black * white;
			}
		}
	}

	cout << ans << endl;
}

