                        int t1 = y*w+x;
                        int t2 = ny*w+nx;
                        uf.unite(t1,t2);
                    }
                }
            }
        }
    }

    vector<int> cnt(h*w,0);
    vector<int> cnt2(h*w,0);

    Rep(y,h){
