class UnionFind
{
public:
    UnionFind(){};
    ~UnionFind(){};
    void init(int num_entries) {
        num_entries_ = num_entries;
        par_.resize(num_entries_);
        rank_.resize(num_entries_, 0);
        REP(i, num_entries_) par_[i] = i;
    }
    int find(int x) {
        if (par_[x] == x) return x;
        else return par_[x] = find(par_[x]);
    }
    void unite(int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return;
        if (rank_[x] < rank_[y]) par_[x] = y;
        else {
            par_[y] = x;
            if (rank_[x] == rank_[y]) rank_[x]++;
        }
    }
    bool same(int x, int y) { return find(x) == find(y); }
private:
    int num_entries_;
    std::vector<int> par_;
    std::vector<int> rank_;
};

int main(void)
{
    cin.sync_with_stdio(false);
    int H, W;
    cin >> H >> W;

    vector<string> cells(H);
    REP(h, H) cin >> cells[h];

    UnionFind uf;
    uf.init(H * W);

    REP(h, H) {
        REP(w, W) {
            int idx = h * W + w;
            if (w != W - 1) {
                if (cells[h][w] != cells[h][w+1]) {
                    uf.unite(idx, idx + 1);
                }
            }
            if (h != H - 1) {
                if (cells[h][w] != cells[h+1][w]) {
                    uf.unite(idx, idx + W);
                }
            }
        }
    }

    // id, <'#'(black), '.'(white)>
    map<int, pair<ll, ll>> cnt;
    REP(h, H) {
        REP(w, W) {
            int idx = h * W + w;
            int id = uf.find(idx);
            if (cells[h][w] == '#') {
                cnt[id].first++;
            } else {
                cnt[id].second++;
            }
        }
    }
    ll ans = 0;
    for(auto kv: cnt) {
        auto id = kv.first;
        auto black = kv.second.first;
        auto white = kv.second.second;
        ans += black * white;
        // cout << kv.first << "," << kv.second << endl;
    }
    cout << ans << endl;
    return 0;
}

