const int dy[] = {1, 0, -1, 0};
const int dx[] = {0, 1, 0, -1};
const int MAX_N = 500;
int h, w;
char table[MAX_N][MAX_N];
char flag[MAX_N][MAX_N];
int bfs(int y, int x)
{
    queue<P> que;
    memset(flag, false, sizeof(flag));
    que.push(P(y, x));
    flag[y][x] = '#';
    int res = 0;
    while(!que.empty())
    {
        P p = que.front();
        que.pop();
        for(int i = 0; i < 4; i++)
        {
            int ny = p.first + dy[i];
            int nx = p.second + dx[i];
            if(nx < 0 || ny < 0 || ny >= h || nx >= w) continue;
            if(table[ny][nx] == table[p.first][p.second]) continue; 
            if(flag[ny][nx]) continue;
            if(table[ny][nx] == '.') res++;
            flag[ny][nx] = true;
            que.push(P(ny, nx));
        }
    }
    return res;
}
int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> h >> w;
    for(int i = 0; i < h; i++)
    {
        for(int j = 0; j < w; j++)
        {
            cin >> table[i][j];
        }
    }
    int ans = 0;
    for(int i = 0; i < h; i++)
    {
        for(int j = 0; j < w; j++)
        {
            if(table[i][j] == '#')
            {
                ans += bfs(i, j);
            }
        }
    }
    cout << ans << endl;
    return 0;
}

