class UF{
    public:
    vector<int> data;
    int sz;
	public:
    UF(int sz):sz(sz){data.resize(sz,-1);}
    bool unite(int x,int y){
        x=root(x);y=root(y);
        if(x==y)return 0;
        if(data[x]>data[y])swap(x,y);
		data[x]+=data[y];
		data[y]=x;
		sz--;
        return 1;
    }
    inline int root(int x){return data[x]<0?x:data[x]=root(data[x]);}
    inline bool same(int x, int y){return root(x)==root(y);}
    inline int size(){return sz;}
	inline int size(int x){return -data[root(x)];}
};

int main(){
	lint h,w;
	cin>>h>>w;
	vector<string>s(h);
	rep(i,h)cin>>s[i];
	UF uf(h*w);
	rep(i,h)rep(j,w){
		if(i&&s[i][j]!=s[i-1][j])uf.unite(i*w+j,(i-1)*w+j);
		if(j&&s[i][j]!=s[i][j-1])uf.unite(i*w+j,i*w+j-1);
	}
	map<lint,lint>p;
	map<lint,lint>q;
	rep(i,h*w){
		if(s[i/w][i%w]=='#')p[uf.root(i)]++;
		else q[uf.root(i)]++;
	}
	lint ans=0;
	for(auto [s,t]:p){
		ans+=q[s]*t;
	}
	cout<<ans<<endl;
}

