void bfs(int color, char check_color, int h, int w) {
    colored_grid[h][w] = check_color;
    if (color == '#') MP[check_color]++;
    is_checked[h][w] = true;
    char target = (color == '#' ? '.' : '#');
    for (int i = 0; i < 4; i++) {
        int now_h = h + dh[i], now_w = w + dw[i];
        if (now_h >= 0 && now_h < H && now_w >= 0 && now_w < W && grid[now_h][now_w] == target && !is_checked[now_h][now_w]) bfs(target, check_color, now_h, now_w);
    }
    return;
}

int main() {
    cin >> H >> W;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) cin >> grid[i][j];
    }
    int now_number = 1;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == '#' && !is_checked[i][j]) {
                bfs('#', now_number, i, j);
                now_number++;
            }
        }
    }
    map<int, int> count_mp;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) count_mp[colored_grid[i][j]]++;
    }
    int ans = 0;
    for (int i = 1; i < now_number; i++) {
        ans += MP[i] * (count_mp[i] - MP[i]);
    }
    cout << ans << endl;
    return 0;
}

