struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

void solve() {
    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    for (int i = 0; i < H; i++) {
        cin >> S[i];
    }

    int dx[] = {1, 0, -1, 0};
    int dy[] = {0, -1, 0, 1};
    UnionFind uf(H * W);
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            for (int k = 0; k < 4; k++) {
                int ty = i + dy[k];
                int tx = j + dx[k];
                if (ty < 0 || ty >= H || tx < 0 || tx >= W) continue;
                if (S[i][j] == S[ty][tx]) continue;
                int ind = i * W + j;
                int ind2 = ty * W + tx;
                uf.unionSet(ind, ind2);
            }
        }
    }

    vector<ll> black(H * W), white(H * W);
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            int ind = i * W + j;

            int r = uf.root(ind);
            if (S[i][j] == '#') black[r]++;
            if (S[i][j] == '.') white[r]++;
        }
    }

    set<int> ID;
    ll ans = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            int ind = i * W + j;
            if (ID.find(uf.root(ind)) != ID.end()) continue;
            ID.insert(uf.root(ind));

            ll N = uf.size(ind);
            ans += black[uf.root(ind)] * white[uf.root(ind)];
            //cout << black[uf.root(ind)] * white[uf.root(ind)] << endl;
        }
    }

    cout << ans << endl;
}

