void assign(ll x, ll y, vvec<ll> &mz, vvec<ll> &viz) {
    vll dx = {-1,0,0,1};
    vll dy = {0,-1,1,0};
    rep(i, 4) {
        if(y+dy[i]<0||y+dy[i]>=H||x+dx[i]<0||x+dx[i]>=W) continue;
        if(mz[y][x]!=mz[y+dy[i]][x+dx[i]]) {
            adj[y*W+x].push_back((y+dy[i])*W+x+dx[i]);
        }
    }
}

void dfs(ll x, ll y, vvec<ll> &mz, vvec<ll> &viz, ll &w, ll &b) {
    if(viz[y][x]==0)return;
    viz[y][x] = 0;
    if(mz[y][x] == 1) b+=1;else w+=1;
    for(auto &e: adj[y*W+x]) {
        if(viz[e/W][e%W]==-1)dfs(e%W,e/W,mz,viz, w,b);
    }
}

void solve() {
    cin >> H >> W;
    vvec<ll> mz(H, vll(W, -1));
    vvec<ll> viz(H, vll(W, -1));
    adj.resize(H*W);
