LL bfs(int y, int x) {
  LL cnt_w = 0, cnt_b = 0;
  queue<P> que; que.push({y, x});
  visited[y][x] = true;

  while (!que.empty()) {
    auto [y, x] = que.front(); que.pop();
    if (S[y][x] == '.') ++cnt_w;
