    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            char cH;
            cin>>cH;
            a[i][j]=(cH=='#');
        }
    }
    memset(used,0,sizeof(used));
    ll ans=solve();
    cout<<ans;
}

