                if (ok(x, y) && s[x][y] != s[i][j]) Merge(x * m + y, i * m + j, root, sz);
            }
        }
    }
    vi black(n * m), white(n * m);
    ll ans = 0;
    for (int i = 0; i < n; i++)
    {
