int reached[400][400];
int H,W;
string S[400];

int canreach(int bi,int bj,int wi,int wj){
  //init
  for(int i=0; i<H; i++){
    for(int j=0; j<W; j++){
      reached[i][j]=0;
    }
  }
  queue<pair<int,int>> q;
  q.push(make_pair(bi,bj));
  reached[bi][bj]=1;
  while(!q.empty()){
    int nowi=q.front().first;
    int nowj=q.front().second;
    if(S[nowi][nowj]=='#'){
      if(nowi-1>=0&&S[nowi-1][nowj]=='.'){
        if(reached[nowi-1][nowj]==0){
          reached[nowi-1][nowj]=1;
          q.push(make_pair(nowi-1,nowj));
        }
      }
      if(nowi+1<H&&S[nowi+1][nowj]=='.'){
        if(reached[nowi+1][nowj]==0){
          reached[nowi+1][nowj]=1;
          q.push(make_pair(nowi+1,nowj));
        }
      }
      if(nowj-1>=0&&S[nowi][nowj-1]=='.'){
        if(reached[nowi][nowj-1]==0){
          reached[nowi][nowj-1]=1;
          q.push(make_pair(nowi,nowj-1));
        }
      }
      if(nowj+1<H&&S[nowi][nowj+1]=='.'){
        if(reached[nowi][nowj+1]==0){
          reached[nowi][nowj+1]=1;
          q.push(make_pair(nowi,nowj+1));
        }
      }
    }else{
      if(nowi-1>=0&&S[nowi-1][nowj]=='#'){
        if(reached[nowi-1][nowj]==0){
          reached[nowi-1][nowj]=1;
          q.push(make_pair(nowi-1,nowj));
        }
      }
      if(nowi+1<H&&S[nowi+1][nowj]=='#'){
        if(reached[nowi+1][nowj]==0){
          reached[nowi+1][nowj]=1;
          q.push(make_pair(nowi+1,nowj));
        }
      }
      if(nowj-1>=0&&S[nowi][nowj-1]=='#'){
        if(reached[nowi][nowj-1]==0){
          reached[nowi][nowj-1]=1;
          q.push(make_pair(nowi,nowj-1));
        }
      }
      if(nowj+1<H&&S[nowi][nowj+1]=='#'){
        if(reached[nowi][nowj+1]==0){
          reached[nowi][nowj+1]=1;
          q.push(make_pair(nowi,nowj+1));
        }
      }
    }
    q.pop();
  }
  return reached[wi][wj];
}


