				if(nx < 0 || ny < 0 || nx >= h || ny >= w) continue;
				if((s[nx][ny] != s[x][y]) && !used[nx][ny]){
					que.push(P(nx, ny));
					cnt[s[nx][ny]]++;
					used[nx][ny] = true;
				}
			}
		}
		ans += cnt[WHITE] * cnt[BLACK];
	}
	cout << ans << endl;
}

