struct UnionFind {
    vector<int> parent; //parent[i]はiの親の番号
    vector<int> rank; // rank[i]は木の深さ
    vector<int> bsize; // bsize[i]はグループに含まれている黒数
    vector<int> wsize; // wsize[i]はグループに含まれている白数
    vector<int> loop; // グループに含まれているloopの数

    UnionFind(int n) {
        //コンストラクタは全て自分が根
        parent = vector<int>(n);
        rank = vector<int>(n);
        bsize = vector<int>(n);
        wsize = vector<int>(n);
        loop = vector<int>(n);
        for (int i=0;i<n;i++) {
            parent[i] = i;
            rank[i] = 0;
            if (S[i/W][i%W] == '#') bsize[i] = 1, wsize[i] = 0;
            else bsize[i] = 0, wsize[i] = 1;
        }
    }

    int root(int x) { //根を再帰で辿りつつ、探索したものを繋ぎなおし
    if (parent[x] == x) return x;
    return parent[x] = root(parent[x]);
    }

    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) {
            loop[rx]++;
            return;
        }
        if (rank[rx] < rank[ry]) {
            parent[rx] = ry;
            bsize[ry] += bsize[rx];
            wsize[ry] += wsize[rx];
            loop[ry] += loop[rx];
        }
        else {
            parent[ry] = rx;
            bsize[rx] += bsize[ry];
            wsize[rx] += wsize[ry];
            loop[rx] += loop[ry];
            if (rank[rx] == rank[ry]) rank[rx]++;
        }
    }

    bool same(int x, int y){
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }

    int getBSize(int x){
        return bsize[root(x)];
    }

    int getWSize(int x){
        return wsize[root(x)];
    }

    int getLoopNum(int x){
        return loop[root(x)];
    }
};

