class UnionFind {
    public:
        UnionFind(){}
        UnionFind(int size) { Init(size); }
        // size: Union-Find で扱いたい要素の数
        void Init(int size) { m_Data.assign(size, -1); }

        // x と y の属する集合を併合
        // 既に一緒な集合内にいるなら false を
        // 新たに併合されたなら true を返す
        bool Unite(int x, int y) {
            x = Find(x), y = Find(y);
            if(x == y) { return (false); }
            if(m_Data[x] > m_Data[y]) { swap(x, y); }
            m_Data[x] += m_Data[y];
            m_Data[y] = x;
            return (true);
        }

        // 要素 k が属する集合の根を返す
        int Find(int k) {
            if(m_Data[k] < 0) { return (k); }
            return (m_Data[k] = Find(m_Data[k]));
        }

        // 要素 k と同じ集合の要素数を返す
        int Size(int k) { return (-m_Data[Find(k)]); }

    private:
        vector<int> m_Data;
};

int H, W;
vector<string> S;
vector< vector<bool> > isUsed;
UnionFind uf;
ll black[MAX_H * MAX_W] = {};    // グループ i の黒の数
ll white[MAX_H * MAX_W] = {};

static inline int get_id(int i, int j) { return i * W + j; }

// 黒→白→黒とたどりいけるところまで行く
// 辿れた全てを Union-Find で同じグループにする
void dfs(int i, int j, char prev, int root) {
    if(isUsed[i][j] || prev == S[i][j]) { return; }
    isUsed[i][j] = true;
    uf.Unite(get_id(i, j), root);

    if(i > 0) { dfs(i-1, j, S[i][j], root); }
    if(i < H-1) { dfs(i+1, j, S[i][j], root); }
    if(j > 0) { dfs(i, j-1, S[i][j], root); }
    if(j < W-1) { dfs(i, j+1, S[i][j], root); }
}

signed main()
{
    cin >> H >> W;
    S.assign(H, "");
    REP(i, H) { cin >> S[i]; }

    isUsed.assign(H, vector<bool>(W, false));
    uf.Init(H * W);

    REP(i, H) {
        REP(j, W) {
            // 探索し、そのノードのグループを決定
            if(isUsed[i][j]) { continue; }
            dfs(i, j, '?', get_id(i, j));
        }
    }

    // 同じグループの白の数と黒の数を数える
    REP(i, H) {
        REP(j, W) {
            if(S[i][j] == '#') { black[uf.Find(get_id(i, j))]++; }
            else { white[uf.Find(get_id(i, j))]++; }
        }
    }

    ll ans = 0;
    REP(i, H) {
        REP(j, W) {
            ans += black[get_id(i, j)] * white[get_id(i, j)];
        }
    }
    printf("%lld\n", ans);

    return 0;
}

