	int num = 0;
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			if (memo[i][j] != 0 || s[i][j] == '.') {
				continue;
			}

			num++;
			walk(i, j, num);
		}
	}

	vector<int> blacks(num+1, 0), whites(num+1, 0);
	for (int i = 0; i < h; i++) {
