struct UnionFind
{
  int n, num;
  vector<int> sz, par;
  UnionFind() {}
  UnionFind(int n_) : n(n_), num(n_), sz(n_, 1), par(n_, 0) { iota(par.begin(), par.end(), 0); }
  int find(int x)
  {
    return (x == par[x] ? x : par[x] = find(par[x]));
  }
  bool same(int x, int y)
  {
    return find(x) == find(y);
  }
  void unite(int x, int y)
  {
    x = find(x);
    y = find(y);
    if (x == y)
      return;
    if (sz[x] < sz[y])
      swap(x, y);
    sz[x] += sz[y];
    par[y] = x;
    num--;
  }
  int size(int x)
  {
    return sz[find(x)];
  }
  int count() const
  {
    return num;
  }
};
