class DisjointSet {
public:
  vector<int> p, rank, size;
  DisjointSet(int n) {
    p.assign(n, 0);
    rank.assign(n, 0);
    size.assign(n, 0);
    for (int i = 0; i < n; i++) {
      make_set(i);
    }
  }

  void make_set(int x) {
    p[x] = x;
    rank[x] = 0;
    size[x] = 1;
  }

  int find_set(int x) {
    if (x != p[x]) {
      p[x] = find_set(p[x]);
    }
    return p[x];
  }

  bool same(int x, int y) {
    return find_set(x) == find_set(y);;
  }

  int union_size(int x) {
    if (x != p[x]) {
      size[x] = union_size(find_set(x));
    }
    return size[x];
  }

  void link(int x, int y) {
    if(rank[x]  > rank[y]) {
        p[y] = x;
        size[x] = size[x] + size[y];
    }else if(rank[x] < rank[y]){
        p[x] = y;
        size[y] = size[x] + size[y];
    }else if(x != y) {
      p[y] = x;
      rank[x]++;
      size[x] = size[x] + size[y];
    }
  }

  void unite(int x, int y) {
      link(find_set(x), find_set(y));
  }
};

void solve() {
  int H, W; cin >> H >> W;
  vector<string> grid(H);
  int n = H * W;
  int d[n];

  rep(i, H) {
    cin >> grid[i];
    rep(j, W) {
      int idx = i * W + j;
      if (grid[i][j] == '#') d[idx] = 0;
      else d[idx] = 1;
    }
  }

  DisjointSet ds(n);
  rep(i, H)rep(j, W) {
    if (i + 1 < H && grid[i][j] != grid[i + 1][j]) {
      // 縦に伸びる辺を併合
      ds.unite(W * i + j, W * (i + 1) + j);
    }
    if (j + 1 < W && grid[i][j] != grid[i][j + 1]) {
      // 横に伸びる辺を併合
      ds.unite(W * i + j, W * i + j + 1);
    }
  }

  ll ans = 0;
  vector<ll> b(n, 0), w(n, 0);
  rep(i, n) {
    if (d[i] == 0) b[ds.find_set(i)]++;
    else w[ds.find_set(i)]++;
  }
  rep(i, n) ans += b[i] * w[i];
  outl(ans);
}

