const char CHAR_STR = '#';
const char CHAR_END = '.';

typedef struct
{
int h;
int w;
char map[400][400];
int tmp[400][400];
} Parameter;

int count_to_goal(Parameter * p, int sx, int sy)
{
    if (p->tmp[sy][sx] != -1)
        return p->tmp[sy][sx];

    char flag[400][400] = { 0 };

    flag[sy][sx] = 2;

    for (char nex = CHAR_STR; ;)
    {
        if (nex == CHAR_STR)
            nex = CHAR_END;
        else
            nex = CHAR_STR;

        char abort = 1;

        for (int y=0; y<p->h; y++)
        {
            for (int x=0; x<p->w; x++)
            {
                if (flag[y][x] != 2) continue;
                flag[y][x] = 3;
                abort = 0;

                for (int i = 0; i < 4; i++)
                {
                    int u = x, v = y;
                    switch (i)
                    {
                    case 0: u += 1; break;
                    case 1: v += 1; break;
                    case 2: u -= 1; break;
                    case 3: v -= 1; break;
                    }
                    if ((u < 0) || (u >= p->w) || (v < 0) || (v >= p->h)) continue;
                    if (flag[v][u] != 0) continue;

                    if (p->map[v][u] == nex)
                        flag[v][u] = 1;
                    else
                        flag[v][u] = -1;
                } // i
            } // x
        } // y

        for (int y=0; y<p->h; y++)
            for (int x=0; x<p->w; x++)
                if (flag[y][x] == 1)
                    flag[y][x] = 2;

        if (abort)
            break;
    } // do-while abort

    int ret = 0;
    for (int y = 0; y < p->h; y++)
        for (int x = 0; x < p->w; x++)
            if ((p->map[y][x] == CHAR_END) && (flag[y][x] == 3))
                ret++;

    for (int y = 0; y < p->h; y++)
        for (int x = 0; x < p->w; x++)
            if ((p->map[y][x] == CHAR_STR) && (flag[y][x] == 3))
                p->tmp[y][x] = ret;

    return ret;
}

int main(int argc, char * argv[])
{
    Parameter p;
    int ret = 0;

    std::cin >> p.h;
    std::cin >> p.w;
    for (int y=0; y<p.h; y++)
        for (int x=0; x<p.w; x++)
            std::cin >> p.map[y][x];

    for (int y=0; y<p.h; y++)
        for (int x=0; x<p.w; x++)
            p.tmp[y][x] = -1;

    for (int y=0; y<p.h; y++)
    {
        for (int x=0; x<p.w; x++)
        {
            if (p.map[y][x] == CHAR_STR)
                ret += count_to_goal(&p, x, y);
        }
    }

    std::cout << ret;

    return 0;
}

