struct UnionFind {
    typedef pair<int, int> P;
    vector<vector<P> > par; 

    UnionFind(int X,int Y) : par(X+2) { //最初は全てが根であるとして初期化
        for(int i = 1; i <= X+1; i++){
            par[i].resize(Y+2);
            for(int j = 1; j <= Y+1; j++){
                par[i][j]=make_pair(i,j);
            }
        } 
    }

    P root(P p) { // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
        if (par[p.first][p.second] == p) return p;
        return par[p.first][p.second] = root(par[p.first][p.second]);
    }

    void unite(P x, P y) { // xとyの木を併合
        P rx = root(x); //xの根をrx
        P ry = root(y); //yの根をry
        if (rx == ry) return; //xとyの根が同じ(=同じ木にある)時はそのまま
        par[rx.first][rx.second] = ry; //xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
    }

    bool same(P x, P y) { // 2つのデータx, yが属する木が同じならtrueを返す
        P rx = root(x);
        P ry = root(y);
        return rx == ry;
    }
};

int main() {

    int  H,W;

    std::cin >> H;
    std::cin >> W;
    int a[402][402]; 

    for(int i = 1 ; i <= H;i++){
        string tmp;
        cin >> tmp;
        for(int j = 1 ; j <= W ;j++){
            if(tmp[j-1]=='#'){
                a[i][j]=-1;
            }else if(tmp[j-1]=='.'){
                a[i][j]=1;
            }
        } 
    }

    UnionFind tree(H,W);


    for(int i = 1 ; i <= H;i++){

        for(int j = 1 ; j <= W ;j++){
            if(a[i][j]*a[i-1][j]==-1) tree.unite(make_pair(i,j),make_pair(i-1,j));            
            if(a[i][j]*a[i][j-1]==-1) tree.unite(make_pair(i,j),make_pair(i,j-1));
            if(a[i][j]*a[i+1][j]==-1) tree.unite(make_pair(i,j),make_pair(i+1,j));
            if(a[i][j]*a[i][j+1]==-1) tree.unite(make_pair(i,j),make_pair(i,j+1));
        }
    }

    queue<pair<int,int> > list;
    map<pair<int,int>,int> black;
    map<pair<int,int>,int> white;
    for(int i = 1 ; i <= H;i++){
        for(int j = 1 ; j <= W ;j++){
            pair<int,int> point = make_pair(i,j);
            pair<int,int> parent=tree.root(point);
            if( black.find(parent) == black.end() && white.find(parent) == white.end()){
                list.push(parent);
            } 
            if(a[i][j]==-1) black[parent]++;
            if(a[i][j]==1) white[parent]++;

        }
    }
    ll answer=0;
    while(!list.empty()){

        answer += black[list.front()]*white[list.front()];
        list.pop();

    }

    cout << answer << endl;
    return 0;
}

