int main()
{
	int h, w;
	scanf("%d%d", &h, &w);
	s.resize(h + 2, vb(w + 2));
	visited.resize(h + 2, vb(w + 2));
	for (int i{1}; i <= h; i++)
		for (int j{1}; j <= w; j++)
		{
			char tmp;
			scanf(" %c", &tmp);
			s[i][j] = tmp == '#';
		}
	for (int r{}; r <= h + 1; r++)
		visited[r][0] = visited[r][w + 1] = true;
	for (int c{}; c <= w + 1; c++)
		visited[0][c] = visited[h + 1][c] = true;
	int count{};
	for (int i{1}; i <= h; i++)
		for (int j{1}; j <= w; j++)
		{
			auto tmp{dfs(i, j, s[i][j])};
			count += tmp.first * tmp.second;
		}
	printf("%d\n", count);

	return 0;
}

pii dfs(int r, int c, bool black)
{
	if (visited[r][c] || s[r][c] != black) return pii();
	visited[r][c] = true;
	pii ret;
	if (black)
		ret.first = 1;
	else
		ret.second = 1;
	for (int i{}; i < 4; i++)
	{
		auto tmp{dfs(r + dir[i][0], c + dir[i][1], !black)};
		ret.first += tmp.first;
		ret.second += tmp.second;
	}
	return ret;
}

