class node_t 
{
public:
  node_t(int xx, int yy, int zz) : x(xx), y(yy), z(zz) {};

public:
  int x;
  int y;
  int z;
};


int main(int argc, char** argv)
{
  std::cin.tie(0);
  std::ios_base::sync_with_stdio(0);

  std::cout << std::fixed << std::setprecision(6);
  std::cerr << std::fixed << std::setprecision(6);

  int H, W;

  std::cin >> H >> W;

  std::vector<std::string> a(H);

  for (auto& s : a)
    std::cin >> s;

  int ids[444][444], id = 1;

  memset(ids, 0, sizeof(ids));

  std::map<int, std::pair<int, int>> map;

  for (int i = 0; i < H; i ++)
    for (int j = 0; j < W; j ++)
      if (a[i][j] == '#')
        if (ids[i][j] == 0) {
          ids[i][j] = id ++;

          std::queue<node_t> queue;

          queue.emplace(j, i, 0);

          map[id].first ++;

          while (! queue.empty()) {
            node_t node = queue.front(); queue.pop();

            for (int i = 0; i < 4; i ++) {
              int x = node.x + dx[i], y = node.y + dy[i], z = 1 - node.z;

              if (x < 0 || x >= W || y < 0 || y >= H)
                continue;

              if (ids[y][x])
                continue;

              if ((z == 0 && a[y][x] == '.') ||
                  (z == 1 && a[y][x] == '#'))

                continue;

              ids[y][x] = id;

              (z == 0 ? map[id].first : map[id].second) ++;

              queue.emplace(x, y, z);
            }
          }
        }

  long long c = 0;

  for (const auto& kv : map) {
    long long x = kv.second.first, y = kv.second.second;

    c += x * y;
  }

  std::cout << c << std::endl;

  return 0;
}

