const int dy[] = {1, 0, -1, 0}, dx[] = {0, -1, 0, 1};

int main() {
  cin.tie(0); ios::sync_with_stdio(false);
  // freopen("input.txt", "r", stdin);

  int h, w; cin >> h >> w;
  vector<vector<char> > s(h, vector<char>(w)); REP(i, h) REP(j, w) cin >> s[i][j];
  vector<vector<bool> > used(h, vector<bool>(w, false));
  long long ans = 0;
  REP(i, h) REP(j, w) if (!used[i][j]) {
    used[i][j] = true;
    long long dot = 0, sharp = 0;
    if (s[i][j] == '.') ++dot;
    else ++sharp;
    queue<pair<int, int>> que;
    que.push({i, j});
    while (!que.empty()) {
      auto a = que.front(); que.pop();
      int old_y = a.first, old_x = a.second;
      REP(k, 4) {
        int y = old_y + dy[k], x = old_x + dx[k];
        if (0 <= y && y < h && 0 <= x && x < w && !used[y][x] && s[y][x] != s[old_y][old_x]) {
          used[y][x] = true;
          if (s[y][x] == '.') ++dot;
          else ++sharp;
          que.push({y, x});
        }
      }
    }
    ans += dot * sharp;
  }
  cout << ans << '\n';
  return 0;
}

