const int N=405;
string s[N];

ll a[N][N];

ll arr[N*N],sz[N*N],cntw[N*N],cntb[N*N];

void init(int h,int w)
{
	for(int i=1;i<=h;i++)
	{
		for(int j=0;j<s[i].size();j++)
		{
			int u=a[i][j];
			arr[u]=u;
			sz[u]=1;

			if(s[i][j]=='#')
				cntb[u]++;
			else
				cntw[u]++;
		}
	}
}

int root(int u)
{
	int i=arr[u];
	while(i!=arr[i])
	{
		i=arr[arr[i]];
	}

	return i;
}

bool find(int u,int v)
{
	if(root(u)==root(v))
		return 1;
	else
		return 0;
}

void merge(int u,int v)
{
	if(!find(u,v))
	{
		int x=root(u),y=root(v);
		if(sz[x]>=sz[y])
		{
			arr[y]=x;
			sz[x]=sz[x]+sz[y];
			cntw[x]=cntw[x]+cntw[y];
			cntb[x]=cntb[x]+cntb[y];
		}
		else
		{
			arr[x]=y;
			sz[y]=sz[y]+sz[x];
			cntw[y]=cntw[y]+cntw[x];
			cntb[y]=cntb[y]+cntb[x];
		}
	}
}


