	for(int i=1;i<=h;i++)
	{
		for(int j=0;j<s[i].size();j++)
			a[i][j]=t++;
	}

	init(h,w);

	for(int i=1;i<=h;i++)
	{
		for(int j=0;j<s[i].size();j++)
		{
			if(s[i][j]=='#')
			{
				if(j+1<w &&s[i][j+1]=='.')
					merge(a[i][j],a[i][j+1]);

				if(i+1<=h && s[i+1][j]=='.')
					merge(a[i][j],a[i+1][j]);
			}
			else
			{
				if(j+1<w &&s[i][j+1]=='#')
					merge(a[i][j],a[i][j+1]);

				if(i+1<=h && s[i+1][j]=='#')
					merge(a[i][j],a[i+1][j]);
			}
		}
	}

	ll ans=0;
	for(int i=1;i<=h;i++)
	{
		for(int j=0;j<w;j++)
		{
			int u=a[i][j];
			if(root(u)==u)
			{

				//cout<<i<<" "<<j<<": "<<u<<" "<<cntw[u]<<" "<<cntb[u]<<"\n";
				ans=ans+cntw[u]*cntb[u];
			}
