bool color[404][404];
int H, W;

void input(){
	memset(color, false, sizeof(color));
	cin >> H >> W;
	rep (i, H) rep (j, W){
		char ch; cin >> ch;
		color[i][j] = (ch == '#');
	} // end rep
}

bool check(int i, int j, int d){
	int ni = i + di[d];
	int nj = j + dj[d];
	if (ni < 0 || ni >= H || nj < 0 || nj >= W) return false;
	if (color[i][j] == color[ni][nj]) return false;
	return true;
}

bool used[404][404];

ll solve(){
	ll ans = 0LL;
	ll b = 0LL, w = 0LL;
	rep (i, H){
		rep (j, W){
			if (used[i][j]) continue;
			b = 0LL;
			w = 0LL;
			queue<P> que;
			used[i][j] |= true;
			que.push(P(i,j));
			while(!que.empty()){
				P p = que.front(); que.pop();
				int ci = p.first, cj = p.second;
				if (color[ci][cj]){
					++b;
				}else{
					++w;
				} // end if
				rep (d, 4){
					if (!check(ci,cj,d)) continue;
					int ni = ci + di[d];
					int nj = cj + dj[d];
					if (used[ni][nj]) continue;
					used[ni][nj] |= true;
					que.push(P(ni,nj));
				} // end rep
			} // end while
			ans += b * w;
		} // end rep
	} // end rep
	return ans;
}

