int num[500][500];

int dx[4] = {-1, 1, 0, 0};
int dy[4] = {0, 0, -1, 1};
int H, W;

int bfs(int i, int j) {
    char c = s[i][j];
    if (c == '.') return 0;
    if (num[i][j] != -1) return num[i][j];

    CLR(visit, false);

    queue<pair<int, int>> q;
    REP(k, 4) {
        int nx = dx[k] + i;
        int ny = dy[k] + j;
        if (nx < 0 || nx >= H || ny < 0 || ny >= W) {
            continue;
        }
        if (s[nx][ny] == '#') continue;
        q.push({nx, ny});
    }


    vector<pair<int, int>> cand;
    int ans = 0;
    visit[i][j] = true;
    while (!q.empty()) {
        auto kv = q.front();
        q.pop();
        int kx = kv.first;
        int ky = kv.second;
        if (visit[kx][ky]) continue;
        visit[kx][ky] = true;

        if (s[kx][ky] == '.') {
            ans++;
            REP(k, 4) {
                int nx = dx[k] + kx;
                int ny = dy[k] + ky;
                if (nx < 0 || nx >= H || ny < 0 || ny >= W) {
                    continue;
                }
                if (s[nx][ny] == '.') continue;
                if (visit[nx][ny]) continue;
                q.push({nx, ny});
            }
        }
        else {
            cand.push_back({kx, ky});
            REP(k, 4) {
                int nx = dx[k] + kx;
                int ny = dy[k] + ky;
                if (nx < 0 || nx >= H || ny < 0 || ny >= W) {
                    continue;
                }
                if (s[nx][ny] == '#') continue;
                if (visit[nx][ny]) continue;
                q.push({nx, ny});
            }
        }
    }

    for (auto kv : cand) {
        num[kv.first][kv.second] = ans;
    }
    return num[i][j] = ans;
}

signed main() {
