void unite(ll x,ll y){
	x=find(x);
	y=find(y);
	if(x==y)return;

	if(ran[x]<ran[y]){
		par[x]=y;
	}else{
		par[y]=x;
		if(ran[x]==ran[y])ran[x]++;
	}
	sizeb[x]=sizeb[y]+sizeb[x];
	sizeb[y]=sizeb[x];
	sizew[x]=sizew[y]+sizew[x];
	sizew[y]=sizew[x];

}

