typedef long long ll;

int H, W;
string S[410];

struct UnionFind {
    vector<int> par;

    UnionFind(int N) : par(N) {
        for(int i = 0; i < N; i++) par[i] = i;
    }

    int root(int x) {
        if (par[x] == x) return x;
        return par[x] = root(par[x]);
    }

    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        par[rx] = ry;
    }

    bool same(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        return rx == ry;
    }
};

int main() {
    cin >> H >> W;
    for (int i = 0; i < H; i++) cin >> S[i];

    UnionFind tree(H*W);

    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (i >= 1 && S[i][j] != S[i-1][j]) {
                tree.unite(W*i+j, W*(i-1)+j);
            }
            if (j >= 1 && S[i][j] != S[i][j-1]) {
                tree.unite(W*i+j, W*i+(j-1));
            }
            if (i <= H-2 && S[i][j] != S[i+1][j]) {
                tree.unite(W*i+j, W*(i+1)+j);
            }
            if (j <= W-2 && S[i][j] != S[i][j+1]) {
                tree.unite(W*i+j, W*i+(j+1));
            }
        }
    }

    map<int, pair<int, int> > mp;
    for (int i = 0; i < H*W; i++) {
        int white = mp[tree.root(i)].first;
        int black = mp[tree.root(i)].second;
        if (S[i/W][i%W] == '#') {
            mp[tree.root(i)] = make_pair(white, black+1);
        }
        else {
            mp[tree.root(i)] = make_pair(white+1, black);
        }
    }    

    int ans = 0;
    for (auto itr = mp.begin(); itr != mp.end(); itr++) {
        int white = itr->second.first;
        int black = itr->second.second;
        ans += white * black;
    }

    cout << ans << endl;

    return 0;
}

