int H, W, HW;

int find(int i)
{
	if (parent[i] == i)
	{
		return i;
	}
	else
	{
		return parent[i] = find(parent[i]);
	}
}

void unite(int i, int j)
{
	i = find(i);
	j = find(j);

	if (i == j)return;

	parent[j] = i;
	white[i] += white[j];
	black[i] += black[j];

}

int index(int x,int y)
{
	return y*W + x;
}


int main()
{
	cin >> H >> W;
	HW = H*W;

	cell = mat(H, vec(W));
	parent = vec(HW, 0);
	white = vec(HW, 0);
	black = vec(HW, 0);

	for (int i = 0; i < HW; ++i)
	{
		parent[i] = i;
	}

	for (int y = 0; y < H; ++y)
	{
		string s;
		cin >> s;
		for (int x = 0; x < W; ++x)
		{

			cell[y][x] = (s[x] == '#') ? 1 : 0;

			if (cell[y][x] == 1)
			{
				black[index(x, y)] = 1;
			}
			else
			{
				white[index(x, y)] = 1;
			}

		}
	}

	for (int y = 0; y < H - 1; ++y)
	{
		for (int x = 0; x < W - 1; ++x)
		{
			if (cell[y][x] != cell[y][x + 1])
			{
				unite(index(x, y), index(x + 1, y));
			}
			if (cell[y][x] != cell[y + 1][x])
			{
				unite(index(x, y), index(x, y + 1));
			}
		}
	}

	for (int y = 0; y < H - 1; ++y)
	{
		if (cell[y][W - 1] != cell[y + 1][W - 1])
		{
			unite(index(W - 1, y), index(W - 1, y + 1));
		}
	}
	for (int x = 0; x < W - 1; ++x)
	{
		if (cell[H - 1][x] != cell[H - 1][x + 1])
		{
			unite(index(x, H - 1), index(x + 1, H - 1));
		}
	}


	int ans = 0;

	for (int i = 0; i < HW; ++i)
	{
		if (parent[i] == i)
		{
			ans += white[i] * black[i];
		}
	}

	cout << ans << endl;

	return 0;
}

