using namespace std;
int O[401][401];
bool seen[401][401];
int init(){
    for(int yi = 0; yi < 401; yi++){
        for(int xi = 0; xi < 401; xi++){
            O[yi][xi] = -1;
            seen[yi][xi] = true;
        }
    }
}
pair<ll,ll> solve(int yi,int xi,int sig){
    if(yi < 0 || xi < 0){
        return pair<ll,ll>(0,0);
    }
    if( seen[yi][xi] || O[yi][xi] != sig){
        return pair<ll,ll>(0,0);
    }
    seen[yi][xi] = true;
    pair<ll,ll> N = solve(yi + 1,xi,1-sig);
    pair<ll,ll> S = solve(yi - 1,xi,1-sig);
    pair<ll,ll> E = solve(yi ,xi + 1,1-sig);
    pair<ll,ll> W = solve(yi ,xi - 1,1-sig);
    pair<ll,ll> result = make_pair(0ll,0ll);
    result.first = N.first + S.first + E.first + W.first;
    result.second = N.second + S.second + E.second + W.second;
    if(O[yi][xi] == 0){
        result.first += 1;
    }
    if(O[yi][xi] == 1){
        result.second += 1;
    }

    return result;
}

int main() {
    ll H,W;
    cin >> H >>W;
    init();
    for(ll yi = 0; yi < H; yi++){
        string s;
        cin >> s;
        for(int xi = 0; xi < W; xi++){
            if(s[xi] == '#'){
                O[yi][xi] = 1;
            }else{
                O[yi][xi] = 0;
            }
            seen[yi][xi] = false;
        }
    }
    pair<ll,ll> bucket[H][W];
    for(int yi = 0; yi < H; yi++){
        for(int xi = 0; xi < W; xi++){
            bucket[yi][xi] = solve(yi,xi,O[yi][xi]);
        }
    }
    ll sum = 0;
    for(int yi = 0; yi < H; yi++){
        for(int xi = 0; xi < W; xi++){
            //cout << "(" << bucket[yi][xi].first << "," << bucket[yi][xi].second << ")";
            sum += bucket[yi][xi].first * bucket[yi][xi].second;
        }
        //cout << endl;
    }
    cout << sum << endl;

}

