class UnionFind {
public:
	vector<int> par;
	vector<int> rank;
	UnionFind(int n) {
		init(n);
	}
	void init(int n) {
		par.resize(n);
		for (int i = 0; i<n; i++) {
			par[i] = i;
		}
		rank.assign(n, 0);
	}
	int find(int x) {
		if (par[x] == x) {
			return x;
		} else {
			return par[x] = find(par[x]);
		}
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;

		if (rank[x] < rank[y]) {
			par[x] = y;
		} else {
			par[y] = x;
			if (rank[x] == rank[y]) rank[x]++;
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
};

int main() {
	int H, W;
	cin >> H >> W;

	vector<string> field(H);
	for(int i=0;i<H;i++) {
		cin >> field[i];
	}

	UnionFind uf(H * W);
	for(int i=0;i<H;i++) {
		for(int j=0;j<W;j++) {
			if(i + 1 < H && field[i][j] != field[i + 1][j]) {
				uf.unite(i * W + j, (i + 1) * W + j);
			}
			if (j + 1 < W && field[i][j] != field[i][j + 1]) {
				uf.unite(i * W + j, i * W + j + 1);
			}
		}
	}

	map<int, pair<int, int>> mp;
	for(int i=0;i<H;i++) {
		for(int j=0;j<W;j++) {
			auto& p = mp[uf.find(i * W + j)];
			if(field[i][j] == '#') {
				p.first++;
			}else {
				p.second++;
			}
		}
	}

	ll ans = 0;
	for(auto& p : mp) {
		ans += ll(p.second.first) * p.second.second;
	}
	cout << ans << endl;


	return 0;
}

