int dfs(int i, int j, bool was_black){


    if((was_black && masu[i][j]=='.') || (!was_black && masu[i][j]=='#')){
            visited[i][j] = true;
    }

    if(was_black && masu[i][j] == '.'){
        white++;
        REP(k,4){
            if(i+dx[k]>=0 && i+dx[k]<H && j+dy[k]>=0 && j+dy[k]<W && !visited[i+dx[k]][j+dy[k]]){
