    } else if(!was_black && masu[i][j] == '#'){
        black++;
        REP(k,4){
            if(i+dx[k]>=0 && i+dx[k]<H && j+dy[k]>=0 && j+dy[k]<W && !visited[i+dx[k]][j+dy[k]]){
                dfs(i+dx[k], j+dy[k], true);
            }
        }
    }
    return black*white;
}

