    for (int i = 0; i < H; i++)
    {
        for (int j = 0; j < W; j++)
        {
            if (S[i][j] == '#')
            {
                white[find(i * W + j)]++;
            }
            else
            {
                black[find(i * W + j)]++;
            }
        }
