            //cout << row << " " << col << endl;
            vector<vector<ll > > dist = bfs(row, col);
        }
    }

    //集計
    ll sum = 0;

    auto begin = ans.begin(), end = ans.end();
    for (auto iter = begin; iter != end; iter++) {
        sum += iter -> second;
    }

    cout << sum << endl;

}

