class UnionFind {
public:
	vector<ll>rank, parent;
	//初期化
	UnionFind(ll size) {
		rank.resize(size, 0);
		parent.resize(size, 0);
		REP(i, size)parent[i] = i;
	}
	//木の根を求める
	ll find(ll x) {
		if(parent[x] == x)return x;
		else return parent[x] = find(parent[x]);
	}
	//xとyの属する集合を併合
	void unite(ll x, ll y) {
		x = find(x);
		y = find(y);
		if(x == y)return;
		if(rank[x] < rank[y])
			parent[x] = y;
		else {
			parent[y] = x;
			if(rank[x] == rank[y])rank[x]++;
		}
	}
	//xとyが同じ集合に属するか否か
	bool same(ll x, ll y) {
		return (find(x) == find(y));
	}
	//parentの内容を出力
	void debug() {
		for(auto num : parent) {
			cout << num << " ";
		}
		cout << "more:" << endl;
		REP(i, parent.size()) {
			cout << find(i) << " ";

		}
		cout << endl << "more:" << endl;
		for(auto num : parent) {
			cout << num << " ";
		}
		cout << endl;
	}
};


