    char m[h*w];
    rep(i, h*w){
        cin >> m[i];
    }

    UnionFind uf(h*w);

    rep(i,h*w){
        if(i%w != 0 && m[i]!=m[i-1]){
            uf.unite(i-1, i);
        }
        if(i>=w && m[i]!=m[i-w]){
            uf.unite(i-w, i);
        }
    }

    int c[h*w] = {0};
    int s[h*w] = {0};
    rep(i,h*w){
        if(m[i]=='.'){
            c[uf.root(i)]++;
        }else{
            s[uf.root(i)]++;
        }
    }

    int sum = 0;
    rep(i,h*w){
        sum += c[i] * s[i];
    }
    cout << sum << endl;
}

