//検証済み
vector<ll> keta(ll x) {
	if(x == 0) return {0};
	ll n = log10(x) + 1;  // xの桁数
	vll w(n, 0);
	for(ll i = 0; i < n; i++) {
		ll p;
		p = x % 10;
		x = x / 10;
		w[n - 1 - i] = p;
	}
	return w;
}

