char parityChar[] = { '#','.' };

struct group {
	bool p;
	int numB, numW;
	ll Count() { return (ll)numB * (ll)numW; }
};

bool calcP(int i, int j, char c) {
	return parityChar[(i + j) % 2] == c;
}

void searchB(vector<vector<char>>& board, group& g,  int i, int j) {
	if (board[i][j] != '!' && g.p == calcP(i, j, board[i][j])) {
		if (board[i][j] == '#') g.numB++;
		else g.numW++;

		board[i][j] = '!';
		searchB(board, g, i + 1, j);
		searchB(board, g, i - 1, j);
		searchB(board, g, i, j - 1);
		searchB(board, g, i, j + 1);
	}
}
int main() {
	int H, W;
	cin >> H >> W;
	vector<vector<char>> board (H+2, vector<char>(W+2, '!'));
	for (int h = 1; h <= H; h++) {
		string S;
		cin >> S;
		for(int w=1; w<=W; w++){
			board[h][w] = S[w-1];
		}
	}

	ll ans = 0;
	for (int h = 1; h <= H; h++) {
		for (int w = 1; w <= W; w++) {
			if (board[h][w]!='!') {
				group g = group{ calcP(h ,w, board[h][w]),0,0 };
				searchB(board, g, h, w);
				ans += g.Count();
			}
		}
	}
	print(ans);
}

