class UnionFind {
public:
    vector <ll> par; // 各元の親を表す配列
    vector <ll> siz; // 素集合のサイズを表す配列(1 で初期化)
    vector <ll> bk;

    // Constructor
    UnionFind(ll sz_): par(sz_), siz(sz_, 1LL), bk(sz_) {
        for (ll i = 0; i < sz_; ++i){
          par[i] = i; // 初期では親は自分自身
          bk[i] = 0;
        }
    }
    void init(ll sz_) {
        siz.assign(sz_, 1LL);  // assign: 再代入
        par.resize(sz_);  // resize: 再確保
        for (ll i = 0; i < sz_; ++i) par[i] = i; // 初期では親は自分自身
    }

    // Member Function
    // Find
    ll root(ll x) { // 根の検索
        while (par[x] != x) {
            x = par[x] = par[par[x]]; // x の親の親を x の親とする
        }
        return x;
    }

    // Union(Unite, Merge)
    bool merge(ll x, ll y) {
        x = root(x);
        y = root(y);
        if (x == y) return false;
        // merge technique（データ構造をマージするテク．小を大にくっつける）
        if (siz[x] < siz[y]) swap(x, y);
        siz[x] += siz[y];
        bk[x]+=bk[y];
        par[y] = x;
        return true;
    }

    bool issame(ll x, ll y) { // 連結判定
        return root(x) == root(y);
    }

    ll size(ll x) { // 素集合のサイズ
        return siz[root(x)];
    }

    void bkp(ll x){
        bk[root(x)]++;
    }

    ll bkn(ll x){
        return bk[root(x)];
    }
};
int main() {
    int h,w;
    cin >> h >> w;
    char c[h][w];
  	UnionFind tree(h*w);
    rep(i,h){
        rep(j,w){
          cin >> c[i][j];
          if(c[i][j]=='#')tree.bkp(i*w+j);
        }
    }
    rep(i,h){
        rep(j,w){
            rep(k,4){
                if(0<=i+dx[k] && i+dx[k]<h && 0<=j+dy[k] && j+dy[k]<w){
                    if(c[i][j]!=c[i+dx[k]][j+dy[k]])tree.merge(i*w+j,(i+dx[k])*w+j+dy[k]);
                }
            }
        }
    }
    bool visited[h*w]={};
    ll sum=0;
    rep(i,h){
        rep(j,w){
          	if(!visited[tree.root(i*w+j)]){
              	visited[tree.root(i*w+j)]=true;
                ll bl=tree.bkn(i*w+j);
               	ll sai=tree.size(i*w+j);
               	sum+=bl*(sai-bl);
            }
        }
    }
    cout << sum;

}

