int H, W;

vector<vector<int>> m;
vector<vector<bool>> h;
int dr[] = {-1, 0, 1, 0};
int dc[] = { 0, 1, 0, -1};

vector<int> dfs(int r, int c, int k = -1)
{
	auto v = vector<int>(2, 0);
	if (!RANGE2D(0, 0, r, c, H, W) || h[r][c] || (k != -1 && m[r][c] + k != 1)) {
		return v;
	}
	h[r][c] = true;
	v[m[r][c]]++;
	rep(i, 4) {
		auto t = dfs(r+dr[i], c+dc[i], m[r][c]);
		v[0] += t[0];
		v[1] += t[1];
	}
	return v;
}

void init()
{
	cin >> H >> W;
	m.RS(H, vector<int>(W));
	h.RS(H, vector<bool>(W, false));
	rep(i, H) {
		rep(j, W) {
			char c;
			cin >> c;
			m[i][j] = c == '#';
		}
	}
}

void solve()
{
	int res = 0;
	rep(i, H) {
		rep(j, W) {
			auto v = dfs(i, j);
			cerr << i << " " << j << " " << v[0] << " " << v[1] << endl;
			res += v[0] * v[1];
		}
	}
	cout << res << endl;
}

