class Graph
{
private:
    int m_vertexNum;
    vector<vector<int>> m_adList;

public:
    Graph(const int N) : m_vertexNum(N)
    {
        m_adList = vector<vector<int>>(N);
    }

    void AddEdge(const int v1, const int v2)
    {
        m_adList[v1].push_back(v2);
        m_adList[v2].push_back(v1);
    }

    const vector<vector<int>> ComputeConnectedComponents() const
    {
        vector<bool> hasNotVisited(m_vertexNum, true);
        vector<vector<int>> ret;
        stack<int> stack;
        for (int v = 0; v < m_vertexNum; ++v)
        {
            if (hasNotVisited[v])
            {
                vector<int> cc;
                stack.push(v);
                hasNotVisited[v] = false;
                while (!stack.empty())
                {
                    const int u = stack.top();
                    stack.pop();
                    cc.push_back(u);
                    for (const int n : m_adList[u])
                    {
                        if (hasNotVisited[n])
                        {
                            stack.push(n);
                            hasNotVisited[n] = false;
                        }
                    }
                }
                ret.push_back(cc);
            }
        }
        return ret;
    }
};

int main()
{
    int H, W;
    cin >> H >> W;
    vector<char> squares(H * W);
    for (int row = 0; row < H; ++row)
    {
        for (int col = 0; col < W; ++col)
        {
            cin >> squares[row * W + col];
        }
    }
    // 隣接する黒マスと白マスを接続したグラフを構築し，連結成分を計算する
    Graph graph(H * W);
    for (int row = 0; row < H; ++row)
    {
        for (int col = 0; col < W; ++col)
        {
            if (col < W - 1 &&
                squares[row * W + col] != squares[row * W + col + 1])
            {
                graph.AddEdge(row * W + col, row * W + col + 1);
            }
            if (row < H - 1 && 
                squares[row * W + col] != squares[(row + 1) * W + col])
            {
                graph.AddEdge(row * W + col, (row + 1) * W + col);
            }
        }
    }
    const auto ccs = graph.ComputeConnectedComponents();
    LLONG ans = 0;
    for (const auto &cc : ccs)
    {
        LLONG blackNum = 0, whiteNum = 0;
        for (const int v : cc)
        {
            if (squares[v] == '#') ++blackNum;
            else ++whiteNum;
        }
        ans += blackNum * whiteNum;
    }
    cout << ans << endl;
}

