typedef long long ll;
typedef pair<ll, ll> P;

int mp[500][500];
int main()
{
  int H, W;
  cin >> H >> W;
  vector<pair<int, int>> pB;
  REP(i, H) REP(j, W) {
    char c; cin >> c;
    if (c == '#') {
      mp[i][j] = 1;
      pB.PB(MP(i, j));
    } else mp[i][j] = -1;
  }

  int dx[] = {-1, 0, 1, 0};
  int dy[] = {0, -1, 0, 1};
  int ans = 0;
  REP(i, pB.size()) {
    queue<pair<int, int>> q;
    q.push(MP(pB[i].FI, pB[i].SE));
    bool used[500][500] = { };
    used[pB[i].FI][pB[i].SE] = true;
    while (! q.empty()) {
      pair<int, int> pos = q.front(); q.pop();
      int y = pos.FI;
      int x = pos.SE;
      REP(j, 4) {
        int ny = y + dy[j];
        int nx = x + dx[j];
        if (0 <= ny && ny < H && 0 <= nx && nx < W
            && !used[ny][nx] && mp[y][x] * mp[ny][nx] == -1) {
          used[ny][nx] = true;
          q.push(MP(ny, nx));
          if (mp[ny][nx] == -1) ans++;
        }
      }
    }
  }
  cout << ans << endl;
  return 0;
}

