int n, m;
long long ans;
char map[401][401];
bool vis[401][401];
int dx[4] = {0, 0, -1, 1}, dy[4] = {1, -1, 0, 0};
int sdx[10001], sdy[10001];

void bfs(int sx, int sy) {
	int head = 0, tail = 1, w = 0, h = 0;
	sdx[tail] = sx, sdy[tail] = sy;
	if (map[sx][sy] == '#') ++w;
	else ++h;
	while(head < tail) {
		++head;
		for (int i = 0; i <= 3; ++i) {
			int c = sdx[head] + dx[i], d = sdy[head] + dy[i];
			if (c > 0 && c <= n && d > 0 && d <= m && !vis[c][d] && map[sdx[head]][sdy[head]] != map[c][d]) {
				if (map[c][d] == '#') ++w;
				else ++h;
				vis[c][d] = 1, ++tail;
				sdx[tail] = c, sdy[tail] = d;
			}
		}
	}
	ans += 1ll * w * h;
}

int main() {
	scanf("%d %d", &n, &m);
	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j <= m; ++j) {
			std::cin >> map[i][j];
		}
	}
	for (int i = 1; i <= n; ++i) {
		for (int j = 1; j <= m; ++j) {
			if (!vis[i][j]) vis[i][j] = 1, bfs(i, j);
		}
	}
	printf("%lld\n", ans);
	return 0;
}

