    visited[i] = 0;
    queue[i] = -1;
  }
  visited[0] = 1;
  queue[0] = 0;
  long head = 0, tail = 0, start = 0, end = 0, cur, flag;
  long ans = 0;
  long black = 0, white = 0;
  if (s[0][0] == '#') {
    black++;
  } else {
    white++;
  }
  while (1) {
    flag = 0;
    for (long i = start; i <= end; i++) {
      cur = queue[i];
      if (cur%w != 0 && visited[cur-1] == 0 && s[cur/w][cur%w] != s[cur/w][cur%w-1]) {
        if (s[cur/w][cur%w-1] == '#') {
          black++;
        } else {
          white++;
        }
        visited[cur-1] = 1;
        tail++;
        queue[tail] = cur-1;
        flag = 1;
      }
      if (cur%w != w-1 && visited[cur+1] == 0 && s[cur/w][cur%w] != s[cur/w][cur%w+1]) {
        if (s[cur/w][cur%w+1] == '#') {
          black++;
        } else {
          white++;
        }
        visited[cur+1] = 1;
        tail++;
        queue[tail] = cur+1;
        flag = 1;
      }
      if (cur/w != 0 && visited[cur-w] == 0 && s[cur/w][cur%w] != s[cur/w-1][cur%w]) {
        if (s[cur/w-1][cur%w] == '#') {
          black++;
        } else {
          white++;
        }
        visited[cur-w] = 1;
        tail++;
        queue[tail] = cur-w;
        flag = 1;
