        visited[cur+w] = 1;
        tail++;
        queue[tail] = cur+w;
        flag = 1;
      }
    }
    if (flag == 0) {
      ans += black*white;
      if (tail == h*w-1) {
        break;
      } else {
        black = 0;
        white = 0;
