void dfs(int x, int y, int k)
{
	visited[x][y] = k;
	count++;
	if (s[x][y] == '#')
		cb++;
	else
		cw++;
	if (x > 0)
		if (s[x][y] != s[x - 1][y] && visited[x - 1][y] == 0)
			dfs(x - 1, y, k);
	if (y > 0)
		if (s[x][y] != s[x][y - 1] && visited[x][y - 1] == 0)
			dfs(x, y - 1, k);
	if (x < h - 1)
		if (s[x][y] != s[x + 1][y] && visited[x + 1][y] == 0)
			dfs(x + 1, y, k);
	if (y < w - 1)
		if (s[x][y] != s[x][y + 1] && visited[x][y + 1] == 0)
			dfs(x, y + 1, k);
	return;
}
int main()
{
	scanf("%d %d", &h, &w);
	int i, j;
	for (i = 0; i < h; i++)
		scanf("%s", s[i]);
	for (i = 0; i < h; i++)
		for (j = 0; j < w; j++)
			visited[i][j] = 0;
	int k = 1;
	long long int ans = 0;
	for (i = 0; i < h; i++)
	{
		for (j = 0; j < w; j++)
		{
			if (visited[i][j] == 0)
			{
				cw = cb = 0;
				dfs(i, j, k);
				ans += cw * cb;
				k++;
			}
		}
	}
	printf("%lld\n", ans);
	return 0;
}

