		for (sll x = 0; x <= maxv - 1; x++) {
			for (sll y = 0; y <= maxu - 1; y++) {

				for (sll z1 = 0; z1 <= 1; z1++) {

					for (sll z2 = 0; z2 <= 1; z2++) {

						tmp[z1 | z2][x + y] = smin(tmp[z1 | z2][x + y], dp[v][z1][x] + dp[u][z2][y]);
