						}
					}
				}

			}
		}
		for (sll x = 0; x < e[v]; x++) {
			dp[v][0][x] = tmp[0][x];
			dp[v][1][x] = tmp[1][x];
			// printf("%lld/%lld: %lld, %lld\n", v, x, dp[v][0][x], dp[v][1][x]);
