	a = uf_find(a);
	b = uf_find(b);
	if (a == b) return false;

	if (size[a] < size[b]) {
		a ^= b;
		b ^= a;
		a ^= b;
	}
	p[b] = a;
	size[a] += size[b];
	return true;
}

