		countb++;
	else
		countw++;
	if (x > 0)
		if (s[x][y] != s[x - 1][y] && visited[x - 1][y] < 0)
			dfs(x - 1, y, k);
	if (y > 0)
		if (s[x][y] != s[x][y - 1] && visited[x][y - 1] < 0)
			dfs(x, y - 1, k);
	if (x < h - 1)
		if (s[x][y] != s[x + 1][y] && visited[x + 1][y] < 0)
			dfs(x + 1, y, k);
	if (y < w - 1)
		if (s[x][y] != s[x][y + 1] && visited[x][y + 1] < 0)
			dfs(x, y + 1, k);
	return;
}
