// マス数 - 取得
int
fGetMCnt(
	int piX						// <I> 位置X
	, int piY					// <I> 位置Y
	, char pcMass				// <I> 対象マスの色
	, int *pipBCnt				// <O> 黒数
	, int *pipWCnt				// <O> 白数
)
{
	// 対象マスの色 - チェック
	if (sc2Mass[piY][piX] != pcMass) {
		return 0;
	}

	// 処理済
	sc2Mass[piY][piX] = 0;

	// 色数・次の色
	if (pcMass == D_MASS_BLACK) {		// 黒
		(*pipBCnt)++;
		pcMass = D_MASS_WHITE;
	}
	else {								// 白
		(*pipWCnt)++;
		pcMass = D_MASS_BLACK;
	}

	// 上下左右へ
	fGetMCnt(piX + 1, piY, pcMass, pipBCnt, pipWCnt);
	fGetMCnt(piX - 1, piY, pcMass, pipBCnt, pipWCnt);
	fGetMCnt(piX, piY + 1, pcMass, pipBCnt, pipWCnt);
	fGetMCnt(piX, piY - 1, pcMass, pipBCnt, pipWCnt);

	return 0;
}

