#include <stdio.h>

int root_check(int h, int w, char s[h][w+1], int start_x, int start_y, int gole_x, int gole_y, int visit[h][w+1]){

    if(visit[start_x][start_y])
        return 0;
    visit[start_x][start_y] = 1;
    if(start_x == gole_x && start_y == gole_y)
        return 1;
    if(start_x > 0 && s[start_x][start_y] != s[start_x-1][start_y]){
        if(root_check(h, w, s, start_x-1, start_y, gole_x, gole_y, visit))
            return 1;
    }
    if(start_x < h-1 && s[start_x][start_y] != s[start_x+1][start_y]){
        if(root_check(h, w, s, start_x+1, start_y, gole_x, gole_y, visit))
            return 1;
    }
    if(start_y > 0 && s[start_x][start_y] != s[start_x][start_y-1]){
        if(root_check(h, w, s, start_x, start_y-1, gole_x, gole_y, visit))
            return 1;
    }
    if(start_y < w-1 && s[start_x][start_y] != s[start_x][start_y+1]){
        if(root_check(h, w, s, start_x, start_y+1, gole_x, gole_y, visit))
            return 1;
    }
    return 0;
}

int black_white(int h, int w, char s[h][w+1], int x, int y){
    int count = 0;
    int i, j;
    int visit[h][w+1];

    for(i = 0; i < h;i++){
        //printf("\n");
        for(j = 0; j < w; j++){
           // printf("%c", s[i][j]);
            if(s[i][j] == '.'){
               // printf("%d %d\n", i,j);
                for(int a=0;a<h;a++)
                    for(int b=0;b<=w; b++)
                        visit[a][b] = 0;    
                count += root_check(h, w, s, x, y, i, j, visit);
               // printf("(%d %d)(%d %d) %d\n",x, y,i,j,count);
            }
        }
    }
    return count;
}

int count_root(int h, int w, char s[h][w+1]){
    int i, j, count = 0;
    for(i = 0; i < h;i++){
        for(j = 0; j < w; j++){
            if(s[i][j] == '#'){
                count += black_white(h, w, s, i, j);
            }
        }
    }

    return count;
}

