#include<stdlib.h>

typedef long long int int64;

#define POS(i,j) ((i)*w+(j))

void run(void){
  int h,w;
  scanf("%d%d",&h,&w);
  char *s=(char *)calloc(h*w+1,sizeof(char));
  int i;
  for(i=0;i<h;i++) scanf("%s",s+i*w);
  char *used=(char *)calloc(h*w,sizeof(char));
  int *now=(int *)calloc(h*w,sizeof(int));
  int *next=(int *)calloc(h*w,sizeof(int));
  int64 ans=0;
  for(i=0;i<h*w;i++){
    if(used[i]) continue;
    used[i]=1;
    int cnt[2]={0,0};
    int k=0;
    int top=0;
    now[top++]=i;
    while(top>0){
      int nextTop=0;
      while(top>0){
	cnt[k]++;
	int p=now[--top];
	int x=p/w;
	int y=p%w;
	int d[4]={-1,0,1,0};
	for(i=0;i<4;i++){
	  int a=x+d[i];
	  int b=y+d[i^1];
	  if(0<=a && a<h && 0<=b && b<w && s[POS(x,y)]!=s[POS(a,b)] && !used[POS(a,b)]){
	    used[POS(a,b)]=1;
	    next[nextTop++]=a*w+b;
	  }
	}
      }
      int *swap=now;
      now=next;
      next=swap;
      top=nextTop;
      k^=1;
    }
    ans+=(int64)cnt[0]*cnt[1];
  }
  printf("%lld\n",ans);
}

int main(void){
  run();
  return 0;
}

