int H, W;
char text[400][401];
int buf[400][400];
int ans = 0;

void loop(int x1, int y1, int last){
  if(x1 < 0 || x1 >= W|| y1 < 0 || y1 >= H){
    return;
  }
  if(text[y1][x1] == last || buf[y1][x1]){
  	return;
  }
  if(text[y1][x1] == '#'){
    ans++;
  }
  buf[y1][x1] = 1;
  int a = text[y1][x1];
  loop(x1 + 1, y1, a);
  loop(x1 - 1, y1, a);
  loop(x1, y1 + 1, a);
  loop(x1, y1 - 1, a);
}

void reset(){
  int x, y;
  for(y = 0; y < H; y++){
    for(x = 0; x < W; x++){
      buf[y][x] = 0;
    }
  }
}

int main(void){
  scanf("%d %d", &H, &W);
  int x, y;
  reset();
  for(y = 0; y < H; y++){
    scanf("%s", text[y]);
  }
  for(y = 0; y < H; y++){
    for(x = 0; x < W; x++){
      reset();
      if(text[y][x] == '.'){
        loop(x, y, 'x');
      }
    }
  }
  printf("%d\n", ans);
  return 0;
}

