class GridBfs(val G: List<String>) {
    data class Pos(val x: Int, val y: Int)
    val H = G.size
    val W = G[0].length
    private val dx = intArrayOf(0,1,0,-1)
    private val dy = intArrayOf(1,0,-1,0)

    fun goalNum(SX: Int, SY: Int): Int {
        val que = ArrayDeque<Pos>()
        que.addLast(Pos(SX, SY))
        val goal = Array(H){IntArray(W){0}}
        val vis = Array(H){BooleanArray(W){false}}
        while (que.isNotEmpty()) {
            val (x, y) = que.removeFirst()

            vis[x][y] = true

            for(i in dx.indices) {
                val nx = x + dx[i]; val ny = y + dy[i]
                if (nx<0 || H<=nx || ny<0 || W<=ny) {
                    continue
                }
                if (G[nx][ny] == G[x][y]) {
                    continue
                }

                if (G[nx][ny] == '.') {
                    goal[nx][ny] = 1
                }

                if (!vis[nx][ny]) {
                    que.push(Pos(nx, ny))
                }
            }
        }

        return goal.map{ it.sum() }.sum()
    }
}

fun solve() {
    val (H, W) = rd.readListInt()
    val G = (0 until H).map { rd.readString() }

    val gbfs = GridBfs(G)

    var ans = 0
    for (i in 0 until H) {
        for (j in 0 until W) {
            if (G[i][j] == '#') {
                ans += gbfs.goalNum(i, j)
            }
        }
    }

    println(ans)
}


