    for (i in 0 until h) for (j in 0 until w) {
        if (!board[i][j] || visited[i][j]) continue
        visited[i][j] = true

        var blackCount = 0L
        var whiteCount = 0L

        val queue = ArrayDeque(listOf(i to j))

        while (queue.isNotEmpty()) {
            val (y, x) = queue.removeFirst()
            if (board[y][x]) blackCount++ else whiteCount++
            queue += around.map { y - it.first to x - it.second }
                .filter { (ny, nx) ->
                    ny in 0 until h && nx in 0 until w && board[ny][nx] != board[y][x] &&
                            visited.let {
                                if (it[ny][nx]) false else {
                                    it[ny][nx] = true
                                    true
                                }
                            }
                }
        }

        answer += blackCount * whiteCount
    }

    println(answer)
}

