class GridBfs(val G: List<String>) {
    val H = G.size
    val W = G[0].length
    private val dx = intArrayOf(0,1,0,-1)
    private val dy = intArrayOf(1,0,-1,0)

    val grp = Array(H){IntArray(W){INF}}
    val mp = mutableMapOf<Int, Int>()

    fun countGoals(group: Int, SX: Int, SY: Int): Int {
        if (grp[SX][SY] < group) return mp[grp[SX][SY]] ?: 0

        val que = ArrayDeque<Pos>()
        que.addLast(Pos(SX, SY))

        val goal = Array(H){IntArray(W){0}}

        while (que.isNotEmpty()) {
            val (x, y) = que.removeFirst()

            grp[x][y] = min(grp[x][y], group)

            for(i in dx.indices) {
                val nx = x + dx[i]; val ny = y + dy[i]
                if (nx<0 || H<=nx || ny<0 || W<=ny) {
                    continue
                }
                if (G[nx][ny] == G[x][y]) {
                    continue
                }

                if (G[nx][ny] == '.') {
                    goal[nx][ny] = 1
                }

                if (grp[nx][ny] > grp[x][y]) {
                    que.push(Pos(nx, ny))
                }
            }
        }

        val res = goal.map{ it.sum() }.sum()
        mp[group] = res
        return res
    }
}

