                val right = if (j<W-1) G[i][j+1] else '#'
                val bottom = if (i<H-1) G[i+1][j] else '#'
                val left = if (0<j) G[i][j-1] else '#'

                if (up=='.' || right=='.'
                        || bottom=='.' || left=='.') {
                    starts.add(Pos(i,j))
                }
            }
        }
    }

    for (i in 0 until starts.size) {
        gbfs.countGoals(i, starts[i].x, starts[i].y)
    }

    var ans = 0
    for (s in starts) {
        val group = gbfs.grp[s.x][s.y]
        if (group<INF) ans += gbfs.mp[group]!!
    }

    println(ans)
}


