        if (x + 1 < w && board[y][x] != board[y][x + 1]) uf.unite(toIndex(y, x), toIndex(y, x + 1))
        if (y + 1 < h && board[y][x] != board[y + 1][x]) uf.unite(toIndex(y, x), toIndex(y + 1, x))
    }

    val blackCountByGroup = IntArray(gridSize)
    val whiteCountByGroup = IntArray(gridSize)

    for (y in 0 until h) for (x in 0 until w) {
        val groupRoot = uf.root(toIndex(y, x))
        if (board[y][x]) blackCountByGroup[groupRoot]++ else whiteCountByGroup[groupRoot]++
    }

    val answer = (0 until gridSize)
        .map { blackCountByGroup[it].toLong() * whiteCountByGroup[it] }.sum()

    println(answer)
}

private class UnionFind(initSize: Int) {
    private val parent = IntArray(initSize) { it }
    private val size = LongArray(initSize) { 1L }

    fun root(x: Int): Int {
        if (x == parent[x]) return x

        val xr = root(parent[x])
        parent[x] = xr
        return xr
    }

    fun unite(x: Int, y: Int) {
        val xr = root(x)
        val yr = root(y)
        if (xr == yr) return

        if (size[xr] >= size[yr]) {
            size[xr] += size[yr]
            parent[yr] = xr
        } else {
            size[yr] += size[xr]
            parent[xr] = yr
        }
    }

    fun isSame(x: Int, y: Int): Boolean = root(x) == root(y)

    fun unite(pair: Pair<Int, Int>): Unit = unite(pair.first, pair.second)
    fun isSame(pair: Pair<Int, Int>): Boolean = isSame(pair.first, pair.second)

    fun size(x: Int): Long = size[root(x)]
}

