        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                // right
                if (j < w - 1) {
                    if (black[i][j] != black[i][j+1]) {
                        int root = this.rootOf(i, j+1, h, ids);
                        int I = root % h;
                        int J = root / h - 1;
                        ids[I][J] = ids[i][j];
                    }
                }

                // down
                if (i < h - 1) {
                    if (black[i][j] != black[i+1][j]) {
                        int root = this.rootOf(i+1, j, h, ids);
                        int I = root % h;
                        int J = root / h - 1;
                        ids[I][J] = ids[i][j];
                    }
                }
            }
        }

        int[] blackCount = new int[(h + 1) * (w + 2) + 1];
        int[] whiteCount = new int[(h + 1) * (w + 2) + 1];
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                int root = this.rootOf(i, j, h, ids);
                if (black[i][j]) {
                    blackCount[root]++;
                } else {
                    whiteCount[root]++;
                }
            }
        }

        int result = 0;
        int last = (h + 1) * (w + 2) + 1;
        for (int i = 0; i < last; i++) {
            result += (blackCount[i] * whiteCount[i]);
        }
        System.out.println(result);
    }

    private int rootOf(int i, int j, int h, int[][] ids) {
        int root = ids[i][j];
        int I = i;
        int J = j;
        while (true) {
            int nextI = root % h;
            int nextJ = root / h - 1;
            if (I != nextI || J != nextJ) {
                root = ids[nextI][nextJ];
                I = nextI;
                J = nextJ;
            } else {
                break;
            }
        }
        return root;
    }
}

import java.util.AbstractMap;
import java.util.Queue;
import java.util.Scanner;
import java.util.concurrent.ArrayBlockingQueue;

public class Main {

    static Scanner scanner;

    public static void main(String[] args) {
        scanner = new Scanner(System.in);

        int H=gi();
        int W=gi();
        char[][] g=new char[H][W];
        boolean[][] f=new boolean[H][W];

        for (int i=0; i<H;i++) {
            String s=gs();
        	for (int j=0; j<W;j++) {
                char c=s.charAt(j);
                g[i][j]=c;
            }
        }
        long ans=0;
        for (int i=0; i<H;i++) {
        	for (int j=0; j<W;j++) {
        		if(f[i][j]) continue;
                Queue<Pair<Integer,Integer>> q=new ArrayBlockingQueue<Pair<Integer,Integer>>(H*W);
                q.add(new Pair<Integer,Integer>(i,j));
                f[i][j]=true;
                long sharp =0;
                long dot=0;
                while(!q.isEmpty()) {
                	Pair<Integer,Integer> p=q.poll();
                	int h=p.getKey();
                	int w=p.getValue();
                	char c=g[h][w];
                	if(c=='#') {
                		sharp++;
                	} else {
                		dot++;
                	}
                	if (h-1>=0 && f[h-1][w]==false && c!=g[h-1][w]) {
                		f[h-1][w]=true;
                		q.add(new Pair<Integer,Integer>(h-1,w));
                	}
                	if (w-1>=0 && f[h][w-1]==false && c!=g[h][w-1]) {
                		f[h][w-1]=true;
                		q.add(new Pair<Integer,Integer>(h,w-1));
                	}
                	if (h+1<H && f[h+1][w]==false && c!=g[h+1][w]) {
                		f[h+1][w]=true;
                		q.add(new Pair<Integer,Integer>(h+1,w));
                	}
                	if (w+1<W && f[h][w+1]==false && c!=g[h][w+1]) {
                		f[h][w+1]=true;
                		q.add(new Pair<Integer,Integer>(h,w+1));
                	}
                }
                ans+=sharp*dot;
                if(f[i][W-1])break;
            }
        }

        System.out.println(ans);
    }

    public static class Pair<K, V> extends AbstractMap.SimpleEntry<K, V> implements Comparable<Pair<K, V>> {
        /** serialVersionUID. */
        private static final long serialVersionUID = 6411527075103472113L;

        public Pair(final K key, final V value) {
            super(key, value);
        }

        @Override
        public int compareTo(Pair<K, V> o) {

            Comparable key = (Comparable)this.getKey();
            Comparable key2 = (Comparable)o.getKey();

            return key.compareTo(key2);
        }

    }

    // 文字列として入力を取得
    public static String gs() {
         return scanner.next();
    }

    // intとして入力を取得
    public static int gi() {
         return Integer.parseInt(scanner.next());
    }

    // longとして入力を取得
    public static long gl() {
         return Long.parseLong(scanner.next());
    }

    // doubleとして入力を取得
    public static double gd() {
         return Double.parseDouble(scanner.next());
    }
}

import java.awt.Point;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Queue;
import java.util.Scanner;

public class Main {
	static int[] dw = { 1, 0, -1, 0 };
	static int[] dh = { 0, 1, 0, -1 };
	static int H;
	static int W;
	static int black;
	static int white;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		H = sc.nextInt();
		W = sc.nextInt();
		ArrayList<String> Sh = new ArrayList<>(450);
		for (int i = 0; i < H; i++) {
			Sh.add(sc.next());
		}
		Queue<Point> queue = new ArrayDeque<>();
		int[][] reached = new int[500][500];
		int ans = 0;
		for (int i = 0; i < W; i++) {
			for (int j = 0; j < H; j++) {
				black=0;
				white=0;
				if (Sh.get(j).charAt(i) == '#' && reached[j][i] == 0) {
					reached[j][i]++;
					black++;
					queue.offer(new Point(j, i));
					bfs(queue, Sh, reached);
//					System.out.println("black = " + black + "white = " + white);
					ans += black * white;
				}
			}
		}

		System.out.println(ans);

		sc.close();
	}

	public static void bfs(Queue<Point> queue, ArrayList<String> S, int[][] reached) {
//		 System.out.println("BFS!! " + queue.peek());
		while (queue.peek() != null) {
			Point p = queue.poll();
			if (p == null) {
				return;
			}
//			 System.out.println("(" + p.x + "," + p.y + ")" + " = " + S.get(p.x).charAt(p.y));
			if (S.get(p.x).charAt(p.y) == '#') {
				for (int k = 0; k < 4; k++) {
					if (p.x + dh[k] > H - 1 || p.x + dh[k] < 0 || p.y + dw[k] > W - 1 || p.y + dw[k] < 0) {
						continue;
					}
					if (reached[p.x + dh[k]][p.y + dw[k]] > 0)
						continue;
					if (S.get(p.x + dh[k]).charAt(p.y + dw[k]) == '.') {
						queue.offer(new Point(p.x + dh[k], p.y + dw[k]));
						reached[p.x + dh[k]][p.y + dw[k]]++;
						white++;
					}
				}
			} else {
				for (int k = 0; k < 4; k++) {
					if (p.x + dh[k] > H - 1 || p.x + dh[k] < 0 || p.y + dw[k] > W - 1 || p.y + dw[k] < 0) {
						continue;
					}
					if (reached[p.x + dh[k]][p.y + dw[k]] > 0)
						continue;
					if (S.get(p.x + dh[k]).charAt(p.y + dw[k]) == '#') {
						queue.offer(new Point(p.x + dh[k], p.y + dw[k]));
						reached[p.x + dh[k]][p.y + dw[k]]++;
						black++;
					}
				}
			}
			bfs(queue,S,reached);
		}

	}
}

