import java.util.*;

public class Main {
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		int h = sc.nextInt();
		int w = sc.nextInt();
		char[][] field = new char[h][];
		for (int i = 0; i < h; i++) {
			field[i] = sc.next().toCharArray();
		}
		UnionFindTree uft = new UnionFindTree(h, w);
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (j != w - 1 && field[i][j] != field[i][j + 1]) {
					uft.union(j, i, j + 1, i);
				}
				if (i != h - 1 && field[i][j] != field[i + 1][j]) {
					uft.union(j, i, j, i + 1);
				}
			}
		}
		int count = 0;
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (field[i][j] == '#') {
					for (int k = 0; k < h; k++) {
						for (int l = 0; l < w; l++) {
							if (field[k][l] == '.' && uft.same(j, i, l, k)) {
								count++;
							}
						}
					}
				}
			}
		}
		System.out.println(count);
	}

	static class UnionFindTree {

		int[] parent;
		int w;

		public UnionFindTree(int h, int w) {
			this.w = w;
			parent = new int[h * w];
			for (int i = 0; i < h * w; i++) {
				parent[i] = i;
			}
		}

		public int find(int i) {
			if (parent[i] == i) {
				return i;
			}
			int p = find(parent[i]);
			parent[i] = p;
			return p;
		}

		public int find(int x, int y){
			return find(x + y * w);
		}

		public boolean same(int a, int b) {
			return (find(a) == find(b));
		}

		public boolean same(int ax, int ay, int bx, int by) {
			return same(ax + ay * w, bx + by * w);
		}

		public void union(int a, int b) {
			parent[a] = find(b);
		}

		public void union(int ax, int ay, int bx, int by) {
			union(ax + ay * w, bx + by * w);
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;

public class Main {

	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		MyInput in = new MyInput(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskX solver = new TaskX();
		solver.solve(1, in, out);
		out.close();
	}

	static int INF = 1 << 30;
	static long LINF = 1L << 55;
	static int MOD = 1000000007;
	static int[] mh4 = { 0, -1, 1, 0 };
	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {

		int h, w;
		char[][] s;
		public void solve(int testNumber, MyInput in, PrintWriter out) {

			h = in.nextInt(); w = in.nextInt();
			UnionFind uf = new UnionFind(h * w);

			s = new char[h][w];
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					s[i][j] = in.nextChar();
					if (s[i][j] == '#') uf.add(f(i, j), 1);
				}
			}

			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					for (int k = 0; k < 4; k++) {
						int mh = i + mh4[k];
						int mw = j + mw4[k];
						if (inside(mh, mw) && ((s[i][j] == '#' && s[mh][mw] == '.') || (s[i][j] == '.' && s[mh][mw] == '#'))) {
							uf.union(f(i, j), f(mh, mw));
						}
					}
				}
			}

			long ans = 0;
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					if (uf.root(f(i, j)) == f(i, j)) {
						long c = uf.black[uf.root(f(i, j))];
						ans += c * (uf.size(f(i, j)) - c);
					}
				}
			}

			out.println(ans);
		}

		boolean inside(int i, int j) {
			return 0 <= i && i < h && 0 <= j && j < w;
		}

		int f(int i, int j) {
			return i * w + j;
		}

		class UnionFind {
			int[] data;
			long[] black;

			public UnionFind(int size) {
				data = new int[size];
				black = new long[size];
				Arrays.fill(data, -1);
			}

			public int root(int x) {
				return data[x] < 0 ? x : (data[x] = root(data[x]));
			}

			public void add(int x, int v) {
				black[x] += v;
			}

			public void union(int x, int y) {
				x = root(x);
				y = root(y);

				if (x != y) {
					if (data[y] > data[x]) {
						final int t = x;
						x = y;
						y = t;
					}

					data[x] += data[y];
					data[y] = x;
					black[x] += black[y];
				}
			}

			boolean same(int x, int y) {
				return root(x) == root(y);
			}

			public long size(int x) {
				return -data[root(x)];
			}
		}
	}

	static class MyInput {
		private final BufferedReader in;
		private static int pos;
		private static int readLen;
		private static final char[] buffer = new char[1024 * 8];
		private static char[] str = new char[500 * 8 * 2];
		private static boolean[] isDigit = new boolean[256];
		private static boolean[] isSpace = new boolean[256];
		private static boolean[] isLineSep = new boolean[256];

		static {
			for (int i = 0; i < 10; i++) {
				isDigit['0' + i] = true;
			}
			isDigit['-'] = true;
			isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
			isLineSep['\r'] = isLineSep['\n'] = true;
		}

		public MyInput(InputStream is) {
			in = new BufferedReader(new InputStreamReader(is));
		}

		public int read() {
			if (pos >= readLen) {
				pos = 0;
				try {
					readLen = in.read(buffer);
				} catch (IOException e) {
					throw new RuntimeException();
				}
				if (readLen <= 0) {
					throw new MyInput.EndOfFileRuntimeException();
				}
			}
			return buffer[pos++];
		}

		public int nextInt() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			int ret = 0;
			if (str[0] == '-') {
				i = 1;
			}
			for (; i < len; i++)
				ret = ret * 10 + str[i] - '0';
			if (str[0] == '-') {
				ret = -ret;
			}
			return ret;
		}

		public long nextLong() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			int i = 0;
			long ret = 0;
			if (str[0] == '-') {
				i = 1;
			}
			for (; i < len; i++)
				ret = ret * 10 + str[i] - '0';
			if (str[0] == '-') {
				ret = -ret;
			}
			return ret;
		}

		public char nextChar() {
			while (true) {
				final int c = read();
				if (!isSpace[c]) {
					return (char) c;
				}
			}
		}

		public String nextString() {
			return new String(nextChars());
		}

		public char[] nextChars() {
			int len = 0;
			str[len++] = nextChar();
			len = reads(len, isSpace);
			return Arrays.copyOf(str, len);
		}

		int reads(int len, boolean[] accept) {
			try {
				while (true) {
					final int c = read();
					if (accept[c]) {
						break;
					}
					if (str.length == len) {
						char[] rep = new char[str.length * 3 / 2];
						System.arraycopy(str, 0, rep, 0, str.length);
						str = rep;
					}
					str[len++] = (char) c;
				}
			} catch (MyInput.EndOfFileRuntimeException e) {
			}
			return len;
		}

		public int[] nextIntArray(final int n) {
			final int[] res = new int[n];
			for (int i = 0; i < n; i++) {
				res[i] = nextInt();
			}
