    String[] strs = new String[h];
    for(int i = 0; i < h; i++){
      strs[i] = sc.nextStr();
    }

    char[][] table = new char[h][w];
    for(int i = 0; i < h; i++){
      for(int j = 0; j < w; j++){
        table[i][j] = strs[i].charAt(j);
      }
    }

    int ans = 0;

    for(int i = 0; i < h; i++){
      for(int j = 0; j < w; j++){
        if(table[i][j] == '.'){continue;}//白やったら無視

        boolean[][] checks = new boolean[h][w];
        for(int k = 0; k < h; k++){
          for(int l = 0; l < w; l++){
            checks[k][l] = false;
          }
        }

