        if(c=='#')
            c='.';
        else
            c='#';
        if(c=='.')
        {
            //System.out.println(hi+" "+wi);
            ++ways;
        }
        visited[hi][wi]=true;


        if(hi+1<arr.length)
        {
            recursion(arr,hi+1,wi,c,visited);
        }

        if(wi+1<arr[hi].length)
        {
            recursion(arr,hi,wi+1,c,visited);
        }
    }
