public class Main {
    public static void main(String[] $) {
        Scanner sc = new Scanner(in);
        int h=sc.nextInt();
        int w=sc.nextInt();
        char[][] f=new char[h][w];
        for (int i = 0; i < h; i++) {
            String t=sc.next();
            for (int j = 0; j < w; j++) {
                f[i][j]=t.charAt(j);
            }
        }
        long ans=0;
        int[] dx={-1,0,1,0};
        int[] dy={0,-1,0,1};
        int[][] node=new int[h][w];
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                int tempW=0,tempB=0;
                if(node[i][j]!=0)break;
                Queue<Point> q=new ArrayDeque<>();
                q.add(new Point(i,j));
                while (!q.isEmpty()) {
                    Point p = q.poll();
                    if(f[p.x][p.y]=='.')tempW++;
