                        if (0 <= x && x < h && 0 <= y && y < w) {
                            if (node[x][y] == 0 && f[p.x][p.y] != f[x][y]) {
                                q.add(new Point(x, y));
                                node[x][y]=1;
                            }
                        }
                    }
                }
                ans+=tempB*tempW;
            }
        }
        out.println(ans);
    }
}

