			if(g[y][x] == 1) {
				continue;
			}
			g[y][x] = 1;
			h[y][x] = 1;
			m[y][x] = false;
			rec('#', x, y);

			int k = y * W + x;
			set2.add(k);
			cnt1 = set1.size();
			cnt2 = set2.size();

			//System.out.println(cnt1 +" " + cnt2);
