					int k = ny * W + nx;
					m[ny][nx] = false;
					set1.add(k);
					rec('.', nx, ny);
				}else if(color == '.' && m[ny][nx] && c[ny][nx] == '#') {
					g[ny][nx] = 1;
					m[ny][nx] = false;
					int k = ny * W + nx;
					set2.add(k);
					rec('#', nx, ny);
				}
			}
