import java.util.*;
import java.io.*;

public class Main {
    static char[][] map;
    static boolean[][] arrived;
    public static void main(String[] args) throws Exception {
        FastScanner sc = new FastScanner(System.in);
        int h = sc.nextInt();
        int w = sc.nextInt();
        map = new char[h][w];
        for(int i = 0; i < h; i++){
            map[i] = sc.next().toCharArray();
        }
        arrived = new boolean[h][w];
        long ans = 0;
        for(int i = 0; i < h; i++){
            for(int j = 0; j < w; j++){
                if(!arrived[i][j]){
                    arrived[i][j] = true;
                    ans += bfs(i, j, h, w);
                }
            }
        }
        System.out.println(ans);
    }

    public static int bfs(int i, int j, int h, int w){
        int dot = 0;
        int sharp = 0;
        int[] my = {-1,0,0,1};
        int[] mx = {0,-1,1,0};
        Deque<Panel> dq = new ArrayDeque<Panel>();
        dq.add(new Panel(i,j));
        while(dq.size() > 0){
            Panel p = dq.poll();
            int y = p.y;
            int x = p.x;
            if(map[y][x] == '#'){
                sharp++;
            }else{
                dot++;
            }
            for(int ii = 0; ii < 4; ii++){
                int ny = y + my[ii];
                int nx = x + mx[ii];
                if(checkPanel(ny,nx,h,w) && !arrived[ny][nx] && map[y][x] != map[ny][nx]){
                    arrived[ny][nx] = true;
                    dq.add(new Panel(ny,nx));
                }
            }
        }
        return sharp*dot;
    }

    public static boolean checkPanel(int y, int x, int h, int w){
        return (0 <= y && y < h && 0 <= x && x < w);
    }
}

class Panel{
    int x,y;
    public Panel(int y, int x){
        this.x = x;
        this.y = y;
    }
}

class FastScanner {
    private BufferedReader reader = null;
    private StringTokenizer tokenizer = null;
    public FastScanner(InputStream in) {
        reader = new BufferedReader(new InputStreamReader(in));
        tokenizer = null;
    }

    public String next() {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public String nextLine() {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken("\n");
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public double nextDouble() {
         return Double.parseDouble(next());
    }

    public String[] nextArray(int n) {
        String[] a = new String[n];
        for (int i = 0; i < n; i++)
            a[i] = next();
        return a;
    }

    public int[] nextIntArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = nextInt();
        return a;
    }

    public long[] nextLongArray(int n) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++)
            a[i] = nextLong();
        return a;
    } 
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.HashSet;

public class Main {
    //    private static final int MOD = 1_000_000_007;
    private static final char BLACK = '#';
    private static final char WHITE = '.';

    private int H;
    private int W;

    public static void main(String[] args) {
        try (CustomReader in = new CustomReader()) {
            new Main().execute(in);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void execute(CustomReader in) throws IOException {
        int[] hw = in.readLineAsIntArray();
        H = hw[0];
        W = hw[1];
        final int SZ = H * W;

        char[][] field = new char[H][];
        int[] parent = new int[H * W];

        for (int i = 0; i < H; i++) {
            field[i] = in.readLine().toCharArray();
        }

        for (int i = 0; i < SZ; i++) {
            parent[i] = i;
        }

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                int cellId = id(i, j);
                if (parent[cellId] == cellId) {
                    dfs(i, j, field, cellId, parent);
                }
            }
        }

        HashMap<Integer, Integer> countBlack = new HashMap<>();
        HashMap<Integer, Integer> countWhite = new HashMap<>();
        HashSet<Integer> keys = new HashSet<>();
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                int cellId = id(i, j);
                if (field[i][j] == BLACK) {
                    int cnt = countBlack.getOrDefault(parent[cellId], 0) + 1;
                    countBlack.put(parent[cellId], cnt);
                }else{
                    int cnt = countWhite.getOrDefault(parent[cellId], 0) + 1;
                    countWhite.put(parent[cellId], cnt);
                }
                keys.add(cellId);
            }
        }



        long totalCount = 0L;
        for(Integer key: keys){
            totalCount += countBlack.getOrDefault(key, 0) * countWhite.getOrDefault(key, 0);
        }
        System.out.println(totalCount);

    }

    private void dfs(int h, int w, char[][] field, int root, int[] parents) {

        if (h - 1 > 0 && field[h][w] != field[h - 1][w]) {
            int adjId = id(h - 1, w);
            if (parents[adjId] == adjId) {
                parents[adjId] = root;
                dfs(h - 1, w, field, root, parents);
            }
        }

        if (w - 1 > 0 && field[h][w] != field[h][w - 1]) {
            int adjId = id(h, w - 1);
            if (parents[adjId] == adjId) {
                parents[adjId] = root;
                dfs(h, w - 1, field, root, parents);
            }
        }

        if (h + 1 < H && field[h][w] != field[h + 1][w]) {
            int adjId = id(h + 1, w);
            if (parents[adjId] == adjId) {
                parents[adjId] = root;
                dfs(h + 1, w, field, root, parents);
            }
        }

        if (w + 1 < W && field[h][w] != field[h][w + 1]) {
            int adjId = id(h, w + 1);
            if (parents[adjId] == adjId) {
                parents[adjId] = root;
                dfs(h, w + 1, field, root, parents);
            }
        }
    }


