import java.util.Set;

public class Main {
	public static void main(String args[]) {
		FastScanner scanner = new FastScanner();
		int h=scanner.nextInt();
		int w=scanner.nextInt();
		board=new String[h][w];
		for(int i=0;i<h;i++) {
			board[i]=scanner.next().split("");
		}
		xq=new ArrayDeque<>();
		yq=new ArrayDeque<>();
		set=new HashSet<>();
		long ans=0;
		for(int i=0;i<h;i++) {
			for(int j=0;j<w;j++) {
				Point p=new Point(j,i);
				if(set.contains(p))continue;
				xq.add(j);
				yq.add(i);
				set.add(p);
				long black=0;
				long white=0;
				while(!xq.isEmpty()) {
					int x=xq.poll();
					int y=yq.poll();
					if(board[y][x].equals("#"))black++;
					else white++;
					check4Neighborhood(board, x, y);
				}
				ans+=black*white;
			}
		}
		System.out.println(ans);
	}

	static String[][] board;
	static Deque<Integer>xq;
	static Deque<Integer>yq;
	static Set<Point>set;
	private static void check4Neighborhood(String[][] s, int x, int y) {
		for (int i = -1; i <= 1; i++) {
			for (int j = -1; j <= 1; j++) {
				if ((i == 0 && j != 0) || (i != 0 && j == 0)) {
					int tarX = j + x;
					int tarY = i + y;
					if (0 <= tarX && tarX <= s[0].length - 1 && 0 <= tarY && tarY <= s.length - 1) {
						if (!s[tarY][tarX].equals(s[y][x])) {
							Point p=new Point(tarX,tarY);
							if(set.contains(p))continue;
							xq.add(tarX);
							yq.add(tarY);
							set.add(p);
						}
					}
				}
			}
		}
	}
}

class Point {
	int x, y;

	Point(int x, int y) {
		this.x = x;
		this.y = y;
	}

	@Override
	public int hashCode() {
		final int prime = 31;
		int result = 1;
		result = prime * result + x;
		result = prime * result + y;
		return result;
	}

	@Override
	public boolean equals(Object obj) {
		if (this == obj)
			return true;
		if (obj == null)
			return false;
		if (getClass() != obj.getClass())
			return false;
		Point other = (Point) obj;
		if (x != other.x)
			return false;
		if (y != other.y)
			return false;
		return true;
	}
}

class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
}

import java.util.*;
import java.lang.*;


public class Main {
	static int h;
	static int w;
	static char[][] masu;
	static long count;
	static boolean[][] used;
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		h = sc.nextInt();
		w = sc.nextInt();
		masu = new char[h + 2][w + 2];
		for (int i = 0; i < w + 2; i++) {
			masu[0][i] = 'n';
			masu[h + 1][i] = 'n';
		}
		for (int i = 0; i < h + 2; i++) {
			masu[i][0] = 'n';
			masu[i][w + 1] = 'n';
		}
		for (int i = 1; i <= h; i++) {
			String tmp = sc.next();
			for (int j = 1; j <= w; j++) {
				masu[i][j] = tmp.charAt(j - 1);
			}
		}
		for (int i = 1; i <= h; i++) {
			for (int j = 1; j <= w; j++) {
				if (masu[i][j] == '#') {
					used = new boolean[h + 2][w + 2];
					dfs(i, j);
				}
			}
		}
		System.out.println(count);
	}
	static void dfs(int i, int j) {
		if (masu[i - 1][j] == '.' && !used[i - 1][j]) {
			count++;
			used[i][j] = true;
			used[i - 1][j] = true;
			if (masu[i - 2][j] == '#' && !used[i - 2][j]) {
				dfs(i - 2, j);
			}
			if (masu[i - 1][j - 1] == '#' && !used[i - 1][j - 1]) {
				dfs(i - 1, j - 1);
			}
			if (masu[i - 1][j + 1] =='#' && !used[i - 1][j + 1]) {
				dfs(i - 1, j + 1);
			}
		}
		if (masu[i + 1][j] == '.' && !used[i + 1][j]) {
			count++;
			used[i][j] = true;
			used[i + 1][j] = true;
			if (masu[i + 2][j] == '#' && !used[i + 2][j]) {
				dfs(i + 2, j);
			}
			if (masu[i + 1][j - 1] == '#' && !used[i + 1][j - 1]) {
				dfs(i + 1, j - 1);
			}
			if (masu[i + 1][j + 1] =='#' && !used[i + 1][j + 1]) {
				dfs(i + 1, j + 1);
			}
		}
		if (masu[i][j + 1] == '.' && !used[i][j + 1]) {
			count++;
			used[i][j] = true;
			used[i][j + 1] = true;
			if (masu[i][j + 2] == '#' && !used[i][j + 2]) {
				dfs(i, j + 2);
			}
			if (masu[i - 1][j + 1] == '#' && !used[i - 1][j + 1]) {
				dfs(i - 1, j + 1);
			}
			if (masu[i + 1][j + 1] =='#' && !used[i + 1][j + 1]) {
				dfs(i + 1, j + 1);
			}
		}
		if (masu[i][j - 1] == '.' && !used[i][j - 1]) {
			count++;
			used[i][j] = true;
			used[i][j - 1] = true;
			if (masu[i][j - 2] == '#' && !used[i][j - 2]) {
				dfs(i, j - 2);
			}
			if (masu[i - 1][j - 1] == '#' && !used[i - 1][j - 1]) {
				dfs(i - 1, j - 1);
			}
			if (masu[i + 1][j - 1] =='#' && !used[i + 1][j - 1]) {
				dfs(i + 1, j - 1);
			}
		}
	}
}

import java.util.Scanner;

public class Main {
	static char[][] field;
	static int h;
	static int w;
	static int B=0;
	static int W=0;
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		h = sc.nextInt();
		w = sc.nextInt();
		long ans=0; 

		field = new char[h][];
		for (int i = 0; i < h; i++) {
			field[i] = sc.next().toCharArray();
		}
		for(int col=0;col<h;col++) {
			for(int row=0;row<w;row++) {
				if(field[col][row]=='.') {
					serchW(col,row);
				}else if(field[col][row]=='#') {
					serchB(col,row);
				}
				ans=ans+B*W;
				B=0;
				W=0;
			}
		}
		System.out.print(ans); 

	}

	public static void serchB(int col, int row) {
		B++;
		field[col][row]='!';
	if(col+1<h)if(field[col+1][row]=='.') {serchW(col+1,row);}
	if(row+1<w)if(field[col][row+1]=='.') {serchW(col,row+1);}
	if(col-1>0)if(field[col-1][row]=='.') {serchW(col-1,row);}
	if(row-1>0)if(field[col][row-1]=='.') {serchW(col,row-1);}	
	}

	public static void serchW(int col, int row) {
		W++;
		field[col][row]='!';
		if(col+1<h)if(field[col+1][row]=='#') {serchB(col+1,row);}
		if(row+1<w)if(field[col][row+1]=='#') {serchB(col,row+1);}
		if(col-1>0)if(field[col-1][row]=='#') {serchB(col-1,row);}
		if(row-1>0)if(field[col][row-1]=='#') {serchB(col,row-1);}	

	}

}

