        for(int i = 0; i < H; i++){
            for(int j = 0; j < W; j++){
                long[] ret = new long[2];
                ret = dfs(i, j);
                ans += ret[0] * ret[1];
            }
        }
        System.out.println(ans);

    }
    private static long[] dfs(int i, int j) {
        long[] ret = new long[2];
        if(visited[i][j] == 1) return ret;
        visited[i][j] = 1;
        if(grid[i][j] == '.') ret[0]++;
        else ret[1]++;
