		{
			String s = sc.next();
			for(int x = 0; x < w; x++)
			{
				grid[x][y] = s.charAt(x)=='#';
			}
		}

		for(int y = 0; y < h; y++)
		{
			for(int x = 0; x < w; x++)
			{
				if(!visited[x][y])
				{
					findIsland(x,y,grid[x][y],curisland);
					curisland++;
				}
			}
		}

		long an = 0;
		for(int i = 0; i < curisland; i++)
		{
			an += (islandbw[i][0] * islandbw[i][1]);
		}

		System.out.println(an);

	}

