    void solve() {
        h = ni();
        w = ni();
        map = new boolean[h][w];
        used = new boolean[h][w];
        for (int i = 0; i < h; ++i) {
            String s = ns();
            for (int j = 0; j < w; ++j) {
                map[i][j] = s.charAt(j) == '#';
            }
        }
        long x = 0;
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                long n = dfs(i, j);
                x += (n & 0xffffffffL) * (n >> 32);
            }
        }
        out.println(x);
    }

    int dx[] = {1, 0, -1, 0};
    int dy[] = {0, 1, 0, -1};

    long dfs(int i, int j) {
        if (used[i][j]) return 0;
        used[i][j] = true;
        long n = 1L << (map[i][j] ? 0 : 32);
        for (int k = 0; k < 4; ++k) {
