	private static boolean check4Neighborhood(String[][] s, int x, int y, UnionFind uf, String tarS) {
		for (int i = -1; i <= 1; i++) {
			for (int j = -1; j <= 1; j++) {
				if ((i == 0 && j != 0) || (i != 0 && j == 0)) {
					int tarX = j + x;
					int tarY = i + y;
					if (0 <= tarX && tarX <= s[0].length - 1 && 0 <= tarY && tarY <= s.length - 1) {
						if (!s[tarY][tarX].equals(tarS)) {
							uf.union(tarY*w+tarX, y*w+x);
							return true;
						}
					}
				}
			}
