		char[][] map = nm(n, m);
		DJSet ds = new DJSet(n*m);
		for(int i = 0;i < n;i++){
			for(int j = 0;j < m;j++){
				if(i+1 < n && map[i][j] != map[i+1][j]){
					ds.union(i*m+j, (i+1)*m+j);
				}
				if(j+1 < m && map[i][j] != map[i][j+1]){
					ds.union(i*m+j, i*m+j+1);
				}
			}
		}
		int[] b = new int[n*m];
		int[] w = new int[n*m];
		for(int i = 0;i < n;i++){
			for(int j = 0;j < m;j++){
				if(map[i][j] == '.'){
					w[ds.root(i*m+j)]++;
				}else{
					b[ds.root(i*m+j)]++;
				}
			}
		}
		long ans = 0;
		for(int i = 0;i < n*m;i++){
			ans += (long)b[i]*w[i];
		}
		out.println(ans);
	}

	public static class DJSet {
		public int[] upper;

		public DJSet(int n) {
			upper = new int[n];
			Arrays.fill(upper, -1);
		}

		public int root(int x) {
			return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
		}

		public boolean equiv(int x, int y) {
			return root(x) == root(y);
		}

		public boolean union(int x, int y) {
			x = root(x);
			y = root(y);
			if (x != y) {
				if (upper[y] < upper[x]) {
					int d = x;
					x = y;
					y = d;
				}
				upper[x] += upper[y];
				upper[y] = x;
			}
			return x == y;
		}

		public int count() {
			int ct = 0;
			for (int u : upper)
				if (u < 0)
					ct++;
			return ct;
		}
	}


