/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        inclass in = new inclass(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CAlternatingPath solver = new CAlternatingPath();
        solver.solve(1, in, out);
        out.close();
    }

    static class CAlternatingPath {
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};
        char[][] mat;
        long[] a;

        public void solve(int testNumber, inclass in, PrintWriter out) {
            int n = in.nextInt(), m = in.nextInt();
            mat = new char[n][m];
            for (int i = 0; i < n; i++) {
                String st = in.readLine();
                for (int j = 0; j < st.length(); j++) {
                    mat[i][j] = st.charAt(j);
                }
            }
            int dp[][] = new int[n][m];
            a = new long[(n * m) + 2];
            int k = 0;
            HashSet<Integer> set = new HashSet<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    char ch = mat[i][j];
                    if (ch == '#') {
                        boolean vis[][] = new boolean[n][m];
                        k++;
                        if (dp[i][j] != 0) {
                            a[k] = dp[i][j];
                        }
                        a[k] = dfs(i, j, dp, vis, k, set, 0);
                    }
                }
            }
            long ans = 0;
            for (int i = 0; i < a.length; i++) {
                ans += (long) a[i];
            }
            out.println(ans);
        }

        private long dfs(int i, int j, int[][] dp, boolean[][] vis, int k, HashSet<Integer> set, int col) {
            dp[i][j] = k;
            vis[i][j] = true;
            long ans = 0;
            boolean flag = false;
            for (int l = 0; l < 4; l++) {
                int pt1 = i + dx[l];
                int pt2 = j + dy[l];
                if (isSafe(pt1, pt2, dp.length, dp[0].length)) {
                    if (!vis[pt1][pt2]) {
                        if (dp[pt1][pt2] == 0) {
                            if (mat[pt1][pt2] == (col == 0 ? '.' : '#')) {
                                if (col == 1) {
                                    ans = ans + (long) dfs(pt1, pt2, dp, vis, k, set, col ^ 1);
                                } else {
                                    flag = true;
                                    ans = ans + 1 + (long) dfs(pt1, pt2, dp, vis, k, set, col ^ 1);
                                }
                            }
                        } else if (col == 0 && mat[pt1][pt2] == '.') {
                            if (!set.contains(dp[pt1][pt2])) {
                                set.add(dp[pt1][pt2]);
                                ans = ans + (long) a[dp[pt1][pt2]];
                            }
                        }
                    }
                }
            }
            return ans;
        }

        private boolean isSafe(int pt1, int pt2, int n, int m) {
            if (pt1 < n && pt2 < m && pt1 >= 0 && pt2 >= 0) {
                return true;
            }
            return false;
        }

    }

    static class inclass {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private inclass.SpaceCharFilter filter;

        public inclass(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private String readLine0() {
            StringBuilder buf = new StringBuilder();
            int c = read();
            while (c != '\n' && c != -1) {
                if (c != '\r') {
                    buf.appendCodePoint(c);
                }
                c = read();
            }
            return buf.toString();
        }

        public String readLine() {
            String s = readLine0();
            while (s.trim().length() == 0) {
                s = readLine0();
            }
            return s;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static InputStream is;
    private static PrintWriter out;
    private static String INPUT = "";

    boolean[][] map, used;
    int h, w;

    void solve() {
        h = ni();
        w = ni();
        map = new boolean[h][w];
        used = new boolean[h][w];
        for (int i = 0; i < h; ++i) {
            String s = ns();
            for (int j = 0; j < w; ++j) {
                map[i][j] = s.charAt(j) == '#';
            }
        }
        int x = 0;
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                int n = dfs(i, j);
                x += (n & 0xffff) * (n >> 16);
            }
        }
        out.println(x);
    }

    int dx[] = {1, 0, -1, 0};
    int dy[] = {0, 1, 0, -1};

    int dfs(int i, int j) {
        if (used[i][j]) return 0;
        used[i][j] = true;
        int n = 1 << (map[i][j] ? 0 : 16);
        for (int k = 0; k < 4; ++k) {
            int a = i + dx[k];
            int b = j + dy[k];
            if (a < 0) continue;
            if (b < 0) continue;
            if (a >= h) continue;
            if (b >= w) continue;
            if (map[i][j] == map[a][b]) continue;
            n += dfs(a, b);
        }
        return n;
    }

    public static void main(String[] args) throws Exception {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        new Main().solve();
        out.flush();
    }

    private static boolean eof() {
        if (lenbuf == -1) return true;
        int lptr = ptrbuf;
        while (lptr < lenbuf)
            if (!isSpaceChar(inbuf[lptr++])) return false;

        try {
            is.mark(1000);
            while (true) {
                int b = is.read();
                if (b == -1) {
                    is.reset();
                    return true;
                } else if (!isSpaceChar(b)) {
                    is.reset();
                    return false;
                }
            }
        } catch (IOException e) {
            return true;
        }
    }

    private static byte[] inbuf = new byte[1024];
    static int lenbuf = 0, ptrbuf = 0;

    private static int readByte() {
        if (lenbuf == -1) throw new InputMismatchException();
        if (ptrbuf >= lenbuf) {
            ptrbuf = 0;
            try {
                lenbuf = is.read(inbuf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (lenbuf <= 0) return -1;
        }
        return inbuf[ptrbuf++];
    }

    private static boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    private static int skip() {
        int b;
        while ((b = readByte()) != -1 && isSpaceChar(b))
            ;
        return b;
    }

    private static double nd() {
        return Double.parseDouble(ns());
    }

    private static char nc() {
        return (char) skip();
    }

    private static String ns() {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while (!(isSpaceChar(b))) { // when nextLine, (isSpaceChar(b) && b != ' ')
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private static char[] ns(int n) {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while (p < n && !(isSpaceChar(b))) {
            buf[p++] = (char) b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private static char[][] nm(int n, int m) {
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++)
            map[i] = ns(m);
        return map;
    }

    private static int[] na(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++)
            a[i] = ni();
        return a;
    }

    private static long[] nal(int n) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++)
            a[i] = ni();
        return a;
    }

    private static int ni() {
        int num = 0, b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
            ;
        if (b == '-') {
            minus = true;
            b = readByte();
        }

        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static long nl() {
        long num = 0;
        int b;
        boolean minus = false;
        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'))
            ;
        if (b == '-') {
            minus = true;
            b = readByte();
        }

        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private class XorShift {
        int x = 123456789;
        int y = 362436069;
        int z = 521288629;
        int w = 88675123;

        int nextInt(int n) {
            final int t = x ^ (x << 11);
            x = y;
            y = z;
            z = w;
            w = (w ^ (w >>> 19)) ^ (t ^ (t >>> 8));
            final int r = w % n;
            return r < 0 ? r + n : r;
        }
    }

