    private final int j;
    Point(int i, int j) {
      this.i = i;
      this.j = j;
    }
  }
}

import java.util.*;

public class Main {
	static class Node {
		int index;
		int color;
		int h, w;

		Node(int index, int color, int h, int w) {
			this.index = index;
			this.color = color;
			this.h = h;
			this.w = w;
		}
	}

	int H, W;
	Node[][] cells;
	boolean[][] flags;
	Set<Map<Integer, Node>> nodeGroups;
	long result = 0;

	Main() {
		Scanner in = new Scanner(System.in);
		String[] tokens = in.nextLine().split(" ");
		H = Integer.parseInt(tokens[0]);
		W = Integer.parseInt(tokens[1]);
		cells = new Node[H][W];
		for (int i = 0; i < H; ++i) {
			String line = in.nextLine();
			for (int j = 0; j < W; ++j) {
				char c = line.charAt(j);
				if (c == '#') {
					cells[i][j] = new Node(i * W + j, 0, i, j);
				} else {
					cells[i][j] = new Node(i * W + j, 1, i, j);
				}
			}
		}
		in.close();
		flags = new boolean[H][W];
		for (int h = 0; h < H; ++h) {
			Arrays.fill(flags[h], false);
		}
		nodeGroups = new HashSet<>();
	}

	Node getInitNode() {
		for (int h = 0; h < H; ++h) {
			for (int w = 0; w < W; ++w) {
				if (!flags[h][w]) {
					return cells[h][w];
				}
			}
		}
		return null;
	}

	void calc() {
		while (true) {
			Node node = getInitNode();
			if (node == null) {
				break;
			}
			Map<Integer, Node> groups = new HashMap<>();
			nodeGroups.add(getGroups(node, groups));
		}
		result = count();
	}

	long count() {
		long result = 0L;
		for (Map<Integer, Node> group : nodeGroups) {
			List<Integer> indexes = new ArrayList<>();
			indexes.addAll(group.keySet());
			Collections.sort(indexes);
			for (int i = 0; i + 1 < indexes.size(); ++i) {
				Node srcNode = group.get(indexes.get(i));
				for (int j = i + 1; j < indexes.size(); ++j) {
					Node dstNode = group.get(indexes.get(j));
					if (srcNode.color != dstNode.color) {
						++result;
					}
				}
			}
		}
		return result;
	}

	boolean canMove(Node a, Node b) {
		if (a.color != b.color) {
			return true;
		} else {
			return false;
		}
	}

	Map<Integer, Node> getGroups(Node node, Map<Integer, Node> group) {
		group.put(node.index, node);
		Map<Integer, Node> result = group;
		int h = node.h;
		int w = node.w;
		flags[h][w] = true;

		if (1 <= node.w) {
			if (canMove(cells[h][w], cells[h][w - 1]) && !flags[h][w - 1]) {
				result = getGroups(cells[h][w - 1], result);
			}
		}
		if (node.w + 1 < W) {
			if (canMove(cells[h][w], cells[h][w + 1]) && !flags[h][w + 1]) {
				result = getGroups(cells[h][w + 1], result);
			}
		}
		if (1 <= node.h) {
			if (canMove(cells[h][w], cells[h - 1][w]) && !flags[h - 1][w]) {
				result = getGroups(cells[h - 1][w], result);
			}
		}
		if (node.h + 1 < H) {
			if (canMove(cells[h][w], cells[h + 1][w]) && !flags[h + 1][w]) {
				result = getGroups(cells[h + 1][w], result);
			}
		}
		return result;
	}

	public static void main(String[] args) {
		Main ins = new Main();
		ins.calc();
		System.out.println(ins.result);

	}

}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int H = sc.nextInt();
		int W = sc.nextInt();
		char[][] c = new char[H][W];
		int n = H * W;
		int[] d  = new int[n];
		for(int i = 0; i < H; i++) {
			String s = sc.next();
			for(int j = 0; j < W; j++) {
				c[i][j] = s.charAt(j);
				int idx = i * W + j;
				if(c[i][j] == '#') {
					d[idx] = 0;
				}else {
					d[idx] = 1;
				}
			}
		}
		sc.close();
		DisjointSet ds = new DisjointSet(n);

		for(int i = 0; i < H; i++) {
			for(int j = 0; j < W; j++) {
				if(i + 1 < H && c[i][j] != c[i + 1][j]) {
					ds.unite(W * i + j, W * (i + 1) + j);
				}
				if(j + 1 < W && c[i][j] != c[i][j + 1]) {
					ds.unite(W * i + j, W * i + j + 1);
				}
			}
		}

		long ans = 0;
		long[] b = new long[n];
		long[] w = new long[n];
		for(int i = 0; i < n; i++) {
			if(d[i] == 0) {
				b[ds.findSet(i)]++;
			}else {
				w[ds.findSet(i)]++;
			}
		}
		for(int i = 0; i < n; i++) {
			ans += b[i] * w[i];
		}
		System.out.println(ans);
	}
	static class DisjointSet {
        int[] p;
        int[] rank;
        int[] size;
        DisjointSet(){}
        DisjointSet(int size){
            this.rank = new int[size];
            this.p = new int[size];
            this.size = new int[size];
            for(int i = 0; i < size; i++) {
                makeSet(i);
            }
        }
        void makeSet(int x) {
            p[x] = x;
            rank[x] = 0;
            size[x] = 1;
        }
        boolean same(int x, int y) {
            return findSet(x) == findSet(y);
        }
        void unite(int x, int y) {
            link(findSet(x), findSet(y));
        }
        void link(int x, int y) {
            if(rank[x]  > rank[y]) {
                p[y] = x;
                size[x] = size[x] + size[y];
            }else if(rank[x] < rank[y]){
                p[x] = y;
                size[y] = size[x] + size[y];
            }else if(x != y) {
            	p[y] = x;
            	rank[x]++;
            	size[x] = size[x] + size[y];
            }
        }
        int findSet(int x) {
            if(x != p[x]) {
                p[x] = findSet(p[x]);
            }
            return p[x];
        }
        int size(int x) {
        	if(x != p[x]) {
        		size[x] = size(findSet(x));
        	}
        	return size[x];
        }
    }
}

