public class Main {

	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		MyInput in = new MyInput(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskX solver = new TaskX();
		solver.solve(1, in, out);
		out.close();
	}

	static int INF = 1 << 30;
	static long LINF = 1L << 55;
	static int MOD = 1000000007;
	static int[] mh4 = { 0, -1, 1, 0 };
	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {

		int h, w;
		char[][] s;
		final int B = 0, W = 1;
		public void solve(int testNumber, MyInput in, PrintWriter out) {

			h = in.nextInt(); w = in.nextInt();
			List<P> list = new ArrayList<>();
			s = new char[h][w];
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					s[i][j] = in.nextChar();
					if (s[i][j] == '#') list.add(new P(i, j));
				}
			}

			DisjointSet disjointset = new DisjointSet(h*w+10);
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					for (int k = 0; k < 4; k++) {
						int mh = i + mh4[k];
						int mw = j + mw4[k];
						if (0 <= mh && mh < h && 0 <= mw && mw < w) {
							if ((s[i][j] == '#' && s[mh][mw] == '.') || (s[i][j] == '.' && s[mh][mw] == '#')) {
								disjointset.unite(f(i, j), f(mh, mw));
							}
						}
					}
				}
			}

			long ans = 0;
			int[] memo = new int[h*w+10];
			Set<Integer> didset = new HashSet<>();
			for (int i = 0; i < list.size(); i++) {
				boolean done = false;

				int tmp = disjointset.root(f(list.get(i).h, list.get(i).w));
				if (didset.contains(tmp)) done = true;
				if (!done) {
					int ret = dfs(list.get(i).h, list.get(i).w, new boolean[h][w], B);
					memo[tmp] = ret;
					ans += memo[tmp];
				} else {
					ans += memo[tmp];
				}

				didset.add(tmp);
			}

			out.println(ans);

		}

		int f(int i, int j) {
			return i * w + j;
		}

		int dfs(int nh, int nw, boolean[][] used, int stat) {

			used[nh][nw] = true;

			int ret = 0;
			for (int i = 0; i < 4; i++) {
				int mh = nh + mh4[i];
				int mw = nw + mw4[i];
				if (0 <= mh && mh < h && 0 <= mw && mw < w && !used[mh][mw]) {
					if (stat == B && s[mh][mw] == '.') {
						ret += dfs(mh, mw, used, W) + 1;
					}
					if (stat == W && s[mh][mw] == '#') {
						ret += dfs(mh, mw, used, B);
