public class Main {
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		int h = sc.nextInt();
		int w = sc.nextInt();
		char[][] field = new char[h][];
		for (int i = 0; i < h; i++) {
			field[i] = sc.next().toCharArray();
		}
		UnionFindTree uft = new UnionFindTree(h, w);
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (j != w - 1 && field[i][j] != field[i][j + 1]) {
					uft.union(j + i * w, j + 1 + i * w, field[i][j], field[i][j + 1]);
				}
				if (i != h - 1 && field[i][j] != field[i + 1][j]) {
					uft.union(j + i * w, j + (i + 1) * w, field[i][j], field[i + 1][j]);
				}
			}
		}
		System.out.println(uft.count());
	}

	static class UnionFindTree {

		int[] parent;
		int[] bCount;
		int[] wCount;
		int w;

		public UnionFindTree(int h, int w) {
			this.w = w;
			parent = new int[h * w];
			bCount = new int[h * w];
			wCount = new int[h * w];
			for (int i = 0; i < h * w; i++) {
				parent[i] = i;
			}
		}

		public int find(int i) {
			if (parent[i] == i) {
				return i;
			}
			int p = find(parent[i]);
			parent[i] = p;
			return p;
		}

		public int find(int x, int y){
			return find(x + y * w);
		}

		public boolean same(int a, int b) {
			return (find(a) == find(b));
		}

		public boolean same(int ax, int ay, int bx, int by) {
			return same(ax + ay * w, bx + by * w);
		}

		public void union(int a, int b, char aa, char bb) {
			int aaa = find(a);
			int bbb = find(b);
			if (aaa == bbb) {
				return;
			}
			if (bCount[aaa] + wCount[aaa] == 0) {
				if (aa == '#') {
					bCount[aaa] = 1;
				} else {
					wCount[aaa] = 1;
				}
			}
			if (bCount[bbb] + wCount[bbb] == 0) {
				if (bb == '#') {
					bCount[bbb] = 1;
				} else {
					wCount[bbb] = 1;
				}
			}
			parent[aaa] = bbb;
			bCount[bbb] += bCount[aaa];
			wCount[bbb] += wCount[aaa];
		}

		public long count() {
			long ans = 0;
			for (int i = 0; i < parent.length; i++) {
				if (parent[i] == i) {
					ans += bCount[i] * wCount[i];
				}
			}
			return ans;
		}
	}
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

    int H, W;
    int[][] B;
    int[] dx = {-1, 0, 1, 0};
    int[] dy = {0, -1, 0, 1};
    int BLACK = 0, WHITE = 1, VISITED = 2;

    void run() {
        Scanner sc = new Scanner(System.in);

        H = sc.nextInt();
        W = sc.nextInt();
        B = new int[H + 2][W + 2];

        Arrays.fill(B[0], VISITED);
        Arrays.fill(B[H + 1], VISITED);

        for (int i = 1; i <=H; i++) {
            Arrays.fill(B[i], VISITED);
            String l = sc.next();
            for (int j = 0; j < W; j++) {
                B[i][j + 1] = l.charAt(j) == '#' ? BLACK : WHITE;
            }
        }

        long ans = 0;
        for (int y = 1; y <= H; y++) for (int x = 1; x <= W; x++) {
            P c = solve(x, y);
            ans += 1L * c.bl * c.wh;
        }

        System.out.println(ans);
    }

    P solve(int x, int y) {
        int cell = B[y][x];
        B[y][x] = VISITED;

        P p = new P(0, 0);
        if (cell == BLACK) {
            p.bl += 1;
        } else if (cell == WHITE) {
            p.wh += 1;
        }

        for (int i = 0; i < 4; i++) if (B[y + dy[i]][x + dx[i]] == 1 - cell) {
            P next = solve(x + dx[i], y + dy[i]);
            p.bl += next.bl;
            p.wh += next.wh;
        }

        return p;
    }

    class P {
        int bl, wh;
        P(int bl, int wh) {
            this.bl = bl;
            this.wh = wh;
        }
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

