public class Main {
    static final int MOD = 1000000007;
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		int h = sc.nextInt();
		int w = sc.nextInt();
		UnionFindTree uft = new UnionFindTree(h, w);
		char[][] field = new char[h][];
		for (int i = 0; i < h; i++) {
		    field[i] = sc.next().toCharArray();
		    for (int j = 0; j < w; j++) {
		        if (field[i][j] == '#') {
		            uft.setBlack(i, j);
		        } else {
		            uft.setWhite(i, j);
		        }
		    }
		}

		for (int i = 0; i < h; i++) {
		    for (int j = 0; j < w; j++) {
		        if (field[i][j] == '.') {
		            continue;
		        }
		        if (i != 0 && field[i - 1][j] == '.') {
		            uft.unite(i, j, i - 1, j);
		        }
		        if (i != h - 1 && field[i + 1][j] == '.') {
		            uft.unite(i, j, i + 1, j);
		        }
		        if (j != 0 && field[i][j - 1] == '.') {
		            uft.unite(i, j, i, j - 1);
		        }
		        if (j != w - 1 && field[i][j + 1] == '.') {
		            uft.unite(i, j, i, j + 1);
		        }

		    }
		}
	    System.out.println(uft.getCount());
	}

	static class UnionFindTree {
	    int h;
	    int w;
	    int[] parents;
	    int[] blacks;
	    int[] whites;

	    public UnionFindTree(int h, int w) {
	        this.h = h;
	        this.w = w;
	        int size = h * w;
	        parents = new int[size];
	        blacks = new int[size];
	        whites = new int[size];
	        for (int i = 0; i < size; i++) {
	            parents[i] = i;
	        }
	    }

	    public int find (int x) {
	        if (parents[x] == x) {
	            return x;
	        } else {
	            return parents[x] = find(parents[x]);
	        }
	    }

	    public void unite(int h1, int w1, int h2, int w2) {
	        unite(h1 * w + w1, h2 * w + w2);
	    }

	    public void unite(int x, int y) {
	        int xx = find(x);
	        int yy = find(y);
	        if (xx == yy) {
	            return;
	        }
	        parents[xx] = yy;
	        blacks[yy] += blacks[xx];
	        whites[yy] += whites[xx];
	    }

	    public void setBlack(int h1, int w1) {
	        blacks[h1 * w + w1]++;
	    }

	    public void setWhite(int h1, int w1) {
	        whites[h1 * w + w1]++;
	    }

	    public long getCount() {
	        long total = 0;
	        for (int i = 0; i < parents.length; i++) {
	            if (parents[i] == i) {
	                total += (long)blacks[i] * whites[i];
	            }
	        }
	        return total;
	    }
	}
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;

public class Main {
    public static class UnionFindTree {
        // nodeNum 个数，下标 [1, nodeNum]
        int nodeNum;
        int [] parent;
        int [] height;

        public UnionFindTree(int nodeNum) {
            this.nodeNum = nodeNum;
            parent = new int[nodeNum + 1];
            height = new int[nodeNum + 1];
            for (int i = 1; i <= nodeNum; ++i) {
                parent[i] = i;
                height[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] == x) {
                return x;
            } else {
                return parent[x] = find(parent[x]);
            }
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) {
                return;
            }
            if (height[rootX] < height[rootY]) {
                parent[rootX] = rootY;
            } else {
                if (height[rootX] == height[rootY]) {
                    height[rootX]++;
                }
                parent[rootY] = rootX;
            }
        }

    }
    public static void main(String [] args) {
        Scanner scanner = new Scanner(System.in);
        int h = scanner.nextInt();
        int w = scanner.nextInt();
        char[][] graph = new char[h][w];
        for (int i = 0; i < h; ++i) {
            String s = scanner.next();
            for (int j = 0; j < w; ++j) {
                graph[i][j] = s.charAt(j);
            }
        }
        UnionFindTree unionFindTree = new UnionFindTree(h * w);
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                if (i + 1 < h) {
                    if (graph[i][j] != graph[i + 1][j]) {
                        unionFindTree.union(
                                i * w + j,
                                (i + 1) * w + j
                        );
                    }
                }
                if (i - 1 >= 0) {
                    if (graph[i][j] != graph[i - 1][j]) {
                        unionFindTree.union(
                                i * w + j,
                                (i - 1) * w + j
                        );
                    }
                }
                if (j + 1 < w) {
                    if (graph[i][j] != graph[i][j + 1]) {
                        unionFindTree.union(
                                i * w + j,
                                i * w + j + 1
                        );
                    }
                }

                if (j - 1 >= 0) {
                    if (graph[i][j] != graph[i][j - 1]) {
                        unionFindTree.union(
                                i * w + j,
                                i * w + j - 1
                        );
                    }
                }

            }
        }
        Map<Integer, Set<Integer>> blacks = new HashMap<>();
        Map<Integer, Integer> sizes = new HashMap<>();
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                int root = unionFindTree.find(i * w + j);
                int number = sizes.getOrDefault(root, 0);
                sizes.put(root, number + 1);
                if (graph[i][j] == '#') {
                    Set<Integer> node = blacks.getOrDefault(root, new HashSet<>());
                    node.add(i * w + j);
                    blacks.put(root, node);
                }
            }
        }
        long result = 0;
        for (Map.Entry<Integer, Integer> rootAndSize : sizes.entrySet()) {
            int blackNum = blacks.getOrDefault(rootAndSize.getKey(), new HashSet<>()).size();
            int whiteNum = rootAndSize.getValue() - blackNum;
            result += blackNum * whiteNum;
        }
        System.out.println(result);


    }
}

