import java.util.*;

class UnionFind {
	int[] roots;
	int[] sameSetCnt;

	public UnionFind(int N) {
		roots = new int[N];
		sameSetCnt = new int[N];
		for(int i = 0; i < N; ++i) {
			roots[i] = i;
			sameSetCnt[i] = 1;
		}
	}

	int getRoot(int x) {
		if(roots[x] == x) return x;
		else return roots[x] = getRoot(roots[x]);
	}

	boolean isSameSet(int x, int y) {
		return getRoot(x) == getRoot(y);
	}

	void unite(int x, int y) {
		int rx = getRoot(x);
		int ry = getRoot(y);
		if(rx == ry) return;

		if(sameSetCnt[rx] < sameSetCnt[ry]) {
			int tmp = rx;
			rx = ry;
			ry = tmp;
		}
		sameSetCnt[rx] += sameSetCnt[ry];
		roots[ry] = rx;
	}

	int getSameSetNum(int i) {
		return sameSetCnt[getRoot(i)];
	}
}

public class Main {
	static Scanner sc = new Scanner(System.in);
	static int h = 0;
	static int w = 0;
	static char[][] grids = null;
	static boolean[][] hasVisited = null;
	static int[][] bnum = null;
	static UnionFind uf = null;
	static int[] dy = {-1, 1, 0, 0};
	static int[] dx = {0, 0, -1, 1};

	public static void main(String[] args) {
		h = sc.nextInt();
		w = sc.nextInt();
		grids = new char[h][w];
		hasVisited = new boolean[h][w];
		for(int i = 0; i < h; ++i) grids[i] = sc.next().toCharArray();

		uf = new UnionFind(h * w);
		bnum = new int[h][w];
		// 黒と白が隣接する各箇所に辺を張る
		for(int y = 0; y < h; ++y) {
			for(int x = 0; x < w; ++x) {
				dfs(y, x);
			}
		}

		// 各連結成分について選ぶ組み合わせの数を足していく
		long ans = 0;
		for(int i = 0; i < h * w; ++i) {
			if(uf.getRoot(i) == i) {
				int bn = bnum[i / w][i - i / w * w];
				int wn = uf.getSameSetNum(i) - bn;
				ans += 1L * bn * wn;
			}
		}
		System.out.println(ans);
	}

	static boolean isOutside(int y, int x) {
		return y < 0 || h <= y || x < 0 || w <= x;
	}

	static void dfs(int sy, int sx) {
		// 訪問済みなら何もせず終了
		if(hasVisited[sy][sx]) return;

		// 自身のマスに訪問済みの印をつける
		hasVisited[sy][sx] = true;

		// 自身のマスの色
		char self = grids[sy][sx];

		// 黒マスならば連結成分の根のカウントを1増やす
		if(self == '#') {
			int ufRootIndex = uf.getRoot(w * sy + sx);
			++bnum[ufRootIndex / w][ufRootIndex - ufRootIndex / w * w];
		}

		// 上下左右のマスを見る
		for(int i = 0; i < 4; ++i) {
			int oy = sy + dy[i];
			int ox = sx + dx[i];

			// 範囲外ならばスキップ
			if(isOutside(oy, ox)) continue;

			// 相手のマスの色
			char other = grids[oy][ox];
			if(self != other) {
				// 自身と相手の色が異なれば辺を張る
				int selfIndex = w * sy + sx;
				int otherIndex = w * oy + ox;
				uf.unite(selfIndex, otherIndex);

				// 相手のマスに関してDFS
				dfs(oy, ox);
			}
		}
	}
}

import java.util.AbstractMap;
import java.util.Queue;
import java.util.Scanner;
import java.util.concurrent.ArrayBlockingQueue;

public class Main {

    static Scanner scanner;

    public static void main(String[] args) {
        scanner = new Scanner(System.in);

        int H=gi();
        int W=gi();
        char[][] g=new char[H][W];
        boolean[][] f=new boolean[H][W];

        for (int i=0; i<H;i++) {
            String s=gs();
        	for (int j=0; j<W;j++) {
                char c=s.charAt(j);
                g[i][j]=c;
            }
        }
        long ans=0;
        for (int i=0; i<H;i++) {
        	for (int j=0; j<W;j++) {
        		if(f[i][j]) continue;
                Queue<Pair<Integer,Integer>> q=new ArrayBlockingQueue<Pair<Integer,Integer>>(H*W);
                q.add(new Pair<Integer,Integer>(i,j));
                f[i][j]=true;
                long sharp =0;
                long dot=0;
                while(!q.isEmpty()) {
                	Pair<Integer,Integer> p=q.poll();
                	int h=p.getKey();
                	int w=p.getValue();
                	char c=g[h][w];
                	if(c=='#') {
                		sharp++;
                	} else {
                		dot++;
                	}
                	if (h-1>=0 && f[h-1][w]==false && c!=g[h-1][w]) {
                		f[h-1][w]=true;
                		q.add(new Pair<Integer,Integer>(h-1,w));
                	}
                	if (w+1<W && f[h][w+1]==false && c!=g[h][w+1]) {
                		f[h][w+1]=true;
                		q.add(new Pair<Integer,Integer>(h,w+1));
                	}
                	if (h+1<H && f[h+1][w]==false && c!=g[h+1][w]) {
                		f[h+1][w]=true;
                		q.add(new Pair<Integer,Integer>(h+1,w));
                	}
                	if (w-1>=0 && f[h][w-1]==false && c!=g[h][w-1]) {
                		f[h][w-1]=true;
                		q.add(new Pair<Integer,Integer>(h,w-1));
                	}
                }
                ans+=sharp*dot;
            }
        }

        System.out.println(ans);
    }

    public static class Pair<K, V> extends AbstractMap.SimpleEntry<K, V> implements Comparable<Pair<K, V>> {
        /** serialVersionUID. */
        private static final long serialVersionUID = 6411527075103472113L;

        public Pair(final K key, final V value) {
            super(key, value);
        }

        @Override
        public int compareTo(Pair<K, V> o) {

            Comparable key = (Comparable)this.getKey();
            Comparable key2 = (Comparable)o.getKey();

            return key.compareTo(key2);
        }

    }

    // 文字列として入力を取得
    public static String gs() {
         return scanner.next();
    }

    // intとして入力を取得
    public static int gi() {
         return Integer.parseInt(scanner.next());
    }

    // longとして入力を取得
    public static long gl() {
         return Long.parseLong(scanner.next());
    }

    // doubleとして入力を取得
    public static double gd() {
         return Double.parseDouble(scanner.next());
    }
}

import java.util.ArrayDeque;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		StringBuilder sb = new StringBuilder();
		int h = sc.nextInt();
		int w = sc.nextInt();
		char[][] map = new char[h][w];
		for (int i = 0; i < h; i++) {
			map[i] = sc.next().toCharArray();
		}
		boolean[][] memo = new boolean[h][w];
		ArrayDeque<Pos> deque = new ArrayDeque<>();
		int ans = 0;
		int bcnt, wcnt;
		int[] dh = { 1, -1, 0, 0 };
		int[] dw = { 0, 0, 1, -1 };
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (!memo[i][j]) {
					memo[i][j] = true;
					deque.add(new Pos(i, j));
					bcnt = 0;
					wcnt = 0;
					if (map[i][j] == '.') {
						wcnt++;
					} else {
						bcnt++;
					}
					while (!deque.isEmpty()) {
						Pos pos = deque.poll();
						for (int k = 0; k < 4; k++) {
							int hh = dh[k] + pos.h;
							int ww = dw[k] + pos.w;
							if (hh >= 0 && hh < h && ww >= 0 && ww < w
									&& map[pos.h][pos.w] != map[hh][ww] && !memo[hh][ww]) {
								memo[hh][ww] = true;
								if (map[hh][ww] == '.') {
									wcnt++;
								} else {
									bcnt++;
								}
								deque.add(new Pos(hh, ww));
							}
						}
					}
					ans += wcnt * bcnt;
				}
			}
		}
		System.out.println(ans);
	}
}

