class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] hw = scanner.nextLine().split(" ", 2);
        int h = Integer.parseInt(hw[0]);
        int w = Integer.parseInt(hw[1]);

        boolean[][] black = new boolean[h][w];
        for (int i = 0; i < h; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < w; j++) {
                black[i][j] = (line.charAt(j) == '#');
            }
        }

        int[][] ids = new int[h][w];
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                ids[i][j] = i + h * (j + 1);
            }
        }

        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                // right
                if (j < w - 1) {
                    if (black[i][j] != black[i][j+1]) {
                        ids[i][j+1] = ids[i][j];
                    }
                }

                // down
                if (i < h - 1) {
                    if (black[i][j] != black[i+1][j]) {
                        ids[i+1][j] = ids[i][j];
                    }
                }
            }
        }

        int[] blackCount = new int[(h + 1) * (w + 2) + 1];
        int[] whiteCount = new int[(h + 1) * (w + 2) + 1];
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                int root = ids[i][j];
                int I = i;
                int J = j;
                while (true) {
                    int nextI = root % h;
                    int nextJ = root / h - 1;
                    if (I != nextI || J != nextJ) {
                        root = ids[nextI][nextJ];
                        I = nextI;
                        J = nextJ;
                    } else {
                        break;
                    }
                }

                if (black[i][j]) {
                    blackCount[root]++;
                } else {
                    whiteCount[root]++;
                }
            }
        }

        int result = 0;
        int last = (h + 1) * (w + 2) + 1;
        for (int i = 0; i < last; i++) {
            result += (blackCount[i] * whiteCount[i]);
        }
        System.out.println(result);
    }
}

