import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int H = sc.nextInt();
    int W = sc.nextInt();
    char[][] m = new char[H][W];
    for (int i = 0; i < H; i++) {
      String s = sc.next();
      for (int j = 0; j < W; j++) {
        m[i][j] = s.charAt(j);
      }
    }

    int count = 0;
    for (int s = 0; s < H*W; s++) {
      int si = s/W;
      int sj = s%W;
      boolean[][] visit = new boolean[H][W];
      LinkedList<Point> q = new LinkedList<>();
      q.offer(new Point(si,sj));
      visit[si][sj] = true;
      while (!q.isEmpty()) {
        Point p = q.poll();
        for (int d = 0; d < 4; d++) {
          int i = p.i+di[d];
          int j = p.j+dj[d];
          if (0 <= i && i < H
             && 0 <= j && j < W
             && !visit[i][j]) {
            visit[i][j] = true;
            if (m[p.i][p.j] != m[i][j]) {
              if (m[si][sj] != m[i][j]) {
                count++;
              }
              //System.out.println(si+","+sj+" "+i+","+j);
              q.add(new Point(i,j));
            }
          }
        }
      }
    }
    System.out.println(count/2);
  }
  private static int[] di = {0,0,1,-1};
  private static int[] dj = {1,-1,0,0};
  private static class Point {
    private final int i;
    private final int j;
    Point(int i, int j) {
      this.i = i;
      this.j = j;
    }
  }
}

import java.util.ArrayList;
import java.util.Objects;
import java.util.Scanner;

public class Main {

	private static final char BLACK = '#';
	private static final char WHITE = '.';

	private int H;
	private int W;

	public static void main(String[] args) {
		new Main().execute();
	}

	public void execute() {
		Scanner sc = new Scanner(System.in);
		H = sc.nextInt();
		W = sc.nextInt();
		sc.nextLine();
		Cell[][] board = new Cell[H][W];
		ArrayList<Cell> blacks = new ArrayList<>();
		ArrayList<Cell> whites = new ArrayList<>();
		UFCell uf = new UFCell();

		for (int i = 0; i < H; i++) {
			String line = sc.nextLine();
			for (int j = 0; j < W; j++) {
				char c = line.charAt(j);
				Cell cell = new Cell(i, j, c);
				board[i][j] = cell;
				uf.add(cell);
				if (i > 0 && cell.Color != board[i - 1][j].Color) {
					uf.union(cell, board[i - 1][j]);
				}
				if (j > 0 && cell.Color != board[i][j - 1].Color) {
					uf.union(cell, board[i][j - 1]);
				}				
				if (c == BLACK) {
					blacks.add(cell);
				} else if (c == WHITE) {
					whites.add(cell);
				} else {
					throw new IllegalArgumentException();
				}
			}
		}

		int cnt = 0;
		for (Cell b : blacks) {
			for (Cell w : whites) {
				if (uf.find(b, w)) {
					cnt++;
				}
			}
		}
		System.out.println(cnt);
		sc.close();
	}

	class Cell {
		public final int id;
		public final char Color;
		public final int x;
		public final int y;

		public Cell(int x, int y, char color) {
			this.x = x;
			this.y = y;
			this.Color = color;
			this.id = H * y + x;
		}

		@Override
		public boolean equals(Object obj) {
			// TODO Auto-generated method stub
			if (obj instanceof Cell) {
				Cell that = (Cell) obj;
				return (this.x == that.x) && (this.y == that.y);
			} else {
				return false;
			}
		}

		@Override
		public int hashCode() {
			return Objects.hash(this.x, this.y);
		}

	}

	class UFCell {
		private int parents[] = new int[H * W];

		public void add(Cell c) {
			parents[c.id] = c.id;
		}

		private int rootID(int cid) {
			if (parents[cid] == cid) {
				return cid;
			} else {
				int pid = parents[cid];
				int root = rootID(pid);
				parents[cid] = root;
				return root;
			}
		}

		public void union(Cell c1, Cell c2) {
			int r1 = rootID(c1.id);
			int r2 = rootID(c2.id);
			if (r1 == r2) {
				return;
			} else {
				parents[r1] = r2;
			}
		}

		public boolean find(Cell c1, Cell c2) {
			return rootID(c1.id) == rootID(c2.id);
		}
	}

}

