    long bfs(Node[] nodes, long[] dist, int start){
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(start);

        int black = 0;
        int white = 0;
        long count = 0;

        while(!queue.isEmpty()){
            int now = queue.poll();
            if(nodes[now].past == 1){
                count += white;
                black++;
            } else {
                count += black;
                white++;
            }
            for(Edge edge : nodes[now].edges){
                if(dist[edge.to] != -1) continue;
                dist[edge.to] = dist[now] + 1;
                queue.add(edge.to);
            }
        }

        return count;
    }

