import java.io.*;
import java.util.*;

public class Main {
	static void solve() {
		int h = ni(), w = ni();
		char[][] f = nm(h, w);
		boolean[][] used = new boolean[h][w];
		long ans = 0;
		for(int i=0;i<h;i++) {
			for(int j=0;j<w;j++) {
				if(f[i][j] == '.')continue;
				if(used[i][j])continue;
				var q = new ArrayDeque<int[]>();
				int[] start = {i, j};
				q.add(start);
				used[i][j] = true;
				boolean[][] tUsed = new boolean[h][w];
				tUsed[i][j] = true;
//				fill(used, false);
				while(!q.isEmpty()) {
					int[] now = q.poll();
					for(int k=0;k<4;k++) {
						int nx = now[0] + dx[k];
						int ny = now[1] + dy[k];
						if(nx < 0 || nx >= h)continue;
						if(ny < 0 || ny >= w)continue;
						if(tUsed[nx][ny])continue;
						if(f[now[0]][now[1]] == f[nx][ny])continue;
						used[nx][ny] = true;
						tUsed[nx][ny] = true;
						int[] next = {nx, ny};
						q.add(next);
					}
				}
				ans += calc(f, tUsed);
			}
		}
		out.println(ans);
	}

	static long calc(char[][] f, boolean[][] used) {
		int nb = 0, nw = 0;
		int n = f.length, m = f[0].length;
		for(int i=0;i<n;i++) {
			for(int j=0;j<m;j++) {
				if(used[i][j]) {
					if(f[i][j] == '.') nw ++;
					else nb ++;
				}
			}
		}
		return nw * nb;
