public class Main {
	static int h;
	static int w;
	static char[][] masu;
	static long count;
	static int[][] used;
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		h = sc.nextInt();
		w = sc.nextInt();
		masu = new char[h + 2][w + 2];
		for (int i = 0; i < w + 2; i++) {
			masu[0][i] = 'n';
			masu[h + 1][i] = 'n';
		}
		for (int i = 0; i < h + 2; i++) {
			masu[i][0] = 'n';
			masu[i][w + 1] = 'n';
		}
		for (int i = 1; i <= h; i++) {
			String tmp = sc.next();
			for (int j = 1; j <= w; j++) {
				masu[i][j] = tmp.charAt(j - 1);
			}
		}
		for (int i = 1; i <= h; i++) {
			for (int j = 1; j <= w; j++) {
				if (masu[i][j] == '#') {
					used = new int[h + 2][w + 2];
					dfs(i, j);
				}
			}
		}
		System.out.println(count);
	}
	static void dfs(int i, int j) {
		if (masu[i - 1][j] == '.' && used[i - 1][j] != 1) {
			count++;
			used[i][j] = 1;
			used[i - 1][j] = 1;
			if (masu[i - 2][j] == '#' && used[i - 2][j] != 1) {
				dfs(i - 2, j);
			}
			if (masu[i - 1][j - 1] == '#' && used[i - 1][j - 1] != 1) {
				dfs(i - 1, j - 1);
			}
			if (masu[i - 1][j + 1] =='#' && used[i - 1][j + 1] != 1) {
				dfs(i - 1, j + 1);
			}
		}
		if (masu[i + 1][j] == '.' && used[i + 1][j] != 1) {
			count++;
			used[i][j] = 1;
			used[i + 1][j] = 1;
			if (masu[i + 2][j] == '#' && used[i + 2][j] != 1) {
				dfs(i + 2, j);
			}
			if (masu[i + 1][j - 1] == '#' && used[i + 1][j - 1] != 1) {
				dfs(i + 1, j - 1);
			}
			if (masu[i + 1][j + 1] =='#' && used[i + 1][j + 1] != 1) {
				dfs(i + 1, j + 1);
			}
		}
		if (masu[i][j + 1] == '.' && used[i][j + 1] != 1) {
			count++;
			used[i][j] = 1;
			used[i][j + 1] = 1;
			if (masu[i][j + 2] == '#' && used[i][j + 2] != 1) {
				dfs(i, j + 2);
			}
			if (masu[i - 1][j + 1] == '#' && used[i - 1][j + 1] != 1) {
				dfs(i - 1, j + 1);
			}
			if (masu[i + 1][j + 1] =='#' && used[i + 1][j + 1] != 1) {
				dfs(i + 1, j + 1);
			}
		}
		if (masu[i][j - 1] == '.' && used[i][j - 1] != 1) {
			count++;
			used[i][j] = 1;
			used[i][j - 1] = 1;
			if (masu[i][j - 2] == '#' && used[i][j - 2] != 1) {
				dfs(i, j - 2);
			}
			if (masu[i - 1][j - 1] == '#' && used[i - 1][j - 1] != 1) {
				dfs(i - 1, j - 1);
			}
			if (masu[i + 1][j - 1] =='#' && used[i + 1][j - 1] != 1) {
				dfs(i + 1, j - 1);
			}
		}
	}
}

import java.util.*;

class UnionFind {
	int[] roots;
	int[] sameSetCnt;

	public UnionFind(int N) {
		roots = new int[N];
		sameSetCnt = new int[N];
		for(int i = 0; i < N; ++i) {
			roots[i] = i;
			sameSetCnt[i] = 1;
		}
	}

	int getRoot(int x) {
		if(roots[x] == x) return x;
		else return roots[x] = getRoot(roots[x]);
	}

	boolean isSameSet(int x, int y) {
		return getRoot(x) == getRoot(y);
	}

	void unite(int x, int y) {
		int rx = getRoot(x);
		int ry = getRoot(y);
		if(rx == ry) return;

		if(sameSetCnt[rx] < sameSetCnt[ry]) {
			int tmp = rx;
			rx = ry;
			ry = tmp;
		}
		sameSetCnt[rx] += sameSetCnt[ry];
		roots[ry] = rx;
	}

	int getSameSetNum(int i) {
		return sameSetCnt[getRoot(i)];
	}
}

public class C {
	static Scanner sc = new Scanner(System.in);
	static int h = 0;
	static int w = 0;
	static char[][] grids = null;
	static boolean[][] hasVisited = null;
	static UnionFind uf = null;
	static int[] dy = {-1, 1, 0, 0};
	static int[] dx = {0, 0, -1, 1};

	public static void main(String[] args) {
		h = sc.nextInt();
		w = sc.nextInt();
		grids = new char[h][w];
		hasVisited = new boolean[h][w];
		for(int i = 0; i < h; ++i) grids[i] = sc.next().toCharArray();

		uf = new UnionFind(h * w);
		// 黒と白が隣接する各箇所に辺を張る
		for(int y = 0; y < h; ++y) {
			for(int x = 0; x < w; ++x) {
				dfs(y, x);
			}
		}

		int[][] bnum = new int[h][w];
		// 各連結成分について黒の数を数える
		for(int y = 0; y < h; ++y) {
			for(int x = 0; x < w; ++x) {
				if(grids[y][x] == '#') {
					int ufRootIndex = uf.getRoot(w * y + x);
					++bnum[ufRootIndex / w][ufRootIndex - ufRootIndex / w * w];
				}
			}
		}

		// 各連結成分について選ぶ組み合わせの数を足していく
		long ans = 0;
		for(int i = 0; i < h * w; ++i) {
			if(uf.getRoot(i) == i) {
				int bn = bnum[i / w][i - i / w * w];
				int wn = uf.getSameSetNum(i) - bn;
				ans += 1L * bn * wn;
			}
		}
		System.out.println(ans);
	}

	static boolean isOutside(int y, int x) {
		return y < 0 || h <= y || x < 0 || w <= x;
	}

	static void dfs(int sy, int sx) {
		// 訪問済みなら何もせず終了
		if(hasVisited[sy][sx]) return;

		// 自身のマスに訪問済みの印をつける
		hasVisited[sy][sx] = true;

		// 自身のマスの色
		char self = grids[sy][sx];

		// 上下左右のマスを見る
		for(int i = 0; i < 4; ++i) {
			int oy = sy + dy[i];
			int ox = sx + dx[i];

			// 範囲外ならばスキップ
			if(isOutside(oy, ox)) continue;

			// 相手のマスの色
			char other = grids[oy][ox];
			if(self != other) {
				// 自身と相手の色が異なれば辺を張る
				int selfIndex = w * sy + sx;
				int otherIndex = w * oy + ox;
				uf.unite(selfIndex, otherIndex);

				// 相手のマスに関してDFS
				dfs(oy, ox);
			}
		}
	}
}

