public class Main{
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int H = sc.nextInt();
    int W = sc.nextInt();
    boolean[][] table = new boolean[H][W];
    int[][] table2 = new int[H][W];
    for(int i = 0; i < table.length; i++){
      String str = sc.next();
      Arrays.fill(table2[i], -1);
      for(int j = 0; j < str.length(); j++){
        table[i][j] = (str.charAt(j) == '#') ? true : false;
      }
    }
    System.out.println(solve(table, table2));
  }

  public static long solve(boolean[][] table, int[][] table2){
    int count = 0;
    for(int i = 0; i < table.length; i++){
      for(int j = 0; j < table[i].length; j++){
        if(table2[i][j] == -1){
          saiki(table, table2, i, j, count);
          count++;
        }
      }
    }
    int[][] counts = new int[count+1][2];

    for(int i = 0; i < table.length; i++){
      for(int j = 0; j < table[i].length; j++){
        if(table[i][j] == true){
          counts[table2[i][j]][0]++;
        }else{
          counts[table2[i][j]][1]++;
        }
      }
    }
    long ans = 0;
    for(int i = 0; i < counts.length; i++){
      ans += counts[i][0] * counts[i][1];
    }
    return ans;
  }

  public static void saiki(boolean[][] table, int[][] table2, int x, int y, int n){
    table2[x][y] = n;
    if(x-1 != -1){
      if(table[x][y] != table[x-1][y] && table2[x][y] != table2[x-1][y]){
        saiki(table, table2, x-1, y, n);
      }
    }
    if(y-1 != -1){
      if(table[x][y] != table[x][y-1] && table2[x][y] != table2[x][y-1]){
        saiki(table, table2, x, y-1, n);
      }
    }
    if(x+1 < table.length){
      if(table[x][y] != table[x+1][y] && table2[x][y] != table2[x+1][y]){
        saiki(table, table2, x+1, y, n);
      }
    }
    if(y+1 < table[0].length){
      if(table[x][y] != table[x][y+1] && table2[x][y] != table2[x][y+1]){
        saiki(table, table2, x, y+1, n);
      }
    }
  }
}

import java.util.AbstractMap;
import java.util.Queue;
import java.util.Scanner;
import java.util.concurrent.ArrayBlockingQueue;

public class Main {

     static Scanner scanner;

     public static void main(String[] args) {
         scanner = new Scanner(System.in);

         int H=gi();
         int W=gi();
         char[][] cs=new char[H][W];

         long ans =0;
         for (int i=0; i<H;i++) {
        	 String s=gs();
        	 for (int j=0; j<W;j++) {
        	      cs[i][j]=s.charAt(j);
             }
         }

         Queue<Pair<Integer,Integer>> q=new ArrayBlockingQueue<Pair<Integer,Integer>>(H*W);
         for (int i=0; i<H;i++) {
        	 for (int j=0; j<W;j++) {
            	 if (cs[i][j]=='#') {
            		 boolean[][] f=new boolean[H][W];
            		 q.add(new Pair<Integer,Integer>(i,j));
            		 f[i][j]=true;
            		 while(!q.isEmpty()) {
            			 Pair<Integer,Integer> p=q.poll();
            			 int h=p.getKey();
            			 int w=p.getValue();
            			 if(h>0 && f[h-1][w]==false && cs[h-1][w]!=cs[h][w]) {
            				 q.add(new Pair<Integer,Integer>(h-1,w));
            				 if(cs[h-1][w]=='.') ans++;
            				 f[h-1][w]=true;
            			 }
            			 if(w>0 && f[h][w-1]==false && cs[h][w-1]!=cs[h][w]) {
            				 q.add(new Pair<Integer,Integer>(h,w-1));
            				 if(cs[h][w-1]=='.') ans++;
            				 f[h][w-1]=true;
            			 }
            			 if(h+1<H  && f[h+1][w]==false && cs[h+1][w]!=cs[h][w]) {
            				 q.add(new Pair<Integer,Integer>(h+1,w));
            				 if(cs[h+1][w]=='.') ans++;
            				 f[h+1][w]=true;
            			 }
            			 if(w+1<W && f[h][w+1]==false && cs[h][w+1]!=cs[h][w]) {
            				 q.add(new Pair<Integer,Integer>(h,w+1));
            				 if(cs[h][w+1]=='.') ans++;
            				 f[h][w+1]=true;
            			 }
            		 }
            	 }
             }
         }

         System.out.println(ans);

     }

     public static class Pair<K, V> extends AbstractMap.SimpleEntry<K, V> implements Comparable<Pair<K, V>> {
    		/** serialVersionUID. */
    	    private static final long serialVersionUID = 6411527075103472113L;

    	    public Pair(final K key, final V value) {
    	        super(key, value);
    	    }

    		@Override
    		public int compareTo(Pair<K, V> o) {

    			Comparable key = (Comparable)this.getKey();
    			Comparable key2 = (Comparable)o.getKey();

    			return key.compareTo(key2);
    		}

    	}
     // 文字列として入力を取得
     public static String gs() {
          return scanner.next();
     }

     // intとして入力を取得
     public static int gi() {
          return Integer.parseInt(scanner.next());
     }

     // longとして入力を取得
     public static long gl() {
          return Long.parseLong(scanner.next());
     }

     // doubleとして入力を取得
     public static double gd() {
          return Double.parseDouble(scanner.next());
     }
}

