    void solve(){
        int h = ni();
        int w = ni();
        char[][] map = nm(h,w);
        edge = new ArrayList[h*w];
        for(int i = 0; i < h*w; i++){
            edge[i] = new ArrayList<>();
        }
        int[] dx = {-1,0,1,0};
        int[] dy = {0,-1,0,1};
        for(int i = 0; i < h; i++){
            for(int j = 0; j < w; j++){
                for(int c = 0; c < 4; c++){
                    int cx = i + dx[c];
                    int cy = j + dy[c];
                    if(cx<0||cx>=h||cy<0||cy>=w) continue;
                    if(map[i][j]==map[cx][cy]) continue;
                    edge[i*w+j].add(new int[]{cx*w+cy, map[cx][cy]=='#' ? 0 : 1});
                }
            }
        }
        long ans = 0;
        seen = new boolean[h*w];
        for(int i = 0; i < h; i++){
            for(int j = 0; j < w; j++){
                if(seen[i*w+j]) continue;
                search(map, i*w+j);
                if(map[i][j]=='#') black++;
                else white++;
                ans += black * white;
                black = 0;
                white = 0;
            }
        }
        out.println(ans);
    }

    void search(char[][] map, int s){
        seen[s] = true;
        for(int[] t : edge[s]){
            if(seen[t[0]]) continue;
            if(t[1]==0) black++;
            if(t[1]==1) white++;
            search(map, t[0]);
        }
    }

