        for (int i=0;i<H;i++) {
            for (int j=0;j<W;j++) {
                if (c[i][j]=='.') continue;
                if (flag[i][j]) continue;

                ArrayDeque<int[]> q = new ArrayDeque<int[]>();
                int[] first = {i, j, 0};
                q.add(first);
                int b_cnt = 0;
                int w_cnt = 0;
                while (!q.isEmpty()) {
                    int[] rem = q.poll();
                    if (rem[0]<0 || H<=rem[0] || rem[1]<0 || W<=rem[1]) continue;
                    if (rem[2]%2==0 && c[rem[0]][rem[1]]=='.') continue;
