                    if (flag[rem[0]][rem[1]]) continue;
                    flag[rem[0]][rem[1]] = true;
                    if (rem[2]%2==0) b_cnt++;
                    if (rem[2]%2==1) w_cnt++;
                    for (int[] del : delta) {
                        int[] add = {rem[0]+del[0], rem[1]+del[1], rem[2]+1};
                        q.add(add);
                    }
                }
                // System.out.println("b, w "+b_cnt+" "+w_cnt);

                ans += (long)b_cnt*w_cnt;
            }
        }
        System.out.println(ans);
    }
