	public static class UnionFind {
		int[] par; //

		public UnionFind(int n) {
			par = new int[n];
			for(int i = 0; i < n; i++){
				par[i] = -1;
			}
		}

		public int find(int x) {
			if(par[x] < 0){
				return x;
			}else{
				return par[x] = find(par[x]);
			}
		}

		public boolean union(int x, int y) {
			x = find(x);
			y = find(y);

			if(x != y){
				if(par[y] < par[x]){ // 多い方が根になるようにスワップする.
					int tmp = x;
					x = y;
					y = tmp;
				}
				par[x] += par[y];
				par[y] = x;
				return true;
			}else{
				return false;
			}
		}

		public boolean same(int x, int y) {
			return find(x) == find(y);
		}

		public int size(int x) {
			return -par[find(x)];
		}
	}

	public static int[][] move_dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

	public static void main(String[] args) throws IOException {
		try(final Scanner sc = new Scanner(System.in)){
			final int H = sc.nextInt();
			final int W = sc.nextInt();

			char[][] colors = new char[H][];
			for(int i = 0; i < H; i++){
				colors[i] = sc.next().toCharArray();
			}

			UnionFind uf = new UnionFind(H * W);

			for(int i = 0; i < H; i++){
				for(int j = 0; j < W; j++){
					final int id = i * W + j;

					for(final int[] moves : move_dirs) {
						final int ni = i + moves[0];
						final int nj = j + moves[1];
						final int nid = ni * W + nj;

						if(0 <= ni && ni < H && 0 <= nj && nj < W && colors[i][j] != colors[ni][nj]) {
							//System.out.println(i + " " + j + " " + ni + " " + nj);
							uf.union(id, nid);
						}
					}
				}
			}

			HashSet<Integer> keys = new HashSet<Integer>();
			HashMap<Integer, Long> whites = new HashMap<Integer, Long>();
			HashMap<Integer, Long> blacks = new HashMap<Integer, Long>();
			for(int i = 0; i < H; i++){
				for(int j = 0; j < W; j++){
					final int id = uf.find(i * W + j);

					keys.add(id);
					if(!whites.containsKey(id)) { whites.put(id, 0l); }
					if(!blacks.containsKey(id)) { blacks.put(id, 0l); }
					if(colors[i][j] == '.') {
						whites.put(id, whites.get(id) + 1);
					}else {
						blacks.put(id, blacks.get(id) + 1);
					}
				}
			}
			//System.out.println(blacks);

			long answer = 0;
			for(final int id : keys) {
				answer += blacks.get(id) * whites.get(id);
			}

			System.out.println(answer);
		}
	}

