	public void solve() throws IOException {
		FastScanner fs = new FastScanner();
		int h = fs.nextInt();
		int w = fs.nextInt();
		int[][] board = new int[h][w];

		for(int i = 0; i < h; i++) {
			String[] row = fs.next().split("");
			for(int j = 0; j < w; j++) {
				if(row[j].equals(".")) {
					board[i][j] = 1;
				}else {
					board[i][j] = 0;
				}
			}
		}

		int ans = 0;
		for(int i = 0; i < h; i++) {
			for(int j = 0; j < w;j++) {
				if(board[i][j] != -1) {
					HashSet<Point> pointSet = makeReachableNodeSet(i, j, board, h, w);

					if(pointSet.size() > 1) {
						int black = 0;
						int white = 0;
						for(Point point : pointSet) {
							if(point.color == 1) {
								white++;
							}else {
								black++;
							}
						}
						ans += black*white;
					}
				}
			}
		}
		System.out.println(ans);
	}

	public HashSet<Point> makeReachableNodeSet(int i, int j, int[][] graph, int h, int w) {

		int hereVal = graph[i][j];

		HashSet<Point> reachableNodeSet = new HashSet<>();
		reachableNodeSet.add(new Point(hereVal, j, i));
		graph[i][j] = -1;

		if(i > 0) {
			if(graph[i-1][j] >= 0 && hereVal != graph[i-1][j]) {
				reachableNodeSet.addAll(makeReachableNodeSet(i-1, j, graph, h, w));
			}
		}

		if(i < h - 1) {
			if(graph[i+1][j] >= 0 && hereVal != graph[i+1][j]) {
				reachableNodeSet.addAll(makeReachableNodeSet(i+1, j, graph,h,w));
			}
		}

		if(j > 0) {
			if(graph[i][j-1] >= 0 && hereVal != graph[i][j-1]) {
				reachableNodeSet.addAll(makeReachableNodeSet(i, j -1, graph, h,w));
			}
		}

		if(j < w - 1) {
			if(graph[i][j + 1] >= 0 && hereVal != graph[i][j+1]) {
				reachableNodeSet.addAll(makeReachableNodeSet(i, j+1, graph, h,w));
			}
		}

		return reachableNodeSet;
	}

	class Point{
		int color;
		int x;
		int y;

		Point(int color, int x, int y){
			this.color = color;
			this.x = x;
			this.y = y;
		}
	}

	public class FastScanner {

		BufferedReader reader;
		private StringTokenizer st;

		public FastScanner() {
			st = null;
			reader = new BufferedReader(new InputStreamReader(System.in));
		}

		public String next() throws IOException {
			if (st == null || !st.hasMoreElements()) {
				st = new StringTokenizer(reader.readLine());
			}
			return st.nextToken();
		}

		public String nextLine() throws IOException {
			st = null;
			String readLine = null;
			readLine = reader.readLine();
			return readLine;
		}

		public int nextInt() throws NumberFormatException, IOException {
			return Integer.parseInt(next());
		}

		public long nextLong() throws NumberFormatException, IOException {
			return Long.parseLong(next());
		}

		public int[] nextIntArr(int n) throws NumberFormatException, IOException {
			int[] retArr = new int[n];
			for (int i = 0; i < n; i++) {
				retArr[i] = nextInt();
			}
			return retArr;
		}

		public long[] nextLongArr(int n) throws NumberFormatException, IOException {
			long[] retArr = new long[n];
			for (int i = 0; i < n; i++) {
				retArr[i] = nextLong();
			}
			return retArr;
		}

		public void close() throws IOException {
			reader.close();
		}
	}

}

import java.util.Scanner;
public class Main{
	static char[][] map;
	static int h;
	static int w;
	static int[] dx={0,0,-1,1};
	static int[] dy={1,-1,0,0};
	static boolean[][] ma;
	static int countw;
	static int countb;
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		h=sc.nextInt();
		w=sc.nextInt();
		map=new char[h][w];
		ma=new boolean[h][w];
		for(int i=0; i<h; i++){
			String s=sc.next();
			map[i]=s.toCharArray();
		}
		int ans=0;
		for(int i=0; i<h; i++){
			for(int j=0; j<w; j++){
				if(!ma[i][j]){
					countw=0;
					countb=0;
					dfs(i,j);
					ans+=countw*countb;
				}
			}
		}
		System.out.println(ans);
	}
	static void dfs(int x,int y){
		ma[x][y]=true;
		if(map[x][y]=='.'){
			countw++;
		}else{
			countb++;
		}
		for(int i=0; i<4; i++){
			if(check(x+dx[i],y+dy[i])){
				if((map[x][y]=='.' && map[x+dx[i]][y+dy[i]]=='#') || (map[x][y]=='#' && map[x+dx[i]][y+dy[i]]=='.')){
					dfs(x+dx[i],y+dy[i]);
				}
			}
		}
		return;
	}
	static boolean check(int x,int y){
		return x>=0 && x<h && y>=0 && y<w && !ma[x][y];
	}
}

import java.util.*;
class Main {
    static int H;
    static int W;
    public static void main(String[] args) {
	Scanner sc = new Scanner(System.in);
	H = sc.nextInt();
	W = sc.nextInt();
	char[][] board = new char[H][W];
	for(int i = 0; i<H; i++) {
	    String str = sc.next();
	    for(int j = 0; j<W; j++) {
		board[i][j] = str.charAt(j);
	    }
	}
	long result = 0;;
	for(int i = 0; i<H; i++) {
	    for(int j = 0; j<W; j++) {
		if(board[i][j] == '#') {
		    int[] part = searchWhite(board,i,j);
		    result += part[0]*part[1];
		}
	    }
	}
	System.out.println(result);

    }

    public static int[] searchWhite(char[][] board, int i, int j) {
	char target = (board[i][j]=='#')? '.': '#';
	int[] cnt = {0,0};
	if(board[i][j] == '.') cnt[0]++;
	else if(board[i][j] == '#') cnt[1]++;
	board[i][j] = '*';
	int[] result;
	if(i+1<H) {
	    if(board[i+1][j] == target) {
		result = searchWhite(board,i+1,j);
		cnt[0] += result[0];
		cnt[1] += result[1];
	    }
	}
	if(i-1>=0) {
	    if(board[i-1][j] == target){
		result = searchWhite(board,i-1,j);
		cnt[0] += result[0];
		cnt[1] += result[1];
	    }
	}
	if(j+1<W) {
	    if(board[i][j+1] == target){
		result = searchWhite(board,i,j+1);
		cnt[0] += result[0];
		cnt[1] += result[1];
	    }
	}
	if(j-1>=0) {
            if(board[i][j-1] == target){
		result = searchWhite(board,i,j-1);
		cnt[0] += result[0];
		cnt[1] += result[1];
	    }
	}
	return cnt;
    }


}

