                    matrix[i][j]=(str.charAt(j)=='#');
                }
            }
            for(int i=0;i<n;i++){
                for(int j=0;j<m;j++){
                    if(!vis[i][j]){
                        int[] x = dfs(i,j,matrix[i][j]);
                        sum+=x[0]*x[1];
                    }
                }
            }
            pw.println(sum);
        }
        public int[] dfs (int x, int y, boolean c){
            int[] dx = {-1,1,0,0};
            int[] dy = {0,0,-1,1};
            if(x<0||y<0||x>=matrix.length||y>=matrix[0].length||vis[x][y]||matrix[x][y]!=c){
                return new int[]{0,0};
            }
            int a = 0;
            int b = 0;
            vis[x][y]=true;
            if(c){
                a++;
            }
            else{
                b++;
