	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {

		int h, w;
		public void solve(int testNumber, MyInput in, PrintWriter out) {

			h = in.nextInt(); w = in.nextInt();
			UnionFind uf = new UnionFind(h * w);
			char[][] s = new char[h][w];
			for (int i = 0; i < h; i++) {
				 for (int j = 0; j < w; j++) {
					 s[i][j] = in.nextChar();
					 if (s[i][j] == '.') uf.add(f(i, j));
				}
			}

			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					for (int k = 0; k < 4; k++) {
						int mh = i + mh4[k];
						int mw = j + mw4[k];
						if (isInside(mh, mw) && ((s[i][j] == '#' && s[mh][mw] == '.') || (s[i][j] == '.' && s[mh][mw] == '#'))) {
							uf.union(f(i, j), f(mh, mw));
						}
					}
				}
			}

			long ans = 0;
			for (int i = 0; i < h * w; i++) {
				if (uf.root(i) == i) {
					long black = uf.size(i) - uf.white[i];
					ans += black * uf.white[i];
				}
			}

			out.println(ans);
		}

		boolean isInside(int i, int j) {
			return 0 <= i && i < h && 0 <= j && j < w;
		}

		class UnionFind {
			int[] data;
			int[] white;

			public UnionFind(int size) {
				data = new int[size];
				white = new int[size];
				clear();
			}

			public void clear() {
				Arrays.fill(data, -1);
			}

			public int root(int x) {
				return data[x] < 0 ? x : (data[x] = root(data[x]));
			}

			void add(int x) {
				white[x]++;
			}

			public void union(int x, int y) {
				x = root(x);
				y = root(y);

				if (x != y) {
					if (data[y] > data[x]) {
						final int t = x;
						x = y;
						y = t;
					}

					data[x] += data[y];
					data[y] = x;
					white[x] += white[y];
				}
			}

			boolean same(int x, int y) {
				return root(x) == root(y);
			}

			public int size(int x) {
				return -data[root(x)];
			}
		}

		int f(int i, int j) {
			return i * w + j;
		}
	}

