	static void solve() {
		int h = ni(), w = ni();
		char[][] f = nm(h, w);
		boolean[][] used = new boolean[h][w];
		long ans = 0;
		for(int i=0;i<h;i++) {
			for(int j=0;j<w;j++) {
				if(f[i][j] == '.')continue;
				if(used[i][j])continue;
				var q = new ArrayDeque<int[]>();
				int[] start = {i, j};
				q.add(start);
				used[i][j] = true;
				long nb = 1, nw = 0;
				while(!q.isEmpty()) {
					int[] now = q.poll();
					int x = now[0], y = now[1];
					for(int k=0;k<4;k++) {
						int nx = x + dx[k];
						int ny = y + dy[k];
						if(nx < 0 || nx >= h)continue;
						if(ny < 0 || ny >= w)continue;
