						if(used[nx][ny])continue;
						used[nx][ny] = true;
						if(f[nx][ny] == '.') nw ++;
						else nb ++;
						int[] next = {nx, ny};
						q.add(next);
					}
				}
				ans += nb * nw;
			}
		}
