import java.util.*;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int H = sc.nextInt();
    int W = sc.nextInt();
    char[][] m = new char[H][W];
    for (int i = 0; i < H; i++) {
      String s = sc.next();
      for (int j = 0; j < W; j++) {
        m[i][j] = s.charAt(j);
      }
    }

    int[][] color = new int[H][W];
    int nowColor = 0;
    for (int s = 0; s < H*W; s++) {
      int si = s/W;
      int sj = s%W;
      if (color[si][sj] > 0) continue;
      nowColor++;
      LinkedList<Point> q = new LinkedList<>();
      q.offer(new Point(si,sj));
      color[si][sj] = nowColor;
      while (!q.isEmpty()) {
        Point p = q.poll();
        for (int d = 0; d < 4; d++) {
          int i = p.i+di[d];
          int j = p.j+dj[d];
          if (0 <= i && i < H
             && 0 <= j && j < W
             && color[i][j] == 0) {
            if (m[p.i][p.j] != m[i][j]) {
              color[i][j] = nowColor;
              //System.out.println(si+","+sj+" "+i+","+j);
              q.add(new Point(i,j));
            }
          }
        }
      }
    }

    int[] black = new int[H*W+1];
    int[] white = new int[H*W+1];
    for (int i = 0; i < H; i++) {
      for (int j = 0; j < W; j++) {
        if (m[i][j] == '#') {
          black[color[i][j]]++;
        } else {
          white[color[i][j]]++;
        }
      }
    }

    long ans = 0;
    for (int i = 0; i < H*W+1; i++) {
      ans += (long)white[i]*black[i];
    }
    System.out.println(ans);
  }
  private static int[] di = {0,0,1,-1};
  private static int[] dj = {1,-1,0,0};
  private static class Point {
    private final int i;
    private final int j;
    Point(int i, int j) {
      this.i = i;
      this.j = j;
    }
  }
}

import java.util.*;
public class Main{
	static int h;
	static int w;
	static char[][] c = new char[402][402];
	static boolean[][] visited = new boolean[402][402];
	static int[][] dxy = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
	static int[][] ans = new int[402][402];
	static int[][][] black = new int[402][402][2];
	static void rec(int sx, int sy, int x, int y){
		if(c[x][y]=='.'){
			ans[sx][sy]++;
		}
		if((c[x][y]=='.' && c[x+1][y]!='#' && c[x-1][y]!='#' &&c[x][y+1]!='#' &&c[x][y-1]!='#') || (c[x][y]=='#' && c[x+1][y]!='.' && c[x-1][y]!='.' &&c[x][y+1]!='.' &&c[x][y-1]!='.')){
			return;
		}
		visited[x][y] = true;
		for(int i=0; i<4; i++){
			int x2 = x + dxy[i][0];
			int y2 = y + dxy[i][1];
			if((c[x][y]=='.' && c[x2][y2]=='#')){
				if(visited[x2][y2]==false){
					rec(sx, sy, x2, y2);
				}
			}
			if((c[x][y]=='#' && c[x2][y2]=='.')){
				if(visited[x2][y2]==false){
					black[x2][y2][0] = sx;
					black[x2][y2][1] = sy;
					rec(sx, sy, x2, y2);
				}
			}
		}
	}

	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		h = sc.nextInt();
		w = sc.nextInt();
		for(int i=1; i<h+1; i++){
			String s = sc.next();
			for(int j=1; j<w+1; j++){
				c[i][j] = s.charAt(j-1);
			}
		}
		int num = 0;
		for(int i=1; i<h+1; i++){
			for(int j=1; j<w+1; j++){
				if(c[i][j]=='#'){
					if(black[i][j][0]!=0){
						ans[i][j] = ans[black[i][j][0]][black[i][j][1]];
					}
					else{
						for(int k=1; k<h+1; k++){
							Arrays.fill(visited[k], false);
						}
						rec(i, j, i, j);
					}
					num += ans[i][j];
				}
			}
		}
		System.out.println(num);
	}
}

