	static class TaskX {

		int h, w;
		char[][] s;
		final int B = 0, W = 1;
		public void solve(int testNumber, MyInput in, PrintWriter out) {

			h = in.nextInt(); w = in.nextInt();
			List<P> list = new ArrayList<>();
			s = new char[h][w];
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					s[i][j] = in.nextChar();
					if (s[i][j] == '#') list.add(new P(i, j));
				}
			}

			DisjointSet disjointset = new DisjointSet(h*w+10);
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					for (int k = 0; k < 4; k++) {
						int mh = i + mh4[k];
						int mw = j + mw4[k];
						if (0 <= mh && mh < h && 0 <= mw && mw < w) {
							if ((s[i][j] == '#' && s[mh][mw] == '.') || (s[i][j] == '.' && s[mh][mw] == '#')) {
								disjointset.unite(f(i, j), f(mh, mw));
							}
						}
					}
				}
			}

			Collections.sort(list);

			long ans = 0;
			int[] memo = new int[h*w+10];
			Set<Integer> didset = new HashSet<>();
			for (int i = 0; i < list.size(); i++) {
				boolean done = false;

				int tmp = disjointset.root(f(list.get(i).h, list.get(i).w));
				if (didset.contains(tmp)) done = true;
				if (!done) {
					int ret = dfs(list.get(i).h, list.get(i).w, new boolean[h][w], B, list.get(i).h, list.get(i).w, new HashSet<>());
					memo[tmp] = ret;
					ans += memo[tmp];
				} else {
					ans += memo[tmp];
				}

				didset.add(tmp);
			}

			out.println(ans);

		}

		int f(int i, int j) {
			return i * w + j;
		}

		int dfs(int nh, int nw, boolean[][] used, int stat, int sh, int sw, Set<T> set) {

			used[nh][nw] = true;

			for (int i = 0; i < 4; i++) {
				int mh = nh + mh4[i];
				int mw = nw + mw4[i];
				if (0 <= mh && mh < h && 0 <= mw && mw < w && !used[mh][mw]) {
					if (stat == B && s[mh][mw] == '.') {
						dfs(mh, mw, used, W, sh, sw, set);
					}
					if (stat == W && s[mh][mw] == '#') {
						dfs(mh, mw, used, B, sh, sw, set);
					}
				}
			}
			if (stat == W) set.add(new T(nh, nw, sh, sw));
			return set.size();
		}
	}

	public static class DisjointSet {

		int[] p, rank, cnt;

		public DisjointSet(int size) {
			p = new int[size];
			rank = new int[size];
			cnt = new int[size];

			for (int j = 0; j < size; j++) {
				makeSet(j);
			}
		}

		private void makeSet(int x) {
			p[x] = x;
			rank[x] = 0;
			cnt[x] = 1;
		}

		public int root(int x) {
			return p[x] == x ? x : root(p[x]);
		}

		private void link(int x, int y) {
			if (rank[x] > rank[y]) {
				p[y] = x;
			} else if (rank[x] < rank[y]) {
				p[x] = y;
			} else if (rank[x] == rank[y]) {
				p[x] = y;
				rank[y]++;
			}

			if (x != y) {
				cnt[x] = cnt[y] += cnt[x];
			}
		}

		public void unite(int x, int y) {
			link(root(x), root(y));
		}

		public boolean same(int x, int y) {
			return root(x) == root(y);
		}

		public int getSize(int x) {
			return cnt[root(x)];
		}
	}

	static class T {
		int th, tw, sh, sw;

		public T(int th, int tw, int sh, int sw) {
			super();
			this.th = th;
			this.tw = tw;
			this.sh = sh;
			this.sw = sw;
		}

