					+ "]";
		}

		@Override
		public int hashCode() {
			final int prime = 31;
			int result = 1;
			result = prime * result + sh;
			result = prime * result + sw;
			result = prime * result + th;
			result = prime * result + tw;
			return result;
		}

		@Override
		public boolean equals(Object obj) {
			if (this == obj)
				return true;
			if (obj == null)
				return false;
			if (getClass() != obj.getClass())
				return false;
			T other = (T) obj;
			if (sh != other.sh)
				return false;
			if (sw != other.sw)
				return false;
			if (th != other.th)
				return false;
			if (tw != other.tw)
				return false;
			return true;
		}

	}

	static class P implements Comparable<P> {
