    boolean[][] map, used;
    int h, w;

    void solve() {
        h = ni();
        w = ni();
        map = new boolean[h][w];
        used = new boolean[h][w];
        for (int i = 0; i < h; ++i) {
            String s = ns();
            for (int j = 0; j < w; ++j) {
                map[i][j] = s.charAt(j) == '#';
            }
        }
        int x = 0;
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                int n = dfs(i, j);
                x += (n / 2) * (n + 1) / 2;
            }
        }
        out.println(x);
    }

    int dx[] = {1, 0, -1, 0};
    int dy[] = {0, 1, 0, -1};

    int dfs(int i, int j) {
        if (used[i][j]) return 0;
        used[i][j] = true;
        int n = 1;
        for (int k = 0; k < 4; ++k) {
            int a = i + dx[k];
            int b = j + dy[k];
            if (a < 0) continue;
            if (b < 0) continue;
            if (a >= h) continue;
            if (b >= w) continue;
            if (map[i][j] == map[a][b]) continue;
            n += dfs(a, b);
        }
        return n;
    }

