import java.util.ArrayDeque;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main implements Runnable { // クラス名はMain1

	PrintWriter out = new PrintWriter(System.out);
	InputReader sc = new InputReader(System.in);
	int[] dx = { 1, 0, -1, 0 }, dy = { 0, 1, 0, -1 }; //4 directions

	public static void main(String[] args) {
		Thread.setDefaultUncaughtExceptionHandler((t, e) -> System.exit(1));
		new Thread(null, new Main(), "", 1024 * 1024 * 1024).start(); // 16MBスタックを確保して実行
	}

	public void run() {

		try {
			//String S = sc.next().trim();
			int H = sc.nextInt();
			int W = sc.nextInt();
			char[][] maze = new char[H][W];
			for (int i = 0; i < H; i++) {
				String S = sc.next().trim();
				for (int j = 0; j < W; j++) {
					maze[i][j] = S.charAt(j);
				}
			}

			long ans = 0;
			boolean[][] visit = new boolean[H][W];
			for (int i = 0; i < H; i++) {
				for (int j = 0; j < W; j++) {
					if (maze[i][j] == '#') {
						Point now = new Point(i, j);
						ans += bfs(maze, H, W, now, visit);
					}
				}
			}

			out.println(ans);

		} catch (ArithmeticException ae) {
			//ae.printStackTrace();
			throw new RuntimeException();
		} catch (Exception e) {
			e.printStackTrace();
			throw new RuntimeException();
		} finally {
			out.flush();
			out.close();
		}
	}

	public long bfs(char[][] maze, int H, int W, Point now, boolean[][] visit) {
		ArrayDeque<Point> deq = new ArrayDeque<>();
		deq.add(now);
		long num = 0;
		char current = maze[now.x][now.y];
		visit[now.x][now.y] = true;
		long white = 0;
		long black = 0;

		while (deq.size() > 0) {
			Point c = deq.poll();
			//visit[c.x][c.y] = true;
			current = maze[c.x][c.y];
			if (maze[c.x][c.y] == '.') {
				white++;
			} else {
				black++;
			}
			for (int i = 0; i < 4; i++) {
				int nx = c.x + dx[i];
				int ny = c.y + dy[i];
				if (nx >= 0 && ny >= 0 && nx < H && ny < W) {
					if (current != maze[nx][ny] && !visit[nx][ny]) {
						num++;
						Point next = new Point(nx, ny);
						deq.add(next);
						visit[nx][ny] = true;
					}
				}
			}
		}

		return white * black;

	}

