3 3
.#.
..#
#..
Sample Output 1
Copy
10
*/
        PrintWriter pw = new PrintWriter(System.out);
        FastReader fr = new FastReader();
        int t = 1;
        for (int ti = 0; ti < t; ++ti)
        {
            int h=fr.i();
            int w=fr.i();
            char [][] arr=new char[h][w];
            for(int hi=0;hi<h;++hi)
            {
                arr[hi]=fr.nextLine().toCharArray();
            }
            ways=0;
            for(int hi=0;hi<h;++hi)
            {
                for(int wi=0;wi<w;++wi)
                {
                    if(arr[hi][wi]=='#')
                    {
                        boolean [][] visited=new boolean[h][w];
                        if(hi-1>=0)
                        {
                            recursion(arr,hi-1,wi,'#',visited);
                        }
                        if(hi+1<h)
                        {
                            recursion(arr,hi+1,wi,'#',visited);
                        }
                        if(wi-1>=0)
                        {
                            recursion(arr,hi,wi-1,'#',visited);
                        }
                        if(wi+1<w)
                        {
                            recursion(arr,hi,wi+1,'#',visited);
                        }
                    }
                }
            }
            pw.println(ways);
        }
        pw.flush();
        pw.close();
    }
    public static void recursion(char [][] arr,int hi,int wi,char c,boolean[][] visited)
    {
        //System.out.println("hi="+hi+" wi="+wi+" c="+c);
        if(c==arr[hi][wi] || visited[hi][wi])
        {
            return;
        }
        if(c=='#')
            c='.';
        else
            c='#';
        if(c=='.')
        {
            //System.out.println(hi+" "+wi);
            ++ways;
        }
        visited[hi][wi]=true;

        if(hi-1>=0)
        {
            recursion(arr,hi-1,wi,c,visited);
        }
        if(hi+1<arr.length)
        {
            recursion(arr,hi+1,wi,c,visited);
        }
        if(wi-1>=0)
        {
            recursion(arr,hi,wi-1,c,visited);
        }
        if(wi+1<arr[hi].length)
        {
            recursion(arr,hi,wi+1,c,visited);
        }
    }
