import java.util.*;
import java.io.*;

public class Main {

  private static void solve() {
    int h = nextInt();
    int w = nextInt();

    char[][] g = new char[h][w];

    for (int i = 0; i < h; i++) {
      g[i] = next().toCharArray();
    }

    boolean[][] visit = new boolean[h][w];

    long ans = 0;
    for (int i = 0; i < h; i++) {
      for (int j = 0; j < w; j++) {
        if (g[i][j] == '#' && !visit[i][j]) {
          ans += bfs(i, j, visit, g, h, w);
        }
      }
    }

    System.out.println(ans);
  }

  private static long bfs(int i, int j, boolean[][] visit, char[][] g, int h, int w) {
    int[] dx = {1, -1, 0, 0};
    int[] dy = {0, 0, 1, -1};
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(new int[] {i, j, 0});
    visit[i][j] = true;

    long black = 1;
    long white = 0;
    while (!queue.isEmpty()) {
      int[] first = queue.poll();

      for (int k = 0; k < dx.length; k++) {
        int nx = first[0] + dx[k];
        int ny = first[1] + dy[k];

        int expected = (first[2] == 0 ? 1 : 0);
        char expectedChar = '#';
        if (expected == 1) {
          expectedChar = '.';
        }

        if (nx >= 0 && nx < h && ny >= 0 && ny < w && expectedChar == g[nx][ny] && !visit[nx][ny]) {
          visit[nx][ny] = true;
          if (g[nx][ny] == '#') {
            black++;
          } else {
            white++;
          }
          queue.offer(new int[] {nx, ny, expected});
        }
      }
    }
    return black * white;
  }

  private static void run() {
    br = new BufferedReader(new InputStreamReader(System.in));
    out = new PrintWriter(System.out);

    solve();

    out.close();
  }

  private static StringTokenizer st;
  private static BufferedReader br;
  private static PrintWriter out;

  private static String next() {
    while (st == null || !st.hasMoreElements()) {
      String s;
      try {
        s = br.readLine();
      } catch (IOException e) {
        return null;
      }
      st = new StringTokenizer(s);
    }
    return st.nextToken();
  }

  private static int nextInt() {
    return Integer.parseInt(next());
  }

  private static long nextLong() {
    return Long.parseLong(next());
  }

  public static void main(String[] args) {
    run();
  }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.*;
public class Main implements Runnable {
    public static int h;
    public static int w;
    public static boolean[][] map;
    public static int[][] root;

    public static void main(String[] args)throws Exception{
        new Thread(null, new Main(), "", 16 * 1024 * 1024).start();
    }
    public void run() {
        FastScanner sc = new FastScanner();


        w = sc.nextInt();
        h = sc.nextInt();

        map = new boolean[w][h];

        for(int i = 0;i < w;i ++){ //map を　格納
            String temp = sc.next();
            for(int j = 0;j < h;j ++){
                map[i][j] = temp.charAt(j)=='#';
            }
        }


        root = new int[w][h];
        int rootcount = 1;

        for(int i = 0;i < w;i ++){
            for(int j = 0;j < h;j ++){
                if(root[i][j] != 0){
                    continue;
                }
                root[i][j] = rootcount;
                rootCheck(i,j);
                rootcount++;

            }
        }

//
//        for(int i = 0;i < w;i++){//現在の2次元配列表示プログラム
//            for(int j = 0;j < h;j++) {
//                System.out.print(root[i][j] + " ");
//                if (j == h - 1)
//                    System.out.println("");
//            }
//        }

        int ans =0;
        for(int i = 0;i < rootcount;i ++){
            int black = 0;
            int white = 0;
            for(int j = 0;j < w;j ++){
                for(int k = 0;k < h;k ++){

                    if (root[j][k] == i){
                        if(map[j][k]){
                            black ++;
                        }else{
                            white ++;
                        }
                    }

                }
            }
            ans += black * white;
        }

        System.out.println(ans);



    }
    static void rootCheck(int i,int j){
        //上
        if(i != 0) {
            if (root[i - 1][j] == 0 && (map[i][j] != map[i-1][j])){
                root[i - 1][j] = root[i][j];
                rootCheck(i-1,j);
            }
        }
        //右
        if(j != h-1) {
            if (root[i][j + 1] == 0 && (map[i][j] != map[i][j + 1])){
                root[i][j + 1] = root[i][j];
                rootCheck(i,j+1);
            }
        }
        //下
        if(i != w-1) {
            if (root[i + 1][j] == 0 && (map[i][j] != map[i + 1][j])){
                root[i + 1][j] = root[i][j];
                rootCheck(i + 1,j);
            }
        }
        //左
        if(j != 0) {
            if (root[i][j - 1] == 0 && (map[i][j] != map[i][j - 1])){
                root[i][j - 1] = root[i][j];
                rootCheck(i,j-1);
            }
        }
    }
}

class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
}

import java.util.ArrayList;
import java.util.Objects;
import java.util.Scanner;

public class Main {

	private static final char BLACK = '#';
	private static final char WHITE = '.';

	private int H;
	private int W;

	public static void main(String[] args) {
		new Main().execute();
	}

	public void execute() {
		Scanner sc = new Scanner(System.in);
		H = sc.nextInt();
		W = sc.nextInt();
		sc.nextLine();
		Cell[][] board = new Cell[H][W];
		ArrayList<Cell> blacks = new ArrayList<>();
		ArrayList<Cell> whites = new ArrayList<>();
		UFCell uf = new UFCell();

		for (int i = 0; i < H; i++) {
			String line = sc.nextLine();
			for (int j = 0; j < W; j++) {
				char c = line.charAt(j);
				Cell cell;
				switch (c) {
				case BLACK:
					cell = new Cell(i, j, BLACK);
					board[i][j] = cell;
					blacks.add(cell);
					uf.add(cell);
					break;
				case WHITE:
					cell = new Cell(i, j, WHITE);
					board[i][j] = cell;
					whites.add(cell);
					uf.add(cell);
					break;
				default:
					throw new IllegalArgumentException();
				}
			}
		}
		for (int i = 0; i < H; i++) {
			for (int j = 0; j < W; j++) {
				Cell c = board[i][j];
				if (i > 0 && c.Color != board[i - 1][j].Color) {
					uf.union(c, board[i - 1][j]);
				}
				if (j > 0 && c.Color != board[i][j - 1].Color) {
					uf.union(c, board[i][j - 1]);
				}
				if (i < H - 1 && c.Color != board[i + 1][j].Color) {
					uf.union(c, board[i + 1][j]);
				}
				if (j < W - 1 && c.Color != board[i][j + 1].Color) {
					uf.union(c, board[i][j + 1]);
				}
			}
		}

		int cnt = 0;
		for (Cell b : blacks) {
			for (Cell w : whites) {
				if (uf.find(b, w)) {
					cnt++;
				}
			}
		}
		System.out.println(cnt);
		sc.close();
	}

	class Cell {
		public final int id;
		public final char Color;
		public final int x;
		public final int y;

		public Cell(int x, int y, char color) {
			this.x = x;
			this.y = y;
			this.Color = color;
			this.id = H * y + x;
		}

		@Override
		public boolean equals(Object obj) {
			// TODO Auto-generated method stub
			if (obj instanceof Cell) {
				Cell that = (Cell) obj;
				return (this.x == that.x) && (this.y == that.y);
			} else {
				return false;
			}
		}

		@Override
		public int hashCode() {
			return Objects.hash(this.x, this.y);
		}

	}

	class UFCell {
		private int parents[] = new int[H * W];

		public void add(Cell c) {
			parents[c.id] = c.id;
		}

		private int rootID(int cid) {
			if (parents[cid] == cid) {
				return cid;
			} else {
				int pid = parents[cid];
				int root = rootID(pid);
				parents[cid] = root;
				return root;
			}
		}

		public void union(Cell c1, Cell c2) {
			int r1 = rootID(c1.id);
			int r2 = rootID(c2.id);
			if (r1 == r2) {
				return;
			} else {
				parents[r1] = r2;
			}
		}

		public boolean find(Cell c1, Cell c2) {
			return rootID(c1.id) == rootID(c2.id);
		}
	}

}

