public class Main {

    static Scanner scanner;

    public static void main(String[] args) {
        scanner = new Scanner(System.in);

        int H=gi();
        int W=gi();
        char[][] g=new char[H][W];
        boolean[][] f=new boolean[H][W];
        UnionFind uf=new UnionFind(H*W);

        for (int i=0; i<H;i++) {
