    public static class Pair<K, V> extends AbstractMap.SimpleEntry<K, V> implements Comparable<Pair<K, V>> {
        /** serialVersionUID. */
        private static final long serialVersionUID = 6411527075103472113L;

        public Pair(final K key, final V value) {
            super(key, value);
        }

        @Override
        public int compareTo(Pair<K, V> o) {

            Comparable key = (Comparable)this.getKey();
            Comparable key2 = (Comparable)o.getKey();

            return key.compareTo(key2);
        }

    }

    public static class UnionFind {

    	int[] parent;
    	public UnionFind(int n) {
    		parent=new int[n];
    		for(int i=0; i<parent.length;i++) {
    			parent[i]=-1;
    		}
    	}

    	public int find(int n) {
    		if(parent[n]<0) {
    			return n;
    		} else {
    			parent[n]=find(parent[n]);
    			return parent[n];
    		}

    	}

    	public void union(int n1, int n2) {
    		int r1=find(n1);
    		int r2=find(n2);
    		if(r1==r2) return;

    		if(getRunk(r1)<getRunk(r2)) {
    			parent[n1]=r2;
    		} else {
    			parent[n2]=r1;
    			if(getRunk(r1)==getRunk(r2)) parent[r1]--;
    		}
    	}

    	public int getRunk(int n) {
            return -parent[find(n)];
    	}

    	public int getKindNum() {
            int ret=0;
            for (int i=0; i<parent.length;i++) {
            	if(parent[i]<0) {
            		ret++;
            	}
            }
            return ret;
    	}

    	public boolean same(int n1, int n2) {
    		return find(n1)==find(n2);
    	}
    }

    // 文字列として入力を取得
    public static String gs() {
         return scanner.next();
    }

    // intとして入力を取得
    public static int gi() {
         return Integer.parseInt(scanner.next());
    }

    // longとして入力を取得
    public static long gl() {
         return Long.parseLong(scanner.next());
    }

    // doubleとして入力を取得
    public static double gd() {
         return Double.parseDouble(scanner.next());
    }
}

import java.awt.Point;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Queue;
import java.util.Scanner;

public class Main {
	static int ans = 0;
	static int[] dw = {1,0,-1,0};
    static int[] dh = {0,1,0,-1};
    static Queue<Point> queue = new ArrayDeque<>();
    static ArrayList<String> Sh = new ArrayList<>(450);
    static int H;
    static int W;
    static int reachedB;
    static int[][] reached = new int[500][500];
    static int[][] reachedBlack = new int[500][500];
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        for(int i=0;i<H;i++) {
        	Sh.add(sc.next());
        }


        for(int i=0;i<W;i++) {
        	for(int j=0;j<H;j++) {
        		if(Sh.get(j).charAt(i) == '#' && reachedBlack[j][i] ==0) {
        			queue.offer(new Point(j,i));
        			reachedB=0;
        			for(int a=0;a<H;a++) {
        				Arrays.fill(reached[a], 0);
        			}
        			bfs();
//        			System.out.println("bbbb  " + queue.poll());
        		}
        	}
        }

        System.out.println(ans);

        sc.close();
    }

    public static void bfs() {
//    	System.out.println("BFS!!  " + queue.peek());
    	while(queue.peek()!=null) {
	    	Point p = queue.poll();
	    	if(p == null) {
	    		return;
	    	}
//	    	System.out.println("(" + p.x + "," + p.y + ")"  + " = " + Sh.get(p.x).charAt(p.y));
	    	if(Sh.get(p.x).charAt(p.y)=='#') {
	    		for(int k=0;k<4;k++) {
	    			if(p.x+dh[k] > H-1 || p.x+dh[k] < 0 || p.y+dw[k] > W-1 || p.y+dw[k] <0) {
	    				continue;
	    			}
	    			if(reached[p.x+dh[k]][p.y+dw[k]] == reachedB) continue;
					if(Sh.get(p.x+dh[k]).charAt(p.y+dw[k]) == '.') {
						queue.offer(new Point(p.x+dh[k],p.y+dw[k]));
						ans++;	
						reached[p.x+dh[k]][p.y+dw[k]] += (reachedB - reached[p.x+dh[k]][p.y+dw[k]]);
						reachedBlack[p.x+dh[k]][p.y+dw[k]]++;
					}
				}
	    	}else {
	    		for(int k=0;k<4;k++) {
	    			if(p.x+dh[k] > H-1 || p.x+dh[k] < 0 || p.y+dw[k] > W-1 || p.y+dw[k] <0) {
	    				continue;
	    			}
	    			if(reached[p.x+dh[k]][p.y+dw[k]] > 0) continue;
					if(Sh.get(p.x+dh[k]).charAt(p.y+dw[k]) == '#') {
						queue.offer(new Point(p.x+dh[k],p.y+dw[k]));
					}
				}
	    	}
	    	bfs();
    	}

    }
}

import java.awt.Point;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main implements Runnable { // クラス名はMain1

	PrintWriter out = new PrintWriter(System.out);
	InputReader sc = new InputReader(System.in);
	int[] dx = { 1, 0, -1, 0 }, dy = { 0, 1, 0, -1 }; //4 directions

	public static void main(String[] args) {
		Thread.setDefaultUncaughtExceptionHandler((t, e) -> System.exit(1));
		new Thread(null, new Main(), "", 1024 * 1024 * 1024).start(); // 16MBスタックを確保して実行
	}

	public void run() {

		try {
			//String S = sc.next().trim();
			int H = sc.nextInt();
			int W = sc.nextInt();
			char[][] maze = new char[H][W];
			for (int i = 0; i < H; i++) {
				String S = sc.next().trim();
				for (int j = 0; j < W; j++) {
					maze[i][j] = S.charAt(j);
				}
			}

			long ans = 0;
			//TreeSet<Point> ts1[][] = new TreeSet[H][W];
			for (int i = 0; i < H; i++) {
				for (int j = 0; j < W; j++) {
					if (maze[i][j] == '#') {
						Point now = new Point(i, j);
						ans += bfs(maze, H, W, now);
					}
					//ts1[i][j].addAll(bfs(maze, H, W, now));
				}
			}

			out.println(ans);

		} catch (ArithmeticException ae) {
			//ae.printStackTrace();
			throw new RuntimeException();
		} catch (Exception e) {
			e.printStackTrace();
			throw new RuntimeException();
		} finally {
			out.flush();
			out.close();
		}
	}

	public long bfs(char[][] maze, int H, int W, Point now) {
		ArrayDeque<Point> deq = new ArrayDeque<>();
		deq.add(now);
		long num = 0;
		char current = maze[now.x][now.y];
		boolean[][] visit = new boolean[H][W];

		while (deq.size() > 0) {
			Point c = deq.poll();
			//visit[c.x][c.y] = true;
			current = maze[c.x][c.y];
			for (int i = 0; i < 4; i++) {
				int nx = c.x + dx[i];
				int ny = c.y + dy[i];
				if (nx >= 0 && ny >= 0 && nx < H && ny < W) {
					if (current != maze[nx][ny] && !visit[nx][ny]) {
						if (maze[nx][ny] == '.') {
							num++;
						}
						Point next = new Point(nx, ny);
						deq.add(next);
						visit[nx][ny] = true;
					}
				}
			}
		}

		return num;

	}

	///////////////////////////////////////////////////////////
	//Ignore
	///////////////////////////////////////////////////////////
	static class InputReader {
		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}
