	static int[] dx={0,0,-1,1};
	static int[] dy={1,-1,0,0};
	static boolean[][] ma;
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		h=sc.nextInt();
		w=sc.nextInt();
