			map[i]=s.toCharArray();
		}
		for(int i=0; i<h; i++){
			for(int j=0; j<w; j++){
				if(map[i][j]=='#'){
					ma=new boolean[h][w];
					dfs(i,j);
				}
			}
		}
		System.out.println(ans);
	}
	static void dfs(int x,int y){
		ma[x][y]=true;
		if(map[x][y]=='.'){
			ans++;
		}
		for(int i=0; i<4; i++){
			if(check(x+dx[i],y+dy[i])){
