	static void solve() {
		int h = ni(), w = ni();
		char[][] f = nm(h, w);
		boolean[][] used = new boolean[h][w];
		long ans = 0;
		for(int i=0;i<h;i++) {
			for(int j=0;j<w;j++) {
				if(f[i][j] == '.')continue;
				if(used[i][j])continue;
				var q = new ArrayDeque<int[]>();
				int[] start = {i, j};
				q.add(start);
				used[i][j] = true;
				boolean[][] tUsed = new boolean[h][w];
				tUsed[i][j] = true;
				int nb = 1, nw = 0;
				while(!q.isEmpty()) {
					int[] now = q.poll();
					for(int k=0;k<4;k++) {
						int nx = now[0] + dx[k];
						int ny = now[1] + dy[k];
						if(nx < 0 || nx >= h)continue;
						if(ny < 0 || ny >= w)continue;
						if(f[now[0]][now[1]] == f[nx][ny])continue;
						if(tUsed[nx][ny])continue;
						used[nx][ny] = true;
						tUsed[nx][ny] = true;
						if(f[nx][ny] == '.') nw ++;
						else nb ++;
						int[] next = {nx, ny};
						q.add(next);
					}
				}
				ans += nb * nw;
			}
		}
		out.println(ans);
	}


