			int[] memo = new int[400500];
			Set<Integer> didset = new HashSet<>();
			for (int i = 0; i < list.size(); i++) {
				boolean done = false;

				int tmp = disjointset.root(f(list.get(i).h, list.get(i).w));
				if (didset.contains(tmp)) done = true;
				if (!done) {
					int ret = dfs(list.get(i).h, list.get(i).w, new boolean[h][w], B, list.get(i).h, list.get(i).w, new HashSet<>());
					memo[tmp] = ret;
