			used[nh][nw] = true;

			for (int i = 0; i < 4; i++) {
				int mh = nh + mh4[i];
				int mw = nw + mw4[i];
				if (0 <= mh && mh < h && 0 <= mw && mw < w && !used[mh][mw]) {
