/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int h = in.nextInt();
            int w = in.nextInt();

            String[] s = in.nextStringArray(h);

            boolean[][] a = new boolean[h][w];
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    a[i][j] = s[i].charAt(j) == '#';
                }
            }

            UnionFind uf = new UnionFind(h * w);
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    if (j < w - 1 && (a[i][j] ^ a[i][j + 1])) {
                        uf.union(i * w + j, i * w + j + 1);
                    }
                    if (i < h - 1 && (a[i][j] ^ a[i + 1][j])) {
                        uf.union(i * w + j, (i + 1) * w + j);
                    }
                }
            }

            Map<Integer, Integer> count = new TreeMap<>();
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    if (a[i][j]) {
                        count.merge(uf.root(i * w + j), 1, Integer::sum);
                    }
                }
            }

            long ans = 0;
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    if (!a[i][j] && count.containsKey(uf.root(i * w + j))) ans += count.get(uf.root(i * w + j));
                }
            }

            out.println(ans);
        }

    }

    static class InputReader {
        private BufferedReader br;
        private StringTokenizer st;

        public InputReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
            st = new StringTokenizer("");
        }

        public String nextString() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public String[] nextStringArray(int n) {
            String[] res = new String[n];
            for (int i = 0; i < n; i++) {
                res[i] = nextString();
            }
            return res;
        }

    }

    static class UnionFind {
        int[] parent;

        public UnionFind(int size) {
            parent = new int[size];
            Arrays.fill(parent, -1);
        }

        public boolean union(int x, int y) {
            x = root(x);
            y = root(y);
            if (x != y) {
                if (parent[y] < parent[x]) {
                    int tmp = y;
                    y = x;
                    x = tmp;
                }
                parent[x] += parent[y];
                parent[y] = x;
                return true;
            }
            return false;
        }

        public int root(int x) {
            return parent[x] < 0 ? x : (parent[x] = root(parent[x]));
        }

        public ArrayList<ArrayList<Integer>> getGroups() {
            int n = parent.length;
            ArrayList<ArrayList<Integer>> groups = new ArrayList<>();
            HashMap<Integer, Integer> map = new HashMap<>();
            for (int i = 0; i < n; i++) {
                int r = root(i);
                if (!map.containsKey(r)) {
                    map.put(r, groups.size());
                    groups.add(new ArrayList<>());
                }
                groups.get(map.get(r)).add(i);
            }
            return groups;
        }

        public String toString() {
            return getGroups().toString();
        }

    }
}

import java.util.*;

public class Main {

    /**
     * @param args
     */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int H = sc.nextInt();
        int W = sc.nextInt();
        String[] S = new String[H];
        for (int i=0; i<H; i++) {
            S[i] = sc.next();
        }
        int ans = solve(H, W, S);

        System.out.println(ans);
    }

    private static int solve(int H, int W, String[] S) {
        int count = 0;

        for (int i=0; i<H; i++) {
            for (int j=0; j<W; j++) {
                if (S[i].charAt(j) == '.') continue;
                boolean[][] visited = new boolean[H][W];
                visited[i][j] = true;

                count += search(H, W, S, visited, i, j);
            }
        }

        return count;
    }

    private static int search(int H, int W, String[] S, boolean[][] visited, int h, int w) {
        int[] moveH = {0, -1, 0, 1};
        int[] moveW = {1, 0, -1, 0};
        int count = 0;

        for(int move=0; move<4; move++) {
            int nextH = h + moveH[move];
            int nextW = w + moveW[move];
            if(nextH < 0 || nextH == H) continue;
            if(nextW < 0 || nextW == W) continue;

            if (S[h].charAt(w) == S[nextH].charAt(nextW)) continue;
            if (visited[nextH][nextW]) continue;

            visited[nextH][nextW] = true;
            if (S[nextH].charAt(nextW) == '.') {
                count++;
            }

            count += search(H, W, S, visited, nextH, nextW);
        }

        return count;
    }
}

import java.util.ArrayDeque;
import java.util.Scanner;

public class Main {
	static int cnt = 0;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		StringBuilder sb = new StringBuilder();
		int h = sc.nextInt();
		int w = sc.nextInt();
		char[][] map = new char[h][w];
		for (int i = 0; i < h; i++) {
			map[i] = sc.next().toCharArray();
		}
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (map[i][j] == '.') {
					solve(i, j, map);
				}
			}
		}
		System.out.println(cnt);
	}

	private static void solve(int i, int j, char[][] map) {
		ArrayDeque<Pos> deque = new ArrayDeque<>();
		Pos pos = new Pos(i, j);
		deque.add(pos);
		int h = map.length;
		int w = map[0].length;
		boolean memo[][] = new boolean[h][w];
		memo[i][j] = true;
		int[] dh = { 1, -1, 0, 0 };
		int[] dw = { 0, 0, 1, -1 };
		int hh, ww;
		while (!deque.isEmpty()) {
			Pos tmp = deque.poll();
			for (int x = 0; x < 4; x++) {
				hh = dh[x] + tmp.h;
				ww = dw[x] + tmp.w;
				if (hh >= 0 && hh < h && ww >= 0 && ww < w) {
					if (map[tmp.h][tmp.w] == '.') {
						if (map[hh][ww] == '#' && !memo[hh][ww]) {
							memo[hh][ww] = true;
							deque.add(new Pos(hh, ww));
							cnt++;
						}
					} else if (map[tmp.h][tmp.w] == '#') {
						if (map[hh][ww] == '.' && !memo[hh][ww]) {
							memo[hh][ww] = true;
							deque.add(new Pos(hh, ww));
						}
					}
				}

			}
		}
	}
}

class Pos {
