	static int[][] islandbw = new int[160000][2];
	static int curisland = 0;

	static void findIsland(int x, int y, boolean state, int island)
	{
		if(x<0||y<0||x>=w||y>=h)return;
		if(visited[x][y])return;
		if(grid[x][y] == state)
		{
			visited[x][y] = true;
