			if(grid[x][y])
				islandbw[island][0]++;
			else islandbw[island][1]++;

			//expand
			findIsland(x-1,y,!state,island);
			findIsland(x+1,y,!state,island);
			findIsland(x,y-1,!state,island);
			findIsland(x,y+1,!state,island);
		}
	}

