/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author prakharjain
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        CAlternatingPath solver = new CAlternatingPath();
        solver.solve(1, in, out);
        out.close();
    }

    static class CAlternatingPath {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int h = in.nextInt();
            int w = in.nextInt();

            String[] g = new String[h];

            for (int i = 0; i < h; i++) {
                g[i] = in.next();
            }

            DsuInteger dsu = new
                    DsuInteger(h * w);

            for (int i = 0; i < h * w; i++) {
                dsu.createSet(i);
            }

            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    int ci = i * w + j;
                    if (i > 0) {
                        if (g[i].charAt(j) != g[i - 1].charAt(j)) {
                            int pr = (i - 1) * w + j;
                            dsu.mergeSets(ci, pr);
                        }
                    }

                    if (j > 0) {
                        if (g[i].charAt(j) != g[i].charAt(j - 1)) {
                            int pr = i * w + j - 1;
                            dsu.mergeSets(ci, pr);
                        }
                    }
                }
            }

            Map<Integer, Integer> bm = new HashMap<>();
            Map<Integer, Integer> wm = new HashMap<>();

            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    int ci = i * w + j;

                    int rep = dsu.findSet(ci);

                    if (!bm.containsKey(rep)) {
                        bm.put(rep, 0);
                        wm.put(rep, 0);
                    }

                    if (g[i].charAt(j) == '#')
                        bm.merge(rep, 1, (x, y) -> x + y);
                    else
                        wm.merge(rep, 1, (x, y) -> x + y);
                }
            }


            long ans = 0;
            for (int key : bm.keySet()) {
                long bs = bm.get(key);
                long ws = wm.get(key);

                ans += bs * ws;
            }

            out.println(ans);
        }

        class DsuInteger {
            int[] parent;
            int[] rank;
            int[] size;
            int n;

            public DsuInteger(int n) {
                this.n = n;
                this.parent = new int[n];
                this.rank = new int[n];
                this.size = new int[n];
            }

            int createSet(int x) {
                parent[x] = x;
                rank[x] = 0;
                size[x] = 1;
                return x;
            }

            int findSet(int x) {
                int par = parent[x];
                if (x != par) {
                    parent[x] = findSet(par);
                    return parent[x];
                }
                return par;
            }

            int mergeSets(int x, int y) {
                int rx = findSet(x);
                int ry = findSet(y);

                if (rx == ry) {
                    return rx;
                }

                int fp = -1;

                if (rank[rx] > rank[ry]) {
                    parent[ry] = rx;
                    fp = rx;
                } else {
                    parent[rx] = ry;
                    fp = ry;
                }

                size[fp] = size[rx] + size[ry];

                if (rank[rx] == rank[ry]) {
                    rank[ry] = rank[ry] + 1;
                }

                return fp;
            }

        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public String next() {
            return nextString();
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(long i) {
            writer.println(i);
        }

    }
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;

public class Main {
    public static class UnionFindTree {
        // nodeNum 个数，下标 [1, nodeNum]
        int nodeNum;
        int [] parent;
        int [] height;

        public UnionFindTree(int nodeNum) {
            this.nodeNum = nodeNum;
            parent = new int[nodeNum + 1];
            height = new int[nodeNum + 1];
            for (int i = 1; i <= nodeNum; ++i) {
                parent[i] = i;
                height[i] = 0;
            }
        }

        int find(int x) {
            if (parent[x] == x) {
                return x;
            } else {
                return parent[x] = find(parent[x]);
            }
        }

        void union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) {
                return;
            }
            if (height[rootX] < height[rootY]) {
                parent[rootX] = rootY;
            } else {
                if (height[rootX] == height[rootY]) {
                    height[rootX]++;
                }
                parent[rootY] = rootX;
            }
        }

    }
    public static void main(String [] args) {
        Scanner scanner = new Scanner(System.in);
        int h = scanner.nextInt();
        int w = scanner.nextInt();
        char[][] graph = new char[h][w];
        for (int i = 0; i < h; ++i) {
            String s = scanner.next();
            for (int j = 0; j < w; ++j) {
                graph[i][j] = s.charAt(j);
            }
        }
        UnionFindTree unionFindTree = new UnionFindTree(h * w);
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                if (i + 1 < h) {
                    if (graph[i][j] != graph[i + 1][j]) {
                        unionFindTree.union(
                                i * w + j,
                                (i + 1) * w + j
                        );
                    }
                }
                if (i - 1 >= 0) {
                    if (graph[i][j] != graph[i - 1][j]) {
                        unionFindTree.union(
                                i * w + j,
                                (i - 1) * w + j
                        );
                    }
                }
                if (j + 1 < w) {
                    if (graph[i][j] != graph[i][j + 1]) {
                        unionFindTree.union(
                                i * w + j,
                                i * w + j + 1
                        );
                    }
                }

                if (j - 1 >= 0) {
                    if (graph[i][j] != graph[i][j - 1]) {
                        unionFindTree.union(
                                i * w + j,
                                i * w + j - 1
                        );
                    }
                }

            }
        }
        Map<Integer, Set<Integer>> blacks = new HashMap<>();
        Map<Integer, Set<Integer>> whites = new HashMap<>();
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                int root = unionFindTree.find(i * w + j);

                if (graph[i][j] == '#') {
                    Set<Integer> node = blacks.getOrDefault(root, new HashSet<>());
                    node.add(i * w + j);
                    blacks.put(root, node);
                } else {
                    Set<Integer> node = whites.getOrDefault(root, new HashSet<>());
                    node.add(i * w + j);
                    whites.put(root, node);
                }
            }
        }
        long result = 0;
        for (Map.Entry<Integer, Set<Integer>> rootAndSize : whites.entrySet()) {
            int blackNum = blacks.getOrDefault(rootAndSize.getKey(), new HashSet<>()).size();
            int whiteNum = rootAndSize.getValue().size();
            result += (long)blackNum * (long)whiteNum;
        }
        System.out.println(result);


    }
}

import java.util.ArrayDeque;
import java.util.Scanner;

public class Main {
	static int acnt = 0, bcnt = 0;
	static boolean memo[][];

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		StringBuilder sb = new StringBuilder();
		int h = sc.nextInt();
		int w = sc.nextInt();
		int sum = 0;
		char[][] map = new char[h][w];
		for (int i = 0; i < h; i++) {
			map[i] = sc.next().toCharArray();
		}
		memo = new boolean[h][w];
		for (int i = 0; i < h; i++) {
			for (int j = 0; j < w; j++) {
				if (map[i][j] == '.' && !memo[i][j]) {
					acnt = 0;
					bcnt = 1;
					solve(i, j, map);
					sum += acnt * bcnt;
				}
			}
		}
		System.out.println(sum);
	}

	private static void solve(int i, int j, char[][] map) {
		ArrayDeque<Pos> deque = new ArrayDeque<>();
		Pos pos = new Pos(i, j);
		deque.add(pos);
		int h = map.length;
		int w = map[0].length;
		memo[i][j] = true;
		int[] dh = { 1, -1, 0, 0 };
		int[] dw = { 0, 0, 1, -1 };
		int hh, ww;
		while (!deque.isEmpty()) {
			Pos tmp = deque.poll();
			for (int x = 0; x < 4; x++) {
				hh = dh[x] + tmp.h;
				ww = dw[x] + tmp.w;
				if (hh >= 0 && hh < h && ww >= 0 && ww < w) {
					if (map[tmp.h][tmp.w] == '.') {
						if (map[hh][ww] == '#' && !memo[hh][ww]) {
							memo[hh][ww] = true;
							deque.add(new Pos(hh, ww));
							acnt++;
						}
					} else if (map[tmp.h][tmp.w] == '#') {
						if (map[hh][ww] == '.' && !memo[hh][ww]) {
							memo[hh][ww] = true;
							deque.add(new Pos(hh, ww));
							bcnt++;
						}
					}
				}

			}
		}
	}
}

