public class Main {

	public static void main(String[] args) throws IOException {
		FastScanner sc = new FastScanner(System.in);

		int H = sc.nextInt();
		int W = sc.nextInt();
		char[][] board = new char[H][W];
		ArrayList<Pair> list = new ArrayList<Pair>();
		for(int i = 0; i < H; i++){
			board[i] = sc.next().toCharArray();
			for(int j = 0; j < W; j++)
				if(board[i][j] == '#') list.add(new Pair(i, j));
		}

		long ans = 0;
		int[][] visited = new int[H][W];	
		int index = 0;

		for(Pair p : list){
			if(visited[p.y][p.x] != 0) continue;
			index++;
			visited[p.y][p.x] = index;
			int numB = 1;
			int numW = 0;
			Deque<Pair> queue = new ArrayDeque<Pair>();
			queue.addFirst(p);

			while(queue.size() != 0){
				Pair q = queue.removeFirst();
				char now = board[q.y][q.x];
				//System.out.println(q.y + " " + q.x);

				int[] dy = {0, -1, 0, 1};
				int[] dx = {1, 0, -1, 0};
				for(int i = 0; i < 4; i++){
					if(q.y + dy[i] >= H || q.y + dy[i] < 0) continue;
					if(q.x + dx[i] >= W || q.x + dx[i] < 0) continue;
					if(visited[q.y+dy[i]][q.x+dx[i]] != 0) continue;

					char next = board[q.y+dy[i]][q.x+dx[i]];
					if(now == next) continue;

					if(next == '.'){
						numW++;
					}else if(next == '#'){
						numB++;
					}
					visited[q.y+dy[i]][q.x+dx[i]] = index;

					queue.addLast(new Pair(q.y+dy[i], q.x+dx[i]));
				}
			}

			//System.out.println(numB + " " + numW);
			ans += (long)numB * numW;

		}

		System.out.println(ans);

		/*
		for(int i = 0; i < H; i++){
			for(int j = 0; j < W; j++){
				System.out.print(visited[i][j] + " ");
			}
			System.out.println();
		}
		*/

	}//end main

}//end Main

class UnionFind{
	int[] par;
	int[] rank;
	int group;

	UnionFind(int n){
		par = new int[n];
		rank = new int[n];
		group = n;
		for(int i = 0; i < n; i++){
			par[i] = i;
			rank[i] = 0;
		}
	}
	//経路圧縮しながらrootを求める
	int find(int x){
		if(par[x] == x) return x;
		return par[x] = find(par[x]);
	}
	void unite(int x, int y){
		x = find(x);
		y = find(y);
		if(x == y) return;
		group--;
		if(rank[x] > rank[y]) par[x] = y;
		else{
			par[y] = x;
			if(rank[x] == rank[y]) rank[x]++;
		}
	}
	boolean same(int x, int y){
		return find(x) == find(y);
	}
}

