            if (!list.contains(s)) {
              list.add(s);
            }
            dfs(sy, sx, y + dy, x + dx, false, count + 1);
          } else if (!black && S[y + dy][x + dx] == '#') {
            dfs(sy, sx, y + dy, x + dx, true, count + 1);
