        grid = new char[H][W];
        for(int i = 0; i < H; i++) grid[i] = sc.next().toCharArray();
        sc.close();
        visited = new int[H][W];
        long ans = 0;
        for(int i = 0; i < H; i++){
            for(int j = 0; j < W; j++){
                int[] ret = new int[2];
                ret = dfs(i, j);
                ans += ret[0] * ret[1];
            }
        }
        System.out.println(ans);

    }
    private static int[] dfs(int i, int j) {
        int[] ret = new int[2];
        if(visited[i][j] == 1) return ret;
        visited[i][j] = 1;
        if(grid[i][j] == '.') ret[0]++;
        else ret[1]++;
        for(int[] d:dir){
            int ni = i +d[0];
            int nj = j +d[1];
            if(ni >=0 && ni <H && nj >=0 && nj <W){
                if(visited[ni][nj] == 0 && grid[ni][nj] != grid[i][j]){
                    int[] ret2 = dfs(ni, nj);
                    ret[0] += ret2[0];
                    ret[1] += ret2[1];
                }
            }
        }

        return ret;
    }

}

