		long invFact[];
		boolean isFactPrepared = false;
		HashMap<Integer, long[]> factMap;
		void prepareFact() {
			fact = new long[MAX_FACT];
			Arrays.fill(fact, 0);
			invFact = new long[MAX_FACT];
			Arrays.fill(invFact, 0);
			fact[0] = 1;
			int maxIndex = min(MAX_FACT, (int)MOD);
			for(int i = 1; i < maxIndex; i ++) { fact[i] = mod(fact[i - 1] * i); }
			invFact[maxIndex - 1] = inv(fact[maxIndex - 1]);
			for(int i = maxIndex - 1; i > 0; i --) { invFact[i - 1] = mod(invFact[i] * i); }

			factMap = new HashMap<>();
			isFactPrepared = true;
		}

		long P(int n, int r) {
			if(!isFactPrepared) { prepareFact(); }
			if(n < 0 || r < 0 || n < r) { return 0; }
			if(n >= MAX_FACT) {
				if(!factMap.containsKey(n)) {
					long largeFact[] = new long[MAX_FACT];
					factMap.put(n, largeFact);
					fill(largeFact, -INF);
					largeFact[0] = 1;
				}
				long largeFact[] = factMap.get(n);
				int i = r;
				while(isINF(largeFact[i])) { i --; }
				for(; i < r; i ++) { largeFact[i + 1] = mod(largeFact[i] * (n - i)); }
				return largeFact[r];
			}
			return mod(fact[n] * invFact[n - r]);
		}
		long C(int n, int r) {
			if(!isFactPrepared) { prepareFact(); }
			if(n < 0 || r < 0 || n < r) { return 0; }
			return mod(P(n, r) * invFact[r]);
		}
		long H(int n, int r) { return C((n - 1) + r, r); }


		// grid
		class Grids {
			int h;
			int w;
			Grid[][] gs;
			Grids(int h, int w) {
				this.h = h;
				this.w = w;
				gs = new Grid[h][w];
				for(int i = 0; i < h; i ++) {
					for(int j = 0; j < w; j ++) {
						gs[i][j] = new Grid(i, j, h, w);
					}
				}
			}

			void init(boolean[][] b) {
				for(int i = 0; i < h; i ++) {
					for(int j = 0; j < w; j ++) {
						gs[i][j].b = b[i][j];
					}
				}
			}
			void init(long[][] val) {
				for(int i = 0; i < h; i ++) {
					for(int j = 0; j < w; j ++) {
						gs[i][j].val = val[i][j];
					}
				}
			}

			Grid get(int x, int y) { return isValid(x, y, h, w) ? gs[x][y] : null; }

			int dx[] = {0, -1, 1, 0, 0, -1, 1, -1, 1};
			int dy[] = {0, 0, 0, -1, 1, -1, -1, 1, 1};
			Grid next(int x, int y, int i) { return next(gs[x][y], i); }
			Grid next(Grid g, int i) {
				return isValid(g.x + dx[i], g.y + dy[i], g.h, g.w)
					? gs[g.x + dx[i]][g.y + dy[i]]
					: null;
			}
		}
		class Grid implements Comparable<Grid> {
			int x;
			int y;
			int h;
			int w;
			int i;
			boolean b;
			long val;

			Grid() {  }
			Grid(int x, int y, int h, int w) { init(x, y, h, w, false, 0); }
			Grid(int x, int y, int h, int w, boolean b) { init(x, y, h, w, b, 0); }
			Grid(int x, int y, int h, int w, long val) { init(x, y, h, w, false, val); }
			Grid(int x, int y, int h, int w, boolean b, long val) { init(x, y, h, w, b, val); }

			void init(int x, int y, int h, int w, boolean b, long val) {
				this.x = x;
				this.y = y;
				this.h = h;
				this.w = w;
				this.b = b;
				this.val = val;
				i = x * w + y;
			}

			@Override
			public int compareTo(Grid g) {
				return Long.compare(this.val, g.val);
			}
		}

		boolean isValid(int x, int y, int h, int w) {
			return x >= 0 && x < h && y >= 0 && y < w;
		}
		boolean isValid(Grid g) {
			return isValid(g.x, g.y, g.h, g.w);
		}

		// graph
		class Graph {
			int numNode;
			int numEdge;
			boolean directed;
			Edge edges[];
			Node nodes[];
			Node reversedNodes[];

			Graph(int numNode, int numEdge, boolean directed) {
				this.numNode = numNode;
				this.numEdge = numEdge;
				this.directed = directed;
				nodes = new Node[numNode];
				reversedNodes = new Node[numNode];
				for(int i = 0; i < numNode; i ++) {
					nodes[i] = new Node(i);
					reversedNodes[i] = new Node(i);
				}
			}

			void init(Edge[] edges) {
				this.edges = edges;
				for(Edge edge : edges) {
					nodes[edge.source].add(edge.target, edge.cost);
					if(directed) {
						reversedNodes[edge.target].add(edge.source, edge.cost);
					}else {
						nodes[edge.target].add(edge.source, edge.cost);
					}
				}
			}

			void clearNodes() {
				for(Node n : nodes) { n.clear(); }
				for(Node n : reversedNodes) { n.clear(); }
			}
		}

		class Node extends ArrayList<Edge> {
			int id;

			Node(int id) {
				this.id = id;
			}
			void add(int target, long cost) {
				add(new Edge(id, target, cost));
			}
		}

		class Edge implements Comparable<Edge> {
			int source;
			int target;
			long cost;
			Edge(int source, int target, long cost) {
				this.source = source;
				this.target = target;
				this.cost = cost;
			}

			@Override
			public int compareTo(Edge e) {
				return Long.compare(this.cost, e.cost);
			}
		}

public void solve() {
	int h = ni();
	int w = ni();
	boolean b[][] = nb(h, w, '#');
	Grids g = new Grids(h, w);
	g.init(b);
	UnionFind uf = new UnionFind(h * w);
	for(int i = 0; i < h; i ++) {
		for(int j = 0; j < w; j ++) {
			Grid crt = g.get(i, j);
			for(int k = 1; k <= 4; k ++) {
				Grid next = g.next(i, j, k);
				if(next != null && next.b != crt.b) {
					uf.unite(crt.i, next.i);
				}
			}
		}
	}
	long cnt[][] = new long[h * w][2];
	for(int i = 0; i < h; i ++) {
		for(int j = 0; j < w; j ++) {
			Grid crt = g.get(i, j);
			cnt[uf.root(crt.i)][crt.b ? 0 : 1] ++;
		}
	}
	long ans = 0;
	for(int i = 0; i < h * w; i ++) {
		ans += cnt[i][0] * cnt[i][1];
	}
	prtln(ans);
}

class UnionFind {
	int parent[];
	int size[];

	public UnionFind(int num) {
		parent = new int[num];
		size = new int[num];
		for(int i = 0; i < num; i ++) {
			initNode(i);
		}
	}

	public void initNode(int i) {
		parent[i] = i;
		size[i] = 1;
	}

	public void unite(int x, int y) {
		int xRoot = root(x);
		int yRoot = root(y);
		if(xRoot == yRoot) { return; }
		if(size[yRoot] > size[xRoot]) {
			parent[xRoot] = yRoot;
			size[yRoot] += size[xRoot];
		}else {
			parent[yRoot] = xRoot;
			size[xRoot] += size[yRoot];
		}
	}

	public int size(int i) {
		return size[root(i)];
	}

	public int root(int i) {
		if(i != parent[i]) {
			parent[i] = root(parent[i]);
		}
		return parent[i];
	}

	public boolean same(int x, int y) {
		return root(x) == root(y);
	}
}

	}
}

import java.io.IOException;
import java.io.InputStream;
import java.util.*;
public class Main implements Runnable {
    public static int h;
    public static int w;
    public static boolean[][] map;
    public static int[][] root;
    public static int[] inRoot;

    public static void main(String[] args)throws Exception{
        new Thread(null, new Main(), "", 16 * 1024 * 1024).start();
    }
    public void run() {
        FastScanner sc = new FastScanner();

        inRoot = new int[16000];

        w = sc.nextInt();
        h = sc.nextInt();

        map = new boolean[w][h];

        for(int i = 0;i < w;i ++){ //map を　格納
            String temp = sc.next();
            for(int j = 0;j < h;j ++){
                map[i][j] = temp.charAt(j)=='#';
            }
        }


        root = new int[w][h];
        int rootcount = 1;

        for(int i = 0;i < w;i ++){
            for(int j = 0;j < h;j ++){
                if(root[i][j] != 0){
                    continue;
                }
                root[i][j] = rootcount;
                rootCheck(i,j);
                rootcount++;

            }
        }

//
//        for(int i = 0;i < w;i++){//現在の2次元配列表示プログラム
//            for(int j = 0;j < h;j++) {
//                System.out.print(root[i][j] + " ");
//                if (j == h - 1)
//                    System.out.println("");
//            }
//        }

        int ans =0;
        for(int i = 0;i < rootcount;i ++){
            int black = 0;
            int white = 0;
            if(inRoot[i] == 0){
                continue;
            }
            for(int j = 0;j < w;j ++){
                for(int k = 0;k < h;k ++){

                    if (root[j][k] == i){
                        if(map[j][k]){
                            black ++;
                        }else{
                            white ++;
                        }
                    }

                }
            }
            ans += black * white;
        }

        System.out.println(ans);



    }
    static void rootCheck(int i,int j){
        //上
        if(i != 0) {
            if (root[i - 1][j] == 0 && (map[i][j] != map[i-1][j])){
                root[i - 1][j] = root[i][j];
                inRoot[root[i][j]] ++;
                rootCheck(i-1,j);
            }
        }
        //右
        if(j != h-1) {
            if (root[i][j + 1] == 0 && (map[i][j] != map[i][j + 1])){
                root[i][j + 1] = root[i][j];
                inRoot[root[i][j]] ++;
                rootCheck(i,j+1);
            }
        }
        //下
        if(i != w-1) {
            if (root[i + 1][j] == 0 && (map[i][j] != map[i + 1][j])){
                root[i + 1][j] = root[i][j];
                inRoot[root[i][j]] ++;
                rootCheck(i + 1,j);
            }
        }
        //左
        if(j != 0) {
            if (root[i][j - 1] == 0 && (map[i][j] != map[i][j - 1])){
                root[i][j - 1] = root[i][j];
                inRoot[root[i][j]] ++;
                rootCheck(i,j-1);
            }
        }
    }
}

class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte() {
        if (ptr < buflen) {
            return true;
        }else{
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }
    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }else if(b == -1 || !isPrintableChar(b)){
                return minus ? -n : n;
            }else{
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
}

import java.awt.Point;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Queue;
import java.util.Scanner;

public class Main {
	static int ans = 0;
	static int[] dw = {1,0,-1,0};
    static int[] dh = {0,1,0,-1};
    static Queue<Point> queue = new ArrayDeque<>();
    static ArrayList<String> Sh = new ArrayList<>(450);
    static int H;
    static int W;
    static int reachedB;
    static int[][] reached = new int[500][500];
    static int[][] reachedBlack = new int[500][500];
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        for(int i=0;i<H;i++) {
        	Sh.add(sc.next());
        }


        for(int i=0;i<W;i++) {
        	for(int j=0;j<H;j++) {
        		if(Sh.get(j).charAt(i) == '#' && reachedBlack[j][i] ==0) {
        			queue.offer(new Point(j,i));
        			reachedB=0;
        			for(int a=0;a<H;a++) {
        				Arrays.fill(reached[a], 0);
        			}
        			bfs();
//        			System.out.println("bbbb  " + queue.poll());
        		}
        	}
        }

        System.out.println(ans);

        sc.close();
    }

    public static void bfs() {
//    	System.out.println("BFS!!  " + queue.peek());
    	while(queue.peek()!=null) {
	    	Point p = queue.poll();
	    	if(p == null) {
	    		return;
	    	}
//	    	System.out.println("(" + p.x + "," + p.y + ")"  + " = " + Sh.get(p.x).charAt(p.y));
	    	if(Sh.get(p.x).charAt(p.y)=='#') {
	    		for(int k=0;k<4;k++) {
	    			if(p.x+dh[k] > H-1 || p.x+dh[k] < 0 || p.y+dw[k] > W-1 || p.y+dw[k] <0) {
	    				continue;
	    			}
	    			if(reached[p.x+dh[k]][p.y+dw[k]] == reachedB) continue;
					if(Sh.get(p.x+dh[k]).charAt(p.y+dw[k]) == '.') {
						queue.offer(new Point(p.x+dh[k],p.y+dw[k]));
						ans+= (reachedB - reached[p.x+dh[k]][p.y+dw[k]]);	
						reached[p.x+dh[k]][p.y+dw[k]] ++;
						reachedBlack[p.x+dh[k]][p.y+dw[k]]++;
					}
				}
	    	}else {
	    		for(int k=0;k<4;k++) {
	    			if(p.x+dh[k] > H-1 || p.x+dh[k] < 0 || p.y+dw[k] > W-1 || p.y+dw[k] <0) {
	    				continue;
	    			}
	    			if(reached[p.x+dh[k]][p.y+dw[k]] > 0) continue;
					if(Sh.get(p.x+dh[k]).charAt(p.y+dw[k]) == '#') {
						queue.offer(new Point(p.x+dh[k],p.y+dw[k]));
					}
				}
	    	}
	    	bfs();
    	}

    }
}

import java.io.*;
import java.util.*;
import static java.lang.System.out;

public class Main {
    static MyReader in = new MyReader();

    public static void main(String[] args) {
        int H = in.i();
        int W = in.i();
        char[] S = new char[H * W];
        for (int i = 0; i < S.length; i++) {
            char c;
            do {
                c = in.next();
            } while (c != '.' && c != '#');
            S[i] = c;
        }

        int[] dp = new int[H * W];
        int[] par = new int[H * W];
        IntStack stack = new IntStack(H * W);
        boolean[] visited = new boolean[H * W];
        int[][] dir = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        IntStack blacks = new IntStack(S.length);
        for (int i = 0; i < S.length; i++) {
            if (S[i] == '#') {
                blacks.push(i);
            }
        }

        long ans = 0;
        while (!blacks.isEmpty()) {
            int code = blacks.pop();

            if (par[code] > 0) {
                ans += dp[par[code] - 1];
                continue;
            }

            stack.push(code);
            visited[code] = true;
            while (!stack.isEmpty()) {
                int hw = stack.pop();
                int h = hw / W;
                int w = hw % W;
                for (int k = 0; k < 4; k++) {
                    int h2 = h + dir[k][0];
                    int w2 = w + dir[k][1];

                    int code2 = h2 * W + w2;
                    if (0 <= h2 && h2 < H && 0 <= w2 && w2 < W && S[hw] != S[code2] && !visited[code2]) {
                        stack.push(code2);
                        if (S[code2] == '.') {
                            dp[code]++;
                        } else {
                            par[code2] = code + 1;
                        }
                        visited[code2] = true;
                    }
                }
            }
            ans += dp[code];
        }

        out.println(ans);
    }
}

class IntStack {
    final int MAX;
    int[] array;
    int head = 0;

    IntStack(int N) {
        MAX = N;
        array = new int[N];
    }

    void push(int n) {
        array[head++] = n;
    }

    int pop() {
        return array[--head];
    }

    boolean isEmpty() {
        return head == 0;
    }
}

class MyReader extends BufferedReader {
    char[] cbuf = new char[1024];
    int head = 0;
    int tail = 0;

    MyReader() {
        super(new InputStreamReader(System.in));
    }

    char next() {
        if (head == tail) {
            try {
                tail = super.read(cbuf, 0, cbuf.length);
            } catch (IOException e) {
                e.printStackTrace();
            }
            head = 0;
        }
        return cbuf[head++];
    }

    void back() {
        head--;
    }

    boolean minus() {
        boolean minus;
        while (true) {
            char c = next();
            if (!isDelimiter(c)) {
                if (!(minus = c == '-')) back();
                return minus;
            }
        }
    }

    void skip() {
        while (isDelimiter(next()));
        back();
    }

    char[] s(int N) {
        char[] cbuf = new char[N];
        read(cbuf, 0, N);
        return cbuf;
    }

    public int read(char[] cbuf, int off, int len) {
        skip();
        int i;
        for (i = 0; i < cbuf.length; i++) {
            char c = next();
            if (isDelimiter(c)) {
                break;
            }
            cbuf[i] = c;
        }
        return i;
    }

    boolean isDelimiter(char c) {
        return c == ' ' || c == '\n' || c == '\r';
    }

    int i() {
        boolean minus = minus();
        int n = 0;
        while (true) {
            int k = next() - '0';
            if (k < 0 || 9 < k) break;
            n = 10 * n + k;
        }
        return minus ? -n : n;
    }

    int[] ii(final int N) {
        int[] a = new int[N];
        for (int j = 0; j < a.length; j++) a[j] = i();
        return a;
    }

    long l() {
        boolean minus = minus();
        long n = 0;
        while (true) {
            int k = next() - '0';
            if (k < 0 || 9 < k) break;
            n = 10 * n + k;
        }
        return minus ? -n : n;
    }
}

