	boolean systemIO = true;

	public class Fraction implements Comparable<Fraction> {
		long x;
		long y;

		public Fraction(long x, long y) {
			this.x = x;
			this.y = y;
		}

		public void norm() {
			long gcd = gcd(x, y);
			x /= gcd;
			y /= gcd;
		}

		@Override
		public int compareTo(Fraction o) {
			if (x > o.x) {
				return 1;
			}
			if (x < o.x) {
				return -1;
			}
			if (y > o.y) {
				return 1;
			}
			if (y < o.y) {
				return -1;
			}
			return 0;
		}
	}

	public Fraction sum(Fraction a, Fraction b) {
		Fraction c = new Fraction(a.x * b.y + a.y * b.x, a.y * b.y);
		c.norm();
		return c;
	}

	public long gcd(long x, long y) {
		if (y == 0) {
			return x;
		}
		if (x == 0) {
			return y;
		}
		return gcd(y, x % y);
	}

	public class Pair implements Comparable<Pair> {
		long x;
		long y;

		public Pair(long x, long y) {
			this.x = x;
			this.y = y;
		}

		public void add(Pair p) {
			x += p.x;
			y += p.y;
		}

		@Override
		public int compareTo(Pair o) {
//			if (x != o.x) {
//				return x - o.x;
//			}
//			return y - o.y;
			return 0;
		}
	}

	public boolean check(int h, int w) {
		return h >= 0 && w >= 0 && h < field.length && w < field[0].length && !used[h][w];
	}

	public Pair dfs(int h, int w) {
		used[h][w] = true;
		Pair ans = new Pair(0, 0);
		if (field[h][w]) {
			ans.x++;
		} else {
			ans.y++;
		}
		if (check(h + 1, w) && (field[h + 1][w] ^ field[h][w])) {
			ans.add(dfs(h + 1, w));
		}
		if (check(h - 1, w) && (field[h - 1][w] ^ field[h][w])) {
			ans.add(dfs(h - 1, w));
		}
		if (check(h, w + 1) && (field[h][w + 1] ^ field[h][w])) {
			ans.add(dfs(h, w + 1));
		}
		if (check(h, w - 1) && (field[h][w - 1] ^ field[h][w])) {
			ans.add(dfs(h, w - 1));
		}
		return ans;
	}

	boolean[][] field;
	boolean[][] used;

	public void solve() {
		int h = in.nextInt();
		int w = in.nextInt();
		field = new boolean[h][w];
		used = new boolean[h][w];
		for (int i = 0; i < field.length; i++) {
			String s = in.next();
			for (int j = 0; j < s.length(); j++) {
				field[i][j] = s.charAt(j) == '#';
			}
		}
		long ans = 0;
		for (int i = 0; i < field.length; i++) {
			for (int j = 0; j < field[0].length; j++) {
				if (!used[i][j]) {
					Pair p = dfs(i, j);
					ans += p.x * p.y;
				}
			}
		}
		out.println(ans);
	}

	public void run() {
		try {
			if (systemIO) {
				in = new FastScanner(System.in);
				out = new PrintWriter(System.out);
			} else {
				in = new FastScanner(new File("input.txt"));
				out = new PrintWriter(new File("output.txt"));
			}
			solve();

			out.close();
		} catch (IOException e) {
			e.printStackTrace();
		}
	}

	class FastScanner {
		BufferedReader br;
