	}
}

import java.io.*;
import java.util.*;
import static java.lang.System.out;

public class Main {
    static MyReader in = new MyReader();

    public static void main(String[] args) {
        int H = in.i();
        int W = in.i();
        char[][] S = new char[H][];
        for (int i = 0; i < H; i++) {
            S[i] = in.s(W);
        }

        int[] dp = new int[H * W];
        UnionFind uf = new UnionFind(H * W);
        IntStack stack = new IntStack(H * W);
        boolean[][] visited = new boolean[H][W];
        int[][] dir = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        long ans = 0;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (S[i][j] == '.') continue;

                int code = i * W + j;
                if (!uf.isRoot(code)) {
                    ans += dp[uf.root(code)];
                    continue;
                }

                stack.push(code);
                visited[i][j] = true;
                while (!stack.isEmpty()) {
                    int hw = stack.pop();
                    int h = hw / W;
                    int w = hw % W;
                    for (int k = 0; k < 4; k++) {
                        int h2 = h + dir[k][0];
                        int w2 = w + dir[k][1];

                        if (0 <= h2 && h2 < H && 0 <= w2 && w2 < W && S[h][w] != S[h2][w2] && !visited[h2][w2]) {
                            int code2 = h2 * W + w2;
                            stack.push(code2);
                            if (S[h2][w2] == '.') {
                                dp[code]++;
                            } else {
                                uf.unite(code, code2);
                            }
                            visited[h2][w2] = true;
                        }
                    }
                }
                ans += dp[code];
            }
        }

        out.println(ans);
    }
}

class UnionFind {
    private final int N;
    int[] parent;
    int[] rank;
    int[] size;

    UnionFind(int n) {
        N = n;
        parent = new int[N];
        Arrays.setAll(parent, i -> i);
        size = new int[N];
        Arrays.fill(size, 1);
        rank = new int[N];
    }

    boolean isRoot(int x) {
        return x == parent[x];
    }

    int root(int x) {
        return isRoot(x) ? x : (parent[x] = root(parent[x]));
    }

    boolean same(int x, int y){
        return root(x) == root(y);
    }

    int size(int x) {
        return size[root(x)];
    }

    void unite(int x, int y){
        x = root(x);
        y = root(y);
        if (x != y) {
            if (rank[x] < rank[y]) {
                parent[x] = y;
                size[y] += size[x];
            } else {
                parent[y] = x;
                size[x] += size[y];
                if (rank[x] == rank[y]) {
                    rank[x]++;
                }
            }
        }
    }
}

class IntStack {
    final int MAX;
    int[] array;
    int head = 0;

    IntStack(int N) {
        MAX = N;
        array = new int[N];
    }

    void push(int n) {
        array[head++] = n;
    }

     int pop() {
        return array[--head];
    }

    boolean isEmpty() {
        return head == 0;
    }
}

class MyReader extends BufferedReader {
    char[] cbuf = new char[1024];
    int head = 0;
    int tail = 0;

    MyReader() {
        super(new InputStreamReader(System.in));
    }

    char next() {
        if (head == tail) {
            try {
                tail = super.read(cbuf, 0, cbuf.length);
            } catch (IOException e) {
                e.printStackTrace();
            }
            head = 0;
        }
        return cbuf[head++];
    }

    void back() {
        head--;
    }

    boolean minus() {
        boolean minus;
        while (true) {
            char c = next();
            if (!isDelimiter(c)) {
                if (!(minus = c == '-')) back();
                return minus;
            }
        }
    }

    void skip() {
        while (isDelimiter(next()));
        back();
    }

    char[] s(int N) {
        char[] cbuf = new char[N];
        read(cbuf, 0, N);
        return cbuf;
    }

    public int read(char[] cbuf, int off, int len) {
        skip();
        int i;
        for (i = 0; i < cbuf.length; i++) {
            char c = next();
            if (isDelimiter(c)) {
                break;
            }
            cbuf[i] = c;
        }
        return i;
    }

    boolean isDelimiter(char c) {
        return c == ' ' || c == '\n' || c == '\r';
    }

    int i() {
        boolean minus = minus();
        int n = 0;
        while (true) {
            int k = next() - '0';
            if (k < 0 || 9 < k) break;
            n = 10 * n + k;
        }
        return minus ? -n : n;
    }

    int[] ii(final int N) {
        int[] a = new int[N];
        for (int j = 0; j < a.length; j++) a[j] = i();
        return a;
    }

    long l() {
        boolean minus = minus();
        long n = 0;
        while (true) {
            int k = next() - '0';
            if (k < 0 || 9 < k) break;
            n = 10 * n + k;
        }
        return minus ? -n : n;
    }
}

import java.util.*;

public class Main {
    static int h, w;
    static int[][] map;
    static boolean[][] bmap;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        h = sc.nextInt();
        w = sc.nextInt();
        map = new int[h+2][w+2];
        bmap = new boolean[h+2][w+2];
        for(int i=0; i<h; i++){
            String s = sc.next();
            for(int j=0; j<w; j++){
                if(s.charAt(j) == '#'){
                    map[i+1][j+1] = 1;
                }else{
                    map[i+1][j+1] = -1;
                }
            }
        }
        sc.close();

        int ans = 0;
        for(int i=0; i<h; i++){
            for(int j=0; j<w; j++){
                if(map[i+1][j+1] == 1){
                    bmap = new boolean[h+2][w+2]; 
                    ans += bfs(i+1, j+1, map[i+1][j+1]);
                    // ans += cont * (cont-1) * 2;
                }
            }
        }

        System.out.println(ans);
    }

    public static int bfs(int x, int y, int now){
        int next = -now;
        int ret = map[x][y] == -1 ? 1 : 0;
        bmap[x][y] = true;
        if(!bmap[x+1][y] && map[x+1][y] == next) ret += bfs(x+1, y, next);
        if(!bmap[x-1][y] && map[x-1][y] == next) ret += bfs(x-1, y, next);
        if(!bmap[x][y+1] && map[x][y+1] == next) ret += bfs(x, y+1, next);
        if(!bmap[x][y-1] && map[x][y-1] == next) ret += bfs(x, y-1, next);
        return ret;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {

    private int H;
    private int W;

    public static void main(String[] args) {
        try (CustomReader in = new CustomReader()) {
            new Main().execute(in);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void execute(CustomReader in) throws IOException {
        int[] hw = in.readLineAsIntArray();
        H = hw[0];
        W = hw[1];
        final int SZ = H * W;

        char[][] field = new char[H][];
        int[] parent = new int[H * W];

        for (int i = 0; i < H; i++) {
            field[i] = in.readLine().toCharArray();
        }

        Arrays.fill(parent, -1);

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                int cellId = id(i, j);
                if (parent[cellId] == -1) {
                    dfs(i, j, field, cellId, parent);
                }
            }
        }

        int[] countBlack = new int[SZ];
        int[] countWhite = new int[SZ];

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                int cellId = parent[id(i, j)];
                if (field[i][j] == '#') {
                    countBlack[cellId]++;
                } else {
                    countWhite[cellId]++;
                }
            }
        }

        long totalCount = 0L;
        for (int i = 0; i < SZ; i++) {
            totalCount += countBlack[i] * countWhite[i];
        }
        System.out.println(totalCount);

    }

    private void dfs(int h, int w, char[][] field, int root, int[] parents) {
        if (parents[id(h, w)] != -1) {
            return;
        }
        parents[id(h, w)] = root;

        if (h - 1 > 0 && field[h][w] != field[h - 1][w]) {
            dfs(h - 1, w, field, root, parents);
        }

        if (w - 1 > 0 && field[h][w] != field[h][w - 1]) {
            dfs(h, w - 1, field, root, parents);
        }

        if (h + 1 < H && field[h][w] != field[h + 1][w]) {
            dfs(h + 1, w, field, root, parents);
        }

        if (w + 1 < W && field[h][w] != field[h][w + 1]) {
            dfs(h, w + 1, field, root, parents);
        }
    }

    private int id(int h, int w) {
        return h * W + w;
    }

    static class CustomReader extends BufferedReader {

        //private static final int DEFAULT_BUF_SIZE = 2048;
        // private static final int DEFAULT_BUF_SIZE = 4096;
         private static final int DEFAULT_BUF_SIZE = 8192;
        //private static final int DEFAULT_BUF_SIZE = 16384;
        // private static final int DEFAULT_BUF_SIZE = 1048576;

        public CustomReader() throws IOException {
            super(new InputStreamReader(System.in), DEFAULT_BUF_SIZE);
        }

        public int[] readLineAsIntArray() throws IOException {
            String[] strArray = this.readLine().split(" ");
            int[] intArray = new int[strArray.length];
            for (int i = 0, n = strArray.length; i < n; i++) {
                intArray[i] = Integer.parseInt(strArray[i]);
            }
            return intArray;
        }

        public int[][] readAsIntMatrix(int rows, int columns) throws IOException {
            int[][] matrix = new int[rows][columns];
            for (int i = 0; i < rows; i++) {
                String[] r = this.readLine().split(" ");
                for (int j = 0; j < columns; j++) {
                    matrix[i][j] = Integer.parseInt(r[j]);
                }
            }
            return matrix;
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Main main = new Main();
        main.solve();
    }
    public void solve() {
        Scanner scan = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int H = scan.nextInt();
        int W = scan.nextInt();
        char[][] map = new char[H][W];
        for (int i = 0; i < H; i++) {
            String s = scan.next();
            map[i] = s.toCharArray();
        }
        UnionFind union = new UnionFind(H, W, map);
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (j + 1 < W && is_connect(map, i, j, i, j+1)) {
                    union.unite(i * W + j, i * W + j + 1);
                }
                if (i + 1 < H && is_connect(map, i, j, i+1, j)) {
                    union.unite(i * W + j, (i + 1) * W + j);
                }
            }
        }
        long answer = 0;
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (map[i][j] == '#') {
                    answer += union.white(i * W + j);
                }
            }
        }
        System.out.println(answer);
    }
    private boolean is_connect(char[][] map, int x1, int y1, int x2, int y2) {
        if (map[x1][y1] == '#' && map[x2][y2] == '.') {
            return true;
        }
        return map[x1][y1] == '.' && map[x2][y2] == '#';
    }
    class UnionFind {
        private int H;
        private int W;
        private char[][] map;
        private int[] size;
        private int[] parent;
        private int[] white;
        UnionFind(int H, int W, char[][] map) {
            this.H = H;
            this.W = W;
            int N = H * W;
            this.map = map;
            this.size = new int[N];
            Arrays.fill(this.size, 0);
            this.parent = new int[N];
            for (int i = 0; i < N; i++) {
                this.parent[i] = i;
            }
            this.white = new int[N];
            Arrays.fill(this.white, 0);
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (map[i][j] == '.') {
                        this.white[i * W + j] = 1;
                    }
                }
            }
        }
        int white(int i) {
            int x = find(i);
            return this.white[x];
        }
        int find(int i) {
            if (this.parent[i] == i) {
                return i;
            }
            return this.parent[i] = find(this.parent[i]);
        }
        boolean same(int i, int j) {
            return find(i) == find(j);
        }
        void unite(int i, int j) {
            int x = this.find(i);
            int y = this.find(j);
            if (x == y) {
                return;
            }
            if (this.size[x] < this.size[y]) {
                this.size[y] += this.size[x];
                this.white[y] += this.white[x];
                this.size[x] = 0;
                this.white[x] = 0;
                this.parent[x] = y;
                return;
            }
            this.size[x] += this.size[y];
            this.white[x] += this.white[y];
            this.size[y] = 0;
            this.white[y] = 0;
            this.parent[y] = x;
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.function.Function;

public class Main {

    static int H, W;
    static char[][] S;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        S = new char[H][];
        for (int i = 0; i < H; i++) {
            S[i] = sc.next().toCharArray();
        }

        System.out.println(solve());
    }

    static int[] DH = {0, 1, 0, -1};
    static int[] DW = {1, 0, -1, 0};

    static long solve() {
        UnionFind uf = new UnionFind(H*W);

        for (int h = 0; h < H; h++) {
            for (int w = 0; w < W; w++) {
                for (int i = 0; i < 4; i++) {
                    int nh = DH[i] + h;
                    int nw = DW[i] + w;
                    if( 0 <= nh && nh < H && 0 <= nw && nw < W && S[h][w] != S[nh][nw]) {
                        uf.unite(cord(h, w), cord(nh, nw));
                    }
                }
            }
        }

        Map<Integer, Integer> all = new HashMap<>();
        Map<Integer, Integer> white = new HashMap<>();
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                int root = uf.root(cord(i, j));
                all.put( root, all.getOrDefault(root, 0) + 1);

                if( S[i][j] == '.' ) {
                    white.put( root, white.getOrDefault(root, 0) + 1);
                }
            }
        }
        long ret = 0;
        for (Integer key : all.keySet()) {
            int a = all.get(key);
            int w = white.getOrDefault(key, 0);
            int b = a - w;
            ret += (long)w * b;
        }
        return ret;
    }

    static int cord(int h, int w) {
        return h * W + w;
    }

    static class UnionFind {

        private final int[] parent;
        private final int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }
        }

        public int root(int i) {
            if( parent[i] == i ) {
                return i;
            } else {
                return parent[i] = root(parent[i]);
            }
        }

        public void unite(int i, int j) {
            int ri = root(i);
            int rj = root(j);
            if( ri == rj ) return;

            if( rank[ri] < rank[rj] ) {
                parent[ri] = rj;

            } else {
                parent[rj] = ri;
                if( rank[ri] == rank[rj] ) {
                    rank[ri]++;
                }
            }
        }

        public boolean isSame(int a, int b) {
            return root(a) == root(b);
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
