                for (int k = 0; k < 4; k++) {
                    int x = i+dx[k], y = j+dy[k];
                    if(x>=0&&x<h&&y>=0&&y<w){
                        if(map[i][j]!=map[x][y]) uf.unite(i*w+j, x*w+y);
                    }
                }
            }
        }
        long[][] count = new long[h*w][2];
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if(map[i][j]=='.'){
                    count[uf.find(i*w+j)][0]++;
                }else{
                    count[uf.find(i*w+j)][1]++;
                }
            }
        }
        long ans = 0;
        for (int i = 0; i < h; i++) {
