					q.add(x-1);q.add(y);
					if(k=='.')
						ans++;
					key[x-1][y]=true;
				}
				if(y!=0&&key[x][y-1]==false&&A[x][y-1]==k){
					q.add(x);q.add(y-1);
					if(k=='.')
						ans++;
					key[x][y-1]=true;
				}
				if(x!=H-1&&key[x+1][y]==false&&A[x+1][y]==k){
					q.add(x+1);q.add(y);
					if(k=='.')
						ans++;
					key[x+1][y]=true;
				}
				cout++;
			}
			key=new boolean[H][W];
			cout=0;
		}
		System.out.println(ans);
	}
