        static int[] Togo;
        static bool CheckBipartite(int now, int prev, List<int>[] g, int c = 0)//0,-1が想定
        {
            if (Togo == null) Togo = Enumerable.Repeat(-1, g.Length).ToArray();
            foreach (var next in g[now])
            {
                if (next == prev) continue;
                var nextc = Togo[next];
                if (nextc >= 0 && nextc == c) return false;
                if (nextc >= 0) continue;
                Togo[next] = (c + 1) % 2;
                var res = CheckBipartite(next, now, g, (c + 1) % 2);
                if (res == false) return false;
            }
            return true;
        }
