namespace AtCoder
{
    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static int Solve(int H, int W, string[] S)
        {
            int sum = 0;
            bool[][] visited = new bool[H][];
            for (int i = 0; i < H; ++i) { visited[i] = new bool[W]; }
            for (int i = 0; i < H; ++i)
            {
                for (int j = 0; j < W; ++j)
                {
                    int white = 0;
                    int black = 0;
                    if (!visited[i][j])
                    {
                        var queue = new Queue<Tuple<int, int>>();
                        queue.Enqueue(new Tuple<int, int>(i, j));
                        visited[i][j] = true;
                        if (S[i][j] == '#') { ++black; } else { ++white; }
                        while (queue.Count > 0)
                        {
                            var p1 = queue.Dequeue();
                            int i1 = p1.Item1;
                            int j1 = p1.Item2;
                            foreach (var p2 in new[] { new Tuple<int, int>(i1 - 1, j1),
                                                       new Tuple<int, int>(i1 + 1, j1),
                                                       new Tuple<int, int>(i1, j1 - 1),
                                                       new Tuple<int, int>(i1, j1 + 1) })
                            {
                                int i2 = p2.Item1;
                                int j2 = p2.Item2;
                                if (0 <= i2 && i2 < H && 0 <= j2 && j2 < W && !visited[i2][j2] && S[i1][j1] != S[i2][j2])
                                {
                                    queue.Enqueue(p2);
                                    visited[i2][j2] = true;
                                    if (S[i2][j2] == '#') { ++black; } else { ++white; }
                                }
                            }
                        }
                    }
                    sum += black * white;
                }
            }
            return sum;
        }

        static void Main(string[] args)
        {
            int[] V = ReadInts();
            int H = V[0], W = V[1];
            var S = new string[H];
            for (int i = 0; i < H; ++i) { S[i] = Read(); }
            Console.WriteLine(Solve(H, W, S));
        }
    }
}

