    /// <summary>
    /// UnionFind
    /// </summary>
    class UnionFind
    {
        int[] par;
        int[] rank;
        int[] count;

        public UnionFind(int n)
        {
            Init(n);
        }

        void Init(int n)
        {
            par = new int[n];
            rank = new int[n];
            count = new int[n].Select(x => 1).ToArray();

            for (int i = 0; i < n; i++)
            {
                par[i] = i;
            }
        }

        public int Find(int x)
        {
            if (par[x] == x)
            {
                return x;
            }
            else
            {
                return par[x] = Find(par[x]);
            }
        }

        public bool Unite(int x, int y)
        {
            x = Find(x);
            y = Find(y);
            if (x == y) return false; //すでに要素を追加済みの場合、falseを返す。

            if (rank[x] < rank[y])
            {
                par[x] = y;
                count[y] += count[x];
            }
            else
            {
                par[y] = x;
                count[x] += count[y];
                if (rank[x] == rank[y]) rank[x]++;
            }
            return true;
        }
        public bool Same(int x, int y)
        {
            return Find(x) == Find(y);
        }

        public int Size(int x)
        {
            return count[Find(x)];
        }
    }
