namespace AISC
{
    static class MainClass
    {
        static string[] bw;
        static bool[,] hist;
        static int[] s;
        static int blk = 0, wht = 0;


        public static void Main(string[] args)
        {

            s = Array.ConvertAll(Console.ReadLine().Split().ToArray(), int.Parse);
            bw = new string[s[0]];

            for(int i = 0; i < s[0]; i++)
            {
                bw[i] = Console.ReadLine();
            }
            hist = new bool[s[0],s[1]];

            int ans = 0;

            for(int j = 0; j < s[0]; j++)
            {
                for(int k = 0; k < s[1]; k++)
                {
                    Dfs(j, k);
                    ans += blk * wht;
                    blk = 0;
                    wht = 0;
                }
            }

            Console.WriteLine(ans);
            return;




        }

        public class IntArrComparer : IEqualityComparer<int[]>
        {
            public bool Equals(int[] l, int[] r)
            {
                if (l[0] == r[0] && l[1] == r[1])
                {
                    return true;
                }
                else
                {
                    return false;
                }
            }

            public int GetHashCode(int[] arr)
            {
                int hcode = arr[0] * arr[1];
                return hcode;
            }
        }





        public static void Dfs(int h, int w)
        {


            hist[h, w] = true;
            if (bw[h][w] == '#')
            {
                blk++;

            }
            else
            {
                wht++;

            }

            int[] dh = new int[4] { -1, 0, 1, 0 };
            int[] dw = new int[4] { 0, 1, 0, -1 };

            for (int i = 0; i < 4; i++)
            {
                int dsth = h + dh[i];
                int dstw = w + dw[i];
                if (dsth >= 0 && dsth <= s[0] - 1 && dstw >= 0 && dstw <= s[1] - 1)
                {

                    if (bw[h][w] != bw[dsth][dstw]&&!hist[dsth,dstw]) {
                        Dfs(dsth, dstw); 
                    }
                }
            }

        }

        public static long Gcd(long a, long b)
        {
            long tmp;
            // a<bにする
            if (a >= b)
            {
                tmp = a;
                a = b;
                b = tmp;
            }

            if (a == 0)
            {
                return b;
            }

            tmp = a;
            a = b % a;
            b = tmp;
            return Gcd(a, b);

        }


        public static IEnumerable<long> PF(long n)
        {
            long i = 2;
            long tmp = n;

            while (i * i <= n) //※1
            {
                if (tmp % i == 0)
                {
                    tmp /= i;
                    yield return i;
                }
                else
                {
                    i++;
                }
            }
            if (tmp != 1) yield return tmp;//最後の素数も返す
        }




    }

}

