namespace MyConsoleAppAlternatingPath1112AC
{
    //
    // AlternatingPath 11.txt  12.txtがACだったプログラムを改良
    // 03,04,10,11,12 AC
    // 01,02,05～09 TLE
    //
    // 構造体
    //
    public struct StartGoal
    {
        public short startpoint_X;
        public short startpoint_Y;
        public short goalpoint_X;
        public short goalpoint_Y;
    }
    class Program
    {
        static char[,] Board;
        static char[,] CheckS;

        static StartGoal sg;

        static List<StartGoal> ls1 = new List<StartGoal>();
        static List<StartGoal> ls2 = new List<StartGoal>();
        static List<StartGoal> ls3 = new List<StartGoal>();

        static void Main(string[] args)
        {
            //
            // 入力
            //
            // スペース区切りの整数の入力
            string[] input = Console.ReadLine().Split(' ');
            short h = short.Parse(input[0]); //高さＨ
            short w = short.Parse(input[1]); //幅Ｗ

            Board = new char[h, w];//２次元配列を準備しておく
            CheckS = new char[h, w];//到達した場所に印を付けておく

            string[] str = new string[h];//マスのデータを受け取る。行数分繰り返す
            // 文字列の入力
            for (int i = 0; i < str.Length; i++)
            {
                str[i] = Console.ReadLine();// 一行分のデータを受け取る
            }
            //
            // ここからプログラム本体
            //
            for (short j = 0; j < h; j++)// 配列の初期化と読み込んだデータのセット
            {
                for (short k = 0; k < w; k++)
                {
                    Board[j, k] = str[j][k];
                    CheckS[j, k] = '?';
                }
            }
            //
            // "#"の位置から"."を探索してみる。見つけた"."の場所には印Gを付ける
            //

            ls1.Clear();// LISTを空にしておいて

            for (short j = 0; j < h; j++)
            {
                for (short k = 0; k < w; k++)
                {
                    if (Board[j, k] == '#')
                    {
                        Surrounding(j, k, h, w);// 周囲を探索するメソッドSurroundingを呼ぶ
                    }
                }
            }
            //
            // 変化がなくなるまでCombineを繰り返す
            //
            int tmp;
            do
            {
                tmp = ls3.Count;
                Combine(h, w);
                ls1.Clear();
                ls1.AddRange(ls3);
            } while (tmp != ls3.Count);
            //
            // 出力
            //
            /*
            foreach (StartGoal element in ls3){
                Console.WriteLine("ls2:{0}, {1}, {2}, {3}",element.startpoint_X,element.startpoint_X,element.goalpoint_X,element.goalpoint_X);
            }
            */
            Console.WriteLine(ls3.Count);
        }
        //
        // Main終わり
        //

        //
        // メソッド　Combine つながるデータはつなげる　#. →　#.#.にできないか調べるメソッド
        //
        public static void Combine(short hh, short ww)
        {
            short temp_X = 0;
            short temp_Y = 0;
            ls2.Clear();
            ls3.Clear();

            for (short p = 0; p < ls1.Count; p++)
            {
                temp_X = ls1[p].goalpoint_X;
                temp_Y = ls1[p].goalpoint_Y;

                if ((ls1[p].goalpoint_X > 0) && (ls1[p].goalpoint_X - 1 != ls1[p].startpoint_X))
                {
                    SetNodeLs2(p, (short)(temp_X-1), temp_Y);
                }
                if ((ls1[p].goalpoint_Y > 0) && (ls1[p].goalpoint_Y - 1 != ls1[p].startpoint_Y))
                {
                    SetNodeLs2(p, temp_X, (short)(temp_Y-1));
                }
                if ((ls1[p].goalpoint_X < (hh - 1)) && (ls1[p].goalpoint_X + 1 != ls1[p].startpoint_X))
                {
                    SetNodeLs2(p, (short)(temp_X+1), temp_Y);
                }
                if ((ls1[p].goalpoint_Y < (ww - 1)) && (ls1[p].goalpoint_Y + 1 != ls1[p].startpoint_Y))
                {
                    SetNodeLs2(p, temp_X,(short)(temp_Y+1));
                }
            }
            //
            // 確認
            //
            //Console.WriteLine("-----lsとls2を連結した後-----");
            ls1.AddRange(ls2);
            ls3 = ls1.Distinct().ToList();// 同じものを削除する
        }
        // メソッド　新たなノードをリストls2に書き込む
        public static void SetNodeLs2(short startNode, short temp_X, short temp_Y)
        {
            for (short j = 0; j < ls1.Count; j++)
            {
                if ((ls1[j].startpoint_X == temp_X) && (ls1[j].startpoint_Y == temp_Y))
                {
                    if ((ls1[j].goalpoint_X != ls1[startNode].goalpoint_X) || (ls1[j].goalpoint_Y != ls1[startNode].goalpoint_Y))
                    {
                        //Console.WriteLine(p.ToString()+"と"+q.ToString()+"を連結しましょう１");
                        //StartGoal sg = new StartGoal();
                        sg.startpoint_X = ls1[startNode].startpoint_X;
                        sg.startpoint_Y = ls1[startNode].startpoint_Y;
                        sg.goalpoint_X = ls1[j].goalpoint_X;
                        sg.goalpoint_Y = ls1[j].goalpoint_Y;
                        ls2.Add(sg);
                    }
                }
            }
        }
        //
        // メソッド　座標の前後左右を調べる
        // スタート地点　Ｓ
        // ゴール地点　Ｇ
        // Ｓ→Ｇのペアを調べてリストに登録する
        //
        public static void Surrounding(short j_pos, short k_pos, short hh, short ww)
        {
            char str1 = '.';
            char str2 = 'G';//たどりついた場所に印をつけるスタート地点Ｓ、ゴール地点Ｇ
            //
            CheckS[j_pos, k_pos] = 'S';// スタート地点にＳをつける
                                       //
            if ((j_pos > 0) && (Board[j_pos - 1, k_pos] == str1))// Boardの中身が'.'だったら
            {
                CheckS[j_pos - 1, k_pos] = str2;// Gをセットする
                SetNodeLs1(j_pos, k_pos, (short)(j_pos - 1), k_pos);// リストlsに追加する
            }
            if ((j_pos < (hh - 1)) && (Board[j_pos + 1, k_pos] == str1))
            {
                CheckS[j_pos + 1, k_pos] = str2;// Gをセットする
                SetNodeLs1(j_pos, k_pos, (short)(j_pos +1), k_pos);
            }
            if ((k_pos > 0) && (Board[j_pos, k_pos - 1] == str1))
            {
                CheckS[j_pos, k_pos - 1] = str2;// Gをセットする
                SetNodeLs1(j_pos, k_pos, j_pos, (short)(k_pos-1));
            }
            if ((k_pos < (ww - 1)) && (Board[j_pos, k_pos + 1] == str1))
            {
                CheckS[j_pos, k_pos + 1] = str2;// Gをセットする
                SetNodeLs1(j_pos, k_pos, j_pos, (short)(k_pos+1));
            }
        }
        // メソッド SetNodeLs1
        public static void SetNodeLs1(short start_X, short start_Y, short goal_X, short goal_Y)
        {
            sg.startpoint_X = start_X;
            sg.startpoint_Y = start_Y;
            sg.goalpoint_X = goal_X;
            sg.goalpoint_Y = goal_Y;
            ls1.Add(sg); //リストに追加する
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using static System.Console;
using static System.Math;

class MainClass : Scanner
{
    static (int x, int y)[] dd = new (int x, int y)[4] { (1, 0), (0, 1), (-1, 0), (0, -1) };
    static void Main()
    {
        var (H, W) = ReadTuple<int,int>();
        var map = new bool[H, W];
        for (int i = 0; i < H; i++)
        {
            var s = RString();
            for (int j = 0; j < W; j++)
            {
                map[i, j] = s[j] == '#';
            }
        }
        var used = new bool[H, W];
        long ans = 0;
        var que = new Queue<(int y,int x,bool color)>();
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                if (map[i, j] && !used[i, j])
                {
                    que.Enqueue((i, j, true));
                    used[i, j] = true;
                }
                else continue;

                long wc = 0;
                long bc = 1;
                while (que.Count > 0)
                {
                    var p = que.Dequeue();
                    foreach (var item in dd)
                    {
                        int nx = p.x + item.x;
                        int ny = p.y + item.y;

                        bool ncolor = !p.color;
                        if (!(0 <= ny && ny < H && 0 <= nx && nx < W)) continue;
                        if (used[ny, nx] || map[ny, nx] == p.color) continue;

                        used[ny, nx] = true;
                        if (ncolor) bc++;
                        else wc++;
                        que.Enqueue((ny, nx, ncolor));
                    }

                    if (que.Count == 0)
                    {
                        ans += bc * wc;
                    }
                }
            }
        }
        WriteLine(ans);
    }
}



class Scanner
{
    public static string RString() => Console.ReadLine();
    public static int RInt() => ReadTuple<int>();
    public static long RLong() => ReadTuple<long>();
    public static double RDouble() => ReadTuple<double>();

    public static string[] RStrings() => Console.ReadLine().Split();
    public static int[] RInts() => Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
    public static long[] RLongs() => Array.ConvertAll(Console.ReadLine().Split(), long.Parse);
    public static double[] RDoubles() => Array.ConvertAll(Console.ReadLine().Split(), double.Parse);
    public static int[] RInts(Func<string, int> func) => Console.ReadLine().Split().Select(func).ToArray();
    public static long[] RLongs(Func<string, long> func) => Console.ReadLine().Split().Select(func).ToArray();
    public static double[] RDoubles(Func<string, double> func) => Console.ReadLine().Split().Select(func).ToArray();
    //public static string[] RStrings(Func<string, string> func) => Console.ReadLine().Split().Select(func).ToArray();

    public static T1 ReadTuple<T1>()
    {
        var r = RString();
        var r1 = (T1)Convert.ChangeType(r, typeof(T1));
        return r1;
    }
    public static (T1, T2) ReadTuple<T1, T2>()
    {
        var r = RStrings();
        var r1 = (T1)Convert.ChangeType(r[0], typeof(T1));
        var r2 = (T2)Convert.ChangeType(r[1], typeof(T2));
        return (r1, r2);
    }
    public static (T1, T2, T3) ReadTuple<T1, T2, T3>()
    {
        var r = RStrings();
        var r1 = (T1)Convert.ChangeType(r[0], typeof(T1));
        var r2 = (T2)Convert.ChangeType(r[1], typeof(T2));
        var r3 = (T3)Convert.ChangeType(r[2], typeof(T3));
        return (r1, r2, r3);
    }
    public static (T1, T2, T3, T4) ReadTuple<T1, T2, T3, T4>()
    {
        var r = RStrings();
        var r1 = (T1)Convert.ChangeType(r[0], typeof(T1));
        var r2 = (T2)Convert.ChangeType(r[1], typeof(T2));
        var r3 = (T3)Convert.ChangeType(r[2], typeof(T3));
        var r4 = (T4)Convert.ChangeType(r[3], typeof(T4));
        return (r1, r2, r3, r4);
    }
}

using System;
using System.Text;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using static System.Console;
using static System.Math;

namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            new Program().Solve(new ConsoleInput(Console.In, ' '));
#if DEBUG
            ReadLine();
#endif
        }

        struct Point
        {
            public int x;
            public int y;

            public Point(int x, int y)
            {
                this.x = x;
                this.y = y;
            }
        }

        void Solve(ConsoleInput cin)
        {
            int h = cin.ReadInt;
            int w = cin.ReadInt;

            bool[,] field = new bool[h, w];
            List<Point> blacks = new List<Point>();

            for (int i = 0; i < h; i++)
            {
                string str = cin.Read;

                for (int j = 0; j < w; j++)
                {
                    field[i, j] = str[j] == '#';
                    if (field[i, j])
                    {
                        blacks.Add(new Point(i, j));
                    }
                }
            }

            bool[,] gone = new bool[h, w];
            int result = 0;

            for (int i = 0; i < blacks.Count(); i++)
            {
                Point b = blacks[i];
                int level = 1;
                int whiteCount = 0;

                Queue<Point> queue = new Queue<Point>();
                queue.Enqueue(b);
                gone[b.x, b.y] = true;

                while (queue.Count() != 0)
                {
                    Point now = queue.Dequeue();

                    for (int j = 0; j < 4; j++)
                    {
                        int nextX = 0;
                        int nextY = 0;

                        switch (j)
                        {
                            case 0:
                                nextX = now.x - 1;
                                nextY = now.y;
                                break;
                            case 1:
                                nextX = now.x;
                                nextY = now.y - 1;
                                break;
                            case 2:
                                nextX = now.x + 1;
                                nextY = now.y;
                                break;
                            case 3:
                                nextX = now.x;
                                nextY = now.y + 1;
                                break;
                            default:
                                nextX = nextY = 0;
                                break;
                        }


                        if (nextX >= 0
                            && nextX < h
                            && nextY >= 0
                            && nextY < w
                            && field[nextX, nextY] != field[now.x, now.y]
                            && !gone[nextX, nextY])
                        {
                            gone[nextX, nextY] = true;

                            if (field[nextX, nextY])
                            {
                                Remove(blacks, nextX, nextY);
                                level++;
                            }
                            else
                            {
                                whiteCount++;
                            }

                            queue.Enqueue(new Point(nextX, nextY));
                        }
                    }
                }

                result += level * whiteCount;
            }

            Console.WriteLine(result);
        }

        void Remove(List<Point> points, int x, int y)
        {
            for (int i = 0; i < points.Count(); i++)
            {
                Point p = points[i];
                if (p.x == x && p.y == y)
                {
                    points.RemoveAt(i);
                    break;
                }
            }
        }

        class ConsoleInput
        {
            private readonly System.IO.TextReader _stream;
            private char _separator = ' ';
            private Queue<string> inputStream;

            public ConsoleInput(System.IO.TextReader stream, char separator = ' ')
            {
                this._separator = separator;
                this._stream = stream;
                inputStream = new Queue<string>();
            }

            public string Read
            {
                get
                {
                    if (inputStream.Count != 0) return inputStream.Dequeue();
                    string[] tmp = _stream.ReadLine().Split(_separator);
                    for (int i = 0; i < tmp.Length; ++i)
                        inputStream.Enqueue(tmp[i]);
                    return inputStream.Dequeue();
                }
            }

            public string ReadLine { get { return _stream.ReadLine(); } }
            public int ReadInt { get { return int.Parse(Read); } }
            public long ReadLong { get { return long.Parse(Read); } }
            public double ReadDouble { get { return double.Parse(Read); } }
            public string[] ReadStrArray(long N) { var ret = new string[N]; for (long i = 0; i < N; ++i) ret[i] = Read; return ret; }
            public int[] ReadIntArray(long N) { var ret = new int[N]; for (long i = 0; i < N; ++i) ret[i] = ReadInt; return ret; }
            public long[] ReadLongArray(long N) { var ret = new long[N]; for (long i = 0; i < N; ++i) ret[i] = ReadLong; return ret; }
        }
    }
}

