            for (int j = 0; j < w; j++)
            {
                if (s[j] == '#') map[i, j] = true;
                sno[i, j] = p++;
            }
        }
        getAns(h, w, map, sno);
    }
    static void getAns2(int h, int w, bool[,] map, int[,] sno, UnionFind uf)
    {
        var d = new Dictionary<int, int>();
        for (int i = 0; i < h; i++)
            for (int j = 0; j < w; j++)
            {
                var p = uf.Root(sno[i, j]);
                if (!d.ContainsKey(p)) d[p] = 0;
                if (map[i, j]) d[p]++;
            }
        var ans = 0;
        foreach (var x in d)
        {
            var t = uf.getMem(x.Key);
            ans += x.Value * (t - x.Value);
        }
        Console.WriteLine(ans);
    }
    static void getAns(int h, int w, bool[,] map, int[,] sno)
    {
        var dx = new int[] { 0, 1 ,0,-1};
        var dy = new int[] { 1, 0 ,-1,0};
        var uf = new UnionFind(h * w);
        for (int i = 0; i < h; i++)
            for (int j = 0; j < w; j++)
                for (int k = 0; k < 4; k++)
                {
                    var nx = i + dx[k];
                    var ny = j + dy[k];
                    if (nx < h && ny < w && nx >= 0 && ny >= 0 &&
                      ((map[i, j] && !map[nx, ny]) | (!map[i, j] && map[nx, ny])))
                        uf.Unite(sno[i, j], sno[nx, ny]);
                }
        getAns2(h, w, map, sno, uf);
    }
}

