        //メソッドCombine　二つのノードを結合する
        public static void Combine(int h, int w)
        {
            int temp_x;
            int temp_y;
            for (int i = 0; i < ls1.Count; i++)
            {
                if (ls1[i].goal_x > 0)
                {
                    temp_x = ls1[i].goal_x - 1;
                    temp_y = ls1[i].goal_y;
                    SetNodeLs2(i, temp_x, temp_y);
                }
                if (ls1[i].goal_x < (h - 1))
                {
                    temp_x = ls1[i].goal_x + 1;
                    temp_y = ls1[i].goal_y;
                    SetNodeLs2(i, temp_x, temp_y);
                }
                if (ls1[i].goal_y > 0)
                {
                    temp_x = ls1[i].goal_x;
                    temp_y = ls1[i].goal_y - 1;
                    SetNodeLs2(i, temp_x, temp_y);
                }
                if (ls1[i].goal_y < (w - 1))
                {
                    temp_x = ls1[i].goal_x;
                    temp_y = ls1[i].goal_y + 1;
                    //
                    SetNodeLs2(i,temp_x,temp_y);
                }

            }
