//メソッドCheckAround SとGの組合せリストをつくる
        public static void CheckAround(int a, int b, int hh, int ww)
        {
            if (a > 0)
            {
                if (Board[a - 1, b] == ".")
                {
                    SetNodeLs1(a, b, a-1, b);
                }
            }
            if (a < (hh - 1))
            {
                if (Board[a + 1, b] == ".")
                {
                    SetNodeLs1(a, b, a+1, b);
                }
            }

            if (b > 0)
            {
                if (Board[a, b - 1] == ".")
                {
                    SetNodeLs1(a, b, a, b - 1);
                }
            }
            if (b < (ww - 1))
            {
                if (Board[a, b + 1] == ".")
                {
                    SetNodeLs1(a, b, a, b + 1);
                }
            }
            void SetNodeLs1(int start_X,int start_Y,int goal_X,int goal_Y)
            {
