        public class IntArrComparer : IEqualityComparer<int[]>
        {
            public bool Equals(int[] l, int[] r)
            {
                if (l[0] == r[0] && l[1] == r[1])
                {
                    return true;
                }
                else
                {
                    return false;
                }
            }

            public int GetHashCode(int[] arr)
            {
                int hcode = arr[0] * arr[1];
                return hcode;
            }
        }

        public static List<int[]> Dfs(int nowh, int noww, List<int[]> hists, List<char[]> bwlst, int H, int W)
        {

            int[] dh = new int[4] { 1, 0, -1, 0 };
            int[] dw = new int[4] { 0, 1, 0, -1 };


            bool isDeadend = true;

            var anslist = new List<int[]>();

            var histlist = new List<int[]>(hists);
            for (int i = 0; i < 4; i++)
            {
                int[] dst = new int[2];
                dst[0] = nowh + dh[i];
                dst[1] = noww + dw[i];


                if (dst[0] >= 0 && dst[0] < H && dst[1] >= 0 && dst[1] < W)
                {
                   // Console.WriteLine("is in length");
                    if (histlist[dst[0]][dst[1]] == 0)
                    {
                     //   Console.WriteLine("no history");
                        if (bwlst[nowh][noww] == '#' && bwlst[dst[0]][dst[1]] == '.')
                        {
                            int[] hist = new int[W];
                            histlist[dst[0]].CopyTo(hist, 0);
                            hist[dst[1]] = 1;
                            histlist[dst[0]] = hist;
                            int[] ansitem = new int[2] { dst[0], dst[1] };
                            anslist.Add(ansitem);


                            int nexth = dst[0];
                            int nextw = dst[1];

                            var tmptmpanslist =Dfs(nexth, nextw, histlist, bwlst, H, W);
                            List<int[]> tmpanslist;
                            if (tmptmpanslist != null)
                            {
                                tmpanslist = new List<int[]>(tmptmpanslist);
                                anslist.AddRange(tmpanslist);
                            }
                            isDeadend = false;
                        }
                        else if (bwlst[nowh][noww] == '.' && bwlst[dst[0]][dst[1]] == '#')
                        {

                            int[] hist = new int[W];
                            histlist[dst[0]].CopyTo(hist, 0);
                            hist[dst[1]] = 1;
                            histlist[dst[0]] = hist;
                            int nexth = dst[0];
                            int nextw = dst[1];
                            var tmptmpanslist = Dfs(nexth, nextw, histlist, bwlst, H, W);
                            List<int[]> tmpanslist;
                            if (tmptmpanslist != null)
                            {
                                isDeadend = false;
                                tmpanslist = new List<int[]>(tmptmpanslist);
                                anslist.AddRange(tmpanslist);

                            }
                        }
                    }
                }

            }
            if (isDeadend) return null;


            return anslist;
        }

        public static long Gcd(long a, long b)
        {
            long tmp;
            // a<bにする
            if (a >= b)
            {
                tmp = a;
                a = b;
                b = tmp;
            }

            if (a == 0)
            {
                return b;
            }

            tmp = a;
            a = b % a;
            b = tmp;
            return Gcd(a, b);

        }


        public static IEnumerable<long> PF(long n)
        {
            long i = 2;
            long tmp = n;

            while (i * i <= n) //※1
            {
                if (tmp % i == 0)
                {
                    tmp /= i;
                    yield return i;
                }
                else
                {
                    i++;
                }
            }
            if (tmp != 1) yield return tmp;//最後の素数も返す
        }




    }

