        UnionFind uf = new UnionFind(h * w);
        for (int i = 0; i < h; i++)
        {
            for (int j = 0; j < w - 1; j++)
            {
                if (map[i][j] != map[i][j + 1]) uf.Unite(i * w + j, i * w + j + 1);
            }
