            {

                int bh = elem / w;
                int bw = elem % w;
                if ((bh % 2 + bw % 2) % 2 == 0) c1++;
                else c2++;
            }
            c1.WriteLog();
            c2.WriteLog();
            res += c1 * c2;
        }
