                    while (queR.Count > 0)
                    {
                        int r = queR.Dequeue();
                        int c = queC.Dequeue();
                        accessed[r, c] = true;
                        if (map[r, c] == '#') countA[countA.Count - 1]++;
                        if (map[r, c] == '.') countB[countB.Count - 1]++;

                        for (int t = 0; t < 4; t++)
