                }
                else continue;

                int wc = 0;
                int bc = 1;
                while (que.Count > 0)
                {
                    var p = que.Dequeue();
                    foreach (var item in dd)
                    {
                        int nx = p.x + item.x;
                        int ny = p.y + item.y;

                        bool ncolor = !p.color;
                        if (!(0 <= nx && nx < W && 0 <= ny && ny < H)) continue;
                        if (used[ny, nx] || map[ny, nx] == p.color) continue;

                        used[ny, nx] = true;
                        if (ncolor) bc++;
                        else wc++;
                        que.Enqueue((ny, nx, ncolor));
                    }

                    if (que.Count == 0)
                    {
                        ans += bc * wc;
                    }
                }
            }
        }
        WriteLine(ans);
    }
}



