public class CompetitiveProgramming
{
  int[] delta = new int[] { 1, 0, -1, 0, 1 };
  public void Solve()
  {
    var o = Ints;
    var H = o[0];
    var W = o[1];
    var S = new char[H][];
    for (int i = 0; i < H; ++i) S[i] = Chars;
    var uf = new UnionFind(H * W);
    for (int i = 0; i < H; ++i)
    {
      for (int j = 0; j < W; ++j)
      {
        int cs = 0;
        if (S[i][j] == '#') cs = 1;
        for (int k = 0; k < 4; ++k)
        {
          int dx = i + delta[k];
          int dy = j + delta[k + 1];
          if (dx < 0 || dx >= H || dy < 0 || dy >= W) continue;
          int cs2 = 0;
          if (S[dx][dy] == '#') cs2 = 1;
          if ((cs ^ cs2) == 1)
          {
            uf.Merge(i * W + j, dx * W + dy);
          }
        }
      }
    }

    var cntblack = new int[H * W];
    var cntwhite = new int[H * W];
    for (int i = 0; i < H; ++i)
    {
      for (int j = 0; j < W; ++j)
      {
        var curconnect = uf.GetParent(i * W + j);
        if (S[i][j] == '#') ++cntblack[curconnect];
        else ++cntwhite[curconnect];
      }
    }
    long ans = 0;
    for (int i = 0; i < H * W; ++i)
    {
      ans += cntwhite[i] * cntblack[i];
    }
    Write(ans);


  }

}
public class UnionFind
{
  int _count;
  int[] par, sizes, rank;
  public UnionFind(int N)
  {
    _count = N;
    par = new int[N];
    sizes = new int[N];
    rank = new int[N];
    for (int i = 0; i < N; ++i)
    {
      par[i] = i;
      sizes[i] = 1;
      rank[i] = 0;
    }
  }
  int Root(int X)
  {
    if (par[X] == X)
    {
      return X;
    }
    else return (par[X] = Root(par[X]));
  }
  public bool Merge(int X, int Y)
  {
    X = Root(X);
    Y = Root(Y);
    if (X == Y) return false;
    --_count;
    if (rank[X] < rank[Y])
    {
      par[X] = Y;
      sizes[Y] += sizes[X];
    }
    else
    {
      par[Y] = X;
      sizes[X] += sizes[Y];
      if (rank[X] == rank[Y]) ++rank[X];
    }
    return true;
  }
  public bool IsSame(int X, int Y) => Root(X) == Root(Y);
  public int Count => _count;
  public bool IsParent(int X) => X == Root(X);
  public int GetParent(int X) => Root(X);
  public int Size(int X) => sizes[Root(X)];
}

public static class Math2
{
  public const int INF = 1 << 29;
  public const long INFL = 1L << 60;
  public const long MOD = 1000000007;
  public const int MOD2 = 998244353;

  public static long Power(long a, long b, long MOD = 1000000007)//i^N
  {
    long res = 1;
    while (b > 0)
    {
      if ((b & 1) != 0) res = res * a % MOD;
      a = a * a % MOD;
      b >>= 1;
    }
    return res;
  }
  public static long Power2(long a, long b)//i^N
  {
    long res = 1;
    while (b > 0)
    {
      if ((b & 1) != 0) res = res * a;
      a = a * a;
      b >>= 1;
    }
    return res;
  }
  public static long GCD(long a, long b)
  {
    while (b > 0)
    {
      var r = a % b;
      a = b;
      b = r;
    }
    return a;
  }
  public static long LCM(long a, long b) => (b / GCD(a, b)) * a;
  public static long Comb(long n, long r, int MOD = 1000000007)
  {
    long ret = 1;
    long x = 1;
    for (long i = n; i >= n - r + 1; --i)
    {
      ret = ret / x * i;
      ret %= MOD;
      x++;
    }
    return ret;
  }
  public static long Comb2(long n, long r)
  {
    long Nume = 1;
    long Deno = 1;

    if (r > n - r) r = n - r;
    for (long i = 1; i <= r; ++i)
    {
      Deno *= i;
      Nume *= n - i + 1;
    }
    return Nume / Deno;
  }
}
