class Program
{
    struct P
    {
        public int h;
        public int w;
        public bool isBlack;
        public P(int h,int w,bool isBlack)
        {
            this.h = h;
            this.w = w;
            this.isBlack = isBlack;
        }
    }
    static void Main(string[] args)
    {
        var hw = Array.ConvertAll(ReadLine().Split(' '), int.Parse);
        var s = new string[hw[0]];
        for (var i = 0; i < hw[0]; i++)
            s[i] = ReadLine();
        var p = new P[hw[0], hw[1]];
        var res = 0;
        var white = new List<P>();
        var black = new List<P>();
        for(var i = 0; i < hw[0]; i++)
        {
            for(var j = 0; j < hw[1]; j++)
            {
                p[i, j] = new P(i, j, s[i][j] == '#');
                if (s[i][j] == '#') black.Add(p[i, j]);
                else white.Add(p[i, j]);
            }
        }

        foreach(var w in white)
        {
            foreach(var b in black)
            {
                if (dfs(p, w.h, w.w, new HashSet<P>(), false, hw[0], hw[1], b))
                    res++;
            }
        }
        WriteLine(res);
    }

    private static bool dfs(P[,] p,int i,int j,HashSet<P> ps,bool isBlack,int h,int w,P clear)
    {
        if (i == clear.h && j == clear.w) return true;
        ps.Add(p[i, j]);
        var isClear = false;
        if (i != 0 && !ps.Contains(p[i - 1, j]) && (p[i - 1, j].isBlack ^ isBlack))
        {
            isClear=isClear?isClear:dfs(p, i - 1, j, ps, !isBlack, h, w, clear);
        }
        if (j != 0 && !ps.Contains(p[i, j - 1]) && (p[i, j - 1].isBlack ^ isBlack))
        {
            isClear=isClear?isClear:dfs(p, i, j - 1, ps, !isBlack, h, w, clear);
        }
        if (i != h - 1 && !ps.Contains(p[i + 1, j]) && (p[i + 1, j].isBlack ^ isBlack))
        {
            isClear = isClear ? isClear:dfs(p, i + 1, j, ps, !isBlack, h, w, clear);
        }
        if (j != w - 1 && !ps.Contains(p[i, j + 1]) && (p[i, j + 1].isBlack ^ isBlack))
        {
            isClear=isClear?isClear:dfs(p, i, j+1, ps, !isBlack, h, w, clear);
        }
        return isClear;
    }
