        foreach(var white in wcell) {
          if(Walk(H, W, black, white, black, isLook, table)) count++;
          for(int h = 0; h<H; h++)
            for(int w = 0; w<W; w++)
              isLook[w, h] = false;
        }

      WriteLine(count);
    }

    static bool Walk(int H, int W, int[] black, int[] white, int[] now, bool[,] isLook, bool[,] table)
    {
      if(isLook[now[X], now[Y]]) return false;
      isLook[now[X], now[Y]] = true;
      if(now[X] == white[X] && now[Y] == white[Y])
        return true;

      bool u = false, d = false, l = false, r = false;
      // up
      if(now[Y] > 0)
        if(table[now[X], now[Y]] != table[now[X], now[Y]-1])
          u = Walk(H, W, black, white, new int[] { now[X], now[Y]-1 }, isLook, table);
      // down
      if(now[Y] < H-1)
        if(table[now[X], now[Y]] != table[now[X], now[Y]+1])
          d = Walk(H, W, black, white, new int[] { now[X], now[Y]+1 }, isLook, table);
      // left
      if(now[X] > 0)
        if(table[now[X], now[Y]] != table[now[X]-1, now[Y]])
          l = Walk(H, W, black, white, new int[] { now[X]-1, now[Y] }, isLook, table);
      // right
      if(now[X] < W-1)
        if(table[now[X], now[Y]] != table[now[X]+1, now[Y]])
          r = Walk(H, W, black, white, new int[] { now[X]+1, now[Y] }, isLook, table);

      return u || d || l || r;
    }
  }
}

