    public class Cell
    {
        public int X, Y;
        public char color;
        public bool added;

        public List<Cell> GetNextCells(Cell[,] S)
        {
            List<Cell> cells = new List<Cell>();
            Cell cu = S[X, Y - 1];
            Cell cd = S[X, Y + 1];
            Cell cl = S[X - 1, Y];
            Cell cr = S[X + 1, Y];
            Cell[] ccand = { cu, cd, cl, cr };

            foreach (Cell c in ccand)
            {
                if (color == '#')
                {
                    if (c.color == '.' && !c.added) {
                        cells.Add(c);
                        c.added = true;
                    }
                }
                else
                {
                    if (c.color == '#' && !c.added)
                    {
                        cells.Add(c);
                        c.added = true;
                    }
                }
            }
            return cells;
        }

    }

