    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.In)).Calc());

    #endregion
    public object Calc()
    {
        var H = cr.Int;
        var W = cr.Int;
        var grid = NewArray(H, () => cr.String);

        uf = new UnionFind(H * W);
        for (int h = 0; h < H; h++)
            for (int w = 0; w < W; w++)
            {
                var cur = h * W + w;
                if (w + 1 < W && grid[h][w] != grid[h][w + 1])
                    uf.UnionSet(cur, cur + 1);
                if (h + 1 < H && grid[h][w] != grid[h + 1][w])
                    uf.UnionSet(cur, cur + W);
            }

        var g = Enumerable.Range(0, H * W).Select(i => grid[i / W][i % W] == '#' ? -1 - uf.Root(i) : 1 + uf.Root(i)).GroupCount();
        var cnt = 0L;
        foreach (var pair in g)
            if (pair.Key >= 0 && g.ContainsKey(-pair.Key))
                cnt += (long)pair.Value * g[-pair.Key];

        return cnt;
    }
    UnionFind uf;
}
class UnionFind
{
    int[] data;
    public UnionFind(int size)
    {
        this.data = Enumerable.Repeat(-1, size).ToArray();
    }

    public int Root(int x)
    {
        if (data[x] < 0) return x;
        return data[x] = Root(data[x]);
    }
    public int Count(int x) => -data[Root(x)];
    public void UnionSet(int x, int y)
    {
        var xRoot = Root(x);
        var yRoot = Root(y);
        if (xRoot == yRoot) return;
        else if (data[yRoot] < data[xRoot])//y側の方が多い場合は逆にする
        {
            var tmp = yRoot;
            yRoot = xRoot;
            xRoot = tmp;
        }
        data[xRoot] += data[yRoot];
        data[yRoot] = xRoot;
    }
    public bool IsSameSet(int x, int y) => Root(x) == Root(y);
}

