class Program {
    static Scanner cin = new Scanner();

    struct p {
        public int x, y;
        public p(int X, int Y) {
            x = X;
            y = Y;
        }
    }

    static void Main(string[] args) {
        int H = cin.Int();
        int W = cin.Int();
        var S = new string[H];
        for (int i = 0; i < H; i++) {
            S[i] = Console.ReadLine();
        }

        int[] dx = { 1, 0, -1, 0 };
        int[] dy = { 0, 1, 0, -1 };

        int ans = 0;
        var isSearched = new bool[H, W];

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (!isSearched[i, j]) {
                    int black = 0, white = 0;
                    Queue<p> que = new Queue<p>();
                    que.Enqueue(new p(j, i));
                    isSearched[i, j] = true;
                    while (que.Count > 0) {
                        p point = que.Dequeue();
                        if (S[point.y][point.x] == '#') black++;
                        else white++;
                        for (int k = 0; k < 4; k++) {
                            int ni = point.y + dy[k];
                            int nj = point.x + dx[k];
                            if (0 <= ni && ni < H && 0 <= nj && nj < W && !isSearched[ni, nj] && S[point.y][point.x] != S[ni][nj]) {
                                    que.Enqueue(new p(nj, ni));
                                    isSearched[ni, nj] = true;
                            }
                        }
                    }
                    ans += black * white;
                }
            }
        }
        Console.WriteLine(ans);
        Console.ReadLine();
    }
}

