using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace Practice
{
    class Program
    {
        static void Main(string[] args)
        {
            Solve();
        }
        private const int MOD = 1000000007;
        private enum Color
        {
            B,
            W,
        }
        private struct Coordinate
        {
            public int x;
            public int y;
            public Coordinate(int x, int y)
            {
                this.x
                     = x;
                this.y = y;
            }
        }
        private const int DFSWhite = 0;
        private const int DFSGray = 1;
        private const int DFSBlack = 2;
        private static readonly int[] offsetX = { 0, -1, 1, 0 };// 2468方向
        private static readonly int[] offsetY = { 1, 0, 0, -1 };
        private static readonly Dictionary<Coordinate, int> nextTable = new Dictionary<Coordinate, int>();
        static void Solve()
        {
            var hw = ReadAndParseIntArr();
            int h = hw[0];
            int w = hw[1];
            var color = new Color[h, w];
            for (int i = 0; i < h; ++i)
            {
                var s = Console.ReadLine();
                for (int x = 0; x < w; ++x)
                {
                    color[i, x] = s[x] == '#' ? Color.B : Color.W;
                }
            }
            long ans = 0;

            var used = new bool[h, w];
            for (int x = 0; x < w; ++x)
            {
                for (int y = 0; y < h; ++y)
                {
                    if (used[y, x]) { continue; }

                    used[y, x] = true;
                    // dfs
                    int totalB = 0;
                    int totalW = 0;
                    var stack = new Stack<Coordinate>();
                    stack.Push(new Coordinate(x, y));
                    if (color[y, x] == Color.B) { totalB++; }
                    else { totalW++; }

                    var dfsColor = new int[h, w];
                    dfsColor[y, x] = DFSGray;
                    while (stack.Count >= 1)
                    {
                        var u = stack.Peek();
                        Coordinate v = Next(u);

                        if( v.x != -10)
                        {

                            if(IsConnected(u,v, w, h, color) &&  dfsColor[v.y, v.x] == DFSWhite)
                            {
                                used[v.y, v.x] = true;
                                dfsColor[v.y, v.x] = DFSGray;
                                if (color[v.y, v.x] == Color.B) { totalB++; }
                                else { totalW++; }
                                stack.Push(v);
                            }
                        }
                        else
                        {
                            stack.Pop();
                            dfsColor[u.y, u.x] = DFSBlack;

                        }
                    }

                    ans += totalB * totalW;
                }
            }
            Console.WriteLine(ans);
        }
        private static Coordinate Next(Coordinate u)
        {
            if (!nextTable.ContainsKey(u))
            {
                nextTable[u] = 0;
            }
            int d = nextTable[u];
            nextTable[u]++;
            if (d <= 3)
            {
                return new Coordinate(u.x + offsetX[d], u.y + offsetY[d]);
            }
            else
            {
                return new Coordinate(-10, -10);
            }

        }
        private static bool IsConnected(Coordinate src, Coordinate dst, int w, int h, Color[,] table)
        {
            if (dst.x < 0 || w <= dst.x) { return false; }
            if (dst.y < 0 || h <= dst.y) { return false; }
            if (table[src.y, src.x] == table[dst.y, dst.x]) { return false; }
            return true;
        }
        #region よく使う便利関数
        private static bool isPrime(long x)
        {
            if (x == 2) { return true; }
            if (x < 2 || x % 2 == 0) { return false; }
            long i = 3;
            while (i * i <= x)
            {
                if (x % i == 0) { return false; }
                i = i + 2;
            }
            return true;
        }
        private static long lcm(long x, long y)
        {
            return x / gcd(x, y) * y;
        }
        private static long gcd(long x, long y)
        {
            return y > 0 ? gcd(y, x % y) : x;
        }
        private static long pow(long x, long n)
        {
            if (n == 0) { return 1; }
            long res = pow(x * x % MOD, n / 2);
            if (n % 2 == 1)
            {
                res = res * x % MOD;
            }
            return res;
        }
        private static int ReadAndParseInt()
        {
            return int.Parse(Console.ReadLine());
        }
        private static int[] ReadAndParseIntArr()
        {
            return Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
        }
        private static long ReadAndParseLong()
        {
            return long.Parse(Console.ReadLine());
        }
        private static long[] ReadAndParseLongArr()
        {
            return Array.ConvertAll(Console.ReadLine().Split(' '), long.Parse);
        }
        #endregion
    }
}

