using System;
using System.Collections.Generic;
class Program
{
	static void Main(string[] args)
	{
		string[] str = Console.ReadLine().Split();
		int H = int.Parse(str[0]);
		int W = int.Parse(str[1]);
		int[,]C = new int[H,W];
		for(var i=0;i<H;i++){
			string str2 = Console.ReadLine();
			for(var j=0;j<W;j++){
				if(str2.Substring(j,1)=="#"){
					C[i,j]=1;
				}
			}
		}
		var uf = new UnionFind(H*W);
		for(var i=0;i<H;i++){
			for(var j=0;j<W;j++){
				if(i<H-1 && C[i+1,j]!=C[i,j]){
					uf.Unite(i*W+j,(i+1)*W+j);
				}
				if(j<W-1 && C[i,j+1]!=C[i,j]){
					uf.Unite(i*W+j,i*W+(j+1));
				}
			}
		}
		int[,]A1 = new int[H,W];
		int[,]A2 = new int[H,W];
		for(var i=0;i<H;i++){
			for(var j=0;j<W;j++){
				int r = uf.Root(i*W+j);
				if(C[i,j]==1){
					A1[r/W,r%W]++;
				} else {
					A2[r/W,r%W]++;
				}
			}
		}
		long ans = 0;
		for(var i=0;i<H;i++){
			for(var j=0;j<W;j++){
				ans += A1[i,j]*A2[i,j];
			}
		}
		Console.WriteLine(ans);
	}
}

public class UnionFind
{
    private int[] data;
	public UnionFind(int size){
        data = new int[size];
        for (int i = 0; i < size; i++) data[i] = -1;
    }
    public bool Unite(int x, int y){
        x = Root(x);
        y = Root(y);
        if (x != y){
            if (data[y] < data[x]){
                var tmp = y;
                y = x;
                x = tmp;
            }
            data[x] += data[y];
            data[y] = x;
        }
        return x != y;
    }
	public bool IsSameGroup(int x, int y){
        return Root(x) == Root(y);
    }
    public int Root(int x){
        return data[x] < 0 ? x : data[x] = Root(data[x]);
    }
}

