using static System.Math;

class Program
{
    private static P[,] p;
    struct bw
    {
        public int w;
        public int b;
    }
    struct P
    {
        public int h;
        public int w;
        public bool isBlack;
        public bool isSearch;
        public P(int h,int w,bool isBlack)
        {
            this.h = h;
            this.w = w;
            this.isBlack = isBlack;
            isSearch = false;
        }
    }
    static void Main(string[] args)
    {
        var hw = Array.ConvertAll(ReadLine().Split(' '), int.Parse);
        var s = new string[hw[0]];
        for (var i = 0; i < hw[0]; i++)
            s[i] = ReadLine();
        p = new P[hw[0], hw[1]];
        var res = 0;
        for(var i = 0; i < hw[0]; i++)
        {
            for(var j = 0; j < hw[1]; j++)
            {
                p[i, j] = new P(i, j, s[i][j] == '#');
            }
        }
        for(var i = 0; i < hw[0]; i++)
        {
            for(var j = 0; j < hw[1]; j++)
            {
                if (!p[i, j].isSearch)
                {
                    var bw = new bw();
                    Get(i, j, hw[0], hw[1],ref bw);
                    res += bw.b * bw.w;
                }
            }
        }
        WriteLine(res);
    }

    private static void Get(int i,int j,int h,int w,ref bw bw)
    {
        p[i, j].isSearch = true;
        if (p[i, j].isBlack) bw.b++;
        else bw.w++;
        if (i != 0 && !p[i-1,j].isSearch && (p[i - 1, j].isBlack ^ p[i,j].isBlack))
        {
            Get( i - 1, j, h, w,ref bw);
        }
        if (j != 0 && !p[i,j-1].isSearch&& (p[i, j - 1].isBlack ^ p[i,j].isBlack))
        {
            Get(i, j - 1,h,w,ref bw);
        }
        if (i != h - 1 && !p[i+1,j].isSearch && (p[i + 1, j].isBlack ^ p[i,j].isBlack))
        {
            Get( i + 1, j,h,w,ref bw);
        }
        if (j != w - 1 && !p[i,j+1].isSearch && (p[i, j + 1].isBlack ^ p[i,j].isBlack))
        {
            Get( i, j + 1,h,w,ref bw);
        }
    }
