		Out.Flush();
	}
	int X, Y;
	bool[,] map, flip, done;
	void Solve()
	{
		var I = G;
		Y = I[0]; X = I[1];
		map = new bool[X, Y];
		for (var y = 0; y < Y; y++)
		{
			var S = Str;
			for (var x = 0; x < X; x++) map[x, y] = S[x] == '#';
		}
		flip = new bool[X, Y];
		for (var x = 0; x < X; x++) for (var y = 0; y < Y; y++) flip[x, y] = map[x, y] ^ ((x + y) % 2 != 0);
		done = new bool[X, Y];
		var ans = 0L;
		for (var x = 0; x < X; x++) for (var y = 0; y < Y; y++) ans += Calc(x, y);
		WriteLine(ans);
	}
	int[] dx = { 1, 0, -1, 0, 1 };
	long Calc(int sx, int sy)
	{
		if (done[sx, sy]) return 0;
		var cnt = new int[2];
		var q = new Queue<Tuple<int, int>>();
		q.Enqueue(new Tuple<int, int>(sx, sy));
		var col = flip[sx, sy];
		while (q.Count > 0)
		{
			var p = q.Dequeue();
			if (done[p.Item1, p.Item2]) continue;
			cnt[map[p.Item1, p.Item2] ? 1 : 0]++;
			done[p.Item1, p.Item2] = true;
			for (var i = 0; i < 4; i++)
			{
				var x = p.Item1 + dx[i];
				var y = p.Item2 + dx[i + 1];
				if (x >= 0 && y >= 0 && x < X && y < Y && !done[x, y] && flip[x, y] == col) q.Enqueue(new Tuple<int, int>(x, y));
			}
		}
		return cnt[0] * (long)cnt[1];
	}
}

