public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.In)).Calc());

    #endregion
    public object Calc()
    {
        var H = cr.Int;
        var W = cr.Int;
        var grid = NewArray(H, () => cr.String);

        uf = new UnionFind(H * W);
        for (int h = 0; h < H; h++)
            for (int w = 0; w < W; w++)
            {
                var cur = h * W + w;
                if (w + 1 < W && grid[h][w] != grid[h][w + 1])
                    uf.UnionSet(cur, cur + 1);
                if (h + 1 < H && grid[h][w] != grid[h + 1][w])
                    uf.UnionSet(cur, cur + W);
            }

        var g = Enumerable.Range(0, H * W).Select(i => uf.Root(i) + (i % 2 == 0 ? 100000 : 0)).GroupCount();
        var cnt = 0L;
        foreach (var pair in g)
            if (pair.Key < 100000)
            {
                int v;
                g.TryGetValue(pair.Key + 100000, out v);
                cnt += (long)pair.Value * v;
            }


        return cnt;
    }
    UnionFind uf;
}
class UnionFind
{
    int[] data;
    public UnionFind(int size)
    {
        this.data = Enumerable.Repeat(-1, size).ToArray();
    }

    public int Root(int x)
    {
        if (data[x] < 0) return x;
        return data[x] = Root(data[x]);
    }
    public int Count(int x) => -data[Root(x)];
    public void UnionSet(int x, int y)
    {
        var xRoot = Root(x);
        var yRoot = Root(y);
        if (xRoot == yRoot) return;
        else if (data[yRoot] < data[xRoot])//y側の方が多い場合は逆にする
        {
            var tmp = yRoot;
            yRoot = xRoot;
            xRoot = tmp;
        }
        data[xRoot] += data[yRoot];
        data[yRoot] = xRoot;
    }
    public bool IsSameSet(int x, int y) => Root(x) == Root(y);
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program {
    static Scanner cin = new Scanner();

    struct p {
        public int x, y;
        public p(int X, int Y) {
            x = X;
            y = Y;
        }
    }

    static void Main(string[] args) {
        int H = cin.Int();
        int W = cin.Int();
        var S = new string[H+2];

        for (int i = 1; i <= H; i++) {
            S[i] = "." + Console.ReadLine() + ".";
        }

        int[] dx = { 1, 0, -1, 0 };
        int[] dy = { 0, 1, 0, -1 };

        long ans = 0;
        var isSearched = new bool[H + 2, W + 2];

        for (int i = 0; i < W+2; i++) {
            isSearched[0, i] = true;
            isSearched[H + 1, i] = true;
        }
        for (int i = 0; i < H+2; i++) {
            isSearched[i, 0] = true;
            isSearched[i, W + 1] = true;
        }

        for (int i = 1; i <= H; i++) {
            for (int j = 1; j <= W; j++) {
                if (!isSearched[i, j]) {
                    int black = 0, white = 0;
                    Queue<p> que = new Queue<p>();
                    que.Enqueue(new p(j, i));
                    isSearched[i, j] = true;
                    while (que.Count > 0) {
                        p point = que.Dequeue();
                        if (S[point.y][point.x] == '#') black++;
                        else if(S[point.y][point.x] == '.') white++;
                        for (int k = 0; k < 4; k++) {
                            int ni = point.y + dy[k];
                            int nj = point.x + dx[k];
                            if (1 <= ni && ni <= H && 1 <= nj && nj <= W && !isSearched[ni, nj] && S[point.y][point.x] != S[ni][nj]) {
                                    que.Enqueue(new p(nj, ni));
                                    isSearched[ni, nj] = true;
                            }
                        }
                    }
                    ans += (long)black * (long)white;
                }
            }
        }
        Console.WriteLine(ans);
        Console.ReadLine();
    }
}

