using System;
using System.Collections.Generic;
using static System.Console;

namespace C
{
  class Program
  {
    static int X = 0;
    static int Y = 1;

    static void Main(string[] args)
    {
      string[] input = ReadLine().Split();
      int H = int.Parse(input[0]);
      int W = int.Parse(input[1]);


      bool[,] isLook = new bool[W, H];
      bool[,] table = new bool[W, H];

      var bcell = new List<int[]>();
      var wcell = new List<int[]>();

      for(int h = 0; h<H; h++) {
        string S = ReadLine();
        for(int w = 0; w<W; w++) {
          table[w, h] = S[w] == '.';
          if(S[w] == '.') wcell.Add(new int[] { w, h });
          else bcell.Add(new int[] { w, h });
        }
      }

      int count = 0;
      foreach(var black in bcell)
        foreach(var white in wcell) {
          if(Walk(H, W, black, white, black, isLook, table)) count++;
          isLook = new bool[W, H];
        }

      WriteLine(count);
    }

    static bool Walk(int H, int W, int[] black, int[] white, int[] now, bool[,] isLook, bool[,] table)
    {
      if(isLook[now[X], now[Y]]) return false;
      isLook[now[X], now[Y]] = true;
      if(now[X] == white[X] && now[Y] == white[Y])
        return true;

      // up
      if(now[Y] > 0)
        if(table[now[X], now[Y]] != table[now[X], now[Y]-1])
          if(Walk(H, W, black, white, new int[] { now[X], now[Y]-1 }, isLook, table))
            return true;
      // down
      if(now[Y] < H-1)
        if(table[now[X], now[Y]] != table[now[X], now[Y]+1])
          if(Walk(H, W, black, white, new int[] { now[X], now[Y]+1 }, isLook, table))
            return true;
      // left
      if(now[X] > 0)
        if(table[now[X], now[Y]] != table[now[X]-1, now[Y]])
          if(Walk(H, W, black, white, new int[] { now[X]-1, now[Y] }, isLook, table))
            return true;
      // right
      if(now[X] < W-1)
        if(table[now[X], now[Y]] != table[now[X]+1, now[Y]])
          if(Walk(H, W, black, white, new int[] { now[X]+1, now[Y] }, isLook, table))
            return true;

      return false;
    }
  }
}

using System;
using System.Collections.Generic;
