    class Program
    {
        private int[] nextY = { 0, 1, 0, -1 };
        private int[] nextX = { 1, 0, -1, 0 };
        public void Solve()
        {
            var sc = new Scanner();
            int H = sc.NextInt();
            int W = sc.NextInt();
            string[] S = new string[H];
            for (int i = 0; i < H; i++)
            {
                S[i] = sc.Next();
            }
            bool[,] B = new bool[H, W];
            long ans = 0;
            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    if (B[i, j]) continue;
                    var yq = new Queue<int>();
                    var xq = new Queue<int>();
                    int bCnt = 0;
                    int wCnt = 0;
                    yq.Enqueue(i);
                    xq.Enqueue(j);
                    while (yq.Count > 0)
                    {
                        int yy = yq.Dequeue();
                        int xx = xq.Dequeue();
                        if (B[yy, xx]) continue;
                        B[yy, xx] = true;
                        if (S[yy][xx] == '#') bCnt++;
                        else wCnt++;
                        for (int k = 0; k < 4; k++)
                        {
                            int ny = nextY[k] + yy;
                            int nx = nextX[k] + xx;
                            if (ny >= 0 && ny < H && nx >= 0 && nx < W && S[yy][xx] != S[ny][nx] && !B[ny, nx])
                            {
                                yq.Enqueue(ny);
                                xq.Enqueue(nx);
                            }
                        }
                    }
                    //Console.WriteLine($"{i} {j} {bCnt} {wCnt}");
                    ans += bCnt * wCnt;
                }
            }
            Console.WriteLine(ans);
        }

        static void Main(string[] args) => new Program().Solve();
    }
}

