                    uf.UnionSet(cur, cur + W);
            }

        var g = Enumerable.Range(0, H * W).Select(i => grid[i / W][i % W] == '#' ? -1 - uf.Root(i) : uf.Root(i)).GroupCount();
        var cnt = 0;
        foreach (var pair in g)
            if (pair.Key >= 0)
            {
                int v;
                g.TryGetValue(-1 - pair.Key, out v);
                cnt += pair.Value * v;
            }


        return cnt;
