		public static void Solve(Scanner cin)
		{
			var n = cin.ReadInt();
			var (a, l) = cin.ReadValueArray<long, long>(n);
			long b = cin.ReadLong();

			if(b == 1)
			{
				Console.WriteLine(0);
				return;
			}
			ModInt.MOD = b;

			ModInt ans = 0;

			for (int i = 0; i < n; i++)
			{
				ModInt tmp = 1;
				long keta = a[i].ToString().Length;
				for (int j = 0; j < keta; j++)
				{
					tmp *= 10;
				}

				ModInt rep;
				{
					rep = 0;
					ModInt tens = tmp;
					ModInt aaa = 1;
					for (int j = 1; j <= l[i]; j *= 2)
					{
						if ((l[i] / j) % 2 == 1) rep = rep * tens + aaa;

						aaa = aaa + tens * aaa;
						tens *= tens;
					}
				}

				tmp = ModInt.Pow(tmp, l[i]);

				ans *= tmp;

				rep *= a[i];
				ans += rep;
			}
			Console.WriteLine(ans);
		}

