	public static readonly int[] dw = new int[4] { 0, -1, 0, 1 };

	public static void Main()
	{
		int H = GetInt();
		int W = GetInt();
		char[,] grid = new char[H, W];		
		int[] numWhite = new int[H * W];
		int[] numBlack = new int[H * W];
		for(int h = 0; h < H; h++)
		{
			string S = GetString();
			for(int w = 0; w < W; w++)
			{
				grid[h, w] = S[w];

				int v = h * W + w;
				if(grid[h, w] == '.')
					numWhite[v] = 1;
				else
					numBlack[v] = 1;
			}
		}

		var uf = new UnionFindEx(H * W, numWhite, numBlack);
		for(int h = 0; h < H; h++)
		{
			for(int w = 0; w < W; w++)
			{
				for(int i = 0; i < 4; i++)
				{
					int nh = h + dh[i];
					int nw = w + dw[i];
					if(nh < 0 || nh >= H || nw < 0 || nw >= W)
						continue;

					if(grid[h, w] == grid[nh, nw])
						continue;

					int v = h * W + w;
					int u = nh * W + nw;
					if(!uf.IsSame(v, u))
						uf.Merge(v, u);
				}
			}
		}

		var rootSet = new HashSet<int>();
		for(int h = 0; h < H; h++)
			for(int w = 0; w < W; w++)
				rootSet.Add(uf.Root(h * W + w));

		var rootList = rootSet.ToList();
		long ans = 0;
		foreach(int root in rootList)
			ans += (long)(uf.NumWhite(root) * uf.NumBlack(root));

		Console.WriteLine(ans);
	}
}


public class UnionFindEx
{
	private int[] par = null;
	private int[] rank = null;
	private int[] m_numWhite = null;
	private int[] m_numBlack = null;

	public UnionFindEx(int n, int[] numWhite, int[] numBlack)
	{
		m_numWhite = numWhite;
		m_numBlack = numBlack;

		par = new int[n];
		rank = new int[n];
		for(int i = 0; i < n; i++)
		{
			par[i] = i;
			rank[i] = 0;
		}
	}

	public bool IsSame(int x, int y)
	{
		return (Root(x) == Root(y));
	}

	public int Root(int x)
	{
		if(par[x] == x)
			return x;

		int r = Root(par[x]);
		par[x] = r;
		return r;
	}

	public bool Merge(int x, int y)
	{
		int rx = Root(x);
		int ry = Root(y);
		if(rx == ry)
			return false;

		if(rank[rx] < rank[ry])
		{
			int tmp = rx;
			rx = ry;
			ry = tmp;
		}
		else if(rank[rx] == rank[ry])
			rank[rx]++;

		par[ry] = rx;
		m_numWhite[rx] = m_numWhite[rx] + m_numWhite[ry];
		m_numBlack[rx] = m_numBlack[rx] + m_numBlack[ry];
		return true;
	}

	public int NumWhite(int x)
	{
		return m_numWhite[Root(x)];
	}

	public int NumBlack(int x)
	{
		return m_numBlack[Root(x)];
	}
}


