class UnionFind{

	int[] parent;
	int[] mem;
	int compo;
	int N;
	public int[] b;
	public int[] w;
	public UnionFind(int n_){
		Initialize(n_);
	}

	public void Initialize(int n_){
		N=n_;
		parent=new int[N];
		mem=new int[N];
		for(int i=0;i<N;i++){
			parent[i]=i;
			mem[i]=1;
		}
		compo=N;
		b = new int[N];
		w = new int[N];
	}

	public int Parent(int a){
		if(parent[a]==a) return a;
		return parent[a] = Parent(parent[a]);
	}

	public bool IsUnited(int a,int b){
		return Parent(a) == Parent(b);
	}

	public void Unite(int a,int b){
		a = Parent(a); b = Parent(b);
		if(a == b) return;
		if(mem[a] <= mem[b]){
			parent[a] = b;
			mem[b] += mem[a];
			this.b[b] += this.b[a];
			this.w[b] += this.w[a];
			compo -= 1;
		} else {
			parent[b] = a;
			mem[a] += mem[b];
			compo -= 1;
			this.b[a] += this.b[b];
			this.w[a] += this.w[b];
		}
	}

	public bool IsRoot(int x){
		return x == parent[x];
	}
	public int MemCnt(int x){
		return mem[Parent(x)];
	}

	public void Dump(){
		for(int i=0;i<parent.Length;i++){
			Console.Write(i==0?"{0}":" {0}",parent[i]);
		}
		Console.WriteLine("");
	}

	public int Compo{
		get{
			return compo;
		}
	}

}

