class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);

        H = sc.ReadInt();
        W = sc.ReadInt();
        S = sc.ReadStrArray(H);

        var b = new List<Tuple<int, int>>();
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                if (S[i][j] == '#') b.Add(Tuple.Create(i, j));
            }
        }
        Visited = new HashSet<Tuple<int, int>>();
        var ans = 0L;
        foreach (var start in b)
        {
            var count = new long[2];
            if (Visited.Contains(start)) continue;
            Visited.Add(start);
            Rec(start.Item1, start.Item2, count);
            ans += count[0] * count[1];
        }
        Console.WriteLine(ans);

        Console.Out.Flush();
    }
    static string[] S;
    static int H;
    static int W;
    static HashSet<Tuple<int, int>> Visited;
    static void Rec(int h, int w, long[] count)
    {
        if (S[h][w] == '.') count[0]++;
        else count[1]++;

        var dh = new int[] { -1, 0, 1, 0 };
        var dw = new int[] { 0, -1, 0, 1 };
        for (int d = 0; d < 4; d++)
        {
            var nh = h + dh[d];
            var nw = w + dw[d];
            if (0 <= nh && nh < H && 0 <= nw && nw < W)
            {
                if (Visited.Contains(Tuple.Create(nh, nw))) continue;
                Visited.Add(Tuple.Create(nh, nw));
                if (S[h][w] != S[nh][nw])
                {
                    Rec(nh, nw, count);
                }
            }
        }
    }
    static Scanner sc = new Scanner();
}

class Scanner
{
    string[] S = new string[0];
    int Index = 0;
    char[] Separators = new char[] { ' ' };

