using namespace std;


struct UF {
	vector<int> par;
	UF(int i) : par(i) {
		for (int j = 0; j < i; j++) {
			par[j] = j;
		}
	}
	int parent(int i) {
		if (par[i] == i) return i;
		return par[i] = parent(par[i]);
	}
	bool find(int i, int j) {
		return parent(i) == parent(j);
	}
	void uni(int i, int j) {
		par[i] = parent(j);
	}
};

int main() {
	int H, W; cin >> H >> W;
	vector<string> S(W);
	for (int i = 0; i < H; i++) cin >> S[i];
	vector<int> Swhite, Sblack;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (S[i][j] == '#') Sblack.push_back(i * W + j);
			else Swhite.push_back(i * W + j);
		}
	}
	UF uf(H * W);
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			char s = S[i][j];
			int idx = i * W + j;
			if (0 <= i - 1 && s != S[i - 1][j]) {
				uf.uni(idx, (i - 1) * W + j);
			}
			if (0 <= j - 1 && s != S[i][j - 1]) {
				uf.uni(idx, i * W + (j - 1));
			}
		}
	}
	int ans = 0;
	for (int i = 0, sz = Sblack.size(); i < sz; i++) {
		for (int j = 0, sz = Swhite.size(); j < sz; j++) {
			if (uf.find(Sblack[i], Swhite[j])) ans++;
		}
	}
	cout << ans << endl;
}

