public class Sub {
    public Sub() { }
    int H, W;
    Lib2D.JagArray2D<char> field;
    Lib2D.Array2D<int> joined;
    long ans = 0;

    public void Main() {
        string[] inp = Console.ReadLine().Split();
        H = int.Parse(inp[0]);
        W = int.Parse(inp[1]);
        field = new Lib2D.JagArray2D<char>(H);
        for (int y = 0; y < H; y++)field.values[y] = Console.ReadLine().ToCharArray();
        joined = new Lib2D.Array2D<int>(W + 2, H + 2, 0);
        for (int y = 0; y < H; y++) {
            for (int x = 0; x < W; x++) {
                joined[x + 1, y + 1] = Type(new Lib2D.Point(x, y));
            }
        }
        // joined.print();
        for (int y = 1; y <= H; y++) {
            for (int x = 1; x <= W; x++) {
                // Console.WriteLine("x = {0}, y = {1}", x, y);
                NofBW n = search(new Lib2D.Point(x, y), Type(new Lib2D.Point(x - 1, y - 1)));
                ans += (long)n.b * (long)n.w;
            }
        }
        Console.WriteLine(ans);
    }

    int Type(Lib2D.Point p) {
        int x = p.X, y = p.Y;
        return (field[p] == '#' && (x + y) % 2 == 0) || (field[p] == '.' && (x + y) % 2 == 1) ? 1 : 2;
    }
    int depth = 0;
    string Indent(int d) {
        string res = "";
        for (int i = 0; i < d; i++) {
            res += "    ";
        }
        return res;
    }
    NofBW search(Lib2D.Point p, int nowtype) {
        // Console.WriteLine(Indent(depth++) + "search(({0}, {1}), {2})", p.X, p.Y, nowtype);
        if (joined[p] == 0 || joined[p] != nowtype) {
            // Console.WriteLine(Indent(--depth) + "return");
            return new NofBW(0, 0);
        }
        joined[p] = 0;
        int bl = 0, wh = 0;
        foreach (var v in Lib2D.Vector.moveV()) {
            NofBW n = search(p + v, nowtype);
            bl += n.b;
            wh += n.w;
        }
        if (field[new Lib2D.Point(p.X - 1, p.Y - 1)] == '#') {
            // Console.WriteLine(Indent(--depth) + "return (black = {0}, white = {1})", bl + 1, wh);
            return new NofBW(bl + 1, wh);
        } else {
            // Console.WriteLine(Indent(--depth) + "return (black = {0}, white = {1})", bl, wh + 1);
            return new NofBW(bl, wh + 1);
        }
    }
}

