namespace C
{
    internal class Program
    {
        private static void Main(string[] args)
        {
            var input = GetInput();
            Console.WriteLine(Solve(input));
        }

        private static int Solve(Dictionary<Position, int> dic)
        {
            var reachableDic = new Dictionary<Position, Dictionary<Position, bool>>();
            foreach (Position pos in dic.Keys)
            {
                reachableDic[pos] = new Dictionary<Position, bool>();
            }

            int ret = 0;
            foreach (Position p1 in dic.Keys)
            {
                if (dic[p1] == -1)
                {
                    foreach (Position p2 in dic.Keys)
                    {
                        if (dic[p2] == 1)
                        {
                            if (reachable(p1, p2, dic, reachableDic)) { ret++; }

                        }
                    }
                }
            }
            return ret;
        }

        private static bool reachable(Position start, Position goal, Dictionary<Position, int> dic, Dictionary<Position, Dictionary<Position, bool>> reachableDic)
        {
            if (reachableDic[start].ContainsKey(goal))
            {
                return reachableDic[start][goal];
            }
            else
            {

                Stack<Tuple<Position, int>> stack = new Stack<Tuple<Position, int>>();
                stack.Push(Tuple.Create(start, dic[start]));
                while (stack.Count > 0)
                {
                    Tuple<Position, int> tp = stack.Pop();
                    Position pos = tp.Item1;
                    int color = tp.Item2;
                    foreach (Position np in pos.Neighbors)
                    {
                        if (dic.ContainsKey(np))
                        {
                            if (!reachableDic[start].ContainsKey(np))
                            {
                                if (reachableDic[start][np] = color != dic[np])
                                {
                                    reachableDic[start][np] = true;

                                    stack.Push(Tuple.Create(np, dic[np]));
                                }
                            }
                        }
                    }
                }



                if (!reachableDic[start].ContainsKey(goal))
                {
                    reachableDic[start][goal] = false;
                }
                return reachableDic[start][goal];


            }


        }

        private static Dictionary<Position, int> GetInput()
        {
            Dictionary<Position, int> ret = new Dictionary<Position, int>();
            string[] items = Console.ReadLine().Split(' ');
            int h = int.Parse(items[0]);
            int w = int.Parse(items[1]);
            for (int y = 0; y < h; y++)
            {
                string line = Console.ReadLine();
                for (int x = 0; x < w; x++)
                {
                    if (line[x] == '#')
                    {
                        ret[new Position(x, y)] = 1;
                    }
                    else
                    {
                        ret[new Position(x, y)] = -1;
                    }
                }
            }
            return ret;
        }

        private struct Position
        {
            public readonly int X, Y;
            public Position(int x, int y)
            {
                X = x;
                Y = y;
            }
            public override int GetHashCode()
            {
                return X + Y * 1000;
            }
            public override bool Equals(object obj)
            {
                return obj is Position && ((Position)obj).X == X && ((Position)obj).Y == Y;
            }

            public IEnumerable<Position> Neighbors
            {
                get
                {
                    yield return new Position(X - 1, Y);
                    yield return new Position(X + 1, Y);
                    yield return new Position(X, Y - 1);
                    yield return new Position(X, Y + 1);
                }
            }
        }

    }
