class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);

        H = sc.ReadInt();
        W = sc.ReadInt();
        S = sc.ReadStrArray(H);

        var b = new List<Tuple<int, int>>();
        for (int i = 0; i < H; i++)
        {
            for (int j = 0; j < W; j++)
            {
                if (S[i][j] == '#') b.Add(Tuple.Create(i, j));
            }
        }
        Visited = new bool[H, W];
        var ans = 0L;
        foreach (var start in b)
        {
            var count = new long[2];
            var h = start.Item1;
            var w = start.Item2;
            if (Visited[h, w]) continue;
            Visited[h, w] = true;
            Rec(h, w, count);
            ans += count[0] * count[1];
        }
        Console.WriteLine(ans);

        Console.Out.Flush();
    }
    static string[] S;
    static int H;
    static int W;
    static bool[,] Visited;
    static void Rec(int h, int w, long[] count)
    {
        if (S[h][w] == '.') count[0]++;
        else count[1]++;

        var dh = new int[] { -1, 0, 1, 0 };
        var dw = new int[] { 0, -1, 0, 1 };
        for (int d = 0; d < 4; d++)
        {
            var nh = h + dh[d];
            var nw = w + dw[d];
            if (0 <= nh && nh < H && 0 <= nw && nw < W)
            {
                if (Visited[nh, nw]) continue;
                if (S[h][w] != S[nh][nw])
                {
                    Visited[nh, nw] = true;
                    Rec(nh, nw, count);
                }
            }
        }
    }
    static Scanner sc = new Scanner();
}

