using System.Linq;

class Program {
    static Scanner cin = new Scanner();

    struct p {
        public int x, y;
        public p(int X, int Y) {
            x = X;
            y = Y;
        }
    }

    static void Main(string[] args) {
        int H = cin.Int();
        int W = cin.Int();
        var S = new string[H+2];
        for(int i = 1; i <= H; i++) {
            S[i] = " " + Console.ReadLine() + " ";
        }

        int[] dx = { 1, 0, -1, 0 };
        int[] dy = { 0, 1, 0, -1 };

        int ans = 0;
        var isSearched = new bool[H + 2, W + 2];
        for (int i = 0; i < W+2; i++) {
            isSearched[0, i] = true;
            isSearched[H + 1, i] = true;
        }
        for (int i = 0; i < H+2; i++) {
            isSearched[i, 0] = true;
            isSearched[i, W + 1] = true;
        }

        for (int i = 1; i <= H; i++) {
            for (int j = 1; j <= W; j++) {
                if(!isSearched[i, j]) {
                    int comb = 0;
                    Queue<p> que = new Queue<p>();
                    que.Enqueue(new p(j, i));
                    isSearched[i, j] = true;
                    while (que.Count > 0) {
                        p point = que.Dequeue();
                        for (int k = 0; k < 4; k++) {
                            int ni = point.y + dy[i];
                            int nj = point.x + dx[i];
                            if (1 <= ni && ni <= H && 1 <= nj && nj <= W && isSearched[ni, nj] == false) {
                                if (S[point.y][point.x] == '.' && S[ni][nj] == '#') {
                                    que.Enqueue(new p(nj, ni));
                                    if (S[i][j] == '.') comb++;
                                    isSearched[ni, nj] = true;
                                }
                                else if (S[point.y][point.x] == '#' && S[ni][nj] == '.') {
                                    que.Enqueue(new p(nj, ni));
                                    if (S[i][j] == '#') comb++;
                                    isSearched[ni, nj] = true;
                                }
                            }
                        }
                    }
                    ans += comb;
                }
            }
        }
        Console.WriteLine(ans);
        Console.ReadLine();
    }
}

class Scanner //標準入力
{
    string[] s;
    int i;

    char[] cs = new char[] { ' ' };

    public Scanner()
    {
        s = new string[0];
        i = 0;
    }

    public string next()
    {
        if (i < s.Length) return s[i++];
        string st = Console.ReadLine();
        while (st == "") st = Console.ReadLine();
        s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
        if (s.Length == 0) return next();
        i = 0;
        return s[i++];
    }

    public int Int()
    {
        return int.Parse(next());
    }
    public int[] ArrayInt(int N, int add = 0)
    {
        int[] Array = new int[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = Int() + add;
        }
        return Array;
    }

    public long Long()
    {
        return long.Parse(next());
    }

    public long[] ArrayLong(int N, long add = 0)
    {
        long[] Array = new long[N];
        for (int i = 0; i < N; i++)
        {
            Array[i] = Long() + add;
        }
        return Array;
    }

    public double Double()
    {
