    class UnionFind
    {
        private int[] Par, Rank;
        public UnionFind(int max)
        {
            Par = new int[max];
            Rank = new int[max];
            for (int i = 0; i < max; i++)
            {
                Par[i] = i;
            }
        }

        public int Find(int n)
        {
            if (Par[n] == n)
            {
                return n;
            }
            else
            {
                return Find(Par[n]);
            }
        }

        public bool Same(int a, int b)
        {
            return Find(a) == Find(b);
        }

        public void Union(int a, int b)
        {
            a = Find(a);
            b = Find(b);
            if (a == b) return;
            if (Rank[a] < Rank[b])
            {
                Par[a] = b;
            }
            else
            {
                Par[b] = a;
                if (Rank[a] == Rank[b]) Rank[a]++;
            }
        }
    }

    class Program
    {

        public void Solve()
        {
            var sc = new Scanner();
            var H = sc.NextInt();
            int W = sc.NextInt();
            char[][] S = sc.GetCharMatrix(H);
            var uf = new UnionFind(H * W);
            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    if (i < H - 1)
                    {
                        if (S[i + 1][j] != S[i][j])
                        {
                            uf.Union(i * W + j, (i + 1) * W + j);
                        }
                    }

                    if (j < W - 1)
                    {
                        if (S[i][j + 1] != S[i][j])
                        {
                            uf.Union(i * W + j, i * W + j + 1);
                        }
                    }
                }
            }

            var bMap = new Dictionary<int, int>();
            var wMap = new Dictionary<int, int>();
            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    int f = uf.Find(i * W + j);
                    int b,w;
                    bMap.TryGetValue(f, out b);
                    wMap.TryGetValue(f, out w);
                    if ((i + j) % 2 == 0)
                    {          
                        bMap[f] = b + 1;
                        wMap[f] = w;
                    }
                    else
                    {
                        bMap[f] = b;
                        wMap[f] = w + 1;
                    }
                }
            }

            long ans = 0;
            foreach (var i in bMap)
            {
                ans += i.Value * wMap[i.Key];
            }
            Console.WriteLine(ans);
        }


        static void Main(string[] args) => new Program().Solve();
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program {
    static Scanner cin = new Scanner();

    struct p {
        public int x, y;
        public p(int X, int Y) {
            x = X;
            y = Y;
        }
    }

    static void Main(string[] args) {
        int H = cin.Int();
        int W = cin.Int();
        var S = new string[H+2];

        for (int i = 1; i <= H; i++) {
            S[i] = "." + Console.ReadLine() + ".";
        }

        int[] dx = { 1, 0, -1, 0 };
        int[] dy = { 0, 1, 0, -1 };

        long ans = 0;
        var isSearched = new bool[H + 2, W + 2];

        for (int i = 0; i < W+2; i++) {
            isSearched[0, i] = true;
            isSearched[H + 1, i] = true;
        }
        for (int i = 0; i < H+2; i++) {
            isSearched[i, 0] = true;
            isSearched[i, W + 1] = true;
        }

        for (int i = 1; i <= H; i++) {
            for (int j = 1; j <= W; j++) {
                if (!isSearched[i, j]) {
                    int black = 0, white = 0;
                    Queue<p> que = new Queue<p>();
                    que.Enqueue(new p(j, i));
                    isSearched[i, j] = true;
                    while (que.Count > 0) {
                        p point = que.Dequeue();
                        if (S[point.y][point.x] == '#') black++;
                        else if(S[point.y][point.x] == '.') white++;
                        for (int k = 0; k < 4; k++) {
                            int ni = point.y + dy[k];
                            int nj = point.x + dx[k];
                            if (1 <= ni && ni <= H && 1 <= nj && nj <= W && !isSearched[ni, nj] && S[point.y][point.x] != S[ni][nj]) {
                                    que.Enqueue(new p(nj, ni));
                                    isSearched[ni, nj] = true;
                            }
                        }
                    }
                    ans += black * white;
                }
            }
        }
        Console.WriteLine(ans);
        Console.ReadLine();
    }
}

