class Solver
{
    int H, W;
    char[][] G;
    public void Solve(Scanner sc)
    {
        sc.Make(out H, out W);
        G = sc.Grid(H);
        var uf = new UnionFind(H * W);
        for (var i = 0; i < H; i++)
            for (var j = 0; j < W; j++)
                if (G[i][j] == '#') uf.ct[Id(i, j)]++;
        for (var i = 0; i < H; i++)
            for (var j = 0; j < W; j++)
                for (var k = 0; k < 4; k++)
                {
                    int h = i + gh[k], w = j + gw[k];
                    if (!Inside(h, w, H, W)) continue;
                    if (G[i][j] != G[h][w]) uf.Union(Id(i, j), Id(h, w));
                }
        var use = new bool[H * W];
        var res = 0L;
        for (var i = 0; i < H; i++)
            for (var j = 0; j < W; j++)
                if (!use[uf[Id(i, j)]]){
                    use[uf[Id(i, j)]] = true;
                    var s = uf.Size(Id(i, j));
                    res += (long)uf.ct[Id(i, j)] * (s - uf.ct[Id(i, j)]);
                }
        WriteLine(res);
    }
    public int Id(int h, int w) => h * W + w;
    int[] gh = new[] { 0, 0, 1, -1 }, gw = new[] { 1, -1, 0, 0 };
    public static bool Inside(int h, int w, int H, int W)
        => 0 <= h && h < H && 0 <= w && w < W;
}

public class UnionFind
{
    public int GroupCount { get; private set; }
    protected int[] data;
    public int[] ct;
    public virtual int this[int i] => Find(i);
    public UnionFind(int size)
    {
        ct = new int[size];
        data = Create(size, () => -1);
        GroupCount = size;
    }
    protected int Find(int i)
        => data[i] < 0 ? i : (data[i] = Find(data[i]));
    public int Size(int i)
        => -data[Find(i)];
    public virtual bool Union(int u, int v)
    {
        u = Find(u); v = Find(v);
        if (u == v) return false;
        if (data[u] > data[v])
            swap(ref u, ref v);
        GroupCount--;
        ct[u] += ct[v];
        data[u] += data[v];
        data[v] = u;
        return true;
    }
}
