            {
                SetNodeLs1(j_pos * width + k_pos, (j_pos+1)* width + k_pos);
            }
            if ((k_pos > 0) && (str[j_pos][k_pos - 1] == str1))
            {
                SetNodeLs1(j_pos * width + k_pos, j_pos * width + k_pos - 1);
            }
            if ((k_pos < (width - 1)) && (str[j_pos][k_pos + 1] == str1))
            {
                SetNodeLs1(j_pos * width + k_pos, j_pos * width + k_pos + 1);
            }
        }
        // メソッド SetNodeLs1
        public static void SetNodeLs1(int start_point, int goal_point)
        {
            sg_Number.start_Number = start_point;
            sg_Number.goal_Number = goal_point;
            ls1.Add(sg_Number); //ls1にノードのリストに追加する
        }
    }
}

