class AC {
    static void Main() {
        Sub s = new Sub();
        s.Main();
    }
}
public class Sub {
    public Sub() { }
    int H, W;
    Lib2D.JagArray2D<char> field;
    Lib2D.Array2D<int> fstate;

    int black, white;
    long ans = 0;

    public void Main() {
        string[] inp = Console.ReadLine().Split();
        H = int.Parse(inp[0]);
        W = int.Parse(inp[1]);
        field = new Lib2D.JagArray2D<char>(H);
        for (int y = 0; y < H; y++)field.values[y] = Console.ReadLine().ToCharArray();
        fstate = new Lib2D.Array2D<int>(W + 2, H + 2, 0);
        for (int y = 0; y < H; y++)
            for (int x = 0; x < W; x++)fstate[x + 1, y + 1] = Type(new Lib2D.Point(x, y));
        for (int y = 1; y <= H; y++)
            for (int x = 1; x <= W; x++) {
                black = white = 0;
                Search(new Lib2D.Point(x, y), Type(new Lib2D.Point(x - 1, y - 1)));
                ans += (black * white);
            }
        Console.WriteLine(ans);
    }
    int Type(Lib2D.Point p) {
        int x = p.X, y = p.Y;
        return (field[p] == '#' && (x + y) % 2 == 0) || (field[p] == '.' && (x + y) % 2 == 1) ? 1 : 2;
    }
    void Search(Lib2D.Point p, int nowtype) {
        if (fstate[p] == 0 || fstate[p] != nowtype)return;
        fstate[p] = 0;
        foreach (var v in Lib2D.Vector.moveV()) { Search(p + v, nowtype); }
        if (field[new Lib2D.Point(p.X - 1, p.Y - 1)] == '#')black++;
        else white++;
        return;
    }
}

