    static void getAns2(int h, int w, bool[,] map, int[,] sno, UnionFind uf)
    {
        var d = new Dictionary<int, P>();
        for (int i = 0; i < h; i++)
            for (int j = 0; j < w; j++)
            {
                var p = uf.Root(sno[i, j]);
                if (!d.ContainsKey(p)) d[p] = new P();
                if (map[i, j]) d[p].b++;
                else d[p].w++;
            }
        var ans = 0L;
        foreach (var x in d)
            ans += x.Value.b * x.Value.w;
        Console.WriteLine(ans);
    }
    static void getAns(int h, int w, bool[,] map, int[,] sno)
    {
        var dx = new int[] { 0, 1 };
        var dy = new int[] { 1, 0 };
        var uf = new UnionFind(h * w);
        for (int i = 0; i < h; i++)
            for (int j = 0; j < w; j++)
                for (int k = 0; k < 2; k++)
                {
                    var nx = i + dx[k];
                    var ny = j + dy[k];
                    if (nx < h && ny < w &&
                      ((map[i, j] && !map[nx, ny]) | (!map[i, j] && map[nx, ny])))
                        uf.Unite(sno[i, j], sno[nx, ny]);
                }
        getAns2(h, w, map, sno, uf);
    }
}

