	public static readonly int[] dw = new int[4] { 0, -1, 0, 1 };

	public static void Main()
	{
		int H = GetInt();
		int W = GetInt();
		char[,] grid = new char[H, W];		
		int[] numWhite = new int[H * W];
		int[] numBlack = new int[H * W];
		for(int h = 0; h < H; h++)
		{
			string S = GetString();
			for(int w = 0; w < W; w++)
			{
				grid[h, w] = S[w];

				int v = h * W + w;
				if(grid[h, w] == '.')
					numWhite[v] = 1;
				else
					numBlack[v] = 1;
			}
		}

		var uf = new UnionFindEx(H * W, numWhite, numBlack);
		for(int h = 0; h < H; h++)
		{
			for(int w = 0; w < W; w++)
			{
				for(int i = 0; i < 4; i++)
				{
					int nh = h + dh[i];
					int nw = w + dw[i];
					if(nh < 0 || nh >= H || nw < 0 || nw >= W)
						continue;

					if(grid[h, w] == grid[nh, nw])
						continue;

					int v = h * W + w;
					int u = nh * W + nw;
					if(!uf.IsSame(v, u))
						uf.Merge(v, u);
				}
			}
		}

