        class UnionFind
        {
            // 親要素のインデックスを保持する
            // 親要素が存在しない(自身がルートである)とき、マイナスでグループの要素数を持つ
            int[] parents;
            public UnionFind(int n)
            {
                this.parents = new int[n];
                for (int i = 0; i < n; i++)
                {
                    // 初期状態ではそれぞれが別のグループ(ルートは自分自身)
                    // ルートなのでマイナスで要素数(1個)を保持する
                    this.parents[i] = -1;
                }
            }

            // 要素xのルート要素はどれか
            public int Find(int x)
            {
                // 親がマイナスの場合は自分自身がルート
                if (this.parents[x] < 0) return x;
                // ルートが見つかるまで再帰的に探す
                // 見つかったルートにつなぎかえる
                this.parents[x] = Find(this.parents[x]);
                return this.parents[x];
            }

            /// <summary>
            /// 要素xの属するグループの要素数を取得する
            /// </summary>
            /// <param name="x"></param>
            public int Size(int x)
            {
                // ルート要素を取得して、サイズを取得して返す
                return -this.parents[this.Find(x)];
            }

            // 要素x, yが同じグループかどうか判定する
            public bool Same(int x, int y)
            {
                return this.Find(x) == this.Find(y);
            }

            // 要素x, yが属するグループを同じグループにまとめる
            public bool Union(int x, int y)
            {
                // x, y のルート
                x = this.Find(x);
                y = this.Find(y);
                // すでに同じグループの場合処理しない
                if (x == y) return false;

                // 要素数が少ないグループを多いほうに書き換えたい
                if (this.Size(x) < this.Size(y))
                {
                    var tmp = x;
                    x = y;
                    y = tmp;
                }
                // まとめる先のグループの要素数を更新
                this.parents[x] += this.parents[y];
                // まとめられるグループのルートの親を書き換え
                this.parents[y] = x;
                return true;
            }
        }
    }
}

using System;
using System.Diagnostics;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static string[] cin = Console.ReadLine().Split();
    static int h = int.Parse(cin[0]);
    static int w = int.Parse(cin[1]);
    static bool[,] map = new bool[w, h];
    static bool[,] search = new bool[w, h];
    static int black = 0;
    static int white = 0;

    static void Main()
    {
        for (int j = 0; j < h; j++)
        {
            string s = Console.ReadLine();
            for (int i = 0; i < w; i++)
            {
                // blackのときtrue
                if (s[i] == '#') map[i, j] = true;
            }
        }

        var route = new long[w, h];
        long ans = 0;
        for (int i = 0; i < w; i++)
        {
            for (int j = 0; j < h; j++)
            {
                if (!search[i, j])
                {
                    Route(i, j);
                    ans += (black * white);
                    black = 0;
                    white = 0;
                }
            }
        }
        Console.WriteLine(ans);
    }

    static void Route(int i, int j)
    {
        search[i, j] = true;
        if (map[i, j]) black++;
        else white++;
        if (0 < j)
        {
            if (map[i, j] != map[i, j - 1])
            {
                if (!search[i, j - 1]) Route(i, j - 1);
            }
        }
        if (0 < i)
        {
            if (map[i, j] != map[i - 1, j])
            {
                if (!search[i - 1, j]) Route(i - 1, j);
            }
        }
        if (i + 1 < w)
        {
            if (map[i, j] != map[i + 1, j])
            {
                if (!search[i + 1, j]) Route(i + 1, j);
            }
        }
        if (j + 1 < h)
        {
            if (map[i, j] != map[i, j + 1])
            {
                if (!search[i, j + 1]) Route(i, j + 1);
            }
        }
    }
}

