namespace AtCoder
{
    class Program
    {
        static int h;
        static int w;
        static char[,] map;
        static bool[,] isReached;

        static void Main(string[] args)
        {
            //[summary]C - Alternating Path
            var line = ReadLine();
            h = line[0];
            w = line[1];

            DrawMap();

            //マップ内の全座標を取得
            var coords = GetCoordinates().ToList();
            int count = 0;

            //すべてのマス目からスタートしてみる
            for(int i = 0; i < coords.Count; i++)
            {
                int y = coords[i].Y;
                int x = coords[i].X;

                //スタート地点に設定できるのは黒マスのみ
                if(map[y, x] == '#')
                {
                    foreach(var goal in coords)
                    {
                        //ゴールに設定できるのは白マスのみ
                        if(map[goal.Y, goal.X] == '.')
                        {
                            isReached = new bool[h, w];
                            isReached[y, x] = true;

                            Move(y + 1, x, map[y, x], goal);
                            Move(y - 1, x, map[y, x], goal);
                            Move(y, x + 1, map[y, x], goal);
                            Move(y, x - 1, map[y, x], goal);

                            if (isReached[goal.Y, goal.X])
                            {
                                //Console.WriteLine("{0} {1} / {2} {3}", y, x, goal.Y, goal.X);
                                count++;
                            }   
                        }
                    }
                }
            }

            Console.WriteLine(count);
        }

        static void Move(int y, int x, char previousColor, Coordinate goal)
        {
            if (y < 0 | y == h | x < 0 | x == w)
            {
                return;
            }
            else if (map[y, x] == previousColor)
            {
                return;
            }
            else if (isReached[y, x])
            {
                return;
            }
            else
            {
                isReached[y, x] = true;
                var color = map[y, x];

                Move(y + 1, x, color, goal);
