        {
            int[] hw = ReadInts();
            int h = hw[0];
            int w = hw[1];
            var black = new bool[h, w];
            for(int i = 0; i < h; i++)
            {
                string s = Read();
                for(int j = 0; j < w; j++)
                {
                    black[i, j] = s[j] == '#';
                }
            }
            int cnt = 0;
            for(int i = 0; i < h; i++)
            {
                for(int j = 0; j < w; j++)
                {
                    if (!black[i, j]) continue;
                    var visited = new bool[h, w];
                    cnt+=DFS(black, ref visited, h, w, i, j);
                }
            }
            Console.WriteLine(cnt);
        }

        static int DFS(bool[,] black, ref bool[,] visited,
            int h, int w, int i, int j)
        {
            visited[i, j] = true;
            bool nowBlack = black[i, j];
            int cnt = nowBlack ? 0 : 1;
            if (i > 0 && nowBlack!=black[i-1,j]&&!visited[i - 1, j])
            {
                cnt += DFS(black, ref visited, h, w, i - 1, j);
            }
            if (j > 0 && nowBlack != black[i, j-1] && !visited[i, j - 1])
            {
                cnt += DFS(black, ref visited, h, w, i, j - 1);
            }
            if (i < h - 1 && nowBlack != black[i + 1, j] && !visited[i + 1, j])
            {
                cnt += DFS(black, ref visited, h, w, i + 1, j);
            }
            if (j < w - 1 && nowBlack != black[i, j+1] && !visited[i, j + 1])
            {
                cnt += DFS(black, ref visited, h, w, i, j + 1);
            }
            return cnt;
        }

