using System;
using System.Collections.Generic;
using System.Linq;
class Program{
	const int mod=1000000007;
	static string[] a;
	static bool[,] h;
	static long ans=0,b=0,c=0;
	static void Main(){
		int[] s=Array.ConvertAll(Console.ReadLine().Split(),int.Parse);
		a=new string[s[0]+2];
		for(int i=1;i<=s[0];i++){a[i]="0"+Console.ReadLine()+"0";}
		a[0]=new string('0',s[1]+2);
		a[s[0]+1]=new string('0',s[1]+2);
		h=new bool[s[0]+2,s[1]+2];
		for(int i=1;i<=s[0];i++){
			for(int j=1;j<=s[1];j++){
				if(!h[i,j]){
					fu(i,j);
					ans+=b*c;
					b=0;c=0;
				}
			}
		}

		Console.WriteLine("{0}",ans);
	}
	static void fu(int y,int x){
		h[y,x]=true;
		if(a[y][x]=='#'){b++;}
		else{c++;}
		if((!h[y-1,x])&&a[y-1][x]!=a[y][x]&&a[y-1][x]!='0'){fu(y-1,x);}
		if((!h[y+1,x])&&a[y+1][x]!=a[y][x]&&a[y+1][x]!='0'){fu(y+1,x);}
		if((!h[y,x-1])&&a[y][x-1]!=a[y][x]&&a[y][x-1]!='0'){fu(y,x-1);}
		if((!h[y,x+1])&&a[y][x+1]!=a[y][x]&&a[y][x+1]!='0'){fu(y,x+1);}
	}
}

using System;
using System.Collections.Generic;
using System.Linq;

class Program {
    static Scanner cin = new Scanner();

    struct p {
        public int x, y;
        public p(int X, int Y) {
            x = X;
            y = Y;
        }
    }

    static void Main(string[] args) {
        int H = cin.Int();
        int W = cin.Int();
        var S = new string[H+2];

        for (int i = 1; i <= H; i++) {
            S[i] = "." + Console.ReadLine() + ".";
        }

        int[] dx = { 1, 0, -1, 0 };
        int[] dy = { 0, 1, 0, -1 };

        long ans = 0;
        var isSearched = new bool[H + 2, W + 2];

        for (int i = 0; i < W+2; i++) {
            isSearched[0, i] = true;
            isSearched[H + 1, i] = true;
        }
        for (int i = 0; i < H+2; i++) {
            isSearched[i, 0] = true;
            isSearched[i, W + 1] = true;
        }

        for (int i = 1; i <= H; i++) {
            for (int j = 1; j <= W; j++) {
                if (!isSearched[i, j]) {
                    int black = 0, white = 0;
                    Queue<p> que = new Queue<p>();
                    que.Enqueue(new p(j, i));
                    isSearched[i, j] = true;
                    while (que.Count > 0) {
                        p point = que.Dequeue();
                        if (S[point.y][point.x] == '#') black++;
                        else if(S[point.y][point.x] == '.') white++;
                        for (int k = 0; k < 4; k++) {
                            int ni = point.y + dy[k];
                            int nj = point.x + dx[k];
                            if (1 <= ni && ni <= H && 1 <= nj && nj <= W && !isSearched[ni, nj] && S[point.y][point.x] != S[ni][nj]) {
                                    que.Enqueue(new p(nj, ni));
                                    isSearched[ni, nj] = true;
                            }
                        }
                    }
                    ans += black * white;
                }
            }
        }
        Console.WriteLine(ans);
        Console.ReadLine();
    }
}

