namespace Atcoder
{

    class Program
    {
        static void Main(string[] args)
        {
            int[] HW = Console.ReadLine().Split(' ').Select(int.Parse).ToArray();
            string[][] S = new string[HW[0]][];
            for (int i = 0; i < HW[0]; i++)
            {
                S[i] = new string[HW[1]];
                S[i] = Console.ReadLine().ToArray().Select(x => x.ToString()).ToArray();

            }
            ;


            int output = 0;
            //全#点を出す

            int[][] already_know = new int[HW[0]][];
            for (int k = 0; k < HW[0]; k++)
            {
                already_know[k] = new int[HW[1]];

            }

            for (int i = 0; i < HW[0]; i++)
            {
                for (int j = 0; j < HW[1]; j++)
                {
                    if (S[i][j] == "#")
                    {
                        string[][] map = new string[HW[0]][];

                        List<pair> sharplist = new List<pair>();
                        for (int k = 0; k < HW[0]; k++)
                        {
                            map[k] = new string[HW[1]];

                        }
                        if (already_know[i][j] == 0)
                        {
                            int result = number_movepoint(i, j, S, map, HW[0], HW[1], sharplist);
                            ;
                            output += result;
                            while (sharplist.Count > 0)
                            {
                                pair temp = sharplist[0];
                                sharplist.RemoveAt(0);
                                already_know[temp.x][temp.y] = result;
                            }
                        }
                        else
                        {
                            output +=already_know[i][j];
                            ;
                        }
                    }
                }

            }
            Console.WriteLine(output);
        }

        public struct pair
        {
            public int x;
            public int y;
            public pair(int x, int y)
            {
                this.x = x;
                this.y = y;

            }

        }

        public static int number_movepoint(int x, int y, string[][] S, string[][] map, int H, int W,List<pair> sharplist)
        {
            int output = 0;
            map[x][y] = ".";
            Queue<pair> q = new Queue<pair>();
            if (isSuitablePoint(x - 1, y, H, W))
            {
                if (map[x - 1][y] == null && S[x - 1][y] == ".")
                {
                    q.Enqueue(new pair(x - 1, y));
                    output++;
                    map[x - 1][y] = ".";
                }
            }
            if (isSuitablePoint(x + 1, y, H, W))
            {
                if (map[x + 1][y] == null && S[x + 1][y] == ".")
                {
                    q.Enqueue(new pair(x + 1, y));
                    output++;
                    map[x + 1][y] = ".";
                }
            }
            if (isSuitablePoint(x, y - 1, H, W))
            {
                if (map[x][y - 1] == null && S[x][y - 1] == ".")
                {
                    q.Enqueue(new pair(x, y - 1));
                    output++;
                    map[x][y - 1] = ".";
                }
            }
            if (isSuitablePoint(x, y + 1, H, W))
            {
                if (map[x][y + 1] == null && S[x][y + 1] == ".")
                {
                    q.Enqueue(new pair(x, y + 1));
                    output++;
                    map[x][y + 1] = ".";
                }
            }
            while (q.Count != 0)
            {
                pair temp = q.Dequeue();
                map[temp.x][temp.y] = ".";
                if (S[temp.x][temp.y] == "#")
                {
                    sharplist.Add(new pair(temp.x, temp.y));
                }
                if (isSuitablePoint(temp.x - 1, temp.y, H, W))
                {
                    if (map[temp.x - 1][temp.y] == null && S[temp.x - 1][temp.y] != S[temp.x][temp.y])
                    {
                        q.Enqueue(new pair(temp.x - 1, temp.y));
                        map[temp.x - 1][temp.y] = ".";
                        if (S[temp.x - 1][temp.y] == ".")
                        {
                            output++;

                        }
                    }
                }
                if (isSuitablePoint(temp.x + 1, temp.y, H, W))
                {
                    if (map[temp.x + 1][temp.y] == null && S[temp.x + 1][temp.y] != S[temp.x][temp.y])
                    {
                        q.Enqueue(new pair(temp.x + 1, temp.y));
                        map[temp.x + 1][temp.y] = ".";
                        if (S[temp.x + 1][temp.y] == ".")
                        {
                            output++;

                        }
                    }
                }
                if (isSuitablePoint(temp.x, temp.y - 1, H, W))
                {
                    if (map[temp.x][temp.y - 1] == null && S[temp.x][temp.y - 1] != S[temp.x][temp.y])
                    {
                        q.Enqueue(new pair(temp.x, temp.y - 1));
                        map[temp.x][temp.y - 1] = ".";
                        if (S[temp.x][temp.y - 1] == ".")
                        {
                            output++;

                        }
                    }
                }
                if (isSuitablePoint(temp.x, temp.y + 1, H, W))
                {
                    if (map[temp.x][temp.y + 1] == null && S[temp.x][temp.y + 1] != S[temp.x][temp.y])
                    {
                        q.Enqueue(new pair(temp.x, temp.y + 1));
                        map[temp.x][temp.y + 1] = ".";
                        if (S[temp.x][temp.y + 1] == ".")
                        {
                            output++;

                        }
                    }
                }

            }

            return output;
        }

        public static bool isSuitablePoint(int x, int y, int H, int W)
        {
            if (x >= 0 && y >= 0 && x < H && y < W)
            {
                return true;

            }
            return false;
        }
    }
}

