                ans += count[0] * count[1];
            }
        }
        Console.WriteLine(ans);
        Console.WriteLine(Call);

        Console.Out.Flush();
    }
    static string[] S;
    static int H;
    static int W;
    static bool[,] Visited;
    static int Call = 0;
    static void Rec(int h, int w, long[] count)
    {
        Call++;
        if (Call > H * W) throw new Exception();
        if (S[h][w] == '.') count[0]++;
        else count[1]++;

        var dh = new int[] { -1, 0, 1, 0 };
        var dw = new int[] { 0, -1, 0, 1 };
        for (int d = 0; d < 4; d++)
        {
            var nh = h + dh[d];
            var nw = w + dw[d];
            if (0 <= nh && nh < H && 0 <= nw && nw < W)
            {
                if (Visited[nh, nw]) continue;
                if (S[h][w] != S[nh][nw])
                {
                    Visited[nh, nw] = true;
                    Rec(nh, nw, count);
                }
            }
        }
    }
    static Scanner sc = new Scanner();
}

