            if ((j_pos > 0) && (str[j_pos - 1][ k_pos] == str1))// Boardの中身が'.'だったら
            {
                SetNodeLs1(j_pos * width + k_pos, (j_pos-1) * width + k_pos);// リストlsに追加する
