        static int[] xdir = new int[] { 0, 0, -1, 1 };
        static int[] ydir = new int[] { -1, 1, 0, 0 };

        static long cntb, cntw;
        static long H, W;

        static void Main(string[] args)
        {
            var HW = Console.ReadLine().Split().Select(int.Parse).ToArray();
            H = HW[0];
            W = HW[1];
            S = new char[H][];
            for (int i = 0; i < H; i++)
            {
                S[i] = Console.ReadLine().ToCharArray();
            }

            var startpoint = new List<Tuple<int, int>>();
            var endpoint = new List<Tuple<int, int>>();

            long sum = 0;
            for (int h = 0; h < H; h++)
            {
                for (int w = 0; w < W; w++)
                {
                    if (S[h][w] == '.' || isChecked[h, w]) continue;
                    cntb = 0;
                    cntw = 0;
                    DFS(h, w);
                    sum += cntb * cntw;
                }
            }

            Console.WriteLine(sum);
