                }
            }

            bool[,] accessed = new bool[H + 2, W + 2];
            Queue<int> queR = new Queue<int>();
            Queue<int> queC = new Queue<int>();

            int[] dr = new int[4] { 1, 0, -1, 0 };
            int[] dc = new int[4] { 0, -1, 0, 1 };

            UnionFind uf = new UnionFind(H * W);
            for (int i = 1; i <= H; i++)
            {
                for (int j = 1; j <= W; j++)
                {
                    if (accessed[i, j]) continue;
                    queR.Enqueue(i);
                    queC.Enqueue(j);

                    while (queR.Count > 0)
                    {
                        int r = queR.Dequeue();
                        int c = queC.Dequeue();
                        accessed[r, c] = true;

                        for (int t = 0; t < 4; t++)
                        {
                            int nr = r + dr[t];
                            int nc = c + dc[t];
                            if (accessed[nr, nc]) continue;
                            if ((map[nr, nc] == '#' && map[r, c] == '.') || (map[nr, nc] == '.' && map[r, c] == '#'))
                            {
                                queR.Enqueue(nr);
                                queC.Enqueue(nc);

                                uf.Unite(Ind(r, c, W), Ind(nr, nc, W));
                            }
                        }
                    }
                }
            }

            int[] countA = new int[H * W];
            int[] countB = new int[H * W];
