    class Program
    {
        static void Main(string[] args)
        {
            int[] In = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            h = In[0];
            w = In[1];
            M = new char[h, w];
            for(int i=0; i < h; i++)
            {
                string In2 = Console.ReadLine();
                for(int j = 0; j < w; j++)
                {
                    M[i, j] = In2[j];
                }
            }
            ans = 0;
            //始める点(#)
            for(int i = 0; i < h; i++)
            {
                for(int j=0; j < w; j++)
                {
                    if (M[i, j] == '.') continue;
                    //終える点(.)
                    for (int x = 0; x < h; x++)
                    {
                        for(int y = 0; y < w; y++)
                        {
                            if (M[x, y] == '#') continue;
                            B = new bool[h, w];
                            dis = (int)(Math.Abs(i - x) + Math.Abs(j - y));
                            Chk(i, j, x, y, 0);
                        }
                    }
                }
            }
            Console.WriteLine(ans);
        }
        static public int h, w;
        static public int ans;
        static public char[,] M;
        static public bool[,] B;
        static public int dis;
        static public void Chk(int x1,int y1, int x2, int y2, int cnt)
        {
            if (cnt % 2 == 0) if (M[x1, y1] == '.') return;
            if (cnt % 2 == 1) if (M[x1, y1] == '#') return;
            if (dis == cnt)
            {
                if (x1 == x2 && y1 == y2 && !B[x1,y1]) { ans++; B[x1,y1]=true; }
                return;
            }
            cnt++;
            //上
            if (0 <= x1 - 1) Chk(x1 - 1, y1, x2, y2, cnt);
            //下
            if (x1 + 1 <  h) Chk(x1 + 1, y1, x2, y2, cnt);
            //左
            if (0 <= y1 - 1) Chk(x1, y1 - 1, x2, y2, cnt);
            //右
            if (y1 + 1 <  w) Chk(x1, y1 + 1, x2, y2, cnt);

        }

    }
}

