		static void Main()
		{
			var cin = new Scanner();
			int h = cin.Int();
			int w = cin.Int();
			var s = new string[h];
			for (int i = 0; i < h; i++) {
				s[i] = cin.Next();
			}

			var groups = new List<(int black, int white)>();
			var done = new bool[h, w];
			for (int i = 0; i < h; i++) {
				for (int j = 0; j < w; j++) {
					if (done[i, j]) {
						continue;
					}

					(int black, int white) group = (0, 0);
					var q = new Queue<(int y, int x, char color)>();
					q.Enqueue((i, j, s[i][j]));
					while (q.Count > 0) {
						var cur = q.Dequeue();
						if (done[cur.y, cur.x]) {
							continue;
						}

						done[cur.y, cur.x] = true;
						if (cur.color == '.') {
							group = (group.black, group.white + 1);
						} else {
							group = (group.black + 1, group.white);
						}

						Helper.DoAt4(cur.y, cur.x, h, w, (ii, jj) => {
							if (done[ii, jj] == false) {
								if (s[ii][jj] != s[cur.y][cur.x]) {
									q.Enqueue((ii, jj, s[ii][jj]));
								}
							}
						});
					}

					groups.Add(group);
				}
			}

			long ans = 0;
			foreach (var g in groups) {
				ans += (long)g.white * g.black;
			}

			Console.WriteLine(ans);
		}
