namespace MyConsoleAppAlternatingPath1112AC
{
    //
    // AlternatingPath 11.txt  12.txtがACだったプログラムを改良する
    //

    //
    // 構造体
    //
    public struct StartGoal
    {
        public int startpoint_X;
        public int startpoint_Y;
        public int goalpoint_X;
        public int goalpoint_Y;
    }
    class Program
    {
        static string[,] Board;
        static string[,] CheckS;

        static StartGoal sg;

        static List<StartGoal> ls1 = new List<StartGoal>();
        static List<StartGoal> ls2 = new List<StartGoal>();
        static List<StartGoal> ls3 = new List<StartGoal>();

        static void Main(string[] args)
        {
            //
            // 入力
            //
            // スペース区切りの整数の入力
            string[] input = Console.ReadLine().Split(' ');
            int h = int.Parse(input[0]); //高さＨ
            int w = int.Parse(input[1]); //幅Ｗ

            Board = new string[h, w];//２次元配列を準備しておく
            CheckS = new string[h, w];//到達した場所に印を付けておく

            string[] str = new string[h];//マスのデータを受け取る。行数分繰り返す
            // 文字列の入力
            for (int i = 0; i < str.Length; i++)
            {
                str[i] = Console.ReadLine();// 一行分のデータを受け取る
            }
            //
            // ここからプログラム本体
            //
            for (int j = 0; j < h; j++)// 配列の初期化と読み込んだデータのセット
            {
                for (int k = 0; k < w; k++)
                {
                    Board[j, k] = str[j].Substring(k, 1);
                    CheckS[j, k] = "?";
                }
            }
            //
            // "#"の位置から"."を探索してみる。見つけた"."の場所には印Gを付ける
            //

            ls1.Clear();// LISTを空にしておいて

            for (int j = 0; j < h; j++)
            {
                for (int k = 0; k < w; k++)
                {
                    if (Board[j, k] == "#")
                    {
                        Surrounding(j, k, h, w);// 周囲を探索するメソッドSurroundingを呼ぶ
                    }
                }
            }
            //
            // 変化がなくなるまでCombineを繰り返す
            //
            int tmp;
            do
            {
                tmp = ls3.Count;
                Combine(h, w);
                ls1.Clear();
                ls1.AddRange(ls3);
            } while (tmp != ls3.Count);
            //
            // 出力
            //
            Console.WriteLine(ls3.Count);
        }
        //
        // Main終わり
        //

        //
        // メソッド　Combine つながるデータはつなげる　#. →　#.#.にできないか調べるメソッド
        //
        public static void Combine(int hh, int ww)
        {
            int temp_X = 0;
            int temp_Y = 0;
            ls2.Clear();
            ls3.Clear();

            for (int p = 0; p < ls1.Count; p++)
            {
                if ((ls1[p].goalpoint_X > 0) && (ls1[p].goalpoint_X - 1 != ls1[p].startpoint_X))
                {
                    temp_X = ls1[p].goalpoint_X - 1;
                    temp_Y = ls1[p].goalpoint_Y;
                    SetNodeLs2(p, temp_X, temp_Y);
                }
                if ((ls1[p].goalpoint_Y > 0) && (ls1[p].goalpoint_Y - 1 != ls1[p].startpoint_Y))
                {
                    temp_X = ls1[p].goalpoint_X;
                    temp_Y = ls1[p].goalpoint_Y - 1;
                    SetNodeLs2(p, temp_X, temp_Y);
                }
                if ((ls1[p].goalpoint_X < (hh - 1)) && (ls1[p].goalpoint_X + 1 != ls1[p].startpoint_X))
                {
                    temp_X = ls1[p].goalpoint_X + 1;
                    temp_Y = ls1[p].goalpoint_Y;                    
                    SetNodeLs2(p, temp_X, temp_Y);
                }
                if ((ls1[p].goalpoint_Y < (ww - 1)) && (ls1[p].goalpoint_Y + 1 != ls1[p].startpoint_Y))
                {
                    temp_X = ls1[p].goalpoint_X;
                    temp_Y = ls1[p].goalpoint_Y + 1;
                    SetNodeLs2(p, temp_X,temp_Y);
                }
            }
            //
            // 確認
            //
            //Console.WriteLine("-----lsとls2を連結した後-----");
            ls1.AddRange(ls2);
            ls3 = ls1.Distinct().ToList();// 同じものを削除する
        }
        // メソッド　新たなノードをリストls2に書き込む
        public static void SetNodeLs2(int startNode, int temp_X, int temp_Y)
        {
            for (int j = 0; j < ls1.Count; j++)
            {
                if ((ls1[j].startpoint_X == temp_X) && (ls1[j].startpoint_Y == temp_Y))
                {
                    if ((ls1[j].goalpoint_X != ls1[startNode].goalpoint_X) || (ls1[j].goalpoint_Y != ls1[startNode].goalpoint_Y))
                    {
                        //Console.WriteLine(p.ToString()+"と"+q.ToString()+"を連結しましょう１");
                        //StartGoal sg = new StartGoal();
                        sg.startpoint_X = ls1[startNode].startpoint_X;
                        sg.startpoint_Y = ls1[startNode].startpoint_Y;
                        sg.goalpoint_X = ls1[j].goalpoint_X;
                        sg.goalpoint_Y = ls1[j].goalpoint_Y;
                        ls2.Add(sg);
                    }
                }
            }
        }
        //
        // メソッド　座標の前後左右を調べる
        // スタート地点　Ｓ
        // ゴール地点　Ｇ
        // Ｓ→Ｇのペアを調べてリストに登録する
        //
        public static void Surrounding(int j_pos, int k_pos, int hh, int ww)
        {
            string str1 = ".";
            string str2 = "G";//たどりついた場所に印をつけるスタート地点Ｓ、ゴール地点Ｇ
                              //
            CheckS[j_pos, k_pos] = "S";// スタート地点にＳをつける
                                       //
            if ((j_pos > 0) && (Board[j_pos - 1, k_pos] == str1))
            {
