    {
        public void Solve()
        {
            int H; int W;
            Multi(out H, out W);
            var map = new string[H].Select(s => GetStr().ToCharArray()).ToArray();

            var uf = new UnionFind(H * W);

            var dy = new int[] { 0, 1, 0, -1 };
            var dx = new int[] { 1, 0, -1, 0 };

            for(int y = 0; y < H; y++)
            {
                for(int x = 0; x < W; x++)
                {
                    for (int i = 0; i < 4; i++)
                    {
                        var ny = y + dy[i];
                        var nx = x + dx[i];
                        if (ny < 0 || H <= ny || nx < 0 || W <= nx) continue;
                        if (map[y][x] != map[ny][nx]) uf.Union(y * W + x, ny * W + nx);
                    }   
                }
            }
            var dic = new Dictionary<int, int[]>();
            for(int y = 0; y < H; y++)
            {
                for(int x = 0; x < W; x++)
                {
                    var pos = y * W + x;
                    var parent = uf.Find(pos);
                    if (dic.ContainsKey(parent) == false) dic.Add(parent, new int[2]);
                    if (map[y][x] == '#') dic[parent][0]++;
                    else dic[parent][1]++;
                }
            }
            long ans = 0;
            foreach (var d in dic) ans += d.Value[0] * (long)d.Value[1];
            Console.WriteLine(ans);


        }

        class UnionFind
        {
            // 親要素のインデックスを保持する
            // 親要素が存在しない(自身がルートである)とき、マイナスでグループの要素数を持つ
            int[] parents;
            public UnionFind(int n)
            {
                this.parents = new int[n];
                for (int i = 0; i < n; i++)
                {
                    // 初期状態ではそれぞれが別のグループ(ルートは自分自身)
                    // ルートなのでマイナスで要素数(1個)を保持する
                    this.parents[i] = -1;
                }
            }

            // 要素xのルート要素はどれか
            public int Find(int x)
            {
                // 親がマイナスの場合は自分自身がルート
                if (this.parents[x] < 0) return x;
                // ルートが見つかるまで再帰的に探す
                // 見つかったルートにつなぎかえる
                this.parents[x] = Find(this.parents[x]);
                return this.parents[x];
            }

            /// <summary>
            /// 要素xの属するグループの要素数を取得する
            /// </summary>
            /// <param name="x"></param>
            public int Size(int x)
            {
                // ルート要素を取得して、サイズを取得して返す
                return -this.parents[this.Find(x)];
            }

            // 要素x, yが同じグループかどうか判定する
            public bool Same(int x, int y)
            {
                return this.Find(x) == this.Find(y);
            }

            // 要素x, yが属するグループを同じグループにまとめる
            public bool Union(int x, int y)
            {
                // x, y のルート
                x = this.Find(x);
                y = this.Find(y);
                // すでに同じグループの場合処理しない
                if (x == y) return false;

                // 要素数が少ないグループを多いほうに書き換えたい
                if (this.Size(x) < this.Size(y))
                {
                    var tmp = x;
                    x = y;
                    y = tmp;
                }
                // まとめる先のグループの要素数を更新
                this.parents[x] += this.parents[y];
                // まとめられるグループのルートの親を書き換え
                this.parents[y] = x;
                return true;
            }
        }
    }
