public class Hello
{
    private const int INF = 1000000007;
    public static void Main()
    {
        int[] HW = IntLine();
        string[] s = new string[HW[0]];
        for (int i = 0; i < HW[0]; i++) s[i] = Console.ReadLine();

        int[] dx = new int[4] { -1, 0, 1, 0 };
        int[] dy = new int[4] { 0, -1, 0, 1 };
        long ans = 0;
        UnionFind uf = new UnionFind(HW[0] * HW[1]);
        for (int i = 0; i < HW[0]; i++)
        {
            for (int j = 0; j < HW[1]; j++)
            {
                for (int d = 0; d < 4; d++)
                {
                    int x = i + dx[d];
                    int y = j + dy[d];
                    if (x < 0 || HW[0] <= x || y < 0 || HW[1] <= y) continue;
                    if (s[i][j] != s[x][y]) uf.Unite(i * HW[1] + j, x * HW[1] + y);
                }
            }
        }

        int[] bc = new int[160000];
        int[] dc = new int[160000];
        for (int i = 0; i < HW[0]; i++)
        {
            for (int j = 0; j < HW[1]; j++)
            {
                if (s[i][j] == '.') dc[uf.Root(i * HW[1] + j)]++;
                else bc[uf.Root(i * HW[1] + j)]++;
            }
        }
        for (int i = 0; i < HW[0] * HW[1]; i++)
        {
            ans += bc[i] * dc[i];
        }
