    static readonly int[] dd = { 0, 1, 0, -1, 0 };
    const string dstring = "RDLU";
    static void Main()
    {
        int h, w;
        sc.Multi(out h, out w);
        var s = new string[h].Select(x => sc.Str).ToArray();
        var vis = new bool[h][];
        for (int i = 0; i < h; i++)
        {
            vis[i] = new bool[w];
        }
        long ans = 0;
        for (int i = 0; i < h; i++)
        {
            for (int j = 0; j < w; j++)
            {
                if (vis[i][j]) continue;
                var q = new Queue<P>();
                int wc = 0, bc = 0;
                vis[i][j] = true;
                if (s[i][j] == '#')  ++bc;
                else ++wc;
                q.Enqueue(new P(i, j));
                while (q.Any()) {
                    var p = q.Dequeue();
                    for (int k = 0; k < 4; k++)
