namespace MyConsoleAppAlternatingPath1112AC
{
    //
    // AlternatingPath 11.txt  12.txtがACだったプログラムを改良
    // 03,04,10,11,12 AC
    // 01,02,05～09 TLE
    //
    // 構造体
    //
    public struct StartGoal
    {
        public int startpoint_X;
        public int startpoint_Y;
        public int goalpoint_X;
        public int goalpoint_Y;
    }
    public struct SGNumber
    {
        public int start_Number;
        public int goal_Number;
    }

    class Program
    {
        static char[,] Board;// 読み込んだ#.を入れる
        static char[,] CheckS;//S:スタート地点　G:ゴール地点　?:到達できない所

        static StartGoal sg;
        static SGNumber sg_Number;

        static List<StartGoal> ls1 = new List<StartGoal>();
        static List<SGNumber> Ls_Temp = new List<SGNumber>(); // 作業用リスト

        static void Main(string[] args)
        {
            //
            // 入力
            //
            // スペース区切りの整数の入力
            string[] input = Console.ReadLine().Split(' ');
            int h = int.Parse(input[0]); //高さＨ
            int w = int.Parse(input[1]); //幅Ｗ

            Board = new char[h, w];//２次元配列を準備しておく
            CheckS = new char[h, w];//到達した場所に印を付けておく

            string[] str = new string[h];//マスのデータを受け取る。行数分繰り返す
            // 文字列の入力
            for (int i = 0; i < str.Length; i++)
            {
                str[i] = Console.ReadLine();// 一行分のデータを受け取る
            }
            //
            // ここからプログラム
            //
            for (int j = 0; j < h; j++)// 配列の初期化と読み込んだデータのセット
            {
                for (int k = 0; k < w; k++)
                {
                    Board[j, k] = str[j][k];// 入力された文字列".#."等から一文字ずつ取り出して保存する
                    CheckS[j, k] = '?';
                }
            }
            //
            // "#"の位置から"."を探索してみる。見つけた"."の場所には印Gを付ける
            //

            ls1.Clear();// LISTを空にしておいて

            for (int j = 0; j < h; j++)
            {
                for (int k = 0; k < w; k++)
                {
                    if (Board[j, k] == '#')
                    {
                        Surrounding(j, k, h, w);// 周囲を探索するメソッドSurroundingを呼ぶ
                    }
                }
            }
            //
            // スタート地点の数　＝"#"の中で隣に"."がある所の数を数える
            //
            int counter_S = 0;
            for (int j = 0; j < h; j++)
            {
                for (int k = 0; k < w; k++)
                {
                    //Console.Write(CheckS[j, k]);
                    if (CheckS[j, k] == 'S')
                    {
                        counter_S++;
                    }
                }
                //Console.WriteLine();
            }
            //Console.WriteLine(counter_S);// "#"のなかでＳになれる数

            //
            // start_Numberでグループ分けする
            //

            List<int>[] Ls = new List<int>[counter_S];//グループごとにint型の値を保存するリスト
            for (int k = 0; k < counter_S; k++)
            {
                Ls[k] = new List<int>();// 各グループ用のリストを準備する
            }
            for (int p = 0; p < ls1.Count; p++)
            {
                int S_nodeNumber = ls1[p].startpoint_X * w + ls1[p].startpoint_Y;
                int G_nodeNumber = ls1[p].goalpoint_X * w + ls1[p].goalpoint_Y;
                sg_Number.start_Number = S_nodeNumber;
                sg_Number.goal_Number = G_nodeNumber;
                Ls_Temp.Add(sg_Number);
            }

            bool[] done = new bool[Ls_Temp.Count];
            for (int r = 0; r < counter_S; r++)// rにグループ番号
            {
                for (int q = 0; q < Ls_Temp.Count; q++)// ノード番号の入ったリストLs_Temp <start_Number,goal_Number>                          
                {
                    if (done[q] == false)// まだ処理していないなら
                    {
                        if ((Ls[r].Count == 0) || (Ls[r].Contains(Ls_Temp[q].start_Number)) == true) // （グループの先頭）または（start_Numberが同じグループ）
                        {
                            Ls[r].Add(Ls_Temp[q].start_Number);
                            Ls[r].Add(Ls_Temp[q].goal_Number);
                            done[q] = true;
                        }
                    }
                }
            }

            Eliminator(counter_S, Ls); // 重複をなくす

            //
            // グループを結合する
            //

            int length_Ls = 0;
            List<int> workList = new List<int>();

            for (int i = 0; i < counter_S; i++)
            {
                label:
                length_Ls = Ls[i].Count;

                foreach (int member in Ls[i])
                {
                    for (int k = (i + 1); k < counter_S; k++)
                    {
                        if (Ls[k].Contains(member) == true)
                        {
                            workList.AddRange(Ls[k]);
                            Ls[k].Clear();
                        }
                    }
                }
                Ls[i].AddRange(workList);
                workList.Clear();
                if (length_Ls != Ls[i].Count)
                {
                    goto label;
                }
            }
            Eliminator(counter_S, Ls); // 重複をなくす eliminatorを呼ぶ

            int blockNumberH = 0;
            int blockNubmerW = 0;
            int answer = 0;
            int countBlack = 0;
            int countWhite = 0;
            for (int cx = 0; cx < counter_S; cx++)
            {
                foreach (int bx in Ls[cx])
                {
                    blockNumberH = bx / w;
                    blockNubmerW = bx % w;
                    if (Board[blockNumberH, blockNubmerW] == '#')
                    {
                        countBlack++;
                    }
                    else
                    {
                        countWhite++;
                    }
                }
                answer += (countBlack * countWhite);
                countBlack = 0;
                countWhite = 0;
            }
            //
            // 出力
            //
            Console.WriteLine(answer);
            /*
            for (int z = 0; z < counter_S; z++)
            {
                Console.Write("Ls[" + z + "]:");
                foreach (int fx in Ls[z])
                {
                    Console.Write(fx + " ");
                }
                Console.WriteLine();
                */
            /*
            Console.Write("LsCombineGroupList[" + z + "]:");
            foreach (int fx in LsCombineGroupList[z])
            {
                Console.Write(fx + " ");
            }
            Console.WriteLine();


            Console.Write("workList2[" + z + "]:");
            foreach (int ex in workList2[z])
            {
                Console.Write(ex + " ");
            }
            Console.WriteLine();
            */
            //Console.WriteLine();
        }
        //
        // Main終わり
        //

        //
        // 重複をなくすメソッド eliminate
        //
        public static void Eliminator(int counter_SS,List<int>[] Lss)
        {

            List<int> LsEnd2 = new List<int>();

            for (int s = 0; s < counter_SS; s++)
            {
                LsEnd2.Clear();
                foreach (int t in Lss[s])
                {
                    if (!LsEnd2.Contains(t))
                    {
                        LsEnd2.Add(t);
                    }
                }
                Lss[s].Clear();
                Lss[s].AddRange(LsEnd2);
            }
        }
        //
        // メソッド　座標の前後左右を調べる
        // スタート地点　Ｓ
        // ゴール地点　Ｇ
        // Ｓ→Ｇのペアを調べてリストに登録する
        //
        public static void Surrounding(int j_pos, int k_pos, int hh, int ww)
        {
            char str0 = 'S';
            char str1 = '.';
            char str2 = 'G';//たどりついた場所に印をつけるスタート地点Ｓ、ゴール地点Ｇ
            //
            if ((j_pos > 0) && (Board[j_pos - 1, k_pos] == str1))// Boardの中身が'.'だったら
            {
                CheckS[j_pos, k_pos] = str0;// スタート地点にＳをつける
                CheckS[j_pos - 1, k_pos] = str2;// Gをセットする
                SetNodeLs1(j_pos, k_pos, j_pos - 1, k_pos);// リストlsに追加する
            }
            if ((j_pos < (hh - 1)) && (Board[j_pos + 1, k_pos] == str1))
            {
                CheckS[j_pos, k_pos] = str0;// スタート地点にＳをつける
                CheckS[j_pos + 1, k_pos] = str2;// Gをセットする
                SetNodeLs1(j_pos, k_pos, j_pos +1, k_pos);
            }
            if ((k_pos > 0) && (Board[j_pos, k_pos - 1] == str1))
            {
                CheckS[j_pos, k_pos] = str0;// スタート地点にＳをつける
                CheckS[j_pos, k_pos - 1] = str2;// Gをセットする
                SetNodeLs1(j_pos, k_pos, j_pos, k_pos-1);
            }
            if ((k_pos < (ww - 1)) && (Board[j_pos, k_pos + 1] == str1))
            {
                CheckS[j_pos, k_pos] = str0;// スタート地点にＳをつける
                CheckS[j_pos, k_pos + 1] = str2;// Gをセットする
                SetNodeLs1(j_pos, k_pos, j_pos, k_pos+1);
            }
        }
        // メソッド SetNodeLs1
        public static void SetNodeLs1(int start_X, int start_Y, int goal_X, int goal_Y)
        {
            sg.startpoint_X = start_X;
            sg.startpoint_Y = start_Y;
            sg.goalpoint_X = goal_X;
            sg.goalpoint_Y = goal_Y;
            ls1.Add(sg); //リストに追加する
        }
    }
}

