    class UnionFind
    {
        private int[] Par, Rank;
        public UnionFind(int max)
        {
            Par = new int[max];
            Rank = new int[max];
            for (int i = 0; i < max; i++)
            {
                Par[i] = i;
            }
        }

        public int Find(int n)
        {
            if (Par[n] == n)
            {
                return n;
            }
            else
            {
                return Find(Par[n]);
            }
        }

        public bool Same(int a, int b)
        {
            return Find(a) == Find(b);
        }

        public void Union(int a, int b)
        {
            a = Find(a);
            b = Find(b);
            if (a == b) return;
            if (Rank[a] < Rank[b])
            {
                Par[a] = b;
            }
            else
            {
                Par[b] = a;
                if (Rank[a] == Rank[b]) Rank[a]++;
            }
        }
    }

    class Program
    {

        public void Solve()
        {
            var sc = new Scanner();
            var H = sc.NextInt();
            int W = sc.NextInt();
            char[][] S = sc.GetCharMatrix(H);
            var uf = new UnionFind(H * W);
            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    if (i < H - 1)
                    {
                        if (S[i + 1][j] != S[i][j])
                        {
                            uf.Union(i * W + j, (i + 1) * W + j);
                        }
                    }

                    if (j < W - 1)
                    {
                        if (S[i][j + 1] != S[i][j])
                        {
                            uf.Union(i * W + j, i * W + j + 1);
                        }
                    }
                }
            }

            var bMap = new Dictionary<int, long>();
            var wMap = new Dictionary<int, long>();
            for (int i = 0; i < H; i++)
            {
                for (int j = 0; j < W; j++)
                {
                    int f = uf.Find(i * W + j);
                    long b,w;
                    bMap.TryGetValue(f, out b);
                    wMap.TryGetValue(f, out w);
                    if ((i + j) % 2 == 0)
                    {          
                        bMap[f] = b + 1;
                        wMap[f] = w;
                    }
                    else
                    {
                        bMap[f] = b;
                        wMap[f] = w + 1;
                    }
                }
            }

            long ans = 0;
            foreach (var i in bMap)
            {
                ans += i.Value * wMap[i.Key];
            }
            Console.WriteLine(ans);
        }


        static void Main(string[] args) => new Program().Solve();
    }
}

using System.Collections.Generic;
using System;

public class UnionFind
{
    private int[] data;
    public UnionFind(int size)
    {
        data = new int[size];
        for (int i = 0; i < size; i++) data[i] = -1;
    }
    public bool Unite(int x, int y)
    {
        x = Root(x);
        y = Root(y);
        if (x != y)
        {
            if (data[y] < data[x])
            {
                var tmp = y;
                y = x;
                x = tmp;
            }
            data[x] += data[y];
            data[y] = x;
        }
        return x != y;
    }
    public bool IsSameGroup(int x, int y) => Root(x) == Root(y);
    public int Root(int x) => data[x] < 0 ? x : data[x] = Root(data[x]);
    public int getMem(int x) => -data[Root(x)];
}


