    static void getAns2(int h, int w, bool[,] map, int[,] sno, UnionFind uf)
    {
        var d = new Dictionary<int, int>();
        for (int i = 0; i < h; i++)
            for (int j = 0; j < w; j++)
            {
                var p = uf.Root(sno[i, j]);
                if (!d.ContainsKey(p)) d[p] = 0;
                if (map[i, j]) d[p]++;
            }
        var ans = 0;
        foreach (var x in d)
        {
            var t = uf.getMem(x.Key);
            ans += x.Value * (t - x.Value);
        }
