        public List<Cell> GetNextCells(Cell[,] S)
        {
            List<Cell> cells = new List<Cell>();
            Cell cu = S[X, Y - 1];
            Cell cd = S[X, Y + 1];
            Cell cl = S[X - 1, Y];
            Cell cr = S[X + 1, Y];
            Cell[] ccand = { cu, cd, cl, cr };

            foreach (Cell c in ccand)
            {
                if (color == '#')
                {
                    if (c.color == '.' && c.groupB < groupB)
                    {
                        cells.Add(c);
                        c.groupB = groupB;
                    }
                }
                else
                {
                    if (c.color == '#' && c.groupB == 0)
                    {
                        cells.Add(c);
                        c.groupB = groupB;
                    }
                }
            }
            return cells;
        }

    }

