var H, W int
var matrix [][]string
var memo map[pair]int

type pair struct {
	x, y int
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	fmt.Sscanf(scanner.Text(), "%d %d", &H, &W)

	matrix = make([][]string, H)
	for i := 0; i < len(matrix); i++ {
		matrix[i] = make([]string, W)
	}

	for i := 0; i < H; i++ {
		var str string
		scanner.Scan()
		fmt.Sscanf(scanner.Text(), "%s", &str)
		matrix[i] = strings.Split(str, "")
	}

	memo := make(map[pair]int)

	ans := 0
	for i := 0; i < H; i++ {
		for j := 0; j < W; j++ {
			if matrix[i][j] == "#" {
				if v, e := memo[pair{i, j}]; e {
					ans = ans + v
					// fmt.Println("memo", i, j)
					continue
				}

				done := make(map[pair]struct{})
				count := search(i, j, done, false)
				for p, _ := range done {
					if matrix[p.x][p.y] == "#" {
						// fmt.Println("add memo", p, count)
						memo[p] = count
					}
				}
				ans = ans + count
			}
		}
	}
	fmt.Println(ans)
}

var dif = [4]pair{pair{-1, 0}, pair{1, 0}, pair{0, -1}, pair{0, 1}}

func search(x, y int, done map[pair]struct{}, wantWhite bool) int {
	if x < 0 || y < 0 || x >= H || y >= W {
		return 0
	}
	if _, e := done[pair{x, y}]; e {
		return 0
	}

	count := 0
	if wantWhite && matrix[x][y] == "." {
		done[pair{x, y}] = struct{}{}

		count++ // for this "."
		for _, d := range dif {
			count = count + search(x+d.x, y+d.y, done, false)
		}
	} else if !wantWhite && matrix[x][y] == "#" {
		done[pair{x, y}] = struct{}{}

		for _, d := range dif {
			count = count + search(x+d.x, y+d.y, done, true)
		}
	}

	return count
}

