package main

import "fmt"

const (
	WHITE = '.'
	BLACK = '#'
)

func dfs(visited [][]bool, board []string, x, y int, color rune) int {
	visited[x][y] = true

	ret := 0
	if rune(board[x][y]) == color {
		if color == WHITE {
			ret++
		}
		for _, d := range [][]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}} {
			dx := x + d[0]
			dy := y + d[1]

			nextColor := WHITE
			if color == nextColor {
				nextColor = BLACK
			}

			if 0 <= dx && dx < len(board) && 0 <= dy && dy < len(board[0]) && visited[dx][dy] == false {
				ret += dfs(visited, board, dx, dy, nextColor)
			}
		}
	}

	return ret
}

func routes(board []string, x, y int, color rune) int {
	visited := make([][]bool, len(board))
	for i := range visited {
		visited[i] = make([]bool, len(board[0]))
	}

	return dfs(visited, board, x, y, color)
}

