type pos struct {
	x, y int
	c    bool
}

var dx = []int{-1, 1, 0, 0}
var dy = []int{0, 0, -1, 1}

func bsf(sx, sy, c int) (int, int) {
	q := make([]pos, 0)
	q = append(q, pos{sx, sy, true})
	u[sy][sx] = c
	b := 1
	w := 0
	for len(q) != 0 {
		cx := q[0].x
		cy := q[0].y
		black := q[0].c
		q = q[1:]
		for i := 0; i < 4; i++ {
			x := cx + dx[i]
			y := cy + dy[i]
			if x < 0 || x >= W || y < 0 || y >= H {
				continue
			}
			if black == true && s[y][x] == '#' {
				continue
			}
			if black == false && s[y][x] == '.' {
				continue
			}
			if u[y][x] != 0 {
				continue
			}
			u[y][x] = c
			if s[y][x] == '#' {
				b++
			} else {
				w++
			}
			q = append(q, pos{x, y, !black})
		}
	}
	return b, w
}

