var queueX []int
var queueY []int

func s(h int, w int, check [][]int) {
	check[h][w]++
	queueX = make([]int, 0)
	queueY = make([]int, 0)
	queueX = append(queueX, w)
	queueY = append(queueY, h)
	idx := 0
	for len(queueX) > idx {
