					continue
				}
				if S[ny][nx] != S[h][w] {
					if S[ny][nx] == '.' {
						cnt++
					} else {
						pass[ny][nx]++
						blackCnt++
					}
					check[ny][nx]++
					queueX = append(queueX, nx)
					queueY = append(queueY, ny)
				}
			}
		}
	}
}

