var DEBUG = true

func main() {
	defer Flush()
	H := readi()
	W := readi()
	S := make([][]byte, H)
	for i := range S {
		S[i] = readb()
	}

	visited := make([][]bool, H)
	for i := range visited {
		visited[i] = make([]bool, W)
	}

	var ans int
	for i := range S {
		for j := range S[i] {
			if S[i][j] == '.' || visited[i][j] {
				continue
			}
			w, b := dfs(H, W, S, visited, i, j)
			ans += w * b
		}
	}
	println(ans)
}

func dfs(H, W int, S [][]byte, visited [][]bool, y, x int) (int, int) {
	visited[y][x] = true
	dx := []int{-1, 0, 1, 0}
	dy := []int{0, -1, 0, 1}
	white, black := 0, 0
	for i := range dx {
		ny := y + dy[i]
		nx := x + dx[i]
		if ny < 0 || H <= ny || nx < 0 || W <= nx || visited[ny][nx] || S[ny][nx] == S[y][x] {
			continue
		}
		w, b := dfs(H, W, S, visited, ny, nx)
		white += w
		black += b
	}

	if S[y][x] == '#' {
		return white, black + 1
	} else {
		return white + 1, black
	}
}

