package main

import "fmt"

const (
	WHITE = '.'
	BLACK = '#'
)

func dfs(board []string, kinds [][]int, x, y int, index int, color rune) {
	if rune(board[x][y]) == color {
		kinds[x][y] = index

		for _, d := range [][]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}} {
			dx := x + d[0]
			dy := y + d[1]
			nextColor := WHITE
			if color == nextColor {
				nextColor = BLACK
			}

			if 0 <= dx && dx < len(board) && 0 <= dy && dy < len(board[0]) && kinds[dx][dy] == 0 {
				dfs(board, kinds, dx, dy, index, nextColor)
			}
		}

	}
}

func routes(board []string, kinds [][]int, x, y int, index int) {
	dfs(board, kinds, x, y, index, rune(board[x][y]))
}

