		fmt.Scan(&board[i])
	}

	kinds := make([][]int, len(board))
	for i := range kinds {
		kinds[i] = make([]int, len(board[0]))
	}

	index := 1
	for i := range board {
		for j := range board[i] {
			if kinds[i][j] == 0 {
				routes(board, kinds, i, j, index)
				index++
			}
		}
	}

	m := map[int]*pair{}
	for i := range board {
