var dif = [4]pair{pair{-1, 0}, pair{1, 0}, pair{0, -1}, pair{0, 1}}

func search(x, y int, done map[pair]struct{}, wantWhite bool) int {
	if x < 0 || y < 0 || x >= H || y >= W {
		return 0
	}
	if _, e := done[pair{x, y}]; e {
		return 0
	}
	done[pair{x, y}] = struct{}{}

	count := 0
	if wantWhite && matrix[x][y] == "." {
		count++ // for this "."
		for _, d := range dif {
			count = count + search(x+d.x, y+d.y, done, false)
		}
	} else if !wantWhite && matrix[x][y] == "#" {
		for _, d := range dif {
			count = count + search(x+d.x, y+d.y, done, true)
		}
	}

	return count
}

