var logger = log.New(os.Stderr, "", 0)

func solve(h, w int, stage []string) (ans int) {
	visited := make([][]bool, h)
	for i := range visited {
		visited[i] = make([]bool, w)
	}
	for x := 0; x < h; x++ {
		for y := 0; y < w; y++ {
			if visited[x][y] {
				continue
			}
			ans += bfs(x, y, visited, stage)
		}
	}
	return ans
}

func bfs(x, y int, visited [][]bool, stage []string) int {
	h, w := len(stage), len(stage[0])
	count := make(map[byte]int, 2)
	q := newQueue()
	visited[x][y] = true
	count[stage[x][y]]++
	q.push(pair{x, y})
	for len(*q) > 0 {
		p := q.pop()
		for i := range dx {
			nx, ny := p.x+dx[i], p.y+dy[i]
			if nx < 0 || h <= nx || ny < 0 || w <= ny {
				logger.Println("continue: out of range", nx, ny)
				continue
			}
			if visited[nx][ny] {
				logger.Println("continue: already visited", nx, ny)
				continue
			}
			if stage[nx][ny] == stage[p.x][p.y] {
				logger.Println("continue: same color", nx, ny)
				continue
			}
			logger.Printf("visit: (%d,%d)->(%d,%d)\n", p.x, p.y, nx, ny)
			visited[nx][ny] = true
			count[stage[nx][ny]]++
			q.push(pair{nx, ny})
		}
	}
	return count['#'] * count['.']
}

