func main() {
	fp := os.Stdin
	wfp := os.Stdout

	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
		if len(os.Args) > 2 {
			wfp, _ = os.Create(os.Args[2])
		}
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	h := getNextInt(scanner)
	w := getNextInt(scanner)
	grid := make([]string, h)

	for i := 0; i < h; i++ {
		grid[i] = getNextString(scanner)
	}

	cnt := h * w
	color := make([]int, cnt)
	for i := 0; i < cnt; i++ {
		color[i] = i
	}

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			if y > 0 && grid[y][x] != grid[y-1][x] {
				r1 := root(y*w+x, color)
				r2 := root((y-1)*w+x, color)
				if r1 != r2 {
					color[r2] = r1
				}
			}
			if x > 0 && grid[y][x] != grid[y][x-1] {
				r1 := root(y*w+x, color)
				r2 := root(y*w+x-1, color)
				if r1 != r2 {
					color[r2] = r1
				}
			}
		}
	}

	sum := makeInts(cnt, 2)
	ans := 0
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			r := root(y*w+x, color)
			if grid[y][x] == '#' {
				sum[r][0]++
				continue
			}
			sum[r][1]++
		}
	}

	for i := 0; i < cnt; i++ {
		ans += sum[i][0] * sum[i][1]
	}

	fmt.Fprintln(writer, ans)

	writer.Flush()
}

func makeInts(h, w int) [][]int {
	index := make([][]int, h, h)
	data := make([]int, h*w, h*w)
	for i := 0; i < h; i++ {
		index[i] = data[i*w : (i+1)*w]
	}
	return index
}

func root(i int, color []int) int {
	if i == color[i] {
		return i
	}
	color[i] = root(color[i], color)
	return color[i]
}

