type Pos struct {
	y    int
	x    int
	turn int
}

func main() {
	vec := []int{1, 0, -1, 0}
	sc := NewScanner()
	H, W := sc.NextInt(), sc.NextInt()
	S := make([]string, H)

	field := make([][]int, H)
	for i := 0; i < H; i++ {
		field[i] = make([]int, W)
	}
	bfs := func(i, j, group int) (int, int) {
		queue := []Pos{}
		queue = append(queue, Pos{i, j, 0})
		black := 1
		white := 0
		field[i][j] = group
		for p := 0; p < len(queue); p++ {
			p := queue[p]

			for k := 0; k < len(vec); k++ {

				y := p.y + vec[k]
				x := p.x + vec[(k+1)%len(vec)]

				if x < 0 || x >= W {
					continue
				}
				if y < 0 || y >= H {
					continue
				}
				if field[y][x] > 0 {
					continue
				}
				if p.turn%2 == 0 && S[y][x] == '#' {
					continue
				}
				if p.turn%2 == 1 && S[y][x] == '.' {
					continue
				}
				queue = append(queue, Pos{y, x, p.turn + 1})
				if S[y][x] == '.' {
					white++
				} else {
					black++
				}
				field[y][x] = group
			}
		}

		return black, white
	}

	for i := 0; i < H; i++ {
		S[i] = sc.NextLine()
	}

	group := 1
	total := 0
	for i := 0; i < H; i++ {
		for j := 0; j < W; j++ {
			if S[i][j] == '.' || field[i][j] > 0 {
				continue
			}

			black, white := bfs(i, j, group)
			total += black * white
			group++
		}
	}
	fmt.Println(total)
}

type Scanner struct {
	r   *bufio.Reader
	buf []byte
	p   int
}

func NewScanner() *Scanner {
	rdr := bufio.NewReaderSize(os.Stdin, 1000)
	return &Scanner{r: rdr}
}
func (s *Scanner) Next() string {
	s.pre()
	start := s.p
	for ; s.p < len(s.buf); s.p++ {
		if s.buf[s.p] == ' ' {
			break
		}
	}
	result := string(s.buf[start:s.p])
	s.p++
	return result
}
func (s *Scanner) NextLine() string {
	s.pre()
	start := s.p
	s.p = len(s.buf)
	return string(s.buf[start:])
}
func (s *Scanner) NextInt() int {
	v, _ := strconv.Atoi(s.Next())
	return v
}
func (s *Scanner) NextInt64() int64 {
	v, _ := strconv.ParseInt(s.Next(), 10, 64)
	return v
}

func (s *Scanner) NextIntArray() []int {
	s.pre()
	start := s.p
	result := []int{}
	for ; s.p < len(s.buf)+1; s.p++ {
		if s.p == len(s.buf) || s.buf[s.p] == ' ' {
			v, _ := strconv.ParseInt(string(s.buf[start:s.p]), 10, 0)
			result = append(result, int(v))
			start = s.p + 1
		}
	}

	return result
}
func (s *Scanner) NextInt64Array() []int64 {
	s.pre()
	start := s.p
	result := []int64{}
	for ; s.p < len(s.buf)+1; s.p++ {
		if s.p == len(s.buf) || s.buf[s.p] == ' ' {
			v, _ := strconv.ParseInt(string(s.buf[start:s.p]), 10, 64)
			result = append(result, v)
			start = s.p + 1
		}
	}
	return result
}

func (s *Scanner) NextMap() map[int]bool {
	s.pre()
	start := s.p
	mp := map[int]bool{}
	for ; s.p < len(s.buf); s.p++ {
		if s.buf[s.p] == ' ' {
			v, _ := strconv.Atoi(string(s.buf[start:s.p]))
			mp[v] = true
			start = s.p + 1
		}
	}
	v, _ := strconv.Atoi(string(s.buf[start:s.p]))
	mp[v] = true

	return mp
}

func (s *Scanner) pre() {
	if s.p >= len(s.buf) {
		s.readLine()
		s.p = 0
	}
}
func (s *Scanner) readLine() {
	s.buf = make([]byte, 0)
	for {
		l, p, e := s.r.ReadLine()
		if e != nil {
			panic(e)
		}
		s.buf = append(s.buf, l...)
		if !p {
			break
		}
	}
}

