type queue []pair

func newQueue() *queue {
	return &queue{}
}

func (q *queue) push(p pair) {
	*q = append(*q, p)
}

func (q *queue) pop() pair {
	p := (*q)[0]
	*q = (*q)[1:]
	return p
}

