	i, _ := strconv.ParseFloat(getNextString(scanner), 64)
	return i
}

func main() {
	fp := os.Stdin
	wfp := os.Stdout

	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
		if len(os.Args) > 2 {
			wfp, _ = os.Create(os.Args[2])
		}
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	h := getNextInt(scanner)
	w := getNextInt(scanner)
	grid := make([]string, h)

	for i := 0; i < h; i++ {
		grid[i] = getNextString(scanner)
	}

	color := makeInts(h, w)

	c := 0

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			if y > 0 && grid[y][x] != grid[y-1][x] {
				color[y][x] = color[y-1][x]
				continue
			}
			if x > 0 && grid[y][x] != grid[y][x-1] {
				color[y][x] = color[y][x-1]
				continue
			}
			c++
			color[y][x] = c
		}
	}

	sum := makeInts(c, 2)
	ans := 0
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			if grid[y][x] == '#' {
				sum[color[y][x]-1][0]++
				continue
			}
			sum[color[y][x]-1][1]++
		}
	}

	for i := 0; i < c; i++ {
		ans += sum[i][0] * sum[i][1]
	}

	fmt.Fprintln(writer, ans)

	writer.Flush()
}

func makeInts(h, w int) [][]int {
	index := make([][]int, h, h)
	data := make([]int, h*w, h*w)
	for i := 0; i < h; i++ {
		index[i] = data[i*w : (i+1)*w]
	}
	return index
}

