func sub(i, j int, r rune) {
	memo[i][j] = true

	steps := [][]int{
		[]int{0, 1},
		[]int{1, 0},
		[]int{-1, 0},
		[]int{0, -1},
	}

	for _, step := range steps {
		dy, dx := step[0], step[1]
		y, x := i+dy, j+dx
		if 0 <= y && y < h && 0 <= x && x < w && !memo[y][x] && r != S[y][x] {
			if S[y][x] == '.' {
				whiteNum++
			} else {
				blackNum++
			}
			sub(y, x, S[y][x])
		}
	}
}

func clearMemo() {
	memo = [][]bool{}
	for i := 0; i < h; i++ {
