func visited(i, j int) bool {
	return v[i+1][j+1]
}
func visit(i, j int) {
	v[i+1][j+1] = true
}

func main() {
	defer stdout.Flush()
	h := readInt()
	w := readInt()
	s = make([][]byte, h)
	v = make([][]bool, h+2)
	v[0] = make([]bool, w+2)
	v[h+1] = make([]bool, w+2)
	for i := range v[0] {
		v[0][i] = true
		v[h+1][i] = true
	}
	for i := range s {
		s[i] = []byte(readString())
		v[i+1] = make([]bool, w+2)
		v[i+1][0] = true
		v[i+1][w+1] = true
	}

	var ans int64
	for i := 0; i < h; i++ {
		for j := 0; j < w; j++ {
			b, w := rec('#', i, j)
			ans += b * w
		}
	}
	println(ans)
}

func rec(c byte, i, j int) (bsum int64, wsum int64) {
	if visited(i, j) {
		return 0, 0
	}
	if s[i][j] != c {
		return 0, 0
	}
	visit(i, j)
	if c == '#' {
		bsum++
	} else {
		wsum++
	}
	nc := byte('#')
	if c == '#' {
		nc = '.'
	}
	for k := range dys {
		ni := i + dys[k]
		nj := j + dxs[k]
		b, w := rec(nc, ni, nj)
		bsum += b
		wsum += w
	}
	return bsum, wsum
}

