type UnionFind struct {
	par []int
}

func newUnionFind(N int) *UnionFind {
	u := new(UnionFind)
	u.par = make([]int, N)
	for i := range u.par {
		u.par[i] = -1
	}
	return u
}
func (u UnionFind) root(x int) int {
	if u.par[x] < 0 {
		return x
	}
	u.par[x] = u.root(u.par[x])
	return u.par[x]
}
func (u UnionFind) unite(x, y int) {
	xr := u.root(x)
	yr := u.root(y)
	if xr == yr {
		return
	}
	u.par[yr] += u.par[xr]
	u.par[xr] = yr
}
func (u UnionFind) same(x, y int) bool {
	if u.root(x) == u.root(y) {
		return true
	}
	return false
}
func (u UnionFind) size(x int) int {
	return -u.par[u.root(x)]
}

class UnionFind{
  treeset: {parent?:number, size:number}[];
  constructor(size){
      this.treeset=new Array(size);
      this.treeset.fill({size:1});
  }
  union(x:number, y:number){
      const rootX=this.find(x);
      const rootY=this.find(y);
      if(rootX!=null && rootX==rootY){
          return;
      }else{
          const sizeX=this.size(x);
          const sizeY=this.size(y);
          if(sizeX>sizeY){
              this.treeset[rootY].parent = rootX;
              this.treeset[rootX].size += this.treeset[rootY].size;
          }else{
              this.treeset[rootX].parent = rootY;
              this.treeset[rootY].size += this.treeset[rootX].size;
          }
      }
  }
  //x should be root
  size(x:number){
      return this.treeset[x].size;
  }
  find(x:number):number{
      let parent = this.treeset[x].parent;
      if(parent==null){
          return x;
      }else{
        const root = this.find(parent);
        this.treeset[x].parent=root;
        return root;
      }
  }
}
