  let enc i j = i*w+j in
  UnionFind_i32.(
    let uf = init (h*w) in
    let k0,k1 = make (h*w) 0,make (h*w) 0 in
    iteri (fun i -> String.iteri (fun j c ->
      (if c='#' then k0 else k1).(enc i j) <- 1)) m;
    iteri (fun i ->
      String.iteri (fun j _ ->
        for k=0 to 1 do
          let s,t = i+k,j+1-k in
          if
            0<=s && s<=h-1 &&
            0<=t && t<=w-1 &&
            m.(s).[t] <> m.(i).[j] &&
            not @@ same_destructive (enc i j) (enc s t) uf
          then (
            (* Printf.printf " %d %d (%d) -- %d %d (%d)\n" i j (enc i j) s t (enc s t) ; *)
            let u,v =
              root_destructive (enc i j) uf,
              root_destructive (enc s t) uf in
            let w = k0.(u) in
            k0.(u) <- k0.(u) + k0.(v);
            k0.(v) <- k0.(v) + w;
            let w = k1.(u) in
            k1.(u) <- k1.(u) + k1.(v);
            k1.(v) <- k1.(v) + w;
            connect_destructive (enc i j) (enc s t) uf
          )
        done;
      )
    ) m;
    fold_left (fun (sum,i) _ ->
      if is_root i uf then (
        let u,v = k0.(i),k1.(i) in
        (sum + u*v, i+1)
      ) else (sum, i+1)
    ) (0,0) uf
    |> fst |> print_int)))

