use v5.18;
use warnings;
  use DDP +{ deparse => 1, use_prototypes => 0 };
use List::Util qw( sum );
sub read_line { chomp(my $s = <>); $s }
sub splited_read_line { split / /, read_line }
sub unique { my %u; $u{$_} = $_ for @_; values %u; }

package UnionFind {

  sub new {
    my ($class, $n) = @_;
    bless +{
      size => $n,
      par  => [ 0 .. $n - 1 ],
      rank => [ (0) x $n ],
    }, $class;
  }

  sub size { shift->{size} }

  sub root {
    my ($self, $x) = @_;
    $self->{par}[$x] == $x ? $x : ( $self->{par}[$x] = $self->root($self->{par}[$x]) );
  }

  sub unite {
    my ($self, $x, $y) = @_;
    my ($x_root, $y_root) = ($self->root($x), $self->root($y));
    return if $x_root == $y_root;
    if ( $self->{rank}[$x_root] < $self->{rank}[$y_root] ) {
      $self->{par}[$x_root] = $y_root;
    }
    else {
      $self->{par}[$y_root] = $x_root;
      $self->{rank}[$x_root]++ if $self->{rank}[$x_root] == $self->{rank}[$y_root];
    }
  }

  sub is_same {
    my ($self, $x, $y) = @_;
    $self->root($x) == $self->root($y);
  }

  sub roots {
    my $self = shift;
    [ map { $self->root($_) } 0 .. $#{ $self->{par} } ];
  }

}

my ($h, $w) = splited_read_line;
my $mass = [ map { [ split //, read_line ] } 0 .. $h - 1 ];
say solve($h, $w, $mass);

sub solve {
  my ($h, $w, $mass) = @_;
  my $tree = UnionFind->new($h * $w);
  for my $y (0 .. $h - 1) {
    for my $x (0 .. $w - 1) {
      my $current = $y * $w + $x;
      next if $mass->[$y][$x] eq '.';
      my $points = [
        [ $y + 1, $x ],
        [ $y - 1, $x ],
        [ $y, $x + 1 ],
        [ $y, $x - 1 ],
      ];
      for my $point (@$points) {
        my ($y, $x) = @$point;
        if ( $y < $h && $y >= 0 && $x < $w && $x >= 0 && $mass->[$y][$x] eq '.' ) {
          $tree->unite($current, $y * $w + $x);
        }
      }
    }
  }
  my @roots = @{ $tree->roots };
  my @vertexes = unique @roots;
  sum map {
    my $vertex = $_;
    my @points = grep { $vertex == $roots[$_] } 0 .. $tree->size - 1;
    my $colors = join '', map {
      my $y = int($_ / $w);
      my $x = $_ % $w;
      $mass->[$y][$x];
    } @points;
    my $black = () = $colors =~ /#/g;
    my $white = () = $colors =~ /\./g;
    $black * $white;
  } @vertexes;
}

