#= Global values ====================================================#
my ($H, $W);
my @g_field;
my @g_chkedField;
my @startMark;
my @detect;
my $g_detCnt = 0;

#= Local routines ===================================================#
# 1ならチェック済み、0なら未チェック
sub isChked{
	my $i = shift;
	my $j = shift;

	if (($i < 0) || ($H <= $i)){
		return 1;
	}
	if (($j < 0) || ($W <= $j)){
		return 1;
	}
	if ($g_chkedField[$i]){
		return $g_chkedField[$i]->[$j];
	}else{
		return 0;
	};
}

sub nextChk{
	my $i = shift;
	my $j = shift;
	my $expMark = shift;
	my $moveList = shift;

	my $mark = $g_field[$i]->[$j];
	if ($expMark eq $mark){
		if ($expMark eq "."){
			# ここで条件合致
			$g_detCnt++;
		}

		$g_chkedField[$i]->[$j] = 1;

		my $nextMark = ($mark eq ".")? "#" : "." ;
		# 上右下左
		# 上をチェックする
		if ($moveList & 0x8){
			if (!isChked($i-1, $j)){
				nextChk($i-1, $j, $nextMark, 0xD);
			}
		}
		# 右をチェックする
		if ($moveList & 0x4){
			if (!isChked($i, $j+1)){
				nextChk($i, $j+1, $nextMark, 0xE);
			}
		}
		# 下をチェックする
		if ($moveList & 0x2){
			if (!isChked($i+1, $j)){
				nextChk($i+1, $j, $nextMark, 0x7);
			}
		}
		# 左をチェックする
		if ($moveList & 0x1){
			if (!isChked($i, $j-1)){
				nextChk($i, $j-1, $nextMark, 0xB);
			}
		}
	}


}

sub main(){
	my $in = <>;chomp $in;
	($H, $W) = split(/ /, $in);

	foreach (1..$H){
		$in = <>; chomp $in;
		$g_field[$_ - 1] = [split(//, $in)];
	}

	foreach my $i (1..$H){
		foreach my $j (1..$W){
			my $nextMark = $g_field[$i-1]->[$j-1];
			if ($nextMark eq "#"){
				$startMark[0] = $i - 1;
				$startMark[1] = $j - 1;
				$startMark[2] = $nextMark;
				@g_chkedField = ();
				foreach my $a (1..$H){
					$g_chkedField[$a-1] = [];
					foreach my $b (1..$W){
						$g_chkedField[$a-1]->[$b-1] = 0;
					}
				}
				nextChk($i - 1, $j - 1, $nextMark, 0xF);
			}
		}
	}

	print $g_detCnt, "\n";

	return 0;
}

