package UnionFind {

  sub new {
    my ($class, $n) = @_;
    bless [ 0 .. $n - 1 ], $class;
  }

  sub root {
    my ($self, $x) = @_;
    if ( $self->[$x] == $x ) {
      $x;
    }
    else {
      $self->[$x] = $self->root($self->[$x]);
    }
  }

  sub unite {
    my ($self, $x, $y) = @_;
    my ($x_root, $y_root) = ($self->root($x), $self->root($y));
    if ( $x_root == $y_root ) {
      return;
    }
    else {
      $self->[$x_root] = $y_root;
    }
  }

  sub is_same {
    my ($self, $x, $y) = @_;
    $self->root($x) == $self->root($y);
  }

  sub compression {
    my $self = shift;
    $self->root($_) for 0 .. $#$self;
  }

}

my ($h, $w) = splited_read_line;
my $mass = [ map { [ split //, read_line ] } 0 .. $h - 1 ];
