sub solve {
  my ($h, $w, $mass) = @_;
  my $tree = UnionFind->new($h * $w);
  for my $y (0 .. $h - 1) {
    for my $x (0 .. $w - 1) {
      my $current        = $y * $w + $x;
      my $current_coloor = $mass->[$y][$x];
      next if $current_coloor eq '.';
      my $points = [
        [ $y + 1, $x ],
        [ $y - 1, $x ],
        [ $y, $x + 1 ],
        [ $y, $x - 1 ],
      ];
      for my $point (@$points) {
        my ($y, $x) = @$point;
        if (
          $y < $h && $y >= 0 && $x < $w && $x >= 0 &&
          $current_coloor ne $mass->[$y][$x]
        ) {
          $tree->unite($y * $w + $x, $current);
        }
      }
    }
  }
  $tree->compression;
  my @vertexes = unique @$tree;
  sum map {
    my $vertex = $_;
    my @points = grep { $vertex == $tree->[$_] } 0 .. $#$tree;
    my $colors = join '', map {
      my $y = int($_ / $w);
      my $x = $_ % $w;
      $mass->[$y][$x];
    } @points;
    my $black = () = $colors =~ /#/g;
    my $white = () = $colors =~ /\./g;
    $black * $white;
  } @vertexes;
}

