    long[] dely = [-1, 0, 1, 0], delx = [0, 1, 0, -1];
    long result;
    void bfs(long y, long x)
    {
        Grid[] que;
        que ~= Grid(y, x);
        seen[y][x] = true;
        long black, white;
        if (s[y][x] == '#') ++black;
        else ++white;
        while (!que.empty)
        {
            Grid now = que.front;
            que.popFront;
