                Grid nxt = now;
                nxt.y += dy, nxt.x += dx;
                if (nxt.y < 0 || h <= nxt.y || nxt.x < 0 || w <= nxt.x) continue;
                if (seen[nxt.y][nxt.x]) continue;
                if (s[nxt.y][nxt.x] == s[now.y][now.x]) continue;

                que ~= nxt;
                seen[nxt.y][nxt.x] = true;
                if (s[nxt.y][nxt.x] == '#') ++black;
                else ++white;
            }
        }
        result += black * white;
    }

    foreach (i; 0 .. h)
    {
        foreach (j; 0 .. w)
        {
            if (!seen[i][j]) bfs(i, j);
        }
    }

    result.writeln;
