int[] di = [1, 0, -1, 0];
int[] dj = [0, 1, 0, -1];

void main() {
    int h, w;
    scan(h, w);
    auto ban = iota(h).map!(i => readln.chomp).array;

    int black, white;
    auto visited = new bool[][](h, w);

    // 0 : #, 1 : .
    void dfs(int i, int j, int bh) {
        visited[i][j] = true;
        if (bh) {
            white++;
        }
        else {
            black++;
        }

        foreach (k ; 0 .. 4) {
            int ni = i + di[k];
            int nj = j + dj[k];

            if (ni < 0 || ni >= h || nj < 0 || nj >= w) continue;
            if (visited[ni][nj]) continue;
            if (bh && ban[ni][nj] != '#') continue;
            if (!bh && ban[ni][nj] != '.') continue;
            dfs(ni, nj, bh ^ 1);
        }
    }

    long ans;

    foreach (i ; 0 .. h) {
        foreach (j ; 0 .. w) {
            if (ban[i][j] == '#' && !visited[i][j]) {
                black = white = 0;
                dfs(i, j, 0);
                debug {
                    writefln("%(%(%b %)\n%)", visited);
                }
                debug {
                    writefln("(%d, %d), %d, %d", i, j, black, white);
                }
                ans += 1L * black * white;
            }
        }
    }

    writeln(ans);
}


