void dfs(long y, long x, char m, ref long a, ref long b) {
  if (field[y][x] == m) {
    a++;
  } else {
    b++;
  }
  used[y][x] = 1;

  if (y - 1 >= 0 && field[y][x] != field[y-1][x] && used[y-1][x] == 0) { 
    dfs(y - 1, x, m, a, b);
  }
  if (x - 1 >= 0 && field[y][x] != field[y][x-1] && used[y][x-1] == 0) {
    dfs(y, x - 1, m, a, b);
  }
  if (y + 1 < h && field[y][x] != field[y+1][x] && used[y+1][x] == 0) { 
    dfs(y + 1, x, m, a, b);
  }
  if (x + 1 < w && field[y][x] != field[y][x+1] && used[y][x+1] == 0) {
    dfs(y, x + 1, m, a, b);
  }

}


