long calc(string[] g) {
    int rows = cast(int) g.length;
    int cols = cast(int) g[0].length;

    auto hash = (int row, int col) => row * cols + col;

    auto uf = new UnionFind(rows * cols);
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (i + 1 < rows && g[i][j] != g[i + 1][j])
                uf.unite(hash(i, j), hash(i+1, j));

            if (j + 1 < cols && g[i][j] != g[i][j + 1])
                uf.unite(hash(i, j), hash(i, j+1));
        }
    }

    long ans = 0;
    bool[int] used;
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            int root = uf.root(hash(i, j));
            if (root in used) continue;
            used[root] = true;

            long a = 0; // 黒の個数
            long b = 0; // 白の個数
            // root に属する全てのノード
            uf.doEach(root, (node) {
                int row = node / cols;
                int col = node % cols;
                if (g[row][col] == '#') a++; else b++;
            });
            ans += a * b;
        }
    }
    return ans;
}

