    auto uf = new UnionFind(h * w);
    foreach (i; iota(h))
    {
        foreach (j; iota(w))
        {
            if (i - 1 >= 0 && s[i - 1][j] != s[i][j])
                uf.unit(convIdx(i - 1, j), convIdx(i, j));

            if (i + 1 < h && s[i + 1][j] != s[i][j])
                uf.unit(convIdx(i + 1, j), convIdx(i, j));

            if (j - 1 >= 0 && s[i][j - 1] != s[i][j])
                uf.unit(convIdx(i, j - 1), convIdx(i, j));

            if (j + 1 < w && s[i][j + 1] != s[i][j])
                uf.unit(convIdx(i, j + 1), convIdx(i, j));
        }
    }
    Pair[long] countBW;
    foreach (i; iota(h))
    {
        foreach (j; iota(w))
        {
