import numpy as np

def solve():
    H, W  = map(int,input().split())
    S = list()
    for _ in range(H):
        S.append([1 if a == '#' else 0 for a in input()])
    S = np.array(S)
    h, w = np.where(S==1)
    V1 = list(zip(h,w))
    h, w = np.where(S==0)
    V2 = list(zip(h,w))
    E = {v:[w for w in V2 if np.abs(np.array(v)-np.array(w)).sum()==1] for v in V1}
    E.update({v:[w for w in V1 if np.abs(np.array(v)-np.array(w)).sum()==1] for v in V2})
    C = {v:set() for v in V1}
    W = set()
    res = 0
    for v in V1:
        X, Y =  {v}, set() 
        if v in W:
            continue
        while X:
            w = X.pop()
            Y.add(w)
            W.add(w)
            X |= set(E[w])-Y
        res += len(Y&set(V1))*len(Y&set(V2))
    return str(res)

