def search(i, j, S, Q):
    nxt = collections.deque([[i, j]])
    black = 0
    white = 0
    if (S[i][j] == "#"): black += 1
    if (S[i][j] == "."): white += 1
    Q[i][j] = True

    while nxt:
        i, j = nxt.popleft()

        if (j + 1 < S.shape[1]):
            if (S[i][j] != S[i][j + 1] and Q[i][j + 1] == False):
                Q[i][j + 1] = True
                nxt.append([i, j + 1])
                if (S[i][j + 1] == "#"):
                    black += 1
                else:
                    white += 1
        if (i + 1 < S.shape[0]):
            if (S[i][j] != S[i + 1][j] and Q[i + 1][j] == False):
                Q[i + 1][j] = True
                nxt.append([i + 1, j])
                if (S[i + 1][j] == "#"):
                    black += 1
                else:
                    white += 1
        if (j - 1 >= 0 and S[i][j] != S[i][j - 1] and Q[i][j - 1] == False):
            Q[i][j - 1] = True
            nxt.append([i, j - 1])
            if (S[i][j - 1] == "#"):
                black += 1
            else:
                white += 1
        if (i - 1 >= 0 and S[i][j] != S[i - 1][j] and Q[i - 1][j] == False):
            Q[i - 1][j] = True
            nxt.append([i - 1, j])
            if (S[i - 1][j] == "#"):
                black += 1
            else:
                white += 1

    #    print(S)
    #    print(Q)
    return black * white

def parse(inp):
    H, W = map(int, next(inp).split())
    S = np.array([list(next(inp).strip()) for _ in range(H)])
    return S


def main(S):
    H, W = S.shape
    # print(S)
    Q = np.full([H, W], False)
    #     print(Q)

    answer = 0
    for i in range(H):
        for j in range(W):
            if (Q[i][j] == False):
                answer += search(i, j, S, Q)
    return answer

