def search(i, j, S, Q):
    nxt = collections.deque([[i, j]])
    black = 0
    white = 0
    if (S[i][j] == "#"): black += 1
    if (S[i][j] == "."): white += 1

    while nxt:
        i, j = nxt.popleft()
        Q[i][j] = True

        if (j + 1 < S.shape[1]):
            if (S[i][j] != S[i][j + 1] and Q[i][j + 1] == False):
                Q[i][j + 1] = True
                nxt.append([i, j + 1])
                if (S[i][j + 1] == "#"):
                    black += 1
                else:
                    white += 1
        if (i + 1 < S.shape[0]):
            if (S[i][j] != S[i + 1][j] and Q[i + 1][j] == False):
                Q[i + 1][j] = True
                nxt.append([i + 1, j])
                if (S[i + 1][j] == "#"):
                    black += 1
                else:
                    white += 1
        if (j - 1 >= 0 and S[i][j] != S[i][j - 1] and Q[i][j - 1] == False):
            Q[i][j - 1] = True
            nxt.append([i, j - 1])
            if (S[i][j - 1] == "#"):
                black += 1
            else:
                white += 1
        if (i - 1 >= 0 and S[i][j] != S[i - 1][j] and Q[i - 1][j] == False):
            Q[i - 1][j] = True
            nxt.append([i - 1, j])
            if (S[i - 1][j] == "#"):
                black += 1
            else:
                white += 1

    #    print(S)
    #    print(Q)
    return black * white

