def solve():
    H, W  = map(int,input().split())
    S = list()
    V1 = set()
    V2 = set()
    E =  dict()
    for i in range(H):
        s = input()
        for j, a in enumerate(s):
            if a == '#':
                V1.add((i,j))
                U = {(i-1,j),(i,j-1)}&V2
                E[(i,j)] = U
                for u in list(U):
                    E[u] |= {(i,j)}
            else:
                V2.add((i,j))
                U = {(i-1,j),(i,j-1)}&V1
                E[(i,j)] = U
                for u in list(U):
                    E[u] |= {(i,j)}

    W = set()
    res = 0
    for v in V1:
        X, Y =  {v}, set() 
        if v in W:
            continue
        while X:
            w = X.pop()
            Y.add(w)
            W.add(w)
            X |= set(E[w])-Y
        res += len(Y&set(V1))*len(Y&set(V2))
    return str(res)

