def search(h,w,field):
    if field[h][w] == '.':
        return 0

    visited = [[False] * len(field[0]) for _ in range(len(field))]

    cnt = 0
    q = deque()
    isBlack = True if field[h][w] == '#' else False
    q.append((h,w,isBlack))

    while len(q) > 0:
        now_h,now_w,now_isBlack = q.popleft()
        d = ((1,0), (0,1), (-1,0), (0,-1))
        for dh, dw in d:
            next_h = now_h + dh
            next_w = now_w + dw
            if not(0 <= next_h < len(field)) or not(0 <= next_w < len(field[0])):
                continue

            next_isBlack = True if field[next_h][next_w] == '#' else False
            if not visited[next_h][next_w] and now_isBlack != next_isBlack:
                q.append((next_h,next_w, next_isBlack))
                visited[next_h][next_w] = True
                if not next_isBlack:
                    cnt += 1

    return cnt 

