def find_chain((hh, ww), t, sumi):
    dd = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    chain_sumi = [[False for _ in range(W)] for _ in range(H)]
    h, w = hh, ww
    sumi[h][w] = True
    chain_sumi[h][w] = True
    c = [0, 0]
    c[t] = 1
    d = 0
    stack = []
    while True:
        while True:
            if d >= 4:
                break
            hd = h + dd[d][0]
            wd = w + dd[d][1]
            d += 1
            if 0 <= hd < H and 0 <= wd < W:
                if not chain_sumi[hd][wd]:
                    td = CR[S[hd][wd]]
                    if td == t-((hh+ww+hd+wd)&1):
                        sumi[hd][wd] = True
                        chain_sumi[hd][wd] = True
                        c[td] += 1
                        stack.append([h, w, d])
                        h , w, d = hd, wd, 0
        if len(stack) == 0:
            break
        h, w, d = stack.pop()
    # print 'sumi :', sumi
    # print 'chain_sumi :', chain_sumi
    return c


def main():
