                area[area == area[i, j - 1]] = area[i - 1, j]
                area[i, j] = area[i - 1, j]
            if j != 0 and C[i, j - 1] != C[i, j]:
                area[i, j] = area[i, j - 1]
            elif i != 0 and C[i - 1, j] != C[i, j]:
