def f(F, h, w):
    S = deque()
    S.append((h, w))
    P = {(h, w)}
    res = 0
    while S:
        h, w = S.popleft()
        for hh, ww in [(h + 1, w), (h - 1, w), (h, w + 1), (h, w - 1)]:
            if not (0 <= hh < H and 0 <= ww < W):
                continue
            if (hh, ww) in P:
                continue
            if F[hh][ww] == F[h][w]:
                continue
            P.add((hh, ww))
            res += 1 if F[hh][ww] == "." else 0
            S.append((hh, ww))
    return res


