class UnionFind:
    def __init__(self, n):
        self.par = [i for i in range(n + 1)]
        self.rank = [0] * (n + 1)

    def find(self, x):
        if self.par[x] == x:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]

    def union(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if self.rank[x] < self.rank[y]:
            self.par[x] = y
        else:
            self.par[y] = x
            if self.rank[x] == self.rank[y]:
                self.rank[x] += 1

    def same_check(self, x, y):
        return self.find(x) == self.find(y)


def solve():
    H, W = map(int, input().split())
    C = [[0] * W for _ in range(H)]
    for i, _ in enumerate(range(H)):
        for j, c in enumerate(input()):
            if c == '#':
                C[i][j] = 1

    uf = UnionFind(H * W)

    for i in range(H):
        for j in range(W):
            if i != 0 and C[i][j] != C[i - 1][j]:
                uf.union(i * W + j, (i - 1) * W + j)
            if j != 0 and C[i][j] != C[i][j - 1]:
                uf.union(i * W + j, i * W + j - 1)
    # count
    cnt = dict()
    for i in range(H):
        for j in range(W):
            par = uf.par[i * W + j]
            wh, bl = cnt.get(par, (0, 0))
            if C[i][j] == 0:
                cnt[par] = (wh + 1, bl)
            else:
                cnt[par] = (wh, bl + 1)

    print(sum(map(lambda x: x[0] * x[1], cnt.values())))


if __name__ == '__main__':
    solve()

