def solve(H, W, Ss):
    d = [[set() for __ in range(W)] for _ in range(H)]
    for _ in range(4):
        for h in range(0, H):
            for w in range(0, W):
                for (hi, wi) in [(h + 1, w), (h - 1, w), (h, w - 1), (h, w + 1)]:
