    for i, _ in enumerate(range(H)):
        for j, c in enumerate(input()):
            if c == '#':
                C[i, j] = 1

    area = np.zeros((H, W))
    now = 0
    for i in range(H):
        for j in range(W):
            if j != 0 and C[i, j - 1] != C[i, j]:
                area[i, j] = area[i, j - 1]
            elif i != 0 and C[i - 1, j] != C[i, j]:
                area[i, j] = area[i - 1, j]
            else:
                area[i, j] = now
                now += 1

    cnt = dict()
