class Unionfind:

    __slots__ = ['nodes','rank']

    def __init__(self, n):
        self.nodes = list(range(n))
        self.rank = [0]*n

    def root(self, x):
        if self.nodes[x] == x:
            return x
        else:
            root_x = self.root(self.nodes[x])
            self.nodes[x] = root_x
            return root_x

    def unite(self, x, y):
        x = self.root(x); y = self.root(y)
        if x == y:
            return
        if self.rank[x] < self.rank[y]:
            x, y = y, x
        self.rank[x] += self.rank[y]
        self.nodes[y] = x

    def same(self, x, y):
        return self.root(x) == self.root(y)

