def search(i, j, S, Q):
    nxt = collections.deque([[i, j]])
    if(S[i][j]=="#"):
        black=1
        white=0
    else:
        white=1
        black=0
    Q[i][j] = True

    while nxt:
        i, j = nxt.popleft()
        if (j + 1 < S.shape[1]):
            if (Q[i][j + 1] == False and S[i][j] != S[i][j + 1]):
                Q[i][j + 1] = True
                nxt.append([i, j + 1])
                if (S[i][j + 1] == "#"):
                    black += 1
                else:
                    white += 1
        if (i + 1 < S.shape[0]):
            if (Q[i + 1][j] == False and S[i][j] != S[i + 1][j]):
                Q[i + 1][j] = True
                nxt.append([i + 1, j])
                if (S[i + 1][j] == "#"):
                    black += 1
                else:
                    white += 1
        if (Q[i][j - 1] == False and j - 1 >= 0 and S[i][j] != S[i][j - 1]):
            Q[i][j - 1] = True
            nxt.append([i, j - 1])
            if (S[i][j - 1] == "#"):
                black += 1
            else:
                white += 1
        if (Q[i - 1][j] == False and i - 1 >= 0 and S[i][j] != S[i - 1][j]):
            Q[i - 1][j] = True
            nxt.append([i - 1, j])
            if (S[i - 1][j] == "#"):
                black += 1
            else:
                white += 1

    #    print(S)
    #    print(Q)
    return black * white

