def get_ways(row,column,Ss,H,W):
    pairs = []
    done = []
    que = []
    que.append((row,column))

    while(len(que) > 0):
        current = que.pop(0)
        done.append(current)
        for i in range(0,4):
            p = (current[0] + dxs[i],current[1] + dys[i])
            if p[0] >= H or p[1] >= W or p[0] < 0 or p[1] < 0 or p in done:
                continue
            elif Ss[current[0]][current[1]] != Ss[p[0]][p[1]]:
                que.append(p)
        pairs += que
    return pairs


