  ss = []
  for _ in range(h):
    # black(#): True, white(.): False
    ss.append([cell == '#' for cell in list(input())])

  ids = [[-1 for _ in range(w)] for _ in range(h)]
  connecteds = []
  same_id = dict()
  for i in range(h):
    for j in range(w):
      id_ = ids[i][j]
      if id_ == -1:
        bw = (1, 0) if ss[i][j] else (0, 1)
        connecteds.append(bw)
        id_ = len(connecteds) - 1
      black, white = connecteds[id_]
      if i < h - 1 and ss[i][j] != ss[i+1][j]:
        if ids[i+1][j] == -1:
          ids[i+1][j] = id_
          if ss[i+1][j]:
            black += 1
          else:
            white += 1
        elif ids[i][j] != ids[i+1][j]:
          same_id[max(ids[i][j], ids[i+1][j])] = min(ids[i][j], ids[i+1][j])
      if j < w - 1 and ss[i][j] != ss[i][j+1]:
        if ids[i][j+1] == -1:
          ids[i][j+1] = id_
          if ss[i][j+1]:
            black += 1
          else:
            white += 1
        elif ids[i][j] != ids[i][j+1]:
          same_id[max(ids[i][j], ids[i][j+1])] = min(ids[i][j], ids[i][j+1])
      connecteds[id_] = (black, white)
  for k, v in same_id.items():
    while connecteds[v] is None:
      v = same_id[v]
    bk, wk = connecteds[k]
    bv, wv = connecteds[v]
    connecteds[v] = (bk+bv, wk+wv)
    connecteds[k] = None
  connecteds = list(filter(lambda x: x is not None, connecteds))
  ret = 0
