def c_alternating_path(H, W, Grid):
    from collections import deque
    ans = 0
    for h in range(H):
        for w in range(W):
            if Grid[h][w] == '#':
                is_visit = [[False] * W for _ in range(H)]
                q = deque([(h, w)])
                while q:
                    row, col = q.pop()
                    if is_visit[row][col]:
                        continue
                    is_visit[row][col] = True
                    if Grid[row][col] == '.':
                        ans += 1
                    for dr, dc in zip((1, 0, -1, 0), (0, 1, 0, -1)):
                        nr, nc = row + dr, col + dc
                        if (0 <= nr < H and 0 <= nc < W
                                and Grid[row][col] != Grid[nr][nc]
                                and not is_visit[nr][nc]):
                            q.appendleft((nr, nc))
    return ans

