import numpy as np
import io

@np.vectorize
def trans(s):
    return 1 if s == "#" else 0

def parse(inp):
    H, W = map(int, next(inp).split())
    return np.array([trans([w for w in next(inp).strip()]) for _ in range(H)])

def find_root(uft, i):
    lst = list()
    while True:
        lst.append(i)
        io = i
        i = uft[i]
        if i == io:
            break
    ri = lst.pop()
    while lst:
        i = lst.pop()
        uft[i] = uft[ri]
    return ri


def union_find_tree(inp):
    shape = inp.shape
    H, W = shape
    grp = inp.flatten()
    uft = np.arange(len(grp))
    for i in range(H):
        for j in range(W-1):
            if grp[i*W+j+1] != grp[i*W+j]:
                uft[i*W + j+1] = uft[i*W + j]
    for j in range(W):
        for i in range(H-1):
            if grp[(i+1)*W+j] != grp[i*W+j]:
                uft[find_root(uft, (i+1)*W+j)] = find_root(uft, i*W+j)
    for i in range(len(uft)):
        find_root(uft, i)
    return set(uft), uft


def test(inp):
    roots, uft = union_find_tree(inp)
    nmax = max(roots) + 1
    n1 = np.full(nmax, 0)
    n0 = np.full(nmax, 0)
    for i, u in zip(inp.flatten(), uft):
        if i:
            n1[u] += 1
        else:
            n0[u] += 1
    return np.sum(n1 * n0)

