    let (h, w) = scan!(usize, usize);
    let vs = scan!(String;h);

    let graph: Vec<_> = vs.iter().map(|v| v.chars().collect::<Vec<_>>()).collect();
    let mut colors = vec![vec![-1; w]; h];

    let mut color = 0i64;
    for i in 0..h {
        for j in 0..w {
            if colors[i][j] == -1 {
                dfs(
                    &graph,
                    &mut colors,
                    i,
                    j,
                    color,
                    if graph[i][j] == '#' { 0 } else { 1 },
                );
                color += 1;
            }
        }
    }

    let mut whites = vec![0i64; color as usize + 1];
    let mut blacks = vec![0i64; color as usize + 1];
    for (i, l) in colors.iter().enumerate() {
        for (j, &c) in l.iter().enumerate() {
            if graph[i][j] == '.' {
                whites[c as usize] += 1;
