        if visited[cur.0][cur.1] {
            continue;
        }
        visited[cur.0][cur.1] = true;
        if table[cur.0][cur.1] == '#' {
            whilte += 1;
        } else {
            black += 1;
        }

        if cur.0 > 0 {
            if table[cur.0 - 1][cur.1] != table[cur.0][cur.1] && !visited[cur.0 - 1][cur.1] {
                queue.push_back((cur.0 - 1, cur.1));
            }
        }

        if cur.0 < table.len() - 1 {
            if table[cur.0 + 1][cur.1] != table[cur.0][cur.1] && !visited[cur.0 + 1][cur.1] {
                queue.push_back((cur.0 + 1, cur.1));
            }
        }

        if cur.1 > 0 {
            if table[cur.0][cur.1 - 1] != table[cur.0][cur.1] && !visited[cur.0][cur.1 - 1] {
                queue.push_back((cur.0, cur.1 - 1));
            }
        }

        if cur.1 < table[0].len() - 1 {
            if table[cur.0][cur.1 + 1] != table[cur.0][cur.1] && !visited[cur.0][cur.1 + 1] {
                queue.push_back((cur.0, cur.1 + 1));
            }
        }
    }

    return whilte * black;
}

