trait CharExt {
    fn toNum(&self) -> usize;
    fn toAlphabetIndex(&self) -> usize;
    fn toNumIndex(&self) -> usize;
}
impl CharExt for char {
    fn toNum(&self) -> usize {
        return *self as usize;
    }
    fn toAlphabetIndex(&self) -> usize {
        return self.toNum() - 'a' as usize;
    }
    fn toNumIndex(&self) -> usize {
        return self.toNum() - '0' as usize;
    }
}

trait VectorExt {
    fn joinToString(&self, s: &str) -> String;
}
impl<T: ToString> VectorExt for Vec<T> {
    fn joinToString(&self, s: &str) -> String {
        return self
            .iter()
            .map(|x| x.to_string())
            .collect::<Vec<_>>()
            .join(s);
    }
}

fn f(
    map: &Vec<Vec<char>>,
    p: (usize, usize),
    used: &mut Vec<Vec<bool>>,
    h: usize,
    w: usize,
) -> usize {
    if map[p.0][p.1] == '.' {
        return 0;
    } else if used[p.0][p.1] {
        return 0;
    }
    let mut kouho: VecDeque<(usize, usize, usize)> = VecDeque::new();
    kouho.push_back((p.0, p.1, 1)); //0:white 1:black
    used[p.0][p.1] = true;
    let mut black = 1;
    let mut white = 0;
    let dir: Vec<i32> = vec![-1, 0, 1, 0, -1, 1, 1, -1, -1];
    while !kouho.is_empty() {
        let (x, y, parent) = kouho.pop_front().unwrap();
        for i in 0..4 {
            let x2 = x as i32 + dir[i];
            let y2 = y as i32 + dir[i + 1];
            if x2 >= 0 && y2 >= 0 && x2 < h as i32 && y2 < w as i32 {
                let color = if map[x2 as usize][y2 as usize] == '#' {
                    1
                } else {
                    0
                };
                if parent == color {
                    continue;
                } else if used[x2 as usize][y2 as usize] {
                    continue;
                }
                kouho.push_back((x2 as usize, y2 as usize, color));
                used[x2 as usize][y2 as usize] = true;
                if color == 1 {
                    black += 1;
                } else {
                    white += 1;
                }
            }
        }
    }

    return black * white;
}

fn main() {
    input! {
       h:usize,
       w:usize,
       map:[chars;h],
    }

    let mut ans: usize = 0;

    let mut used = vec![vec![false; w]; h];
    for i in 0..h {
        for j in 0..w {
            ans += f(&map, (i, j), &mut used, h, w);
        }
    }
    echo!(ans);
}

use std::io::*;
use std::str::FromStr;
use std::collections::VecDeque;

fn main() {
    let h: usize = read();
    let w: usize = read();
    let s: Vec<Vec<char>> = (0..h).map(|_| read::<String>().chars().collect()).collect();

    let mut ans = 0;
    for i in 0..h {
        for j in 0..w {
            if s[i][j] == '.' {
                continue;
            }
            let mut check: Vec<Vec<bool>> = vec![vec![false; w]; h];
            let mut que: VecDeque<(usize, usize)> = VecDeque::new();
            let mut cnt: i64 = 0;
            que.push_back((i, j));
            while let Some((y, x)) = que.pop_front() {
                if check[y][x] {
                    continue;
                }
                check[y][x] = true;
                let c = s[y][x];
                if c == '.' {
                    cnt += 1;
                }
                if x > 0 && c != s[y][x-1] {
                    que.push_back((y, x-1));
                }
                if x < w-1 && c != s[y][x+1] {
                    que.push_back((y, x+1));
                }
                if y > 0 && c != s[y-1][x] {
                    que.push_back((y-1, x));
                }
                if y < h-1 && c != s[y+1][x] {
                    que.push_back((y+1, x));
                }
            }
            ans += cnt;
        }
    }
    println!("{}", ans);
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

