fn search(
    info: &Vec<usize>,
    board: &Vec<Vec<char>>,
    group_memo: &mut Vec<Vec<Option<usize>>>,
    count: &mut usize,
) {
    let mut group_num = 0;
    for i in 0..info[0] {
        for j in 0..info[1] {
            let mut b = 0;
            let mut w = 0;
            let (mut b, mut w) = dp(
                i, j, group_num, board, group_memo, info, &mut b, &mut w,
            );
            if b != 0 || w != 0 {
                if board[i][j] == '#' {
                    b += 1;
                } else {
                    w += 1;
                }
            }
            *count += b * w;
            group_num += 1;
        }
    }
}
fn dp(
    i: usize,
    j: usize,
    group_num: usize,
    board: &Vec<Vec<char>>,
    group_memo: &mut Vec<Vec<Option<usize>>>,
    info: &Vec<usize>,
    black: &mut usize,
    white:  &mut usize,
) -> (usize, usize) {
    if (i < info[0] - 1) && board[i + 1][j] != board[i][j] {
        match group_memo[i + 1][j] {
            Some(num) => {}
            None => {
                group_memo[i][j] = Some(group_num);
                group_memo[i + 1][j] = Some(group_num);
                dp(i + 1, j, group_num, board, group_memo, info, black, white);
                if board[i + 1][j] == '#' {
                    *black += 1;
                } else {
                    *white += 1;
                }
            }
        }
    }
    if (j < info[1] - 1) && board[i][j + 1] != board[i][j] {
        match group_memo[i][j + 1] {
            Some(num) => {}
            None => {
                group_memo[i][j] = Some(group_num);
                group_memo[i][j + 1] = Some(group_num);
                dp(i, j + 1, group_num, board, group_memo, info, black, white);
                if board[i][j + 1] == '#' {
                    *black += 1;
                } else {
                    *white += 1;
                }
            }
        }
    }
    if i > 0 && board[i - 1][j] != board[i][j] {
        match group_memo[i - 1][j] {
            Some(num) => {}
            None => {
                group_memo[i][j] = Some(group_num);
                group_memo[i - 1][j] = Some(group_num);
                dp(i - 1, j, group_num, board, group_memo, info, black, white);
                if board[i - 1][j] == '#' {
                    *black += 1;
                } else {
                    *white += 1;
                }
            }
        }
    }
    if j > 0 && board[i][j - 1] != board[i][j] {
        match group_memo[i][j - 1] {
            Some(num) => {}
            None => {
                group_memo[i][j] = Some(group_num);
                group_memo[i][j - 1] = Some(group_num);
                dp(i, j - 1, group_num, board, group_memo, info, black, white);
                if board[i][j - 1] == '#' {
                    *black += 1;
                } else {
                    *white += 1;
                }
            }
        }
    }
    return (*black, *white);
}

