#[fastout()]
fn main() {
    input! {
        h: usize, w: usize,
        s: [Chars; h]
    }

    let mut visited = vec![vec![false; w]; h];
    let mut ans = 0usize;
    for y in 0..h {
        for x in 0..w {
            if visited[y][x] {
                continue;
            }
            let mut black = 0;
            let mut white = 0;
            let mut que = Vec::new();
            que.push((x, y));
            visited[y][x] = true;
            while let Some((x1, y1)) = que.pop() {
                if s[y1][x1] == '#' {
                    black += 1;
                } else {
                    white += 1;
                }
                let d = [(0, 1), (1, 0), (-1, 0), (0, -1)];
                for &(dx, dy) in &d {
                    let x2 = clamp(x1 as isize + dx, 0, w as isize - 1) as usize;
                    let y2 = clamp(y1 as isize + dy, 0, h as isize - 1) as usize;
                    if visited[y2][x2] || s[y1][x1] == s[y2][x2] {
                        continue;
                    }
                    visited[y2][x2] = true;
                    que.push((x2, y2));
                }
            }
            ans += black * white;
        }
    }
    println!("{}", ans);
}

use std::cmp::*;
use std::io::*;

fn main() {
    let mut s: String = String::new();
    stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let h: usize = itr.next().unwrap().parse().unwrap();
    let w: usize = itr.next().unwrap().parse().unwrap();
    let g: Vec<Vec<char>> = (0..h)
        .map(|_| itr.next().unwrap().chars().collect())
        .collect();
    let dx: Vec<isize> = [0, -1, 0, 1].to_vec();
    let dy: Vec<isize> = [1, 0, -1, 0].to_vec();

    let mut used = vec![vec![false; w]; h];
    let mut q = std::collections::VecDeque::new();
    let mut ans = 0;
    for i in 0..h {
        for j in 0..w {
            if !used[i][j] {
                q.push_back((i, j));
                used[i][j] = true;

                let mut white = 0;
                let mut black = 0;
                while let Some((y, x)) = q.pop_front() {
                    if g[y][x] == '.' {
                        white += 1;
                    } else {
                        black += 1;
                    }
                    for k in 0..4 {
                        let nx = x as isize + dx[k];
                        let ny = y as isize + dy[k];
                        if 0 <= nx
                            && nx < w as isize
                            && 0 <= ny
                            && ny < h as isize
                            && g[y][x] != g[ny as usize][nx as usize]
                            && !used[ny as usize][nx as usize]
                        {
                            q.push_back((ny as usize, nx as usize));
                            used[ny as usize][nx as usize] = true;
                        }
                    }
                }
                ans += white * black;
            }
        }
    }
    println!("{}", ans);
}

