   let mut ans = 0;
   for i in 1..=h {
      for j in 1..=w {
         if m[i][j] != 2 {
            let (n, m) = bfs((i, j), &mut m);
            ans += n * m;
         }
      }
   }

   println!("{}", ans);
}

fn bfs((x, y): (usize, usize), m: &mut Vec<Vec<usize>>) -> (usize, usize) {
   let mut n1 = 0;
   let mut n2 = 0;
   if m[x][y] == 0 {
      n1 += 1;
   } else {
      n2 += 1;
   }
   let s = m[x][y];
   m[x][y] = 2;
   for (dx, dy) in [(1, 0), (0, 1), (!0, 0), (0, !0)].iter() {
      let xn = x + dx;
      let yn = y + dy;
      if m[xn][yn] != 2 && m[xn][yn] != s {
         let (dn1, dn2) = bfs((xn, yn), m);
         n1 += dn1;
         n2 += dn2;
      }
   }
   (n1, n2)
}

