fn dfs(v: usize, vis: &mut [bool], g: &[Vec<usize>], col: &[bool])
       -> (i64, i64) {
    if vis[v] { return (0, 0); }
    vis[v] = true;
    let (mut bc, mut wc) = if col[v] { (1, 0) } else { (0, 1) };
    for &w in g[v].iter() {
        let (x, y) = dfs(w, vis, g, col);
        bc += x;
        wc += y;
    }
    (bc, wc)
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        h: usize,
        w: usize,
        s: [chars; h],
    }
    let mut g = vec![Vec::new(); h * w];
    for i in 0 .. h - 1 {
        for j in 0 .. w {
            if s[i][j] != s[i + 1][j] {
                let a = i * w + j;
                let b = i * w + w + j;
                g[a].push(b);
                g[b].push(a);
            }
        }
    }
    for i in 0 .. h {
        for j in 0 .. w - 1 {
            if s[i][j] != s[i][j + 1] {
                let a = i * w + j;
                let b = i * w + j + 1;
                g[a].push(b);
                g[b].push(a);
            }
        }
    }
    let mut col = vec![false; h * w];
    for i in 0 .. h {
        for j in 0 .. w {
            col[i * w + j] = s[i][j] == '#';
        }
    }
    let mut vis = vec![false; h * w];
    let mut tot = 0;
    for i in 0 .. h * w {
        if vis[i] { continue; }
        let (b, w) = dfs(i, &mut vis, &g, &col);
        tot += b * w;
    }
    puts!("{}\n", tot);
}

