fn search(info: &Vec<usize>, board: &Vec<Vec<char>>, group_memo: &mut Vec<Vec<Option<usize>>>) {
    let mut group_num = 0;
    for i in 0..info[0] {
        for j in 0..info[1] {
            dp(i, j, &mut group_num, board, group_memo, info);
            group_num += 1;
        }
    }
}
fn dp(
    i: usize,
    j: usize,
    group_num: &mut usize,
    board: &Vec<Vec<char>>,
    group_memo: &mut Vec<Vec<Option<usize>>>,
    info: &Vec<usize>,
) {
    if (i < info[0] - 1) && board[i + 1][j] != board[i][j] {
        match group_memo[i + 1][j] {
            Some(num) => {}
            None => {
                group_memo[i][j] = Some(*group_num);
                group_memo[i + 1][j] = Some(*group_num);
                dp(i + 1, j, group_num, board, group_memo, info);
            }
        }
    }
    if (j < info[1] - 1) && board[i][j + 1] != board[i][j] {
        match group_memo[i][j + 1] {
            Some(num) => {}
            None => {
                group_memo[i][j] = Some(*group_num);
                group_memo[i][j + 1] = Some(*group_num);
                dp(i, j+1, group_num, board, group_memo, info);
            }
        }
    }
    if i > 0 && board[i - 1][j] != board[i][j] {
        match group_memo[i - 1][j] {
            Some(num) => {}
            None => {
                group_memo[i][j] = Some(*group_num);
                group_memo[i - 1][j] = Some(*group_num);
                dp(i - 1, j, group_num, board, group_memo, info);
            }
        }
    }
    if j > 0 && board[i][j - 1] != board[i][j] {
        match group_memo[i][j - 1] {
            Some(num) => {}
            None => {
                group_memo[i][j] = Some(*group_num);
                group_memo[i][j - 1] = Some(*group_num);
                dp(i, j - 1, group_num, board, group_memo, info);
            }
        }
    }
}

