use std::collections::VecDeque;



fn bfs(h: i64, w: i64, s: Vec<Vec<bool>>) -> usize {
    let mut visited = vec![vec![false; w as usize]; h as usize];
    let mut res = 0;
    let next = vec![(0, -1), (-1, 0), (0, 1), (1, 0)];
    let mut q = VecDeque::new();
    for i in 0..h {
        for j in 0..w {
            if visited[i as usize][j as usize] {
                continue;
            }
            if s[i as usize][j as usize] {
                visited[i as usize][j as usize] = true;
                q.push_back(((i, j), true));
            }
            let mut black = 1;
            let mut white = 0;
            while let Some(((height, width), c)) = q.pop_front() {
                for n in 0..4 {
                    let n = next[n];
                    let height = height + n.1;
                    let width = width + n.0;
                    if width < 0 || height < 0 || width >= w || height >= h {
                        continue;
                    }
                    if visited[height as usize][width as usize] {
                        continue;
                    }
                    if c ^ s[height as usize][width as usize] {
                        q.push_back(((height, width), s[height as usize][width as usize]));
                        if s[height as usize][width as usize] {
                            black += 1;
                        } else {
                            white += 1;
                        }
                        visited[height as usize][width as usize] = true;
                    }
                }
            }
            res += black * white;
        }
    }
    res
}


