fn main() {
    input! {
        h: usize,
        w: usize,
        s: [chars; h]
    }

    let mut f = vec![vec![false; w]; h];
    let mut num = 0;
    for i in 0..h {
        for j in 0..w {
            if f[i][j] == false {
                let mut c1 = 1;
                let mut c2 = 0;
                let mut q = VecDeque::new();
                q.push_back(Mass {
                    x: j,
                    y: i,
                    c: s[i][j],
                });
                f[i][j] = true;

                while let Some(cur) = q.pop_front() {
                    for (dx, dy) in [0, 0, -1, 1].iter().zip([-1, 1, 0, 0].iter()) {
                        let nx = (cur.x as i64) + dx;
                        let ny = (cur.y as i64) + dy;
                        if 0 <= nx && nx < w as i64 && 0 <= ny && ny < h as i64 {
                            if f[ny as usize][nx as usize] == false
                                && cur.c != s[ny as usize][nx as usize]
                            {
                                q.push_back(Mass {
                                    x: nx as usize,
                                    y: ny as usize,
                                    c: s[ny as usize][nx as usize],
                                });
                                f[ny as usize][nx as usize] = true;
                                if s[i][j] == s[ny as usize][nx as usize] {
                                    c1 += 1;
                                } else {
                                    c2 += 1;
                                }
                            }
                        }
                    }
                }
                num += c1 * c2;
            }
        }
    }

    println!("{}", num);
}

