    line.trim().chars().collect()
}

fn idx(y: usize, x: usize, w: usize) -> usize {
    y * w + x
}

fn count(idx: usize, w: usize, grid: &Vec<char>, checker: &Vec<char>, visited: &mut HashSet<usize>) -> Vec<u64> {
    // println!("idx: {}", idx);
    visited.insert(idx);
    if grid[idx] != checker[idx] {
        return vec![0; 2];
    }
    let i: usize;
    if grid[idx] == '#' {
        i = 0;
    } else {
        i = 1;
    }
    let mut tmp = vec![0; 2];
    tmp[i] += 1;
    let h = grid.len() / w;
    if idx % w != w - 1 && !visited.contains(&(idx+1)) {
        let c = count(idx + 1, w, grid, checker, visited);
        tmp[0] += c[0];
        tmp[1] += c[1];
    }
    if idx % w != 0 && !visited.contains(&(idx-1)) {
        let c = count(idx - 1, w, grid, checker, visited);
        tmp[0] += c[0];
        tmp[1] += c[1];
    }
    if idx < (h - 1) * w && !visited.contains(&(idx+w)) {
        let c = count(idx + w, w, grid, checker, visited);
        tmp[0] += c[0];
        tmp[1] += c[1];
    }
    if idx > w - 1 && !visited.contains(&(idx-w)) {
        let c = count(idx - w, w, grid, checker, visited);
        tmp[0] += c[0];
        tmp[1] += c[1];
    }
    tmp
}

