struct Graph<T> {
    edge: BTreeMap<T, BTreeSet<T>>,
}

impl<T: Ord + Copy + Clone + std::fmt::Debug> Graph<T> {
    fn new() -> Self {
        Graph{
            edge: BTreeMap::new(),
        }
    }

    fn add(&mut self, a: T, b: T) {
        self.edge.entry(a).or_insert(BTreeSet::new()).insert(b);
        self.edge.entry(b).or_insert(BTreeSet::new()).insert(a);
    }

    fn bfs(&self) -> usize {
        let mut searched = BTreeSet::<T>::new();
        let mut vec = Vec::new();
        for k in self.edge.keys() {
            if searched.contains(k) {
                continue;
            }
            searched.insert(*k);
            let mut b = 0;
            let mut w = 0;
            let mut queue = VecDeque::new();
            queue.push_back((k, 0));
            while let Some((key, depth)) = queue.pop_front() {
                let vs = self.edge.get(key).unwrap().iter().filter(|e| !searched.contains(*e)).collect::<Vec<_>>();
                for v in vs {
                    searched.insert(*v);
                    queue.push_back((v, depth+1));
                }
                if depth % 2 == 0 {
                    b += 1;
                } else {
                    w += 1;
                }
            }
            vec.push((b,w));
        }
        vec.into_iter().map(|(a,b)| a*b).sum()
    }
}

