fn search(i: usize, j: usize, h: usize, w: usize, ss: &Vec<Vec<char>>, seen: &mut Vec<Vec<bool>>, c: char, c1: &mut usize, c2: &mut usize) {
    if seen[i][j] {
        return;
    }

    if ss[i][j] != c {
        return;
    }

    if c == '#' {
        *c1 += 1;
    } else {
        *c2 += 1;
    }

    seen[i][j] = true;

    let i = i as isize;
    let j = j as isize;
    let h = h as isize;
    let w = w as isize;

    let ds = [
        [1,0],
        [-1,0],
        [0,1],
        [0,-1],
    ];

    for d in ds.iter() {
        let dx = d[0];
        let dy = d[1];
        if i + dx < 0 || i + dx >= h {
            continue;
        }

        if j + dy < 0 || j + dy >= w {
            continue;
        }
        search((i+dx) as usize, (j+dy) as usize, h as usize, w as usize, ss, seen, if c == '#'  { '.' } else { '#' }, c1, c2);
    }
}

