macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (h, w) = parse!(it, 2);
    let g: Vec<Vec<bool>> = (0..h)
        .map(|_| it.next().unwrap().chars().map(|c| c == '.').collect())
        .collect();
    let mut seen = std::collections::HashSet::<(usize, usize)>::new();
    let mut ret = 0;
    for i in 0..h {
        for j in 0..w {
            if seen.contains(&(i, j)) {
                continue;
            }
            let mut q = std::collections::VecDeque::<(usize, usize)>::new();
            q.push_back((i, j));
            seen.insert((i, j));
            let mut ca = 0;
            let mut cb = 0;
            while let Some((i, j)) = q.pop_back() {
                if g[i][j] {
                    ca += 1
                } else {
                    cb += 1
                }
                let mut nexts = vec![];
                if i > 0 {
                    nexts.push((i - 1, j));
                }
                if j > 0 {
                    nexts.push((i, j - 1));
                }
                if i < h - 1 {
                    nexts.push((i + 1, j));
                }
                if j < w - 1 {
                    nexts.push((i, j + 1));
                }
                for (ni, nj) in nexts {
                    if !seen.contains(&(ni, nj)) && g[ni][nj] != g[i][j] {
                        seen.insert((ni, nj));
                        q.push_back((ni, nj))
                    }
                }
            }
            ret += ca * cb;
        }
    }
    println!("{}", ret);
}

