fn f(
    h: usize,
    w: usize,
    map: &Vec<Vec<char>>,
    visited: &mut Vec<Vec<bool>>,
    x: usize,
    y: usize,
    expect: char,
) -> (u64, u64) {
    if !visited[y][x] && map[y][x] == expect {
        visited[y][x] = true;

        match [
            (x as i32 - 1, y as i32),
            (x as i32 + 1, y as i32),
            (x as i32, y as i32 - 1),
            (x as i32, y as i32 + 1),
        ]
        .into_iter()
        .filter(|&&(x, y)| 0 <= x && x < w as i32 && 0 <= y && y < h as i32)
        .map(|&(x, y)| (x as usize, y as usize))
        .map(|(x, y)| {
            f(
                h,
                w,
                map,
                visited,
                x,
                y,
                if expect == '#' { '.' } else { '#' },
            )
        })
        .fold((0, 0), |(b_sum, w_sum), (b, w)| (b_sum + b, w_sum + w))
        {
            (b, w) => {
                if map[y][x] == '#' {
                    (b + 1, w)
                } else {
                    (b, w + 1)
                }
            }
        }
    } else {
        (0, 0)
    }
}

