fn main() {
    proconio::input! {
        h: usize,
        w: usize,
        ss: [proconio::marker::Chars; h],
    }
    let mut group = vec![vec![None; w]; h];
    for i_origin in 0..h {
        for j_origin in 0..w {
            if ss[i_origin][j_origin] == '.' || group[i_origin][j_origin].is_some() {
                continue;
            }
            let mut deque = std::collections::VecDeque::new();
            deque.push_back((i_origin, j_origin));
            while let Some((i, j)) = deque.pop_front() {
                group[i][j] = Some((i_origin, j_origin));
                let nexts = [
                    (i.wrapping_sub(1), j),
                    (i, j.wrapping_sub(1)),
                    (i + 1, j),
                    (i, j + 1),
                ];
                for &(i_next, j_next) in &nexts {
                    if i_next < h
                        && j_next < w
                        && group[i_next][j_next].is_none()
                        && ss[i][j] != ss[i_next][j_next]
                    {
                        deque.push_back((i_next, j_next));
                    }
                }
            }
        }
    }
    let mut nums = std::collections::HashMap::new();
    for (i, group) in group.iter().enumerate() {
        for (j, group) in group.iter().enumerate() {
            if let Some(group) = group {
                let e = nums.entry(group).or_insert([0, 0]);
                let idx = if ss[i][j] == '#' { 0 } else { 1 };
                (*e)[idx] += 1;
            }
        }
    }
    let ans = nums.values().map(|x| x[0] * x[1]).sum::<usize>();
    println!("{}", ans);
}

fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let h: usize = sc.read();
    let w: usize = sc.read();
    let s: Vec<Vec<char>> = (0..h).map(|_| sc.chars()).collect();
    let mut ut = UnionFind::new(h * w);
    for i in 0..h {
        for j in 0..w {
            if s[i][j] == '#' {
                for k in 0..4 {
                    if let Some((ny, nx)) = utils::try_adj(i, j, k, h, w) {
                        if s[ny][nx] == '.' {
                            ut.unite(i * w + j, ny * w + nx);
                        }
                    }
                }
            }
        }
    }
    let mut cnts = vec![(0, 0); h * w];
    for i in 0..h {
        for j in 0..w {
            let root = ut.root(i * w + j);
            if s[i][j] == '#' {
                cnts[root].0 += 1;
            } else {
                cnts[root].1 += 1;
            }
        }
    }
    let mut result = 0;
    for i in 0..h {
        for j in 0..w {
            if ut.is_root(i * w + j) {
                result += cnts[i * w + j].0 * cnts[i * w + j].1;
            }
        }
    }
    println!("{}", result);
}

