fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let h: usize = itr.next().unwrap().parse().unwrap();
    let w: usize = itr.next().unwrap().parse().unwrap();
    let s: Vec<Vec<char>> = (0..h)
        .map(|_| itr.next().unwrap().chars().collect())
        .collect();

    let mut ans: u64 = 0;
    let mut q = std::collections::VecDeque::new();
    let mut visit = vec![vec![false; w]; h];
    for i in 0..h {
        for j in 0..w {
            if !visit[i][j] && s[i][j] == '#' {
                visit[i][j] = true;
                q.push_back((i, j));
                let mut kuro: u64 = 1;
                let mut shiro: u64 = 0;
                while let Some((y, x)) = q.pop_front() {
                    for (dy, dx) in vec![(-1, 0), (1, 0), (0, -1), (0, 1)] {
                        let ny = ((y as isize) + dy) as usize;
                        let nx = ((x as isize) + dx) as usize;
                        if nx < w && ny < h && !visit[ny][nx] {
                            if s[ny][nx] == '.' && s[y][x] == '#' {
                                shiro += 1;
                                q.push_back((ny, nx));
                                visit[ny][nx] = true;
                            } else if s[ny][nx] == '#' && s[y][x] == '.' {
                                kuro += 1;
                                q.push_back((ny, nx));
                                visit[ny][nx] = true;
                            }
                        }
                    }
                }
                ans += shiro * kuro;
            }
        }
    }
    println!("{}", ans);
}

