fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let h: usize = sc.read();
    let w: usize = sc.read();
    let s: Vec<Vec<char>> = (0..h).map(|_| sc.chars()).collect();
    let mut ut = UnionFind::new(h * w + 10);
    for i in 0..h {
        for j in 0..w {
            if s[i][j] == '#' {
                for k in 0..4 {
                    if let Some((ny, nx)) = utils::try_adj(i, j, k, h, w) {
                        if s[ny][nx] == '.' {
                            ut.unite(i * w + j, ny * w + nx);
                        }
                    }
                }
            }
        }
    }
    let mut cnts = vec![(0, 0); h * w];
    for i in 0..h {
        for j in 0..w {
            let root = ut.root(i * w + j);
            if s[i][j] == '#' {
                cnts[root].0 += 1;
            } else {
                cnts[root].1 += 1;
            }
        }
    }
    let mut result = 0;
    for i in 0..h {
        for j in 0..w {
            if ut.is_root(i * w + j) {
                let black = cnts[i * w + j].0;
                let white = cnts[i * w + j].1;
                if black > 0 && white > 0 {
                    // println!("{} {}", black, white);
                    result += black * white;
                    // result += black * (black - 1) / 2;
                }
            }
        }
    }
    println!("{}", result);
}

