fn main() {
    input! {
        h: usize,
        w: usize,
        s: [chars; h],
    }
    let mut s = s;

    let mut ans = 0;

    for y in 0..h {
        for x in 0..w {
            if s[y][x] == '#' {
                let t = paint(x as _, y as _, ' ', &mut s);
                ans += t.0 * t.1;
            }
        }
    }

    println!("{}", ans);
}

fn paint(x: i64, y: i64, prev: char, bd: &mut Vec<Vec<char>>) -> (usize, usize) {
    if !(x >= 0 && x < bd[0].len() as _ && y >= 0 && y < bd.len() as _) {
        return (0, 0);
    }
    let c = bd[y as usize][x as usize];

    if c == ' ' || c == prev {
        return (0, 0);
    }

    bd[y as usize][x as usize] = ' ';

    let mut ret = if c == '.' { (1, 0) } else { (0, 1) };

    let t = paint(x + 0, y + 1, c, bd);
    ret.0 += t.0;
    ret.1 += t.1;

    let t = paint(x + 0, y - 1, c, bd);
    ret.0 += t.0;
    ret.1 += t.1;

    let t = paint(x + 1, y + 0, c, bd);
    ret.0 += t.0;
    ret.1 += t.1;

    let t = paint(x - 1, y + 0, c, bd);
    ret.0 += t.0;
    ret.1 += t.1;

    return ret;
}

