type Graph = Vec<Vec<usize>>;
const DH: [i64; 4] = [0, 1, 0, -1];
const DW: [i64; 4] = [1, 0, -1, 0];

fn rec(h: usize, w: usize, table: &Vec<Vec<char>>, memo: &mut Vec<Vec<bool>>) -> (usize, usize) {
    memo[h][w] = true;
    let mut bl = 0;
    let mut wh = 0;
    if table[h][w] == '#' {
        bl += 1;
    } else {
        wh += 1;
    }
    for i in 0..4 {
        let nh = h as i64 + DH[i];
        let nw = w as i64 + DW[i];
        if nh < 0 || nh as usize >= table.len() || nw < 0 || nw as usize >= table[0].len() {
            continue;
        }
        let nh = nh as usize;
        let nw = nw as usize;
        if memo[nh][nw] || table[nh][nw] == table[h][w] {
            continue;
        }
        let res = rec(nh, nw, table, memo);
        bl += res.0;
        wh += res.1;
    }
    (bl, wh)
}

fn main() {
    input! {
        h: usize, w: usize,
        s: [chars; h],
    }

    let mut memo = vec![vec![false; w]; h];

    let mut sum = 0;
    for i in 0..h {
        for j in 0..w {
            if !memo[i][j] {
                let (b, w) = rec(i, j, &s, &mut memo);
                sum += b * w;
            }
        }
    }
    println!("{}", sum);
}

