fn test_solve() {
    assert_eq!(solve("3 3\n.#.\n..#\n#..\n"), "10\n");
    assert_eq!(solve("2 4\n....\n....\n"), "0\n");
    assert_eq!(solve("4 3\n###\n###\n...\n###\n"), "6\n");
    assert_eq!(solve("3 3 ### ### ###"), "0\n");
    assert_eq!(solve("3 3 #.# .#. #.#"), "20\n");
    assert_eq!(solve("3 3 ### #.# ###"), "4\n");
}
fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let h: usize = sc.read();
    let w: usize = sc.read();
    let mas: Vec<Vec<char>> = (0..h).map(|_| sc.get().chars().collect()).collect();

    let mut vsd = vec![vec![false; w]; h];
    let mut cnt: u64 = 0;
    for i in 0..h {
        for j in 0..w {
            if !vsd[i][j] {
                vsd[i][j] = true;
                let mut bct = 0;
                let mut wct = 0;
                let mut stk = vec![(i, j)];
                while let Some((i, j)) = stk.pop() {
                    let c = mas[i][j];
                    if c == '#' {
                        bct += 1;
                    } else {
                        wct += 1;
                    }
                    let mut chk = |i: usize, j: usize| {
                        if !vsd[i][j] && mas[i][j] != c {
                            vsd[i][j] = true;
                            stk.push((i, j))
                        }
                    };
                    if i > 0 {
                        chk(i - 1, j)
                    }
                    if i < h - 1 {
                        chk(i + 1, j)
                    }
                    if j > 0 {
                        chk(i, j - 1)
                    }
                    if j < w - 1 {
                        chk(i, j + 1)
                    }
                }
                cnt += bct * wct;
            }
        }
    }

    format!("{}\n", cnt)
}
fn main() {
    let mut buf = String::new();
    use std::io::{Read, Write};
    std::io::stdin().read_to_string(&mut buf).unwrap();
    std::io::stdout().write_all(solve(&buf).as_bytes()).unwrap();
}
