use std::io::*;
use std::str::FromStr;

fn main() {
    let h: usize = read();
    let w: usize = read();
    let s: Vec<Vec<char>> = (0..h).map(|_| read::<String>().chars().collect()).collect();

    let n = h * w;
    let mut uf = UnionFind::new(n);
    for i in 0..h {
        for j in 0..w {
            if i < h-1 && s[i][j] != s[i+1][j] {
                uf.unite(i*w + j, (i+1)*w + j);
            }
            if j < w-1 && s[i][j] != s[i][j+1] {
                uf.unite(i*w + j, i*w + j+1);
            }
        }
    }

    let mut black = vec![0; n];
    let mut white = vec![0; n];
    for i in 0..h {
        for j in 0..w {
            let root = uf.find(i*w + j);
            if s[i][j] == '#' {
                black[root] += 1;
            } else {
                white[root] += 1;
            }
        }
    }

    let mut used = vec![false; n];
    let mut ans: i64 = 0;
    for i in 0..h {
        for j in 0..w {
            let root = uf.find(i*w + j);
            if used[root] {
                continue;
            }
            ans += black[root] * white[root];
            used[root] = true;
        }
    }

    println!("{}", ans);
}

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

#[derive(Debug)]
struct UnionFind {
    par: Vec<usize>,
    rank: Vec<usize>,
}

impl UnionFind {
    fn new(n: usize) -> UnionFind {
        UnionFind {
            par: (0..n).collect(),
            rank: vec![0; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        let par = self.par[x];
        if par != x {
            self.par[x] = self.find(par);
        }
        self.par[x]
    }

    fn unite(&mut self, x: usize, y: usize) {
        let x = self.find(x);
        let y = self.find(y);
        if x == y {
            return;
        }

        let rx = self.rank[x];
        let ry = self.rank[y];
        if rx < ry {
            self.par[x] = y;
        } else {
            self.par[y] = x;
            if rx == ry {
                self.rank[x] += 1;
            }
        }
    }

    fn same(&mut self, x: usize, y: usize) -> bool {
        self.find(x) == self.find(y)
    }
}

