}

fn dfs(i: usize, j: usize, field: &mut Vec<Vec<char>>, is_checked: &mut Vec<Vec<bool>>) -> u32 {
    let mut stack = std::collections::VecDeque::new();
    stack.push_back((i, j));
    let mut black_count = 0;
    let mut white_count = 0;
    is_checked[i][j] = true;
    while let Some((cur_x, cur_y)) = stack.pop_back() {
        if field[cur_x][cur_y] == '#' {
            black_count += 1;
        } else {
            white_count += 1;
        }
        if cur_x > 0 && field[cur_x - 1][cur_y] != field[cur_x][cur_y] && !is_checked[cur_x - 1][cur_y] {
            is_checked[cur_x - 1][cur_y] = true;
            stack.push_back((cur_x - 1, cur_y));
        }
        if cur_x < field.len() - 1 && field[cur_x + 1][cur_y] != field[cur_x][cur_y] && !is_checked[cur_x + 1][cur_y] {
            is_checked[cur_x + 1][cur_y] = true;
            stack.push_back((cur_x + 1, cur_y));
        }
        if cur_y > 0 && field[cur_x][cur_y - 1] != field[cur_x][cur_y] && !is_checked[cur_x][cur_y - 1] {
            is_checked[cur_x][cur_y - 1] = true;
            stack.push_back((cur_x, cur_y - 1));
        }
        if cur_y < field[0].len() - 1 && field[cur_x][cur_y + 1] != field[cur_x][cur_y] && !is_checked[cur_x][cur_y + 1] {
            is_checked[cur_x][cur_y + 1] = true;
            stack.push_back((cur_x, cur_y + 1));
        }
    }
    // println!("{:?}", (black_count, white_count));
    black_count * white_count
}

fn main() {
    let v = read_vec::<usize>();
    let (h, w) = (v[0], v[1]);

    let mut field = (0..h)
        .map(|_| read::<String>().chars().collect::<Vec<_>>())
        .collect::<Vec<_>>();

    let mut is_checked: Vec<Vec<bool>> = vec![vec![false; w]; h];

    let mut ans = 0;
    for i in 0..field.len() {
        for j in 0..field[0].len() {
            if field[i][j] == '#' && !is_checked[i][j] {
                ans += dfs(i, j, &mut field, &mut is_checked);
            }
        }
    }
    println!("{:?}", ans);
}

fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let h: usize = sc.read();
    let w: usize = sc.read();
    let s: Vec<Vec<char>> = (0..h).map(|_| sc.chars()).collect();
    let mut ut = UnionFind::new(h * w + 10);
    for i in 0..h {
        for j in 0..w {
            for k in 0..4 {
                if let Some((ny, nx)) = utils::try_adj(i, j, k, h, w) {
                    // println!("{} {} {} {}", i, j, ny, nx);
                    if s[ny][nx] != s[i][j] {
                        ut.unite(i * w + j, ny * w + nx);
                    }
                }
            }
        }
    }
    let mut cnts = vec![(0, 0); h * w];
    for i in 0..h {
        for j in 0..w {
            let root = ut.find(i * w + j);
            if s[i][j] == '#' {
                cnts[root].0 += 1;
            } else {
                cnts[root].1 += 1;
            }
        }
    }
    let mut result = 0;
    for i in 0..h {
        for j in 0..w {
            if ut.find(i * w + j) == i * w + j {
                let black = cnts[i * w + j].0;
                let white = cnts[i * w + j].1;
                if black > 0 && white > 0 {
                    // println!("{} {}", black, white);
                    result += black * white;
                    // result += black * (black - 1) / 2;
                }
            } else {
                assert_eq!((0, 0), cnts[i * w + j]);
            }
        }
    }
    println!("{}", result);
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| solve())
        .unwrap()
        .join()
        .unwrap();
}
struct UnionFind {
    par: Vec<usize>,
    rank: Vec<usize>,
}

impl UnionFind {
    fn new(n: usize) -> UnionFind {
        let mut vec = vec![0; n];
        for i in 0..n {
            vec[i] = i;
        }
        UnionFind {
            par: vec,
            rank: vec![0; n],
        }
    }

    fn find(&mut self, x: usize) -> usize {
        if x == self.par[x] {
            x
        } else {
            let par = self.par[x];
            let res = self.find(par);
            self.par[x] = res;
            res
        }
    }

    fn same(&mut self, a: usize, b: usize) -> bool {
        self.find(a) == self.find(b)
    }

    fn unite(&mut self, a: usize, b: usize) {
        let apar = self.find(a);
        let bpar = self.find(b);
        if self.rank[apar] > self.rank[bpar] {
            self.par[bpar] = apar;
        } else {
            self.par[apar] = bpar;
            if self.rank[apar] == self.rank[bpar] {
                self.rank[bpar] += 1;
            }
        }
    }
}

pub mod utils {

    const DYX: [(isize, isize); 8] = [
        (0, 1),   //right
        (1, 0),   //down
        (0, -1),  //left
        (-1, 0),  //top
        (1, 1),   //down right
        (-1, 1),  //top right
        (1, -1),  //down left
        (-1, -1), //top left
    ];

    pub fn try_adj(y: usize, x: usize, dir: usize, h: usize, w: usize) -> Option<(usize, usize)> {
        let ny = y as isize + DYX[dir].0;
        let nx = x as isize + DYX[dir].1;
        if ny >= 0 && nx >= 0 {
            let ny = ny as usize;
            let nx = nx as usize;
            if ny < h && nx < w {
                Some((ny, nx))
            } else {
                None
            }
        } else {
            None
        }
    }
}

