fn dfs(pos: (usize, usize), board: &Table<char>, visited: &mut Table<bool>) -> (usize, usize) {
    if visited[pos] {
        return (0, 0);
    }
    visited[pos] = true;
    let (mut w, mut b) = if board[pos] == '.' { (1, 0) } else { (0, 1) };
    for next in board.adjacent4_indices(pos).unwrap() {
        if board[pos] == board[next] {
            continue;
        }
        let (w1, b1) = dfs(next, board, visited);
        w += w1;
        b += b1;
    }
    (w, b)
}

