    let board = read_char_table();
    let mut visited = table![false; h,w];
    let ans: usize = (0..h).map(|y| {
        (0..w).map(|x| {
            let (w, b) = dfs((y, x), &board, &mut visited);
            w * b
        }).sum::<usize>()
    }).sum();
    echo!(ans);
}

use std::io::*;
use std::str::FromStr;
use std::collections::VecDeque;

fn main() {
    let h: usize = read();
    let w: usize = read();
    let s: Vec<Vec<char>> = (0..h).map(|_| read::<String>().chars().collect()).collect();

    let mut a: Vec<Vec<i64>> = vec![vec![-1; w]; h];
    let d: [(isize, isize); 4] = [(0, 1), (0, -1), (1, 0), (-1, 0)];
    let mut ans = 0;
    for i in 0..h {
        for j in 0..w {
            if s[i][j] == '.' {
                continue;
            }
            if a[i][j] >= 0 {
                ans += a[i][j];
                continue;
            }
            let mut check: Vec<Vec<bool>> = vec![vec![false; w]; h];
            let mut que: VecDeque<(usize, usize)> = VecDeque::new();
            let mut same: Vec<(usize, usize)> = Vec::new();
            let mut cnt: i64 = 0;
            check[i][j] = true;
            que.push_back((i, j));
            while let Some((y, x)) = que.pop_front() {
                let c = s[y][x];
                if c == '.' {
                    cnt += 1;
                } else {
                    same.push((y, x));
                }
                for k in 0..4 {
                    let (dx, dy) = d[k];
                    let nx: isize = x as isize + dx;
                    let ny: isize = y as isize + dy;
                    if 0 > nx && 0 > ny {
                        continue;
                    }
                    let nx = nx as usize;
                    let ny = ny as usize;
                    if nx < w && ny < h && c != s[ny][nx] && !check[ny][nx] {
                        check[ny][nx] = true;
                        que.push_back((ny, nx));
                    }
                }
            }
            a[i][j] = cnt;
            for i in &same {
                let (y, x) = *i;
                a[y][x] = cnt;
            }
            ans += cnt;
        }
    }
    println!("{}", ans);
}

