fn main() {
    proconio::input! {
        h: usize,
        w: usize,
        ss: [proconio::marker::Chars; h],
    }
    let mut group = vec![vec![None; w]; h];
    let mut deque = std::collections::VecDeque::new();
    for i_origin in 0..h {
        for j_origin in 0..w {
            if ss[i_origin][j_origin] == '.' || group[i_origin][j_origin].is_some() {
                continue;
            }
            deque.clear();
            deque.push_back((i_origin, j_origin));
            while let Some((i, j)) = deque.pop_front() {
                group[i][j] = Some((i_origin, j_origin));
                let nexts = [
                    (i.wrapping_sub(1), j),
                    (i, j.wrapping_sub(1)),
                    (i + 1, j),
                    (i, j + 1),
                ];
                for &(i_next, j_next) in &nexts {
                    if i_next < h
                        && j_next < w
                        && group[i_next][j_next].is_none()
                        && ss[i][j] != ss[i_next][j_next]
                    {
                        deque.push_back((i_next, j_next));
                    }
                }
            }
        }
    }
    let mut nums = std::collections::HashMap::new();
    for (i, group) in group.iter().enumerate() {
        for (j, group) in group.iter().enumerate() {
            if let Some(group) = group {
                let e = nums.entry(group).or_insert([0, 0]);
                let idx = if ss[i][j] == '#' { 0 } else { 1 };
                (*e)[idx] += 1;
            }
        }
    }
