const C: [char; 2] = ['.', '#'];

fn dfs(x: usize, y: usize, s: &Vec<Vec<char>>, memo: &mut Vec<Vec<Option<bool>>>, c: usize) -> (u64,u64) {
    if memo[x][y].is_some() {
        return (0,0)
    }
    if s[x-1][y-1] == C[c] {
        let mut ans = [0, 0];
        ans[c] += 1;
        memo[x][y] = Some(true);
        let (w,b) = dfs(x-1, y, s, memo, (c+1)%2);
        ans[0] += w;
        ans[1] += b;
        let (w,b)= dfs(x+1, y, s, memo, (c+1)%2);
        ans[0] += w;
        ans[1] += b;
        let (w,b)= dfs(x, y-1, s, memo, (c+1)%2);
        ans[0] += w;
        ans[1] += b;
        let (w,b)= dfs(x, y+1, s, memo, (c+1)%2);
        ans[0] += w;
        ans[1] += b;
        (ans[0], ans[1])
    } else {
        memo[x][y] = Some(false);
        (0,0)
    }
}

fn main() {
    let line: Vec<usize> = read_line().split_whitespace().map(|s| s.parse().unwrap()).collect();
    let h = line[0];
    let w = line[1];
    let mut s = Vec::with_capacity(h);
    for _ in 0..h {
        let line: Vec<char> = read_line().trim().chars().collect();
        s.push(line);
    }
    let mut memo = vec![vec![None; w+2]; h+2];
    for i in 0..h+2 {
        memo[i][0] = Some(false);
        memo[i][w+1] = Some(false);
    }
    for i in 0..w+2 {
        memo[0][i] = Some(false);
        memo[h+1][i] = Some(false);
    }

    let mut ans = 0;
    for i in 0..h {
        for j in 0..w {
            let (tmp1, tmp2) = dfs(i+1, j+1, &s, &mut memo, (i+j)%2);       
            ans += tmp1 * tmp2;
        }
    }
    let mut memo = vec![vec![None; w+2]; h+2];
    for i in 0..h+2 {
        memo[i][0] = Some(false);
        memo[i][w+1] = Some(false);
    }
    for i in 0..w+2 {
        memo[0][i] = Some(false);
        memo[h+1][i] = Some(false);
    }
    for i in 0..h {
        for j in 0..w {
            let (tmp1, tmp2) = dfs(i+1, j+1, &s, &mut memo, (i+j+1)%2);       
            ans += tmp1 * tmp2;
        }
    }
    println!("{}", ans);
}

