    ($t:ty;;$n:expr) => {
        (0..$n).map(|_| scan!($t;;)).collect::<Vec<_>>()
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
                    scan!($t)
        ).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
                    scan!($($t),*)
        ).collect::<Vec<_>>()
    };
}

fn dfs(graph: &[Vec<char>], colors: &mut [Vec<i64>], i: usize, j: usize, color: i64, bw: usize) {
    colors[i as usize][j as usize] = color;

    for (k, l) in &[(1, 0), (-1, 0), (0, -1), (0, 1)] {
        let w = i as i64 + k;
        if !(0 <= w && w < graph.len() as i64) {
            continue;
        }
        let v = j as i64 + l;
        if !(0 <= v && v < graph[0].len() as i64) {
            continue;
        }

        let (x, y) = (w as usize, v as usize);
        if colors[x][y] == -1 {
            if bw == 0 {
                if graph[x][y] == '.' {
                    dfs(graph, colors, x, y, color, 1)
                }
            } else {
                if graph[x][y] == '#' {
                    dfs(graph, colors, x, y, color, 0)
                }
            }
        }
    }
}

fn main() {
    let (h, w) = scan!(usize, usize);
    let vs = scan!(String;h);

    let graph: Vec<_> = vs.iter().map(|v| v.chars().collect::<Vec<_>>()).collect();
    let mut colors = vec![vec![-1; w]; h];

    let mut color = 0i64;
    for i in 0..h {
        for j in 0..w {
            if colors[i][j] == -1 && graph[i][j] == '#' {
                dfs(&graph, &mut colors, i, j, color, 0);
                color += 1;
            }
        }
    }

    let mut whites = vec![0; color as usize + 1];
    let mut blacks = vec![0; color as usize + 1];
    for (i, l) in colors.iter().enumerate() {
        for (j, &c) in l.iter().enumerate() {
            if c == -1 {
                continue;
            }
            if graph[i][j] == '.' {
                whites[c as usize] += 1;
            } else {
                blacks[c as usize] += 1;
            }
        }
    }

    println!(
        "{}",
        whites
            .iter()
            .zip(blacks.iter())
            .map(|(w, b)| w * b)
            .sum::<i32>()
    )
}

use std::io::*;
use std::str::FromStr;
use std::collections::VecDeque;

fn main() {
    let h: usize = read();
    let w: usize = read();
    let s: Vec<Vec<char>> = (0..h).map(|_| read::<String>().chars().collect()).collect();

    let mut a: Vec<Vec<i64>> = vec![vec![0; w]; h];
    let mut ans = 0;
    for i in 0..h {
        for j in 0..w {
            if s[i][j] == '.' {
                continue;
            }
            if a[i][j] > 0 {
                ans += a[i][j];
                continue;
            }
            let mut check: Vec<Vec<bool>> = vec![vec![false; w]; h];
            let mut que: VecDeque<(usize, usize)> = VecDeque::new();
            let mut same: Vec<(usize, usize)> = Vec::new();
            let mut cnt: i64 = 0;
            que.push_back((i, j));
            while let Some((y, x)) = que.pop_front() {
                if check[y][x] {
                    continue;
                }
                check[y][x] = true;
                let c = s[y][x];
                if c == '.' {
                    cnt += 1;
                } else {
                    same.push((y, x));
                }
                if x > 0 && c != s[y][x-1] {
                    que.push_back((y, x-1));
                }
                if x < w-1 && c != s[y][x+1] {
                    que.push_back((y, x+1));
                }
                if y > 0 && c != s[y-1][x] {
                    que.push_back((y-1, x));
                }
                if y < h-1 && c != s[y+1][x] {
                    que.push_back((y+1, x));
                }
            }
            a[i][j] = cnt;
            for i in &same {
                let (y, x) = *i;
                a[y][x] = cnt;
            }
            ans += cnt;
        }
    }
    println!("{}", ans);
}

