macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (h, w) = parse!(it, 2);
    let g: Vec<Vec<bool>> = (0..h)
        .map(|_| it.next().unwrap().chars().map(|c| c == '.').collect())
        .collect();
    let mut seen = vec![vec![false; w]; h];
    let mut ret = 0;
    let di = vec![1, -1, 0, 0];
    let dj = vec![0, 0, 1, -1];
    let around = |i: usize, j: usize| {
        let mut ret = vec![];
        for k in 0..4 {
            let ni = (i as isize) + di[k];
            let nj = (j as isize) + dj[k];
            if ni >= 0 && ni < (h as isize) && nj >= 0 && nj < (w as isize) {
                let ni = ni as usize;
                let nj = nj as usize;
                if g[i][j] != g[ni][nj] {
                    ret.push((ni, nj))
                }
            }
        }
        ret
    };
    for i in 0..h {
        for j in 0..w {
            if seen[i][j] {
                continue;
            }
            let mut q = std::collections::VecDeque::<(usize, usize)>::new();
            q.push_back((i, j));
            seen[i][j] = true;
            let mut ca = 0;
            let mut cb = 0;
            while let Some((i, j)) = q.pop_front() {
                if g[i][j] {
                    ca += 1
                } else {
                    cb += 1
                }
                for (ni, nj) in around(i, j) {
                    if !seen[ni][nj] {
                        seen[ni][nj] = true;
                        q.push_back((ni, nj))
                    }
                }
            }
            ret += ca * cb;
        }
    }
    println!("{}", ret);
}

