fn get_color(board:&Vec<Vec<bool>>) -> i64{
    let mut result = vec![vec![0;board[0].len()];board.len()];
    let mut ans = 0;

    for i in 0..board.len(){
        for j in 0..board[0].len(){
            let c = i*board[0].len() + j+1;
            let (b,w) = fill(i,j,&mut result,board,c as i64,board[i][j]);
            let pattern = b*w;
            ans += pattern;
        }
    }

    ans
}

fn fill(x:usize,y:usize,result:&mut Vec<Vec<i64>>,board:&Vec<Vec<bool>>,c:i64,wait:bool)->(i64,i64){
    let mut b = 0;
    let mut w = 0;

    if result[x][y] == 0{
        if board[x][y] != wait{
            return (0,0);
        }

        result[x][y] = c;

        for i in 0..4{
            let dx = DXS[i];
            let dy = DYS[i];
            let xx = x as i64 + dx;
            let yy = y as i64 + dy;

            if xx < 0 || xx >= board.len() as i64 || yy < 0 || yy >= board[0].len() as i64{
                continue;
            }
            let (bb,ww) = fill(xx as usize,yy as usize,result,board,c,!wait);

            b += bb;
            w += ww;
        }

        if board[x][y]{
            (b+1,w)
        }else{
            (b,w+1)
        }
    }else{
        (0,0)
    }
}

