fn solve(s: &str) -> String {
    let mut sc = Scanner::from_str(s);

    let h: usize = sc.read();
    let w: usize = sc.read();
    let g: Vec<Vec<_>> = (0..h).map(|_| sc.get().chars().collect()).collect();

    let mut seen = vec![vec![false; w]; h];
    let mut ret: usize = 0;
    for i in 0..h {
        for j in 0..w {
            if !seen[i][j] {
                seen[i][j] = true;
                let mut sa = 0;
                let mut sb = 0;
                let mut q = vec![(i, j)];
                while let Some((i, j)) = q.pop() {
                    let c = g[i][j];
                    if c == '#' {
                        sa += 1;
                    } else {
                        sb += 1;
                    }
                    let mut chk = |i: usize, j: usize| {
                        if !seen[i][j] && g[i][j] != c {
                            seen[i][j] = true;
                            q.push((i, j))
                        }
                    };
                    if i > 0 {
                        chk(i - 1, j)
                    }
                    if i < h - 1 {
                        chk(i + 1, j)
                    }
                    if j > 0 {
                        chk(i, j - 1)
                    }
                    if j < w - 1 {
                        chk(i, j + 1)
                    }
                }
                ret += sa * sb;
            }
        }
    }
    format!("{}\n", ret)
}

