        for i in 0..info[0] {
            handle.read_line(&mut buf).unwrap();
            let t = buf.trim().chars().collect();
            buf.clear();
            tmp.push(t);
        }
        tmp
    };

    let mut memo: Vec<Vec<Option<usize>>> = vec![vec![None; info[1]]; info[0]];
    let mut count = 0;
    search(&info, &board, &mut memo, &mut count);
    println!("{}", count);
}
fn search(
    info: &Vec<usize>,
    board: &Vec<Vec<char>>,
    group_memo: &mut Vec<Vec<Option<usize>>>,
    count: &mut usize,
) {
    let mut group_num = 0;
    for i in 0..info[0] {
        for j in 0..info[1] {
            let mut b = 0;
            let mut w = 0;
            let (mut b, mut w) = dp(
                i, j, group_num, board, group_memo, info, &mut b, &mut w,
            );
            if b != 0 || w != 0 {
                if board[i][j] == '#' {
                    b += 1;
                } else {
                    w += 1;
                }
            }
            *count += b * w;
            group_num += 1;
        }
    }
}
fn dp(
    i: usize,
    j: usize,
    group_num: usize,
    board: &Vec<Vec<char>>,
    group_memo: &mut Vec<Vec<Option<usize>>>,
    info: &Vec<usize>,
    black: &mut usize,
    white:  &mut usize,
) -> (usize, usize) {
    if (i < info[0] - 1) && board[i + 1][j] != board[i][j] {
        match group_memo[i + 1][j] {
            Some(num) => {}
            None => {
                group_memo[i][j] = Some(group_num);
                group_memo[i + 1][j] = Some(group_num);
                dp(i + 1, j, group_num, board, group_memo, info, black, white);
                if board[i + 1][j] == '#' {
                    *black += 1;
                } else {
                    *white += 1;
                }
            }
        }
    }
    if (j < info[1] - 1) && board[i][j + 1] != board[i][j] {
        match group_memo[i][j + 1] {
            Some(num) => {}
            None => {
                group_memo[i][j] = Some(group_num);
                group_memo[i][j + 1] = Some(group_num);
                dp(i, j + 1, group_num, board, group_memo, info, black, white);
                if board[i][j + 1] == '#' {
                    *black += 1;
                } else {
                    *white += 1;
                }
            }
        }
    }
    if i > 0 && board[i - 1][j] != board[i][j] {
        match group_memo[i - 1][j] {
            Some(num) => {}
            None => {
                group_memo[i][j] = Some(group_num);
                group_memo[i - 1][j] = Some(group_num);
                dp(i - 1, j, group_num, board, group_memo, info, black, white);
                if board[i - 1][j] == '#' {
                    *black += 1;
                } else {
                    *white += 1;
                }
            }
        }
    }
    if j > 0 && board[i][j - 1] != board[i][j] {
        match group_memo[i][j - 1] {
            Some(num) => {}
            None => {
                group_memo[i][j] = Some(group_num);
                group_memo[i][j - 1] = Some(group_num);
                dp(i, j - 1, group_num, board, group_memo, info, black, white);
                if board[i][j - 1] == '#' {
                    *black += 1;
                } else {
                    *white += 1;
                }
            }
        }
    }
    return (*black, *white);
}

#[allow(unused_macros)]
macro_rules! scan {
    () => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().to_string()
        }
    };
    (;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().split_whitespace().map(|s| s.to_string()).collect::<Vec<String>>()
        }
    };
    (;;$n:expr) => {
        {
            (0..$n).map(|_| scan!()).collect::<Vec<_>>()
        }
    };
    ($t:ty) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.trim().parse::<$t>().unwrap()
        }
    };
    ($($t:ty),*) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            let mut iter = line.split_whitespace();
            (
                $(iter.next().unwrap().parse::<$t>().unwrap(),)*
            )
        }
    };
    ($t:ty;;) => {
        {
            let mut line: String = String::new();
            std::io::stdin().read_line(&mut line).unwrap();
            line.split_whitespace()
                .map(|t| t.parse::<$t>().unwrap())
                .collect::<Vec<_>>()
        }
    };
    ($t:ty;;$n:expr) => {
        (0..$n).map(|_| scan!($t;;)).collect::<Vec<_>>()
    };
    ($t:ty; $n:expr) => {
        (0..$n).map(|_|
                    scan!($t)
        ).collect::<Vec<_>>()
    };
    ($($t:ty),*; $n:expr) => {
        (0..$n).map(|_|
                    scan!($($t),*)
        ).collect::<Vec<_>>()
    };
}

fn dfs(graph: &[Vec<char>], colors: &mut [Vec<i64>], i: usize, j: usize, color: i64, bw: usize) {
    colors[i as usize][j as usize] = color;

    for &(k, l) in &[(1, 0), (-1, 0), (0, -1), (0, 1)] {
        let w = i as i64 + k;
        if !(0 <= w && w < graph.len() as i64) {
            continue;
        }
        let v = j as i64 + l;
        if !(0 <= v && v < graph[0].len() as i64) {
            continue;
        }

        let (x, y) = (w as usize, v as usize);
        if colors[x][y] == -1 {
            if bw == 0 {
                if graph[x][y] == '.' {
                    dfs(graph, colors, x, y, color, 1)
                }
            } else {
                if graph[x][y] == '#' {
                    dfs(graph, colors, x, y, color, 0)
                }
            }
        }
    }
}

fn main() {
    let (h, w) = scan!(usize, usize);
    let vs = scan!(String;h);

    let graph: Vec<_> = vs.iter().map(|v| v.chars().collect::<Vec<_>>()).collect();
    let mut colors = vec![vec![-1; w]; h];

    let mut color = 0i64;
    for i in 0..h {
        for j in 0..w {
            if colors[i][j] == -1 {
                dfs(
                    &graph,
                    &mut colors,
                    i,
                    j,
                    color,
                    if graph[i][j] == '#' { 0 } else { 1 },
                );
                color += 1;
            }
        }
    }

    let mut whites = vec![0; color as usize + 1];
    let mut blacks = vec![0; color as usize + 1];
    for (i, l) in colors.iter().enumerate() {
        for (j, &c) in l.iter().enumerate() {
            if c == -1 {
                continue;
            }
            if graph[i][j] == '.' {
                whites[c as usize] += 1;
            } else {
                blacks[c as usize] += 1;
            }
        }
    }

    println!(
        "{}",
        whites
            .iter()
            .zip(blacks.iter())
            .map(|(w, b)| w * b)
            .sum::<i32>()
    )
}

