    let g: Vec<Vec<bool>> = (0..h)
        .map(|_| it.next().unwrap().chars().map(|c| c == '.').collect())
        .collect();
    let mut seen = std::collections::HashSet::<(usize, usize)>::new();
    let mut ret = 0;
    for i in 0..h {
        for j in 0..w {
            if seen.contains(&(i, j)) {
                continue;
            }
            let mut q = std::collections::VecDeque::<(usize, usize)>::new();
            q.push_back((i, j));
            seen.insert((i, j));
            let mut ca = 0;
            let mut cb = 0;
