                if g[i][j] {
                    ca += 1
                } else {
                    cb += 1
                }
                let mut nexts = vec![];
                if i > 0 {
                    nexts.push((i - 1, j));
                }
                if j > 0 {
                    nexts.push((i, j - 1));
                }
                if i < h - 1 {
                    nexts.push((i + 1, j));
                }
                if j < w - 1 {
                    nexts.push((i, j + 1));
                }
                for (ni, nj) in nexts {
                    if !seen.contains(&(ni, nj)) && g[ni][nj] != g[i][j] {
                        seen.insert((ni, nj));
                        q.push_back((ni, nj))
                    }
                }
            }
            ret += ca * cb;
