struct Dfs<'a> {
    H: usize,
    W: usize,
    done: Vec<Vec<bool>>,
    board: &'a Vec<Vec<char>>,
}

impl<'a> Dfs<'a> {
    fn run(mut self) {
        let mut s = 0_i64;

        for y in 0..self.H {
            for x in 0..self.W {
                if self.done[y][x] {
                    continue;
                }

                let mut whites = 0_i64;
                let mut blacks = 0;

                self.dfs(y, x, &mut whites, &mut blacks);

                debug!((y, x, whites, blacks));

                s += whites * blacks;
            }
        }

        println!("{}", s)
    }

    fn dfs(&mut self, y: usize, x: usize, whites: &mut i64, blacks: &mut i64) {
        if self.done[y][x] {
            return;
        }
        self.done[y][x] = true;

        if self.board[y][x] == '.' {
            *whites += 1;
        } else {
            *blacks += 1;
        }

        if y >= 1 {
            if self.board[y][x] != self.board[y - 1][x] {
                self.dfs(y - 1, x, whites, blacks);
            }
        }
        if x >= 1 {
            if self.board[y][x] != self.board[y][x - 1] {
                self.dfs(y, x - 1, whites, blacks);
            }
        }
        if y + 1 < self.H {
            if self.board[y][x] != self.board[y + 1][x] {
                self.dfs(y + 1, x, whites, blacks);
            }
        }
        if x + 1 < self.W {
            if self.board[y][x] != self.board[y][x + 1] {
                self.dfs(y, x + 1, whites, blacks);
            }
        }
    }
}

fn main() {
    let (H, W) = read!(usize, usize);
    let board = read![String; H]
        .into_iter()
        .map(|s| s.chars().collect::<Vec<_>>())
        .collect::<Vec<_>>();

    Dfs {
        H: H,
        W: W,
        board: &board,
        done: vec![vec![false; W]; H],
    }
    .run()
}

fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let h: usize = sc.read();
    let w: usize = sc.read();
    let s: Vec<Vec<char>> = (0..h).map(|_| sc.chars()).collect();
    let mut ut = UnionFind::new(h * w + 10);
    for i in 0..h {
        for j in 0..w {
            if i + 1 < h && s[i][j] != s[i + 1][j] {
                ut.unite(i * w + j, (i + 1) * w + j);
            }
            if j + 1 < w && s[i][j] != s[i][j + 1] {
                ut.unite(i * w + j, i * w + j + 1);
            }
        }
    }
    let mut cnts = vec![(0, 0); h * w];
    for i in 0..h {
