macro_rules! parse {
    ($it: ident) => {
        $it.next().unwrap().parse().unwrap()
    };
    ($it: ident,2) => {
        (parse!($it), parse!($it))
    };
    ($it: ident,3) => {
        (parse!($it), parse!($it), parse!($it))
    };
    ($it: ident,4) => {
        (parse!($it), parse!($it), parse!($it), parse!($it))
    };
    ($it: ident, $n: expr) => {
        (&mut $it).take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(s: &str) {
    let mut it = s.split_whitespace();
    let (h, w): (usize, usize) = parse!(it, 2);
    let mut g: Vec<Vec<bool>> = vec![];
    for _ in 0..h {
        let s = it.next().unwrap();
        g.push(s.chars().map(|c| c == '#').collect());
    }
    let mut seen = vec![vec![false; w]; h];
    let mut ret = 0;
    for i in 0..h {
        for j in 0..w {
            if seen[i][j] {
                continue;
            }
            let mut q = vec![(i, j)];
            seen[i][j] = true;
            let mut sa = 0;
            let mut sb = 0;
            while let Some((i, j)) = q.pop() {
                if g[i][j] {
                    sa += 1;
                } else {
                    sb += 1;
                }
                let mut nexts = vec![];
                if i > 0 {
                    nexts.push((i - 1, j));
                }
                if j > 0 {
                    nexts.push((i, j - 1));
                }
                if i < h - 1 {
                    nexts.push((i + 1, j));
                }
                if j < w - 1 {
                    nexts.push((i, j + 1));
                }
                for (ni, nj) in nexts {
                    if !seen[ni][nj] && g[i][j] != g[ni][nj] {
                        seen[ni][nj] = true;
                        q.push((ni, nj));
                    }
                }
            }
            ret += sa * sb;
        }
    }
    println!("{}", ret);
}

